window.BIBLE_DATA = {"version":"2026-10-07","books":[{"id":"GEN","name":"ഉത്പത്തി","chapters":{"1":[{"v":1,"t":"ആദിയിൽ ദൈവം ആകാശവും ഭൂമിയും സൃഷ്ടിച്ചു.","p":1},{"v":2,"t":"ഭൂമി രൂപരഹിതവും ശൂന്യവുമായിരുന്നു. ആഴത്തിനു മുകളിൽ അന്ധകാരം വ്യാപിച്ചിരുന്നു. ദൈവത്തിന്റെ ചൈതന്യം വെള്ളത്തിനു മീതെ ചലിച്ചുകൊണ്ടിരുന്നു."},{"v":3,"t":"ദൈവം അരുളിച്ചെയ്തു: വെളിച്ചം ഉണ്ടാകട്ടെ. വെളിച്ചം ഉണ്ടായി.","p":1},{"v":4,"t":"വെളിച്ചം നല്ലതെന്നു ദൈവം കണ്ടു. വെളിച്ചവും ഇരുളും തമ്മിൽ ദൈവം വേർതിരിച്ചു."},{"v":5,"t":"വെളിച്ചത്തെ പകലെന്നും ഇരുളിനെ രാത്രിയെന്നും ദൈവം വിളിച്ചു. പ്രദോഷമായി, പ്രഭാതമായി - ഒന്നാം ദിവസം."},{"v":6,"t":"ദൈവം അരുളിച്ചെയ്തു: ജലമധ്യത്തിൽ ഒരു വിതാനം ഉണ്ടാകട്ടെ; അത് ജലത്തെ ജലത്തിൽനിന്നു വേർതിരിക്കട്ടെ.","p":1},{"v":7,"t":"ദൈവം വിതാനമുണ്ടാക്കുകയും വിതാനത്തിനു താഴെയുള്ള ജലം വിതാനത്തിനു മുകളിലുള്ള ജലത്തിൽനിന്നു വേർതിരിക്കുകയും ചെയ്തു."},{"v":8,"t":"അപ്രകാരം സംഭവിച്ചു. വിതാനത്തെ ദൈവം ആകാശമെന്നു വിളിച്ചു. പ്രദോഷമായി, പ്രഭാതമായി - രണ്ടാം ദിവസം."},{"v":9,"t":"ദൈവം അരുളിച്ചെയ്തു: ആകാശത്തിനു കീഴെയുള്ള ജലമെല്ലാം ഒരിടത്തു കൂടട്ടെ; ഉണങ്ങിയ കര പ്രത്യക്ഷപ്പെടട്ടെ. അപ്രകാരം സംഭവിച്ചു.","p":1},{"v":10,"t":"ഉണങ്ങിയ കരയെ ഭൂമിയെന്നും ഒന്നിച്ചുകൂടിയ ജലത്തെ കടലെന്നും ദൈവം വിളിച്ചു. അതു നല്ലതെന്ന് ദൈവം കണ്ടു."},{"v":11,"t":"ദൈവം വീണ്ടും അരുളിച്ചെയ്തു: പുല്ലും വിത്തുള്ള സസ്യങ്ങളും വിത്തോടുകൂടിയ അത്തനിനം ഫലം ഉത്പാദിപ്പിക്കുന്ന ഫലവൃക്ഷങ്ങളും ഭൂമി മുളപ്പിക്കട്ടെ. അപ്രകാരം സംഭവിച്ചു.","p":1},{"v":12,"t":"പുല്ലും അത്തനിനം വിത്തു മുളപ്പിക്കുന്ന സസ്യങ്ങളും അത്തനിനം വിത്തുള്ളവയും ഫലം ഉത്പാദിപ്പിക്കുന്ന വൃക്ഷങ്ങളും ഭൂമി പുറപ്പെടുവിച്ചു. അവ നല്ലതെന്ന് ദൈവം കണ്ടു."},{"v":13,"t":"പ്രദോഷമായി, പ്രഭാതമായി - മൂന്നാം ദിവസം."},{"v":14,"t":"ദൈവം അരുളിച്ചെയ്തു: പകലും രാത്രിയും തമ്മിൽ വേർതിരിക്കാൻ ആകാശവിതാനത്തിൽ ജ്യോതിസ്സുകൾ ഉണ്ടാകട്ടെ. അവ കാലങ്ങളും ദിനങ്ങളും വർഷങ്ങളും കുറിക്കുന്ന അടയാളങ്ങളായിരിക്കട്ടെ.","p":1},{"v":15,"t":"ഭൂമിയിൽ പ്രകാശം ചൊരിയാൻ അവ ആകാശവിതാനത്തിൽ ആയിരിക്കട്ടെ. അപ്രകാരം സംഭവിച്ചു."},{"v":16,"t":"ദൈവം രണ്ട് മഹാജ്യോതിസ്സുകളെ ഉണ്ടാക്കി. പകലിനു വലിയ ജ്യോതിസ്സ്, രാത്രിക്ക് ചെറിയ ജ്യോതിസ്സ്; കൂടാതെ, നക്ഷത്രങ്ങളും."},{"v":17,"t":"ദൈവം അവയെ ആകാശവിതാനത്തിൽ സ്ഥാപിച്ചു; അത് ഭൂമിയിന്മേൽ പ്രകാശം ചൊരിയാനും"},{"v":18,"t":"ദിനരാത്രങ്ങളെ ഭരിക്കാനും വെളിച്ചവും അന്ധകാരവും തമ്മിൽ വേർതിരിക്കാനുമായിരുന്നു. അതു നല്ലതെന്ന് ദൈവം കണ്ടു."},{"v":19,"t":"പ്രദോഷമായി, പ്രഭാതമായി - നാലാം ദിവസം."},{"v":20,"t":"ദൈവം അരുളിച്ചെയ്തു: ജലം ജീവനുള്ളവയെക്കൊണ്ടു തിങ്ങിനിറയട്ടെ; പക്ഷികൾ ഭൂമിക്കുമീതെ ആകാശവിതാനത്തു പറക്കട്ടെ.","p":1},{"v":21,"t":"അങ്ങനെ ദൈവം ഭീമാകാരങ്ങളായ ജലജീവികളെയും ജലത്തിൽ പറ്റിച്ചേർന്നു നീന്തുന്ന വിവിധയിനം ജീവികളെയും സൃഷ്ടിച്ചു. അത്തനിനം പക്ഷികളെയും. അവ നല്ലതെന്ന് ദൈവം കണ്ടു."},{"v":22,"t":"ദൈവം അവയെ ഇപ്രകാരം അനുഗ്രഹിച്ചു: പെറ്റുപെരുകി സമുദ്രജലത്തിൽ നിറയുവിൻ; പക്ഷികൾ ഭൂമിയിൽ വർധിക്കട്ടെ."},{"v":23,"t":"പ്രദോഷമായി, പ്രഭാതമായി - അഞ്ചാം ദിവസം."},{"v":24,"t":"ദൈവം അരുളിച്ചെയ്തു: ജീവജാലങ്ങളെ, അതായത് കന്നുകാലികൾ, ഇഴജന്തുക്കൾ, കാട്ടുജീവികൾ എന്നിവയെ ഇനമനുസരിച്ച് ഭൂമി പുറപ്പെടുവിക്കട്ടെ. അപ്രകാരം സംഭവിച്ചു.","p":1},{"v":25,"t":"ദൈവം ഇനമനുസരിച്ച് ഭൂമിയിലെ കാട്ടുജീവികളെയും കന്നുകാലികളെയും മണ്ണിലെ സർവ ഇഴജന്തുക്കളെയും ഉരുവാക്കി. അവ നല്ലതെന്ന് ദൈവം കണ്ടു."},{"v":26,"t":"അനന്തരം, ദൈവം അരുളിച്ചെയ്തു: നമുക്ക് നമ്മുടെ ഛായയിലും സാദൃശ്യത്തിലും മനുഷ്യനെ ഉരുവാക്കാം. കടലിലെ മത്സ്യങ്ങളുടെയും ആകാശത്തിലെ പറവകളുടെയും കന്നുകാലികളുടെയും ഭൂമി മുഴുവന്റെയും ഭൂമിയിൽ ഇഴയുന്ന എല്ലാ ഇഴജന്തുക്കളുടെയുംമേൽ അവർക്ക് ആധിപത്യം ഉണ്ടാകട്ടെ.","p":1},{"v":27,"t":"അങ്ങനെ, ദൈവം തന്റെ ഛായയിൽ മനുഷ്യനെ സൃഷ്ടിച്ചു. ദൈവത്തിന്റെ ഛായയിൽ അവനെ സൃഷ്ടിച്ചു; ആണും പെണ്ണുമായി അവരെ സൃഷ്ടിച്ചു."},{"v":28,"t":"ദൈവം അവരെ അനുഗ്രഹിച്ചു.അവരോട് ദൈവം അരുൾ ചെയ്തു.പെറ്റുപെരുകിഭൂ"},{"v":29,"t":"ദൈവം വീണ്ടുംഅരുളിച്ചെയ്തു: ഇതാ, ഭൂമിയിലെങ്ങും വിത്ത് ഉല്പാദിപ്പിക്കുന്ന എല്ലാ സസ്യങ്ങളും എല്ലാ വൃക്ഷങ്ങളും ഞാൻ നിങ്ങൾക്കു നൽകുന്നു; അവ നിങ്ങൾക്കു ആഹാരമായിരിക്കും. ഭൂമിയിലെ എല്ലാ വന്യജീവികൾക്കും ആകാശത്തിലെ എല്ലാ പക്ഷികൾക്കും ഭൂമിയിൽ ഇഴയുന്നവയും ജീവശ്വാസമുള്ളവ സകലത്തിനും എല്ലാ ഹരിതസസ്യങ്ങളും ആഹാരമായിരിക്കും; അപ്രകാരം സംഭവിച്ചു. താൻ സൃഷ്ടിച്ചതെല്ലാം ദൈവം കണ്ടു: ഇതാ, വളരെ നല്ലത്! പ്രഭാതമായി, പ്രദോഷമായി - ആറാം ദിവസം."}],"2":[{"v":1,"t":"അങ്ങനെ ആകാശവും ഭൂമിയും അവയുടെ സമസ്ത വ്യൂഹവും പൂർത്തീകരിക്കപ്പെട്ടു.","p":1},{"v":2,"t":"താൻ ചെയ്തുകൊണ്ടിരുന്ന പ്രവൃത്തി ഏഴാം ദിവസം ദൈവം പൂർത്തിയാക്കി. താൻ ചെയ്തിരുന്ന സകല പ്രവൃത്തിയിൽനിന്നും ഏഴാം ദിവസം ദൈവം വിശ്രമിച്ചു."},{"v":3,"t":"ഏഴാം ദിവസത്തെ അനുഗ്രഹിച്ച് ദൈവം അതിനെ വിശുദ്ധീകരിച്ചു. എന്തെന്നാൽ, അന്നു താൻ ചെയ്തുകൊണ്ടിരുന്ന സകല സൃഷ്ടികർമ്മത്തിൽനിന്നും ദൈവം വിശ്രമിച്ചു."},{"v":4,"t":"ആകാശവും ഭൂമിയും സൃഷ്ടിക്കപ്പെട്ടപ്പോഴത്തെ അവയുടെ ഉല്പത്തിക്രമം ഇതായിരുന്നു."},{"h":"ഏദൻതോട്ടം"},{"v":4,"t":"ദൈവമായ കർത്താവ് ഭൂമിയും ആകാശവും സൃഷ്ടിച്ച നാളിൽ","p":1},{"v":5,"t":"ഭൂമിയിൽ കാട്ടുചെടികളൊന്നും അതുവരെ ഉണ്ടായിരുന്നില്ല. വയൽപ്പുല്ലുകളൊന്നും അതുവരെ മുളച്ചിരുന്നില്ല. കാരണം, ദൈവമായ കർത്താവ് ഭൂമിയിൽ മഴ പെയ്യിച്ചിരുന്നില്ല. മണ്ണിൽ അദ്ധ്വാനിക്കാൻ മനുഷ്യനും ഉണ്ടായിരുന്നില്ല."},{"v":6,"t":"എന്നാൽ, ഭൂമിയിൽനിന്ന് കോടമഞ്ഞ് ഉയർന്ന് ഭൂതലമെല്ലാം നനച്ചു."},{"v":7,"t":"ദൈവമായ കർത്താവ് പൂഴി മണ്ണുകൊണ്ട് മനുഷ്യനെ മെനയുകയും ജീവന്റെ ശ്വാസം അവന്റെ നാസാരന്ധ്രങ്ങളിലേക്ക് ഊതുകയും ചെയ്തു. അങ്ങനെ മനുഷ്യൻ ജീവനുള്ളവനായിത്തീർന്നു."},{"v":8,"t":"കിഴക്ക് ഏദനിൽ ദൈവമായ കർത്താവ് ഒരു തോട്ടം നട്ടുപിടിപ്പിക്കുകയും താൻ മെനഞ്ഞ മനുഷ്യനെ അവിടെ നിയോഗിക്കുകയും ചെയ്തു.","p":1},{"v":9,"t":"കാഴ്ചയ്ക്കു മനോഹരവും ഭക്ഷിക്കാൻ ഉപയുക്തവുമായ എല്ലാ വൃക്ഷങ്ങളും ദൈവമായ കർത്താവ് മണ്ണിൽനിന്നു മുളപ്പിച്ചു. തോട്ടത്തിന്റെ നടുവിൽ ജീവന്റെ വൃക്ഷവും നന്മതിന്മകളെക്കുറിച്ചുള്ള അറിവിന്റെ വൃക്ഷവും.","p":1},{"v":10,"t":"തോട്ടം നനയ്ക്കാൻ ഏദനിൽനിന്ന് ഒരു നദി പുറപ്പെട്ടു; അവിടെവെച്ച് അത് നാലു ശാഖകളായി പിരിഞ്ഞു."},{"v":11,"t":"ഒന്നാമത്തേതിന്റെ പേര് പീഷോൻ. അത് സ്വർണ്ണനിറമുള്ള ഹവിലാ മുഴുവൻ ചുറ്റി ഒഴുകുന്നു."},{"v":12,"t":"ആ നാട്ടിലെ സ്വർണ്ണം മേല്ത്തരമാണ്. അവിടെ സുഗന്ധദ്രവ്യങ്ങളും പവിഴക്കല്ലുകളുമുണ്ട്."},{"v":13,"t":"രണ്ടാമത്തെ നദിയുടെ പേര് ഗീഹോൻ. അത് കൂഷ്ദേശം മുഴുവൻ ചുറ്റി ഒഴുകുന്നു."},{"v":14,"t":"മൂന്നാമത്തെ നദിയുടെ പേര് ടൈഗ്രിസ്. അത് അസ്സീറിയായുടെ കിഴക്കുഭാഗത്തു കൂടെ ഒഴുകുന്നു. നാലാമത്തെ നദി യൂഫ്രട്ടീസ്."},{"v":15,"t":"ഏദൻതോട്ടത്തിൽ വേലചെയ്യാനും അതിനെ പരിരക്ഷിക്കാനുമായി ദൈവമായ കർത്താവ് മനുഷ്യനെ അവിടെ കൊണ്ടുപോയി പാർപ്പിച്ചു."},{"v":16,"t":"ദൈവമായ കർത്താവ് മനുഷ്യനോട് ഇങ്ങനെ കല്പിച്ചു: തോട്ടത്തിലെ ഏതു വൃക്ഷത്തിൽനിന്നും നിനക്ക് യഥേഷ്ടം ഭക്ഷിക്കാം."},{"v":17,"t":"എന്നാൽ, നന്മതിന്മകളുടെ അറിവിന്റെ വൃക്ഷത്തിൽനിന്നും നീ ഭക്ഷിക്കരുത്; കാരണം, അതിൽനിന്നു ഭക്ഷിക്കുന്ന ദിവസം നീ തീർച്ചയായും മരിക്കും."},{"v":18,"t":"ദൈവമായ കർത്താവ് അരുളിച്ചെയ്തു: മനുഷ്യൻ ഏകനായിരിക്കുന്നത് നന്നല്ല. അവനുചേർന്ന തുണയെ ഞാൻ അവനുവേണ്ടി സൃഷ്ടിക്കും."},{"v":19,"t":"ദൈവമായ കർത്താവ് കയ്യിലെ സകലമൃഗങ്ങളെയും ആകാശത്തിലെ സകല പക്ഷികളെയും മണ്ണിൽനിന്നു മെനഞ്ഞെടുത്തു; മനുഷ്യൻ എന്തു വിളിക്കുമെന്നു കാണാൻ അവയെ അവന്റെയടുക്കൽ കൊണ്ടുവന്നു. മനുഷ്യൻ ഓരോ ജീവിയെയും എന്തു വിളിച്ചോ, അത് അതിന്റെ പേരായി."},{"v":20,"t":"എല്ലാ കന്നുകാലികൾക്കും ആകാശത്തിലെ പക്ഷികൾക്കും കരയിലെ മൃഗങ്ങൾക്കും മനുഷ്യൻ പേരുനല്കി. എന്നാൽ, തനിക്കു ചേർന്ന തുണയെ മനുഷ്യൻ കണ്ടില്ല."},{"v":21,"t":"അതുകൊണ്ട്, ദൈവമായ കർത്താവ് മനുഷ്യനിൽ ഗാഢനിദ്ര വരുത്തി; അവൻ ഉറങ്ങി. അനന്തരം അവിടെനിന്ന് അവന്റെ വാരിയെല്ലുകളിൽ ഒന്നെടുത്ത് ആവിടം മാംസംകൊണ്ടു മൂടി."},{"v":22,"t":"മനുഷ്യനിൽനിന്നെടുത്ത വാരിയെല്ലുകൊണ്ടു ദൈവമായ കർത്താവ് ഒരു സ്ത്രീയെ രൂപപ്പെടുത്തി. അവളെ മനുഷ്യന്റെ അടുക്കൽ കൊണ്ടുവന്നു."},{"v":23,"t":"അപ്പോൾ മനുഷ്യൻ പറഞ്ഞു: ഒടുവിൽ ഇതാ! ഇവളാണ് എന്റെ അസ്ഥികളിൽനിന്നുള്ള അസ്ഥിയും മാംസത്തിൽനിന്നുള്ള മാംസവും! ഇവൾ നാരിഎന്നു വിളിക്കപ്പെടും; എന്തെന്നാൽ, നരനിൽനിന്നു ഇവൾ എടുക്കപ്പെട്ടു.","p":1},{"v":24,"t":"അതിനാൽ, പുരുഷൻ തന്റെ പിതാവിനെയും മാതാവിനെയും വിട്ടു തന്റെ ഭാര്യയുമായി സംയോജിക്കുകയും അവർ ഏകശരീരമായിത്തീരുകയും ചെയ്യും.","p":1},{"v":25,"t":"അവരിരുവരും, മനുഷ്യനും അവന്റെ സ്ത്രീയും, നഗ്നരായി രുന്നു; എന്നാൽ അവർക്കു ലജ്ജതോന്നിയിരുന്നില്ല."}],"3":[{"h":"മനുഷ്യന്റെ പതനം"},{"v":1,"t":"ദൈവമായ കർത്താവ് ഉരുവാക്കിയ എല്ലാ വന്യജീവികളിലുംവെച്ച് കൗശലമേറിയതായിരുന്നു സർപ്പം. അതു സ്ത്രീയോടു ചോദിച്ചു: തോട്ടത്തിലെ ഒരു വൃക്ഷത്തിൽ നിന്നും ഭക്ഷിക്കരുതെന്ന് ദൈവം വാസ്തവത്തിൽ പറഞ്ഞിട്ടുണ്ടോ?","p":1},{"v":2,"t":"സ്ത്രീ സർപ്പത്തോടു പറഞ്ഞു: തോട്ടത്തിലെ വൃക്ഷങ്ങളുടെ ഫലങ്ങൾ ഞങ്ങൾക്കു ഭക്ഷിക്കാം.","p":1},{"v":3,"t":"എന്നാൽ, 'നിങ്ങൾ മരിക്കാതിരിക്കാൻ തോട്ടത്തിന്റെ നടുവിലുള്ള വൃക്ഷത്തിന്റെ ഫലത്തിൽനിന്നു ഭക്ഷിക്കരുത്; അതിൽ തൊടുകയുമരുത്' എന്നു ദൈവം പറഞ്ഞിട്ടുണ്ട്.","p":1},{"v":4,"t":"സർപ്പം സ്ത്രീയോടു പറഞ്ഞു: നിങ്ങൾ തീർച്ചയായും മരിക്കുകയില്ല.","p":1},{"v":5,"t":"കാരണം, അതിൽനിന്നു തിന്നുന്ന ദിവസം നിങ്ങളുടെ കണ്ണുകൾ തുറക്കുമെന്നും നന്മയും തിന്മയും അറിയുന്നവരായി നിങ്ങൾ ദൈവത്തെപ്പോലെ ആകുമെന്നും ദൈവത്തിന് അറിയാം.","p":1},{"v":6,"t":"ആ വൃക്ഷം ഭക്ഷിക്കാൻ ഉപയുക്തവും കണ്ണുകൾക്ക് ആകർഷകവുമാണെന്ന് സ്ത്രീ കണ്ടു. ആ വൃക്ഷം അറിവുണ്ടാക്കാൻ പര്യാപ്തവുമായിരുന്നു. അവൾ അതിന്റെ ഫലത്തിൽനിന്നു എടുത്തു ഭക്ഷിച്ചു; തന്നോടൊപ്പം ഇരുന്ന ഭർത്താവിനും അവൾ നൽകി; അവനും ഭക്ഷിച്ചു.","p":1},{"v":7,"t":"അപ്പോൾ ഇരുവരുടെയും കണ്ണുകൾ തുറക്കപ്പെട്ടു; തങ്ങൾ നഗ്നരാണെന്ന് അവർ അറിഞ്ഞു. അവർ അത്തിയിലകൾ കൂട്ടിച്ചേർത്തു തങ്ങൾക്കായി അരപ്പട്ടയുണ്ടാക്കി.","p":1},{"v":8,"t":"സായാഹ്നനേരത്ത് തോട്ടത്തിൽ ഉലാത്തുന്ന ദൈവമായ കർത്താവിന്റെ ശബ്ദം അവർ കേട്ടു. മനുഷ്യനും അവന്റെ ഭാര്യയും ദൈവമായ കർത്താവിന്റെ സന്നിധിയിൽനിന്ന് തോട്ടത്തിലെ മരങ്ങൾക്കിടയിലൊളിച്ചു.","p":1},{"v":9,"t":"ദൈവമായ കർത്താവ് മനുഷ്യനെ വിളിച്ച് അവനോടു ചോദിച്ചു: നീ എവിടെയാണ്?","p":1},{"v":10,"t":"അവൻ മറുപടി പറഞ്ഞു: തോട്ടത്തിൽ അവിടത്തെ ശബ്ദം ഞാൻ കേട്ടു. ഞാൻ നഗ്നനായിരുന്നതിനാൽ ഭയപ്പെട്ടുപോയി, അതുകൊണ്ട് ഞാൻ ഒളിച്ചതാണ്.","p":1},{"v":11,"t":"അവിടുന്ന് ചോദിച്ചു: നീ നഗ്നനാണെന്ന് ആരാണ് നിന്നോടു പറഞ്ഞത്? ഭക്ഷിക്കരുതെന്ന് ഞാൻ നിന്നോടു കല്പിച്ച വൃക്ഷത്തിൽനിന്ന് നീ ഭക്ഷിച്ചുവോ?","p":1},{"v":12,"t":"മനുഷ്യൻ പറഞ്ഞു: അങ്ങേ എനിക്കു കൂട്ടിനു തന്ന സ്ത്രീ; അവളാണ് വൃക്ഷത്തിൽനിന്നുള്ള ഫലം എനിക്കു നൽകിയത്. ഞാൻ അതു ഭക്ഷിക്കുകയും ചെയ്തു.","p":1},{"v":13,"t":"ദൈവമായ കർത്താവ് സ്ത്രീയോടു ചോദിച്ചു: നീ എന്താണ് ഈ ചെയ്തത്? സ്ത്രീ പറഞ്ഞു: സർപ്പം എന്നെ വഞ്ചിച്ചു; ഞാൻ ഭക്ഷിക്കുകയും ചെയ്തു.","p":1},{"h":"ശിക്ഷയും വാഗ്ദാനവും"},{"v":14,"t":"ദൈവമായ കർത്താവ് സർപ്പത്തോടു പറഞ്ഞു: ഇതു നീ ചെയ്തതുകൊണ്ട് എല്ലാ കന്നുകാലികളിലും കാട്ടുമൃഗങ്ങളിലുംവെച്ച് നീ ശപിക്കപ്പെട്ടവനായിരിക്കും. നീ ഉരസ്സുകൊണ്ട് ഇഴഞ്ഞുനടക്കും, നിന്റെ ജീവിതകാലമത്രയും പൊടിതിന്നും!","p":1},{"v":15,"t":"നീയും സ്ത്രീയും തമ്മിലും നിന്റെ സന്തതിയും അവളുടെ സന്തതിയും തമ്മിലും ഞാൻ ശത്രുത ഉളവാക്കും. അവൻ നിന്റെ തല തകർക്കും, നീ അവന്റെ കുതികാലിൽ ദംശിക്കുകയും ചെയ്യും.","p":1},{"v":16,"t":"അവിടുന്ന് സ്ത്രീയോടു പറഞ്ഞു: നിന്റെ ഗർഭാവസ്ഥകൾ ഞാൻ തീർച്ചയായും വർധിപ്പിക്കും. നീ വേദനയോടെ മക്കളെ പ്രസവിക്കും. എന്നാലും നിന്റെ അഭിലാഷം നിന്റെ ഭർത്താവിലായിരിക്കും, അവൻ നിന്നെ ഭരിക്കുകയും ചെയ്യും.","p":1},{"v":17,"t":"ആദത്തോട് അവിടന്നു പറഞ്ഞു: നീ നിന്റെ ഭാര്യയുടെ സ്വരം കേൾക്കുകയും തിന്നരുതെന്ന് ഞാൻ കല്പിച്ചിരുന്ന മരത്തിൽനിന്ന് തിന്നുകയും ചെയ്തതു കൊണ്ട് നീ മൂലം മണ്ണ് ശപിക്കപ്പെട്ടതായിരിക്കും. നിന്റെ ആയുഷ്കാലം മുഴുവൻ അധ്വാനംകൊണ്ട് നീ അതിൽനിന്നു ഭക്ഷിക്കും.","p":1},{"v":18,"t":"അത് മുള്ളും മുൾച്ചെടികളും നിനക്കായിമുളപ്പിക്കും. നീ വയൽച്ചെടികൾ ഭക്ഷിക്കും.","p":1},{"v":19,"t":"നീ മണ്ണിൽനിന്ന് എടുക്കപ്പെട്ടതുകൊണ്ട്അതിലേക്കു മടങ്ങുന്നതുവരെ നിന്റെ നെറ്റിയിലെ വിയർപ്പുകൊണ്ട് നീ അപ്പം ഭക്ഷിക്കും. എന്തെന്നാൽ, നീ പൊടിയാണ്; പൊടിയിലേക്കുതന്നെ നീ മടങ്ങും.","p":1},{"v":20,"t":"മനുഷ്യൻ തന്റെ ഭാര്യയെ ഹവ്വാ എന്നു പേരുവിളിച്ചു. കാരണം. അവൾ ജീവനുള്ള എല്ലാറ്റിന്റെയും മാതാവാണ്.","p":1},{"v":21,"t":"ദൈവമായ കർത്താവ് ആദത്തിനും അവന്റെ ഭാര്യയ്ക്കും തോലുകൊണ്ട് ഉടുപ്പുണ്ടാക്കി, അവരെ ധരിപ്പിച്ചു.","p":1},{"v":22,"t":"അനന്തരം ദൈവമായ കർത്താവ് പറഞ്ഞു: മനുഷ്യൻ ഇതാ, നന്മയും തിന്മയും അറിഞ്ഞ് നമ്മിലൊരുവനെപ്പോലെ ആയിരിക്കുന്നു. ഇനി അവൻ കൈ നീട്ടി ജീവന്റെ വൃക്ഷത്തിൽ നിന്നുകൂടി പറിച്ചു തിന്ന്നിത്യം ജീവിക്കുന്നവനാകാൻ ഇടയാകരുത്.","p":1},{"v":23,"t":"എവിടെനിന്ന് അവൻ എടുക്കപ്പെട്ടുവോ, ആ മണ്ണിൽ അധ്വാനിക്കേണ്ടതിന് ദൈവമായ കർത്താവ് അവനെ ഏദൻതോട്ടത്തിൽനിന്നു പുറത്താക്കി.","p":1},{"v":24,"t":"മനുഷ്യനെ പുറത്താക്കിയശേഷം ജീവവൃക്ഷത്തിന്റെ വഴി കാക്കാൻ അവിടന്ന് കെരൂബുകളെ, എല്ലാ വശത്തേക്കുംകറങ്ങുന്നതും തീ ജ്വലിക്കുന്നതുമായ വാളുമായി ഏദൻതോട്ടത്തിനു മുമ്പിൽ കാവൽ നിറുത്തി.","p":1}],"4":[{"h":"കായേനും ആബേലും"},{"v":1,"t":"മനുഷ്യൻ തന്റെ ഭാര്യയായ ഹവ്വായെ അറിഞ്ഞു അവൾ ഗർഭംധരിച്ച് കായേനെ പ്രസവിച്ചു. അവൾ പറഞ്ഞും കർത്താവിന്റെ സഹായത്താൽ ഞാനൊരു ആൺകുഞ്ഞിനെ നേടിയിരിക്കുന്നു.","p":1},{"v":2,"t":"തുടർന്ന് അവൾ അവന്റെ സഹോദരൻ ആബേലിനെ പ്രസവിച്ചു. ആബേൽ ആടുകളെ മേയിക്കുന്നവനും കായേൻ മണ്ണിൽ അധ്വാനിക്കുന്നവനുമായിരുന്നു.","p":1},{"v":3,"t":"യഥാകാലം കായേൻ ഭൂമിയിൽ നിന്നുള്ള വിളവിന്റെ ഒരു ഭാഗം കർത്താവിനു കാണിക്കയായി കൊണ്ടുവന്നു.","p":1},{"v":4,"t":"ആബേലും തന്റെ ആട്ടിൻ കൂട്ടത്തിലെ ചില കടിഞ്ഞൂലുകളെയും അവയുടെ കൊഴുപ്പിന്റെ ഒരു ഭാഗവും കൊണ്ടുവന്നു. ആബേലിലും അവന്റെ കാണിക്കയിലും കർത്താവു പ്രസാദിച്ചു.","p":1},{"v":5,"t":"എന്നാൽ കായേനിലും അവന്റെ കാണിക്കയിലും അവിടന്നു പ്രസാദിച്ചില്ല. അതിനാൽ കായേൽ അത്യധികം കുപിതനായി. അവന്റെ മുഖം താണു.","p":1},{"v":6,"t":"കർത്താവു കായേനോടു ചോദിച്ചു: നീ കോപിച്ചിരിക്കുന്നതെന്തുകൊണ്ട്? നിന്റെ മുഖം താണിരിക്കുന്നതെന്തുകൊണ്ട്?","p":1},{"v":7,"t":"അത് ഉയർത്താൻ തക്ക വിധം നന്നായി വർത്തിച്ചിരുന്നെങ്കിൽ! നീ നല്ലതു ചെയ്യുന്നില്ലെങ്കിൽ വാതില്ക്കൽത്തന്നെ പാപം പതിയിരിക്കുന്നു. അതിന്റെ അഭിലാഷം നിന്നിലാണ്. പക്ഷേ, നീ അതിനെ കീഴടക്കേണ്ടിയിരിക്കുന്നു.","p":1},{"v":8,"t":"കായേൻ തന്റെ സഹോദരനായ ആബേലിനോട് കയർത്തു. അനന്തരം അവർ വയലിലായിരിക്കേ കായേൻ ആബേലിനെതിരേ ചെന്ന് അവനെ കൊന്നു.","p":1},{"v":9,"t":"കർത്താവ് കായേനോടു ചോദിച്ചു: നിന്റെ സഹോദരൻ ആബേൽ എവിടെ? അവൻ പറഞ്ഞു. എനിക്കറിഞ്ഞുകൂടാ. ഞാനാണോ എന്റെ സഹോദരന്റെ കാവല്ക്കാരൻ?","p":1},{"v":10,"t":"എന്നാൽ അവിടന്നു ചോദിച്ചു നീ എന്താണു ചെയ്തത്? നിന്റെ സഹോദരന്റെ രക്തം മണ്ണിൽ നിന്ന് എന്റെ നേർക്കു മുറവിളികൂട്ടുന്നതിന്റെ സ്വരം!","p":1},{"v":11,"t":"നിന്റെ കൈയിൽനിന്ന് നിന്റെ സഹോദരന്റെ രക്തം സ്വീകരിക്കാൻ വായ്പിളർന്ന നിലത്താൽ ഇപ്പോൾ നീ ശപിക്കപ്പെട്ടവനായിരിക്കും.","p":1},{"v":12,"t":"നീ നിലം കൃഷി ചെയ്യുമ്പോൾ ഇനിമുതൽ അത് അതിന്റെ വിള നിനക്കു തരുകയില്ല. നീ ഭൂമിയിൽ അസ്ഥിരനും അലയുന്നവനുമായിരിക്കും.","p":1},{"v":13,"t":"കായേൻ കർത്താവിനോടു പറഞ്ഞു: എനിക്കു വഹിക്കാവുന്നതിലും വലുതാണ് എന്റെ ശിക്ഷ.","p":1},{"v":14,"t":"ഇന്ന് ഇതാ അവിടന്ന് എന്നെ ഈ മണ്ണിൽനിന്ന് ആട്ടിപ്പായിച്ചിരിക്കുന്നു. അവിടത്തെ സന്നിധിയിൽനിന്ന് ഞാൻ സ്വയം ഒളിക്കേണ്ടിയിരിക്കുന്നു. ഞാൻ ഭൂമിയിൽ അസ്ഥിരനും അലയുന്നവനുമായിരിക്കും എന്നെ കണ്ടുമുട്ടുന്ന ആരും എന്നെ കൊല്ലും.","p":1},{"v":15,"t":"കർത്താവ് അവനോടു പറഞ്ഞു. അങ്ങനെയെങ്കിൽ കായനെ കൊല്ലുന്ന ആരുടെമേലും ഏഴ് ഇരട്ടിയായി പ്രതികാരം ചെയ്യപ്പെടും അവനെ കണ്ടുമുട്ടുന്നവർ ആരും അവനെ കൊല്ലാതിരിക്കേണ്ടതിന് കർത്താവ് കായേന്റെ മേൽ ഒരു അടയാളം പതിച്ചു.","p":1},{"v":16,"t":"കായേൻ കർത്താവിൻറെ സന്നിധി വിട്ട് ഏദനു കിഴക്ക് നോദ് ദേശത്ത് വാസമുറപ്പിച്ചു .","p":1},{"h":"കായേന്റെ സന്തതിപരമ്പര"},{"v":17,"t":"കായേൻ തന്റെ ഭാര്യയെ അറിഞ്ഞു. അവൾ ഗർഭം ധരിച്ചു ഹെനോക്കിനെ പ്രസവിച്ചു. അവൻ ഒരു പട്ടണം പണിയുന്നുണ്ടായിരുന്നു. തന്റെ പുത്രന്റെ പേരനുസരിച്ച് ആ പട്ടണത്തിന് അവൻ ഹെനോക്ക് എന്നു പേരിട്ടു.","p":1},{"v":18,"t":"ഹെനോക്കിന് ഈരാദ് ജനിച്ചു; ഈരാദിന് മെഹൂയാവേലിനെ ജനിപ്പിച്ചു; മെഹൂയാവേൽ മെഥൂശായേലിനെ ജനിപ്പിച്ചു. മെഥൂശായേൽ ലാമേക്കിനെ ജനിപ്പിച്ചു.","p":1},{"v":19,"t":"ലാമേക് രണ്ടു സ്ത്രീകളെ ഭാര്യമാരായി സ്വീകരിച്ചു. ഒന്നാമത്തവളുടെ പേര് ആദാ; രണ്ടാമത്തവളുടെ പേര് സില്ലാ.","p":1},{"v":20,"t":"ആദാ യാബാലിനെ പ്രസവിച്ചു. അവൻ ആടുമാടുകളോടൊപ്പം കൂടാരത്തിൽ വസിക്കുന്നവരുടെ പിതാവായിരുന്നു.","p":1},{"v":21,"t":"അവന്റെ സഹോദരന്റെ പേര് യൂബാൽ. കിന്നരവും വേണുവും വായിക്കുന്നവരുടെ പൂർവ്വിതാവായിരുന്നു അവൻ.","p":1},{"v":22,"t":"സില്ലായും പ്രസവിച്ചു, തൂബൽക്കയീനെ. അവൻ ചെമ്പുകൊണ്ടും ഇരുമ്പുകൊണ്ടും എല്ലാത്തരം ഉപകരണങ്ങളും നിർമ്മിക്കുന്നവനായിരുന്നു. തൂബൽക്കയീന്റെ സഹോദരി നാമാ ആയിരുന്നു.","p":1},{"v":23,"t":"ലാമേക് തന്റെ ഭാര്യമാരോടു പറഞ്ഞു: ആദാ, സില്ലാ, എന്റെ സ്വരം കേൾക്കുവിൻ! ലാമേക്കിന്റെ ഭാര്യമാരേ, എന്റെ ഈ വാക്കിനു ചെവിതരുവിൻ: എന്നെ മുറിവേല്പിച്ചതിന് ഒരുവനെ ഞാൻ കൊന്നു; എന്നെ അടിച്ചതിന് ഒരു കുട്ടിയെയും.","p":1},{"v":24,"t":"എന്തെന്നാൽ, കായേന്റെ പ്രതികാരം ഏഴിരട്ടിയെങ്കിൽ ലാമേക്കിന്റെ എഴുപത്തേഴ് ഇരട്ടിയായിരിക്കും.","p":1},{"v":25,"t":"ആദം വീണ്ടും തന്റെ ഭാര്യയെ അറിഞ്ഞു. അവൾ ഒരു പുത്രനു ജന്മം നൽകി. കായേൻ ആബേലിനെ വധിച്ചിരുന്നതുകൊണ്ട്, അവനുപകരം ദൈവം എനിക്ക് മറ്റൊരു സന്താനത്തെ നൽകി എന്ന അർത്ഥത്തിൽ അവൾ അവന് സേത്ത് എന്നു പേരിട്ടു.","p":1},{"v":26,"t":"സേത്തിനും ഒരു പുത്രൻ ജനിച്ചു. അയാൾ അവന് എനോശ് എന്നു പേരിട്ടു. അക്കാലത്താണ് കർത്താവിന്റെ നാമം വിളിച്ചപേക്ഷിക്കാൻ തുടങ്ങിയത്.","p":1}],"5":[{"h":"ആദം മുതൽ നോഹവരെ"},{"v":1,"t":"ആദത്തിന്റെ വംശാവലിഗ്രന്ഥമാണിത്: ദൈവം മനുഷ്യനെ സൃഷ്ടിച്ച ദിവസം തന്റെ സാദൃശ്യത്തിൽ ദൈവം അവനെ രൂപപ്പെടുത്തി.","p":1},{"v":2,"t":"ആണും പെണ്ണുമായി അവരെ അവിടുന്ന് സൃഷ്ടിച്ചു; അവിടുന്ന് അവരെ അനുഗ്രഹിച്ചു. അവർ സൃഷ്ടിക്കപ്പെട്ട ദിവസം മനുഷ്യൻ എന്ന് അവിടുന്ന് അവരെ പേർവിളിച്ചു.","p":1},{"v":3,"t":"നൂറ്റിമുപ്പതു വയസ്സായപ്പോൾ ആദം തന്റെ ഛായയിലും സാദൃശ്യത്തിലും ഒരു പുത്രനെ ജനിപ്പിച്ചു; അവൻ സേത്ത് എന്നു പേരിട്ടു.","p":1},{"v":4,"t":"സേത്തിനെ ജനിപ്പിച്ചശേഷം ആദത്തിന്റെ ആയുസ്സ് എണ്ണൂറു വർഷമായിരുന്നു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":5,"t":"ആദത്തിന്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തി മുപ്പതു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു."},{"v":6,"t":"നൂറ്റഞ്ചു വയസ്സായപ്പോൾ സേത്ത് എനോഷിനെ ജനിപ്പിച്ചു.","p":1},{"v":7,"t":"എനോഷിനെ ജനിപ്പിച്ചശേഷം സേത്ത് എണ്ണൂറ്റി ഏഴു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":8,"t":"സേത്തിന്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തിപ്പന്ത്രണ്ടു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":9,"t":"തൊണ്ണൂറു വയസ്സായപ്പോൾ എനോഷ് കെയ്‌നാനെ ജനിപ്പിച്ചു.","p":1},{"v":10,"t":"കെയ്‌നാനെ ജനിപ്പിച്ചശേഷം എനോഷ് എണ്ണൂറ്റിപ്പതിനഞ്ചു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":11,"t":"എനോഷിൻ്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തി അഞ്ചു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു."},{"v":12,"t":"എഴുപതു വയസ്സായപ്പോൾ കെയ്‌നാൻ മഹലലേലിനെ ജനിപ്പിച്ചു.","p":1},{"v":13,"t":"മഹലലേലിനെ ജനിപ്പിച്ചശേഷം കെയ്‌നാൻ എണ്ണൂറ്റിപ്പത്തു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":14,"t":"കെയ്‌നാന്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തിപ്പത്തു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":15,"t":"അറുപത്തഞ്ചു വയസ്സായപ്പോൾ മഹലലേൽ യാരെദിനെ ജനിപ്പിച്ചു.","p":1},{"v":16,"t":"യാരെദിനെ ജനിപ്പിച്ചശേഷം മഹലലേൽ എണ്ണൂറ്റിമുപ്പതു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":17,"t":"മഹലലേലിന്റെ ആകെ ജീവിതായുസ്സ് എണ്ണൂറ്റി തൊണ്ണൂറ്റി അഞ്ചു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":18,"t":"നൂറ്റിയറുപത്തിരണ്ടു വയസ്സായപ്പോൾ യാരെദ് ഹെനോക്കിനെ ജനിപ്പിച്ചു.","p":1},{"v":19,"t":"ഹെനോക്കിനെ ജനിപ്പിച്ച ശേഷം യാരെദ് എണ്ണൂറു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":20,"t":"യാരെദിന്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തി അറുപത്തിരണ്ടു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":21,"t":"അറുപത്തഞ്ചു വയസ്സായപ്പോൾ ഹെനോക്ക് മെത്തുശെലഹിനെ ജനിപ്പിച്ചു.","p":1},{"v":22,"t":"മെത്തുശെലഹിനെ ജനിപ്പിച്ചശേഷം ഹെനോക്ക് മുന്നൂറു വർഷം ദൈവത്തോടൊപ്പം വ്യാപരിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":23,"t":"ഹെനോക്കിന്റെ ആകെ ജീവിതായുസ്സ് മുന്നൂറ്റി അറുപത്തഞ്ചു വർഷമായിരുന്നു.","p":1},{"v":24,"t":"ഹെനോക്ക് ദൈവത്തോടൊപ്പം വ്യാപരിച്ചു. പിന്നെ അവൻ കാണപ്പെട്ടില്ല. കാരണം, ദൈവം അവനെ എടുത്തു.","p":1},{"v":25,"t":"നൂറ്റിയെൺപത്തേഴു വയസ്സായപ്പോൾ മെത്തുശെലഹ് ലാമെക്കിനെ ജനിപ്പിച്ചു.","p":1},{"v":26,"t":"ലാമെക്കിനെ ജനിപ്പിച്ചശേഷം മെത്തുശെലഹ് എഴുനൂറ്റിഎൺപത്തിരണ്ടു വർഷം ജീവിച്ചു. മെത്തുശെലഹ് പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":27,"t":"മെത്തുശെലഹിന്റെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തി അറുപത്തൊമ്പതു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":28,"t":"നൂറ്റിയെൺപത്തിരണ്ടു വയസ്സായപ്പോൾ ലാമെക്ക് ഒരു പുത്രനെ ജനിപ്പിച്ചു.","p":1},{"v":29,"t":"കർത്താവു ശപിച്ച മണ്ണുമുഖാന്തരമുള്ള നമ്മുടെ അധ്വാനത്തിൽനിന്നും കൈകളുടെ ക്ലേശത്തിൽനിന്നും ഇവൻ നമ്മെ ആശ്വസിപ്പിക്കും എന്നു പറഞ്ഞ് അവൻ നോഹ എന്നു പേരിട്ടു.","p":1},{"v":30,"t":"നോഹയെ ജനിപ്പിച്ചശേഷം ലാമെക്ക് അഞ്ഞൂറ്റി തൊണ്ണൂറ്റഞ്ചു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":31,"t":"ലാമെക്കിന്റെ ആകെ ജീവിതായുസ്സ് എഴുനൂറ്റി എഴുപത്തിയേഴു വർഷമായിരുന്നു. അനന്തരം അവൻ മരിച്ചു.","p":1},{"v":32,"t":"നോഹയ്ക്ക് അഞ്ഞൂറു വയസ്സു തികഞ്ഞു. നോഹ ഷേമിനെയും ഹാമിനെയും യാഫെത്തിനെയും ജനിപ്പിച്ചു.","p":1}],"6":[{"h":"തിന്മ വർദ്ധിക്കുന്നു"},{"v":1,"t":"മനുഷ്യൻ ഭൂമിയിൽ പെരുകാൻ തുടങ്ങുകയും അവർക്ക് പുത്രിമാർ ജനിക്കയും ചെയ്തപ്പോൾ","p":1},{"v":2,"t":"മനുഷ്യപുത്രിമാർ അഴകുള്ളവരാണെന്ന് ദൈവപുത്രന്മാർ കണ്ടു. തങ്ങൾ തിരഞ്ഞെടുത്ത എല്ലാവരിൽനിന്നും അവർ തങ്ങൾക്കായി ഭാര്യമാരെ സ്വീകരിച്ചു."},{"v":3,"t":"അപ്പോൾ കർത്താവു പറഞ്ഞു: എന്റെ ചൈതന്യം മനുഷ്യനിൽ എന്നേക്കും നിലനിൽക്കുകയില്ല. കാരണം, അവൻ ജഡംകൂടിയാണ്. അവന്റെ ആയുസ്സ് ഇനിമേൽ നൂറ്റിയിരുപതു വർഷമായിരിക്കും.","p":1},{"v":4,"t":"ദൈവകുമാരന്മാർ മനുഷ്യപുത്രിമാരെ പ്രാപിക്കുകയും അവർക്ക് മക്കൾ ജനിക്കയും ചെയ്തിരുന്ന ആ കാലഘട്ടവും അതിനുശേഷവും ഭൂമിയിൽ നെഫിലുകൾ ഉണ്ടായി. അവരാണ് പുരാതനകാലത്തെ പേരുകേട്ട യുദ്ധവീരന്മാർ.","p":1},{"v":5,"t":"ഭൂമിയിൽ മനുഷ്യന്റെ ദുഷ്ടത വലുതാണെന്നും അവന്റെ ഹൃദയത്തിലെ ചിന്തകളുടെ ഓരോ രൂപവും എപ്പോഴും ദുഷ്ടത മാത്രമാണെന്നും കർത്താവു കണ്ടു.","p":1},{"v":6,"t":"ഭൂമിയിൽ മനുഷ്യനെ രൂപപ്പെടുത്തിയതിൽ കർത്താവു പരിതപിച്ചു; അവിടത്തെ ഹൃദയം നൊന്തു.","p":1},{"v":7,"t":"കർത്താവു അരുളിച്ചെയ്തു: ഞാൻ സൃഷ്ടിച്ച മനുഷ്യനെ ഭൂമുഖത്തുനിന്നു ഞാൻ തുടച്ചുമാറ്റും. മനുഷ്യൻ മുതൽ മൃഗങ്ങളും ഇഴജന്തുക്കളും ആകാശത്തിലെ പറവകളും വരെ തുടച്ചുമാറ്റും. എന്തെന്നാൽ, അവയെ സൃഷ്ടിച്ചതിൽ ഞാൻ പരിതപിക്കുന്നു.","p":1},{"v":8,"t":"എന്നാൽ, നോഹ കർത്താവിന്റെ ദൃഷ്ടിയിൽ പ്രീതി കണ്ടെത്തി.","p":1},{"v":9,"t":"ഇതാണ് നോഹയുടെ വംശാവലി: നോഹ നീതിമാനായിരുന്നു; തന്റെ തലമുറയിലെ പൂർണ്ണനായ മനുഷ്യൻ. ദൈവത്തോടൊപ്പം നോഹ വ്യാപരിച്ചു.","p":1},{"v":10,"t":"നോഹ മൂന്നു പുത്രന്മാരെ ജനിപ്പിച്ചു: ഷേം, ഹാം, യാഫെത്ത്.","p":1},{"v":11,"t":"ദൈവത്തിന്റെ മുമ്പാകെ ഭൂമി ദുഷിച്ചതായിത്തീർന്നു. ഭൂമി അക്രമംകൊണ്ടു നിറഞ്ഞു.","p":1},{"v":12,"t":"ദൈവം ഭൂമിയെ നോക്കി. ഇതാ, അത് ദുഷിച്ചതായിരിക്കുന്നു. കാരണം, എല്ലാ മനുഷ്യരും ഭൂമിയിലെ തങ്ങളുടെ മാർഗ്ഗങ്ങൾ ദുഷിപ്പിച്ചു കളഞ്ഞു.","p":1},{"h":"നോഹയുടെ പെട്ടകം"},{"v":13,"t":"ദൈവം നോഹയോട് അരുളിച്ചെയ്തു: എന്റെ മുമ്പിൽ മനുഷ്യരുടെയെല്ലാം അവസാനം അടുത്തു. കാരണം, അവർമൂലം ഭൂമി അക്രമംകൊണ്ടു നിറഞ്ഞിരിക്കുന്നു. ഇതാ, ഞാൻ അവരെ ഭൂമിയോടൊപ്പം നശിപ്പിക്കും .","p":1},{"v":14,"t":"ഗോഫർമരംകൊണ്ട് നീ ഒരു പെട്ടകം ഉണ്ടാക്കണം. അതിൽ മുറികൾ തിരിക്കുക. അതിന്റെ അകത്തും പുറത്തും കീലുതേയ്കണം."},{"v":15,"t":"ഇങ്ങനെയാണ് അതു ചെയ്യേണ്ടത്. പെട്ടകത്തിനു മൂന്നുറു മുഴം നീളവും അമ്പതു മുഴം വീതിയും മുപ്പതു മുഴം ഉയരവും.","p":1},{"v":16,"t":"പെട്ടകത്തിന് നീ ഒരു മേൽക്കൂര യുണ്ടാക്കണം മേൽക്കൂരയിൽ നിന്ന് ഒരു മുഴം താഴെ പെട്ടകത്തിന് ഒരു ജനലും വശത്ത് ഒരു വാതിലും വയ്ക്കണം കീഴ്ത്തട്ടും രണ്ടാംതട്ടും മൂന്നാംതട്ടുമായി വേണം നീ പണിയാൻ.","p":1},{"v":17,"t":"ഇതാ, ഞാൻ ആകാശത്തിൻ കീഴിൽ ജീവശ്വാസമുള്ള എല്ലാ ശരീരി കളെയും നശിപ്പിക്കാൻ ഭൂമിയിലേക്ക് ജലപ്രളയം കൊണ്ടുവരും. ഭൂമിയിലുള്ളതെല്ലാം നശിക്കും.","p":1},{"v":18,"t":"എന്നാൽ നീയുമായി ഞാൻ എൻ്റെ ഉടമ്പടി ഉറപ്പിക്കും. നീ പെട്ടകത്തിലേക്കു കടക്കണം, നീയും നിന്നോടൊപ്പം നിൻ്റെ പുത്രന്മാരും നിൻ്റെ ഭാര്യയും നിൻ്റെ പുത്രന്മാരുടെ ഭാര്യമാരും നിന്നോടൊപ്പം ജീവൻ നിലനിർത്തേണ്ടതിന് പെട്ടകത്തിലേക്ക് എല്ലാറ്റിലും നിന്ന് - എല്ലാ ജീവികളിലും ശരീരികളിൽ നിന്ന് - ആണും പെണ്ണുമായി ഓരോ ജോഡി കൊണ്ടുവരണം. ജീവൻ നിലനിർത്തേണ്ടതിന് എല്ലാറ്റിറ്റും നിന്ന് പക്ഷികൾ, മൃഗങ്ങൾ എന്നിവയിൽനിന്ന് ഇനംതിരിഞ്ഞ്, ഭൂമിയിൽ ഇഴയുന്ന സകലതിലും നിന്ന് ഇനം തിരിഞ്ഞ് ഓരോ ജോഡി നിൻ്റെ പക്കലേക്ക് വരട്ടെ. നീയാകട്ടെ, ഭക്ഷ്യയോഗ്യമായ എല്ലാ ആഹാര പദാർത്ഥങ്ങളിൽ നിന്നും എടുത്ത് നിൻ്റെ പക്കൽ ശേഖരിക്കണം. അവ നിനക്കും അവർക്കുമുള്ള ഭക്ഷണമായിരിക്കും. ദൈവം തന്നോടു കൽപ്പിച്ചതെല്ലാം നോഹ ചെയ്തു; അപ്രകാരം തന്നെ അവൻ ചെയ്തു.","p":1}],"7":[{"h":"പെട്ടകപ്രവേശം"},{"v":1,"t":"കർത്താവ് നോഹയോട് അരുൾച്ചെയ്തു: നീയും നിൻ്റെ കുടുംബമെല്ലാവരും പെട്ടകത്തിൽ പ്രവേശിക്കുക. കാരണം, ഈ തലമുറയിൽ എൻ്റെ മുമ്പാകെ നിന്നെ ഞാൻ നീതിമാനായി കണ്ടിരിക്കുന്നു.","p":1},{"v":2,"t":"ശുദ്ധിയുള്ള എല്ലാ മൃഗങ്ങളിൽനിന്നും ആണും പെണ്ണുമായി ഏഴു ജോഡിവീതവും ശുദ്ധിയില്ലാത്തമൃഗങ്ങളിൽനിന്ന് ആണും പെണ്ണുമായി ഓരോ ജോഡിവീതം നീ എടുക്കണം.","p":1},{"v":3,"t":"അതുപോലെ, ആകാശത്തിലെ പക്ഷികളിൽനിന്ന് പൂവനും പിടയമായി ഏഴു ജോഡി വീതവും ഭൂമി മുഴുവൻ അവയുടെ വംശപരമ്പര നിലനിർത്തേണ്ടതിനാണിത്.","p":1},{"v":4,"t":"എന്തെന്നാൽ ഏഴു ദിവസം കൂടി കഴിഞ്ഞാൽ നാല്പതു പകലും നാല്പതു രാവും ഭൂമിയിൽ ഞാൻ മഴ പെയ്യിക്കും; ഞാൻ ഉരുവാക്കിയ സകല ജീവികളെയും ഞാൻ ഭൂമുഖത്തുനിന്നു തുടച്ചുനീക്കും.","p":1},{"v":5,"t":"കർത്താവ് തന്നോട് കൽപ്പിച്ചതൊക്കെയും നോഹ ചെയ്തു.","p":1},{"v":6,"t":"നോഹയ്ക്ക് അറുനൂറു വയസ്സുള്ളപ്പോഴാണ് ഭൂമിയിൽ ജലപ്രളയമുണ്ടായത്.","p":1},{"v":7,"t":"നോഹയും അലനോടൊപ്പം അവൻ്റെ പുത്രന്മാരും അവൻ്റെ ഭാര്യയും അവൻ്റെ പുത്രന്മാരുടെ ഭാര്യമാരും ജലപ്രളയത്തിനു മുന്നേ പെട്ടകത്തിലേക്ക് വന്നു.","p":1},{"v":8,"t":"ശുദ്ധിയുള്ള മൃഗങ്ങളിൽനിന്നും ശുദ്ധിയില്ലാത്തവയിൽനിന്നും പക്ഷികളിൽ നിന്നും നിലത്തിഴയുന്ന സകലതിൽനിന്നും,","p":1},{"v":9,"t":"നോഹയോടു കർത്താവു കൽപ്പിച്ചിരുന്നതുപോലെ, രണ്ടുവീതം, ആണും പെണ്ണുമായി നോഹയുടെ അടുത്ത് പെട്ടകത്തിലേക്ക് വന്നു."},{"v":10,"t":"ഏഴാംദിവസം ഭൂമിയിൽ ജലപ്രളയമുണ്ടായി.","p":1},{"v":11,"t":"നോഹയുടെ ജീവിതത്തിൻ്റെഅറുനൂറാം വർഷം രണ്ടാംമാസം പതിനേഴാം ദിവസം, അതേദിവസം, അത്യഗാധത്തിൻ്റെ ഉറവുകളെല്ലാംപൊട്ടിയൊഴുകി; ആകാശജാലകങ്ങൾ തുറക്കപ്പെട്ടു.","p":1},{"v":12,"t":"നാല്പതു പകലും നാല്പതു രാവും ഭൂമിയിൽ മഴ പെയ്തുകൊണ്ടിരുന്നു.","p":1},{"v":13,"t":"ഈ ദിനം തന്നെ നോഹയും നോഹയുടെ പുത്രന്മാരായ ഷേം, ഹാം, യാഫെത്ത് എന്നിവരും നോഹയുടെ ഭാര്യ, അവൻ്റെ പുത്രന്മാരുടെ മൂന്നു ഭാര്യമാർ എന്നിവരും അവനോടൊപ്പം പെട്ടകത്തിൽ പ്രവേശിച്ചു.","p":1},{"v":14,"t":"അവരും ഇനമനുസരിച്ച് എല്ലാ ജീവികളും എല്ലാ കന്നുകാലികളും ഭൂമിയിൽ ഇഴയുന്ന എല്ലാ ഉരഗങ്ങളും എല്ലാ പക്ഷികളും പറവകളും","p":1},{"v":15,"t":"ജീവശ്വാസമുള്ള എല്ലാ ശരീരികളിൽനിന്നും രണ്ടുവീതം നോഹയുടെ അടുത്ത് പെട്ടകത്തിലേക്ക് വന്നു."},{"v":16,"t":"അവനോട് ദൈവം കൽപ്പിച്ചിരുന്നതുപോലെ സകല ശരീരികളിൽനിന്നും ആണും പെണ്ണുമായി വന്നവയെല്ലാം അകത്തുകടന്നു. അവനെ അകത്താക്കി കർത്താവ് വാതിലടച്ചു."},{"h":"ജലപ്രളയം"},{"v":17,"t":"ഭൂമിയുടെമേൽ നാല്പതുദിവസത്തേക്ക് ജലപ്രളയമുണ്ടായി; ജലം പെരുകി പെട്ടകത്തെ ഉയർത്തി; അത് ഭൂമിക്ക് മുകളിൽ ഉയർന്നു പൊങ്ങി","p":1},{"v":18,"t":"ജലം പ്രബലപ്പെടുകയും ഭൂമിയിൽ ഏറെ പെരുകുകയും ചെയ്തു; പെട്ടകം ജല മുഖത്ത് ചരിച്ചു."},{"v":19,"t":"ജലം ഭൂമിക്ക് മേൽ അത്യധികം പ്രബലപ്പെട്ടു. ആകാശം മുഴുവൻ്റേയും കീഴിലുള്ള എല്ലാ ഉന്നതപർവ്വതങ്ങളും മൂടപ്പെട്ടു","p":1},{"v":20,"t":"പർവതങ്ങൾ മൂടപ്പെടുമാറ് ജലം അവയ്ക്ക് മുകളിൽ പതിനഞ്ചു മുഴം ഉയർന്നു നിന്നു."},{"v":21,"t":"പക്ഷികളിലും കന്നുകാലികളിലും വന്യ മൃഗങ്ങളിലും ഭൂമിയിൽ നിറഞ്ഞിരുന്ന എല്ലാ ജന്തുക്കളിലും പെട്ട എല്ലാ രൂപശരീരികളും ചത്തൊടുങ്ങി. ഒപ്പം, എല്ലാ മനുഷ്യരും.","p":1},{"v":22,"t":"കരയിലുള്ളവയിൽ ജീവചൈതന്യശ്വാസം നാസ രന്ധ്രങ്ങളിലുള്ളവയെല്ലാം ചത്തു.","p":1},{"v":23,"t":"മനുഷ്യൻമുതൽ മൃഗംവരേ, ഇഴന്തുമുതൽ ആകാശപ്രാവരേ ഭൂതലത്തെ സകല ജീവികളെയും അവിടന്നു തുടച്ചുമാറ്റി. അവ ഭൂമിയിൽനിന്നു തുടച്ചുനീക്കപ്പെട്ടപ്പോൾ നോഹയും അവനോടൊപ്പം പെട്ടകത്തി ലുണ്ടായിരുന്നവരും മാത്രം അവശേഷിച്ചു.","p":1},{"v":24,"t":"നൂറ്റമ്പതു ദിവസം വെള്ളപ്പൊക്കം ഭൂമിയിന്മേൽ പ്രബലപ്പെട്ടിരുന്നു","p":1}],"8":[{"h":"ജലപ്രളയം ശമിക്കുന്നു"},{"v":1,"t":"നോഹയെയും അവനോടൊപ്പം പെട്ടകത്തിലുണ്ടായിരുന്ന എല്ലാ ജീവികളെയും കന്നുകാലികളെയും ദൈവം ഓർത്തു. ഭൂമിയിന്മേൽ കാറ്റുവീശാൻ ദൈവം ഇടയാക്കി; ജലം അടങ്ങി.","p":1},{"v":2,"t":"ആഴത്തിന്റെ ഉറവുകളും ആകാശത്തിന്റെ ജാലകങ്ങളും അടഞ്ഞു; ആകാശത്തുനിന്നുള്ള മഴ നിലച്ചു.","p":1},{"v":3,"t":"ഭൂമിയിൽനിന്ന് ജലം പിൻവാങ്ങിക്കൊണ്ടിരുന്നു. നൂറ്റമ്പതു ദിവസം കഴിഞ്ഞപ്പോൾ ജലം കുറഞ്ഞു.","p":1},{"v":4,"t":"ഏഴാംമാസം, മാസത്തിന്റെ പതിനേഴാംദിവസം, പെട്ടകം അറാറാത്തു പർവതനിരയിൽ ഉറച്ചു.","p":1},{"v":5,"t":"പത്തു മാസത്തേക്ക് ജലം കുറഞ്ഞുകൊണ്ടേയിരുന്നു. പത്താംമാസം, മാസത്തിന്റെ ഒന്നാംദിവസം പർവത്യശൃംഗങ്ങൾ കണ്ടുതുടങ്ങി.","p":1},{"v":6,"t":"നാല്പതു ദിവസം കഴിഞ്ഞപ്പോൾ നോഹ പെട്ടകത്തിന് താനുണ്ടാക്കിയിരുന്ന കിളിവാതിൽ തുറന്ന്","p":1},{"v":7,"t":"മലങ്കാക്കയെ പുറത്തേക്കയച്ചു. അത് ഭൂമിയിൽ ജലം വറ്റുവോളം പോയുംവന്നും കൊണ്ടിരുന്നു."},{"v":8,"t":"ഭൂതലത്തിൽ ജലത്തിന്റെ ശക്തി കുറഞ്ഞോ എന്നു കാണാൻ അവൻ പിന്നീട് തന്റെ അടുത്തുനിന്നൊരു പ്രാവിനെ പുറത്തേക്കയച്ചു.","p":1},{"v":9,"t":"ഭൂമുഖത്തെല്ലാം ജലമായതിനാൽ കാലുകുത്താൻ ഇടം കാണാതെ പ്രാവ് അവന്റെനേർക്ക് പെട്ടകത്തിലേക്ക് തിരിച്ചുവന്നു. അവൻ കൈനീട്ടി അതിനെ പിടിച്ച് തന്റെ അടുത്തുചേർത്തു, പെട്ടകത്തിലേക്ക് പ്രവേശിപ്പിച്ചു.","p":1},{"v":10,"t":"ഏഴു ദിവസകൂടി കാത്തിരുന്നിട്ടു അവൻ പ്രാവിനെ വീണ്ടും പെട്ടകത്തിനു പുറത്തേക്കയച്ചു.","p":1},{"v":11,"t":"വൈകുന്നേരമായപ്പോൾ പ്രാവ് അവന്റെയടുക്കലേക്കു വന്നു. ഇതാ, അതിന്റെ ചുണ്ടിൽ ഇപ്പോൾ കൊത്തിയെടുത്തൊരു ഒലിവില! അങ്ങനെ, ഭൂതലത്തിൽ ജലത്തിന്റെ ശക്തി കുറഞ്ഞെന്ന് നോഹ അറിഞ്ഞു.","p":1},{"v":12,"t":"എഴുദിവസകൂടി കാത്തിരുന്നശേഷം അവൻ പ്രാവിനെ വീണ്ടും പുറത്തേക്കയച്ചു. അത് പിന്നീടൊരിക്കലും അവന്റെയടുക്കലേക്ക് തിരിച്ചുവന്നില്ല.","p":1},{"v":13,"t":"അറുനൂറ്റിഒന്നാംവർഷം ഒന്നാംമാസത്തിന്റെആദ്യമാസത്തിൽ ഭൂമിയിലുണ്ടായിരുന്ന ജലം വറ്റിത്തീർന്നു. നോഹ പെട്ടകത്തിന്റെ മേൽക്കൂര നീക്കി. അപ്പോൾ അവൻ കണ്ടു: ഇതാ, ഭൂമുഖം ഉണങ്ങിയിരിക്കുന്നു.!","p":1},{"v":14,"t":"രണ്ടാംമാസം, മാസത്തിന്റെ ഇരുപത്തേഴാംദിവസമാണ് ഭൂമി ഉണങ്ങിയത്.","p":1},{"v":15,"t":"ദൈവം നോഹയോട് ഇപ്രകാരം പറഞ്ഞു:","p":1},{"v":16,"t":"പെട്ടകത്തിൽനിന്നു പുറത്തുവരുക; നീയും നിന്നോടൊപ്പം നിന്റെ ഭാര്യയും നിന്റെ പുത്രന്മാരും നിന്റെ പുത്രന്മാരുടെ ഭാര്യമാരും.","p":1},{"v":17,"t":"പക്ഷികളിലും മൃഗങ്ങളിലും ഭൂമിയിൽ ഇഴയുന്ന എല്ലാ ഇഴയുന്ന എല്ലാ ഉരഗങ്ങളിലും കന്നുകാലികളിലുമായി, എല്ലാ ശരീരങ്ങളിൽനിന്നു നിന്നോടൊപ്പമുള്ള എല്ലാ ജന്തുക്കളെയും പുറത്തുകൊണ്ടുവരുക, അവ ഭൂമിയിൽ തിങ്ങിനിറയട്ടെ! ഭൂതലത്തിൽ അവ പെറ്റുപെരുകട്ടെ!\"","p":1},{"v":18,"t":"നോഹ തന്റെ പുത്രന്മാരോടും തന്റെ ഭാര്യയോടും തന്റെ പുത്രന്മാരുടെ ഭാര്യമാരോടൊത്ത് പുറത്തുവന്നു.","p":1},{"v":19,"t":"എല്ലാ ജീവികളും എല്ലാ ഇഴജന്തുക്കളും എല്ലാ പക്ഷികളും, ഭൂതലത്തിൽ ചലിക്കുന്നവയൊക്കെയും, അവയുടെ വർഗ്ഗമനുസരിച്ച്, പെട്ടകത്തിൽനിന്നു പുറത്തുവന്നു.","p":1},{"h":"നോഹ ബലിയർപ്പിക്കുന്നു"},{"v":20,"t":"നോഹ കർത്താവിന് ഒരു ബലിപീഠം നിർമ്മിച്ചു. ശുചിയുള്ള എല്ലാ മൃഗങ്ങളിലും ശുദ്ധിയുള്ള എല്ലാ പക്ഷികളിലുംനിന്നു അവൻ ബലിപീഠത്തിൽ ഹോമയാഗങ്ങൾഉർപ്പിച്ചു.","p":1},{"v":21,"t":"സുരഭിലപരിമളം അസ്വദിച്ചപ്പോൾ കർത്താവ് ഹൃദയത്തിൽ പറഞ്ഞു: ഇനിയൊരിക്കലും മനുഷ്യനെപ്രതി മണ്ണിനെ ഞാൻ ശപിക്കുകയില്ല കാരണം, ചെറുപ്പംമുതൽ മനുഷ്യന്റെ ഹൃദയഭാവനദുഷിച്ചതാണ്. ഞാൻ ചെയ്തതുപോലെ ഇനിയൊരിക്കലും ജീവജാലമൊന്നടങ്കം ഞാൻ നശിപ്പിക്കുകയില്ല.","p":1},{"v":22,"t":"ഭൂമിയുള്ള കാലത്തോളംവിത്തും കൊയ്ത്തും തണുപ്പും ചൂടുംവേനലും വർഷവും പകലും രാത്രിയും നിലയ്ക്കുകയില്ല.","p":1}],"9":[{"h":"നോഹയുമായി ഉടമ്പടി"},{"v":1,"t":"നോഹയെയും അവന്റെ പുത്രന്മാരെയും അനുഗ്രഹിച്ചുകൊണ്ട് ദൈവം അവരോടു പറഞ്ഞു: “പെറ്റുപെരുകി ഭൂമിയിൽ നിറയുവിൻ.","p":1},{"v":2,"t":"നിങ്ങളെക്കുറിച്ചുള്ള ഭയവും നിങ്ങളെക്കുറിച്ചുള്ള നടുക്കവും ഭൂമിയിലെ എല്ലാ മൃഗങ്ങളുടെയും ആകാശത്തിലെ എല്ലാ പക്ഷികളുടെയും മേലും നിലത്തിലെ എല്ലാ ജന്തുക്കളെയും സമുദ്രത്തിലെ എല്ലാ മത്സ്യങ്ങളിലും ഉണ്ടായിരിക്കും; അവ നിങ്ങളുടെ കയ്യിൽ ഏൽപ്പിക്കപ്പെട്ടിരിക്കുന്നു.","p":1},{"v":3,"t":"ചരിക്കുന്ന ഓരോ ജീവിയും നിങ്ങൾക്ക് ആഹാരമായിരിക്കട്ടെ. ഹരിതസസ്യങ്ങളെപ്പോലെ ഇവയെല്ലാം നിങ്ങൾക്ക് ഞാൻ തരുന്നു.","p":1},{"v":4,"t":"എന്നാൽ മാംസം അതിന്റെ ജീവനോടുകൂടെ, രക്തത്തോടുകൂടെ, നിങ്ങൾ ഭക്ഷിക്കരുത്.","p":1},{"v":5,"t":"തീർച്ചയായും നിങ്ങളുടെ ജീവനുവേണ്ടി നിങ്ങളുടെ രക്തം ഞാൻ ആവശ്യപ്പെടും; ഓരോ ജീവിയുടെയും കയ്യിൽനിന്നും അതു ഞാൻ ആവശ്യപ്പെടും; മനുഷ്യന്റെ കയ്യിൽനിന്നും, അവന്റെ സഹോദരന്റെ കയ്യിൽനിന്നും, മനുഷ്യജീവൻ ഞാൻ ആവശ്യപ്പെടും.","p":1},{"v":6,"t":"മനുഷ്യന്റെ രക്തം ചിന്തുന്നവന്റെ രക്തം മനുഷ്യനാൽ ചിന്തപ്പെടും. എന്തെന്നാൽ ദൈവത്തിന്റെ ഛായയിലാണല്ലോ അവിടന്ന് അവനെ മെനഞ്ഞത്.","p":1},{"v":7,"t":"നിങ്ങൾ പെറ്റുപെരുകുവിൻ, ഭൂമിയിൽ നിറയുവിൻ, അവളിൽ നിങ്ങൾ പെരുകുവിൻ!","p":1},{"v":8,"t":"നോഹയോടും അവനോടുകൂടെയുണ്ടായിരുന്ന പുത്രന്മാരോടും ദൈവം ഇപ്രകാരം അരുളിച്ചെയ്തു:","p":1},{"v":9,"t":"“ഞാനിതാ, നിങ്ങളുമായും നിങ്ങൾക്കുശേഷമുള്ള നിങ്ങളുടെ സന്തതികളുമായും എന്റെ ഉടമ്പടി സ്ഥാപിക്കുന്നു;"},{"v":10,"t":"പെട്ടകത്തിൽനിന്നു പുറത്തുവന്നവ തുടങ്ങി ഭൂമിയിലെ സകലജന്തുക്കളുമായും - നിങ്ങളോടൊത്തുള്ള സകല ജീവജാലവുമായും പക്ഷിജാലത്തിലും മൃഗഗണത്തിലും സകല ഭൗമജീവിയിലും നിങ്ങളോടുകൂടെയുള്ളവയുമായും","p":1},{"v":11,"t":"നിങ്ങളുമായും ഞാൻ എന്റെ ഉടമ്പടി സ്ഥാപിക്കുന്നു: ഇനിയൊരിക്കലും ജലപ്രളയത്താൽ ശരീരികളാകമാനം നശിപ്പിക്കപ്പെടുകയില്ല. ഭൂമിയെ നശിപ്പിക്കും വിധം ഇനിയൊരു പ്രളയമുണ്ടാവുകയില്ല."},{"v":12,"t":"അനന്തരം ദൈവം പറഞ്ഞു: ഞാനും നിങ്ങളും തമ്മിലും നിങ്ങളോടൊപ്പമുള്ള എല്ലാ ജീവജാലങ്ങളും തമ്മിലും, തലമുറകളോളം ശാശ്വതമായി, ഞാൻ ഉറപ്പിക്കുന്ന ഉടമ്പടിയുടെ അടയാളം ഇതായിരിക്കും","p":1},{"v":13,"t":"ഞാൻ മേഘത്തിൽ എന്റെ വില്ല് വയ്ക്കുന്നു. അത് ഞാനും ഭൂമിയും തമ്മിലുള്ള ഉടമ്പടിയുടെ അടയാളമായിരിക്കും."},{"v":14,"t":"ഞാൻ ഭൂമി മേഘാവൃതമാക്കുകയും വില്ല് മേഘത്തിൽ പ്രത്യക്ഷമാവുകയും ചെയ്യുമ്പോൾ,"},{"v":15,"t":"നിങ്ങളുമായും സകല ശരീരിയിലുംപെട്ട ഓരോ ജീവജാലവുമായുമുള്ള എന്റെ ഉടമ്പടി ഞാൻ അനുസ്മരിക്കും; ശരീരികളെ ഒന്നാകെ നശിപ്പിക്കുവിൻ ഇനിയൊരിക്കലും ജലം ഒരു പ്രളയമായിത്തീരുകയില്ല."},{"v":16,"t":"വില്ല് മേഘത്തിൽ പ്രത്യക്ഷപ്പെടുമ്പോൾ, ദൈവവും ഭൂമിയിലെ സകല ശരീരിയിലുംപെട്ട ഓരോ ജീവജാലവും തമ്മിലുള്ള ശാശ്വതമായ ഉടമ്പടി ഓർമ്മിക്കാൻവേണ്ടി ഞാൻ അതു നോക്കിക്കാണും."},{"v":17,"t":"ദൈവം നോഹയോട് അരുളിച്ചെയ്തു: ഇത് ഞാനും ഭൂമിയിലെ ഓരോ ശരീരിയും തമ്മിൽ ഞാൻ സ്ഥാപിക്കുന്ന ഉടമ്പടിയുടെ അടയാളമായിരിക്കും.","p":1},{"h":"നോഹയുടെ പുത്രന്മാർ"},{"v":18,"t":"ഷേം, ഹാം, യാഫെത്ത് എന്നിവരാണ് പെട്ടകത്തിൽനിന്നു പുറത്തിറങ്ങിയ നോഹയുടെ പുത്രന്മാർ. ഹാം ആണ് കാനാൻ്റെ പിതാവ്.","p":1},{"v":19,"t":"ഇവരാകുന്നു നോഹയുടെ മൂന്നു പുത്രന്മാർ; ഇവരെക്കൊണ്ടാണ് ഭൂമി മുഴുവൻ നിറഞ്ഞത്.","p":1},{"v":20,"t":"കർഷകവൃത്തി ആരംഭിച്ച്, നോഹ ഒരു മുന്തിരിത്തോട്ടം നട്ടുപിടിപ്പിച്ചു.","p":1},{"v":21,"t":"വീഞ്ഞുകുടിച്ചു ഉന്മത്തനായി അവൻ തന്റെ കൂടാരത്തിന്റെ നടുവിൽ വിവസ്ത്രനായി കിടന്നു."},{"v":22,"t":"കാനാൻ്റെ പിതാവായ ഹാം തന്റെ പിതാവിന്റെ നഗ്നത കാണുകയും പുറത്തുണ്ടായിരുന്ന തന്റെ രണ്ടു സഹോദരന്മാരോട് പറയുകയും ചെയ്തു.","p":1},{"v":23,"t":"ഷേമും യാഫെത്തും മേല് വസ്ത്രമെടുത്തു തങ്ങളിരുവരുടെയും തോളിലിട്ട്, പിറകോട്ടു നടന്നുചെന്ന് സ്വപിതാവിന്റെ നഗ്നത മറച്ചു. മുഖം പിറകോട്ടു തിരിച്ചുരുന്നതിനാൽ തങ്ങളുടെ പിതാവിന്റെ നഗ്നത അവർ കണ്ടില്ല.","p":1},{"v":24,"t":"ലഹരിവിട്ടു ഉണർന്ന നോഹ തന്റെ ഇളയമകൻ തന്നോട് ചെയ്തതെന്തെന്ന് അറിഞ്ഞു."},{"v":25,"t":"അപ്പോൾ അവൻ പറഞ്ഞു: കാനാൻ ശപിക്കപ്പെട്ടവൻ! അവൻ തന്റെ സഹോദരങ്ങൾക്ക് അടിമകളുടെ അടിമയാകും."},{"v":26,"t":"തുടർന്ന് അവൻ പറഞ്ഞു: ശേമിന്റെ ദൈവമായ കർത്താവ് വാഴ്ത്തപ്പെട്ടവൻ! കാനാൻ അവന് അടിമയാകട്ടെ!","p":1},{"v":27,"t":"ദൈവം യാഫെത്തിനെ വിപുലമാക്കട്ടെ! അവൻ ഷേമിന്റെ കൂടാരങ്ങളിൽ പാർക്കട്ടെ! കാനാൻ അവരുടെ അടിമയാകട്ടെ!","p":1},{"v":28,"t":"പ്രളയത്തിനുശേഷം നോഹ മുന്നൂറ്റിമുപ്പതു വർഷം ജീവിച്ചു.","p":1},{"v":29,"t":"നോഹയുടെ ആകെ ജീവിതായുസ്സ് തൊള്ളായിരത്തമ്പതു വർഷമായിരുന്നു. അവൻ മരിച്ചു","p":1}],"10":[{"h":"ജനതകളുടെ ഉത്ഭവം"},{"v":1,"t":"നോഹയുടെ പുത്രന്മാരായ ഷേമിന്റെയുംഹാമിന്റെയും യാഫെത്തിന്റെയും തലമുറകൾ - പ്രളയശേഷം അവർ ജന്മംകൊടുത്ത മക്കൾ - ഇവയാണ്.","p":1},{"v":2,"t":"യാഫെത്തിന്റെ മക്കൾ ഗോമെർ, മാഗോഗ്, മാദായ്, യാവാൻ, തുബാൽ, മെഷെക്, തീരാസ്.","p":1},{"v":3,"t":"ഗോമെറിന്റെ മക്കൾ: അഷ്കെനാസ്, റീഫത്ത്, തോഗർമ.","p":1},{"v":4,"t":"യാവാന്റെ മക്കൾ: എലീശാ, തർഷീശ്, കിത്തിം, ദോദാനിം.","p":1},{"v":5,"t":"ഇവരിൽനിന്നാണ് ജനതകൾ അവരുടെ ദേശങ്ങളിൽ ഓരോന്നിന്റെയും ഭാഷയനുസരിച്ച് അവരുടെ ജനതകളിൽ താന്തങ്ങളുടെ വംശമനുസരിച്ചും വിന്യസിക്കപ്പെട്ടത്.","p":1},{"v":6,"t":"ഹാമിന്റെ മക്കൾ: കൂശ്, മിസ്രയിം, ഫുത്ത്, കാനാൻ എന്നിവർ.","p":1},{"v":7,"t":"കുഷിന്റെ മക്കൾ: സേബാ, ഹവീലാ, സബത്താ, റാമാ, സബ്ത്തേക്കാ റാമായുടെ മക്കളാണ് ഷെബായും ദെദാനും.","p":1},{"v":8,"t":"കൂശ് നിമ്രോദിനെ ജനിപ്പിച്ചു. അവൻ ഭൂമിയിൽ ഒരു വീരപുരുഷനാകാൻ തുടങ്ങി.","p":1},{"v":9,"t":"അവൻ കർത്താവിൻമുമ്പിൽ ഒരു നായാട്ടുവിരനായിരുന്നു. അതുകൊണ്ട്, കർത്താവിൻമുമ്പിൽ നിമ്രോദിനെപ്പോലൊരു നായാട്ടുവിരൻ എന്ന ചൊല്ലുണ്ടായി.","p":1},{"v":10,"t":"അവന്റെ രാജ്യത്തിന്റെ ആരംഭം ഷീനാർദേശത്തെ ബാബേൽ, ഏറെക്, അക്കാദ്, കൽനെഎന്നിവയായിരുന്നു.","p":1},{"v":11,"t":"അവൻ ആ നാട്ടിൽനിന്ന് അഷൂറിലേക്ക് പുറപ്പെട്ട് നിനെവേ, രെഹോബോത്ത് ഈർ, കാലാഹ് എന്നിവ പണികഴിപ്പിച്ചു;","p":1},{"v":12,"t":"ഒപ്പം നിനെവേക്കും കാലാഹിനുമിടയിൽ റേസൻ എന്ന മഹാനഗരവും.","p":1},{"v":13,"t":"മിസ്രയിം ജന്മംകൊടുത്തതാണ്ലൂദീം, അനാമീം, ലഹാബീം, നഫ്തൂഹീം,","p":1},{"v":14,"t":"പത്രൂസീം, ഫിലിസ്ത്യർ പുറപ്പെട്ടുപോന്ന കസ്ലൂഹീം, കഫ്തോറിം എന്നിവ."},{"v":15,"t":"കാനാൻ ജന്മംനല്കിയത് തന്റെ കടിഞ്ഞൂലായസീദോനും ഹേത്ത്,","p":1},{"v":16,"t":"ജബൂസ്യർ, അമോര്യർ, ഗിർഗാഷ്യർ,"},{"v":17,"t":"ഹിവ്യർ, അർക്കീയർ, സീന്യർ,"},{"v":18,"t":"അർവാദിയർ, സെമറീയർ, ഹമാത്യർ എന്നിവർക്കുമായിരുന്നു. പില്ക്കാലത്ത് കാനാൻകാരുടെ വംശങ്ങൾ പലയിടത്തും വ്യാപിച്ചു."},{"v":19,"t":"കാനാൻകാരുടെ ദേശാതിർത്തി, സീദോൻ തുടങ്ങി ഗെരാറിലേക്കുള്ള ദിശയിൽ ഗാസ വരെയും സൊദോം-ഗൊമോറ-അദ്മാ ദിശയിൽ സെബോയിം തുടങ്ങി ലാശാ വരെയും ആണ്.","p":1},{"v":20,"t":"ഇവരാണ് തങ്ങളുടെ ദേശങ്ങളിലും ജനതകളിലും വംശവും ഭാഷയുമനുസരിച്ച് ഹാമിന്റെ മക്കൾ.","p":1},{"v":21,"t":"ഷേമിനും മക്കളുണ്ടായി; അവൻ ഹെബ്രായരുടെയെല്ലാം പിതാവും യാഫെത്തിന്റെ മൂത്ത സഹോദരനുമായിരുന്നു.","p":1},{"v":22,"t":"ശേമിന്റെ മക്കൾ ഏലാം, അഷൂർ, അർപ്പക്ഷാദ്, ലൂദ്, ആരാം എന്നിവരും","p":1},{"v":23,"t":"ആരാമിന്റെ മക്കൾ ഊസ്, ഹൂൽ, ഗെതർ, മാഷ് എന്നിവരുമായിരുന്നു."},{"v":24,"t":"അർപ്പക്ഷാദ് ഷേലാഹിനും ഷേലാഹ് എബറിനും ജന്മംകൊടുത്തു.","p":1},{"v":25,"t":"എബറിന് രണ്ടു പുത്രന്മാർ ജനിച്ചു: ഒന്നാമത്തെ പേര് പേലെഗ്. കാരണം, അവന്റെ കാലത്താണ് ഭൂമി വിഭജിതമായത്. അവന്റെ സഹോദരന്റെ പേര് യോക്താൻ.","p":1},{"v":26,"t":"അവൻ അൽമോദാദ്, ശെലെഫ്, ഹസർവേത്ത്, യാറഹ്,","p":1},{"v":27,"t":"ഹദോറാം, ഊസാൽ, ദിക്ലാ,"},{"v":28,"t":"ഒബാൽ, അബിമായേൽ, ഷെബാ,"},{"v":29,"t":"ഓഫീർ, ഹവീലാ, യോബാബ് എന്നിവർക്ക് ജന്മംകൊടുത്തു. ഇവരൊക്കെയായിരുന്നു യോക്താ ന്റെ മക്കൾ."},{"v":30,"t":"അവർ പാർത്തിരുന്ന നാട്, മേഷാ തുടങ്ങി കിഴക്കൻ മലയായ സെഫാറിന്റെ ദിശയിലായിരുന്നു.","p":1},{"v":31,"t":"ഇവരാണ് തങ്ങളുടെ ദേശങ്ങളിലും ജനതകളിലും വംശവും ഭാഷയും അനുസരിച്ച് ഷേമിന്റെ മക്കൾ.","p":1},{"v":32,"t":"ഇവയാണ് തങ്ങളുടെ ഉത്പത്തിയനുസരിച്ച് ജനതകളിൽ നോഹയുടെ മക്കളുടെ വംശങ്ങൾ ഇവരിൽ നിന്നാണ് പ്രളയത്തിനുശേഷം ജനതകൾ ഭൂമിയിൽ വേർതിരിഞ്ഞത്","p":1}],"11":[{"h":"ബാബേൽഗോപുരം"},{"v":1,"t":"1 ഭൂമിമുഴുവനും ഒരേ ഭാഷയും ഒരേ പദാവലിയും ആയിരുന്നു.","p":1},{"v":2,"t":"അക്കാലത്ത് കിഴക്കുനിന്നു പുറ പ്പെട്ടവർ ഷീനാർദേശത്ത് ഒരു സമതലം കണ്ടെത്തി അവിടെ പാർപ്പുറപ്പിച്ചു.","p":1},{"v":3,"t":"അവർ പരസ്പരം പറഞ്ഞു: വരുവിൻ, നമുക്ക് ഇഷ്ടികയുണ്ടാക്കി തീയിൽചുട്ടെടുക്കാം. അങ്ങനെ അവർക്ക് ഇഷ്ടിക കല്ലിനുപകരവും കീല് കുമ്മായത്തിനു പകരവുമായി.","p":1},{"v":4,"t":"അവർ തുടർന്നുപറഞ്ഞു: വരുവിൻ, നമുക്ക് ഒരു പട്ടണവുംആകാശമുട്ടുന്ന ഒരു ഗോപുരവും പണിത് നമുക്കായി പേരു സമ്പാദിക്കാം. അതല്ലെങ്കിൽ, നാം ഭൂമുഖത്താകെത്താകെ ചിതറിപ്പോകും.","p":1},{"v":5,"t":"മനുഷ്യമക്കൾ നിർമ്മിച്ച നഗരവും ഗോപുരവും കാണാൻ കർത്താവു ഇറങ്ങിവന്നു.","p":1},{"v":6,"t":"കർത്താവു പറഞ്ഞു: നോക്കൂ, ഒരു ജനതയും അവർക്കെല്ലാം ഒറ്റ ഭാഷയും! ഇത് അവർ ചെയ്യാനിരിക്കുന്നതിന്റെ തുടക്കംമാത്രം. ചെയ്യാൻ ഉദ്യമിക്കുന്നതൊന്നും അവർക്കിനി അസാദ്ധ്യമായിരിക്കയില്ല.","p":1},{"v":7,"t":"വരുവീൻ, നമുക്ക് ഇറങ്ങിച്ചെന്ന് അവിടെവച്ച് അവരുടെ ഭാഷ പരസ്പരം ഗ്രഹിക്കാനാവാത്തവിധം കുഴച്ചുമറിക്കാം.","p":1},{"v":8,"t":"അങ്ങനെ കർത്താവു അവരെ അവിടെനിന്ന് ഭൂമുഖത്തെങ്ങും ചിതറിച്ചു. അതോടെ അവർ പട്ടണം പണിയുന്നത് ഉപേക്ഷിച്ചു.","p":1},{"v":9,"t":"ഭൂമിയിലാകെയുള്ള ഭാഷ കർത്താവു അവിടെവച്ച് കുഴച്ചുമറിച്ചതുകൊണ്ടാണ് ആ സ്ഥലത്തിന് ബാബേൽ എന്നു പേരുണ്ടായത്. അവിടെനിന്നാണ് കർത്താവു അവരെ ഭൂമുഖത്താകെ ചിതറിച്ചത്.","p":1},{"h":"ഷേം മുതൽ അബ്രാഹം വരെ"},{"v":10,"t":"ഇതാണ് ഷേമിന്റെ വംശാവലി: ഷേമിന് നൂറു വയസ്സായപ്പോൾ, പ്രളയത്തിനുശേഷം രണ്ടാം വർഷം അവൻ അർപ്പക്ഷാദിനെ ജനിപ്പിച്ചു.","p":1},{"v":11,"t":"അർപ്പക്ഷാദിന്റെ ജനനത്തിനുശേഷം അഞ്ഞൂറുവർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":12,"t":"മുപ്പത്തഞ്ചു വയസ്സായപ്പോൾ അർപ്പക്ഷാദ് ശേലാഹിനെ ജനിപ്പിച്ചു.","p":1},{"v":13,"t":"ശേലാഹിന്റെ ജനനത്തിനുശേഷം അർപ്പക്ഷാദ് നാനൂറ്റിമൂന്നു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":14,"t":"മുപ്പതുവയസ്സായപ്പോൾ എബർ ഷേലാഹിനെ ജനിപ്പിച്ചു.","p":1},{"v":15,"t":"എബറിന്റെ ജനനത്തിനുശേഷം നാനൂറ്റി മൂന്നുവർഷം ഷേലാഹ് ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു."},{"v":16,"t":"മുപ്പത്തിനാലു വയസ്സായപ്പോൾ ഏബർ പേലേഗിനെ ജനിപ്പിച്ചു.","p":1},{"v":17,"t":"പേലേഗിന്റെ ജനനത്തിനുശേഷം ഏബർ നാനൂറ്റിമുപ്പതുവർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":18,"t":"മുപ്പതുവയസ്സായപ്പോൾ പേലേഗ് റെവൂവിനെ ജനിപ്പിച്ചു.","p":1},{"v":19,"t":"റെവൂവിന്റെ ജനനത്തിനുശേഷം പേലേഗ് ഇരുനൂറ്റൊമ്പതുവർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":20,"t":"മുപ്പത്തിരണ്ടു വയസ്സായപ്പോൾ റെവൂ സെരൂഗിനെ ജനിപ്പിച്ചു.","p":1},{"v":21,"t":"സെരൂഗിന്റെ ജനനത്തിനുശേഷം റെവൂ ഇരുനൂറ്റേഴുവർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":22,"t":"മുപ്പതുവയസ്സായപ്പോൾ സെരൂഗ് നാഹോറിനെ ജനിപ്പിച്ചു.","p":1},{"v":23,"t":"നാഹോറിന്റെ ജനനത്തിനുശേഷം സെരൂഗ് ഇരുനൂറു വർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":24,"t":"ഇരുപത്തൊമ്പതു വയസ്സായപ്പോൾ നാഹോർ തെരാഹിനെ ജനിപ്പിച്ചു.","p":1},{"v":25,"t":"തെരാഹിന്റെ ജനനത്തിനുശേഷം നാഹോർ നൂറ്റിപ്പത്തൊമ്പതുവർഷം ജീവിച്ചു. അവൻ പുത്രന്മാരെയും പുത്രിമാരെയും ജനിപ്പിച്ചു.","p":1},{"v":26,"t":"എഴുപതുവയസ്സായപ്പോൾ തെരാഹ് അബ്രാമിനെയും നാഹോറിനെയും ഹാരാനെയും ജനിപ്പിച്ചു.","p":1},{"v":27,"t":"ഇവയാണ് തെരാഹിന്റെ വംശാവലി: തെരാഹ് അബ്രാമിനും നാഹോറിനും ഹാരാനും ജന്മംനല്കി. ഹാരാൻ ലോത്തിന് ജന്മംനല്കി.","p":1},{"v":28,"t":"ഹാരാൻ തന്റെ പിതാവായ തെരാഹിനുമുമ്പേ ജന്മനാടായ കല്ദായരുടെ ഊറിൽവച്ച് ചരമമടഞ്ഞു.","p":1},{"v":29,"t":"അബ്രാമും നാഹോറും തങ്ങൾക്കായി ഭാര്യമാരെ സ്വീകരിച്ചു. അബ്രാമിന്റെ ഭാര്യയുടെ പേര് സാറായി. നാഹോറിന്റെ ഭാര്യയുടെ പേര് മിൽക്ക; അവൾ ഹാരാന്റെ മകളായിരുന്നു. ഹാരാൻ മിൽക്കയുടെയും ഇസ്കായുടെയും പിതാവായിരുന്നു.","p":1},{"v":30,"t":"സാറായി വന്ധ്യയായിരുന്നു. അവൾക്ക് മക്കളുണ്ടായിരുന്നില്ല.","p":1},{"v":31,"t":"തെരാഹ് തന്റെ മകൻ അബ്രാമിനെയും പേരക്കിടാവും ഹാരാന്റെ മകനുമായ ലോത്തിനെയും അബ്രാമിന്റെ ഭാര്യയും തന്റെ മരുമകളുമായ സാറായിയെയുംകൂട്ടി അവരോടുകൂടെ കല്ദായരുടെ ഊരിൽനിന്ന് കാനാൻദേശത്തേക്ക് കാലനടയായി പുറപ്പെട്ട് ഹാരാൻവരെയെത്തി. അവിടെ അവർ വാസമുറപ്പിച്ചു.","p":1},{"v":32,"t":"തെരാഹിന്റെ ആയുസ്സ് ഇരുനൂറ്റഞ്ചുവർഷം ആയിരുന്നു. അവൻ ഹാരാനിൽവച്ച് മൃതിയടഞ്ഞു.","p":1}],"12":[{"h":"അബ്രാമിനെ വിളിക്കുന്നു"},{"v":1,"t":"കർത്താവു അബ്രാമിനോട് അരുളിച്ചെയ്തു: \"നിന്റെ ദേശത്തുനിന്നും സ്വജനത്തിൽനിന്നും പിതൃഭവനത്തിൽനിന്നും ഞാൻ കാണിച്ചുതരുന്ന നാട്ടിലേക്ക് പോവുക.","p":1},{"v":2,"t":"ഞാൻ നിന്നെ വലിയൊരു ജനതയാക്കും. നിന്നെ ഞാൻ അനുഗ്രഹിക്കും. നിന്റെ പേര് ഞാൻ ശ്രേഷ്ഠമാക്കും. അങ്ങനെ നീ ഒരനുഗ്രഹമായിരിക്കും.","p":1},{"v":3,"t":"നിന്നെ അനുഗ്രഹിക്കുന്നവനെ ഞാൻ അനുഗ്രഹിക്കും. നിന്നെ ശപിക്കുന്നവനെ ഞാൻ ശപിക്കും. നിന്നിലൂടെ ഭൂമിയിലെ വംശങ്ങളെല്ലാം അനുഗ്രഹീതമാകും.\"","p":1},{"v":4,"t":"കർത്താവു തന്നോട് പറഞ്ഞതന്നനുസരിച്ച് അബ്രാം പോയി. ലോത്തും അവനോടൊപ്പം പോയി. ഹാരോണിൽനിന്നു പുറപ്പെടുമ്പോൾ","p":1},{"v":5,"t":"അബ്രാം എഴുപത്തഞ്ചു വയസ്സു പ്രായമായിരുന്നു. അബ്രാം ഭാര്യ സാറായിയെയും സഹോദരപുത്രൻ ലോത്തിനെയും തങ്ങൾ നേടിയ മുഴുവൻ സമ്പത്തും ഹാരോൺ ദേശത്ത് തങ്ങൾ സംഘടിപ്പിച്ച ആളുകളെയും കൂടെക്കൂട്ടി. അനന്തരം കാനാൻ ദേശത്തേക്ക് പോകാൻ അവർ യാത്രയായി. അങ്ങനെ അവർ കാനാൻ ദേശത്തു വന്നുചേർന്നു."},{"v":6,"t":"അബ്രാം ആ നാട്ടിലൂടെ സഞ്ചരിച്ച് ഷെക്കെം പ്രദേശംവരെ, മോറെയിലെ ഓക്കുമരംവരെ എത്തി.അക്കാലത്ത് ആ ദേശത്തുണ്ടായിരുന്നത് കാനാൻകാരാണ്.","p":1},{"v":7,"t":"കർത്താവ് അബ്രാമിന് പ്രത്യക്ഷപ്പെട്ട് അരുളിച്ചെയ്തു: ഈ നാട് നിന്റെ സന്തതിക്കു ഞാൻ കൊടുക്കും. തനിക്ക് പ്രത്യക്ഷപ്പെട്ട കർത്താവിന് അവൻ അവിടെ ഒരു ബലിപീഠം പണിതു.","p":1},{"v":8,"t":"അവിടെനിന്ന് അവൻ ബേഥേലിനു കിഴക്കുള്ള മലയിലേക്കു നീങ്ങി ബേഥേലിനു കിഴക്കുംംആയിക്കു പടിഞ്ഞാറുമായി കൂടാരമടിച്ചു. അവിടെ കർത്താവിന് ഒരു ബലിപീഠം പണിത്, അവൻ കർത്താവിന്റെ നാമം വിളിച്ചപേക്ഷിച്ചു.","p":1},{"v":9,"t":"അവിടെനിന്ന് അബ്രാം നെഗെബിലേക്കു നേരെ പടിപടിയായി യാത്ര ചെയ്തു.","p":1},{"h":"അബ്രാം ഈജിപ്തിൽ"},{"v":10,"t":"ആ നാട്ടിൽ ഒരു ക്ഷാമം ഉണ്ടായി. അവിടെ കടുത്ത ക്ഷാമമായിരുന്നതിനാൽ അബ്രാം തത്കാലവാസത്തിന് ഈജിപ്തിലേക്ക് ഇറങ്ങിത്തിരിച്ചു.","p":1},{"v":11,"t":"ഈജിപ്തിനെ സമീപിച്ച്, അതിൽ പ്രവേശിക്കാറായപ്പോൾ അവൻ ഭാര്യ സാറായിയോടു പറഞ്ഞു: ഇതാ, നീ കാണാൻ അഴകുള്ള സ്ത്രീയാണെന്ന് എനിക്കറിയാം.","p":1},{"v":12,"t":"ഈജിപ്തുകാർ നിന്നെ കാണുന്ന മാത്രയിൽ, ഇവൾ അവന്റെ ഭാര്യയാണ് എന്നു പറഞ്ഞ് എന്നെ കൊന്നിട്ടു നിന്നെ ജീവിക്കാൻ അനുവദിക്കും.","p":1},{"v":13,"t":"നീ മൂലം എനിക്ക് നല്ലത് സംഭവിക്കേണ്ടതിന് നീ എന്റെ സഹോദരിയാണെന്നു തന്നെ പറയണം. അങ്ങനെ നീ മൂലം എന്റെ പ്രാണൻ നിലനില്ക്കും.","p":1},{"v":14,"t":"അബ്രാം ഈജിപ്തിൽ പ്രവേശിച്ചപ്പോൾ ഈജിപ്തുകാർ ആ സ്ത്രീയെ ശ്രദ്ധിച്ചു കാരണം, അവൾ അതീവസുന്ദരിയായിരുന്നു."},{"v":15,"t":"ഫറവോയുടെ പ്രഭുക്കന്മാർ അവളെ കാണുകയും അവളെക്കുറിച്ച് ഫറവോയോടു വർണ്ണിച്ചുപറയുകയും ചെയ്തു. ആ സ്ത്രീ ഫറവോയുടെ ഭവനത്തിലേക്ക് സ്വീകരിക്കപ്പെട്ടു.","p":1},{"v":16,"t":"അയാൾ അവളെപ്രതി അബ്രാമിനോട് നന്നായി പെരുമാറി. അങ്ങനെ അവന് ആടുമാടുകളും ആൺകഴുതകളും ദാസന്മാരും പരിചാരികമാരും പെൺകഴുതകളും ഒട്ടകങ്ങളും ലഭിച്ചു.","p":1},{"v":17,"t":"പക്ഷെ, കർത്താവ് അബ്രാമിന്റെ ഭാര്യ സാറായിയെ പ്രതി ഫറവോയെയും കുടുംബത്തെയും മഹാബാധകളാൽ പ്രഹരിച്ചു.","p":1},{"v":18,"t":"ഫറവോ അബ്രാമിനെ വിളിച്ചു പറഞ്ഞു: നീ എന്നോട് എന്താണീ ചെയ്തത്? അവൾ നിന്റെ ഭാര്യയാണെന്ന് എന്തുകൊണ്ട് എന്നോടു പറഞ്ഞില്ല?","p":1},{"v":19,"t":"ഞാനവളെ എന്റെ ഭാര്യയാക്കത്തക്കവിധം നീ എന്തിനാണ്, അവൾ എന്റെ സഹോദരിയാണ് എന്നു പറഞ്ഞത്? ഇപ്പോൾ ഇതാ, നിന്റെ ഭാര്യ; അവളെയുംകൊണ്ടു സ്ഥലവിടുക.","p":1},{"v":20,"t":"ഫറവോ അവനെക്കുറിച്ച് ആളുകൾക്കു കല്പനകൊടുത്തു. അവർ അവനെയും ഭാര്യയെയും അവനു സ്വന്തമായുണ്ടായിരുന്ന സകലത്തോടും കൂടെ പറഞ്ഞയച്ചു","p":1}],"13":[{"h":"അബ്രാം തിരികെ ബേഥേലിൽ"},{"v":1,"t":"അബ്രാം ഭാര്യയോടും സ്വന്തമായ സകലത്തോടും കൂടെ ഈജിപ്തിൽനിന്ന് നെഗെബിലേക്കു കയറിപ്പോയി ലോത്തും അവനോടുകൂടെയുണ്ടായിരുന്നു.","p":1},{"v":2,"t":"കന്നുകാലികൾ, വെള്ളി, സ്വർണ്ണം എന്നിവയാൽ അബ്രാം ഏറെ സമ്പന്നനായിരുന്നു."},{"v":3,"t":"അവൻ നെഗെബിൽനിന്നു യാത്രചെയ്ത് ബേഥേൽ വരെയും ബേഥേലിനും ആയിക്കുമിടയ്ക്ക്, മുമ്പ് തന്റെ കൂടാരം ഉണ്ടായിരുന്നതും മുമ്പ് ബലിപീഠം പണിതതുമായ സ്ഥലംവരെയുമെത്തിച്ചേർന്നു."},{"v":4,"t":"അവിടെ അബ്രാം കർത്താവിന്റെ നാമം വിളിച്ചപേക്ഷിച്ചു."},{"h":"അബ്രാമും ലോത്തും വഴിപിരിയുന്നു"},{"v":5,"t":"അബ്രാമിനോടൊപ്പം സഞ്ചരിച്ചിരുന്ന ലോത്തിനും ആടുമാടുകളും കൂടാരങ്ങളുമുണ്ടായിരുന്നു.","p":1},{"v":6,"t":"അവർക്ക് ഒന്നിച്ചുതാമസിക്കാൻ ആ ദേശം മതിയായില്ല. കാരണം, അവരുടെ കാലിസമ്പത്ത് ഏറെയായിരുന്നു. അവർ ഒന്നിച്ചുപാർക്കുകയെന്നത് അസാധ്യമായിരുന്നു.","p":1},{"v":7,"t":"മാത്രമല്ല, അബ്രാമിന്റെ കാലിമേയ്ക്കുന്നവരും ലോത്തിന്റെ കാലിമേയ്ക്കുന്നവരും തമ്മിൽ കലഹവുമുണ്ടായി. അക്കാലത്ത് കാനാന്യരും പെരിസ്യരും അന്നാട്ടിൽ പാർത്തിരുന്നു.","p":1},{"v":8,"t":"അബ്രാം ലോത്തിനോടു പറഞ്ഞു: ഞാനും നീയും തമ്മിലും എന്റെ ഇടയന്മാരും നിന്റെ ഇടയന്മാരും തമ്മിലും ഒരിക്കലും കലഹമുണ്ടാകാതിരിക്കട്ടെ. കാരണം, നമ്മൾ സഹോദരന്മാരാണ്."},{"v":9,"t":"ദേശമെല്ലാം നിന്റെ കണ്മുമ്പിലില്ലേ? നിനക്ക് എന്നെ വിട്ടുപോകാം. നീ ഇടത്തേക്കെങ്കിൽ ഞാൻ വലത്തേക്കു പോയിക്കൊള്ളാം; നീ വലത്തേക്കെങ്കിൽ ഞാൻ ഇടത്തേക്കു പോയിക്കൊള്ളാം."},{"v":10,"t":"ലോത്ത് കണ്ണുകളുയർത്തി ജോർദ്ദാൻസമതലം അപ്പാടെ കണ്ടു. കർത്താവ് സോദോമുംഗൊമോറയും നശിപ്പിക്കുന്നതിനുമുമ്പ് അതു മുഴുവൻ കർത്താവിന്റെ തോട്ടംപോലെയും ഈജിപ്തുദേശം പോലെയും നീരോട്ടമുള്ള പ്രദേശമായിരുന്നു. അത് സോവാരിലേക്കുള്ള ദിശയിലാണ്.","p":1},{"v":11,"t":"ജോർദ്ദാൻസമതലം മുഴുവൻ ലോത്ത് തനിക്കുവേണ്ടി തിരഞ്ഞെടുത്തു. അവൻ കിഴക്കോട്ടു യാത്രതിരിച്ചു. അങ്ങനെ അവർ തമ്മിൽ പിരിഞ്ഞു.","p":1},{"v":12,"t":"അബ്രാം കാനാൻദേശത്തു താമസമാക്കി. ലോത്ത് സമതലത്തിലെ നഗരങ്ങളിൽ പാർത്തു.","p":1},{"v":13,"t":"സോദോമിലെ ആളുകൾ കർത്താവിന്റെ മുമ്പിൽ കൊടിയ ദുഷ്ടരും പാപികളുമായിരുന്നു.","p":1},{"v":14,"t":"ലോത്ത് അവനിൽനിന്ന് വേർപിരിഞ്ഞശേഷം കർത്താവ് അബ്രാമിനോട് അരുളിച്ചെയ്തു: നീ ആയിരിക്കുന്ന സ്ഥലത്തുനിന്നുകൊണ്ട് കണ്ണകളുയർത്തി വടക്കോട്ടും തെക്കോട്ടും കിഴക്കോട്ടും പടിഞ്ഞാറോട്ടും നോക്കുക.","p":1},{"v":15,"t":"എന്തെന്നാൽ, നീ കാണുന്ന പ്രദേശമെല്ലാം നിനക്കും നിന്റെ സന്തതിക്കും എന്നേക്കുമായി ഞാൻ നൽകും.","p":1},{"v":16,"t":"നിന്റെ സന്തതിയെ ഞാൻ ഭൂമിയിലെ പൂഴിപോലെയാക്കും. ഭൂമിയിലെ പുഴി ആർക്കെങ്കിലും എണ്ണാനാവുമെങ്കിൽ നിന്റെ സന്തതിയെയും എണ്ണാം.","p":1},{"v":17,"t":"എഴുന്നേറ്റ് ദേശത്തിനു നെടുകേയും കുറുകെയും ഉലാത്തുക; അത് ഞാൻ നിനക്കു തരുന്നു.","p":1},{"v":18,"t":"അബ്രാം കൂടാരം മാറ്റി ഹെബ്രോണിലുള്ള മാമ്രേയുടെ ഓക്കു മരങ്ങൾക്കു സമീപം താമസമാക്കി. അവിടെ അവൻ കർത്താവിനു ഒരു ബലിപീഠം പണിതു.","p":1}],"14":[{"h":"അബ്രാമും മെൽക്കിസെദെക്കും"},{"v":1,"t":"ഷീനാർരാജാവായ അമ്റാഫേൽ, എല്ലാസർ രാജാവായ അരിയൊക്ക്, ഏലാം രാജാവായ കെദോർലാവോമർ, ഗോയിം രാജാവായ തിദാൽ എന്നിവർ, തങ്ങളുടെ കാലത്ത് .","p":1},{"v":2,"t":"സോദോം രാജാവായ ബേറാ, ഗൊമോറ രാജാവായ ബീർഷ, അദ്മാ രാജാവായ ഷീനാബ്, സെബോയിം രാജാവായ ഷെമെബർ, ബേലയുടെ, അതായത് സോവാറിന്റെ രാജാവ് എന്നിവരോടു യുദ്ധംചെയ്തു. ഇവർക്കെല്ലാവരും സിദ്ദീം താഴ്‌വരയിൽ അണിനിരന്നവരായിരുന്നു.","p":1},{"v":3,"t":"ഉപ്പു കടലായ സിദ്ധിമിന്റെ താഴ്‌വരയിൽ ഇവരെല്ലാം സഖ്യത്തിലായി.","p":1},{"v":4,"t":"ഇവർ പന്ത്രണ്ടു വർഷം കെദോർലാവോമറിനെ സേവിച്ചു; പതിമൂന്നാം വർഷം അവർ കലാപമുയർത്തി.","p":1},{"v":5,"t":"പതിനാലാം വർഷം കെദോർലാവോമറും കൂടെയുണ്ടായിരുന്ന രാജാക്കന്മാരും ചെന്ന് അഷ്‌തെരോത്ത് കർണായിമിൽ റാഫാഭകളെയും ഹാമിൽ സുസീമുകളെയും ഷാവേക്കിരിയാത്തായിമിൽ എമീമുകളെയും"},{"v":6,"t":"സേയീർമലകളിൽ ഹോരികളെയും അടിച്ചമർത്തി. അവർ മരുഭൂമിയുടെ അരികിലുള്ള എൽപാരാൻ വരെയെത്തി.","p":1},{"v":7,"t":"അവർ പിന്തിരിഞ്ഞ് എൻമിഷ്പാത്തിൽ അതായത്, കാദേഷിൽ ചെന്ന് അമലേക്കുകളുടെ നാടുകളെയും നശിപ്പിച്ചു; ആസ്സസോൻതാമാറിൽ പാർത്തിരുന്ന അമോര്യരെയും.","p":1},{"v":8,"t":"അപ്പോൾ സോദോംരാജാവ്, ഗൊമോറരാജാവ്, അദ്മാരാജാവ്, സെബോയിംരാജാവ്, ഷെമെബർ അതായത്, സോവാറിലെ രാജാവ് എന്നിവർ പുറപ്പെട്ട് സിദ്ദീം താഴ്‌വരയിൽ യുദ്ധത്തിനൊരുങ്ങി -","p":1},{"v":9,"t":"ഏലാം രാജാവായ കെദോർലാവോമർ, ഗോയിം രാജാവായ തിദാൽ, ഷീനാർരാജാവായ അമ്റാഫേൽ, എല്ലസാർ രാജാവായ അരിയൊക്ക് എന്നിവർക്കെതിരെ, നാലു രാജാക്കന്മാർ അഞ്ചുപേർക്കെതിരെ.","p":1},{"v":10,"t":"സിദ്ദീം താഴ്‌വര മുഴുവൻ കളിമൺ കുഴികളായിരുന്നു. പിന്തിരിഞ്ഞോടിയപ്പോൾ സോദോമിലെയും ഗൊമോറയിലെയും രാജാക്കന്മാർ അതിൽ വീണു. ശേഷിച്ചവർ മലയിലേക്കു ഓടിപ്പോയി.","p":1},{"v":11,"t":"സോദോമിലെയും ഗൊമോറയിലെയും സർവ സമ്പത്തും ഭക്ഷണസാധനങ്ങളും അവർ കവർന്നു കൊണ്ടുപോയി.","p":1},{"v":12,"t":"അബ്രാമിന്റെ സഹോദരപുത്രനായ ലോത്തിനെയും അവന്റെ സമ്പത്തോടുംകൂടെ അവർ പിടിച്ചുകൊണ്ടുപോയി. അവൻ അപ്പോൾ സോദോമിൽ പാർക്കുകയായിരുന്നു.","p":1},{"v":13,"t":"രക്ഷപ്പെട്ട ഒരുവൻ വന്ന് ഹെബ്രായനായ അബ്രാമിനെ വിവരമറിയിച്ചു. അവൻ അപ്പോൾ എഷ്കോലിന്റെയും ആനേറിന്റെയും സഹോദരൻ അമോര്യനായ മാമ്രേയുടെ ഓക്കുമരത്തോപ്പിനു സമീപം താമസിക്കുകയായിരുന്നു. അവർ അബ്രാമിന്റെ ഉടമ്പടിയിൽ പങ്കാളികളായിരുന്നു.","p":1},{"v":14,"t":"സഹോദരൻ തടവുകാരനാക്കപ്പെട്ടെന്ന് അബ്രാം കേട്ടപ്പോൾ തന്റെ വീട്ടിൽ ജനിച്ചുവളർന്നവരും പയറ്റി തെളിഞ്ഞ വരുമായ മുന്നൂറ്റിപ്പതിനെട്ടുപേരെ കൂട്ടി ദാൻവരെ അവരെ പിന്തുടർന്നു.","p":1},{"v":15,"t":"അവനും അവന്റെ ഭൃത്യരും രാത്രിയിൽ വിവിധഗണങ്ങളായിപ്പിരിഞ്ഞ് അവരെ ആക്രമിച്ച് ദമാസ്കസിനു വടക്കുള്ള ഹോബാവരെ അവരെ പിന്തുടർന്നു.","p":1},{"v":15,"t":"15 അവനും അവൻ്റെ സേവകരും രാത്രി വിവിധ ഗണങ്ങളായി","p":1},{"v":15,"t":"തിരിഞ്ഞ് അവരെ ആക്രമിച്ചു.ദമാസ്കസിന് വടക്കുള്ള ഹോബാ വരെ അവൻ അവരെ പിന്തുടർന്നു","p":1},{"v":16,"t":"അവൻ സർവ്വ സമ്പത്തും തിരികെ കൊണ്ടുവന്നു കൂടാതെ അവൻ്റെ സഹോദരൻ ലോകത്തിനെയും അവൻ്റെ സമ്പത്തും ഒപ്പം സ്ത്രീകളെയും ജനങ്ങളെയും തിരികെ കൊണ്ടുവന്നു","p":1},{"v":17,"t":"കെദൊർലാവോമെറെയും കൂടെയുണ്ടായിരുന്ന രാജാക്കന്മാരെയും തോല്പിച്ച് അവൻ മടങ്ങി വന്നശേഷം, അവനെ സന്ദർശിക്കാൻ സോദോംരാജാവ്, രാജാവിന്റെ താഴ്‌വര എന്നറിയപ്പെടുന്ന ഷാവേ താഴ്‌വരയിലേക്ക് പുറപ്പെട്ടു.","p":1},{"v":18,"t":"ശാലേംരാജാവായ മെൽക്കിസെദേക്ക് അപ്പവും വീഞ്ഞും കൊണ്ടുവന്നു. അദ്ദേഹം അത്യുന്നത ദൈവത്തിന്റെ പുരോഹിതനായിരുന്നു.","p":1},{"v":19,"t":"അദ്ദേഹം അബ്രഹാമിനെ ആശീർവദിച്ചുകൊണ്ട് പറഞ്ഞു:","p":1},{"v":19,"t":"ആകാശത്തിന്റെയും ഭൂമിയുടെയും നാഥനായ അത്യുന്നത ദൈവത്താൽ അബ്രാം അനുഗ്രഹീതൻ!","p":1},{"v":20,"t":"നിന്റെ എതിരാളികളെ നിന്റെ കൈയിലേല്പിച്ച അത്യുന്നത ദൈവം വാഴ്ത്തപ്പെട്ടവൻ!","p":1},{"v":20,"t":"അവൻ എല്ലാറ്റിന്റെയും ദശാംശം അദ്ദേഹത്തിനു കൊടുത്തു.","p":1},{"v":21,"t":"സോദോംരാജാവ് അബ്രാമിനോടു പറഞ്ഞു: ആളുകളെ എനിക്കു തരൂ; സമ്പത്ത് നീ എടുത്തുകൊള്ളുക.","p":1},{"v":22,"t":"അബ്രാം സോദോംരാജാവിനോടു പറഞ്ഞു: ആകാശത്തിന്റെയും ഭൂമിയുടെയും ഉടമയായ അത്യുന്നതദൈവം എന്ന കർത്താവിങ്കലേക്ക് ഞാൻ എന്റെ കരമുയർത്തുന്നു.","p":1},{"v":23,"t":"ഞാൻ അബ്രാമിനെ സമ്പന്നനാക്കി എന്നു നീ പറയാതിരിക്കാൻ ഒരു ചരടോ ചെരുപ്പിന്റെ വാറോ നിന്റേതായ ഒന്നുതന്നെയോ ഞാൻ എടുക്കുകയില്ല.","p":1},{"v":24,"t":"യുവാക്കൾ ഭക്ഷിച്ചതും എന്റെ കൂടെ വന്ന ആളുകളുടെ പങ്കുമൊഴികെ, ആനർ, എഷ്കോൽ, മാമ്രെ എന്നിവർ തങ്ങളുടെ പങ്ക് എടുത്തുകൊള്ളട്ടെ","p":1}],"15":[{"h":"ദൈവവും അബ്രാമും തമ്മിൽ ഉടമ്പടി"},{"v":1,"t":"ഈ സംഭവങ്ങൾക്കുശേഷം അബ്രാമിന് ദർശനത്തിൽ കർത്താവിന്റെ വചനം ഇപ്രകാരം ഭവിച്ചു: അബ്രാം, ഭയപ്പെടേണ്ട. ഞാൻ നിനക്കു പരിചയാണ്. നിന്റെ പ്രതിഫലം വളരെ വലുതായിരിക്കും.","p":1},{"v":2,"t":"അബ്രാം ചോദിച്ചു: എന്റെ നാഥനായ കർത്താവേ, അങ്ങ് എനിക്കെന്താണ് തരിക? ഞാൻ ഇപ്പോഴും സന്താനരഹിതനായിത്തന്നെ കഴിയുന്നു. ദമാസ്കസ്സുകാരൻ എലിയേസറാണ് എന്റെ വീടിന്റെ കാര്യസ്ഥൻ."},{"v":3,"t":"തുടർന്ന് അബ്രാം പറഞ്ഞു: നോക്കൂ, എനിക്കൊരു സന്താനത്തെ അങ്ങ് തന്നിട്ടില്ല. ഇതാ, എന്റെ ഭവനത്തിലെ ഒരംഗമായിരിക്കും എന്റെ അനന്തരാവകാശി.","p":1},{"v":4,"t":"അപ്പോൾ അവന് കർത്താവിന്റെ വചനം ഇപ്രകാരം ഉണ്ടാവുകയുണ്ടായി: അവനല്ല നിന്റെ അനന്തരാവകാശിയാകുന്നത്; പ്രത്യുത, നിന്റെ ഉള്ളിൽനിന്നു പുറപ്പെടുന്നവൻ തന്നെ നിന്റെ അനന്തരാവകാശിയാകും.","p":1},{"v":5,"t":"അവിടുന്ന് അവനെ പുറത്തേക്കു കൊണ്ടുവന്നിട്ട് പറഞ്ഞു: ആകാശത്തേക്കു നോക്കുക; നക്ഷത്രങ്ങളെ എണ്ണുക, അവയെ എണ്ണാൻ നിനക്കു കഴിയുമെങ്കിൽ! അവിടുന്ന് തുടർന്ന് അവനോടു പറഞ്ഞു: അതുപോലെയായിരിക്കും നിന്റെ സന്തതിയും.","p":1},{"v":6,"t":"അവൻ കർത്താവിൽ വിശ്വസിച്ചു; അത് അവിടുന്ന് അവന് നീതിയായി പരിഗണിക്കുകയും ചെയ്തു.","p":1},{"v":7,"t":"അവിടുന്ന് തുടർന്ന് അവനോട് അരുളിച്ചെയ്തു: ഈ നാട് നിനക്ക് അവകാശമായിത്തരാൻവേണ്ടി നിന്നെ കല്ദായരുടെ ഊറിൽനിന്നു കൂട്ടിക്കൊണ്ടുവന്ന കർത്താവാണു ഞാൻ.","p":1},{"v":8,"t":"അവൻ ചോദിച്ചു: എന്റെ നാഥനായ കർത്താവേ, ഇതു ഞാൻ അവകാശമാക്കുമെന്ന് ഞാൻ എങ്ങനെ അറിയും?","p":1},{"v":9,"t":"അവിടുന്ന് അവനോടു പറഞ്ഞു: മൂന്നു വയസ്സു പ്രായമുള്ള ഒരു പശുക്കിടാവ്, മൂന്നു വയസ്സു പ്രായമുള്ള ഒരു പെണ്ണാട്, മൂന്നു വയസ്സു പ്രായമുള്ള ഒരു മുട്ടാട് എന്നിവയെയും ഒരു ചെങ്ങാലിയെയും പ്രാവിൻ കുഞ്ഞിനെയും എനിക്കായി കൊണ്ടുവരുക.","p":1},{"v":10,"t":"അവൻ അവയെല്ലാം അവിടേക്കായി കൊണ്ടുവന്ന് അവ നെടുകെ പിളർന്ന് കഷ്ണങ്ങൾ നേർക്കുനേർ വെച്ചു. എന്നാൽ പക്ഷികളെ അവൻ പിളർന്നില്ല.","p":1},{"v":11,"t":"ജഡത്തിന്മേൽ റാഞ്ചൽ പക്ഷികൾ ഇറങ്ങിവന്നപ്പോൾ അബ്രാം അവയെ ആട്ടിയോടിച്ചു.","p":1},{"v":12,"t":"സൂര്യൻ അസ്തമിച്ചുകൊണ്ടിരുന്നപ്പോൾ അബ്രഹാമിന്റെമേൽ ഒരു ഗാഢനിദ്ര പതിച്ചു. ഇതാ, കൂരിരുളാർന്ന ഒരു ഭീതി അവന്റെമേൽ നിപതിക്കുന്നു.","p":1},{"v":13,"t":"അപ്പോൾ കർത്താവ് അബ്രാമിനോട് അരുളിച്ചെയ്തു: നീ ഇത് ഉറപ്പായും അറിഞ്ഞുകൊള്ളുക. നിന്റെ സന്തതി തങ്ങളുടേതല്ലാത്ത നാട്ടിൽ പ്രവാസികളായിരിക്കും. അവർ അക്കൂട്ടർക്ക് ദാസവേല ചെയ്യും; അവരാകട്ടെ നാന്നൂറു കൊല്ലം അവരെ കഷ്ടപ്പെടുത്തും.","p":1},{"v":14,"t":"എന്നാൽ അവർ സേവിക്കുന്ന ജനതയെ ഞാൻ വിധിക്കും; അതിനുശേഷം ധാരാളം സമ്പത്തുമായി അവർ പുറത്തുവരും.","p":1},{"v":15,"t":"നീയാകട്ടെ, സമാധാനത്തോടെ നിന്റെ പിതാക്കന്മാരോടു ചേരും. വാർദ്ധക്യത്തിൽ നീ സംസ്കരിക്കപ്പെടും.","p":1},{"v":16,"t":"നാലാംതലമുറയിൽ അവർ ഇങ്ങോട്ട് തിരിച്ചുപോരും. എന്തെന്നാൽ, അമോര്യരുടെ ദുഷ്ടത ഇനിയും പൂർത്തിയായിട്ടില്ല.","p":1},{"v":17,"t":"സൂര്യൻ അസ്തമിച്ചപ്പോൾ കനത്ത അന്ധകാരം ഉണ്ടായി ഇതാ, പുകയുന്ന തീച്ചുളയും ജ്വലിക്കുന്ന തീനാളവും ആ കഷ്ണങ്ങളുടെ നടുവിലൂടെ കടന്നുപോയി.","p":1},{"v":18,"t":"ആ ദിവസം തന്നെ കർത്താവ് അബ്രാമുമായി ഇപ്രകാരം ഉടമ്പടി ചെയ്തു നിന്റെ സന്തതിക്ക് ഈ നാടു ഞാൻ തന്നിരിക്കുന്നു;","p":1},{"h":"ഈജിപ്തുനദി മുതൽ മഹാനദിയായ യൂഫ്രട്ടീസ് നദിവരെയുള്ള"},{"v":19,"t":"കേന്യർ, കെനീസ്യർ, കദ്മോന്യർ,","p":1},{"v":19,"t":"ഹിത്യർ, പെരിസ്യർ, റഫായീം, അമോര്യർ, കാനാൻ","p":1},{"v":19,"t":"ന്യർ, ഗിർഗാശ്യർ, ജബൂസ്യർ എന്നിവരെത്തന്നെ..","p":1}],"16":[{"h":"ഹാഗാറും ഇസ്മായേലും"},{"v":1,"t":"അബ്രാമിന്റെ ഭാര്യ സാറായി പ്രസവിച്ചിരുന്നില്ല. അവൾക്കു ഹാഗാർ എന്നു പേരുള്ള ഈജിപ്തുകാരിയായ ഒരു പരിചാരിക ഉണ്ടായിരിന്നു.","p":1},{"v":2,"t":"സാറായി അബ്രാമിനോടു പറഞ്ഞു: ഇതാ, പ്രസവിക്കുന്നതിൽനിന്നു കർത്താവു എന്നെ തടഞ്ഞിരിക്കുന്നു. അങ്ങ് എന്റെ പരിചാരികയെ പ്രാപിക്കുക. ഒരുപക്ഷേ,അവളിൽനിന്നു ഞാൻ പുത്രലബ്ധയാകും. അബ്രാം സാറായിയുടെ വാക്ക് ശ്രവിച്ചു.","p":1},{"v":3,"t":"അബ്രാമിന്റെ കാനാൻ ദേശവാസം പത്തു വർഷം പിന്നിട്ടപ്പോൾ അബ്രാമിന്റെ ഭാര്യ സാറായി തന്റെ പരിചാരികയായ ഈജിപ്തുകാരി ഹാഗാറിനെ ഭർത്താവായ അബ്രാമിനു ഭാര്യയായി നൽകി.","p":1},{"v":4,"t":"അവൻ ഹാഗാറിനെ പ്രാപിക്കുകയും അവൾ ഗർഭം ധരിക്കുകയും ചെയ്തു. താൻ ഗർഭിണിയാണെന്നു കണ്ടപ്പോൾ തന്റെ യജമാനത്തി അവളുടെ ദൃഷ്ടികളിൽ വിലകെട്ടവളായിത്തീർന്നു.","p":1},{"v":5,"t":"അപ്പോൾ സാറായി അബ്രാമിനോടു പറഞ്ഞു: എന്റെ ദുരിതം നിങ്ങളുടെമേൽ ആയിരിക്കട്ടെ! ഞാനാണ് എന്റെ പരിചാരികയെ നിങ്ങളുടെ മാറിലേക്കുവിട്ടു തന്നത്. പക്ഷേ, അവൾ ഗർഭിണിയാണെന്നു കണ്ടപ്പോൾ, ഞാൻ അവളുടെ ദൃഷ്ടികളിൽ വിലകെട്ടവളായി എനിക്കും നിങ്ങൾക്കും മധ്യേ കർത്താവു ന്യായം വിധിക്കട്ടെ.","p":1},{"v":6,"t":"അബ്രാം സാറായിയോടു പറഞ്ഞു: ഇതാ, നിന്റെ പരിചാരിക നിന്റെ കയ്യിൽത്തന്നെയാണ്. നിന്റെ ദൃഷ്ടിയിൽ ശരിയായത് അവളോടു ചെയ്തുകൊള്ളുക. സാറായി അവളെ കഷ്ടപ്പെടുത്താൻ തുടങ്ങി. അപ്പോൾ അവൾ അവളുടെ മുമ്പിൽനിന്നു ഓടിപ്പോയി.","p":1},{"v":7,"t":"എന്നാൽ, കർത്താവിന്റെ ദൂതൻ മരുഭൂമിയിലുള്ള ഒരു നീരുറവയുടെ, ഷൂറിലേക്കുള്ള വഴിയിലുള്ള ഉറവയുടെ, അരികിൽ അവളെ കണ്ടെത്തി."},{"v":8,"t":"അവൻ ചോദിച്ചു: സാറായിയുടെ പരിചാരികയായ ഹാഗാർ, നീ എവിടെനിന്നു വരുന്നു? എങ്ങോട്ടുപോകുന്നു? അവൾ മറുപടി പറഞ്ഞു: ഞാൻ എന്റെ യജമാനത്തിയായ സാറായിയുടെ മുമ്പിൽനിന്നു ഓടിപ്പോവുകയാണ്."},{"v":9,"t":"കർത്താവിന്റെ ദൂതൻ അവളോടു പറഞ്ഞു: നിന്റെ യജമാനത്തിയുടെ അടുത്തേക്കു തിരിച്ചപോയി നീ അവളുടെ കാര്യങ്ങൾക്കു കീഴെ എളിമപ്പെടുക.","p":1},{"v":10,"t":"കർത്താവിന്റെ ദൂതൻ അവളോടു തുടർന്നുപറഞ്ഞു: എണ്ണിയാൽ തീരാത്തവണ്ണം അത്രയധികമായി നിന്റെ സന്തതിയെ ഞാൻ തീർച്ചയായും വർധിപ്പിക്കും."},{"v":11,"t":"കർത്താവിന്റെ ദൂതൻ അവളോടു പറഞ്ഞു: ഇതാ, നീ ഗർഭവതിയായിരിക്കുന്നു നീ ഒരു പുത്രനെ പ്രസവിക്കും. ഇസ്മായേൽ എന്നു നീ അവനു പേരിടണം. കാരണം, കർത്താവു നിന്റെ കഷ്ടത ശ്രവിച്ചിരിക്കുന്നു.","p":1},{"v":12,"t":"കാട്ടുക്കഴുതക്കൊത്ത മനുഷ്യനായിരിക്കും അവൻ. അവന്റെ കൈ എല്ലാവർക്കുമെതിരേയും എല്ലാവരുടെയും കൈ അവനെതിരേയും ആയിരിക്കും. തന്റെ എല്ലാ സഹോദരങ്ങൾക്കുമെതിരായി അവൻ വാസമുറപ്പിക്കും."},{"v":13,"t":"തന്നോടു സംസാരിച്ച കർത്താവിന് അവൾ അത്താ എൽ റോയി എന്നു പേരിട്ടു. കാരണം, എന്നെ കാണുന്നവനായ ദൈവത്തെ പിന്നീട് ഞാനും ഇവിടെവെച്ചുകണ്ടല്ലോ എന്ന് അവൾ പറഞ്ഞു.","p":1},{"v":14,"t":"അതുകൊണ്ട് ആ കിണറിനെ ബേർ-ലഹായ്-റോയി എന്നു വിളിച്ചു. അത് കാദേശിനും ബേരെദിനും ഇടയ്ക്കാണ്.","p":1},{"v":15,"t":"ഹാഗാർ അബ്രാമിനു ഒരു പുത്രനെ പ്രസവിച്ചു. ഹാഗാർ പ്രസവിച്ച തന്റെ പുത്രന് അബ്രാം, ഇസ്മായേൽ എന്നു പേരിട്ടു.","p":1},{"v":16,"t":"ഹാഗാർ അബ്രാമിനുവേണ്ടി ഇസ്മായേലിനെ പ്രസവിക്കുമ്പോൾ അബ്രാമിന് എൺപത്താറു വയസ്സായിരുന്നു.","p":1}],"17":[{"h":"ഉടമ്പടിയും പരിച്ഛേദനവും"},{"v":1,"t":"അബ്രാമിന് തൊണ്ണൂറ്റൊമ്പതു വയസ്സായപ്പോൾ കർത്താവു അബ്രാമിനു പ്രത്യക്ഷപ്പെട്ട് അവനോട് അരുളിച്ചെയ്തു: ഞാൻ സർവശക്തനായ ദൈവം ആകുന്നു. എന്റെ മുമ്പിൽ വ്യാപരിക്കുക. പൂർണ്ണനായിരിക്കുക.","p":1},{"v":2,"t":"എന്റെ ഉടമ്പടി എനിക്കും നിനക്കുമിടയിൽ ഞാൻ സ്ഥാപിക്കും. ഞാൻ നിന്നെ അത്യധികം വർധിപ്പിക്കും.","p":1},{"v":3,"t":"അപ്പോൾ അബ്രാം മുഖംമുട്ടേ കുമ്പിട്ടു. ദൈവം അവനോട് ഇപ്രകാരം അരുളിച്ചെയ്തു:"},{"v":4,"t":"ഇതാ, നിന്നോടുകൂടെ ഞാൻ എന്റെ ഉടമ്പടി ചെയ്യുന്നു. നീ ജനതതികളുടെ പിതാവായിത്തീരും.","p":1},{"v":5,"t":"ഇനിമേൽ നിന്റെ പേര് അബ്രാം എന്നല്ല വിളിക്കപ്പെടുകയില്ല; പ്രത്യുത, നിന്റെ പേര് അബ്രാഹം എന്നായിരിക്കും എന്തെന്നാൽ, ഞാൻ നിന്നെ ജനതകളുടെ പിതാവാക്കിയിരിക്കുന്നു.","p":1},{"v":6,"t":"ഞാൻ നിന്നെ അത്യധികം സന്താനപുഷ്ടിയുള്ളവനാക്കും. നിന്നെ ഞാൻ ജനതകളാക്കിയിരിക്കുന്നു. രാജാക്കന്മാർ നിന്നിൽ നിന്ന് പുറപ്പെടും.","p":1},{"v":7,"t":"ഞാൻ നിനക്കും നിനക്കുശേഷം നിന്റെ സന്തതിക്കും ദൈവമായിരിക്കേണ്ടതിന് ഞാനും നീയും തമ്മിലും നിനക്കുശേഷം നിന്റെ സന്തതിയും തമ്മിലുള്ള എന്റെ ഉടമ്പടി ഞാൻ ഉയർത്തിയിരിക്കുന്നു. അവരുടെ തലമുറകൾക്ക് ഇത് ശാശ്വത ഉടമ്പടിയായിരിക്കും.","p":1},{"v":8,"t":"നിന്റെ പ്രവാസത്തിന്റെ ദേശം, കാനാൻ ദേശം മുഴുവനും എന്നേക്കുമുളള അവകാശമായി നിനക്കും നിനക്കുശേഷം നിന്റെ സന്തതിക്കും ഞാൻ തരും; അവർക്കു ഞാൻ ദൈവമായിരിക്കുകയും ചെയ്യും.","p":1},{"v":9,"t":"ദൈവം അബ്രാഹത്തോടു അരുളിച്ചെയ്തു:നീ, നീയും നിനക്കുശേഷമുള്ള നിന്റെ സന്തതിയും അവരുടെ തലമുറകളും, എന്റെ ഉടമ്പടി പാലിക്കണം.","p":1},{"v":10,"t":"എനിക്കു നിങ്ങളോടും നിനക്കുശേഷം നിന്റെ സന്തതിയോടും ഉളളതും നിങ്ങൾ പാലിക്കേണ്ടതുമായ എന്റെ ഉടമ്പടി ഇതാണ്: നിങ്ങളുടെ പുരുഷന്മാരെല്ലാം പരിച്ഛേദനം ചെയ്യപ്പെടണം.","p":1},{"v":11,"t":"നിങ്ങൾ നിങ്ങളുടെ അഗ്രചർമം ഛേദിക്കണം. അത് ഞാനും നിങ്ങളുമായുള്ള ഉടമ്പടിയുടെ അടയാളമായിരിക്കും."},{"v":12,"t":"നിങ്ങളിൽ, നിങ്ങളുടെ തലമുറകളിൽ എട്ടു ദിവസം പ്രായമായ ഓരോ ആൺകുട്ടിയും, അവൻ നിന്റെ വീട്ടിൽ പിറന്നവനോ നിന്റെ സന്താനത്തിൽപ്പെടാത്ത, വിലയ്ക്കു വാങ്ങപ്പെട്ട പരദേശിയോ ആകട്ടെ, പരിച്ഛേദനം ചെയ്യപ്പെടണം.","p":1},{"v":13,"t":"നിന്റെ വീട്ടിൽ പിറന്നവനും നീ വിലയ്ക്കു വാങ്ങിയവനും നിശ്ചയമായും പരിച്ഛേദനം ചെയ്യപ്പെടണം. അങ്ങനെ എന്റെ ഉടമ്പടി നിങ്ങളുടെ ശരീരത്തിൽ ശാശ്വതമായി ഒരു ഉടമ്പടിയായിരിക്കും.","p":1},{"v":14,"t":"അഗ്രചർമം നീക്കം ചെയ്യപ്പെടാത്ത പുരുഷൻ അപരിച്ഛേദിതനാണ്. ആ വ്യക്തി തന്റെ ജനത്തിൽനിന്ന് വിച്ഛേദിക്കപ്പെടണം, എന്റെ ഉടമ്പടിയാണ് അവൻ ലംഘിച്ചിരിക്കുന്നത്.","p":1},{"h":"ഇസഹാക്ക്"},{"v":15,"t":"ദൈവം അബ്രാഹത്തോടു അരുൾച്ചെയ്തു: നിന്റെ ഭാര്യ സാറായിയെ ഇനിമേൽ സാറായി എന്നല്ല നീ വിളിക്കേണ്ടത്; മറിച്ച് അവളുടെ പേര് സാറാ എന്നായിരിക്കും.","p":1},{"v":16,"t":"ഞാൻ അവളെ അനുഗ്രഹിക്കും; അവളിൽനിന്നു ഞാൻ നിനക്കൊരു പുത്രനെ നൽകുകയും ചെയ്യും. അവളെ ഞാൻ അനുഗ്രഹിക്കും; അവൾ ജനതകളായിത്തീരും. ജനങ്ങളുടെ രാജാക്കന്മാർ അവളിൽനിന്നു ഉദ്ഭവിക്കും.","p":1},{"v":17,"t":"അപ്പോൾ അബ്രാഹം മുഖം മുട്ടേ കുമ്പിട്ടു; എന്നാൽ, അവൻ ചിരിച്ചുകൊണ്ട് ആത്മഗതം ചെയ്തു: നൂറു വയകാരന് ഒരു പുത്രൻ ജനിക്കുമോ? തൊണ്ണൂറു വയസ്സുകാരി സാറാ പ്രസവിക്കുമോ?","p":1},{"v":18,"t":"അപ്പോൾ അബ്രാഹം ദൈവത്തോടു പറഞ്ഞു: ഇസ്മായേൽ അങ്ങയുടെ മുമ്പിൽ ജീവിച്ചിരുന്നാൽ മതിയായിരുന്നു!"},{"v":19,"t":"ദൈവം അരുൾച്ചെയ്തു: നിന്റെ ഭാര്യ സാറാ തന്നെ നിനക്കൊരു പുത്രനെ പ്രസവിക്കും, നീ അവനു ഇസഹാക് എന്നു പേരു വിളിക്കണം. അവനുമായി ഞാൻ എന്റെ ഉടമ്പടി ഉറപ്പിക്കും; അവനുശേഷം അവന്റെ സന്തതിക്കും വേണ്ടിയുള്ള ശാശ്വത ഉടമ്പടി.","p":1},{"v":20,"t":"ഇസ്മായീലിന് വേണ്ടിയും ഞാൻ നിന്നെ ശ്രവിച്ചിരിക്കുന്നു. ഇതാ, ഞാൻ അവനെ അനുഗ്രഹിക്കുന്നു; അവൻ അത്യധികം പെരുകി വർധിക്കാൻ ഞാൻ ഇടയാക്കും. അവൻ പന്ത്രണ്ടു പ്രഭുക്കന്മാർക്കു ജന്മമേകും ; അവനെ ഞാൻ വലിയ ഒരു ജനതയാക്കി സ്ഥാപിക്കും.","p":1},{"v":21,"t":"എന്നാൽ, അടുത്തവർഷം ഇതേ സമയത്ത് സാറാ നിനക്കുവേണ്ടി പ്രസവിക്കുന്ന ഇസഹാക്കുമായാണ് എന്റെ ഉടമ്പടി ഞാൻ ഉയർത്തുന്നത്.","p":1},{"v":22,"t":"ദൈവം അബ്രാഹത്തോടു സംസാരിച്ചുകഴിഞ്ഞ് അവനെവിട്ട് ആരോഹണം ചെയ്തു.","p":1},{"v":23,"t":"ദൈവം അബ്രാഹത്തോടു ആവശ്യപ്പെട്ടതുപോലെ മകൻ ഇസ്മായേലിനെയും തന്റെ വീട്ടിൽ പിറന്നവരെയും താൻ വിലകൊടുത്തു വാങ്ങിയവരെയും തന്റെ ഭവനത്തിലുള്ള സകല പുരുഷന്മാരെയും കൊണ്ടു വന്ന് അവൻ ആ ദിവസംതന്നെ അവരുടെ അഗ്രചർമം പരിച്ഛേദനം ചെയ്തു.","p":1},{"v":24,"t":"അഗ്രചർമ്മം പരിച്ഛേദനം ചെയ്യപ്പെടുമ്പോൾ അബ്രാഹത്തിനു തൊണ്ണൂറ്റൊൻപതു വയസ്സായിരുന്നു.","p":1},{"v":25,"t":"അവന്റെ പുത്രൻ ഇസ്മായേലിന് അഗ്രചർമം പരിച്ഛേദനം ചെയ്യപ്പെടുമ്പോൾ പതിമൂന്നു വയസ്സായിരുന്നു.","p":1},{"v":26,"t":"ഒരേ ദിവസമാണ് അബ്രാഹവും മകൻ ഇസ്മായേലും പരിച്ഛേദനം ചെയ്യപ്പെട്ടത്.","p":1},{"v":27,"t":"അവന്റെ വീട്ടിലെ എല്ലാ പുരുഷന്മാരും, വീട്ടിൽ പിറന്നവരും പരദേശികളിൽനിന്ന് വിലയ്ക്കു വാങ്ങിയവരും, അവനോടൊപ്പം പരിച്ഛേദനം ചെയ്യപ്പെട്ടു.","p":1}],"18":[{"v":1,"t":"മാമ്രയുടെ ഓക്ക് മരങ്ങൾക്ക് സമീപം കർത്താവ് അവനു പ്രത്യക്ഷനായി ദിവസത്തിന് ചൂടേറിയപ്പോൾ അവൻ തന്റെ കൂടാരത്തിന്റെ വാതില്ക്കൽ ഇരിക്കുകയായിരുന്നു.","p":1},{"v":2,"t":"അവൻ കണ്ണുകളുയർത്തി നോക്കിയപ്പോൾ ഇതാ, മൂന്നാളുകൾ തനിക്കെതിരെ നില്ക്കുന്നു. അവരെ കണ്ടമാത്രയിൽ അവൻ അവരെ എതിരേൽക്കാൻ കൂടാരവാതില്കൽനിന്ന് ഓടിച്ചെന്ന്, നിലംപറ്റേ കുമ്പിട്ടു.","p":1},{"v":3,"t":"‘അവൻ പറഞ്ഞു: യജമാനനേ, അങ്ങയുടെ ദൃഷ്ടികളിൽ ഞാൻ പ്രീതികണ്ടെത്തിയെങ്കിൽ അങ്ങയുടെ ദാസനെ കടന്നുപോകരുതേ!.","p":1},{"v":4,"t":"കുറച്ചു വെള്ളം കൊണ്ടുവരട്ടെ. നിങ്ങളുടെ പാദങ്ങൾ കഴുകി മരച്ചുവട്ടിൽ വിശ്രമിച്ചാലും.","p":1},{"v":5,"t":"നിങ്ങളുടെ ഈ ദാസന്റെ അടുക്കൽ വന്നനിലയ്ക്ക് ഞാൻ കുറച്ച് അപ്പം കൊണ്ടുവരാം. നിങ്ങളുടെ ഹൃദയം ഉന്മേഷമുള്ളതാക്കി യാത്ര തുടരാം. അവർ പറഞ്ഞു: നീ പറഞ്ഞതുപോലെ ചെയ്തുകൊള്ളുക.","p":1},{"v":6,"t":"അബ്രഹാം കൂടാരത്തിൽ സാറായുടെ അടുത്തേക്ക് കുതിച്ചു. അവൻ പറഞ്ഞു: വേഗം മൂന്നു സെയാ നേരിയ മാവ് കുഴച്ച് അപ്പമുണ്ടാക്കുക.","p":1},{"v":7,"t":"അബ്രഹാം കാലിക്കൂട്ടത്തിലേക്ക് ഓടിച്ചെന്ന് ഇളയതും നല്ലതുമായ ഒരു കാലിക്കൂട്ടിയെ പിടിച്ച് വേലക്കാരനെ ഏൽപ്പിച്ചു. ഉടനെ അയാൾ അത് പാകംചെയ്യാൻ തുടങ്ങി.","p":1},{"v":8,"t":"അവൻ വെണ്ണയും പാലും പാകംചെയ്ത മാംസവും അവരുടെ മുമ്പിൽ വിളമ്പി. അവർ ഭക്ഷിച്ചു. അവനാകട്ടെ, മരച്ചുവട്ടിൽ അവരുടെ സമീപം നിന്നു.","p":1},{"v":9,"t":"അവർ അവനോട് ചോദിച്ചു: നിന്റെ ഭാര്യ സാറാ എവിടെ? ഇതാ, കൂടാരത്തിലുണ്ട്. അവൻ മറുപടി പറഞ്ഞു.","p":1},{"v":10,"t":"അവിടന്നു പറഞ്ഞു: വസന്തകാലത്ത് ഞാൻ തീർച്ചയായും നിന്റെയടുത്ത് മടങ്ങിവരും. അപ്പോൾ നിന്റെ ഭാര്യ സാറായ്ക്ക് ഒരു പുത്രനുണ്ടായിരിക്കും. അവന്റെ പുറകിലെ കൂടാരവാതില്കൽ സാറാ ഇത് കേൾക്കുന്നുണ്ടായിരുന്നു.","p":1},{"v":11,"t":"അബ്രഹവും സാറായും വൃദ്ധരും പ്രായംകഴിഞ്ഞവരുമായിരുന്നു; സാറായ്ക്ക് സ്ത്രീകളുടെ മുറ നിലച്ചുപോയിരുന്നു.","p":1},{"v":12,"t":"അതിനാൽ, സാറാ ചിരിക്കുകയും ഇപ്രകാരം ഉള്ളിൽ പറയുകയും ചെയ്തു: എല്ലാ കൊഴിഞ്ഞുതീർന്നപ്പോൾ എനിക്ക് ഇനിയും ദാമ്പത്യസുഖമോ? എന്റെ ഭർത്താവോ, വൃദ്ധൻ!","p":1},{"v":13,"t":"കർത്താവ് അബ്രഹത്തോടു ചോദിച്ചു: എന്തിനാണ് ‘ഞാൻ വൃദ്ധയായിരിക്കുന്നു; വാസ്തവത്തിൽ, ഞാൻ ഇനി പ്രസവിക്കുമോ’ എന്നു ചോദിച്ചുകൊണ്ട് സാറാ ചിരിക്കുന്നത്?","p":1},{"v":14,"t":"കർത്താവിന് അസാധ്യമായി എന്തെങ്കിലുമുണ്ടോ? നിശ്ചിതസമയത്ത് വസന്തകാലത്ത് ഞാൻ നിന്റെയടുത്ത് മടങ്ങിവരും. അപ്പോൾ സാറായ്ക്ക് ഒരു പുത്രനുണ്ടായിരിക്കും.","p":1},{"v":15,"t":"ഞാൻ ചിരിച്ചില്ല എന്ന് സാറ കള്ളം പറഞ്ഞു. എന്തെന്നാൽ, അവൾ ഭയന്നിരുന്നു. അവിടന്നുഊ പറഞ്ഞു: അല്ല, നീ ചിരിക്കുകതന്നെ ചെയ്തു."},{"h":"സോദോം-ഗോമോറായുടെ നാശം"},{"v":16,"t":"അനന്തരം ആ വ്യക്തികൾ അവിടെനിന്നെഴുന്നേറ്റ് സോദോമിനുനേരെ താഴേക്ക് നോക്കി. അവരെ യാത്രയാക്കാൻ അബ്രഹാം അവരോടൊപ്പം നടന്നു.","p":1},{"v":17,"t":"കർത്താവ് ആത്മഗതം ചെയ്തു: ഞാൻ ചെയ്യാൻ പോകുന്നത് അബ്രാഹത്തി നിന്ന് മറച്ചുവയ്കേണ്ടതുണ്ടോ?","p":1},{"v":18,"t":"അബ്രഹാം നിശ്ചയമായും മഹത്തും ശക്തവുമായ ഒരു ജനതയായിത്തീരും. ഭൂമിയിലെ ജനതകളെല്ലാം അവനിലൂടെ അനുഗ്രഹിക്കപ്പെടും.","p":1},{"v":19,"t":"ഞാൻ അവനെ തിരഞ്ഞെടുത്തിരിക്കുന്നത്, അവൻ തന്റെ മക്കളെയും പിൻമുറക്കാരെയും അനുശാസിക്കാനും അതുവഴി അവർ നീതിയും ന്യായവും പ്രവർത്തിച്ച് കർത്താവിന്റെ മാർഗ്ഗം പാലിക്കാനും. അങ്ങനെ കർത്താവ് അബ്രാത്തെക്കുറിച്ച് പറഞ്ഞിട്ടുള്ളവ അവനിൽ പൂർത്തിയാക്കാനുമാണ്.","p":1},{"v":20,"t":"കർത്താവ് പറഞ്ഞു: സോദോമിന്റെയും ഗോമോറായുടെയും രോദനം തീവ്രവും അവരുടെ പാപം അതീവ ഗുരുതരവുമാണ്.","p":1},{"v":21,"t":"അവർ പ്രവർത്തിച്ചിരിക്കുന്നതൊക്കെയും എന്റെ പക്കലെത്തിയ രോദനംപോലെ തന്നെയാണോ എന്നുകാണാൻ ഞാൻ ഇറങ്ങിച്ചെല്ലട്ടെ; അങ്ങനെയല്ലെങ്കിൽ എനിക്കറിയാമല്ലോ.","p":1},{"v":22,"t":"ആ വ്യക്തികൾ അവിടെനിന്നു തിരിഞ്ഞ് സോദോമിനുനേരെ നടന്നു. അബ്രഹാമാകട്ടെ, അപ്പോഴും കർത്താവിന്റെ മുമ്പിൽത്തന്നെ നിലകൊണ്ടു.","p":1},{"v":23,"t":"അബ്രഹാം അടുത്തെ ചെന്നു ചോദിച്ചു: ദുഷ്ടനോടൊപ്പം നീതിമാനെയും അങ്ങ് തുടച്ചുനീക്കുമോ?","p":1},{"v":24,"t":"ആ നഗരത്തിനുള്ളിൽ അമ്പതു നീതിമാന്മാരുള്ളപക്ഷവും, അങ്ങ് അതിനെ തുടച്ചുനീക്കുമോ?അവിടെയുള്ള ആ അമ്പതു നീതിമാന്മാരെപ്രതി ആ പ്രദേശത്തോട് ക്ഷമിക്കില്ലേ?","p":1},{"v":25,"t":"ദുഷ്ടനോടൊപ്പം നീതിമാനെയും സംഹരിക്കുക - ഇങ്ങനെയൊരു കാര്യം ചെയ്യുകയെന്നത് അങ്ങിൽനിന്ന് അകന്നിരിക്കട്ടെ. നീതിമാനും ദുഷ്ടനും ഒന്നുപോലെയകുകയെന്നതും അങ്ങിൽനിന്ന് അകന്നിരിക്കട്ടെ. ഭൂമി മുഴുവൻ്റെയും വിധികർത്താവ് നീതി പ്രവർത്തിക്കാതിരിക്കുമോ?","p":1},{"v":26,"t":"കർത്താവ് അരുൾചെയ്തു: സോദോമിൽ, ആ നഗരത്തിനുള്ളിൽ അമ്പതു നീതിമാന്മാരെ ഞാൻ കണ്ടെത്തുന്നപക്ഷം, അവരെപ്രതി ഞാൻ ആ പ്രദേശത്തോട് മുഴുവൻ ക്ഷമിക്കും,","p":1},{"v":27,"t":"അബ്രഹാം മറുപടിയായി പറഞ്ഞു: ഇതാ, ഞാൻ എന്റെ നാഥനോട് സംസാരിക്കാൻ തുനിഞ്ഞല്ലോ! ഞാനാകട്ടെ, പൊടിയും ചാരവും","p":1},{"v":28,"t":"ഒരുപക്ഷേ നീതിമാന്മാർ അമ്പതിന് അഞ്ചു കുറവു വന്നാൽ, ആ അഞ്ചിനെപ്രതി നഗരം മുഴുവൻ നശിപ്പിക്കുമോ? അവിടുന്നു അരുളിച്ചെയ്തു: നാൽപ്പത്തഞ്ചുപേരെ ഞാൻ അവിടെ കണ്ടെത്തുകയാണെങ്കിൽ നശിപ്പിക്കുകയില്ല.","p":1},{"v":29,"t":"അവിടത്തോടു തുടർന്നു സംസാരിക്കവേ അവൻ പറഞ്ഞു: ഒരുപക്ഷേ, അവിടെ നാല്പതുപേരെ മാത്രമേ കണ്ടെത്താനുള്ളൂ എങ്കിലോ? അവിടുന്നു അരുളിച്ചെയ്തു: ആ നാല്പതിനെപ്രതി ഞാൻ അതു ചെയ്യുകയില്ല.","p":1},{"v":30,"t":"അവൻ പറഞ്ഞു: എന്റെ യജമാനൻ കോപിക്കരുതേ! ഞാൻ പറഞ്ഞു കൊള്ളട്ടെ: ഒരുപക്ഷേ, അവിടെ മുപ്പതുപേരെ മാത്രമേ കണ്ടെത്താനുള്ളൂ എങ്കിലോ? അവിടുന്നു അരുളിച്ചെയ്തു: അവിടെ ഞാൻ മുപ്പതുപേരെ മാത്രമേ കണ്ടെത്തുകയുള്ളൂവെങ്കിൽ ഞാനതു ചെയ്യുകയില്ല.","p":1},{"v":31,"t":"അവൻ പറഞ്ഞു: ഇതാ, ഞാൻ എന്റെ യജമാനനോട് സംസാരിക്കാൻ തുനിഞ്ഞല്ലോ. ഒരുപക്ഷേ, ഇരുപതുപേരെ മാത്രമേ അവിടെ കണ്ടെത്തുന്നുള്ളൂ എങ്കിലോ? അവിടുന്നു അരുളിച്ചെയ്തു: ആ ഇരുപതുപേരെപ്രതി ഞാൻ നശിപ്പിക്കുകയില്ല.","p":1},{"v":32,"t":"അവൻ പറഞ്ഞു: എന്റെ യജമാനൻ കോപിക്കരുതേ! ഈ ഒരു പ്രാവശ്യം കൂടി ഞാൻ പറഞ്ഞുകൊള്ളട്ടെ: ഒരുപക്ഷേ, പത്തുപേരെ മാത്രമേ അവിടെ കണ്ടെത്തുന്നുള്ളൂ എങ്കിലോ? അവിടുന്നു അരുൾച്ചെയ്തു: ആ പത്തുപേരെപ്രതി ഞാൻ നശിപ്പിക്കുകയില്ല.","p":1},{"v":33,"t":"അബ്രാഹത്തോടു സംസാരിച്ചു കഴിഞ്ഞപ്പോൾ കർത്താവ് യാത്രയായി. അബ്രഹാവും സ്വസ്ഥാനത്തേക്കു മടങ്ങി","p":1}],"19":[{"h":"സോദോമിന്റെ പാപം"},{"v":1,"t":"വൈകുന്നേരം രണ്ടു ദൂതന്മാർ സോദോമിലെത്തി. ലോത്ത് നഗരവാതിൽക്കൽ ഇരിക്കുകയായിരുന്നു. അവരെക്കണ്ടപ്പോൾ ലോത്ത് എതിരേല്ക്കാനായിഎഴുന്നേറ്റ് നിലംപറ്റി മുഖംതാഴ്ത്തി വണങ്ങി.","p":1},{"v":2,"t":"അവൻ പറഞ്ഞു: എന്റെ യജമാനന്മാരെ, ഇതാ, നിങ്ങളുടെ ദാസന്റെ വീട്ടിലേക്കു വന്ന് രാപാർത്താലും; നിങ്ങളുടെ കാലുകൾ കഴുകിയാലും. എന്നിട്ടു രാവിലെ എഴുന്നേറ്റ് നിങ്ങളുടെ വഴിക്കു പോകാം. അപ്പോൾ അവർ പറഞ്ഞു: വേണ്ട, ഞങ്ങൾ തെരുവിൽ രാത്രി കഴിച്ചുകൊള്ളാം.","p":1},{"v":3,"t":"എന്നാൽ, അവൻ ഏറെ നിർബന്ധിച്ചപ്പോൾ അവർ അവന്റെ നേരെ തിരിഞ്ഞ് അവന്റെ വീട്ടിലേക്കു ചെന്നു. അവൻ അവർക്കു വിരുന്നൊരുക്കി; പുളിപ്പില്ലാത്ത അപ്പവും ചുട്ടു. അവർ ഭക്ഷിച്ചു.","p":1},{"v":4,"t":"അവർ കിടക്കുംമുമ്പേ നഗരത്തിലെ ആളുകൾ, യുവാക്കന്മാർ മുതൽ വൃദ്ധന്മാർ വരെ, അവസാനത്തെ ആളുൾപ്പെടെ സോദോമിലുള്ള എല്ലാ പുരുഷന്മാരുംകൂടി ആ വീടു വളഞ്ഞു.","p":1},{"v":5,"t":"അവർ ലോത്തിനെ വിളിച്ച് അവനോടു ചോദിച്ചു: ഈ രാത്രി നിന്റെയടുക്കൽ വന്ന ആളുകളെവിടെ? ഞങ്ങൾ അവരുമായി രമിക്കേണ്ടതിന് അവരെ ഞങ്ങളുടെയടുത്തു പുറത്തുകൊണ്ടുവരുക.","p":1},{"v":6,"t":"ലോത്ത് അവരുടെയടുത്തു വാതില്ക്കലേക്കു ചെന്നു. അവൻ പുറത്തുകടന്നു കതകടച്ചു.","p":1},{"v":7,"t":"അവൻ പറഞ്ഞു: അരുത്, എന്റെ സഹോദരന്മാരേ, തിന്മ ചെയ്യരുത്.","p":1},{"v":8,"t":"നോക്കൂ, പുരുഷനെ അറിയാത്ത രണ്ടു പെൺമക്കൾ എനിക്കുണ്ട്; ഞാൻ അവരെ നിങ്ങളുടെപക്കലേക്ക് പുറത്തുകൊണ്ടുവരാം; നിങ്ങൾക്കിഷ്ടമുള്ളതുപോലെ അവരോടു ചെയ്തുകൊള്ളുക. പക്ഷേ, ഈ ആളുകളോട് മാത്രം ഒന്നും ചെയ്യരുത്. എന്തെന്നാൽ, അവർ എന്റെ മേൽക്കൂരയുടെ തണലിൽ വന്നവരാണ്.","p":1},{"v":9,"t":"അവർ അവന് അലറി: മാറിനില്ക്കൂ! തുടർന്നു അവർ പറഞ്ഞു: വിപ്രവാസത്തിനു വന്നവൻ ന്യായം വിധിക്കാൻ മുതിരുന്നുവോ! ഇപ്പോൾ, അവരോടന്നതിനേക്കാൾ മോശമായി നിന്നോട് ഞങ്ങൾ പെരുമാറും. അവർ ലോത്തിനെ ശക്തിയോടെ തള്ളി, വാതിൽ തല്ലിപ്പൊളിക്കാൻ അടുത്തുചെന്നു.","p":1},{"v":10,"t":"അപ്പോൾ, ആ അതിഥികൾ തങ്ങളുടെ കൈനീട്ടി ലോത്തിനെ അടുത്തേക്കു വലിച്ച് വീട്ടിനുള്ളിലാക്കി വാതിലടച്ചു.","p":1},{"v":11,"t":"എന്നിട്ട് അവർ വീട്ടുവാതില്കലുണ്ടായിരുന്ന ആ പുരുഷന്മാരെ, ചെറിയവൻ മുതൽ വലിയവൻവരെ, അന്ധതയാൽ പ്രഹരിച്ചു; അവർ വാതിൽ കണ്ടെത്തനാവാതെ വലഞ്ഞു.","p":1},{"v":12,"t":"ആ അതിഥികൾ ലോത്തിനോട് ആരാഞ്ഞു: ഇവിടെ നിനക്ക് സ്വന്തക്കാർ വേറെയുണ്ടോ? മരുമകനോ നിന്റെ പുത്രന്മാരോ പുത്രിമാരോ ആരുമാകട്ടെ ഈ നഗരത്തിൽ നിനക്കുള്ളവരെ ഈ പ്രദേശത്തുനിന്നു പുറത്തുകൊണ്ടുപോകുവിൻ.","p":1},{"v":13,"t":"എന്തെന്നാൽ, ഈ പ്രദേശം ഞങ്ങൾ നശിപ്പിക്കാൻപോകുകയാണ്. കർത്താവിന്റെ മുമ്പിൽ അവയുടെ രോദനം വലുതാകയാൽ ഇവിടം നശിപ്പിക്കാൻ കർത്താവു ഞങ്ങളെ അയച്ചിരിക്കുന്നു.","p":1},{"v":14,"t":"ലോത്ത് പുറത്തുചെന്ന്, തന്റെ പുത്രിമാരെ വിവാഹം ചെയ്യാനിരുന്ന തന്റെ മരുമക്കളെ കാര്യമറിയിച്ചു അവൻ പറഞ്ഞു: എഴുന്നേറ്റ് ഇവിടം വിടുവിൻ എന്തെന്നാൽ, കർത്താവു ഈ നഗരം നശിപ്പിക്കാൻ പോകുകയാണ്. എന്നാൽ അവൻ്റെ മരുമക്കളുടെ ദൃഷ്ടിയിൽ അതൊരു തമാശ പോലെയായിരുന്നു.","p":1},{"h":"ലോത്ത് സോദോം വിടുന്നു"},{"v":15,"t":"നേരംപുലർന്നപ്പോൾ ദൂതന്മാർ ലോത്തിനോടു നിർബന്ധിച്ചുപറഞ്ഞു: എഴുന്നേല്ക്കു! നിന്റെ ഭാര്യയെയും ഇപ്പോഴുള്ള നിന്റെ രണ്ടു പെണൺമക്കളെയും കൂടെക്കൂട്ടുക. അല്ലെങ്കിൽ നഗരത്തിന്റെ ശിക്ഷയിൽ നീയും തുടച്ചുനീക്കപ്പെടും.","p":1},{"v":16,"t":"എന്നാൽ, മടിച്ചുനിന്നപ്പോൾഅയാളോടുള്ള കർത്താവിന്റെ അനുകമ്പ കൊണ്ട് ആ ആളുകൾ, അയാളുടെ കൈയിലും ഭാര്യയുടെ കൈയിലും രണ്ടു പുത്രിമാരുടെയും കൈയിലും മുറുകെപ്പിടിച്ച്, അയാളെ നഗരത്തിനുപുറത്തു കൊണ്ടുവിട്ടു.","p":1},{"v":17,"t":"അവരെ പുറത്തു കൊണ്ടുചെന്നാക്കുമ്പോൾ അവൻ പറഞ്ഞു: നിന്റെ പ്രാണനെപ്രതി തിടുക്കംകൂട്ടുക; നിന്റെ പിന്നിലേക്കു നോക്കരുത്; സമതലത്തിൽഒരിടത്തും നില്ക്കരുത്; മലയിലേക്ക് ഓടി രക്ഷപ്പെടുക; അല്ലെങ്കിൽ നീ തുടച്ചുനീക്കപ്പെടും.","p":1},{"v":18,"t":"ലോത്ത് അവരോടു പറഞ്ഞു: എന്റെ യജമാനന്മാരേ, അരുതേ!","p":1},{"v":19,"t":"ഇതാ, അങ്ങയുടെ ദാസൻ ഇപ്പോൾ അങ്ങയുടെ ദൃഷ്ടികളിൽ പ്രീതി കണ്ടെത്തിയിരിക്കുകയാണല്ലോ. മാത്രമല്ല, എന്റെ ജീവൻ സംരക്ഷിക്കാൻ എന്നോട് അങ്ങു ചെയ്ത കാരുണ്യം അങ്ങു വിശാലമാക്കുകയും ചെയ്തിരിക്കുന്നു. എന്നാൽ, ആപത്ത് എന്നെ പിടികൂടി ഞാൻ മരിക്കാതിരിക്കേണ്ടതിന്, മലയിലേക്ക് ഓടി രക്ഷപ്പെടാൻ എനിക്കു സാധിക്കുകയില്ല.","p":1},{"v":20,"t":"നോക്കൂ, ആ പട്ടണം ഓടിയെത്താൻമാത്രം സമീപസ്ഥലമാണ്, അതു ചെറുതുമാണ്. ഞാൻ അങ്ങോട്ട് ഓടി രക്ഷപ്പെട്ടുകൊള്ളട്ടെ, അതു ചെറുതാണല്ലോ; അങ്ങനെ എന്റെ ജീവൻ നിലനില്ക്കട്ടെ.","p":1},{"v":21,"t":"അവൻ അയാളോടു പറഞ്ഞു: ശരി, അക്കാര്യവും ഞാൻ അംഗീകരിക്കുന്നു. നീ പറഞ്ഞ പട്ടണം നശിപ്പിക്കുന്നത് ഞാൻ ഒഴിവാക്കിയിരിക്കുന്നു.","p":1},{"v":22,"t":"വേഗമാവട്ടെ; അങ്ങോട്ട് ഓടിരക്ഷപ്പെടുക. നീ അവിടെയെത്തുംവരെ എനിക്കൊന്നും ചെയ്യാനാവില്ലല്ലോ. അങ്ങനെ, ആ പട്ടണത്തിന് സോവാർ എന്നു പേരുണ്ടായി.സോദോം-ഗൊമോറായുടെ നാശം"},{"v":23,"t":"ലോത്ത് സോവാറിൽ എത്തിയപ്പോഴേക്കും ഭൂമിയുടെമേൽ സൂര്യൻ ഉദിച്ചിരുന്നു."},{"v":24,"t":"കർത്താവ് സോദോമിന്റെമേലും ഗൊമോറായുടെമേലും ആകാശത്തിൽനിന്ന്, കർത്താവിന്റെ പക്കൽനിന്ന്, ഗന്ധകവും അഗ്നിയും വർഷിച്ചു.","p":1},{"v":25,"t":"ആ പട്ടണങ്ങളെയും സമതലമുഴൂവനയും പട്ടണവാസികളേവരെയം മണ്ണിൽ മുളച്ചവയെയും അവിടന്ന് ഉന്മൂലനം ചെയ്തു."},{"v":26,"t":"അയാളുടെ ഭാര്യ പിന്നിൽനിന്ന് തിരിഞ്ഞുനോക്കി; അവൾ ഒരു ഉപ്പുതൂണാവുകയും ചെയ്തു.","p":1},{"v":27,"t":"അബ്രാഹം അതിരാവിലെ എഴുന്നേറ്റ്, കർത്താവിന്റെ മുമ്പിൽ താൻ നിന്ന സ്ഥലത്തേക്ക് ചെന്നു.","p":1},{"v":28,"t":"അവൻ സൊദോമിന്റെയുംഗൊമോറായുടെയും സമതലപ്രദേശം മുഴുവന്റെയും നേർക്ക് താഴേക്കുനോക്കി. ഇതാ, തീച്ചൂളയിലെ പുകയെന്നപോലെ ആ പ്രദേശത്തുനിന്നെല്ലാം പുക ഉയരുന്നത് അവൻ കണ്ടു. മോവാബ്യർ, അമ്മോന്യർ","p":1},{"v":29,"t":"ദൈവം സമതലപ്രദേശങ്ങളിലെ നഗരങ്ങൾ നശിപ്പിച്ചപ്പോൾ അബ്രാഹത്തെ ഓർത്തു. അതിനാൽ ലോത്ത് പാർത്തിരുന്ന നഗരങ്ങളെ ഉന്മൂലനം ചെയ്തപ്പോൾ വിനാശത്തിന്റെ നടുവിൽനിന്ന് ദൈവം ലോത്തിനെ ഒഴിവാക്കി."},{"v":30,"t":"സോവാറിൽ പാർക്കാൻ ഭയമായിരുന്നതുകൊണ്ട്, ലോത്ത് സോവാറിൽനിന്ന് മലയിൽ കയറി പാർത്തു. അവന്റെ രണ്ടു പുത്രിമാരും അവനോടൊപ്പം ഉണ്ടായിരുന്നു. അവനും അവന്റെ രണ്ടു പുത്രിമാരും ഒരു ഗുഹയിൽ പാർത്തു.","p":1},{"v":31,"t":"മൂത്തവൾ ഇളയവളോടു പറഞ്ഞു: നമ്മുടെ പിതാവിനു പ്രായമായി. നാട്ടുനടപ്പനുസരിച്ച് നമ്മെ പ്രാപിക്കാൻ ഒരു പുരുഷനും ഭൂമിയിലില്ല.","p":1},{"v":32,"t":"വരൂ, നമ്മുടെ പിതാവിനെ വീഞ്ഞുകുടിപ്പിച്ച് നമുക്ക് അവനോടൊന്നിച്ച് ശയിക്കാം; അങ്ങനെ നമുക്ക് നമ്മുടെ പിതാവിൽനിന്ന് സന്തതിയെ നിലനിർത്താം.","p":1},{"v":33,"t":"ആ രാത്രി അവർ തങ്ങളുടെ പിതാവിനെ വീഞ്ഞുകുടിപ്പിച്ചു; മൂത്തവൾ ചെന്ന് തന്റെ പിതാവിനോടുകൂടെ ശയിച്ചു. അവൾ കിടന്നപ്പോഴോ എഴുന്നേറ്റപ്പോഴോ അവൻ അറിഞ്ഞില്ല.","p":1},{"v":34,"t":"പിറ്റേന്ന് മൂത്തവൾ ഇളയവളോടു പറഞ്ഞു: നോക്കൂ, ഇന്നലെ ഞാൻ എന്റെ പിതാവിനോടുകൂടെ ശയിച്ചു. ഇന്നു രാത്രിയും നമുക്കവനെ വീഞ്ഞുകുടിപ്പിക്കാം. എന്നിട്ട്, നീ ചെന്ന് അവനോടുകൂടെ ശയിക്കുക. അങ്ങനെ നമുക്ക് നമ്മുടെ പിതാവിൽനിന്ന് സന്തതിയെ നിലനിർത്താം.","p":1},{"v":35,"t":"ആ രാത്രിയും അവർ തങ്ങളുടെ പിതാവിനെ വീഞ്ഞുകുടിപ്പിച്ചു. ഇളയവൾ എഴൂന്നേറ്റ് അവനോടുകൂടെ ശയിച്ചു. അവൾ കിടന്നപ്പോഴോ എഴുന്നേറ്റപ്പോഴോ അവൻ അറിഞ്ഞില്ല.","p":1},{"v":36,"t":"അങ്ങനെ ലോത്തിന്റെ രണ്ടു പുത്രിമാരും തങ്ങളുടെപിതാവിൽനിന്ന് ഗർഭംധരിച്ചു.","p":1},{"v":37,"t":"മൂത്തവൾ ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ മോവാബ് എന്ന് അവനു പേരിട്ടു. ഇന്നുവരെയും അവനെയാണ് മോവാബു കാരുടെ പിതാവായി കരുതുന്നത്.","p":1},{"v":38,"t":"ഇളയവളും ഒരു പുത്രനെ പ്രസവിച്ചു അവൾ അവന് ബെൻ - അമ്മി എന്ന് പേരിട്ടു ഇന്നുവരെയും അവനെയാണ് അമ്മോന്യരുടെ പിതാവായി കരുതുന്നത്","p":1}],"20":[{"h":"അബ്രഹവും അബിമെലെക്കും"},{"v":1,"t":"അബ്രഹാം അവിടെനിന്ന് നെഗേബ്പ്രദേശത്തേക്ക് യാത്രതിരിച്ച് കാദെഷിനുംഷൂറിനും ഇടയ്ക്ക് വാസമുറപ്പിച്ചു. അവൻ ഗരാറിൽ പ്രവാസിയായിക്കഴിഞ്ഞു. '","p":1},{"v":2,"t":"അബ്രഹാം ഭാര്യ സാറാ യെക്കുറിച്ച്, 'അവൾ എന്റെ സഹോദരിയാണ്' എന്നത്രെ പറഞ്ഞത്. ഗരാറിലെ രാജാവായ അബിമെലെക് സാറായെ വരുത്തി, സ്വന്തമാക്കി."},{"v":3,"t":"ആ രാത്രി സ്വപ്നത്തിൽ ദൈവം അബിമെലെക്കിനെ സമീപിച്ച് അവനോടു പറഞ്ഞു: നോക്കൂ, നീ സ്വന്തമാക്കിയിരിക്കുന്നസ്ത്രീനിമിത്തം നീ മരിക്കും. അവൾ ഭർത്തൃമതിയാണ്.","p":1},{"v":4,"t":"'അബിമെലെക് അവളെ സമീപിച്ചിട്ടില്ലായിരുന്നു. അവൻ ചോദിച്ചു: പ്രഭോ, നീതിനിഷ്ഠമായ ഒരു ജനതയെയും അങ്ങ് വധിക്കുമോ?","p":1},{"v":5,"t":"അവൾ എന്റെ സഹോദരിയാണ് എന്ന് അവൻതന്നെയല്ലേ എന്നോട് പറഞ്ഞത്? അവൻ എന്റെ സഹോദരനാണെന്ന് അവളും പറഞ്ഞു. പരമാർത്ഥഹൃദയത്തോടും നിർമലകരങ്ങളോടുകൂടിയുമാണ് ഞാൻ ഇതു ചെയ്തത്.","p":1},{"v":6,"t":"അപ്പോൾ ദൈവം അവനോടു സ്വപ്നത്തിൽ അരുളിച്ചെയ്തു: പരമാർത്ഥഹൃദയത്തോടെയാണ് നീ ഇതു ചെയ്തതെന്ന് എനിക്കും അറിയാം. എനിക്കെതിരായി പാപം ചെയ്യുന്നതിൽനിന്ന് ഞാൻ തന്നെയാണ് നിന്നെ തടഞ്ഞത്. അതുകൊണ്ടാണ് അവളെ തൊടാൻ നിന്നെ ഞാൻ അനുവദിക്കാതിരുന്നത്.","p":1},{"v":7,"t":"'ഇപ്പോൾ ആ മനുഷ്യന്റെ ഭാര്യയെ തിരിച്ചേല്പിക്കുക. കാരണം, അവൻ ഒരു പ്രവാചകനാണ്. അവൻ നിനക്കുവേണ്ടി പ്രാർത്ഥിക്കും, നീ ജീവിക്കുകയും ചെയ്യും; തിരിച്ചേല്പിക്കാത്തപക്ഷം, നീയും നിനക്കുള്ളവരോക്കെയും തീർച്ചയായും മരിക്കും എന്നറിഞ്ഞുകൊള്ളുക.","p":1},{"v":8,"t":"അബിമെലെക് അതിരാവിലെ എഴുന്നേറ്റ് തന്റെ സേവകരെമുഴുവൻ വിളിച്ച് ഇക്കാര്യങ്ങളെല്ലാം അവർ കേൾക്കെ വിവരിച്ചു; ആ ആളുകൾ ഏറെ ഭയപ്പെട്ടു.","p":1},{"v":9,"t":"അബിമെലെക് അബ്രഹാത്തെ വിളിച്ച് അവനോടു ചോദിച്ചു: നീ എന്താണു ഞങ്ങളോട് ചെയ്തത്? നിനക്കെതിരായി ഞാൻ എന്തു തെറ്റുവരുത്തിയിട്ടാണ് എന്റെയും എന്റെ രാജ്യത്തിന്റെ യുംമേൽ ഇത്ര വലിയ പാപം വരുത്തിവെച്ചത്? ചെയ്യരുതാത്ത പ്രവൃത്തികളാണ് നീ എന്നോട് ചെയ്തിരിക്കുന്നത്.","p":1},{"v":10,"t":"അബിമെലെക് അബ്രഹാമോട് വീണ്ടും ചോദിച്ചു: എന്തു കണ്ടിട്ടാണ് നീ ഇക്കാര്യം ചെയ്തത്?","p":1},{"v":11,"t":"അബ്രഹാം പ്രത്യുത്തരിച്ചു: ഈ നാട്ടിൽ ദൈവഭയംതീരെയില്ലെന്നും എന്റെ ഭാര്യനിമിത്തം അവർ എന്നെ കൊല്ലുമെന്നും ഞാൻ കരുതി.","p":1},{"v":12,"t":"വാസ്തവത്തിൽ, അവൾ എന്റെ സഹോദരിതന്നെയാണ് - എന്റെ പിതാവിന്റെ മകളത്രെ; പക്ഷേ, എന്റെ മാതാവിന്റെ മകളല്ല; അവൾ എനിക്കു ഭാര്യയുമായി.","p":1},{"v":13,"t":"എന്റെ പിതൃഭവനത്തിൽനിന്ന് ഇറങ്ങിപ്പുറപ്പെടാൻ ദൈവം എനിക്ക് ഇടവരുത്തിയപ്പോൾ ഞാൻ അവളോട് പറഞ്ഞു: നീ എന്നോടു കാണിക്കേണ്ട കാരുണ്യം ഇതാണ്: നമ്മൾ പോകുന്ന ദേശത്തെല്ലാം, 'ഇവൻ എന്റെ സഹോദരനാണ്' എന്ന് എന്നെക്കുറിച്ച് നീ പറയണം."},{"v":14,"t":"അപ്പോൾഅബിമെലെക് ആടുകളെയും ദാസന്മാരെയും പരിചാരിക്കാരെയും കൊണ്ടുവന്ന് അബ്രഹാമിനു കൊടുത്തു; അവന് ഭാര്യ സാറായെ തിരിച്ചുനൽകുകകയും ചെയ്തു."},{"v":15,"t":"അബിമെലെക് പറഞ്ഞു: ഇതാ, എന്റെ നാട് നിന്റെ മുമ്പിൽ; നിന്റെ ദൃഷ്ടികളിൽ നല്ല ഇടത്ത് പാർത്തുക്കൊള്ളുക.","p":1},{"v":16,"t":"സാറായോട് അവൻ പറഞ്ഞു: ഇതാ, ആയിരം വെള്ളിനാണയം നിന്റെ സഹോദരനു ഞാൻ കൊടുക്കുന്നു. അത് നിന്നോടൊപ്പുമുള്ളവർക്കും മറ്റെല്ലാവർക്കും, നിന്നെ സംബന്ധിച്ച്, നൈർമല്യത്തിനുള്ള സാക്ഷ്യം ആയിരിക്കും. നീ നിർദോഷയാണ്.","p":1},{"v":17,"t":"\"അബ്രഹാം ദൈവത്തോട് പ്രാർത്ഥിച്ചു; ദൈവം അബിമെലെക്കിനെയും അവന്റെ ഭാര്യയെയും അവന്റെ ദാസിമാരെയും സൗഖ്യപ്പെടുത്തി, അവർക്ക് സന്താനങ്ങൾ ജനിക്കുകയും ചെയ്തു. \"എന്തെന്നാൽ, അബ്രഹാമിന്റെ ഭാര്യ സാറായുടെ കാര്യത്തെപ്രതി കർത്താവ് അബിമെലെക്കിന്റെ അന്തപുരത്തിലെ ഓരോ ഗർഭപാത്രവും തീർത്തും അടച്ചി രുന്നു.","p":1}],"21":[{"h":"ഇസഹാക്കിന്റെ ജനനം"},{"v":1,"t":"അരുൾചെയ്തിരുന്നതുപോലെ കർത്താവ് സാറായെ സന്ദർശിച്ചു. കർത്താവ് അറിയിച്ചിരുന്നതുപോലെ സാറായോട് വർത്തിക്കുകയും ചെയ്തു.","p":1},{"v":2,"t":"ദൈവം അബ്രാഹത്തെ അറിയിച്ചിരുന്ന നിശ്ചിതസമയത്ത് സാറാ ഗർഭംധരിച്ചു; അവന്റെ വാർധക്യത്തിൽ, അവൾ ഒരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":3,"t":"അബ്രാഹം തനിക്കു ജനിച്ച പുത്രന്, സാറാ പ്രസവിച്ച പുത്രന്, ഇസഹാക്ക് എന്നു പേരിട്ടു.","p":1},{"v":4,"t":"ദൈവം അബ്രാഹത്തോടു കല്പിച്ചിരുന്നതുപോലെ, അവൻ തന്റെ പുത്രൻ ഇസഹാക്കിന് എട്ടാം ദിവസം പരിച്ഛേദനം നടത്തി.","p":1},{"v":5,"t":"പുത്രൻ ഇസഹാക്ക് ജനിച്ചപ്പോൾ അബ്രാഹത്തിന് നൂറ് വയസ്സായിരുന്നു.","p":1},{"v":6,"t":"സാറാ പറഞ്ഞു: ദൈവം എനിക്കു ചിരി ഉളവാക്കിയിരിക്കുന്നു; കേൾക്കുന്നവരെല്ലാം എന്നെപ്രതി ചിരിക്കും.","p":1},{"v":7,"t":"അവൾ തുടർന്നു: സാറാ കുഞ്ഞുങ്ങളെ മുലയൂട്ടുമെന്ന് ആരെങ്കിലും അബ്രാഹത്തോടു പറയുമായിരുന്നോ? എന്നാൽ ഞാൻ അവന്റെ വാർദ്ധക്യത്തിൽ ഒരു പുത്രനെ പ്രസവിച്ചിരിക്കുന്നു.","p":1},{"h":"ഇശ്മായേൽ പുറന്തള്ളപ്പെടുന്നു"},{"v":8,"t":"കുഞ്ഞ് വളർന്ന് മുലകുടിമാറി; ഇസഹാക്കിനെ മുലകുടിമാറ്റിയ ദിവസം അബ്രാഹം വലിയൊരു വിരുന്നുനടത്തി.","p":1},{"v":9,"t":"ഈജിപ്തുകാരി ഹാഗാറിന്റെ പുത്രനെ, അബ്രാഹത്തിനായി അവൾ ജന്മംകൊടുത്തവനെ, സാറാ കണ്ടു; അവൻ കളിക്കുകയായിരുന്നു.","p":1},{"v":10,"t":"അവൾ അബ്രാഹത്തോടു പറഞ്ഞു: ആ അടിമപ്പെണ്ണിനെയും അവളുടെ മകനെയും ഇറക്കിവിടുക. എന്റെ മകനോടൊപ്പം, ഇസഹാക്കിനോടൊപ്പം, ആ അടിമപ്പെണ്ണിന്റെ മകൻ അവകാശിയാകാൻ പാടില്ല.","p":1},{"v":11,"t":"തന്റെ പുത്രനെസംബന്ധിച്ച ഇക്കാര്യം അബ്രാഹത്തിന്റെ ദൃഷ്ടികളിൽ ഏറെ സങ്കടകരമായിരുന്നു.","p":1},{"v":12,"t":"എന്നാൽ, ദൈവം അബ്രാഹത്തോട് അരുൾചെയ്തു: കുട്ടിയെക്കുറിച്ചും നിന്റെ ദാസിയെക്കുറിച്ചും സാറാ നിന്നോടു പറയുന്നതൊന്നും നിന്റെ ദൃഷ്ടികളിൽ സങ്കടകരമാകാതിരിക്കട്ടെ. അവളുടെ സ്വരം നീ ശ്രവിക്കുക. കാരണം, നിന്റെ സന്തതി അറിയപ്പെടുന്നത് ഇസഹാക്കിലൂടെയായിരിക്കും.","p":1},{"v":13,"t":"ദാസിയുടെ പുത്രനെയും ഞാനൊരു ജനതയാക്കും; കാരണം, അവനും നിന്റെ സന്തതിയാണല്ലോ.","p":1},{"v":14,"t":"അബ്രാഹം അതിരാവിലെ എഴുന്നേറ്റ് അപ്പവും വെള്ളംനിറച്ച തുകൽസഞ്ചിയുമെടുത്ത് ഹാഗാറിനു നൽകി; കുട്ടിയെ തോളിൽ വച്ചുകൊടുത്ത് അവളെ പറഞ്ഞയച്ചു. അവൾ ബേർഷെബാ മരുപ്രദേശത്ത് അലഞ്ഞുനടന്നു.","p":1},{"v":15,"t":"തുകൽസഞ്ചിയിലെ വെള്ളം തീർന്നപ്പോൾ അവൾ കുട്ടിയെ കുറ്റിച്ചെടികളിലൊന്നിന്റെ ചുവട്ടിൽ ഉപേക്ഷിച്ചു.","p":1},{"v":16,"t":"കുട്ടിയുടെ മരണം ഞാൻ കാണാതിരിക്കട്ടെ എന്നു പറഞ്ഞ് അവൾ ഒരു അമ്പെയ്യത്തുദൂരം മാറി എതിർവശത്തേക്കു തിരിഞ്ഞിരുന്നു. അവിടെയിരുന്ന് അവൾ സ്വരമുയർത്തി കരഞ്ഞു.","p":1},{"v":17,"t":"അപ്പോൾ കുട്ടിയുടെ സ്വരം ദൈവം കേട്ടു. ദൈവത്തിന്റെ ദൂതൻ ആകാശത്തുനിന്ന് ഹാഗാറിനെ വിളിച്ച് അവളോടു ചോദിച്ചു: ഹാഗാർ, നിനക്കെന്തുപറ്റി? നീ ഭയപ്പെടേണ്ട. എന്തെന്നാൽ, ദൈവം കുട്ടിയുടെ സ്വരം, അവൻ ആയിരിക്കുന്ന ഇടത്തുനിന്ന്, കേട്ടിരിക്കുന്നു."},{"v":18,"t":"നീ എഴുന്നേറ്റ് കുട്ടിയെ എടുക്കുക; നിന്റെ കരംകൊണ്ട് അവനെ മുറുകെപ്പിടിക്കുക. ഞാൻ അവനെ വലിയൊരു ജനതയാക്കും.","p":1},{"v":19,"t":"ദൈവം അവളുടെ കണ്ണുതുറന്നു; അവൾ വെള്ളമുള്ള ഒരു കിണർ കണ്ടു. അവൾ ചെന്ന് തുകൽസഞ്ചിയിൽ വെള്ളംനിറച്ച്, കുട്ടിക്കു കുടിക്കാൻ കൊടുത്തു."},{"v":20,"t":"ദൈവം ആ കുട്ടിയോടുകൂടെയുണ്ടായിരുന്നു. അവൻ വളർന്നു; മരുഭൂമിയിൽ പാർത്തു; സമർത്ഥനായ വില്ലാളിയായിത്തീർന്നു.","p":1},{"v":21,"t":"അവൻ പാരാൻമരുഭൂമിയിൽ പാർത്തു. അവന്റെ അമ്മ അവനുവേണ്ടി ഈജിപ്തുദേശത്തുനിന്ന് ഒരു ഭാര്യയെ കണ്ടെത്തി.","p":1},{"h":"അബ്രാഹവും അബിമെലെക്കും തമ്മിലുള്ള ഉടമ്പടി"},{"v":22,"t":"അക്കാലത്ത് അബിമെലെക്കും അവന്റെ സൈന്യാധിപൻ ഫിക്കോലും അബ്രാഹത്തോട് ഇപ്രകാരം പറഞ്ഞു: നീ ചെയ്യുന്നതിലെല്ലാം ദൈവം നിന്നോടുകൂടെയുണ്ട്.","p":1},{"v":23,"t":"നീ എന്നോടും എന്റെ അനന്തരഗാമിയോടും പിൻതലമുറക്കാരോടും വ്യാജമായി വർത്തിക്കുകയില്ലെന്ന് ഇപ്പോൾ ദൈവത്തെക്കൊണ്ട് ഇവിടെവച്ച് എന്നോട് ശപഥം ചെയ്യണം. ഞാൻ നിന്നോടു ചെയ്ത കാരുണ്യ മനുസരിച്ച് എന്നോടും നീ പ്രവാസിയായി പാർத்துவരുന്ന ഈ നാടിനോടും പ്രവർത്തിക്കണം.","p":1},{"v":24,"t":"ഞാൻ ശപഥം ചെയ്യുന്നു, അബ്രാഹം പറഞ്ഞു.","p":1},{"v":25,"t":"പിന്നീട് അബിമെലെക്കിന്റെ ദാസന്മാർ പിടിച്ചെടുത്ത വെള്ളമുള്ള കിണറിനെ സംബന്ധിച്ച് അബ്രാഹം അബിമെലെക്കിനെ കുറ്റപ്പെടുത്തി.","p":1},{"v":26,"t":"അപ്പോൾ അബിമെലെക് പറഞ്ഞു: ആരാണ് ഇക്കാര്യം ചെയ്തതെന്ന് എനിക്കറിഞ്ഞുകൂടാ; നീയാകട്ടെ, എന്നെ അറിയിച്ചതുമില്ല; ഇന്നല്ലാതെ ഞാൻ ഇതേക്കുറിച്ചു കേട്ടിട്ടുമില്ല.","p":1},{"v":27,"t":"അബ്രാഹം അബിമെലെക്കിന് ആടാടുകളെ കൊണ്ടുവന്നുകൊടുത്തു; അവരിരുവരും ഒരു ഉടമ്പടിയുണ്ടാക്കി.","p":1},{"v":28,"t":"അബ്രാഹം ആട്ടിൻപറ്റത്തിലെ ഏഴു പെണ്ണാടുകളെ മാറ്റിനിർത്തി.","p":1},{"v":29,"t":"അബിമെലെക് അബ്രാഹത്തോടു ചോദിച്ചു: നീ മാറ്റിനിർത്തിയിരിക്കുന്ന ഈ ഏഴു പെണ്ണാടുകളുടെ അർത്ഥമെന്ത്?","p":1},{"v":30,"t":"അവൻ പറഞ്ഞു: ഈ ഏഴു പെണ്ണാടുകളെ എന്റെ കരങ്ങളിൽനിന്ന് സ്വീകരിക്കുകവഴി, ഞാനാണ് ഈ കിണർ കുഴിച്ചത് എന്നതിന് നീ തന്നെയായിരിക്കും എനിക്കുള്ള സാക്ഷി.","p":1},{"v":31,"t":"ആ സ്ഥലത്തിന് ബേർഷെബാ എന്നു പേരായി; കാരണം, അവിടെവച്ച് അവർ രണ്ടുപേരും ശപഥം ചെയ്തു.","p":1},{"v":32,"t":"അങ്ങനെ ബേർഷെബായിൽ വച്ച് അവർ ഒരു ഉടമ്പടിയുണ്ടാക്കി. അനന്തരം അബിമെലെകും സൈനാധിപനായ ഫിക്കോളും എഴുന്നേറ്റ് ഫിലിസ്ത്യരുടെ നാട്ടിലേക്കു തിരിച്ചുപോയി","p":1},{"v":33,"t":"അബ്രഹാം ബേർഷെബായിൽ ഒരു ഭാനുകവൃക്ഷം നട്ടുപിടിപ്പിക്കുകയും അവിടെവച്ച് കർത്താവിനെ നിത്യനായ ദൈവം എന്ന് വിളിക്കുകയും ചെയ്തു","p":1},{"v":33,"t":"32 അബ്രഹാം ഫിലിസ്ത്യരുടെ നാട്ടിൽ വളരെ കാലം വിപ്രവാസിയായിരുന്നു.","p":1}],"22":[{"h":"അബ്രാഹത്തിന്റെ ബലി"},{"v":1,"t":"ഈ സംഭവങ്ങൾക്കുശേഷം ദൈവം അബ്രാഹത്തെ പരീക്ഷിച്ചു. അവിടുന്ന് അവനെ വിളിച്ചു: അബ്രാഹം! 'ഇതാ ഞാൻ' അവൻ മറുപടി പറഞ്ഞു.","p":1},{"v":2,"t":"അവിടുന്നു പറഞ്ഞു: നിന്റെ പുത്രൻ, നീ സ്നേഹിക്കുന്ന നിന്റെ ഏകപുത്രൻ ഇസഹാക്കിനെ കൂട്ടിക്കൊണ്ട് മോരിയാദേശത്തേക്കു പോവുക. അവിടെ ഞാൻ നിന്നോടു പറയുന്ന മലകളിലൊന്നിന്റെ മുകളിൽ നീ അവനെ ഹോമയാഗമായി അർപ്പിക്കണം.","p":1},{"v":3,"t":"അബ്രാഹം അതിരാവിലെ ഉണർന്ന് കഴുതയ്ക്കു ജിനിയിട്ട് തന്നോടൊപ്പം രണ്ടു ബാല്യക്കാരെയും മകൻ ഇസഹാക്കിനെയുംകൂട്ടി ഹോമയാഗത്തിനുവേണ്ട വിറകും കീറി ദൈവം അവനോടു പറഞ്ഞ സ്ഥലത്തേക്ക് നടന്നുനീങ്ങി.","p":1},{"v":4,"t":"മൂന്നാംദിവസം അബ്രാഹം തന്റെ കണ്ണുകളുയർത്തി അകലെനിന്ന് ആ സ്ഥലം കണ്ടു.","p":1},{"v":5,"t":"തന്റെ ബാല്യക്കാരോട് അബ്രാഹം പറഞ്ഞു: കഴുതയുമായി നിങ്ങൾ ഇവിടെ തങ്ങുക. ഞാനും കുട്ടിയും അവിടം വരെ പോയി ആരാധിച്ചിട്ട് നിങ്ങളുടെ അടുത്തേക്ക് തിരിച്ചുവരാം.","p":1},{"v":6,"t":"അബ്രാഹം ഹോമയാഗത്തിനുള്ള വിറകെടുത്ത് മകൻ ഇസഹാക്കിന്റെമേൽ വെച്ചു കൊടുത്തു; തീയും കത്തിയും തന്റെ കയ്യിലും എടുത്തു. അവരിരുവരും ഒരുമിച്ചുനടന്നു.","p":1},{"v":7,"t":"ഇസഹാക്ക് തന്റെ പിതാവായ അബ്രാഹത്തോടു സംസാരിച്ചുതുടങ്ങി. എന്റെ പിതാവേ, എന്ന് അവൻ വിളിച്ചു. ഇതാ ഞാൻ, എന്റെ മകനേ! അവൻ വിളികേട്ടു. അവൻ ചോദിച്ചു: ഇതാ, തീയും വിറകും; എന്നാൽ, ദഹനബലിക്കുള്ള കുഞ്ഞാടെവിടെ?","p":1},{"v":8,"t":"അബ്രാഹം മറുപടി പറഞ്ഞു: എന്റെ മകനേ, ഹോമയാഗത്തിനുള്ള കുഞ്ഞാടിന്റെ കാര്യം ദൈവം തന്നെ നോക്കിക്കൊള്ളും. അവരിരുവരും ഒരുമിച്ചു നടന്നു.","p":1},{"v":9,"t":"ദൈവം അവനോടു പറഞ്ഞിരുന്ന സ്ഥലത്ത് അവരെത്തിയപ്പോൾ, അബ്രാഹം അവിടെ ബലിപീഠം പണിത്, വിറകടുക്കി; തന്റെ പുത്രൻ ഇസഹാക്കിനെ ബന്ധിച്ച് ബലിപീഠത്തിൽ വിറകിനുമേൽ കിടത്തി.","p":1},{"v":10,"t":"മകനെ ബലികഴിക്കാൻ അബ്രാഹം കൈനീട്ടി കത്തിയെടുത്തു.","p":1},{"v":11,"t":"എന്നാൽ, കർത്താവിന്റെ ദൂതൻ ആകാശത്തുനിന്ന് അവനെ വിളിച്ചു: അബ്രാഹം, അബ്രാഹം! 'ഇതാ ഞാൻ' അവൻ മറുപടിപറഞ്ഞു.","p":1},{"v":12,"t":"ദൂതൻ പറഞ്ഞു: കുട്ടിയുടെമേൽ കൈവെക്കരുത്; അവനെ ഒന്നും ചെയ്യരുത്. കാരണം, നീ ദൈവഭയമുള്ളവനാണെന്ന് ഇപ്പോൾ ഞാൻ അറിയുന്നു; നിന്റെ ഒരേയൊരു പുത്രനെ നീ എന്നിൽനിന്ന് ഒഴിവാക്കിയില്ല.","p":1},{"v":13,"t":"അബ്രാഹം തന്റെ കണ്ണുകളുയർത്തി നോക്കി. ഇതാ, പുറകിലായി കൂറ്റിച്ചെടികൾക്കിടയിൽ കൊമ്പ് കുടുങ്ങിക്കിടക്കുന്ന മൂട്ടാട്! അബ്രാഹം ചെന്ന് ആ മൂട്ടാടിനെയെടുത്ത് തന്റെ മകനുപകരം ഹോമയാഗമർപ്പിച്ചു.","p":1},{"v":14,"t":"അബ്രാഹം ആ സ്ഥലത്തിന് യാഹ്‌വെ-യിരെ എന്ന് പേരിട്ടു. അതാണ് കർത്താവിന്റെ മലയിൽ അവിടുന്ന് പ്രത്യക്ഷപ്പെടും എന്ന് ഇന്ന് പറയപ്പെടുന്നത്.","p":1},{"v":15,"t":"കർത്താവിന്റെ ദൂതൻ ആകാശത്തുനിന്ന് രണ്ടാമതും അബ്രാഹത്തെ വിളിച്ചു.","p":1},{"v":16,"t":"അവൻ പറഞ്ഞു: ഞാൻ എന്നെക്കൊണ്ട് ശപഥചെയ്യുന്നു, കർത്താവിന്റെ അരുളപ്പാട്: നിന്റെ ഒരേയൊരു പുത്രനെ ഒഴിവാക്കാതെ നീ ഇക്കാര്യം ചെയ്തയാൽ","p":1},{"v":17,"t":"ഞാൻ നിന്നെ തീർച്ചയായും അനുഗ്രഹിക്കും. നിന്റെ സന്തതിയെ ആകാശത്തിലെ നക്ഷത്രങ്ങൾപോലെയും കടൽത്തീരത്തെ മണൽത്തരികൾപോലെയും നിശ്ചയമായും ഞാൻ വർദ്ധിപ്പിക്കും. നിന്റെ സന്തതി ശത്രുക്കളുടെ കവാടം കൈവശപ്പെടുത്തും.","p":1},{"v":18,"t":"നീ എന്റെ സ്വരം ശ്രവിച്ചതുകൊണ്ട്, നിന്റെ സന്തതിമുഖാന്തരം ഭൂമിയിലെ എല്ലാ ജനതകളും തങ്ങളെത്തന്നെ അനുഗ്രഹിക്കും."},{"v":19,"t":"അബ്രാഹം തന്റെ ബാല്യക്കാരുടെ അടുത്ത് മടങ്ങിയെത്തി, അവർ എഴുനേറ്റ് ബേർഷെബായിലേക്ക് ഒരുമിച്ചുനടന്നു. അബ്രാഹം ബേർഷെബായിൽ പാർത്തു.","p":1},{"v":20,"t":"ഈ സംഭവങ്ങൾക്കുശേഷം അബ്രാഹത്തിന് ഇപ്രകാരം സന്ദേശം ലഭിച്ചു: ഇതാ, മിൽക്കായും നിന്റെ സഹോദരൻ നാഹോറിന് സന്താനങ്ങളെ പ്രസവിച്ചിരിക്കുന്നു.","p":1},{"v":21,"t":"അവർ ആദ്യജാതനായ ഊസ്, അവന്റെ സഹോദരൻ ബൂസ്, ആരാമിന്റെ പിതാവായ കെമൂവേൽ,","p":1},{"v":22,"t":"കേസെദ്, ഹാസോ, പിൽദാഷ്, ഇത്ലാഫ്, ബത്തൂവേൽ എന്നിവരാണ്.","p":1},{"v":23,"t":"ബത്തൂവേലാണ് റബേക്കായെ ജനിപ്പിച്ചത്. അബ്രാഹത്തിന്റെ സഹോദരനായ നാഹോറിന് മിൽക്കായിലുണ്ടായവരാണ് അവർ എട്ടുപേരും.","p":1},{"v":24,"t":"കൂടാതെ, റവൂമാ എന്നുപേരുള്ള അവന്റെ ഉപനാരിയും തേബഹ്, ഗഹം, തഹഷ്, മാക്കാഹ് എന്നിവരെ പ്രസവിച്ചു.","p":1}],"23":[{"h":"സാറായുടെ മരണം"},{"v":1,"t":"സാറാ നൂറ്റ ഇരുപത്തേഴു വർഷം ജീവിച്ചിരുന്നു; അതാണ് സാറായുടെ ജീവിതകാലം.","p":1},{"v":2,"t":"കിരിയാത്ത് അർബായിൽവെച്ച്, അതായത് കാനാൻദേശത്തുള്ള ഹെബ്രോനിൽവെച്ച്, സാറാ മരിച്ചു. സാറായെപ്രതി വിലപിക്കാനും കരയാനും അബ്രാഹം എത്തി.","p":1},{"v":3,"t":"മരിച്ചവളുടെ അടുക്കൽനിന്ന് എഴുന്നേറ്റ് അബ്രാഹം ഹിത്യരോട് ഇപ്രകാരം പറഞ്ഞു:","p":1},{"v":4,"t":"ഞാൻ നിങ്ങളുടെ ഇടയിൽ പ്രവാസിയും കുടികിടപ്പുകാരനുമാണ്. നിങ്ങളുടെ ഇടയിൽ ഉടമാവകാശത്തോടുകൂടിയ ഒരു ശ്മശാനം എനിക്ക് തരുക; എന്റെ മരിച്ചവളെ എന്റെ മുമ്പിൽനിന്ന് ഞാൻ മറവുചെയ്യട്ടെ."},{"v":5,"t":"ഹിത്യർ അബ്രാഹത്തോടു മറുപടിയായി ഇങ്ങനെ പറഞ്ഞു:","p":1},{"v":6,"t":"യജമാനനേ, ഞങ്ങളെ കേട്ടാലും. അങ്ങു ഞങ്ങളുടെയിടയിലെ ശക്തനായ പ്രഭുവാണ്. അങ്ങയുടെ മരിച്ചവളെ ഞങ്ങളുടെ ഏറ്റവും നല്ല കബറിടത്തിൽ അടക്കിക്കൊള്ളുക. ഞങ്ങളിൽ ഒരുവൻപോലും തന്റെ കബറിടം അങ്ങയുടെ മരിച്ചവളെ അടക്കാൻ അങ്ങേക്കു നിഷേധിക്കില്ല.","p":1},{"v":7,"t":"അബ്രാഹം എഴുന്നേറ്റ് നാട്ടുകാരായ ഹിത്യരെ വണങ്ങി.","p":1},{"v":8,"t":"അവൻ അവരോട് ഇപ്രകാരം പറഞ്ഞു: എന്റെ മരിച്ചവളെ സംസ്‌കരിക്കുന്നതിന് നിങ്ങൾക്കു മനസ്സുണ്ടെങ്കിൽ, എന്നെ ശ്രവിച്ച് സോഹാറിന്റെ പുത്രനായ എഫ്രോനെ എനിക്കുവേണ്ടി പോയിക്കാണണം.","p":1},{"v":9,"t":"അവന്റെ പറമ്പിന്റെ അതിർത്തിയിൽ അവനുള്ള മക്‌പെലാഗുഹ എനിക്കു നൽകട്ടെ; നിങ്ങളുടെയിടയിൽ ഉടമാവകാശത്തോടുകൂടിയ ഒരു കബറിടമായി എനിക്ക് മുഴുവൻവിലയ്ക്കും അവൻ അതു തരട്ടെ.","p":1},{"v":10,"t":"ഹിത്യരുടെ ഇടയിൽത്തന്നെ എഫ്രോൺ ഇരിപ്പുണ്ടായിരുന്നു. ഹിത്യരും തന്റെ നഗരവാതില്ക്കൽ വന്ന എല്ലാവരും കേൾക്കേ ഹിത്യനായ എഫ്രോൺ അബ്രാഹത്തോട് ഇങ്ങനെ പ്രതിവചിച്ചു:","p":1},{"v":11,"t":"അങ്ങനെയല്ല, പ്രഭോ, എന്നെ ശ്രവിച്ചാലും. ആ പറമ്പ് അങ്ങേക്കു ഞാൻ സമ്മാനിക്കുന്നു, അതിലുള്ള ഗുഹയും അങ്ങേക്ക് ഞാൻ തരുന്നു; എന്റെ ജനത്തിന്റെ കൺമുമ്പിൽവെച്ച് അങ്ങേക്കു ഞാനത് തരുന്നു. അങ്ങയുടെ മരിച്ചവളെ അടക്കിക്കൊള്ളുക.","p":1},{"v":12,"t":"അബ്രാഹം നാട്ടുകാർക്കു മുമ്പിൽ വണങ്ങി.","p":1},{"v":13,"t":"നാട്ടുകാർ കേൾക്കേ അവൻ എഫ്രോണോട് ഇങ്ങനെ പറഞ്ഞു: ദയവായി എന്നെ കേട്ടാലും; ഞാൻ പറമ്പിന്റെ വില തരുന്നു. എന്നിൽനിന്ന് സ്വീകരിച്ചാലും. എന്റെ മരിച്ചവളെ അവിടെ ഞാൻ സംസ്‌കരിക്കട്ടെ.","p":1},{"v":14,"t":"എഫ്രോൻ അബ്രാഹത്തോടു മറുപടിയായി പറഞ്ഞു:","p":1},{"v":15,"t":"പ്രഭോ, എന്നെ ശ്രവിച്ചാലും. നാനൂറു ഷെക്കൽ വെള്ളിയുടെ ഒരു തുണ്ടുഭൂമിയെന്നത് എനിക്കും അങ്ങയ്ക്കുമിടയിൽ എന്താണ്? അങ്ങയുടെ മരിച്ചവളെ സംസ്‌കരിച്ചുകൊള്ളുക.","p":1},{"v":16,"t":"അബ്രാഹം എഫ്രോനെ ശ്രവിച്ചു. ഹിത്യർ കേൾക്കേ എഫ്രോൻ പറഞ്ഞ നാനൂറു ഷെക്കൽ വെള്ളി, കച്ചവടക്കാരുടെയിടയിലെ നടപ്പനുസരിച്ച്, അബ്രാഹം എഫ്രോനിനു തൂക്കിക്കൊടുത്തു.","p":1},{"v":17,"t":"അങ്ങനെ അവൻ മമ്രേക്ക് അടുത്ത് മക്‌പെലയിലുള്ള എഫ്രോന്റെ പറമ്പും അവിടെയുണ്ടായിരുന്ന ഗുഹയും, പറമ്പിലും അതിന്റെ ചുറ്റുമതിലിലുമുള്ള എല്ലാ വൃക്ഷങ്ങളുമടക്കം കരാറുറപ്പിച്ചു;","p":1},{"v":18,"t":"ഹിത്യരുടെയും നഗരവാതിൽക്കൽ വന്നവരുടെയും സമക്ഷം അബ്രാഹത്തിന് അത് അവകാശമായിത്തീർന്നു.","p":1},{"v":19,"t":"അതിനുശേഷം അബ്രാഹം തന്റെ ഭാര്യ സാറായെ മമ്രേക്കു മുമ്പിൽ മക്‌പെലയിലെ പറമ്പിലുള്ള ഗുഹയിൽ, അതായത് കാനാൻദേശത്തെ ഹെബ്രോനിൽ, സംസ്‌കരിച്ചു.","p":1},{"v":20,"t":"അങ്ങനെ ആ പറമ്പും അതിലെ ഗുഹയും ഹിത്യരിൽനിന്ന് തനിക്ക് ഉടമാവകാശമുള്ള കബറിടമായി അബ്രാഹം ഉറപ്പിച്ചു.","p":1}],"24":[{"h":"ഇസഹാക്കും റബേക്കായും"},{"v":1,"t":"അബ്രാഹം പ്രായംചെന്ന്, വൃദ്ധനായി. കർത്താവ് എല്ലാറ്റിലും അബ്രാഹത്തെ അനുഗ്രഹിച്ചു.","p":1},{"v":2,"t":"തനിക്കുള്ള എല്ലാറ്റിന്റെയും കാര്യസ്ഥനായ തന്റെ ഭവനത്തിലെ മുതിർന്ന ഭൃത്യനോട് അബ്രാഹം പറഞ്ഞു: നിന്റെ കൈ എന്റെ തുടയുടെകീഴെ വയ്ക്കുക.","p":1},{"v":3,"t":"ഞാൻ പാർക്കുന്ന ഈ നാട്ടിലെ കാനാൻകാരുടെ പെൺമക്കളിൽനിന്ന് എന്റെ പുത്രനു ഭാര്യയെ തിരഞ്ഞെടുക്കുകയില്ലെന്ന് ആകാശത്തിന്റെ ദൈവവും ഭൂമിയുടെ ദൈവവുമായ കർത്താവിനെക്കൊണ്ട് നിന്നെ ഞാൻ സത്യംചെയ്യിക്കുന്നു.","p":1},{"v":4,"t":"എന്റെ നാട്ടിൽ, എന്റെ സഹജരുടെയടുക്കൽ ചെന്ന്, എന്റെ പുത്രൻ ഇസഹാക്കിന് നീ ഭാര്യയെ കൊണ്ടുവരണം.","p":1},{"v":5,"t":"അപ്പോൾ ആ ദാസൻ അവനോടു ചോദിച്ചു: ഒരുപക്ഷേ, ആ സ്ത്രീ എന്റെപിന്നാലെ ഈ നാട്ടിലേക്ക് വരാൻ തയ്യാറല്ലെങ്കിൽ അങ്ങു പുറപ്പെട്ടുപോന്ന ആ നാട്ടിലേക്ക് അങ്ങയുടെ പുത്രനെ ഞാൻ ഉറപ്പായും തിരിച്ചു കൊണ്ടുപോകണമോ?"},{"v":6,"t":"അബ്രാഹം അവനോടു പറഞ്ഞു: എന്റെ പുത്രനെ ഒരിക്കലും അങ്ങോട്ടു തിരിച്ചു കൊണ്ടുപോകാതിരിക്കാൻ നീ ശ്രദ്ധിക്കണം.","p":1},{"v":7,"t":"എന്റെ പിതൃഭവനത്തിൽനിന്നും ജന്മനാട്ടിൽനിന്നും എന്നെ കൊണ്ടുവന്നവനും എന്നോടു സംസാരിച്ചവനും നിന്റെ സന്തതിക്കു ഈ നാട് ഞാൻ നൽകുമെന്നു എന്നോടു വാഗ്ദാനം ചെയ്തവനുമായ ആകാശത്തിന്റെ ദൈവമായ കർത്താവുതന്നെ തന്റെ ദൂതനെ നിനക്കു മുമ്പെ അയയ്ക്കും; നീ അവിടെനിന്നു എന്റെ പുത്രന്നു ഒരു സ്ത്രീയെ കൊണ്ടുവരണം."},{"v":8,"t":"എന്നാൽ, ആ സ്ത്രീ നിന്റെ പിന്നാലെ വരാൻ തയ്യാറല്ലെങ്കിൽ എന്റെ ഈ ശപഥത്തിൽനിന്നു നീ മുക്തനായിരിക്കും; എന്റെ പുത്രനെ അങ്ങോട്ടു മടക്കരുതെന്നുമാത്രം.","p":1},{"v":9,"t":"അപ്പോൾ ഭൃത്യൻ തന്റെ യജമാനനായ അബ്രാഹാമിന്റെ തുടയുടെകീഴെ തന്റെ കൈവെച്ചു ആ കാര്യത്തെപ്രതി സത്യം ചെയ്തു.","p":1},{"v":10,"t":"അനന്തരം, ഭൃത്യൻ യജമാനന്റെ ഒട്ടകങ്ങളിൽനിന്നു പത്തു ഒട്ടകങ്ങളെയും കൊണ്ടു യാത്രയ്ക്കൊരുങ്ങി. യജമാനന്റെ എല്ലാ വിശിഷ്ടവസ്തുക്കളും അവന്റെ കൈവശമുണ്ടായിരുന്നു. അവൻ എഴുന്നേറ്റു നാഹോറിന്റെ പട്ടണമായ അറംനഹറായിമിലേക്കു പോയി.","p":1},{"v":11,"t":"സായംകാലത്തു, വെള്ളംകോരുന്നവർ വരുന്ന സമയത്തു അവൻ ഒട്ടകങ്ങളെ പട്ടണത്തിനുവെളിയിൽ വെള്ളമുള്ള ഒരു കിണറിനടുത്തു കിടത്തി.","p":1},{"v":12,"t":"എന്നിട്ടു, അവൻ പ്രാർത്ഥിച്ചു: എന്റെ യജമാനനായ അബ്രാഹാമിന്റെ ദൈവമായ കർത്താവേ, ഇന്ന് എനിക്കു ഇതു സാധിച്ചുതരേണമേ. എന്റെ യജമാനനായ അബ്രാഹത്തോടു കരുണചെയ്യേണമേ.","p":1},{"v":13,"t":"ഇതാ, ഞാൻ നീരുറയ്ക്കരുകിൽ നിൽക്കുകയാണ്; നഗരത്തിലെ ആളുകളുടെ പെൺകുട്ടികൾ വെള്ളംകോരാൻ പുറപ്പെട്ടിട്ടുണ്ട്.","p":1},{"v":14,"t":"എനിക്കു കുടിക്കാനായി നിന്റെ കുടം ചായ്ച്ചുതരിക എന്നു ഞാൻ പറയുമ്പോൾ, 'കുടിച്ചുകൊള്ളുക; നിന്റെ ഒട്ടകങ്ങൾക്കും ഞാൻ കുടിക്കാൻ കൊടുക്കാം' എന്നു ഏതു പെൺകുട്ടി പറയുന്നുവോ, അവളായിരിക്കും അങ്ങയുടെ ദാസനായ ഇസഹാക്കിനുവേണ്ടി അങ്ങ് നിശ്ചയിച്ചിട്ടുള്ളവൾ. എന്റെ യജമാനനോടു അങ്ങ് കരുണചെയ്തിരിക്കുന്നുവെന്നു അവൾമൂലം ഞാൻ അറിയും.","p":1},{"v":15,"t":"അവൻ പറഞ്ഞുതീരുംമുമ്പ്, ഇതാ, അബ്രാഹാമിന്റെ സഹോദരൻ നാഹോറിന്റെ ഭാര്യ മില്ക്കായുടെ പുത്രൻ ബെത്തൂവേലിനു ജനിച്ചവളായ റബേക്കാ വരുന്നു! അവളുടെ തോളിൽ ഒരു കുടമുണ്ടായിരുന്നു.","p":1},{"v":16,"t":"ആ പെൺകുട്ടി കാണാൻ അതിസുന്ദരിയും കന്യകയും പുരുഷനെ അറിയാത്തവളുമായിരുന്നു. അവൾ ഉറവയിലേക്കിറങ്ങി തന്റെ കുടംനിറച്ചു കയറിവന്നു.","p":1},{"v":17,"t":"ആ ഭൃത്യൻ അപ്പോൾ അവളുടെ അടുത്തെത്താൻ ഓടി. അവൻ പറഞ്ഞു: ദയവായി നിന്റെ കുടത്തിൽനിന്നു കുറച്ചു വെള്ളം എനിക്കു കുടിക്കാൻ തരിക.","p":1},{"v":18,"t":"പ്രഭോ, കുടിച്ചാലും, അവൾ പറഞ്ഞു.തിടുക്കത്തിൽ കുടം തന്റെ കരത്തിലേക്ക് താഴ്ത്തി അവൾ അവനു് കുടിക്കാൻ കൊടുത്തു.","p":1},{"v":19,"t":"അവൻ കുടിച്ചുകഴിഞ്ഞപ്പോൾ അവൾ പറഞ്ഞു: താങ്കളുടെ ഒട്ടകങ്ങൾക്കും അവ കുടിച്ചു തീരുവോളം ഞാൻ വെള്ളം കോരാം.","p":1},{"v":20,"t":"അവൾ വേഗം വെള്ളം തൊട്ടിയിലേക്കു പകർന്നു; വെള്ളംകോരാൻ വീണ്ടും കിണറ്റിലേക്കോടി; അവന്റെ ഒട്ടകങ്ങൾക്കെല്ലാം വെള്ളംകോരി."},{"v":21,"t":"അവൻ അവളെ സാകൂതം നോക്കിനിന്നു; തന്റെ വഴി കർത്താവു ശുഭമാക്കിയോ ഇല്ലയോ എന്നറിയാൻ അയാൾ നിശ്ശബ്ദനായിരുന്നു.","p":1},{"v":22,"t":"ഒട്ടകങ്ങൾ കുടിച്ചു കഴിഞ്ഞപ്പോൾ, അവൻ അവൾക്കുവേണ്ടി അര ഷെക്കെൽ തൂക്കമുള്ള ഒരു സ്വർണ്ണമൂക്കുത്തിയും പത്തു സ്വർണ്ണത്തൂക്കമുള്ള രണ്ടു കൈവളകളും എടുത്തു."},{"v":23,"t":"അവൻ പറഞ്ഞു: നീ ആരുടെ മകളാണെന്ന് എന്നെ അറിയിച്ചാലും. നിന്റെ പിതാവിന്റെ ഭവനത്തിൽ ഞങ്ങൾക്കു രാപാർക്കാൻ ഇടം കാണുമോ?","p":1},{"v":24,"t":"അവൾ അവനോടു പറഞ്ഞു: നാഹോറിനായി മില്ക്കാ പ്രസവിച്ച പുത്രൻ ബെത്തൂവേലിന്റെ മകളാണു് ഞാൻ.","p":1},{"v":25,"t":"അവൾ വീണ്ടും പറഞ്ഞു: ഞങ്ങളുടെ പക്കൽ വൈക്കോലും തീറ്റയും വേണ്ടുവോളമുണ്ട്; താമസിക്കാൻ ഇടവുമുണ്ടു്.","p":1},{"v":26,"t":"അയാൾ കുമ്പിട്ടു കർത്താവിനെ ആരാധിച്ചു.","p":1},{"v":27,"t":"എന്നിട്ടു പറഞ്ഞു: എന്റെ യജമാനനായ അബ്രാഹാമിന്റെ ദൈവമായ കർത്താവ് വാഴ്ത്തപ്പെട്ടവനാകട്ടെ! തന്റെ കാരുണ്യവും വിശ്വസ്തതയും അവിടുന്ന് എന്റെ യജമാനനിൽനിന്നു പിൻവലിച്ചിട്ടില്ല. എന്നെയാകട്ടെ, എന്റെ യജമാനന്റെ സഹോദരങ്ങളുടെ ഭവനത്തിലേക്ക് കർത്താവു് വഴിനയിക്കുകയും ചെയ്തിരിക്കുന്നു.","p":1},{"v":28,"t":"പെൺകുട്ടി ഓടിച്ചെന്നു തന്റെ അമ്മയുടെ വീട്ടുകാരെ ഇക്കാര്യങ്ങൾ യഥാക്രമം ധരിപ്പിച്ചു.","p":1},{"v":29,"t":"റബേക്കായ്ക്കു് ലാബാൻ എന്നു പേരുള്ള ഒരു സഹോദരനുണ്ടായിരുന്നു. ലാബാൻ പുറത്തു് ഉറവയുടെ അരികിലേക്ക്, ആ മനുഷ്യന്റെ അടുത്തേക്കു് ഓടി.","p":1},{"v":30,"t":"മൂക്കുത്തിയും വളകളും തന്റെ സഹോദരി റബേക്കായുടെ കൈകളിൽ കാണുകയും ആ മനുഷ്യൻ എന്നോടിങ്ങനെ സംസാരിച്ചു എന്ന അവളുടെ വാക്കുകൾ കേൾക്കുകയും ചെയ്തപ്പോൾ, അവൻ ആ മനുഷ്യന്റെ അടുത്തേക്കു ചെന്നു; അതാ, അയാൾ ഒട്ടകങ്ങളുടെ സമീപത്തു ഉറവയ്ക്കരികിൽ നിൽക്കുകയായിരുന്നു.","p":1},{"v":31,"t":"അവൻ പറഞ്ഞു: കർത്താവിനാൽ അനുഗൃഹീതനേ, വരിക. എന്താണു പുറത്തുനിൽക്കുന്നത്? വീടും ഒട്ടകങ്ങൾക്കുള്ള സ്ഥലവും ഞാൻ തന്നെ ഒരുക്കിയിട്ടുണ്ടു്.","p":1},{"v":32,"t":"അയാൾ വീട്ടിലേക്കു വന്നു. അവൻ ഒട്ടകങ്ങളെ അഴിച്ചുവിട്ടു ഒട്ടകങ്ങൾക്കു കച്ചിയും തീറ്റയും കൊടുത്തു; ഒപ്പം, അയാളുടെ കാലുകളും കൂടെയുള്ള ആളുകളുടെ കാലുകളും കഴുകാൻ വെള്ളവും.","p":1},{"v":33,"t":"എന്റെ മുമ്പിൽ ഭക്ഷണം വിളമ്പവേ, അയാൾ പറഞ്ഞു: എന്റെ ദൗത്യം പറയാതെ ഞാൻ ഭക്ഷണം കഴിക്കുകയില്ല. പറഞ്ഞുകൊള്ളുക, അവൻ പറഞ്ഞു.","p":1},{"v":34,"t":"അപ്പോൾ അയാൾ പറഞ്ഞു: അബ്രാഹത്തിന്റെ ഭൃത്യനാണു ഞാൻ.","p":1},{"v":35,"t":"കർത്താവ് എന്റെ യജമാനനെ സമൃദ്ധമായി അനുഗ്രഹിച്ചിരിക്കുന്നു. അദ്ദേഹം വലിയവനായിത്തീർന്നിരിക്കുന്നു. ആടുമാടുകളെയും വെള്ളിയും സ്വർണവും ദാസന്മാരെയും പരിചാരികമാരെയും ഒട്ടകങ്ങളെയും കഴുതകളെയും അവിടുന്ന് അദ്ദേഹത്തിനു കൊടുത്തിരിക്കുന്നു."},{"v":36,"t":"എന്റെ യജമാനന്റെ ഭാര്യ സാറാ അവളുടെ വാർദ്ധക്യത്തിൽ എന്റെ യജമാനന് ഒരു പുത്രനെ പ്രസവിച്ചു. തനിക്കുള്ളതെല്ലാം അദ്ദേഹം അവനാണു കൊടുത്തിരിക്കുന്നത്.","p":1},{"v":37,"t":"എന്റെ യജമാനൻ എന്നെക്കൊണ്ട് ഇങ്ങനെ സത്യംചെയ്യിച്ചിരിക്കുകയാണ്: ഞാൻ പാർക്കുന്ന നാട്ടിലെ കാനാൻകാരുടെ പുത്രിമാരിൽനിന്ന് എന്റെ മകന് വധുവിനെ നീ തിരഞ്ഞെടുക്കരുത്.","p":1},{"v":38,"t":"മറിച്ച്, എന്റെ പിതൃഭവനത്തിൽ, എന്റെ വംശക്കാരുടെപക്കൽ ചെന്ന് എന്റെ പുത്രന് ഭാര്യയെ കൊണ്ടുവരണം.","p":1},{"v":39,"t":"ഞാൻ എന്റെ യജമാനനോടു ചോദിച്ചു: ഒരുവേള, ആ സ്ത്രീ എന്റെ പിന്നാലെ വന്നില്ലെങ്കിലോ?","p":1},{"v":40,"t":"അദ്ദേഹം എന്നോടു പറഞ്ഞു: ഞാൻ ആരുടെ മുമ്പിൽ വ്യാപരിക്കുന്നുവോ ആ കർത്താവ് തന്റെ ദൂതനെ നിന്റെകൂടെ അയച്ച് നിന്റെ വഴി ശുഭമാക്കും. എന്റെ വംശക്കാരിൽനിന്ന്, എന്റെ പിതൃഭവനത്തിൽനിന്ന് എന്റെ പുത്രന് നീ ഒരു സ്ത്രീയെ കൊണ്ടുവരുകതന്നെ ചെയ്യും.","p":1},{"v":41,"t":"എന്റെ വംശജരുടെ അടുത്തു ചെല്ലുന്നതുകൊണ്ടുതന്നെ നീ എന്റെ പ്രതിജ്ഞയിൽനിന്ന് വിമുക്തനാകും. അവർ അവളെ നിനക്ക് വിട്ടുതന്നില്ലെങ്കിലും എന്റെ പ്രതിജ്ഞയിൽനിന്ന് നീ വിമുക്തനായിരിക്കും.","p":1},{"v":42,"t":"ഇന്ന് ഞാൻ ഉറവയ്ക്കരികിൽ വന്നപ്പോൾ പറഞ്ഞു: എന്റെ യജമാനനായ അബ്രാഹത്തിന്റെ ദൈവമായ കർത്താവേ, ഞാൻ സഞ്ചരിക്കുന്ന വഴി ശുഭമാക്കാൻ അങ്ങ് മനസ്സാകുന്നുവെങ്കിൽ,","p":1},{"v":43,"t":"ഇതാ, ഞാൻ ഈ നീരുറവയ്ക്കരികിൽ നിൽക്കുന്നു. വെള്ളംകോരാൻ വരുന്ന യുവതിയോട്, ദയവായി നിന്റെ കുടത്തിൽനിന്ന് എനിക്കല്പം വെള്ളം കുടിക്കാൻതരുക എന്ന് ഞാൻ പറയുമ്പോൾ,","p":1},{"v":44,"t":"കുടിച്ചുകൊള്ളുക; താങ്കളുടെ ഒട്ടകങ്ങൾക്കും ഞാൻ വെള്ളം കോരാം എന്ന് എന്നോടു പറയുന്നവളായിരിക്കും എന്റെ യജമാനന്റെ പുത്രന് കർത്താവ് നിശ്ചയിച്ചിട്ടുള്ള ഭാര്യ.","p":1},{"v":45,"t":"എന്റെ ഉള്ളിൽ ഞാനിതു പറഞ്ഞു...","p":1},{"v":45,"t":"വലതു വശം:","p":1},{"v":45,"t":"തീരുംമുമ്പ് ഇതാ, തോളിൽ കുടവുമായി റബേക്കാ പുറത്തേക്കു വരുന്നു; അവൾ ഉറവിൽ ഇറങ്ങിച്ചെന്ന് വെള്ളംകോരി. ഞാൻ അവളോട്, ദയവായി എനിക്ക് കുടിക്കാൻ തരുക എന്നുപറഞ്ഞു.","p":1},{"v":46,"t":"അവൾ ഉടനെ കുടം താഴ്ത്തിവെച്ചുകൊണ്ടു പറഞ്ഞു: കുടിച്ചോളൂ; താങ്കളുടെ ഒട്ടകങ്ങൾക്കും ഞാൻ കുടിക്കാൻ കൊടുക്കാം. ഞാൻ കുടിച്ചു; ഒട്ടകങ്ങൾക്കും അവൾ കുടിക്കാൻ കൊടുത്തു.","p":1},{"v":47,"t":"അപ്പോൾ, ഞാൻ അവളോട് അന്വേഷണാർഥംനീ ആരുടെ മകളാണ് എന്ന് ചോദിച്ചു. നാഹോറിന് മിൽക്കാ പ്രസവിച്ച പുത്രനായ ബത്തൂവേലിന്റെ മകളാണു ഞാൻ എന്ന് അവൾ പറഞ്ഞു. അപ്പോൾ ഞാൻ അവളുടെ മൂക്കിൽ മൂക്കുത്തിയും കൈകളിൽ വളകളും അണിയിച്ചു.","p":1},{"v":48,"t":"അതിനുശേഷം ഞാൻ കുമ്പിട്ടു കർത്താവിനെ ആരാധിച്ചു; എന്റെ യജമാനനായ അബ്രാഹത്തിന്റെ ദൈവമായ കർത്താവിനെ ഞാൻ വാഴ്ത്തി. കാരണം, എന്റെ യജമാനന്റെ സഹോദരപുത്രിയെ അദ്ദേഹത്തിന്റെ പുത്രനുവേണ്ടി കൊണ്ടുവരാൻ അവിടുന്ന് എന്നെ നേരായ മാർഗ്ഗത്തിൽ നയിച്ചു.","p":1},{"v":49,"t":"ഇപ്പോൾ അതുകൊണ്ട് എന്റെ യജമാനനോടു നിങ്ങൾ കാരുണ്യത്തോടെയും വിശ്വസ്തതയോടെയും പെരുമാറുമെങ്കിൽ എന്നോടു പറയുക; മറിച്ചാണെങ്കിലും എന്നോടു പറയുക. എനിക്ക് വലത്തോട്ടോ ഇടത്തോട്ടോ തിരിയാമല്ലോ.","p":1},{"v":50,"t":"അപ്പോൾ ലാബാനും ബത്തൂവേലും മറുപടിയായി പറഞ്ഞു: ഇക്കാര്യം കർത്താവിൽനിന്ന് വന്നതാണ്. ഞങ്ങൾക്ക് നിന്നോട് ദോഷമോ ഗുണമോ പറയാനാവില്ല.","p":1},{"v":51,"t":"ഇതാ, റബേക്കാ നിന്റെ മുമ്പിൽ; കൊണ്ടുപോയ്ക്കൊള്ളുക. കർത്താവ് അരുൾചെയ്തതുപോലെ അവൾ നിന്റെ യജമാനന്റെ മകനു ഭാര്യയാകട്ടെ.","p":1},{"v":52,"t":"അവരുടെ വാക്കുകൾ കേട്ടപ്പോൾ അബ്രാഹത്തിന്റെ ഭൃത്യൻ കർത്താവിനെ നിലംപറ്റെ വണങ്ങി.","p":1},{"v":53,"t":"അനന്തരം, ആ ഭൃത്യൻ വെള്ളിയാഭരണങ്ങളും സ്വർണ്ണാഭരണങ്ങളും വസ്ത്രങ്ങളും പുറത്തെടുത്ത് റബേക്കായ്ക്കു കൊടുത്തു; വിലപിടിപ്പുള്ള വസ്തുക്കൾ അവൻ അവളുടെ സഹോദരനും അമ്മയ്ക്കും കൊടുത്തു.","p":1},{"v":54,"t":"അവനും കൂടെയുണ്ടായിരുന്നവരും ഭക്ഷിക്കുകയും പാനംചെയ്യുകയും അവിടെ രാപ്പാർക്കുകയും ചെയ്തു; പുലർച്ചെ എഴുന്നേറ്റ് അവൻ പറഞ്ഞു: എന്റെ യജമാനന്റെ അടുത്തേക്ക് എന്നെ പറഞ്ഞയച്ചാലും.","p":1},{"v":55,"t":"അവളുടെ സഹോദരനും അമ്മയും പറഞ്ഞു: കുറച്ചുനാൾ, അല്ലെങ്കിൽ പത്തുദിവസം പെൺകുട്ടി ഞങ്ങളോടൊപ്പം പാർക്കട്ടെ. അതുകഴിഞ്ഞ് അവൾക്കു പോകാം.","p":1},{"v":56,"t":"അവൻ അവരോടു പറഞ്ഞു: എന്നെ വൈകിക്കരുത്, കർത്താവ് എന്റെ വഴി ശുഭമാക്കിയിരിക്കയാണ്","p":1},{"v":57,"t":"അവർ പറഞ്ഞു: നമുക്കു പെൺകുട്ടിയെ വിളിച്ച് അവളുടെ അഭിപ്രായംചോദിക്കാം.","p":1},{"v":58,"t":"അവർ റബേക്കായെ വിളിച്ച്, നീ ഈ മനുഷ്യനോടുകൂടെ പോകുന്നുവോ എന്നുചോദിച്ചു. ഞാൻ പോകുന്നു എന്ന് അവൾ മറുപടിപറഞ്ഞു.","p":1},{"v":59,"t":"അവർ അവരുടെ സഹോദരി റബേക്കായെയും അവളുടെ തോഴിയെയും അബ്രാഹത്തിന്റെ ഭൃത്യനെയും അവന്റെ ആളക്കാരെയും പറഞ്ഞയച്ചു.","p":1},{"v":60,"t":"റബേക്കായെ ആശീർവദിച്ചുകൊണ്ട് അവർ അവളോടു പറഞ്ഞു:","p":1},{"v":60,"t":"ഞങ്ങളുടെ സഹോദരീ,","p":1},{"v":60,"t":"നീ പതിനായിരത്തിന്റെ ആയിരങ്ങളായിത്തീരട്ടെ.","p":1},{"v":60,"t":"നിന്റെ സന്തതി, തന്നെ വെറുക്കുന്നവരുടെ കവാടം കൈവശമാക്കട്ടെ.","p":1},{"v":61,"t":"റബേക്കായും അവളുടെ ഭൃത്യകളും എഴുന്നേറ്റ് ഒട്ടകപ്പുറത്തു കയറി അയാളെ അനുഗമിച്ചു. അങ്ങനെ ആ ദാസൻ റബേക്കായെയും കൂട്ടി യാത്രയായി.","p":1},{"v":62,"t":"ആയിടയ്ക്ക് ഇസഹാക്ക് ബേർ-ല്ഹായ്-റോയിയുടെ സമീപത്തുനിന്നു വന്ന് നെഗെബ്ദേശത്തു താമസിക്കുകയായിരുന്നു.","p":1},{"v":63,"t":"വയലിൽ ധ്യാനിച്ച് സായാഹ്നം ചെലവഴിക്കാൻ ഇസഹാക്ക് പുറത്തിറങ്ങി. അവൻ ദൃഷ്ടികളുയർത്തിയപ്പോൾ കണ്ടു, ഇതാ, ഒട്ടകങ്ങൾ വരുന്നു.","p":1},{"v":64,"t":"റബേക്കാ കണ്ണുകൾ ഉയർത്തിയപ്പോൾ ഇസഹാക്കിനെ കണ്ട് ഒട്ടകപ്പുറത്തുനിന്നു വേഗമിറങ്ങി.","p":1},{"v":65,"t":"അവൾ ഭൃത്യനോടു ചോദിച്ചു: വയലിലൂടെ നമുക്കഭിമുഖമായി നടന്നുവരുന്ന ആ പുരുഷൻ ആരാണ്? ഭൃത്യൻ പറഞ്ഞു: അതെന്റെ യജമാനനാണ്. ഉടനെ അവൾ മൂടുപടമെടുത്ത് സ്വയം മറച്ചു.","p":1},{"v":66,"t":"താൻ ചെയ്ത എല്ലാക്കാര്യങ്ങളും ഭൃത്യൻ ഇസഹാക്കിനോടു വിവരിച്ചു.","p":1},{"v":67,"t":"ഇസഹാക്ക് തന്റെ അമ്മ സാറായുടെ കൂടാരത്തിലേക്കു റബേക്കായെ കൂട്ടിക്കൊണ്ടുവന്നു. അവൻ അവളെ സ്വീകരിച്ചു; അവൾ അവനു ഭാര്യയായിത്തീർന്നു. അവൻ അവളെ സ്നേഹിച്ചു. അങ്ങനെ തന്റെ അമ്മയുടെ മരണശേഷം ഇസഹാക്ക് സമാശ്വാസം കണ്ടെത്തി.","p":1}],"25":[{"h":"അബ്രാഹത്തിന്റെ ഇതരസന്തതികൾ"},{"v":1,"t":"അബ്രാഹം കെത്തൂറാ എന്നു പേരുള്ള ഒരു സ്ത്രീയെക്കൂടി വിവാഹം ചെയ്തിരുന്നു.","p":1},{"v":2,"t":"സിമ്രാൻ, യോക്ഷാൻ, മെദാൻ, മിദിയാൻ, ഇഷ്ബാക്ക്, ഷൂവാഹ് എന്നിവരെ അവൾ പ്രസവിച്ചു.","p":1},{"v":3,"t":"യോക്ഷാൻ ഷെബാനും ദെദാനും ജന്മംകൊടുത്തു. ദെദാന്റെ സന്തതികളായിരുന്നു അശ്ശൂറിം, ലത്തൂഷിം, ലവൂമിം എന്നിവർ,","p":1},{"v":4,"t":"മിദിയാന്റെ സന്തതികൾ ഏഫാ, ഏഫെർ, ഹനോക്, അബീദാ, എൽദായാ എന്നിവരാണ്; ഇവരെല്ലാവരുമായിരുന്നു കെത്തൂറായുടെ സന്തതികൾ.","p":1},{"v":5,"t":"അബ്രാഹം തനിക്കുണ്ടായിരുന്നതെല്ലാം ഇസഹാക്കിനു കൊടുത്തു;","p":1},{"v":6,"t":"തന്റെ ഉപനാരികളിലുണ്ടായ മക്കൾക്കും അബ്രാഹം സമ്മാനങ്ങൾ നൽകി; അവൻ ജീവിച്ചിരിക്കുമ്പോൾത്തന്നെ അവരെയെല്ലാം തന്റെ മകനായ ഇസഹാക്കിൽനിന്നു ദൂരെ കിഴക്കൻദേശത്തേക്ക് പറഞ്ഞയച്ചു.അബ്രാഹത്തിന്റെ മരണം","p":1},{"v":7,"t":"അബ്രാഹം പൂർത്തിയാക്കിയ ആയുഷ്‌കാലം നൂറ്റി എഴുപത്തഞ്ചുവർഷമായിരുന്നു.","p":1},{"v":8,"t":"അബ്രാഹം അന്ത്യശ്വാസം വലിച്ചു; വാർദ്ധക്യത്തിന്റെ തികവിൽ, വയോധികനും സംതൃപ്തനുമായി മരിച്ച് അവൻ തന്റെ ജനങ്ങളോട് ചേർന്നു.","p":1},{"v":9,"t":"അവന്റെ പുത്രന്മാരായ ഇസഹാക്കും ഇസ്മായേലും ഒന്നിച്ച് മമ്രേയ്ക്കടുത്ത് ഹിത്യനായ സോഹാറിന്റെ പുത്രൻ എഫ്രോന്റെ പറമ്പിലെ മക്പേലാഗുഹയിൽ അവനെ സംസ്കരിച്ചു.","p":1},{"v":10,"t":"ഹിത്യരിൽനിന്ന് അബ്രാഹം വിലയ്ക്ക് വാങ്ങിയതാണ് ആ പറമ്പ്. അവിടെയാണ് അബ്രാഹവും അവന്റെ ഭാര്യ സാറായും സംസ്കരിക്കപ്പെട്ടത്.","p":1},{"v":11,"t":"അബ്രാഹത്തിന്റെ മരണശേഷം അവന്റെ പുത്രൻ ഇസഹാക്കിനെ ദൈവം അനുഗ്രഹിച്ചു; ഇസഹാക് ബേർലഹായ്റോയിയുടെ സമീപത്ത് പാർത്തു.","p":1},{"h":"ഇസ്മായേലിന്റെ സന്തതികൾ"},{"v":12,"t":"അബ്രാഹത്തിനായി സാറായുടെ ഈജിപ്തുകാരി പരിചാരിക ഹാഗാർ പ്രസവിച്ച, അബ്രാഹത്തിന്റെ പുത്രൻ ഇസ്മായേലിന്റെ തലമുറകൾ ഇവയാണ്.","p":1},{"v":13,"t":"ജനനക്രമമനുസരിച്ച് ഇസ്മായേലിന്റെ മക്കളുടെ പേരുവിവരം: ഇസ്മായേലിന്റെ കടിഞ്ഞൂൽപുത്രനായ നെബാ യോത്ത്, കേദാർ, അദ്ബേൽ, മിബ്‌സാം,","p":1},{"v":14,"t":"മിഷ്‌മാ, ദുമാ, മസ്സാ,","p":1},{"v":15,"t":"ഹദാദ്, തേമാ, യത്തൂർ,","p":1},{"v":16,"t":"നഫീഷ്, കേദെമാ. ഇവരാണ് ഇസ്മായേലിന്റെ പുത്രന്മാർ. ഗ്രാമങ്ങളും താമസസ്ഥലങ്ങളുമനുസരിച്ച് അവരുടെ ജനതകളുടെ പന്ത്രണ്ടു പ്രഭുക്കന്മാരുടെ പേരുകളാണിവ.","p":1},{"v":17,"t":"ഇസ്മായേലിന്റെ ആയുഷ്‌കാലം നൂറ്റിമുപ്പത്തേഴു വർഷമായിരുന്നു; അവൻ അന്ത്യശ്വാസം വലിച്ച്, മറിച്ച് തന്റെ ജനങ്ങളോട് ചേർന്നു.","p":1},{"v":18,"t":"ഈജിപ്തിനുമുമ്പിൽ അസ്സീറിയായിലേക്കുള്ള ദിശയിൽ ഹവിലാമുതൽ ഷൂർവരെ അവർ കുടിപാർത്തു. അവൻ തന്റെ സഹോദരന്മാർക്കെല്ലാം മുൻപിൽ താമസിച്ചു.ഏസാവും യാക്കോബും","p":1},{"v":19,"t":"അബ്രാഹത്തിന്റെ പുത്രൻ ഇസഹാക്കിന്റെ തലമുറകൾ ഇവയാണ്; അബ്രാഹം ഇസഹാക്കിനു ജന്മം കൊടുത്തു.","p":1},{"v":20,"t":"പദാൻ ആരാമിൽനിന്നുള്ള അരാമായനായ ബെത്തൂവേലിന്റെ പുത്രിയും അരാമ്യനായ ലാബാന്റെ സഹോദരിയുമായ റബേക്കായെ ഭാര്യയായി സ്വീകരിക്കുമ്പോൾ ഇസഹാക്കിനു നാൽപതു വയസ്സായിരുന്നു.","p":1},{"v":21,"t":"ഇസഹാക് തന്റെ ഭാര്യയ്ക്കുവേണ്ടി കർത്താവിനോട് അപേക്ഷിച്ചു; കാരണം, അവൾ വന്ധ്യയായിരുന്നു. കർത്താവ് അവന്റെ യാചന കേൾക്കുകയും അവന്റെ ഭാര്യ റബേക്കാ ഗർഭംധരിക്കുകയും ചെയ്തു.","p":1},{"v":22,"t":"അവളുടെ ഉദരത്തിൽക്കിടന്ന് പുത്രന്മാർ മല്ലിട്ടപ്പോൾ അവൾ പറഞ്ഞു: ഇങ്ങനെയാണെങ്കിൽ എനിക്ക് ഇത് എന്തിനാണ്? അവൾ കർത്താവിന്റെ പക്കൽ ഇതെക്കുറിച്ച് അന്വേഷിക്കാൻ പോയി.","p":1},{"v":23,"t":"കർത്താവ് അവളോട് അരുൾചെയ്തു:","p":1},{"v":23,"t":"രണ്ടു ജാതികൾ നിന്റെ ഉദരത്തിൽ;","p":1},{"v":23,"t":"രണ്ടു ജനതകൾ നിന്റെ ഉള്ളിൽവെച്ചു വേർതിരിക്കപ്പെടും.","p":1},{"v":23,"t":"ഒരു ജനത മറ്റേ ജനതയെക്കാൾ ശക്തമാകും;","p":1},{"v":23,"t":"മൂത്തവൻ ഇളയവനെ സേവിക്കും.","p":1},{"v":24,"t":"അവളുടെ പ്രസവകാലം പൂർത്തിയായപ്പോൾ ഇതാ, അവളുടെ ഉദരത്തിൽ ഇരട്ടകൾ!","p":1},{"v":25,"t":"ഒന്നാമൻ പുറത്തുവന്നു. അവൻ ചെമന്നിരുന്നു; അവന്റെ ദേഹം മുഴുവൻ രോമക്കുപ്പായംപോലെയായിരുന്നു. അവർ അവന് ഏസാവ് എന്നു പേരിട്ടു.","p":1},{"v":26,"t":"അതിനുശേഷം അവന്റെ സഹോദരൻ പുറത്തുവന്നു. അവന്റെ കരം ഏസാവിന്റെ കുതികാലിൽ പിടിച്ചിരുന്നു. അവനെ യാക്കോബ് എന്ന് പേരുവിളിച്ചു. അവൾ അവരെ പ്രസവിച്ചപ്പോൾ ഇസഹാക്കിന് അറുപതു വയസ്സായിരുന്നു.","p":1},{"h":"ഏസാവ് കടിഞ്ഞൂലവകാശം വിൽക്കുന്നു"},{"v":27,"t":"കുട്ടികൾ വളർന്നപ്പോൾ, ഏസാവ് നായാട്ടിൽ സമർഥനും വനപ്രദേശമനുഷ്യനുമായിരുന്നു; യാക്കോബാകട്ടെ, കൂടാരങ്ങളിൽ പാർക്കുന്ന പ്രശാന്തനും.","p":1},{"v":28,"t":"നായാട്ടിറച്ചി തനിക്ക് രുചികരമാകയാൽ ഇസഹാക് ഏസാവിനെ സ്നേഹിച്ചു; എന്നാൽ, റബേക്കാ യാക്കോബിനെയാണു സ്നേഹിച്ചത്.","p":1},{"v":29,"t":"ഒരിക്കൽ, യാക്കോബ് പായസം പാചകംചെയ്യുകയായിരുന്നു. അപ്പോൾ ഏസാവ് വയലിൽനിന്നു വന്നു; അവൻ അവശനായിരുന്നു.","p":1},{"v":30,"t":"ഏസാവ് യാക്കോബിനോടു പറഞ്ഞു: ആ ചെമന്നുചെമന്നിരിക്കുന്നതിൽനിന്ന് എനിക്കു തിന്നാൻ തരുക. കാരണം, ഞാൻ അവശനായിരിക്കുന്നു. തന്മൂലം അവന് ഏദോം എന്നു പേരുണ്ടായി.","p":1},{"v":31,"t":"യാക്കോബ് പറഞ്ഞു: ഇപ്പോൾത്തന്നെ നിന്റെ കടിഞ്ഞൂലവകാശം എനിക്കു വില്ക്കുക.","p":1},{"v":32,"t":"ഏസാവ് പറഞ്ഞു: ഞാനിതാ ചാകാൻ പോകുന്നു; ഈ കടിഞ്ഞൂലവകാശം എനിക്കെന്തിന്?","p":1},{"v":33,"t":"യാക്കോബ് പറഞ്ഞു: ഇപ്പോൾത്തന്നെ എന്നോടു ശപഥംചെയ്യുക. ഏസാവ് അവനോടു ശപഥംചെയ്തു തന്റെ കടിഞ്ഞൂലവകാശം യാക്കോബിനു വിറ്റു.","p":1},{"v":34,"t":"യാക്കോബ് ഏസാവിന് അപ്പവും പയറുപായസവും നൽകി. തിന്നുകയും കുടിക്കുകയും ചെയ്തിട്ട് അവൻ എഴുന്നേറ്റുപോയി. അങ്ങനെ ഏസാവ് തന്റെ കടിഞ്ഞൂലവകാശം അവമതിച്ചു.","p":1}],"26":[{"h":"ഇസഹാക്കും അബിമെലക്കും"},{"v":1,"t":"നാട്ടിൽ ഒരു ക്ഷാമമുണ്ടായി. മുൻപൊരിക്കൽ അബ്രാഹത്തിന്റെ നാളുകളിലുണ്ടായ ക്ഷാമത്തിനുപുറമേയായിരുന്നു ഇത്. ഇസഹാക്ക് ഗരാറിലേക്ക്, ഫിലിസ്ത്യരുടെ രാജാവായ അബിമെലക്കിന്റെപക്കലേക്കു പോയി.","p":1},{"v":2,"t":"കർത്താവ് അവനു പ്രത്യക്ഷപ്പെട്ട് അരുൾചെയ്തിരുന്നു: ഈജിപ്തിലേക്ക് പോകരുത്; ഞാൻ നിന്നോടു പറയുന്ന നാട്ടിൽ കുടിപാർക്കുക.","p":1},{"v":3,"t":"ഈ നാട്ടിൽ തത്കാലവാസം ചെയ്യുക. ഞാൻ നിന്റെകൂടെയുണ്ടായിരിക്കും. നിന്നെ ഞാൻ അനുഗ്രഹിക്കുകയും ചെയ്യും. നിനക്കും നിന്റെ സന്തതിക്കുമായി ഈ ദേശമെല്ലാം ഞാൻ തരും. നിന്റെ പിതാവായ അബ്രാഹത്തോടു ചെയ്ത ശപഥം ഞാൻ ഉറപ്പിക്കും.","p":1},{"v":4,"t":"ആകാശത്തിലെ നക്ഷത്രങ്ങൾപോലെ നിന്റെ സന്തതിയെ ഞാൻ വർധിപ്പിക്കും. ഈ ദേശമെല്ലാം നിന്റെ സന്തതിക്കു ഞാൻ നൽകും. ഭൂമിയിലെ എല്ലാ ജനതകളും നിന്റെ സന്തതിയാൽ അനുഗ്രഹിക്കപ്പെടും.","p":1},{"v":5,"t":"കാരണം, അബ്രാഹം എന്റെ സ്വരം കേൾക്കുകയും എന്റെ അനുശാസനങ്ങളും കൽപനകളും പ്രമാണങ്ങളും പ്രബോധനങ്ങളും പാലിക്കുകയും ചെയ്തു.","p":1},{"v":6,"t":"അങ്ങനെ ഇസഹാക്ക് ഗരാറിൽ തന്നെ താമസിച്ചു.","p":1},{"v":7,"t":"അന്നാട്ടുകാർ അവന്റെ ഭാര്യയെക്കുറിച്ചു ചോദിച്ചപ്പോൾ, 'അവൾ എന്റെ സഹോദരിയാണ്' എന്ന് അവൻ പറഞ്ഞു. കാരണം, റബെക്കാ കാണാൻ അഴകുള്ളവളായതുകൊണ്ട് അവൾനിമിത്തം അന്നാട്ടുകാർ അവനെ കൊന്നുകളയാതിരിക്കേണ്ടതിന് 'അവൾ എന്റെ ഭാര്യയാണ്' എന്നു പറയാൻ അവൻ ഭയപ്പെട്ടു.","p":1},{"v":8,"t":"അവൻ കുറേക്കാലം അവിടെ താമസമാക്കി. ഒരിക്കൽ ഫിലിസ്ത്യരുടെ രാജാവായ അബിമെലക് ജാലകത്തിലൂടെ താഴേക്കു നോക്കിയപ്പോൾ, ഇതാ ഇസഹാക്ക് ഭാര്യ റബെക്കായെ പുണരുന്നതു കണ്ടു.","p":1},{"v":9,"t":"അബിമെലക് ഇസഹാക്കിനെ വിളിച്ചു പറഞ്ഞു: നോക്കൂ, അവൾ തീർച്ചയായും നിന്റെ ഭാര്യയാണ്. പിന്നെ എന്തുകൊണ്ടാണ്, ഇവൾ എന്റെ സഹോദരിയാണ് എന്നു നീ പറഞ്ഞത്? ഇസഹാക്ക് അവനോടു പറഞ്ഞു: അവൾമൂലം ഞാൻ മരിക്കാതിരിക്കേണ്ടതിനാണ് അങ്ങനെ പറഞ്ഞത്.","p":1},{"v":10,"t":"അബിമെലക് ചോദിച്ചു: ഇതെന്താണ് നീ ഞങ്ങളോടു ചെയ്തത്? ജനങ്ങളിലാരെങ്കിലും അബദ്ധവശാൽ നിന്റെ ഭാര്യയോടൊത്തു ശയിക്കുകയും അങ്ങനെ ഞങ്ങളുടെമേൽ നീ കുറ്റം വരുത്തുകയും ചെയ്യുമായിരുന്നു.","p":1},{"v":11,"t":"അതെത്തുടർന്ന്, അബിമെലക് എല്ലാ ജനങ്ങളോടും ഇപ്രകാരം കല്പിച്ചു: ഈ മനുഷ്യനെയോ അവന്റെ ഭാര്യയെയോ ആരെങ്കിലും തൊട്ടുപോയാൽ അവൻ നിശ്ചയമായും മരിക്കും.","p":1},{"v":12,"t":"ഇസഹാക്ക് ആ നാട്ടിൽ വിതയ്ക്കുകയും അക്കൊല്ലം തന്നെ നൂറുമേനി നേടുകയും ചെയ്തു. കർത്താവ് അവനെ അനുഗ്രഹിച്ചു.","p":1},{"v":13,"t":"അവൻ അഭിവൃദ്ധിപ്പെട്ട് വളരെ വലിയവനാകുന്നതുവരെ പടിപടിയായി വളർന്നുകൊണ്ടിരുന്നു.","p":1},{"v":14,"t":"അവന് സ്വന്തമായി ആടുമാടുകളും വലിയൊരു പരിചാരകവൃന്ദവും ഉണ്ടായിരുന്നു. അതുകൊണ്ട്, ഫിലിസ്ത്യർക്ക് അവനോട് അസൂയതോന്നി.","p":1},{"v":15,"t":"അവന്റെ പിതാവായ അബ്രാഹത്തിന്റെ കാലത്ത് പിതാവിന്റെ വേലക്കാർ കുഴിച്ച എല്ലാ കിണറുകളും ഫിലിസ്ത്യർ ഉപരോധിക്കുകയും പൂഴിയിട്ടു നികത്തുകയും ചെയ്തു.","p":1},{"v":16,"t":"അബിമെലക് ഇസഹാക്കിനോടു പറഞ്ഞു: ഞങ്ങളെ വിട്ടുപോവുക. എന്തെന്നാൽ, നീ ഞങ്ങളെക്കാൾ കൂടുതൽ ശക്തനായിരിക്കുന്നു.","p":1},{"v":17,"t":"ഇസഹാക്ക് അവിടുനിന്നു പോയി ഗരാർ നീർച്ചാലിനടുത്തു താവളമടിച്ച്, അവിടെ താമസമാക്കി.","p":1},{"v":18,"t":"തന്റെ പിതാവായ അബ്രാഹത്തിന്റെ കാലത്തു കുഴിച്ചതും അബ്രാഹത്തിന്റെ മരണശേഷം ഫിലിസ്ത്യർ ഉപരോധിച്ചതുമായ വെള്ളമുള്ള കിണറുകളെയെല്ലാം ഇസഹാക്ക് പുതുക്കിക്കുഴിച്ചു; തന്റെ പിതാവ് നൽകിയിരുന്ന പേരുകൾതന്നെ അവയ്ക്കു നൽകുകയും ചെയ്തു.","p":1},{"v":19,"t":"നീർച്ചാലിനടുത്തു കുഴിച്ചുകൊണ്ടിരിക്കേ, ഇസഹാക്കിന്റെ വേലക്കാർ നീരുറവുള്ള ഒരു കിണർ കണ്ടെത്തി.","p":1},{"v":20,"t":"അപ്പോൾ ഗരാറിലെ ഇടയന്മാർ, 'ഈ വെള്ളം ഞങ്ങളുടേതാണ്' എന്നു പറഞ്ഞ് ഇസഹാക്കിന്റെ ഇടയന്മാരുമായി തർക്കിച്ചു. അവൻ ആ വഴക്കിടിച്ചതിനാൽ അവൻ ആ കിണറിന് ഏസെക് എന്നു പേരിട്ടു.","p":1},{"v":21,"t":"അവർ മറ്റൊരു കിണർ കുഴിച്ചു. അതിനെപ്രതിയും അവർ തർക്കിച്ചു. അവൻ അതിന് സിത്നാ എന്നു വിളിച്ചു.","p":1},{"v":22,"t":"അവൻ അവിടെനിന്നു മുന്നോട്ടുനീങ്ങി വേറൊരു കിണർ കുഴിച്ചു. എന്നാൽ അതിന്റെ പേരിൽ അവർ കലഹിച്ചില്ല. അവൻ അതിന് രഹോബോത്ത് എന്നു പേരിട്ടുകൊണ്ടു പറഞ്ഞു: ഇപ്പോൾ കർത്താവ് ഞങ്ങൾക്ക് ഇടം വിശാലമാക്കിയിരിക്കുന്നതിനാൽ ഞങ്ങൾ ഭൂമിയിൽ പെരുകും.","p":1},{"v":23,"t":"അവിടെനിന്ന് അവൻ ബേർഷെബയിലേക്കു പോയി.","p":1},{"v":24,"t":"ആ രാത്രിയിൽ കർത്താവ് അവനു പ്രത്യക്ഷപ്പെട്ട് അരുൾചെയ്തു: നിന്റെ പിതാവായ അബ്രാഹത്തിന്റെ ദൈവമാണു ഞാൻ; നീ ഭയപ്പെടേണ്ട, എന്തെന്നാൽ ഞാൻ നിന്നോടുകൂടെയുണ്ട്. ഞാൻ നിന്നെ അനുഗ്രഹിക്കും; എന്റെ ദാസനായ അബ്രാഹത്തെപ്രതി നിന്റെ സന്തതിയെ ഞാൻ വർധിപ്പിക്കുകയും ചെയ്യും.","p":1},{"v":25,"t":"അവൻ അവിടെ ഒരു ബലിപീഠം പണിത്, കർത്താവിന്റെ നാമം വിളിച്ചപേക്ഷിച്ചു. അവൻ അവിടെ തന്റെ കൂടാരമടിച്ചു. ഇസഹാക്കിന്റെ ഭृत्यന്മാർ അവിടെ ഒരു കിണർ കുഴിച്ചു.","p":1},{"v":26,"t":"ഗരാറിൽനിന്ന് അബിമെലക് തന്റെ സ്നേഹിതനായ അഹുസ്സത്തും സേനാധിപനായ ഫികോളുമൊത്ത് അവന്റെ അടുത്തുചെന്നു.","p":1},{"v":27,"t":"ഇസഹാക്ക് അവരോടു ചോദിച്ചു: നിങ്ങളെന്തിനാണ് എന്റെ അടുക്കൽ വരുന്നത്? നിങ്ങൾ എന്നെ വെറുക്കുകയും നിങ്ങളുടെ ഇടയിൽനിന്ന് എന്നെ പുറത്താക്കുകയും ചെയ്തതാണല്ലോ.","p":1},{"v":28,"t":"അവർ പറഞ്ഞു: കർത്താവ് നിന്നോടുകൂടെയുണ്ടെന്ന് ഞങ്ങൾ വ്യക്തമായി കാണുന്നു. അതിനാൽ നമുക്കിടയിൽ, നിനക്കും ഞങ്ങൾക്കുമിടയിൽ, ഒരു പ്രതിജ്ഞയാകട്ടെ എന്നു ഞങ്ങൾ കരുതി. ഞങ്ങൾ നിന്നോട് ഒരു ഉടമ്പടിയുണ്ടാക്കാം.","p":1},{"v":29,"t":"ഞങ്ങൾ നിന്നെ ഉപദ്രവിക്കാതിരിക്കുകയും നിനക്കു നന്മമാത്രം ചെയ്യുകയും സമാധാനത്തിൽ നിന്നെ പറഞ്ഞയയ്ക്കുകയും ചെയ്തതുപോലെ നീയും ഞങ്ങളോടു തിന്മചെയ്യരുത്. നീ ഇപ്പോൾ കർത്താവിന്റെ അനുഗൃഹീതനാണ്.","p":1},{"v":30,"t":"അവൻ അവർക്കൊരു വിരുന്നൊരുക്കി. അവർ തിന്നുകയും കുടിക്കുകയും ചെയ്തു.","p":1},{"v":31,"t":"അവർ അതിരാവിലെ എഴുന്നേറ്റ് അന്യോന്യം ശപഥംചെയ്തു. ഇസഹാക്ക് അവരെ യാത്രയാക്കി. അവർ സമാധാനത്തോടെ അവനെ വിട്ടുപോയി.","p":1},{"v":32,"t":"അന്നുതന്നെ ഇസഹാക്കിന്റെ വേലക്കാർ വന്ന് തങ്ങൾ കുഴിച്ച കിണറിന്റെ കാര്യം അവനോടു വിവരിച്ചു: 'ഞങ്ങൾ വെള്ളം കണ്ടെത്തി' എന്ന് അവർ അവനെ അറിയിച്ചു.","p":1},{"v":33,"t":"അവൻ അതിനെ ഷേബാ എന്നു വിളിച്ചു.","p":1},{"h":"അതിനാൽ ഇന്നുവരെയും ആ പട്ടണത്തിന് ബേർഷെബാ എന്നാണ് പേര്"},{"v":34,"t":"നാല്പതു വയസ്സായപ്പോൾ ഏസാവ് ഹിത്യനായ ബേരിയുടെ പുത്രി യൂദിത്തിനെയും ഹിത്യനായ ഏലോണിന്റെ പുത്രി ബാസ്മത്തിനെയും വിവാഹം ചെയ്തു അവരാകട്ടെ ഇസഹാക്കിന്റെയും റബേക്കായുടെ മനസ്സിന് കൈയ്പായി തീർന്നു.","p":1}],"27":[{"v":1,"t":"ഇസഹാക്കിനു പ്രായമായതോടെ കണ്ണുകൾക്കു കാഴ്ചമങ്ങി. അദ്ദേഹം തന്റെ മൂത്ത മകൻ ഏസാവിനെ വിളിച്ച് അവനോടു പറഞ്ഞു: എന്റെ മകനേ. അവൻ വിളികേട്ടു: ഇതാ ഞാൻ.","p":1},{"v":2,"t":"അദ്ദേഹം പറഞ്ഞു: എനിക്കു വയസ്സായി. എന്റെ മരണദിവസം എനിക്കറിഞ്ഞുകൂടാ.","p":1},{"v":3,"t":"നിന്റെ ആയുധങ്ങളായ അമ്പും വില്ലുമെടുത്ത് വനത്തിൽ പോയി എനിക്കുവേണ്ടി ഇരയെ വേട്ടയാടുക.","p":1},{"v":4,"t":"മരിക്കുന്നതിനുമുമ്പ് എന്റെ ആത്മാവ് നിന്നെ അനുഗ്രഹിക്കേണ്ടതിന് രുചിയുള്ള ഭക്ഷണം എനിക്കിഷ്ടപ്പെട്ട രീതിയിൽ പാകംപെടുത്തി എന്റെയടുക്കൽ കൊണ്ടുവരിക; ഞാൻ ഭക്ഷിക്കട്ടെ.","p":1},{"v":5,"t":"ഇസഹാക്ക് പുത്രൻ ഏസാവിനോടു പറയുന്നത് റബെക്കാ കേൾക്കുന്നുണ്ടായിരുന്നു. ഏസാവ് വേട്ടയിറച്ചി കൊണ്ടുവരേണ്ടതിന് വയലിലേക്കു പോയി.","p":1},{"v":6,"t":"റബെക്കാ തന്റെ പുത്രൻ യാക്കോബിനോട് ഇപ്രകാരം പറഞ്ഞു: നിന്റെ പിതാവ് നിന്റെ സഹോദരൻ ഏസാവിനോട് ഇങ്ങനെ പറയുന്നതു ഇപ്പോൾ ഞാൻ കേട്ടു,","p":1},{"v":7,"t":"'എനിക്കായി വേട്ടയിറച്ചി കൊണ്ടുവന്ന് രുചികരമായ ഭക്ഷണം പാകംചെയ്യുക; ഞാൻ ഭക്ഷിച്ച്, എന്റെ മരണത്തിനുമുമ്പായി കർത്താവിന്റെ സന്നിധിയിൽ നിന്നെ അനുഗ്രഹിക്കട്ടെ'.","p":1},{"v":8,"t":"അതുകൊണ്ട്, എന്റെ മകനേ, ഞാൻ നിന്നോടു കല്പിക്കുന്നത് ഇപ്പോൾ അനുസരിക്കുക.","p":1},{"v":9,"t":"നീ ചെന്ന് ആട്ടിൻകൂട്ടത്തിൽ നിന്ന് രണ്ടു നല്ല കുഞ്ഞാടുകളെ എന്റെയടുക്കൽ പിടിച്ചുകൊണ്ടുവരിക. ഞാൻ നിന്റെ പിതാവിനുവേണ്ടി, അദ്ദേഹത്തിന് ഇഷ്ടപ്പെടുന്ന വിധത്തിൽ രുചികരമായവ പാകംചെയ്യാം.","p":1},{"v":10,"t":"നീ അത് നിന്റെ പിതാവിന്റെ അടുക്കൽ കൊണ്ടുചെല്ലണം. അപ്പോൾ അദ്ദേഹം അതു ഭക്ഷിക്കുകയും അതുവഴി മരണത്തിനുമുമ്പ് നിന്നെ അനുഗ്രഹിക്കുകയും ചെയ്യും.","p":1},{"v":11,"t":"യാക്കോബ് തന്റെ അമ്മ റബെക്കായോടു പറഞ്ഞു: നോക്കൂ, എന്റെ സഹോദരൻ ഏസാവ് രോമാവൃതനാണ്; ഞാനാകട്ടെ, രോമമില്ലാത്തവനും.","p":1},{"v":12,"t":"ഒരുപക്ഷേ, എന്റെ പിതാവ് എന്നെ തടവിനോക്കുകയും അദ്ദേഹത്തിന്റെ മുമ്പിൽ ഞാൻ പരിഹസിക്കുന്നവനെപ്പോലെ ആകുകയും ചെയ്താൽ, അനുഗ്രഹമല്ല ശാപമായിരിക്കും ഞാൻ എന്റെമേൽ വരുത്തിവെയ്ക്കുക.","p":1},{"v":13,"t":"അവന്റെ അമ്മ നോടു പറഞ്ഞു: എന്റെ മകനേ, നിന്റെ ശാപം എന്റെ മേലായിരിക്കട്ടെ! ഇപ്പോൾ എന്റെ സ്വരം ശ്രവിക്കുക. നീ പോയി അവയെ പിടിച്ചു എന്റെയടുത്തു കൊണ്ടുവരിക.","p":1},{"v":14,"t":"അവൻ പോയി അവയെ പിടിച്ചു അമ്മയുടെ അടുക്കൽ കൊണ്ടു വന്നു. അവന്റെ പിതാവിന് ഇഷ്ടപ്പെട്ട രുചികരമായ ഭക്ഷണം അവന്റെ അമ്മ തയ്യാറാക്കി.","p":1},{"v":15,"t":"റബെക്കാ തന്റെ മൂത്തമകൻ ഏസാവിന്റെതായി വീട്ടിൽ അവളുടെ പക്കൽ ഉണ്ടായിരുന്ന ഏറ്റവും നല്ല വസ്ത്രങ്ങളെടുത്ത് തന്റെ ഇളയമകൻ യാക്കോബിനെ ധരിപ്പിച്ചു;","p":1},{"v":16,"t":"ആട്ടിൻകുട്ടിയുടെ തോലുകൊണ്ട് അവന്റെ കൈകളും കഴുത്തിലെ മിനുസമുള്ള ഭാഗവും അവൾ പൊതിഞ്ഞു.","p":1},{"v":17,"t":"അവൾ പാകംചെയ്ത രുചികരമായ ഭക്ഷണവും അപ്പവും മകൻ യാക്കോബിന്റെ കൈവശം ഏൽപ്പിച്ചു.","p":1},{"v":18,"t":"അവൻ പിതാവിന്റെയടുക്കൽച്ചെന്നു വിളിച്ചു: പിതാവേ! അദ്ദേഹം വിളികേട്ടു: ഇതാ ഞാൻ; നീയാരാണ് മകനേ?","p":1},{"v":19,"t":"യാക്കോബ് തന്റെ പിതാവിനോടു പറഞ്ഞു: അങ്ങയുടെ കടിഞ്ഞൂൽപുത്രൻ ഏസാവാണ് ഞാൻ. അങ്ങ് എന്നോട് ആവശ്യപ്പെട്ടതുപോലെ ഞാൻ ചെയ്തിരിക്കുന്നു. എഴുന്നേറ്റിരുന്നാലും; അങ്ങയുടെ ആത്മാവ് എന്നെ അനുഗ്രഹിക്കേണ്ടതിന് എന്റെ വേട്ടയിറച്ചിയിൽനിന്ന് ഭക്ഷിച്ചാലും.","p":1},{"v":20,"t":"ഇസഹാക്ക് തന്റെ പുത്രനോടു ചോദിച്ചു: ഇതെങ്ങനെ എന്റെ മകനേ? ഇത്രവേഗം നിനക്ക് കണ്ടെത്താൻ കഴിഞ്ഞല്ലോ! അവൻ പറഞ്ഞു: അങ്ങയുടെ ദൈവമായ കർത്താവാണ് എനിക്കിതു സാധ്യമാക്കിയത്.","p":1},{"v":21,"t":"അപ്പോൾ ഇസഹാക്ക് യാക്കോബിനോടു പറഞ്ഞു: മകനേ, ഞാൻ നിന്നെ സ്പർശിക്കേണ്ടതിന് അടുത്തുവരിക; നീ എന്റെ മകൻ ഏസാവുതന്നെയല്ലേ?","p":1},{"v":22,"t":"യാക്കോബ് തന്റെ പിതാവായ ഇസഹാക്കിന്റെയടുത്തു ചെന്നു. അവനെ തടവിനോക്കിയിട്ട് അദ്ദേഹം പറഞ്ഞു: സ്വരം യാക്കോബിന്റെ സ്വരവും കൈകൾ ഏസാവിന്റെ കൈകളും!","p":1},{"v":23,"t":"അവന്റെ കൈകൾ സഹോദരനായ ഏസാവിന്റെ കൈകൾപോലെ രോമാവൃതമായിരുന്നതിനാൽ അദ്ദേഹം അവനെ തിരിച്ചറിഞ്ഞില്ല. അവനെ അദ്ദേഹം അനുഗ്രഹിച്ചു.","p":1},{"v":24,"t":"അദ്ദേഹം ചോദിച്ചു: എന്റെ മകൻ ഏസാവ് നീ തന്നെയോ? ഞാൻതന്നെ, അവൻ മറുപടി പറഞ്ഞു.","p":1},{"v":25,"t":"അദ്ദേഹം പറഞ്ഞു: എന്റെ മകന്റെ വേട്ടയിറച്ചിയിൽനിന്ന് ഞാൻ ഭക്ഷിച്ച്, എന്റെ ആത്മാവ് നിന്നെ അനുഗ്രഹിക്കുന്നതിനായി അത് എന്റെ അടുത്തുകൊണ്ടുവരിക. അവൻ അത് അദ്ദേഹത്തിന്റെ പക്കൽ കൊണ്ടുചെന്നു; അദ്ദേഹം ഭക്ഷിച്ചു. അവൻ അദ്ദേഹത്തിന് വീഞ്ഞും കൊണ്ടുചെന്നു; അദ്ദേഹം കുടിക്കുകയും ചെയ്തു.","p":1},{"v":26,"t":"അവൻ്റെ പിതാവായ ഇസഹാക്ക് അവനോട് പറഞ്ഞു എൻ്റെ മകനേ, നീ അടുത്തുവന്ന് എന്നെ ചുംബിക്കുക.","p":1},{"v":27,"t":"അവൻ അടുത്തൂചെന്ന് അദ്ദേഹത്തെ ചുംബിച്ചു. അവന്റെ വസ്ത്രത്തിന്റെ ഗന്ധമറിഞ്ഞിട്ട് അവനെ ആശീർവദിച്ചുകൊണ്ട് അദ്ദേഹം പറഞ്ഞു: നോക്കൂ, എന്റെ മകന്റെ ഗന്ധം കർത്താവ് അനുഗ്രഹിച്ച വയലിന്റെ ഗന്ധംപോലെ!","p":1},{"v":28,"t":"ആകാശത്തിൽനിന്നും ഭൗമഫലപുഷ്ടിയിൽനിന്നും ദൈവം നിനക്ക് നൽകട്ടെ; ധാന്യത്തിന്റെയും വീഞ്ഞിന്റെയും സമൃദ്ധിയും.","p":1},{"v":29,"t":"ജനങ്ങൾ നിന്നെ സേവിക്കട്ടെ. ജനപദങ്ങൾ നിന്നെ നമിക്കട്ടെ. നിന്റെ സഹോദരങ്ങൾക്ക് നീ അധികാരിയാകുക. നിന്റെ അമ്മയുടെ മക്കൾ നിന്നെ നമിക്കട്ടെ. നിന്നെ ശപിക്കുന്നവർ ശപ്തർ; നിന്നെ അനുഗ്രഹിക്കുന്നവർ അനുഗൃഹീതർ!","p":1},{"h":"ഏസാവ് അനുഗ്രഹം യാചിക്കുന്നു"},{"v":30,"t":"ഇസഹാക്ക് യാക്കോബിനെ അനുഗ്രഹിച്ചുകഴിഞ്ഞ് യാക്കോബ് തന്റെ പിതാവായ ഇസഹാക്കിന്റെ മുമ്പിൽനിന്നു പുറത്തുകടന്നമാത്രയിൽ അവന്റെ സഹോദരൻ ഏസാവ് നായാട്ടുകഴിഞ്ഞ് എത്തിച്ചേർന്നു.","p":1},{"v":31,"t":"അവനും രുചികരമായ ഭക്ഷണം തയ്യാറാക്കി തന്റെ പിതാവിന്റെ അടുക്കൽകൊണ്ടുവന്നിട്ട് പിതാവിനോടു പറഞ്ഞു: എന്റെ പിതാവ് എഴുന്നേറ്റ്, മകന്റെ നായാട്ടിറച്ചിയിൽ നിന്നു ഭക്ഷിക്കട്ടെ! അതുവഴി, അങ്ങയുടെ ആത്മാവ് എന്നെ അനുഗ്രഹിക്കട്ടെ.","p":1},{"v":32,"t":"നീ ആരാണ്? അവന്റെ പിതാവായ ഇസഹാക്ക് അവനോടു ചോദിച്ചു. അവൻ പറഞ്ഞു: അങ്ങയുടെ പുത്രൻ, അങ്ങയുടെ കടിഞ്ഞൂൽപുത്രൻ ഏസാവാണ് ഞാൻ.","p":1},{"v":33,"t":"ഇസഹാക്ക് സംഭ്രമിച്ചുപോയി - അതിഭീമമായ സംഭ്രമം! അവൻ ചോദിച്ചു: അപ്പോൾ, ഇരയെ നായാടി എനിക്കു കൊണ്ടുവന്ന അവൻ ആരാണ്? നീ വരുന്നതിനുമുമ്പേ ഞാൻ അതിൽനിന്നെല്ലാം ഭക്ഷിക്കുകയും അവനെ അനുഗ്രഹിക്കുകയും ചെയ്തല്ലോ. അവൻ അനുഗ്രഹിക്കപ്പെട്ടവൻതന്നെയായിരിക്കും.","p":1},{"v":34,"t":"ഏസാവ് പിതാവിന്റെ വാക്കുകൾ കേട്ടപ്പോൾ നിലവിളിച്ചു - അതിതിക്തമായ വൻനിലവിളി! അവൻ പിതാവിനോട് അപേക്ഷിച്ചു: എന്നെ അനുഗ്രഹിക്കുക, എന്റെ പിതാവേ, എന്നെയും.","p":1},{"v":35,"t":"അവൻ പറഞ്ഞു: നിന്റെ സഹോദരൻ ചതിയിൽ വന്ന് നിനക്കുള്ള അനുഗ്രഹം തട്ടിയെടുക്കുമല്ലോ.","p":1},{"v":36,"t":"ഏസാവ് പറഞ്ഞു: അതുകൊണ്ടു തന്നെയല്ലേ അവനെ യാക്കോബ് എന്നു വിളിക്കുന്നത്! ഇത് രണ്ടാംപ്രാവശ്യമാണ് അവൻ എന്റെ കുതികാൽ വെട്ടുന്നത്: എന്റെ കടിഞ്ഞൂലവകാശം അവൻ കൈക്കലാക്കി; ഇതാ ഇപ്പോൾ, എനിക്കുള്ള അനുഗ്രഹവും അവൻ തട്ടിയെടുത്തുതിരിക്കുന്നു. എനിക്കുവേണ്ടി ഒരനുഗ്രഹംപോലും അങ്ങു നീക്കിവച്ചിട്ടില്ലേ? അവൻ ചോദിച്ചു.","p":1},{"v":37,"t":"ഇസഹാക്ക് ഏസാവിനോടു മറുപടി പറഞ്ഞു: നോക്കൂ, ഞാൻ അവനെ നിന്റെ അധികാരിയായി അവരോധിച്ചിരിക്കുന്നു; അവന്റെ എല്ലാ സഹോദരങ്ങളെയും അവനു സേവകരായി ഞാൻ നൽകിയിരിക്കുന്നു. ധാന്യവും പുതുവീഞ്ഞുംകൊണ്ട് ഞാൻ അവനെ ശക്തിപ്പെടുത്തി. എന്റെ മകനേ, നിനക്കുവേണ്ടി എന്താണ് എനിക്കിനി ചെയ്യാൻ കഴിയുക?","p":1},{"v":38,"t":"അപ്പോൾ ഏസാവ് പിതാവിനോടു പറഞ്ഞു; എന്റെ പിതാവേ, ഒറ്റ അനുഗ്രഹമേ അങ്ങയുടെ പക്കലുള്ളൂ? എന്നെ അനുഗ്രഹിക്കണമേ, എന്റെ പിതാവേ, എന്നെയും. ഏസാവ് സ്വർമുയർത്തിക്കരഞ്ഞു.","p":1},{"v":39,"t":"അവന്റെ പിതാവ് ഇസഹാക്ക് അവനോട് മറുപടിയായി പറഞ്ഞു: ഇതാ! ഭൗമഫലപുഷ്ടിയിൽനിന്നും ഉന്നതാകാശത്തിന്റെ മഞ്ഞിൽനിന്നും അകലെയായിരിക്കും നിന്റെ വാസസ്ഥലം.","p":1},{"v":40,"t":"നിന്റെ വാളുകൊണ്ട് നീ ജീവിക്കും; നിന്റെ സഹോദരനെ നീ സേവിക്കും. എന്നാൽ നീ അസ്വസ്ഥനാകുമ്പോൾ അവന്റെ നുകം നിന്റെ ചുമലിൽനിന്ന് നീ തകർത്തെറിയും.","p":1},{"h":"യാക്കോബ് ലാബാന്റെ അടുക്കലേക്ക്"},{"v":41,"t":"തന്റെ പിതാവ് യാക്കോബിനെ അനുഗ്രഹിച്ചതുമൂലം ഏസാവ് യാക്കോബിനെ വെറുത്തു. അവൻ ആത്മഗതംചെയ്തു: പിതാവിനെപ്പറ്റി വിലപിക്കാനുള്ള ദിവസങ്ങൾ അടുത്തുവരുന്നുണ്ട്. അതുകഴിഞ്ഞ് ഞാൻ എന്റെ സഹോദരൻ യാക്കോബിനെ കൊല്ലും.","p":1},{"v":42,"t":"തന്റെ മൂത്തമകൻ ഏസാവിന്റെ വാക്കുകളെപ്പറ്റി റബെക്കായ്ക്ക് അറിവുകിട്ടി. അവൾ തന്റെ ഇളയമകൻ യാക്കോബിനെ വിളിച്ചുവരുത്തി പറഞ്ഞു: ഇതാ, നിന്റെ സഹോദരൻ ഏസാവ് നിന്നെ കൊല്ലാ൯ഒരുങ്ങി പ്രതികാരചിന്തയിലാണ്.","p":1},{"v":43,"t":"എന്റെ മകനേ, ഇപ്പോൾ എന്റെ സ്വരം ശ്രവിക്കുക. എഴുന്നേറ്റ് ഹാരാനിലേക്ക്, എന്റെ സഹോദരൻ ലാബാന്റെ അടുക്കലേക്ക് രക്ഷപ്പെട്ടുകൊള്ളുക.","p":1},{"v":44,"t":"നിന്റെ സഹോദരന്റെ രോഷമടങ്ങുവോളം നീ കുറച്ചുനാൾ അവനോടൊപ്പം താമസിക്കുക.","p":1},{"v":45,"t":"നിന്റെ സഹോദരനു നിന്നോടുള്ള കോപം അടങ്ങുകയും നീ ചെയ്തതൊക്കെ അവൻ മറക്കുകയും ചെയ്യട്ടെ. അപ്പോൾ ഞാൻ ആളയച്ച് നിന്നെ അവിടെനിന്നു കൊണ്ടുവരാം. ഒരേദിവസം നിങ്ങൾ രണ്ടുപേരും എനിക്കു നഷ്ടപ്പെടുന്നതെന്തിന്?","p":1},{"v":46,"t":"റബെക്കാ ഇസഹാക്കിനോടു പറഞ്ഞു: ഈ ഹിത്യസ്ത്രീകളോടൊപ്പമുള്ള ജീവിതം എനിക്കു മടുത്തു. ഇവരെപ്പോലെയുള്ള ഈ നാട്ടുകാരായ ഹിത്യസ്ത്രീകളിൽനിന്ന് ഒരുവളെ യാക്കോബും ഭാര്യയായി സ്വീകരിച്ചാൽ പിന്നെ എനിക്ക് എന്തിനാണ് ജീവിതം?","p":1}],"28":[{"v":1,"t":"ഇസഹാക്ക് യാക്കോബിനെ വിളിച്ച് അവനെ അനുഗ്രഹിച്ചു; അവനോടു കൽപിച്ചുകൊണ്ടു പറഞ്ഞു: കാനാനുസ്ത്രീകളിൽനിന്ന് നീ ഭാര്യയെ സ്വീകരിക്കരുത്.","p":1},{"v":2,"t":"നീ എഴുന്നേറ്റ്, പാദാൻആരാമിൽ നിന്റെ അമ്മയുടെ പിതാവായ ബെത്തുവേലിന്റെ വീട്ടിലേക്കു പോവുക. അവിടെനിന്ന്, നിന്റെ അമ്മയുടെ സഹോദരനായ ലാബാന്റെ പുത്രിമാരിലൊരാളെ നീ ഭാര്യയായി സ്വീകരിക്കുക.","p":1},{"v":3,"t":"സർവശക്തനായ തമ്പുരാൻ നിന്നെ അനുഗ്രഹിച്ച്, ഫലസമൃദ്ധമാക്കി വർധിപ്പിക്കട്ടെ; അങ്ങനെ നീ ജനങ്ങളുടെ ഒരു സമൂഹമായിതീരും.","p":1},{"v":4,"t":"ദൈവം അബ്രാഹത്തിനു നൽകിയ നിന്റെ വിപ്രവാസത്തിന്റെ ഈ നാട് നീ അവകാശപ്പെടുത്തേണ്ടതിന് അബ്രാഹത്തിന്റെ അനുഗ്രഹം നിനക്കും നിന്നോടൊപ്പം നിന്റെ സന്തതിക്കുമായി അവിടുന്ന് നൽകട്ടെ.","p":1},{"v":5,"t":"അങ്ങനെ ഇസഹാക്ക് യാക്കോബിനെ പറഞ്ഞയച്ചു. അവൻ പാദാൻആരാമിലുള്ള, അരാമായനായ ബെത്തുവേലിന്റെ മകനും യാക്കോബിന്റെയും ഏസാവിന്റെയും അമ്മ റബെക്കായുടെ സഹോദരനുമായ ലാബാന്റെ അടുക്കലേക്കു പോയി.","p":1},{"v":6,"t":"ഇസഹാക്ക് യാക്കോബിനെ അനുഗ്രഹിച്ചതും പാദാൻആരാമിൽനിന്ന് ഭാര്യയെ കണ്ടുപിടിക്കുന്നതിന് പറഞ്ഞയച്ചതും അവനെ അനുഗ്രഹിക്കവേ, കാനാന്യരിൽ നിന്ന് ഭാര്യയെ സ്വീകരിക്കരുതെന്ന് അവനോടു കൽപ്പിച്ചതും ഏസാവ് മനസ്സിലാക്കി.","p":1},{"v":7,"t":"യാക്കോബ് തന്റെ പിതാവിനെയും മാതാവിനെയും അനുസരിച്ച് പാദാൻആരാമിലേക്കു പോയി.","p":1},{"v":8,"t":"തന്റെ പിതാവായ ഇസഹാക്കിന്റെ ദൃഷ്ടികളിൽ കാനാൻ പുത്രിമാർ ദൂഷിച്ചവരാണെന്ന് ഏസാവ് കണ്ടു.","p":1},{"v":9,"t":"ഏസാവ് ഇസ്മായേലിന്റെ അടുത്തുചെന്ന് അബ്രാഹത്തിന്റെ പുത്രനായ ഇസ്മായേലിന്റെ മകളും നെബാ","p":1},{"h":"യാക്കോബിന്റെ സ്വപ്നം"},{"v":10,"t":"യാക്കോബ് ബേർഷെബയിൽനിന്നു പുറപ്പെട്ട് ഹാരാനിലേക്കു പോയി.","p":1},{"v":11,"t":"അവൻ ഒരു സ്ഥലത്തെത്തിയപ്പോൾ സൂര്യൻ അസ്തമിക്കുകയാൽ അവിടെ രാപ്പാർത്തു. ആ സ്ഥലത്തെ കല്ലുകളിലൊന്നെടുത്ത് തലയ്കൽ വച്ച് ആ സ്ഥലത്ത് അവൻ കിടന്നു.","p":1},{"v":12,"t":"അപ്പോൾ അവൻ സ്വപ്നംകണ്ടു: ഇതാ, ഭൂമിയിൽ ഉറപ്പിച്ച ഒരു കോവണി! അതിന്റെ മുകളറ്റം ആകാശത്ം മുട്ടിയിരുന്നു. ദൈവതൂതന്മാർ അതിലൂടെ കയറുകയും ഇറങ്ങുകയും ചെയ്തുകൊണ്ടിരുന്നു!","p":1},{"v":13,"t":"ഇതാ, അതിനുമുകളിലായി കർത്താവ് നിൽക്കുന്നു! അവിടുന്ന് അരുൾചെയ്തു: ഞാൻ നിന്റെ പിതാവായ അബ്രാഹത്തിന്റെ ദൈവമായ കർത്താവും ഇസഹാക്കിന്റെ ദൈവവുമാണ്. നീ കിടക്കുന്ന ഈ ഭൂമി നിനക്കും നിന്റെ സന്തതിക്കും ഞാൻ നൽകും.","p":1},{"v":14,"t":"നിന്റെ സന്തതി ഭൂമിയിലെ പൂഴിപോലെയാകും; പടിഞ്ഞാറോട്ടും കിഴക്കോട്ടും വടക്കോട്ടും തെക്കോട്ടും നീ വ്യാപിക്കും. മണ്ണിലെ വംശങ്ങളെല്ലാം നിന്നിലൂടെയും നിന്റെ സന്തതിയിലൂടെയും അനുഗ്രഹിക്കപ്പെടും.","p":1},{"v":15,"t":"ഇതാ, ഞാൻ നിന്നോടുകൂടെയുണ്ട്. നീ പോകുന്ന ഇടത്തെല്ലാം ഞാൻ നിന്നെ സംരക്ഷിക്കും; നിന്നെ ഈ മണ്ണിലേക്കുതന്നെ തിരിയെക്കൊണ്ടുവരും. എന്തെന്നാൽ, നിന്നോടു ഞാൻ പറഞ്ഞതു നിറവേറ്റുന്നതുവരെ ഞാൻ നിന്നെ കൈവിടുകയില്ല.","p":1},{"v":16,"t":"അപ്പോൾ യാക്കോബ് ഉറക്കത്തിൽനിന്നുണർന്നു. അവൻ പറഞ്ഞു: തീർച്ചയായും കർത്താവ് ഈ സ്ഥലത്തുണ്ട്; എന്നാൽ, ഞാൻ അതറിഞ്ഞില്ല.","p":1},{"v":17,"t":"ഭീതിപൂണ്ട് അവൻ പറഞ്ഞു: ഈ സ്ഥലം എത്ര ഭയാനകമാണ്! ഇത് ദൈവത്തിന്റെ ഭവനമല്ലാതെ മറ്റൊന്നുമല്ല; സ്വർഗത്തിന്റെ കവാടമാണിത്.","p":1},{"v":18,"t":"യാക്കോബ് അതിരാവിലെ എഴുന്നേറ്റ് തലയ്ക്കു കീഴെ വച്ചിരുന്ന കല്ലെടുത്ത് ഒരു തൂണായി കുത്തിനിർത്തി അതിന്റെ മുകളിൽ എണ്ണയൊഴിച്ചു.","p":1},{"v":19,"t":"അവൻ ആ സ്ഥലത്തിന് ബേഥേൽ എന്നുപേരിട്ടു; ലൂസ് എന്നായിരുന്നു ആ പട്ടണത്തിന്റെ ആദ്യത്തെ പേര്.","p":1},{"v":20,"t":"അതുകഴിഞ്ഞ് യാക്കോബ് ഒരു നേർച്ചനേർന്നുകൊണ്ടു പറഞ്ഞു: ദൈവം എന്നോടുകൂടെയുണ്ടായിരിക്കുകയും ഞാൻ സഞ്ചരിക്കുന്ന ഈ വഴിയിൽ എന്നെ സംരക്ഷിക്കുകയും എനിക്കു ഭക്ഷിക്കാൻ അപ്പവും ധരിക്കാൻ വസ്ത്രവും തരുകയും","p":1},{"v":21,"t":"എന്റെ പിതാവിന്റെ വീട്ടിലേക്ക് സമാധാനത്തോടെ ഞാൻ തിരിച്ചെത്തുകയും ചെയ്താൽ കർത്താവ് എനിക്കു ദൈവമായിത്തീരും.","p":1},{"v":22,"t":"തൂണായി ഞാൻ കുത്തിനിർത്തിയിരിക്കുന്ന ഈ കല്ല് ദൈവത്തിന്റെ ഭവനമായിരിക്കും. അവിടുന്ന് എനിക്കു തരുന്നതിന്റെയെല്ലാം ദശാംശം ഞാൻ അവിടത്തേക്കു സമർപ്പിക്കുകയും ചെയ്യും.","p":1}],"29":[{"h":"ലാബാന്റെ വീട്ടിൽ"},{"v":1,"t":"യാക്കോബ് യാത്രതുടർന്ന് പൗരസ്ത്യരുടെ ദേശത്തേക്കു സഞ്ചരിച്ചു.","p":1},{"v":2,"t":"അവൻ നോക്കിയപ്പോൾ ഇതാ, വയലിൽ ഒരു കിണർ! അവിടെ അതിനുമുന്നിലായി മൂന്ന് ആട്ടിൻപറ്റങ്ങൾ കിടക്കുന്നുണ്ടായിരുന്നു. കാരണം, ആ കിണറ്റിൽനിന്നാണ് അവർ ആടുകളെ കുടിപ്പിച്ചിരുന്നത്. കിണറിന്റെ വായ്ക്കല്ല് വലുതായിരുന്നു.","p":1},{"v":3,"t":"അവർ ആട്ടിൻപറ്റങ്ങളെയെല്ലാം അവിടെ ഒരുമിച്ചുകൂട്ടുമ്പോൾ, കിണറിന്റെ വായ്ക്കല്ല് ഉരുട്ടിമാറ്റി ആടുകൾക്കു വെള്ളംകൊടുത്തിരുന്നു; അതുകഴിഞ്ഞ് കല്ല് കിണറിന്റെമുകളിൽ യഥാസ്ഥാനം തിരികെവയ്ക്കുകയും ചെയ്തിരുന്നു.","p":1},{"v":4,"t":"യാക്കോബ് അവരോടു ചോദിച്ചു: എന്റെ സഹോദരന്മാരേ, നിങ്ങൾ എവിടെനിന്നാണ്? ഞങ്ങൾ ഹാറാനിൽ നിന്നാണ് എന്ന് അവർ മറുപടി പറഞ്ഞു.","p":1},{"v":5,"t":"അവൻ വീണ്ടും ചോദിച്ചു: നിങ്ങൾ നാഹോറിന്റെ മകൻ ലാബാനെ അറിയുമോ? അറിയാം എന്ന് അവർ പറഞ്ഞു.","p":1},{"v":6,"t":"അവനു ക്ഷേമമാണോ, അവൻ ചോദിച്ചു. ക്ഷേമമതന്നെ, അവർ പറഞ്ഞു: ഇതാ, അവന്റെ മകൾ റാഹേൽ ആടുകളുമായി വരുന്നു.","p":1},{"v":7,"t":"അവൻ പറഞ്ഞു: പകൽ ഇനിയും ഏറെയുണ്ടല്ലോ. ആടുകളെ ഒരുമിച്ചുകൂട്ടാനുള്ള നേരമായിട്ടില്ല. ആടുകൾക്കു വെള്ളംകൊടുത്തിട്ട് നിങ്ങൾ പോയി അവയെ മേയ്ക്കുക.","p":1},{"v":8,"t":"അവർ പറഞ്ഞു: ഞങ്ങൾക്ക് സാധിക്കുകയില്ല. ആട്ടിൻപറ്റങ്ങളെയെല്ലാം ഒരുമിച്ചുകൂട്ടുകയും കിണറിന്റെ വായ്ക്കല്ല് ഉരുട്ടി മാറ്റുകയും ചെയ്തിട്ടേ ഞങ്ങൾ ആടുകൾക്ക് വെള്ളം കൊടുക്കാറുള്ളൂ.","p":1},{"v":9,"t":"അവൻ അവരുമായി സംസാരിച്ചുകൊണ്ടിരിക്കേ, റാഹേൽ തന്റെ പിതാവിന്റെ ആടുകളുമായി വന്നു; എന്തെന്നാൽ, അവൾ ഇടയസ്ത്രീയായിരുന്നു.","p":1},{"v":10,"t":"തന്റെ മാതുലൻ ലാബാന്റെ മകൾ റാഹേലിനെയും അവന്റെ ആടുകളെയും കണ്ടപ്പോൾ യാക്കോബ് അടുത്തുചെന്ന് കിണറിന്റെ വായ്ക്കല്ല് ഉരുട്ടിമാറ്റുകയും ആടുകൾക്കു വെള്ളം കൊടുക്കുകയും ചെയ്തു.","p":1},{"v":11,"t":"പിന്നീട് യാക്കോബ് റാഹേലിനെ ചുംബിക്കുകയും ഉച്ചസ്വരംത്തിൽ കരയുകയും ചെയ്തു.","p":1},{"v":12,"t":"താൻ അവളുടെ പിതാവിന്റെ ബന്ധുവും റബെക്കായുടെ മകനുമാണെന്ന് യാക്കോബ് റാഹേലിനെ അറിയിച്ചു. അവൾ ഓടിച്ചെന്ന് പിതാവിനെ വിവരമറിയിച്ചു.","p":1},{"v":13,"t":"തന്റെ സഹോദരീപുത്രനായ യാക്കോബിന്റെ വാർത്ത കേട്ടപ്പോൾ ലാബാൻ അവനെ എതിരേൽക്കാൻ ഓടിയെത്തി. അവൻ അവനെ കെട്ടിപ്പിടിച്ചു ചുംബിച്ച് വീട്ടിലേക്കു കൂട്ടിക്കൊണ്ടുപോയി. അവൻ സംഭവിച്ചതെല്ലാം ലാബാനോടു വിവരിച്ചു.","p":1},{"v":14,"t":"ലാബാൻ അവനോടു പറഞ്ഞു: എന്റെ അസ്ഥിയും മാംസവും തന്നെയയാണല്ലോ നീ! ഒരു മാസക്കാലം അവൻ അവന്റെകൂടെ പാർത്തു.","p":1},{"v":15,"t":"ലാബാൻ യാക്കോബിനോടു പറഞ്ഞു: നീ എന്റെ ചാർച്ചക്കാരനായതുകൊണ്ട്, പ്രതിഫലമില്ലാതെ എനിക്കുവേണ്ടി പണിയെടുക്കേണ്ടതുണ്ടോ? നിന്റെ വേതനം എന്താണെന്നു എന്നോടു പറയുക.","p":1},{"v":16,"t":"ലാബാന് രണ്ടു പുത്രിമാരുണ്ടായിരുന്നു. മൂത്തവളുടെ പേര് ലെയാ, ഇളയവളുടെ പേര് റാഹേൽ.","p":1},{"v":17,"t":"ലെയായുടെ നയനങ്ങൾ മങ്ങിയവയായിരുന്നു; റാഹേലാകട്ടെ, രൂപഭംഗിയുള്ളവളും കാഴ്ചയ്ക്കു സുന്ദരിയും.","p":1},{"v":18,"t":"യാക്കോബ് റാഹേലിൽ അനുരക്തനായി. അവൻ ലാബാനോടു പറഞ്ഞു: അങ്ങയുടെ ഇളയമകളായ റാഹേലിനുവേണ്ടി ഏഴുകൊല്ലം ഞാൻ അങ്ങയെ സേവിക്കാം.","p":1},{"v":19,"t":"ലാബാൻ പറഞ്ഞു: അവളെ മറ്റാർക്കെങ്കിലും കൊടുക്കുന്നതിനെക്കാൾ നല്ലത് ഞാൻ അവളെ നിനക്കു തരുന്നതാണ്. എന്റെകൂടെ പാർത്തുകൊള്ളുക.","p":1},{"v":20,"t":"അങ്ങനെ റാഹേലിനുവേണ്ടി യാക്കോബ് ഏഴു കൊല്ലം പണിയടുത്തു. അവളോടുള്ള ഇഷ്ടംമൂലം അവന്റെ ദൃഷ്ടികളിൽ അവ ഏതാനും നാളുകൾപോലെയേ തോന്നിയുള്ളൂ.","p":1},{"v":21,"t":"അപ്പോൾ യാക്കോബ് ലാബാനോടു പറഞ്ഞു: എന്റെ ദിനങ്ങൾ പൂർത്തിയായതുകൊണ്ട് എന്റെ ഭാര്യയെ തരുക; ഞാൻ അവളെ പ്രാപിക്കട്ടെ.","p":1},{"v":22,"t":"ലാബാൻ ആ പ്രദേശത്തുള്ളവരെയെല്ലാം ഒരുമിച്ചുകൂട്ടി ഒരു വിരുന്നു നടത്തി.","p":1},{"v":23,"t":"വൈകുന്നേരമായപ്പോൾ അവൻ തന്റെ മകൾ ലെയായെ യാക്കോബിന്റെ അടുത്തേക്കു കൊണ്ടുവന്നു. അവൻ അവളെ പ്രാപിച്ചു.","p":1},{"v":24,"t":"തന്റെ മകൾ ലെയായ്ക്കു പരിചാരികയായി ലാബാൻ തന്റെ പരിചാരിക സിൽഫായെ കൊടുത്തു.","p":1},{"v":25,"t":"നേരം പുലർന്നപ്പോൾ അത് ലെയാ ആണെന്നുകണ്ട് അവൻ ലാബാനോടു ചോദിച്ചു: അങ്ങ് എന്നോട് എന്താണീ ചെയ്തത്? റാഹേലിനു വേണ്ടിയല്ലേ ഞാൻ അങ്ങയോടൊപ്പം പണിയെടുത്തത്? പിന്നെ അങ്ങ് എന്നെ ചതിച്ചതെന്തിന്?","p":1},{"v":26,"t":"ലാബാൻ പറഞ്ഞു: മൂത്തവൾക്കുമുമ്പേ ഇളയവളെ നൽകുക എന്നത് ഞങ്ങളുടെ നാട്ടിൽ ചെയ്യാറില്ല.","p":1},{"v":27,"t":"ഇവളുടെ ആഴ്ച പൂർത്തിയാക്കുക. ഇനിയും വേറെ ഏഴുവർഷംകൂടി നീ എന്നോടൊപ്പം വേലചെയ്താൽ അവളെയും വേതനമായി ഞങ്ങൾ നിനക്കു തരാം.","p":1},{"v":28,"t":"യാക്കോബ് അപ്രകാരം ചെയ്തു. അവളുടെ ആഴ്ച പൂർത്തിയായപ്പോൾ ലാബാൻ തന്റെ പുത്രി റാഹേലിനെയും അവനു ഭാര്യയായി നൽകി.","p":1},{"v":29,"t":"ലാബാൻ പുത്രി റാഹേലിനു പരിചാരികയായി തന്റെ പരിചാരിക ബിൽഹായെ നൽകി.","p":1},{"v":30,"t":"അവൻ റാഹേലിനെ പ്രാപിക്കുകയും ലെയായെക്കാൾ കൂടുതലായി റാഹേലിനെ ഇഷ്ടപ്പെടുകയും ചെയ്തു. തുടർന്ന് ഏഴുവർഷം കൂടി അവൻ അയാളോടൊപ്പം വേലചെയ്തു.","p":1},{"h":"യാക്കോബിന്റെ മക്കൾ"},{"v":31,"t":"ലെയാ വെറുക്കപ്പെടുന്നതായിക്കണ്ട് കർത്താവ് അവളുടെ ഗർഭപാത്രം തുറന്നു. റാഹേലാകട്ടെ, വന്ധ്യയായിരുന്നു.","p":1},{"v":32,"t":"ലെയാ ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ അവനു റൂബൻ എന്നു പേരിട്ടു. എന്തെന്നാൽ, കർത്താവ് എന്റെ കഷ്ടപ്പാടു കണ്ടിരിക്കുന്നു; ഇനി തീർച്ചയായും എന്റെ ഭർത്താവ് എന്നെ സ്നേഹിക്കും എന്ന് അവൾ പറഞ്ഞു.","p":1},{"v":33,"t":"അവൾ വീണ്ടും ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ പറഞ്ഞു: ഞാൻ വെറുക്കപ്പെടുന്നു എന്ന് കർത്താവ് കേട്ടതിനാൽ, അവിടുന്ന് എനിക്ക് ഇവനെയും നൽകിയിരിക്കുന്നു. അതുകൊണ്ട് അവൾ അവന് ശിമയോൻ എന്നു പേരിട്ടു.","p":1},{"v":34,"t":"അവൾ പിന്നെയും ഗർഭംധരിച്ചു, ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ പറഞ്ഞു: ഞാനവനു മൂന്നുപുത്രന്മാരെ പ്രസവിച്ചിരിക്കുന്നതിനാൽ ഇത്തവണ എന്റെ ഭർത്താവ് എന്നോട് അടുക്കുകതന്നെചെയ്യും. അതുകൊണ്ട് അവനെ ലേവി എന്നു പേരു വിളിച്ചു.","p":1},{"v":35,"t":"അവൾ വീണ്ടും ഗർഭംധരിക്കുകയും ഒരു പുത്രനെ പ്രസവിക്കുകയും ചെയ്തു. അവൾ പറഞ്ഞു: ഇപ്രാവശ്യം ഞാൻ കർത്താവിനെ സ്തുതിക്കും; അതുകൊണ്ട്, അവൾ അവനെ യൂദാ എന്ന് പേരു വിളിച്ചു. പിന്നീട് അവൾക്ക് പ്രസവിക്കാനായില്ല.","p":1}],"30":[{"v":1,"t":"താൻ യാക്കോബിന് മക്കളെ പ്രസവിക്കുന്നില്ലെന്ന് കണ്ടു റാഹേൽ തൻ്റെ സഹോദരിയോട് അസൂയാലുവായി അവൾ യാക്കോബിനോട് പറഞ്ഞു എനിക്ക് മക്കളെ തരുക അല്ലെങ്കിൽ ഞാൻ മരിക്കും.","p":1},{"v":2,"t":"യാക്കോബ് റാഹേലിനോട് കോപിച്ചു പറഞ്ഞു നിന്നിൽ നിന്ന് ഉദരഫലം തടഞ്ഞ ദൈവത്തിൻ്റെ സ്ഥാനത്താണോ ഞാൻ?","p":1},{"v":3,"t":"അവൾ പറഞ്ഞു ഇതാ എൻ്റെ ദാസി ബിൽഹാ അവളെ പ്രാപിക്കുക അവൾ എന്റെ മടിയിൽ പ്രസവിക്കട്ടെ. അങ്ങനെ അവളിലൂടെ ഞാനും പുത്രലബ്ധയാകും.","p":1},{"v":4,"t":"അവൾ തൻ്റെ പരിചാരിക ബിൽഹായെ അവന് ഭാര്യയായി നൽകി അവൻ അവളെ പ്രാപിച്ചു.","p":1},{"v":5,"t":"ബിൽഹാ ഗർഭം ധരിച്ച് യാക്കോബിന് ഒരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":6,"t":"അപ്പോൾ റാഹേൽ പറഞ്ഞു ദൈവം എന്നെ വിധിക്കുകയും എൻ്റെ സ്വരം കേട്ട് എനിക്കൊരു പുത്രനെ നൽകുകയും ചെയ്തിരിക്കുന്നു. അക്കാരണത്താൽ, അവൾ അവന് ദാൻ എന്നു പേരിട്ടു.","p":1},{"v":7,"t":"റാഹേലിന്റെ പരിചാരിക ബിൽഹാ വീണ്ടും ഗർഭംധരിച്ചു. യാക്കോബിന് അവൾ രണ്ടാമതൊരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":8,"t":"റാഹേൽ പറഞ്ഞു: എന്റെ സഹോദരിയുമായി കടുത്ത മത്സരം തന്നെ നടത്തി ഞാൻ ജയിച്ചിരിക്കുന്നു. അവൾ അവനെ നഫ്താലി എന്നുവിളിച്ചു.","p":1},{"v":9,"t":"തനിക്കു പ്രസവിക്കാനാകുന്നില്ലെന്നു കണ്ട് ലെയാ തന്റെ പരിചാരിക സിൽഫായെ കൊണ്ടുവന്ന് യാക്കോബിനു ഭാര്യയായി നൽകി.","p":1},{"v":10,"t":"ലെയായുടെ പരിചാരിക സിൽഫാ യാക്കോബിന് ഒരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":11,"t":"ഭാഗ്യമായി എന്നു പറഞ്ഞുകൊണ്ട് അവൾ അവന് ഗാദ് എന്നു പേരിട്ടു.","p":1},{"v":12,"t":"ലെയായുടെ പരിചാരിക സിൽഫാ യാക്കോബിന് രണ്ടാമതൊരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":13,"t":"ലെയാ പറഞ്ഞു: എന്റെ സന്തോഷം കാരണം പെൺകൊടികൾ എന്നെ സന്തോഷവതിയെന്നു വിളിക്കും. അവൾ അവന് ആശേർ എന്നു പേരിട്ടു.","p":1},{"v":14,"t":"ഗോതമ്പുകൊയ്ത്തുകാലത്ത് റൂബൻ വയലിൽ ചെന്നപ്പോൾ, ദുദായിപ്പഴം കാണുകയും അവ തന്റെ അമ്മ ലെയായ്ക്കു കൊണ്ടുവരുകയും ചെയ്തു. അപ്പോൾ റാഹേൽ ലെയായോട് പറഞ്ഞു: നിന്റെ പുത്രന്റെ ദുദായിപ്പഴത്തിൽനിന്ന് സദയം എനിക്കും തരുക.","p":1},{"v":15,"t":"അവൾ പറഞ്ഞു: എന്റെ ഭർത്താവിനെ നീ കൈയടക്കിവച്ചിരിക്കുന്നത് നിസ്സാരകാര്യമോ? എന്റെ മകന്റെ ദുദായിപ്പഴവും കൈവശപ്പെടുത്തണമോ? റാഹേൽ പറഞ്ഞു: അതുകൊണ്ട് നിന്റെ മകന്റെ ദുദായിപ്പഴത്തിനുപകരം അദ്ദേഹം ഈ രാത്രി നിന്റെ കൂടെ ശയിച്ചുകൊള്ളട്ടെ.","p":1},{"v":16,"t":"യാക്കോബ് വൈകുന്നേരം വയലിൽനിന്നു വന്നു. ലെയാ അവനെ കാണാൻ പുറത്തേക്കുചെന്ന് അവനോടു പറഞ്ഞു: എന്റെയടുത്ത് അങ്ങു വരണം; കാരണം, എന്റെ മകന്റെ ദുദായിപ്പഴം ഞാൻതന്നെ പ്രതിഫലമായി കൊടുത്ത് അങ്ങയെ വാങ്ങിയിരിക്കുകയാണ്. ആ രാത്രി അവൻ അവളോടുകൂടെ ശയിച്ചു.","p":1},{"v":17,"t":"ദൈവം ലെയായെ ശ്രവിച്ചു; അവൾ ഗർഭംധരിച്ച് യാക്കോബിന് അഞ്ചാമതൊരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":18,"t":"എന്റെ പരിചാരികയെ ഭർത്താവിനു കൊടുത്തതിന് ദൈവം എനിക്കു പ്രതിഫലം തന്നു എന്നു പറഞ്ഞ് അവൾ അവന് ഇസ്സാക്കർ എന്നു പേരിട്ടു.","p":1},{"v":19,"t":"ലെയാ വീണ്ടും ഗർഭം ധരിച്ചു; യാക്കോബിന് അവൾ ആറാമതൊരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":20,"t":"(തുടർച്ച): ലെയാ പറഞ്ഞു: ദൈവം എനിക്ക് നല്ല ഉപഹാരം സമ്മാനിച്ചിരിക്കുന്നു. ഇത്തവണ ഭർത്താവ് എന്നെ മാനിക്കും; കാരണം, അവനു ഞാൻ ആറു മക്കളെ പ്രസവിച്ചിരിക്കുന്നു. അവൾ അവന് സെബുലൂൺ എന്നു പേരിട്ടു.","p":1},{"v":21,"t":"അതിനുശേഷം അവൾ ഒരു പുത്രിയെ പ്രസവിച്ചു. അവൾ അവൾക്ക് ദീനാ എന്നു പേരിട്ടു.","p":1},{"v":22,"t":"ദൈവം റാഹേലിനെ സ്മരിച്ചു. അവിടുന്ന് അവളെ കേൾക്കുകയും അവളുടെ ഗർഭപാത്രം തുറക്കുകയും ചെയ്തു.","p":1},{"v":23,"t":"അവൾ ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ പറഞ്ഞു: എന്റെ അപമാനം ദൈവം നീക്കിക്കളഞ്ഞിരിക്കുന്നു.","p":1},{"v":24,"t":"കർത്താവ് എനിക്ക് ഒരു പുത്രനെക്കൂടി തരട്ടെ എന്നു പറഞ്ഞ് അവൾ അവന് ജോസഫ് എന്നു പേരിട്ടു.","p":1},{"h":"യാക്കോബിന്റെ സമ്പത്ത്"},{"v":25,"t":"റാഹേൽ ജോസഫിനെ പ്രസവിച്ചുകഴിഞ്ഞ്, യാക്കോബ് ലാബാനോടു പറഞ്ഞു: എന്നെ വിട്ടയച്ചാലും; ഞാൻ എന്റെ സ്ഥലത്തേക്കും ദേശത്തേക്കും പോകട്ടെ.","p":1},{"v":26,"t":"എന്റെ ഭാര്യമാരെയും കുട്ടികളെയും തന്നാലും; അവരെപ്രതിയാണല്ലോ ഞാൻ അങ്ങയെ സേവിച്ചത്. ഞാൻ പോകട്ടെ; അങ്ങയ്ക്കുവേണ്ടി ഞാൻ ചെയ്ത സേവനം അങ്ങയ്ക്ക് നന്നായി അറിയാമല്ലോ.","p":1},{"v":27,"t":"ലാബാൻ അവനോടു പറഞ്ഞു: നിന്റെ ദൃഷ്ടികളിൽ പ്രീതി കണ്ടെത്താൻ എനിക്കു കഴിഞ്ഞിരുന്നെങ്കിൽ! നീ മൂലമാണ് കർത്താവ് എന്നെ അനുഗ്രഹിച്ചത് എന്ന് ഞാൻ ഗണിച്ചറിഞ്ഞിരിക്കുന്നു.","p":1},{"v":28,"t":"അയാൾ തുടർന്നു പറഞ്ഞു: നിന്റെ വേതനം എന്നിൽനിന്ന് ഈടാക്കൂ; അതു ഞാൻ തരാം.","p":1},{"v":29,"t":"അവൻ അയാളോടു പറഞ്ഞു: ഞാൻ അങ്ങയെ എപ്രകാരം സേവിച്ചെന്നും അങ്ങയുടെ കന്നുകാലികൾ എന്റെകീഴിൽ എപ്രകാരമായിരുന്നുവെന്നും അങ്ങയ്ക്ക് നന്നായി അറിയാമല്ലോ.","p":1},{"v":30,"t":"എനിക്കുമുമ്പ് അങ്ങേക്ക് കുറച്ചുമാത്രം ഉണ്ടായിരുന്നത് ഇപ്പോൾ തീർച്ചയായും ഏറെ പെരുകിയിരിക്കുന്നു. എന്റെ ഓരോ ചുവടിനും കർത്താവ് അങ്ങയെ അനുഗ്രഹിച്ചിരിക്കുന്നു. ഇനി ഞാൻ എപ്പോഴാണ് എന്റെ ഭവനത്തിനായി എന്തെങ്കിലും ചെയ്യുക?","p":1},{"v":31,"t":"അയാൾ ചോദിച്ചു: ഞാൻ നിനക്ക് എന്തു തരണം? യാക്കോബ് പറഞ്ഞു: അങ്ങ് എനിക്ക് ഒന്നും തരേണ്ട. ഞാൻ പറയാൻപോകുന്ന ഈ കാര്യം അങ്ങ് ചെയ്താൽ, അങ്ങയുടെ ആടുകളെ ഞാൻ തുടർന്നും മേയിച്ച് കാത്തുകൊള്ളാം.","p":1},{"v":32,"t":"ഞാൻ എന്നുതന്നെ അങ്ങയുടെ ഓരോ ആട്ടിൻകൂട്ടത്തിലൂടെയും കടന്ന് ചെമ്മരിയാടുകളിൽ പുള്ളിയും പാണ്ടും ഉള്ള എല്ലാ ആടുകളെയും കറുത്ത ആടുകളെയും കോലാടുകളിൽ പാണ്ടും പുള്ളിയും ഉള്ളവയെയും വേർതിരിക്കാം. അവയായിരിക്കും എന്റെ വേതനം.","p":1},{"v":33,"t":"വരും നാളിൽ എന്റെ വേതനം അങ്ങയുടെ പരിഗണനയ്ക്കുവരുമ്പോൾ എന്റെ നീതി എനിക്ക് സാക്ഷ്യമായിരിക്കും. കോലാടുകളിൽ പുള്ളിയോ പാണ്ഡോ, ചെമ്മരിയാടുകളിൽ കറുപ്പോ ഇല്ലാത്തതായി എന്റെ പക്കലുള്ളതെല്ലാം കളവു മുതലായിരിക്കും.","p":1},{"v":34,"t":"ലാബാൻ പറഞ്ഞു: അതു, കൊള്ളാമല്ലോ, നീ പറഞ്ഞതുപോലെതന്നെയാകട്ടെ.","p":1},{"v":35,"t":"അന്നുതന്നെ അവൻ വരയും പാണ്ടുമുള്ള മുട്ടാടുകളെയും പുള്ളികളുള്ള എല്ലാ കോലാടുകളെയും അതിൽ പാണ്ടുകളുള്ള എല്ലാ വെള്ളുത്തതിനെയും ചെമ്മരിയാടുകളിൽ എല്ലാ കറുത്ത അതിനെയും വേർതിരിച്ച് അവയെ തന്റെ പുത്രന്മാരെ ഏൽപ്പിച്ചു.","p":1},{"v":36,"t":"തനിക്കും യാക്കോബിനും മധ്യേ അവൻ മൂന്നു ദിവസത്തെ വഴിയകലം നിർണയിച്ചു. യാക്കോബാകട്ടെ, ലാബാന്റെ അവശേഷിച്ച ആടുകളെ മേയിച്ചുകൊണ്ടിരുന്നു.","p":1},{"v":37,"t":"യാക്കോബ് ഇലവിന്റെയും ബദാമിന്റെയും അഴിഞ്ഞിലിന്റെയും പച്ചക്കമ്പുകൾ വെട്ടിയെടുത്ത് കമ്പുകളിലെ വെള്ളപ്പു കാണത്തക്കവിധം തൊലിയുരിഞ്ഞുനീക്കി,","p":1},{"v":38,"t":"താൻ തൊലിയുരിഞ്ഞുമാറ്റിയ കമ്പുകൾ ആടുകൾ വെള്ളം കുടിക്കുന്ന പാത്തികളിൽ ആടുകളുടെ മുമ്പിൽ അവൻ കുത്തിനിർത്തി. വെള്ളംകുടിക്കാൻ വരുമ്പോഴാണ് അവ ഇണചേർന്നിരുന്നത്.","p":1},{"v":39,"t":"ആടുകൾ ഈ കമ്പുകളുടെ മുമ്പിൽ ഇണചേർന്നു. അവ വരയും പുള്ളിയും പാണ്ടുമുള്ള കുഞ്ഞുങ്ങളെ പ്രസവിച്ചു.","p":1},{"v":40,"t":"ചെമ്മരിയാടുകളെയാകട്ടെ, യാക്കോബ് വേർതിരിച്ച് ലാബാന്റെ കൂട്ടത്തിലെ വരയുള്ളതും കറുത്തതുമായ എല്ലാ ആടുകളുടെയും നേരേ നിർത്തി. അവൻ അങ്ങനെ തനിക്കുവേണ്ടി പ്രത്യേകം ആടുകളെ സ്വന്തമാക്കി; അവയെ ലാബാന്റെ ആടുകളോടു ചേർക്കാതെ മാറ്റിനിർത്തി.","p":1},{"v":41,"t":"കൊഴുത്ത ആടുകൾ ഇണചേരുമ്പോഴെല്ലാം, അവ കമ്പുകളുടെ അരികിൽവെച്ച് ഇണചേരേണ്ടതിന്, യാക്കോബ് കമ്പുകൾ ആടുകൾ കാൺകേ പാത്തികളിൽ വച്ചിരുന്നു.","p":1},{"v":42,"t":"എന്നാൽ, മെലിഞ്ഞ ആടുകളുടെ കാര്യത്തിൽ അവൻ അതു ചെയ്തില്ല. അങ്ങനെ മെലിഞ്ഞവ ലാബാന്റേതും കൊഴുത്തവ യാക്കോബിന്റേതുമായി.","p":1},{"v":43,"t":"അവൻ അത്യധികം അഭിവൃദ്ധിപ്പെട്ടു. അവനു ധാരാളം ആടുകളും പരിചാരികമാരും ദാസന്മാരും ഒട്ടകങ്ങളും കഴുതകളും ഉണ്ടായി.","p":1}],"31":[{"h":"യാക്കോബ് ഒളിച്ചോടുന്നു"},{"v":1,"t":"ലാബാന്റെ മക്കൾ ഇങ്ങനെ പറയുന്നത് അവൻ കേട്ടു: നമ്മുടെ പിതാവിനുള്ളതെല്ലാം യാക്കോബ് കൈവശപ്പെടുത്തി. നമ്മുടെ പിതാവിന്റേതിൽനിന്നാണ് അവൻ ഈ മഹത്ത്വമെല്ലാം ഉണ്ടാക്കിയത്.","p":1},{"v":2,"t":"യാക്കോബ് ലാബാന്റെ മുഖം ശ്രദ്ധിച്ചു. ഇതാ അത് മുമ്പത്തെപ്പോലെയായിരുന്നില്ല","p":1},{"v":3,"t":"കർത്താവു യാക്കോബിനോട് അരുളച്ചെയ്തു: നിന്റെ പിതാക്കന്മാരുടെ നാട്ടിലേക്കും സഹജരുടെ അടുത്തേക്കും തിരിച്ചുപോവുക. ഞാൻ നിന്നോടുകൂടെ ഉണ്ടായിരിക്കും.","p":1},{"v":4,"t":"വയലിൽ, തന്റെ ആടുകളുടെ അടുത്തേക്ക് റാഹേലിനെയും ലെയായെയും യാക്കോബ് അയച്ചു വിളിച്ചു.","p":1},{"v":5,"t":"അവൻ അവരോടു പറഞ്ഞു: എന്നോടുള്ള നിങ്ങളുടെ പിതാവിന്റെ മുഖം മുമ്പത്തെപ്പോലെയല്ല എന്നു ഞാൻ കാണുന്നു. എന്നാൽ, എന്റെ പിതാവിന്റെ ദൈവം എന്റെകൂടെ ഉണ്ട്.","p":1},{"v":6,"t":"എന്റെ സർവ്വശക്തിയോടുകൂടെയാണ് നിങ്ങളുടെ പിതാവിനെ ഞാൻ സേവിച്ചതെന്ന് നിങ്ങൾ നന്നായി അറിയുന്നുണ്ടല്ലോ.","p":1},{"v":7,"t":"എന്നാൽ, നിങ്ങളുടെ പിതാവ് എന്നെ ചതിക്കുകയും പത്തു തവണ എന്റെ വേതനത്തിൽ മാറ്റം വരുത്തുകയും ചെയ്തു. പക്ഷേ, എനിക്ക് തിന്മ വരുത്താൻ ദൈവം അവനെ അനുവദിച്ചില്ല.","p":1},{"v":8,"t":"പുള്ളിയുള്ളവയായിരിക്കും നിന്റെ വേതനം എന്ന് അവൻ പറഞ്ഞാൽ എല്ലാ ആടും പുള്ളിയുള്ളതിനെ പ്രസവിക്കും; അതല്ല, വരയുള്ളവയായിരിക്കും നിന്റെ വേതനം എന്ന് അവൻ പറഞ്ഞാൽ, ആടുകളൊക്കെ വരയുള്ളതിനെ പ്രസവിക്കും!","p":1},{"v":9,"t":"അങ്ങനെ ദൈവം നിങ്ങളുടെ പിതാവിന്റെ കാലിസമ്പത്ത് അവനിൽനിന്നു പിടിച്ചെടുത്ത് എനിക്കു തന്നിരിക്കുകയാണ്.","p":1},{"v":10,"t":"ആടുകളുമായി ഇണചേരുന്ന മുട്ടാടുകളെല്ലാം വരയും പുള്ളിയും പൊട്ടുമുള്ളവയായിരുന്നുവെന്ന് ആടുകൾ ഇണചേരുങ്കാലത്ത് ഞാൻ സ്വപ്നത്തിൽ കണ്ണുയർത്തി കണ്ടു.","p":1},{"v":11,"t":"സ്വപ്നത്തിൽ ദൈവദൂതൻ എന്നെ യാക്കോബേ എന്നു വിളിച്ചു. ഇതാ ഞാൻ എന്നു ഞാൻ വിളികേട്ടു.","p":1},{"v":12,"t":"ദൂതൻ പറഞ്ഞു: നീ കണ്ണുകളുയർത്തി നോക്കുക. ആടുകളുമായി ഇണചേരുന്ന മുട്ടാടുകളെല്ലാം വരയും പുള്ളിയും പൊട്ടുമുള്ളവയാണ്. കാരണം, ലാബാൻ നിന്നോടു ചെയ്യുന്നതെല്ലാം ഞാൻ കണ്ടിരിക്കുന്നു.","p":1},{"v":13,"t":"ബേഥെലിലെ ദൈവമാണ് ഞാൻ. അവിടെ വച്ചാണ് തൂണ് അഭിഷേകംചെയ്ത് നീ എന്നോടു വ്രതംചെയ്തത്. എഴുന്നേറ്റ് ഇപ്പോൾ ഈ ദേശത്തുനിന്നു പുറപ്പെടുക. നിന്റെ ജന്മദേശത്തേക്ക് തിരിച്ചുപോവുക.","p":1},{"v":14,"t":"റാഹേലും ലെയായും അവനോടു മറുപടിയായി പറഞ്ഞു: നമ്മുടെ പിതാവിന്റെ വീട്ടിൽ എന്തെങ്കിലും ഓഹരിയോ അവകാശമോ നമുക്ക് ഇനി ഉണ്ടോ?","p":1},{"v":15,"t":"നമ്മളെ അന്യരായല്ലേ അവൻ കരുതുന്നത്? നമ്മെ വിറ്റിട്ട് അവൻ നമ്മുടെ പണം വിഴുങ്ങിക്കൊണ്ടിരിക്കുകയുമല്ലേ?","p":1},{"v":16,"t":"തീർച്ചയായും, നമ്മുടെ പിതാവിൽനിന്നു ദൈവം പിടിച്ചെടുത്ത സമ്പത്തെല്ലാം നമുക്കും നമ്മുടെ മക്കൾക്കും അവകാശപ്പെട്ടതാണ്. അതിനാൽ, ഇപ്പോൾ ദൈവം അങ്ങയോടു പറയുന്നതെല്ലാം ചെയ്യുക.","p":1},{"v":17,"t":"യാക്കോബ് എഴുന്നേറ്റ് തന്റെ പുത്രന്മാരെയും ഭാര്യമാരെയും ഒട്ടകപ്പുറത്തു കയറ്റി.","p":1},{"v":18,"t":"പദാൻആരാമിൽവച്ച് നേടിയെടുത്ത തന്റെ മുതൽകൂട്ടായ കാലിഗണത്തെ - താൻ സമ്പാദിച്ചിരുന്ന എല്ലാ കാലിക്കൂട്ടത്തെയും സകലമൃഗസമ്പത്തിനെയും - തന്റെ പിതാവായ ഇസഹാക്കിന്റെ അടുത്തേക്കു പോകാനായി അവൻ കാനാൻദേശത്തേക്ക് തെളിച്ചു.","p":1},{"v":19,"t":"അപ്പോൾ ലാബാൻ തന്റെ ആടുകളുടെ രോമംകത്രിക്കാൻ പോയിരിക്കുകയായിരുന്നു. ഇതിനിടെ റാഹേൽ തന്റെ പിതാവിന്റെ കുലവിഗ്രഹങ്ങളെല്ലാം കൈക്കലാക്കി.","p":1},{"v":20,"t":"താൻ ഒളിച്ചോടുകയാണെന്ന് അറിയിക്കാതെ യാക്കോബ് അരമായനായ ലാബാനെ കബളിപ്പിക്കുകയായിരുന്നു.","p":1},{"v":21,"t":"അവൻ തനിക്കുള്ള സകലതോടുംകൂടെ ഒളിച്ചോടുകയായിരുന്നു. അവൻ എഴുന്നേറ്റ്, ഗിലയാദ്മല ലക്ഷ്യമാക്കി നദി കടന്നു.","p":1},{"h":"ലാബാൻ പിന്തുടരുന്നു"},{"v":22,"t":"യാക്കോബ് ഒളിച്ചോടിയെന്ന് മൂന്നാംദിവസം ലാബാന് അറിവുകിട്ടി.","p":1},{"v":23,"t":"അയാൾ തന്റെ ചാർച്ചക്കാരെ തന്നോടൊപ്പം കൂട്ടി, ഏഴു ദിവസത്തെ വഴി അനുധാവനംചെയ്ത്, ഗിലയാദ്മലയിൽ അവന്റെ പിന്നാലെ ഒപ്പമെത്തി.","p":1},{"v":24,"t":"എന്നാൽ, ആ രാത്രിയിൽ സ്വപ്നത്തിൽ ദൈവം അരമായനായ ലാബാന്റെ അടുത്തുവന്ന് അവനോടു പറഞ്ഞു: നല്ലതോ ചീത്തയോ ആയ ഒന്നും യാക്കോബിനോട് ഉരിയാടാതിരിക്കാൻ നിനക്ക് കരുതലുണ്ടാകണം.","p":1},{"v":25,"t":"ലാബാൻ യാക്കോബിനെ മറികടന്നു. യാക്കോബ് മലയിൽ കൂടാരമടിച്ചിരിക്കെ, ലാബാനും തന്റെ ചാർച്ചക്കാരോടൊത്ത് ഗിലയാദ്മലയിൽ കൂടാരമടിച്ചു.","p":1},{"v":26,"t":"ലാബാൻ യാക്കോബിനോടു ചോദിച്ചു: നീ എന്താണു ചെയ്തത്? നീ എന്നെ കബളിപ്പിച്ചു. വാളാൽ നേടിയ തടവുകാരെപ്പോലെ നീ എന്റെ പെൺമക്കളെ പിടിച്ചുകൊണ്ടുപോകുന്നു!","p":1},{"v":27,"t":"എന്തുകൊണ്ടാണ് നീ പലായനം ചെയ്തത് രഹസ്യമാക്കിവച്ചതും എന്നെ കൊള്ളയടിച്ചതും എന്നോടു വെളിപ്പെടുത്താതിരുന്നതും? ഞാൻ ആഹ്ലാദത്തോടെ, പാട്ടുകളോടും തപ്പു-കിന്നരങ്ങളോടുംകൂടെ നിന്നെ യാത്രയാക്കുമായിരുന്നുവല്ലോ.","p":1},{"v":28,"t":"എന്റെ പുത്രന്മാരെയും പുത്രിമാരെയും ചുംബിക്കുന്നതിന് നീ എന്നെ അനുവദിച്ചില്ല. നീ ഇപ്പോൾ പ്രവർത്തിച്ചത് ബുദ്ധിശൂന്യമായിപ്പോയി.","p":1},{"v":29,"t":"നിങ്ങൾക്ക് ഉപദ്രവം ചെയ്യാൻ എന്റെ കരം ശക്തമാണ്. എന്നാൽ, 'നല്ലതോ ചീത്തയോ ആയ ഒന്നും യാക്കോബിനോട് ഉരിയാടാതിരിക്കാൻ നിനക്ക് കരുതലുണ്ടാകണം’എന്ന് നിങ്ങളുടെ പിതാവിൻ്റെ ദൈവം കഴിഞ്ഞ രാത്രി എന്നോട് പറഞ്ഞു","p":1},{"v":30,"t":"നീ ഇപ്പോൾ നിർബന്ധമായും പോകുന്നത് നിന്റെ പിതൃഭവനത്തെ തീവ്രമായി അഭിലഷിക്കുന്നതുകൊണ്ടാണെങ്കിൽ, പിന്നെന്തിനാണ് എന്റെ ദേവന്മാരെ കട്ടെടുത്തത്?","p":1},{"v":31,"t":"അപ്പോൾ യാക്കോബ് ലാബാനോടു മറുപടിയായി പറഞ്ഞു: എനിക്കു ഭയമായിരുന്നു. എന്തെന്നാൽ, അങ്ങയുടെ പുത്രിമാരെ അങ്ങ് എന്നിൽനിന്ന് അകറ്റിയേക്കുമെന്നു ഞാൻ വിചാരിച്ചു.","p":1},{"v":32,"t":"അങ്ങയുടെ ദേവന്മാരെ ആരുടെകൂടെ അങ്ങ് കണ്ടെത്തുന്നുവോ അവൻ പിന്നെ ജീവിച്ചിരിക്കില്ല. നമ്മുടെ ചാർച്ചക്കാരുടെ മുമ്പിൽവച്ച് എന്റെ പക്കലുള്ളവ അങ്ങ് പരിശോധിച്ച് അങ്ങയുടേത് എടുത്തുകൊള്ളുക. എന്നാൽ റാഹേൽ അവ മോഷ്ടിച്ചിട്ടുണ്ടെന്ന് യാക്കോബ് അറിഞ്ഞില്ല.","p":1},{"v":33,"t":"ലാബാൻ യാക്കോബിന്റെ കൂടാരത്തിലും ലെയായുടെ കൂടാരത്തിലും രണ്ടു ദാസിമാരുടെയും കൂടാരത്തിലും ചെന്നു; എന്നാൽ അവ കണ്ടെത്തിയില്ല. ലെയായുടെ കൂടാരത്തിൽനിന്നു പുറത്തുകടന്ന് അവൻ റാഹേലിന്റെ കൂടാരത്തിലേക്കു ചെന്നു.","p":1},{"v":34,"t":"റാഹേൽ വിഗ്രഹങ്ങളെടുത്ത് ഒരു ഒട്ടകക്കാണത്തിലിട്ട് അതിന്മേൽ കയറിയിരുന്നു. ലാബാൻ കൂടാരത്തിലെല്ലാം അവ തിരഞ്ഞിട്ടും കണ്ടെത്തിയില്ല.","p":1},{"v":35,"t":"അപ്പോൾ റാഹേൽ തന്റെ പിതാവിനോടു പറഞ്ഞു: എന്റെ യജമാനന്റെ കണ്ണുകളിൽ കോപമരുതേ! അങ്ങയുടെമുമ്പിൽ എനിക്ക് എഴുന്നേൽക്കാനാവില്ല. എനിക്കിപ്പോൾ മാസമുറയാണ്. അവൻ തിരഞ്ഞെങ്കിലും വിഗ്രഹങ്ങൾ കണ്ടെത്തിയില്ല.","p":1},{"v":36,"t":"അപ്പോൾ യാക്കോബിന് അരിശമായി; അവൻ ലാബാനോടു കയർത്തു. യാക്കോബ് ലാബാനോടു മറുപടിയായി പറഞ്ഞു: എന്നെ ക്രോധത്തോടെ പിന്തുടരാൻ എന്റെ അതിക്രമമെന്താണ്? എന്റെ തെറ്റെന്താണ്?","p":1},{"v":37,"t":"എന്റെ സാധനങ്ങളെല്ലാം അങ്ങ് തഴുകിപ്പരിശോധിച്ചു; എന്നിട്ട്, അങ്ങയുടെ വീട്ടുവകസാധനങ്ങളിൽ എന്തെല്ലാമാണ് അങ്ങ് കണ്ടെത്തിയത്? എന്റെ ചാർച്ചക്കാരുടെയും അങ്ങയുടെ ചാർച്ചക്കാരുടെയും മുമ്പിൽ ഇവിടെ നിരത്തി വയ്ക്കുക. നമ്മൾ ഇരുവർക്കുമിടയിൽ അവർ വിധി പറയട്ടെ.","p":1},{"v":38,"t":"ഈ ഇരുപതു വർഷവും ഞാൻ അങ്ങയോടൊപ്പമായിരുന്നു. അങ്ങയുടെ ചെമ്മരിയാടുകൾക്കും അങ്ങയുടെ കോലാടുകൾക്കും ഗർഭഛിദ്രം സംഭവിച്ചിട്ടില്ല. അങ്ങയുടെ ആട്ടിൻപറ്റത്തിലെ മുട്ടാടുകളെ ഞാൻ ഭക്ഷിച്ചിട്ടുമില്ല.","p":1},{"v":39,"t":"കാട്ടുമൃഗങ്ങൾ കടിച്ചു കീറിയവയെ ഞാൻ അങ്ങയുടെയടുത്തു കൊണ്ടുവന്നിട്ടില്ല. ആ നഷ്ടം ഞാൻതന്നെ വഹിച്ചു. രാത്രിയിൽ കളവുപോയതിനും പകൽ കളവുപോയതിനും അങ്ങ് എന്റെ കയ്യിൽനിന്നുതന്നെ അത് ഈടാക്കിയിരുന്നു.","p":1},{"v":40,"t":"പകൽ ഉഷ്ണവും രാത്രി ശൈത്യവും എന്നെ കാർന്നുതിന്നു. ഉറക്കം എന്റെ കണ്ണുകളിൽനിന്ന് ഓടിയകന്നു. അതായിരുന്നു എന്റെ സ്ഥിതി.","p":1},{"v":41,"t":"എന്റെ ഈ ഇരുപതു വർഷവും ഞാൻ അങ്ങയുടെ വീട്ടിലായിരുന്നു. പതിനാലു വർഷം അങ്ങയുടെ രണ്ടു പെൺമക്കൾക്കുവേണ്ടിയും ആറു വർഷം ആടുകൾക്കുവേണ്ടിയും ഞാൻ വേലചെയ്തു. പത്തു തവണ അങ്ങ് എന്റെ കൂലിയിൽ മാറ്റംവരുത്തി.","p":1},{"v":42,"t":"എന്റെ പിതാവിന്റെ ദൈവം, അബ്രാഹത്തിന്റെ ദൈവവും ഇസഹാക്കിന്റെ ഭീതിയുമായവൻ, എന്റെ ഭാഗത്തില്ലായിരുന്നുവെങ്കിൽ ഇപ്പോൾ അങ്ങ് എന്നെ വെറുംകൈയോടെ പറഞ്ഞയയ്ക്കുമായിരുന്നു. എന്റെ കഷ്ടപ്പാടും എന്റെ ഉള്ളംകൈയുടെ അധ്വാനവും ദൈവം കണ്ടു. അതുകൊണ്ടാണ് കഴിഞ്ഞരാത്രി അവിടുന്ന് അങ്ങയെ ശകാരിച്ചത്.","p":1},{"h":"ലാബാനുമായി ഉടമ്പടി"},{"v":43,"t":"ലാബാൻ യാക്കോബിനോടു മറുപടിയായി പറഞ്ഞു: ഈ പെൺമക്കൾ എന്റെ പുത്രിമാരും ഈ കുട്ടികൾ എന്റെ കുട്ടികളും ഈ ആട്ടിൻപറ്റം എന്റെ ആട്ടിൻപറ്റവുമാണ്. നീ കാണുന്നതൊക്കെ എന്റേതാണ്. എന്റെ ഈ പെൺമക്കൾക്കുവേണ്ടിയാകട്ടെ, അവർ പ്രസവിച്ച കുട്ടികൾക്കുവേണ്ടിയാകട്ടെ, ഞാൻ എന്താണ് ഇന്ന് ചെയ്യേണ്ടത്?","p":1},{"v":44,"t":"ആകയാൽ ഇപ്പോൾ വരിക, നമുക്കൊരു ഉടമ്പടിയുണ്ടാക്കാം - ഞാനും നീയും തമ്മിൽ. അത് എനിക്കും നിനക്കും മധ്യേ ഒരു സാക്ഷ്യമായിരിക്കട്ടെ.","p":1},{"v":45,"t":"അപ്പോൾ യാക്കോബ് ഒരു കല്ലെടുത്ത്, അത് ഒരു തൂണായി ഉയർത്തി.","p":1},{"v":46,"t":"കല്ലുകൾ പെറുക്കിക്കൂട്ടുവിൻ യാക്കോബ് തന്റെ ചാർച്ചക്കാരോടു പറഞ്ഞു. അവർ കല്ലുകളെടുത്ത് ഒരു കുമ്പാരം കൂട്ടി. അവിടെ ആ കുമ്പാരത്തിന്മേൽ അവർ ഭക്ഷണം കഴിച്ചു.","p":1},{"v":47,"t":"ലാബാൻ അതിനെ യെഗാർസാഹദൂത്ത എന്നുവിളിച്ചു. യാക്കോബ് അതിനെ ഗലേദ് എന്നും.","p":1},{"v":48,"t":"ഈ കുമ്പാരം ഇന്ന് എനിക്കും നിനക്കും മധ്യേ സാക്ഷ്യമായിരിക്കും, ലാബാൻ പറഞ്ഞു. അതുകൊണ്ട്, ഗലേദ് എന്ന് അതിനു പേരിട്ടു.","p":1},{"v":49,"t":"അതാണ് മിസ്പാ. എന്തെന്നാൽ, ഒരുവൻ തന്റെ അയൽക്കാരനിൽനിന്ന് മറയുമ്പോൾ, കർത്താവ് എനിക്കും നിനക്കും മധ്യേ കാവലായിരിക്കട്ടെ എന്ന് അവൻ പറഞ്ഞിരുന്നു.","p":1},{"v":50,"t":"എന്റെ പുത്രിമാരെ നീ പീഡിപ്പിക്കുകയോ എന്റെ പുത്രിമാർക്കുപുറമേ നീ വേറെ ഭാര്യമാരെ സ്വീകരിക്കുകയോ ചെയ്താൽ, ആരും നമ്മോടൊപ്പമില്ലെങ്കിലും, ദൈവം എനിക്കും നിനക്കും മധ്യേ സാക്ഷിയായുണ്ടെന്ന് കണ്ടാലും.","p":1},{"v":51,"t":"ലാബാൻ യാക്കോബിനോടു പറഞ്ഞു: എനിക്കും നിനക്കും മധ്യേ ഞാൻ ഉയർത്തിയിരിക്കുന്ന കുമ്പാരം ഈ സ്തംഭവും ഇതാ!","p":1},{"v":52,"t":"ദ്രോഹലക്ഷ്യത്തോടെ നിന്റെ അടുത്തേക്ക് ഞാൻ ഈ കൂമ്പാരം കടക്കാതിരിക്കാനും","p":1},{"v":52,"t":"എന്റെ അടുത്തേക്ക് ഈ കൂമ്പാരവും സ്തംഭവും നീ കടക്കാതിരിക്കാനും ഈ കുമ്പാരം ഒരു സാക്ഷ്യമാണ്; ഈ സ്തംഭവും സാക്ഷ്യമാണ്.","p":1},{"v":53,"t":"അബ്രാഹത്തിന്റെ ദൈവം, നാഹോറിന്റെ ദൈവം, അവരുടെ പിതാവിന്റെ ദൈവം നമുക്കുമധ്യേ ന്യായവിധി നടത്തട്ടെ. യാക്കോബും തന്റെ പിതാവായ ഇസഹാക്കിന്റെ ഭീതിയായവനെക്കൊണ്ട് സത്യംചെയ്തു.","p":1},{"v":54,"t":"മലമുകളിൽ യാക്കോബ് ബലി സമർപ്പിച്ചു; അപ്പം ഭക്ഷിക്കാൻ തന്റെ ചാർച്ചക്കാരെ ക്ഷണിക്കുകയും ചെയ്തു. അവർ അപ്പം ഭക്ഷിച്ചശേഷം മലമുകളിൽ രാപാർത്തു.","p":1}],"32":[{"v":1,"t":"ലാബാൻ പ്രഭാതത്തിൽ ഉണർന്ന് തന്റെ പേരക്കുട്ടികളെയും പെൺമക്കളെയും ചുംബിക്കുകയും അവരെ അനുഗ്രഹിക്കുകയും ചെയ്തു. എന്നിട്ട് ലാബാൻ നടന്ന് സ്വന്തം സ്ഥലത്തേക്കു തിരിച്ചുപോയി.","p":1},{"v":2,"t":"യാക്കോബാകട്ടെ, തന്റെ വഴിക്കും നടന്നു. അപ്പോൾ ദൈവത്തിന്റെ ദൂതന്മാർ അവനെ കണ്ടുമുട്ടി.","p":1},{"v":3,"t":"അവരെ കണ്ടപ്പോൾ യാക്കോബു പറഞ്ഞു: ഇതു ദൈവത്തിന്റെ പാളയമാണ്. ആ സ്ഥലത്തിന് അവൻ മഹനായിം എന്നു പേരുവിളിച്ചു.","p":1},{"v":4,"t":"യാക്കോബ് തന്റെ സഹോദരനായ ഏസാവിന്റെ അടുത്തേക്ക്, സെയീർനാട്ടിൽ ഏദോമിന്റെ വയലിലേക്ക്, തനിക്കുമുമ്പേ ദൂതന്മാരെ അയച്ചു.","p":1},{"v":5,"t":"അവൻ ഇപ്രകാരം അവരോടു നിർദേശിച്ചു: എന്റെ യജമാനനായ ഏസാവിനോടു നിങ്ങൾ ഇങ്ങനെ പറയണം, 'അങ്ങയുടെ ദാസനായ യാക്കോബ് ഇപ്രകാരം പറയുന്നു: ലാബാന്റെകൂടെ താൽക്കാലവാസിയായിരുന്ന ഞാൻ ഇതുവരെയും അവിടെയായിരുന്നു.","p":1},{"v":6,"t":"എനിക്ക് കാള, കഴുത, ആട്, ദാസൻ, പരിചാരിക എന്നിവ ഉണ്ടായിട്ടുണ്ട്. എന്റെ യജമാനനോടു വിവരിക്കുന്നതിനും അങ്ങയുടെ ദൃഷ്ടികളിൽ ദയ കണ്ടെത്തുന്നതിനും വേണ്ടിയാണ് ഞാൻ ആളയയ്ക്കുന്നത്'.","p":1},{"v":7,"t":"ദൂതന്മാർ യാക്കോബിന്റെ പക്കൽ, 'ഞങ്ങൾ അങ്ങയുടെ സഹോദരനായ ഏസാവിന്റെയടുക്കൽചെന്നു; അവൻതന്നെ നാനൂറ് ആളുകളുടെ അകമ്പടിയോടെ അങ്ങയെ സ്വീകരിക്കാൻ വരുന്നുണ്ട്' എന്നു പറഞ്ഞുകൊണ്ടു തിരിച്ചുവന്നു.","p":1},{"v":8,"t":"യാക്കോബ് വളരെയധികം ഭയപ്പെട്ടു; അവനു വേവലാതിയായി. തന്റെകൂടെയുണ്ടായിരുന്ന ആളുകളെയും ആടുമാടുകളെയും ഒട്ടകങ്ങളെയും അവൻ രണ്ടു സംഘമായി തിരിച്ചു.","p":1},{"v":9,"t":"ഏസാവ് ഒന്നാമത്തെ സംഘത്തിലെത്തി അതിനെ ആക്രമിക്കുന്നപക്ഷം, ശേഷിക്കുന്ന സംഘം സുരക്ഷിതമായിരിക്കുമല്ലോ എന്ന് അവൻ ചിന്തിച്ചു.","p":1},{"v":10,"t":"യാക്കോബു പറഞ്ഞു: എന്റെ പിതാവായ അബ്രാഹത്തിന്റെ ദൈവമേ, എന്റെ പിതാവായ ഇസഹാക്കിന്റെ ദൈവമേ, 'നിന്റെ നാട്ടിലേക്കും നിന്റെ സഹജരുടെ അടുത്തേക്കും തിരിയെപ്പോകുക, നിനക്കു ഞാൻ എല്ലാം ശുഭമാക്കും' എന്ന് എന്നോടരുളച്ചെയ്ത കർത്താവേ,","p":1},{"v":11,"t":"'അങ്ങയുടെ ദാസനോട് അങ്ങ് ചെയ്ത സകല കൃപകൾക്കും സകല വിശ്വസ്തതയ്ക്കും ഞാൻ ഒട്ടും അർഹനല്ല. കേവലം എന്റെ ഒരു വടിയുമായാണ് ഞാൻ ഈ ജോർദാൻ കടന്നത്. ഇപ്പോൾ ഇതാ ഞാൻ രണ്ടു സംഘമായിത്തീർന്നിരിക്കുന്നു.","p":1},{"v":12,"t":"എന്റെ സഹോദരന്റെ കൈയിൽനിന്ന്, ഏസാവിന്റെ കൈയിൽനിന്ന്, എന്നെ സദയം രക്ഷിക്കണമേ. കാരണം, ഞാൻ അവനെ ഭയപ്പെടുന്നു. അവൻ വന്ന് അമ്മയോടും മക്കളോടുമൊപ്പം എന്നെ കൊല്ലാൻ ഇടവരുത്തരുതേ.","p":1},{"v":13,"t":"മാത്രമല്ല, 'ഞാൻ തീർച്ചയായും നിനക്കു ശുഭം വരുത്തും; നിന്റെ സന്തതിയെ പെറുപ്പമൂലം എണ്ണാനാവാത്ത കടൽമണൽത്തരിപോലെ ആക്കിത്തീർക്കും' എന്ന് അങ്ങ് അരുളച്ചെയ്തിട്ടുണ്ടല്ലോ.","p":1},{"v":14,"t":"ആ രാത്രി അവൻ അവിടെ കഴിഞ്ഞുകൂടി. പിന്നെ, തന്റെ കൈവശമുള്ളതിൽനിന്ന് അവൻ തന്റെ സഹോദരൻ ഏസാവിനുവേണ്ടിയുള്ള കാഴ്ച എടുത്തു:","p":1},{"v":15,"t":"ഇരുനൂറു പെൺകോലാട്, ഇരുപത് ആൺകോലാട്, ഇരുനൂറു പെൺചെമ്മരിയാട്, ഇരുപത് ആൺചെമ്മരിയാട്,","p":1},{"v":16,"t":"കറവയുള്ള മുപ്പത് ഒട്ടകം, അവയുടെ കിടാങ്ങൾ, നാൽപതു പശു, പത്തു കാള, ഇരുപതു പെൺകഴുത, പത്ത് ആൺകഴുത എന്നിവ.","p":1},{"v":17,"t":"ഈ ഓരോ കൂട്ടത്തെയും അവൻ തന്റെ ഭൃത്യന്മാരുടെ കൈവശം വെവ്വേറെ കൊടുത്തേൽപ്പിച്ചു. അവൻ തന്റെ ഭൃത്യന്മാരോടു പറഞ്ഞു: എനിക്കുമുമ്പേ നടന്നുനീങ്ങുവിൻ. കൂട്ടങ്ങൾ തമ്മിൽ അൽപം അകലമിട്ടിരിക്കണം.","p":1},{"v":18,"t":"ഏറ്റവും മുമ്പേ പോയവനെ അവൻ ഇപ്രകാരം ചുമതലപ്പെടുത്തി: എന്റെ സഹോദരൻ ഏസാവ് നിന്നെ കണ്ടുമുട്ടുമ്പോൾ അവൻ നിന്നോട് ഇങ്ങനെ അന്വേഷിക്കും: നീ ആരുടെ ആളാണ്, നീ എവിടേക്കു പോകുന്നു, നിന്റെ മുമ്പിലുള്ള ഇതെല്ലാം ആരുടേതാണ്?","p":1},{"v":19,"t":"അപ്പോൾ നീ പറയണം: അങ്ങയുടെ ദാസനായ യാക്കോബിന്റേതാണ്. എന്റെ യജമാനനായ ഏസാവിനു കൊടുത്തയച്ചിരിക്കുന്ന കാഴ്ചവസ്തുവാണിത്. അതാ, അവനും ഞങ്ങളുടെ പിന്നാലെയുണ്ട്.","p":1},{"v":20,"t":"തുടർന്ന് അവൻ രണ്ടാമത്തവനെയും മൂന്നാമത്തവനെയും കൂട്ടങ്ങൾക്കുപിമ്പേ നടന്നിരുന്ന എല്ലാവരെയും ഇപ്രകാരം ചുമതലപ്പെടുത്തി: നിങ്ങൾ ഏസാവിനെ കണ്ടുമുട്ടുമ്പോൾ ഇതുപോലെതന്നെ അവനോടു...കാര്യം പറയണം.","p":1},{"v":21,"t":"\"ഇതാ, അങ്ങയുടെ ദാസനായ യാക്കോബ് ഞങ്ങൾക്കു പിന്നാലെയുണ്ട്\" എന്നുകൂടി നിങ്ങൾ പറയണം. അങ്ങനെ, എനിക്കുമുമ്പേ നീങ്ങുന്ന കാഴ്ചവസ്തുക്കൊണ്ട് അവന്റെ മുഖം ഞാൻ മറയ്ക്കട്ടെ; അതു കഴിഞ്ഞ് ഞാൻ അവനെ നേരിൽക്കാണും; ഒരുപക്ഷേ, അവൻ എന്നെ സ്വീകരിക്കും എന്ന് അവൻ പറഞ്ഞു.","p":1},{"v":22,"t":"അങ്ങനെ കാഴ്ചവസ്തു അവനുമുമ്പേ കടന്നുപോയി. അവനാകട്ടെ, ആ രാത്രി പാളയത്തിൽ പാർത്തു.","p":1},{"h":"യാക്കോബിന്റെ മല്പിടുത്തം"},{"v":23,"t":"അവൻ രാത്രിയിൽ ഉണർന്ന് തന്റെ രണ്ടു ഭാര്യമാരെയും തന്റെ രണ്ടു പരിചാരികമാരെയും തന്റെ പതിനൊന്നു മക്കളെയും കൂട്ടിക്കൊണ്ട് യാബ്ബോക്കിന്റെ കടവു കടന്നു.","p":1},{"v":24,"t":"അവൻ അവരെയെടുത്ത് പുഴയ്ക്കക്കരെ കടത്തിവിട്ടു. തനിക്കുണ്ടായിരുന്നതെല്ലാം അവൻ അക്കരെയെത്തിച്ചു.","p":1},{"v":25,"t":"യാക്കോബു മാത്രം അവശേഷിച്ചു. അപ്പോൾ ഒരാൾ പ്രഭാതം വിടരുന്നതുവരെ അവനുമായി മല്പിടുത്തം നടത്തി.","p":1},{"v":26,"t":"അവനോടു ജയിക്കില്ലെന്നു കണ്ടപ്പോൾ അയാൾ യാക്കോബിന്റെ എളിയീൽ ഇടിച്ചു. അവനുമായുള്ളയാളുടെ മല്പിടുത്തത്തിനിടയിൽ യാക്കോബിന്റെ എളിക്കുഴ തെറ്റി.","p":1},{"v":27,"t":"അയാൾ പറഞ്ഞു: എന്നെ വിട്ടയച്ചാലും; കാരണം, പ്രഭാതം വിടരുകയാണ്. അവൻ പറഞ്ഞു: എന്നെ അനുഗ്രഹിച്ചിട്ടല്ലാതെ അങ്ങയെ ഞാൻ വിട്ടയയ്ക്കുകയില്ല.","p":1},{"v":28,"t":"അയാൾ അവനോടു ചോദിച്ചു: നിന്റെ പേരെന്താണ്? അവൻ പറഞ്ഞു: യാക്കോബ്.","p":1},{"v":29,"t":"അപ്പോൾ അയാൾ പറഞ്ഞു: ഇനിമേൽ നിന്റെ പേര് യാക്കോബ് എന്നല്ല, പ്രത്യുത, ഇസ്രായേൽ എന്നു പറയപ്പെടും. കാരണം, നീ ദൈവത്തോടും മനുഷ്യരോടും മല്ലിട്ട് ജയിച്ചിരിക്കുന്നു.","p":1},{"v":30,"t":"അപ്പോൾ യാക്കോബ് ജിജ്ഞാസയോടെ അഭ്യർത്ഥിച്ചു: അങ്ങയുടെ പേര് വെളിപ്പെടുത്തിയാലും. അതിന് അയാൾ പറഞ്ഞു: നീ എന്റെ പേര് അന്വേഷിക്കുന്നതെന്തിന്? എന്നിട്ട്, അവിടെവെച്ച് അയാൾ യാക്കോബിനെ അനുഗ്രഹിച്ചു.","p":1},{"v":31,"t":"അപ്പോൾ യാക്കോബ് ഉദ്ഘോഷിച്ചു: ഈ സ്ഥലത്തിന്റെ പേര് പെനിയേൽ എന്നാണ്; കാരണം, ദൈവത്തെ ഞാൻ മുഖാമുഖം കണ്ടു. എന്നിട്ടും എന്റെ ജീവൻ സുരക്ഷിതമായിരിക്കുന്നു!","p":1},{"v":32,"t":"അവൻ പെനുവേൽ കടന്നപ്പോഴേക്കും സൂര്യൻ ഉദിച്ചിരുന്നു. അവനാകട്ടെ, തന്റെ എളിമൂലം മുളന്തുകയായിരുന്നു.","p":1},{"v":33,"t":"അവിടുന്ന് യാക്കോബിന്റെ എളിക്കൂഴിയിൽ, തുടയുടെ സ്‌നായുഭാഗത്ത്, ഇടിച്ചതുകൊണ്ട് ഇസ്രായേല്യർ ഇന്നും തുടയുടെ സ്‌നായു ഭക്ഷിക്കാറില്ല.","p":1}],"33":[{"h":"ഏസാവിനെ കണ്ടുമുട്ടുന്നു"},{"v":1,"t":"യാക്കോബ് തന്റെ കണ്ണുകളുയർത്തി നോക്കി: ഇതാ, ഏസാവ് അയാളോടൊപ്പം നാന്നൂറു പുരുഷന്മാരുമായി വരുന്നു. അപ്പോൾ യാക്കോബ് മക്കളെ ലെയായുടെ പക്കലും റാഹേലിന്റെ പക്കലും രണ്ടു പരിചാരികമാരുടെ പക്കലുമായി വേർതിരിച്ചു.","p":1},{"v":2,"t":"അവൻ പരിചാരികമാരെയും അവരുടെ മക്കളെയും മുന്നിലും, ലെയായെയും അവളുടെ മക്കളെയും അതിനുപുറകിലും, റാഹേലിനെയും ജോസഫിനെയും ഏറ്റവും പുറകിലും നിർത്തി.","p":1},{"v":3,"t":"എന്നിട്ട്, അവൻ അവരുടെ മുമ്പേ നീങ്ങി. തന്റെ സഹോദരന്റെ അടുത്തെത്തുവോളം അവൻ ഏഴു തവണ നിലംമുട്ടേ കുമ്പിട്ടു.","p":1},{"v":4,"t":"ഏസാവാകട്ടെ, അവനെ സ്വീകരിക്കാനായി ഓടിവന്നു; അവനെ ആലിംഗനംചെയ്തു; അവന്റെ കഴുത്തിൽവീണ് അവനെ ചുംബിച്ചു; അവർ കരഞ്ഞു.","p":1},{"v":5,"t":"അയാൾ തന്റെ കണ്ണുകളുയർത്തിയപ്പോൾ സ്ത്രീകളെയും കുട്ടികളെയും കണ്ടു. അപ്പോൾ അയാൾ ചോദിച്ചു: ഇവർ നിന്റെ ആരാണ്? അവൻ പറഞ്ഞു: ദൈവം അങ്ങയുടെ ദാസനു ചെയ്ത ഔദാര്യമാണ് ഈ കുട്ടികൾ.","p":1},{"v":6,"t":"അപ്പോൾ പരിചാരികമാർ, അവരും അവരുടെ മക്കളും, അടുത്തുചെന്ന് വണങ്ങി.","p":1},{"v":7,"t":"തുടർന്ന് ലെയായും അവളുടെ മക്കളും അടുത്തുചെന്ന് വണങ്ങി. അതിനുശേഷം ജോസഫും റാഹേലും അടുത്തുചെന്ന് വണങ്ങി.","p":1},{"v":8,"t":"അവൻ ചോദിച്ചു: ഞാൻ കണ്ടുമുട്ടിയ ആ സംഘമെല്ലാം നിന്റെ ആരാണ്? യാക്കോബു പറഞ്ഞു: എന്റെ യജമാനന്റെ ദൃഷ്ടികളിൽ പ്രീതി സമ്പാദിക്കാൻ വേണ്ടിയുള്ളതാണ്.","p":1},{"v":9,"t":"ഏസാവു പറഞ്ഞു: എന്റെ സഹോദരാ, എനിക്കതു വേണ്ടത്രയുണ്ട്; നിന്റേത് നിനക്കുതന്നെയിരിക്കട്ടെ.","p":1},{"v":10,"t":"യാക്കോബ് പറഞ്ഞു: അരുതേ! അങ്ങയുടെ ദൃഷ്ടികളിൽ ഞാൻ പ്രീതി കണ്ടെത്തിയിട്ടുണ്ടെങ്കിൽ, എന്റെ കയ്യിൽനിന്ന് എന്റെ കാഴ്ചവസ്തു സ്വീകരിക്കണം. കാരണം, തീർച്ചയായും ദൈവത്തിന്റെ മുഖം കണ്ടാലെന്നപോലെയാണ് ഞാൻ അങ്ങയുടെ മുഖം കണ്ടത്; അങ്ങ് എന്നിൽ സംപ്രീതനാകുകയും ചെയ്തിരിക്കുന്നു.","p":1},{"v":11,"t":"ദൈവം എന്നോട് ഔദാര്യം കാണിച്ചിരിക്കുന്നതിനാലും എനിക്ക് എല്ലാം ഉള്ളതിനാലും അങ്ങയ്ക്കായി എത്തിച്ചിരിക്കുന്ന എന്റെ കാഴ്ച സ്വീകരിച്ചാലും. അവൻ അയാളെ നിർബന്ധിച്ചപ്പോൾ അയാൾ അതു സ്വീകരിച്ചു.","p":1},{"v":12,"t":"അയാൾ പറഞ്ഞു: നമുക്കു യാത്രയാകാം; നമുക്കു പുറപ്പെടാം. ഞാൻ നിന്റെ മുമ്പേ നടക്കാം.","p":1},{"v":13,"t":"അവൻ അയാളോടു പറഞ്ഞു:എന്റെ യജമാനനേ, കുട്ടികളൊക്കെ ക്ഷീണിച്ചിരിക്കുകയാണെന്ന് അങ്ങേക്കറിയാമല്ലോ. കരവയുള്ള ആടുമാടുകളും എന്റെ ചുമതലയിലുണ്ട്. ഒരു ദിവസത്തേക്കാണെങ്കിലും കൂടുതലായി ഓടിച്ചാൽ ആട്ടിൻപറ്റംമുഴുവൻ ചത്തുപോകും.","p":1},{"v":14,"t":"എന്റെ യജമാനൻ അങ്ങേ ദാസനുമുമ്പേ പോയാലും. ഞാനാകട്ടെ, സെയീരിലേക്ക്, എന്റെ യജമാനന്റെ അടുത്തേക്കു വന്നെത്തുന്നതുവരെ, എന്റെ മുമ്പിലുള്ള കന്നുകാലികളുടെ നടപ്പിനൊത്ത്, കുട്ടികളുടെ നടപ്പിനൊത്ത്, സാവകാശം മുന്നേറാം.","p":1},{"v":15,"t":"എന്റെകൂടെയുള്ള ജനത്തിൽനിന്ന് കുറേപ്പേരെ ഞാൻ നിന്റെകൂടെ നിർത്താം എന്ന് ഏസാവ് പറഞ്ഞപ്പോൾ അവൻ ചോദിച്ചു: അതെന്തിനാണ്? ഞാൻ എന്റെ യജമാനന്റെ ദൃഷ്ടികളിൽ ദയ കണ്ടെത്തുന്നല്ലോ.","p":1},{"v":16,"t":"ഏസാവ് അന്നുതന്നെ തന്റെ വഴിക്കു സെയീരിലേക്കു തിരിയെപ്പോയി.","p":1},{"v":17,"t":"യാക്കോബാകട്ടെ, സുക്കോത്തിലേക്കു നീങ്ങി. പിന്നെ തനിക്ക് ഒരു വീട് പണിതു; തന്റെ കാലിക്കൂട്ടത്തിന് കൂടുകളും കെട്ടി. അതുകൊണ്ടാണ് ആ സ്ഥലത്തെ സുക്കോത്ത് എന്നു പേരുവിളിക്കുന്നത്.","p":1},{"v":18,"t":"യാക്കോബ് പാദാൻആരാമിൽനിന്നു പുറപ്പെട്ട് കാനാൻദേശത്തുള്ള ഷെക്കെംപട്ടണത്തിൽ സുരക്ഷിതനായി എത്തിച്ചേർന്നു. അവിടെ നഗരത്തിനുമുമ്പിലായി പാളയമടിച്ചു.","p":1},{"v":19,"t":"തന്റെ കൂടാരമടിച്ച വയൽഭാഗം ഷെക്കെമിന്റെ പിതാവായ ഹാ മോറിന്റെ മക്കളിൽനിന്ന്, നൂറു ഖെസീഥായ്ക്ക് അവൻ വാങ്ങി.","p":1},{"v":20,"t":"അവൻ അവിടെ ഒരു ബലിപീഠം സ്ഥാപിച്ചു. അതിനെ ഏൽ-ഏലൊഹെയ്-ഇസ്രായേൽ എന്നു വിളിച്ചു.","p":1}],"34":[{"h":"ദീനായുടെ മാനഭംഗം"},{"v":1,"t":"യാക്കോബിനുവേണ്ടി ലെയാ പ്രസവിച്ച മകൾ ദീനാ ആ നാട്ടിലെ പെൺകുട്ടികളെ കാണാനിറങ്ങി.","p":1},{"v":2,"t":"നാടിന്റെ പ്രഭുവായ ഹാമോർ എന്ന ഹിവ്യന്റെ മകൻ ഷെക്കെം അവളെ കണ്ടു. അവൻ അവളെ പിടികൂടി അവളോടൊത്തു ശയിച്ച് പീഡിപ്പിച്ചു.","p":1},{"v":3,"t":"ഒപ്പം, അവന്റെ ആത്മാവ് യാക്കോബിന്റെ മകളായ ദീനയിൽ ലയിച്ചു. അവൻ ആ പെൺകുട്ടിയെ പ്രണയിച്ചു. അവൻ ആ പെൺകുട്ടിയോട് ഹൃദയപൂർവം സംസാരിച്ചു.","p":1},{"v":4,"t":"ഷെക്കെം തന്റെ പിതാവായ ഹാമോറിനോട് ഇപ്രകാരം പറഞ്ഞു: ഈ തരുണിയെ എനിക്കു ഭാര്യയാക്കിത്തരണം.","p":1},{"v":5,"t":"തന്റെ മകളായ ദീനായെ അവൻ കളങ്കിതയാക്കി എന്നു യാക്കോബു കേട്ടു. അവന്റെ പുത്രന്മാർ അവന്റെ കാലിക്കൂട്ടത്തോടൊപ്പം വയലിലായിരുന്നു. അവർ വരുന്നതുവരെ യാക്കോബ് സംയമനംപാലിച്ചു.","p":1},{"v":6,"t":"അപ്പോൾ, ഷെക്കെമിന്റെ പിതാവായ ഹാ മോർ യാക്കോബിനോട് സംസാരിക്കാനായി അവന്റെ അടുത്തേക്ക് തിരിച്ചു","p":1},{"v":7,"t":"കേട്ടമാത്രയിൽ, യാക്കോബിന്റെ പുത്രന്മാരും വയലിൽ നിന്ന് വന്നെത്തി. അവർ രോഷം കൊണ്ടു. യാക്കോബിന്റെ മകളുമൊത്തു ശയിച്ചതുവഴി ഇസ്രായേലിൽ മ്ലേച്ഛകൃത്യം ചെയ്തുകൊണ്ട് അവൻ അവരെ അതീവം കുപിതരാക്കി. അപ്രകാരം ചെയ്യപ്പെടാൻപാടില്ലായിരുന്നു.","p":1},{"v":8,"t":"അപ്പോൾ ഹാമോർ അവരോട് ഇപ്രകാരം പറഞ്ഞു: ഷെക്കെം എന്റെ മകനാണ്. അവന്റെ ആത്മാവ് നിങ്ങളുടെ പുത്രിയിൽ അനുരക്തമാണ്. അവളെ അവനു ഭാര്യയായി നൽകിയാലും.","p":1},{"v":9,"t":"ഞങ്ങളുമായി വിവാഹബന്ധത്തിലേർപ്പെടുവിൻ. നിങ്ങളുടെ പെൺമക്കളെ ഞങ്ങൾക്കു തരുവിൻ; ഞങ്ങളുടെ പെൺമക്കളെ നിങ്ങൾക്കായും സ്വീകരിക്കുവിൻ.","p":1},{"v":10,"t":"നിങ്ങൾ ഞങ്ങളുടെകൂടെ പാർക്കുവിൻ. ഈ നാടു നിങ്ങളുടെ മുൻപിലുണ്ടല്ലോ. അതിൽ വസിച്ച്, അതിനെ പ്രയോജനപ്പെടുത്തി, സമ്പാദ്യമുണ്ടാക്കുവിൻ.","p":1},{"v":11,"t":"തുടർന്ന് അവളുടെ പിതാവിനോടും സഹോദരന്മാരോടുമായി ഷെക്കെം പറഞ്ഞു: നിങ്ങളുടെ ദൃഷ്ടികളിൽ ഞാൻ പ്രീതി കണ്ടെത്തട്ടെ. നിങ്ങൾ എന്നോടു പറയുന്നതു ഞാൻ തരാം.","p":1},{"v":12,"t":"സ്ത്രീധനവും സമ്മാനവും എന്റെമേൽ അധികമായി വർധിപ്പിച്ചുകൊള്ളുവിൻ. നിങ്ങൾ എന്നോട് ആവശ്യപ്പെടുന്നതെന്തായാലും ഞാൻ തരുന്നതാണ്. പെൺകുട്ടിയെ ഭാര്യയായി എനിക്കു നൽകിയാൽമതി.","p":1},{"v":13,"t":"തങ്ങളുടെ സഹോദരി ദീനായെ ഷെക്കെം കളങ്കിതയാക്കിയതുകൊണ്ട് യാക്കോബിന്റെ മക്കൾ അവനോടും അവന്റെ പിതാവായ ഹാമോറിനോടും വഞ്ചനാപൂർവം മറുപടിപറഞ്ഞു.","p":1},{"v":14,"t":"അവർ അവനോടു പറഞ്ഞു: അഗ്രചർമം ഞങ്ങൾക്ക് അപമാനമായതുകൊണ്ട്, അതുള്ള ഒരാൾക്ക് ഞങ്ങളുടെ സഹോദരിയെ നൽകുക എന്ന ഇക്കാര്യം ചെയ്യുക ഞങ്ങൾക്കു സാധ്യമല്ല.","p":1},{"v":15,"t":"എന്നാൽ ഇങ്ങനെമാത്രം ഞങ്ങൾ നിങ്ങളോടു സമ്മതിക്കാം: നിങ്ങൾക്കിടയിലെ ഓരോ പുരുഷനും ഞങ്ങളെപ്പോലെയാകണം അതായത്, പരിച്ഛേദനം ചെയ്യപ്പെടണം.","p":1},{"v":16,"t":"അപ്പോൾ ഞങ്ങളുടെ പുത്രിമാരെ ഞങ്ങൾ നിങ്ങൾക്കു തരാം. നിങ്ങളുടെ പുത്രിമാരെ ഞങ്ങൾക്കായി സ്വീകരിക്കുകയും ചെയ്യാം. ഞങ്ങൾ നിങ്ങളോടൊത്തു വസിക്കുകയും നമ്മൾ ഒറ്റജനമായിത്തീരുകയും ചെയ്യും.","p":1},{"v":17,"t":"പരിച്ഛേദനം ചെയ്യുന്നതിൽ നിങ്ങൾ ഞങ്ങളെ കേൾക്കാത്തപക്ഷം, ഞങ്ങളുടെ മകളെയുംകൊണ്ട് ഞങ്ങൾ പോകും.","p":1},{"v":18,"t":"അവരുടെ വാക്കുകൾ ഹാമോറിന്റെ ദൃഷ്ടികളിലും ഹാമോറിന്റെ മകൻ ഷെക്കെമിന്റെ ദൃഷ്ടികളിലും ആകർഷകമായിരുന്നു.","p":1},{"v":19,"t":"അക്കാര്യം ചെയ്യാൻ ആ ചെറുപ്പക്കാരൻ അമാന്തിച്ചില്ല. കാരണം, യാക്കോബിന്റെ മകളിൽ അവൻ അനുരക്തനായിരുന്നു. തന്റെ പിതൃഭവനംമുഴുവനിലും അവൻ മതിക്കപ്പെട്ടവനായിരുന്നു.","p":1},{"v":20,"t":"ഹാമോറും സ്വപുത്രൻ ഷെക്കെമും തങ്ങളുടെ നഗര കവാടത്തിൽച്ചെന്ന് തങ്ങളുടെ പട്ടണത്തിലെ ആളുകളോട് ഇപ്രകാരം പറഞ്ഞു:","p":1},{"v":21,"t":"ഈ ആളുകൾ നമ്മോട് സൗഹാർദത്തിലാണ്. അവർ ഈ നാട്ടിൽ പാർത്ത്, അതു പ്രയോജനപ്പെടുത്തട്ടെ. നോക്കൂ, നാട് അവരുടെ മുൻപിൽ ഇരുമടങ്ങ് വിസ്തൃതമാണല്ലോ. അവരുടെ പുത്രിമാരെ നമുക്കു ഭാര്യമാരായി നമ്മൾ സ്വീകരിക്കും. നമ്മുടെ പുത്രിമാരെ നമ്മൾ അവർക്കു നൽകുകയും ചെയ്യും.","p":1},{"v":22,"t":"എന്നാൽ, ഇങ്ങനെമാത്രമാണ് ആ ആളുകൾ നമ്മോടൊത്തു വസിക്കാനും ഒറ്റജനമായിത്തീരാനും സമ്മതിച്ചിട്ടുള്ളത്: അതായത്, അവർ പരിച്ഛേദിതരായിരിക്കുന്നപോലെ, നമ്മുടെ ഓരോ പുരുഷനും പരിച്ഛേദിതനാകണം.","p":1},{"v":23,"t":"അവരുടെ കാലിക്കൂട്ടവും അവരുടെ സമ്പാദ്യവും അവരുടെ മൃഗസമ്പത്തുമുഴുവനും നമ്മുടേതാവില്ലേ? ആകയാൽ, നമുക്ക് അവരോടു സമ്മതിക്കാം. എങ്കിൽ, അവർ നമ്മുടെ കൂടെ താമസിക്കും.","p":1},{"v":24,"t":"അവന്റെ നഗരകവാടം കടന്ന എല്ലാവരും ഹാമോറിനെയും അവന്റെ മകൻ ഷെക്കെമിനെയും അനുസരിച്ചു; അങ്ങനെ, അവന്റെ നഗര കവാടം കടന്ന എല്ലാവരും, ഓരോ പുരുഷനും, പരിച്ഛേദനം ചെയ്യപ്പെട്ടു.","p":1},{"v":25,"t":"മൂന്നാംദിവസം അവർ വേദനിച്ചിരിക്കേ, യാക്കോബിന്റെ രണ്ടു പുത്രന്മാർ, ദീനായുടെ സഹോദരന്മാർ, ശിമയോനും ലേവിയും താന്താങ്ങളുടെ വാളെടുത്ത് അപ്രതിരോധ്യരായി നഗരത്തിൽ കടന്ന് ഓരോ പുരുഷനെയും വധിച്ചു.","p":1},{"v":26,"t":"ഹാമോറിനെയും അവന്റെ മകൻ ഷെക്കെമിനെയും അവർ വാളിന്റെ വായ്ത്തലയ്ക്ക് ഇരയാക്കി. ഷെക്കെമിന്റെ വീട്ടിൽനിന്നു ദീനായെ വീണ്ടെടുത്ത് അവർ പുറത്തുകടന്നു.","p":1},{"v":27,"t":"തങ്ങളുടെ സഹോദരിയെ അവർ കളങ്കിതയാക്കിയതിനാൽ വധിക്കപ്പെട്ടവരുടെയിടയിലൂടെ യാക്കോബിന്റെ മക്കൾ വന്ന് നഗരം കൊള്ളയടിച്ചു.","p":1},{"v":28,"t":"അവരുടെ ആടുമാടുകളെയും അവരുടെ കഴുതകളെയും നഗരത്തിലും വയലിലുമുണ്ടായിരുന്നവയും അവർ എടുത്തുകൊണ്ടുപോയി.","p":1},{"v":29,"t":"അവരുടെ സർവസമ്പത്തും വീട്ടുവകകളൊക്കെയും അവർ കൊള്ളയടിക്കുകയും അവരുടെ ഓരോ കുഞ്ഞിനെയും അവരുടെ സ്ത്രീകളെയും ബന്ധനസ്ഥരാക്കുകയും ചെയ്തു.","p":1},{"v":30,"t":"അപ്പോൾ യാക്കോബ് ശിമയോനോടും ലേവിയോടും പറഞ്ഞു: തദേശവാസികൾക്കിടയിൽ - കാനാന്യർക്കിടയിലും പെരീസ്യർക്കിടയിലും - എന്നെ അപഹാസ്യനാക്കുംവിധം നിങ്ങൾ എന്നെ കുഴപ്പത്തിലാക്കിയിരിക്കുന്നു. ഞാൻ ആളെണ്ണം കുറഞ്ഞവനാണ്. അവർ എനിക്കെതിരേ സംഘടിച്ച് എന്നെ ആക്രമിക്കും. അപ്പോൾ ഞാൻ, ഞാനും എന്റെ കുടുംബവും, നിർമാർജനം ചെയ്യപ്പെടും.","p":1},{"v":31,"t":"അപ്പോൾ അവർ ചോദിച്ചു: ഞങ്ങളുടെ സഹോദരിയെ അവൻ ഒരു വേശ്യകണക്കേ ആക്കാമെന്നോ?","p":1}],"35":[{"h":"യാക്കോബ് വീണ്ടും ബേഥേലിൽ"},{"v":1,"t":"ദൈവം യാക്കോബിനോട് അരുൾചെയ്തു: എഴുന്നേറ്റ് ബേഥേലിലേക്കു കയറി അവിടെ പാർക്കുക. നിന്റെ സഹോദരനായ ഏസാവിന്റെ മുൻപിൽനിന്നു നീ പളായനം ചെയ്തപ്പോൾ നിനക്കു പ്രത്യക്ഷപ്പെട്ട ദൈവത്തിന് അവിടെ ഒരു ബലിപീഠമുണ്ടാക്കുക.","p":1},{"v":2,"t":"അതുകൊണ്ട്, യാക്കോബ് തന്റെ കുടുംബത്തോടും കൂടെയുണ്ടായിരുന്ന എല്ലാവരോടുമായി പറഞ്ഞു: നിങ്ങളുടെ ഇടയിലുള്ള അന്യദേവന്മാരെ ദൂരെക്കളയുവിൻ; നിങ്ങളെത്തന്നെ ശുദ്ധീകരിപ്പിൻ; നിങ്ങളുടെ വസ്ത്രങ്ങൾ മാറുവിൻ.","p":1},{"v":3,"t":"നമുക്ക് എഴുന്നേറ്റ് ബേഥേലിലേക്കു കയറാം. എന്റെ കഷ്ടതയുടെ ദിനത്തിൽ എനിക്ക് ഉത്തരമരുളിയ ദൈവത്തിന് ഞാൻ അവിടെ ഒരു ബലിപീഠം പണിയട്ടെ; ഞാൻ പ്രയാണംചെയ്ത വഴിയിൽ അവിടുന്ന് എന്നോടുകൂടെയുണ്ടായിരുന്നു.","p":1},{"v":4,"t":"തങ്ങളുടെ കൈവശമുണ്ടായിരുന്ന എല്ലാ അന്യദേവന്മാരെയും തങ്ങളുടെ കർണാഭരണങ്ങളും അവർ യാക്കോബിനു നൽകി. യാക്കോബ് അവ ഷെക്കെമിനടുത്തുള്ള ഓക്കുമരത്തിന്റെ ചുവട്ടിൽ കുഴിച്ചുമൂടി.","p":1},{"v":5,"t":"അവർ യാത്രതിരിച്ചു; അവർക്കു ചുറ്റുമുള്ള നഗരങ്ങളുടെമേൽ ദൈവീകമായ ഭീതിയുണ്ടായി. അതുകൊണ്ട് യാക്കോബിന്റെ മക്കളെ അവർ പിന്തുടർന്നില്ല.","p":1},{"v":6,"t":"അങ്ങനെ യാക്കോബ്, അവനും അവനോടുകൂടെയുണ്ടായിരുന്ന ജനമുഴുവനും, കാനാൻനാട്ടിലെ ലൂസിൽ വന്നുചേർന്നു; അതുതന്നെയാണ് ബേഥേൽ.","p":1},{"v":7,"t":"അവിടെ അവൻ ഒരു ബലിപീഠം പണിയുകയും ആ സ്ഥലത്തിന് ഏൽ ബേഥേൽ എന്ന് പേരിടുകയും ചെയ്തു. കാരണം, സ്വന്തം സഹോദരന്റെ മുൻപിൽനിന്ന് ഒളിച്ചോടിയപ്പോൾ ദൈവം തന്നെത്തന്നെ അവനു വെളിപ്പെടുത്തിയത് അവിടെവച്ചാണ്.","p":1},{"v":8,"t":"റബെക്കാക്കായുടെ പരിചാരികയായ ദബോറ മരണമടഞ്ഞു. ബേഥേലിന്റെ താഴ്‌വരയിലുള്ള ഓക്കുമരത്തിൻകീഴെ അവൾ സംസ്‌കരിക്കപ്പെട്ടു. അലോൺ ബാക്കൂത്ത് എന്ന് അതിന് പേരുവിളിക്കുകയും ചെയ്തു.","p":1},{"v":9,"t":"പാദാൻആരാമിൽനിന്നു യാക്കോബു പോന്നപ്പോൾ ദൈവം അവനു വീണ്ടും പ്രത്യക്ഷപ്പെട്ട്, അവനെ അനുഗ്രഹിച്ചു.","p":1},{"v":10,"t":"ദൈവം അവനോട് അരുൾചെയ്തു: യാക്കോബ് എന്നാണ് നിന്റെ പേര്, ഇനിമേൽ നിന്റെ പേര് യാക്കോബ് എന്നല്ല വിളിക്കപ്പെടുന്നത്. പ്രത്യുത, നിന്റെ പേര് ഇസ്രായേൽ എന്നായിരിക്കും. അവിടുന്ന് അവന്റെ പേര് ഇസ്രായേൽ എന്നു വിളിച്ചു.","p":1},{"v":11,"t":"ദൈവം അവനോട് അരുൾചെയ്തു: ഞാനാണ് സർവശക്തനായ തമ്പുരാൻ. നീ സന്താനമുള്ളവനായി പെരുകുക. ജനതയും ജനതകളുടെ സമൂഹവും നിന്നിൽനിന്ന് ഉദ്ഭവിക്കും; രാജാക്കന്മാർ നിന്റെ അരക്കെട്ടിൽനിന്ന് പുറപ്പെടും.","p":1},{"v":12,"t":"അബ്രാഹത്തിനും ഇസഹാക്കിനും ഞാൻ നൽകിയ നാട് നിനക്കു ഞാൻ തരും; നിനക്കുശേഷം നിന്റെ സന്തതിക്കും ഞാൻ ആ നാടു നൽകും.","p":1},{"v":13,"t":"അനന്തരം, അവനുമായി സംസാരിച്ച സ്ഥലത്ത്, അവനുമുകളിൽനിന്ന് ദൈവം ആരോഹണം ചെയ്തു.","p":1},{"v":14,"t":"അവിടുന്നു തന്നോടു സംസാരിച്ച സ്ഥലത്ത് യാക്കോബ് ഒരു സ്തംഭം നാട്ടി, ഒരു ശിലാസ്തംഭം. അതിന്മേൽ അവൻ ഒരു പാനീയബലിയർപ്പിക്കുകയും എണ്ണയൊഴിക്കുകയും ചെയ്തു.","p":1},{"v":15,"t":"ദൈവം തന്നോടു സംസാരിച്ച ആ സ്ഥലത്തിന് യാക്കോബ് ബേഥേൽ എന്നു പേരുവിളിച്ചു.","p":1},{"h":"റാഹേലിന്റെ മരണം"},{"v":16,"t":"ബേഥേലിൽനിന്ന് അവർ നീങ്ങി എഫ്രാത്തായായിൽ എത്താൻ ഒരു കിബ്‌റാ ദൂരം കൂടിയുള്ളപ്പോൾ റാഹേൽ പ്രസവിച്ചു. അവളുടെ പ്രസവത്തിൽ അവൾ തീവ്രവേദനകൊണ്ടു.","p":1},{"v":17,"t":"അവൾ തന്റെ പ്രസവത്തിൽ തീവ്രവേദനകൊണ്ടപ്പോൾ സുതികർമിണി അവളോടു പറഞ്ഞു: ഭയപ്പെടേണ്ട; എന്തെന്നാൽ, നിനക്ക് ഇതും ഒരു പുത്രൻതന്നെ.","p":1},{"v":18,"t":"എന്നാൽ, അവൾ മരിക്കുകയായിരുന്നുവെന്നതുകൊണ്ട്, അവളുടെ ആത്മാവു വേർപിരിയവേ, അവൾ അവനെ ബെൻ-ഓനി എന്നു പേരുവിളിച്ചു. എന്നാൽ, അവന്റെ പിതാവ് അവനെ ബെഞ്ചമിൻ എന്നാണ് വിളിച്ചത്.","p":1},{"v":19,"t":"റാഹേൽ നിര്യാതയായി ബെത്‌ലെഹെം എന്ന എഫ്രാത്തിലേക്കുള്ള വഴിയിൽ അവൾ സംസ്‌കരിക്കപ്പെട്ടു.","p":1},{"v":20,"t":"അവളുടെ കല്ലറമേൽ യാക്കോബ് ഒരു സ്തംഭം നാട്ടി. ഇന്നുവരെയും അതാണ് റാഹേലിന്റെ കബറിടസ്തംഭം.","p":1},{"v":21,"t":"ഇസ്രായേൽ നീങ്ങി ഏദെർഗോപുരത്തിനപ്പുറത്ത് കൂടാരമടിച്ചു.","p":1},{"v":22,"t":"ഇസ്രായേൽ ആ നാട്ടിൽ പാർത്തിരുന്നപ്പോൾ റൂബൻ പോയി തന്റെ പിതാവിന്റെ ഉപനാരിയായ ബിൽഹായുമൊത്തു ശയിച്ചു; ഇസ്രായേൽ അതു കേൾക്കാനിടയാവുകയും ചെയ്തു.","p":1},{"h":"യാക്കോബിന്റെ പുത്രന്മാർ"},{"v":22,"t":"യാക്കോബിനു പന്ത്രണ്ടു പുത്രന്മാരുണ്ടായിരുന്നു.","p":1},{"v":23,"t":"ലെയായുടെ പുത്രന്മാർ: യാക്കോബിന്റെ കടിഞ്ഞൂൽ പുത്രൻ റൂബൻ, ശിമയോൻ, ലേവി, യൂദാ, ഇസ്സാക്കർ, സെബുലൂൺ.","p":1},{"v":24,"t":"റാഹേലിന്റെ പുത്രന്മാർ: ജോസഫ്, ബെഞ്ചമിൻ.","p":1},{"v":25,"t":"റാഹേലിന്റെ പരിചാരി കയായ ബിൽഹായുടെ പുത്രന്മാർ: ദാൻ, നഫ്താലി.","p":1},{"v":26,"t":"ലെയായുടെ പരിചാരികയായ സിൽഫായുടെ പുത്രന്മാർ: ഗാദ്, ആഷേർ. യാക്കോബിന് പാദാൻ ആരാമിൽവച്ചു ജനിച്ച പുത്രന്മാരാണ് ഇവർ.","p":1},{"h":"ഇസഹാക്കിന്റെ മരണം"},{"v":27,"t":"അബ്രാഹവും ഇസഹാക്കും തത്കാലവാസം നടത്തിയിരുന്ന കിരിയാത്-അർബായിലെ മാമ്രേയിൽ, അതായത് ഹെബ്രോണിൽ, തന്റെ പിതാവായ ഇസഹാക്കിന്റെ അടുത്തേക്ക് യാക്കോബു വന്നു.","p":1},{"v":28,"t":"ഇസഹാക്കിന്റെ ആയുഷ്‌കാലം നൂറ്റെൺപതു വർഷമായിരുന്നു.","p":1},{"v":29,"t":"ഇസഹാക്ക് വൃദ്ധനും ആയുഷ്‌കാലം തികഞ്ഞവനുമായി അന്ത്യശ്വാസംവലിച്ചു. അവൻ മരിച്ച് സ്വന്തം ജനങ്ങളോട് ചേർന്നു. അവന്റെ മക്കളായ ഏസാവും യാക്കോബും അവനെ സംസ്‌കരിച്ചു.","p":1}],"36":[{"h":"ഏസാവ് ഏദോമ്യരുടെ പിതാവ്"},{"v":1,"t":"ഏസാവിന്റെ അതായത്, ഏദോമിന്റെ വംശാവലി ഇതാണ്:","p":1},{"v":2,"t":"കാനാന്യസ്ത്രീകളിൽനിന്നാണ് ഏസാവ് തനിക്കു ഭാര്യമാരെ സ്വീകരിച്ചത് - ഹിത്യനായ ഏലോനിന്റെ മകൾ ആദാ, ഹിവ്യനായ സിബിയോന്റെ മകളായ ആനായുടെ പുത്രി ഒഹോലിബാമാ,","p":1},{"v":3,"t":"ഇസ്മായേലിന്റെ മകളും നെബായോത്തിന്റെ സഹോദരിയുമായ ബസ്മത്ത് എന്നിവരായിരുന്നു അവർ.","p":1},{"v":4,"t":"ആദാ ഏസാവിനായി എലിഫാസിനെ പ്രസവിച്ചു; ബസ്മത്ത് റവുവേലിനെയും പ്രസവിച്ചു.","p":1},{"v":5,"t":"ഒഹോലിബാമാ യവൂഷിനെയും യാലാമിനെയും കോറഹിനെയും പ്രസവിച്ചു. ഇവരാണ് കാനാൻദേശത്ത് ഏസാവിനു പിറന്ന മക്കൾ.","p":1},{"v":6,"t":"ഏസാവ് തന്റെ ഭാര്യമാരെയും പുത്രീപുത്രന്മാരെയും വീട്ടിലുള്ള എല്ലാ ആളുകളെയും തന്റെ കാലിക്കൂട്ടവും സകല മൃഗസമ്പത്തും കാനാൻദേശത്തു താൻ നേടിയ സകല സമ്പാദ്യവും എടുത്ത് സ്വസഹോദരനായ യാക്കോബിൽനിന്നകലെ ഒരു നാട്ടിലേക്കു പോയി.","p":1},{"v":7,"t":"കാരണം, ഒന്നിച്ച് പാർക്കാൻ വയ്യാത്തവിധം അത്ര അധികമായിരുന്നു അവരുടെ സമ്പാദ്യം. അവരുടെ കാലിക്കൂട്ടങ്ങൾമൂലം അവരെ സംവഹിക്കാൻ അവരുടെ തത്കാലവാസഭൂമി അപര്യാപ്തമായിരുന്നു.","p":1},{"v":8,"t":"അതുകൊണ്ട്, ഏസാവ് സെയ്‌ർമലയിൽ താമസമാക്കി. ഏസാവുതന്നെയാണ് ഏദോം.","p":1},{"v":9,"t":"സെയിർമലയിലെ ഏദോമ്യരുടെ പിതാവായ ഏസാവിന്റെ വംശാവലി ഇതാണ്.","p":1},{"v":10,"t":"ഏസാവിന്റെ പുത്രന്മാരുടെ പേരുകൾ ഇവയാണ്: ഏസാവിന്റെ ഭാര്യ ആദായുടെ മകൻ എലിഫാസ്, ഏസാവിന്റെ ഭാര്യ ബസ്മത്തിന്റെ മകൻ റവുവേൽ.","p":1},{"v":11,"t":"എലിഫാസിന്റെ പുത്രന്മാരായിരുന്നു തേമാൻ, ഓമർ, സെഫോ, ഗത്താം, കെനസ് എന്നിവർ.","p":1},{"v":12,"t":"ഏസാവിന്റെ മകൻ എലിഫാസിന് തിമ്നാ എന്നൊരു ഉപനാരിയുണ്ടായിരുന്നു. അവൾ എലിഫാസിനായി അമലേക്കിനെ പ്രസവിച്ചു. ഇവരാണ് ഏസാവിന്റെ ഭാര്യയായ ആദായുടെ പുത്രന്മാർ.","p":1},{"v":13,"t":"റവുവേലിന്റെ പുത്രന്മാരാണ് നഹത്ത്, സേറഹ്, ഷമ്മാ, മിസ്സാ എന്നിവർ; ഏസാവിന്റെ ഭാര്യ ബസ്മത്തിന്റെ മക്കളാണ് ഇവർ.","p":1},{"v":14,"t":"സിബിയോന്റെ പുത്രിയായ ആനായുടെ മകളും ഏസാവിന്റെ ഭാര്യയുമായ ഒഹോലിബാമായുടെ പുത്രന്മാർ ഇവരാണ് - അവൾ ഏസാവിനായി യവൂഷിനെയും യാലാമിനെയും കോറഹിനെയും പ്രസവിച്ചു.","p":1},{"v":15,"t":"ഏസാവിന്റെ മക്കളുടെ പ്രഭുക്കന്മാർ ഇവരാണ്: ഏസാവിന്റെ ആദ്യജാതനായ എലിഫാസിന്റെ മക്കൾ തേമാൻപ്രഭു, ഓമർപ്രഭു, സെഫോപ്രഭു, കെനസ്പ്രഭു,","p":1},{"v":16,"t":"കോറഹ്പ്രഭു, ഗത്താംപ്രഭു, അമലേക്പ്രഭു. ഇവരാണ് ഏദോംനാട്ടിൽ എലിഫാസിന്റെ പ്രഭുക്കന്മാർ. ആദായുടെ പുത്രന്മാരാണിവർ.","p":1},{"v":17,"t":"ഏസാവിന്റെ മകനായ റവുവേലിന്റെ പുത്രന്മാർ: നഹത്ത്പ്രഭു, സേറഹ്പ്രഭു, ഷമ്മാപ്രഭു, മിസ്സാപ്രഭു. ഇവയാണ് ഏദോംനാട്ടിൽ റവുവേലിന്റെ പ്രഭുക്കന്മാർ. ഇവർ ഏസാവിന്റെ ഭാര്യ ബസ്മത്തിന്റെ മക്കളാണ്.","p":1},{"v":18,"t":"ഏസാവിന്റെ ഭാര്യ ഒഹോലിബാമായുടെ പുത്രന്മാർ ഇവരാണ്: യവൂഷ്പ്രഭു, യാലാംപ്രഭു, കോറഹ്പ്രഭു. ഇവരാണ് ഏസാവിന്റെ ഭാര്യയും ആനായുടെ മകളുമായ ഒഹോലിബാമായുടെ പ്രഭുക്കന്മാർ.","p":1},{"v":19,"t":"ഇവരാണ് ഏസാവിന്റെ അതായത്, ഏദോമിന്റെ പുത്രന്മാർ. അവരുടെ പ്രഭുക്കന്മാർ ഇവർതന്നെ.","p":1},{"v":20,"t":"ഇവർ അന്നാട്ടിൽ പാർത്തിരുന്നവരും സെയ്‌ർ എന്ന ഹോര്യന്റെ പുത്രന്മാരുമാണ്: ലോത്താൻ, ഷൊബാൽ, സിബയോൻ, ആനാ,","p":1},{"v":21,"t":"ദീഷോൻ, ഏസെർ, ദീഷാൻ. ഏദോംനാട്ടിലെ സെയ്‌റിന്റെ പുത്രന്മാരും ഹോര്യകുലങ്ങളുമാണ് ഇവർ.","p":1},{"v":22,"t":"ലോത്താന്റെ പുത്രന്മാരായിരുന്നു ഹോറിയും ഹേമാമും. ലോത്താന്റെ സഹോദരിയായിരുന്നു തിമ്നാ.","p":1},{"v":23,"t":"ഷൊബാലിന്റെ പുത്രന്മാർ അൽവാൻ, മനഹത്ത്, ഏബാൽ, ഷെഫോ, ഓനാം എന്നിവർ.","p":1},{"v":24,"t":"സിബയോന്റെ പുത്രന്മാർ ഇവ","p":1},{"v":24,"t":"രാണ്: ആയ്യാ, ആനാ. തന്റെ പിതാവായ സിബയോന്റെ കഴുതകളെ മേയ്ക്കുമ്പോൾ മരുഭൂമിയിൽ ചൂടു ഉറവകൾ കണ്ടെത്തിയ ആനാ ഇവൻതന്നെ.","p":1},{"v":25,"t":"ആനായുടെ മക്കൾ ഇവരാണ്: ദീഷോനും ആനായുടെ പുത്രി ഒഹോലിബാമായും.","p":1},{"v":26,"t":"ദീഷാന്റെ പുത്രന്മാർ ഹെമ്ദാൻ, എഷ്‌ബാൻ, ഇത്രാൻ, കെരാൻ എന്നിവരായിരുന്നു.","p":1},{"v":27,"t":"ഏസെറിന്റെ പുത്രന്മാർ ഇവരാണ്: ബിൽഹാൻ, സാവാൻ, അക്കാൻ.","p":1},{"v":28,"t":"ദീഷാന്റെ പുത്രന്മാർ ഊസ്, അരാൻ എന്നിവരാണ്.","p":1},{"v":29,"t":"ഹോര്യകുലങ്ങൾ ഇവയാണ്: ലോത്താൻകുലം, ഷൊബാൻകുലം, സിബയോൻകുലം, ആനാകുലം,","p":1},{"v":30,"t":"ദീഷോൻകുലം, ഏസെർകുലം, ദീഷാൻകുലം. സെയ്‌ർനാട്ടിൽ ഹോര്യകുലങ്ങൾ, അവരുടെ നേതാക്കൾക്കനുസരിച്ച്, ഇവയാണ്.","p":1},{"v":31,"t":"ഇസ്രായേല്യർക്ക് രാജഭരണം ഉണ്ടാകുന്നതിനുമുമ്പ് ഏദോംനാടു ഭരിച്ച രാജാക്കന്മാർ ഇവരായിരുന്നു:","p":1},{"v":32,"t":"ബെയോറിന്റെ മകനായ ബേല ഏദോമിൽ ഭരിച്ചു. അവന്റെ പട്ടണത്തിന്റെ പേര് ദിൻഹാബാ എന്നായിരുന്നു.","p":1},{"v":33,"t":"ബേല മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് ബോസ്രായിൽനിന്നുള്ള സേറഹിന്റെ മകൻ യോബാബ് ഏദോമിൽ ഭരിച്ചു.","p":1},{"v":34,"t":"യോബാബ് മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് തേമാന്യദേശത്തുനിന്നുള്ള ഹൂഷാം രാജാവായി.","p":1},{"v":35,"t":"ഹൂഷാം മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് ബദാദിന്റെ പുത്രനായ ഹദാദ് രാജാവായി. അവൻ മൊവാബുദേശത്തുവച്ച് മിദിയാനെ തോൽപ്പിച്ചു. അവന്റെ പട്ടണത്തിന്റെ പേര് അവിത് എന്നായിരുന്നു.","p":1},{"v":36,"t":"ഹദാദ് മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് മസ്റേക്കയിലെ സംലാ രാജാവായി.","p":1},{"v":37,"t":"സംലാ മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് റഹോബോത്ത് ഹന്നാറിലെ സാവുൾ രാജാവായി.","p":1},{"v":38,"t":"സാവുൾ മരിച്ചപ്പോൾ അവന്റെ സ്ഥാനത്ത് അക്ബോറിന്റെ മകനായ ബാൽ ഹാനാൻ രാജാവായി.","p":1},{"v":39,"t":"അക്ബോറിന്റെ മകനായ ബാൽ ഹാനാൻ മരിച്ചപ്പോൾ ഹദാർ അവന്റെ സ്ഥാനത്തു രാജാവായി. അവന്റെ പട്ടണത്തിന്റെ പേര് പാവു എന്നായിരുന്നു. അവന്റെ ഭാര്യയുടെ പേര് മെഹേത്തബേൽ എന്നായിരുന്നു; അവൾ മത്രേദിന്റെ പുത്രിയും മെസാഹാബിന്റെ പൗത്രിയുമായിരുന്നു.","p":1},{"v":40,"t":"തങ്ങളുടെ വംശങ്ങളും സ്ഥലങ്ങളും പേരുകളുമനുസരിച്ച് ഏസാവിന്റെ കുലനാമങ്ങൾ ഇവയാണ്: തിമ്നാകുലം, അൽവാകുലം, യത്തെത്ത്കുലം,","p":1},{"v":41,"t":"ഒഹോലിബാമാകുലം, ഏലാകുലം, പിനോൻകുലം,","p":1},{"v":42,"t":"കെനസ്കുലം, തേമാൻകുലം, മിബ്‌സാർകുലം,","p":1},{"v":43,"t":"മഗ്ദീയേൽകുലം, ഈറാംകുലം. തങ്ങളുടെ അവകാശമായ നാട്ടിലെ താമസസ്ഥലമനുസരിച്ച് ഏദോമിന്റെ കുലങ്ങൾ ഇവയായിരുന്നു. ഏദോമ്യരുടെ പൂർവികനാണ് ഏസാവ്.","p":1}],"37":[{"v":1,"t":"യാക്കോബ് തന്റെ പിതാവിന്റെ വിപ്രവാസ നാടായിരുന്ന കാനാൻദേശത്തു വാസമുറപ്പിച്ചു.","p":1},{"v":2,"t":"ഇതാണു യാക്കോബിന്റെ വംശചരിത്രം. ജോസഫ് പതിനേഴു വയസ്സുള്ളപ്പോൾ തന്റെ സഹോദരന്മാരോടൊപ്പം ആടുമേയ്ക്കുകയായിരുന്നു. അവൻ തന്റെ പിതാവിന്റെ ഭാര്യമാരായ ബിൽഹായുടെയും സിൽഫായുടെയും മക്കളുടെ കൂടെ സഹായിയായിരുന്നു. അവരെപ്പറ്റിയുള്ള ദുർവാർത്ത ജോസഫ് പിതാവിന്റെ പക്കലെത്തിച്ചു.","p":1},{"v":3,"t":"ജോസഫിനെ ഇസ്രായേൽ തന്റെ മറ്റെല്ലാ മക്കളെക്കാൾ അധികം സ്നേഹിച്ചിരുന്നു. കാരണം, തന്റെ വാർദ്ധക്യത്തിലെ മകനായിരുന്നു അവൻ. കൈയുള്ള ഒരു നീളനങ്കി അദ്ദേഹം അവനുവേണ്ടി ഉണ്ടാക്കി.","p":1},{"v":4,"t":"തങ്ങളുടെ പിതാവ് അവനെ അവന്റെ സഹോദരന്മാർ എല്ലാവരെക്കാൾ സ്നേഹിക്കുന്നു എന്ന് അവന്റെ സഹോദരന്മാർ കണ്ടു. അതുകൊണ്ട്, അവർ അവനെ വെറുത്തു. അവനോടു സൗമ്യമായി സംസാരിക്കാൻ അവർക്കു കഴിഞ്ഞില്ല.","p":1},{"v":5,"t":"ജോസഫിന് ഒരു സ്വപ്നമുണ്ടായി. അവൻ അത് തന്റെ സഹോദരന്മാരോടു വിവരിച്ചപ്പോൾ അവർ അവനെ വീണ്ടും കൂടുതൽ വെറുത്തു.","p":1},{"v":6,"t":"അവൻ അവരോടു പറഞ്ഞു: എനിക്കുണ്ടായ ഈ സ്വപ്നം കേട്ടാലും:","p":1},{"v":7,"t":"ഇതാ, നമ്മൾ പാടത്ത് കറ്റകൾ കെട്ടുകയായിരുന്നു. അപ്പോൾ ഇതാ, എന്റെ കറ്റ എഴുന്നേറ്റു; മാത്രമല്ല, അതു നിവർന്നുനിന്നു. ഇതാ, നിങ്ങളുടെ കറ്റകൾ ചുറ്റുംവന്ന് എന്റെ കറ്റയെ താണുവണങ്ങി.","p":1},{"v":8,"t":"അവന്റെ സഹോദരന്മാർ അവനോടു ചോദിച്ചു: നീ ഞങ്ങളുടെമേൽ രാജാവായിരിക്കുമെന്നുതന്നെയോണോ? അതോ, നീ ഞങ്ങളിൽ ആധിപത്യം സ്ഥാപിക്കുമെന്നുതന്നെയാണോ? അവന്റെ സ്വപ്നങ്ങളും വാക്കുകളും കാരണം അവർ അവനെ വീണ്ടും കൂടുതലായി വെറുത്തു.","p":1},{"v":9,"t":"അവനു വീണ്ടും മറ്റൊരു സ്വപ്നമുണ്ടായി. അവൻ അത് തന്റെ സഹോദരന്മാരോടു വർണ്ണിച്ചു. അവൻ പറഞ്ഞു: നോക്കൂ, ഞാൻ വേറൊരു സ്വപ്നം കണ്ടു. ഇതാ, സൂര്യനും ചന്ദ്രനും പതിനൊന്നു നക്ഷത്രങ്ങളും എന്നെ താണുവണങ്ങുന്നു.","p":1},{"v":10,"t":"അവൻ ഇത് തന്റെ പിതാവിനോടും തന്റെ സഹോദരന്മാരോടും വർണ്ണിച്ചപ്പോൾ അവന്റെ പിതാവ് അവനെ ശകാരിച്ചുകൊണ്ട് അവനോടു ചോദിച്ചു: ഇതെന്തു സ്വപ്നമാണ് നീ കണ്ടത്? ഞങ്ങൾ, ഞാനും നിന്റെ അമ്മയും നിന്റെ സഹോദരന്മാരും, നിന്നെ നിലപറ്റി താണുവണങ്ങാൻ വരുകതന്നെ വേണമെന്നോ?","p":1},{"v":11,"t":"അവന്റെ സഹോദരന്മാർക്ക് അവനോട് അസൂയയായി. അവന്റെ പിതാവാകട്ടെ, ഇക്കാര്യം ശ്രദ്ധയിൽവച്ചു.","p":1},{"v":12,"t":"അവന്റെ സഹോദരന്മാർ തങ്ങളുടെ പിതാവിന്റെ ആടുകളെ മേയ്ക്കാൻ ഷെക്കെമിൽ പോയി.","p":1},{"v":13,"t":"ഇസ്രായേൽ ജോസഫിനോടു പറഞ്ഞു: നിന്റെ സഹോദരന്മാർ ഷെക്കെമിൽ മേയ്ക്കുകയല്ലേ? വരൂ, അവരുടെ അടുത്തേക്ക് നിന്നെ ഞാനയയ്ക്കാം. അവൻ അദ്ദേഹത്തോടു പറഞ്ഞു: ഇതാ ഞാൻ!","p":1},{"v":14,"t":"അപ്പോൾ അദ്ദേഹം അവനോടു പറഞ്ഞു: നീ പോയാലും! നിന്റെ സഹോദരന്മാരുടെ ക്ഷേമവും ആട്ടിൻപറ്റത്തിന്റെ ക്ഷേമവും അന്വേഷിക്കുക. എന്നിട്ട് എന്റെ പക്കൽ വിവരമെത്തിക്കണം. അദ്ദേഹം അവനെ ഹെബ്രോൻ താഴ്‌വരയിൽനിന്നു യാത്രയാക്കി. അവൻ ഷെക്കെമിലേക്കു പോയി.","p":1},{"v":15,"t":"അവൻ അതാ, വയലിൽ അലയുകയായിരുന്നു. അപ്പോൾ ഒരാൾ അവനെ കണ്ടു. അയാൾ അവനോടു തിരക്കി: നീ എന്താണ് അന്വേഷിക്കുന്നത്?","p":1},{"v":16,"t":"അവൻ പറഞ്ഞു: ഞാൻ എന്റെ സഹോദരന്മാരെ അന്വേഷിക്കുകയാണ്. അവർ എവിടെയാണ് മേയ്ക്കുന്നത് എന്ന് എന്നോടു ദയയോടെ പറയുക.","p":1},{"v":17,"t":"അയാൾ പറഞ്ഞു: അവർ ഇവിടെനിന്നു നീങ്ങി. കാരണം, നമുക്ക് ദോത്താനിലേക്കു പോകാം എന്ന് അവർ പറയുന്നതു ഞാൻ കേട്ടു. തന്റെ സഹോദരന്മാരുടെ പുറകേ ജോസഫും പോയി. ദോത്താനിൽ അവൻ അവരെ കണ്ടുമുട്ടി.","p":1},{"v":18,"t":"ദൂരെവച്ചുതന്നെ അവർ അവനെ കണ്ടു. അവൻ അവരുടെ അടുത്തെത്തുംമുമ്പേ, അവനെ വധിക്കാൻ അവർ ഗൂഢാലോചന നടത്തി.","p":1},{"v":19,"t":"അവർ പരസ്പരം പറഞ്ഞു: അതാ വരുന്നു, സ്വപ്നങ്ങളുടെ വിദ്വാൻ","p":1},{"v":20,"t":"വരുവിൻ, ഇപ്പോൾത്തന്നെ നമുക്ക് അവനെ കൊല്ലാം, എന്നിട്ട് അവനെ കുഴികളിലൊന്നിൽ എറിയാം; ഒരു ദുഷ്ടമൃഗം അവനെ തിന്നുവെന്ന് പറയുകയും ചെയ്യാം. അവന്റെ സ്വപ്നങ്ങൾക്കു എന്തു സംഭവിക്കുമെന്നു നമുക്കു കാണാമല്ലോ.","p":1},{"v":21,"t":"റൂബൻ ഇതു കേട്ടു. അയാൾ അവനെ അവരുടെ കൈയിൽനിന്നു രക്ഷിച്ചു. അയാൾ പറഞ്ഞു: നമുക്കു ജീവൻ നശിപ്പിക്കേണ്ട.","p":1},{"v":22,"t":"അവനെ അവരുടെ കൈയിൽനിന്നു രക്ഷിച്ച് അവന്റെ പിതാവിന് തിരിച്ചേൽപ്പിക്കേണ്ടതിന്, റൂബൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ രക്തംചിന്തരുത്. അവനെ നിങ്ങൾ മരുഭൂമിയിലെ ഈ കുഴിയിൽ തള്ളിയിടുക. എന്നാൽ, അവന്റെമേൽ നിങ്ങൾ കൈവയ്ക്കരുത്.","p":1},{"v":23,"t":"അതിനാൽ, ജോസഫ് തന്റെ സഹോദരന്മാരുടെ അടുത്തെത്തിയപ്പോൾ, അവർ ജോസഫിൽനിന്ന് അവന്റെ അങ്കി - അവന്റെ മേലുണ്ടായിരുന്ന കൈനീളൻ അങ്കിതന്നെ - ഊരിയെടുത്തു.","p":1},{"v":24,"t":"എന്നിട്ട് അവർ അവനെ എടുത്ത് ആ കുഴിയിലേക്കെറിഞ്ഞു. അതു വെള്ളമില്ലാത്ത പൊട്ടക്കിണറായിരുന്നു.","p":1},{"v":25,"t":"അവർ ഭക്ഷണം കഴിക്കാനിരുന്നപ്പോൾ തങ്ങളുടെ കണ്ണുകളുയർത്തി നോക്കി. അപ്പോൾ അതാ, ഗിലയാദിൽനിന്ന് ഇസ്മായേല്യരുടെ ഒരു കച്ചവട സംഘം വരുന്നു. തങ്ങളുടെ ഒട്ടകങ്ങൾ സംവഹിച്ചിരുന്ന സുഗന്ധപശയും പരിമള ദ്രവ്യങ്ങളും കുന്തിരുക്കവും ഈജിപ്തിലേക്ക് കൊണ്ടുപോകാനായി അവർ നടന്നു നീങ്ങുകയായിരുന്നു","p":1},{"v":26,"t":"അപ്പോൾ യൂദാ തന്റെ സഹോദരന്മാരോടു പറഞ്ഞു: നമ്മുടെ സഹോദരനെ കൊന്ന് അവന്റെ രക്തം നാം മറച്ചുവെച്ചതുകൊണ്ട് എന്തു ലാഭം?","p":1},{"v":27,"t":"വരുവിൻ, നമുക്കവനെ ഇസ്‌മായേല്യർക്കു വിൽക്കാം. നമ്മുടെ കൈ അവനെതിരേ വേണ്ടാ. കാരണം, അവൻ നമ്മുടെ സഹോദരനാണ്, നമ്മുടെതന്നെ മാംസം. അവന്റെ സഹോദരന്മാർ അത് അനുസരിച്ചു.","p":1},{"v":28,"t":"അവർ ജോസഫിനെ കുഴിയിൽനിന്നു വലിച്ചുകയറ്റിയപ്പോഴേക്കും മിദിയാൻകാരായ ആ കച്ചവടക്കാർ കടന്നുവന്നു. ആ ഇസ്‌മായേല്യർക്ക് ഇരുപതു വെള്ളിക്കാശിന് ജോസഫിനെ വിറ്റു. അവർ ജോസഫിനെ ഈജിപ്തിലേക്കു കൊണ്ടുപോയി.","p":1},{"v":29,"t":"കുഴിയുടെ അടുത്തേക്ക് റൂബൻ തിരിച്ചുചെന്നപ്പോൾ അതാ, ജോസഫ് കുഴിയിൽ ഉണ്ടായിരുന്നില്ല. അയാൾ തന്റെ വസ്ത്രം വലിച്ചുകീറി;","p":1},{"v":30,"t":"സഹോദരന്മാരുടെ അടുത്തു മടങ്ങിയെത്തി. അയാൾ പറഞ്ഞു: കുട്ടി അവിടെ ഇല്ലല്ലോ. ഞാൻ, ഞാനിനി എങ്ങോട്ടു പോകും!","p":1},{"v":31,"t":"അവർ ജോസഫിന്റെ അങ്കിയെടുത്തു; ഒരു മുട്ടാടിനെ അറുത്ത്, അങ്കി രക്തത്തിൽ മുക്കി.","p":1},{"v":32,"t":"അവർ കൈനീളൻ അങ്കി കൊടുത്തയച്ചു; അത് അവരുടെ പിതാവിന്റെയടുക്കൽ എത്തിച്ചവർ പറഞ്ഞു: ഇതു ഞങ്ങൾ കണ്ടെത്തി. ഈ കുപ്പായം അങ്ങയുടെ മകന്റേതാണോ അല്ലയോ എന്നു പരിശോധിച്ചാലും.","p":1},{"v":33,"t":"അദ്ദേഹം അതു തിരിച്ചറിഞ്ഞു. അദ്ദേഹം പറഞ്ഞു: എന്റെ മകന്റെ കുപ്പായം! ഏതോ ദുഷ്ടമൃഗം ജോസഫിനെ തീർച്ചയായും കടിച്ചുകീറി തിന്നതുതന്നെ!","p":1},{"v":34,"t":"യാക്കോബ് തന്റെ വസ്ത്രം വലിച്ചുകീറി; അരയിൽ ചാക്കുടുത്തു; വളരെനാൾ തന്റെ മകനെക്കുറിച്ചു വിലപിച്ചു.","p":1},{"v":35,"t":"അദ്ദേഹത്തിന്റെ പുത്രീപുത്രന്മാരെല്ലാവരും അദ്ദേഹത്തെ ആശ്വസിപ്പിക്കാൻ ശ്രമിച്ചു. എന്നാൽ, ആശ്വസിപ്പിക്കപ്പെടാൻ വിസമ്മതിച്ചുകൊണ്ട് അദ്ദേഹം ഇങ്ങനെ പറഞ്ഞു: വിലപിച്ചുകൊണ്ടുതന്നെ എന്റെ മകന്റെയടുത്തേക്ക്, പാതാളത്തിലേക്ക് ഞാൻ ഇറങ്ങും. അദ്ദേഹം തന്റെ മകനെയോർത്തു കരഞ്ഞു.","p":1},{"v":36,"t":"മിദിയാൻകാരാകട്ടെ, അവനെ ഈജിപ്തിൽ ഫറവോയുടെ ഒരു ഉദ്യോഗസ്ഥനും കാവൽപ്പടയുടെ നായകനുമായ പൊത്തിഫറിനു വിറ്റു.","p":1}],"38":[{"v":1,"t":"അക്കാലത്ത് യൂദാ തന്റെ സഹോദരന്മാരിൽ നിന്ന് അകന്ന് ഹീറോ എന്ന് പേരുള്ള ഒരു അദുല്ലാംകാരൻ്റെ അടുത്തേക്ക് ഇറങ്ങിത്തിരിച്ചു","p":1},{"v":2,"t":"യൂദാ അവിടെ ഷുവാ എന്നു പേരുള്ള ഒരു കാനാൻകാരന്റെ മകളെ കണ്ടു. അവളെ അവൻ സ്വന്തമാക്കി, അവളെ പ്രാപിച്ചു.","p":1},{"v":3,"t":"അവൾ ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അയാൾ അവൻ ഏർ എന്നു പേരിട്ടു.","p":1},{"v":4,"t":"അവൾ വീണ്ടും ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അവൾ അവന് ഓനാൻ എന്നു പേരിട്ടു.","p":1},{"v":5,"t":"അതെത്തുടർന്ന് അവൾ വീണ്ടും ഒരു മകനെ പ്രസവിച്ചു. അവൾ അവന് ഷേലാ എന്നു പേരിട്ടു. അവൾ അവനെ പ്രസവിക്കുമ്പോൾ അയാൾ കെസീബിൽ ആയിരുന്നു.","p":1},{"v":6,"t":"യൂദാ തന്റെ കടിഞ്ഞൂൽപുത്രനായ ഏറിനുവേണ്ടി ഒരു ഭാര്യയെ കൊണ്ടുവന്നു. താമാർ എന്നായിരുന്നു അവളുടെ പേര്.","p":1},{"v":7,"t":"എന്നാൽ, യൂദായുടെ കടിഞ്ഞൂൽപുത്രനായ ഏർ കർത്താവിന്റെ മുൻപിൽ ദുഷിച്ചവനാനായിരുന്നു. കർത്താവ് അവനെ മരണത്തിനിരയാക്കി.","p":1},{"v":8,"t":"അപ്പോൾ യൂദാ ഓനാനോട് പറഞ്ഞു: നിന്റെ സഹോദരന്റെ ഭാര്യയെ പ്രാപിച്ച് അവൾക്കു പ്രതിഭർത്താവായി നിന്റെ സഹോദരനുവേണ്ടി സന്താനത്തെ വളർത്തുക.","p":1},{"v":9,"t":"സന്തതി തന്റേതായിരിക്കില്ലെന്ന് അറിയാമായിരുന്ന ഓനാൻ തന്റെ സഹോദരനു സന്താനത്തെ നൽകാതിരിക്കാൻ, തന്റെ സഹോദരഭാര്യയെ പ്രാപിച്ചപ്പോൾ നിലത്തേക്ക് ബീജം സ്രവിപ്പിച്ചു.","p":1},{"v":10,"t":"അവൻ ചെയ്തത് കർത്താവിന്റെ ദൃഷ്ടികളിൽ തിന്മയായിരുന്നു; അവനെയും അവിടുന്ന് മരണത്തിനിരയാക്കി.","p":1},{"v":11,"t":"അപ്പോൾ യൂദാ തന്റെ മരുമകളായ താമാറിനോടു പറഞ്ഞു: എന്റെ മകൻ ഷേലാ വളരുന്നതുവരെ നിന്റെ പിതാവിന്റെ വീട്ടിൽ ഒരു വിധവയായി പാർക്കുക. എന്തെന്നാൽ, അവൻ ആത്മഗതംചെയ്തു: സഹോദരന്മാരെപ്പോലെ ഇവനും മരിക്കരുതല്ലോ! താമാർ പോയി തന്റെ പിതാവിന്റെ വീട്ടിൽ താമസിച്ചു.","p":1},{"v":12,"t":"നാളുകളേറെക്കഴിഞ്ഞപ്പോൾ യൂദായുടെ ഭാര്യ, ഷുവായുടെ മകൾ, മരിച്ചു. ദുഃഖാചരണകാലം കഴിഞ്ഞ് യൂദാ തന്റെ സുഹൃത്ത് അതുല്ലാംകാരൻ ഹീറായുടെകൂടെ തിമ്നായിലേക്ക്, തന്റെ ആടുകളുടെ രോമം കത്രിക്കുന്നവരുടെ അടുത്തേക്കുപോയി.","p":1},{"v":13,"t":"ആരോ താമാറിനെ ഇപ്രകാരം അറിയിച്ചു: അതാ, നിന്റെ അമ്മായിയപ്പൻ തന്റെ ആടുകളുടെ രോമംമുറിക്കാൻ തിമ്നായിലേക്കു പോകുന്നുണ്ട്.","p":1},{"v":14,"t":"ഷേലാ വളർന്നിട്ടും അവന് അവൾ ഭാര്യയായി നൽകപ്പെട്ടില്ല എന്നു കണ്ട് അവൾ തന്റെമേലുണ്ടായിരുന്ന വിധവാവസ്ത്രങ്ങൾ മാറ്റി, ഒരു മൂടുപടംകൊണ്ടു മൂടി. സ്വയംമറച്ച് അവൾ തിമ്നായിലേക്കുള്ള വഴിയിൽ എനായീംകവാടത്തിങ്കൽ ഇരുന്നു.","p":1},{"v":15,"t":"യൂദാ അവളെ കണ്ടു. അവൾ മുഖം മൂടി യിരുന്നതുകൊണ്ട് അവളെ ഒരു വേശ്യയായി അവൻ കരുതി.","p":1},{"v":16,"t":"വഴിയിലേക്ക്, അവളുടെനേർക്കു കുനിഞ്ഞ് അവൻ പറഞ്ഞു: വന്നാലും, ഞാൻ നിന്നെ പ്രാപിക്കട്ടെ. തന്റെ മരുമകളാണ് അവളെന്ന് അവൻ അറിഞ്ഞില്ല. അവൾ ചോദിച്ചു: താങ്കൾ എന്നെ പ്രാപിക്കുന്നതിന് എനിക്ക് എന്തുതരും?","p":1},{"v":17,"t":"അവൻ പറഞ്ഞു: ആട്ടിൻകൂട്ടത്തിൽനിന്ന് ഒരു ആട്ടിൻകുട്ടിയെ ഞാൻ കൊടുത്തയയ്ക്കാം. അവൾ ചോദിച്ചു: താങ്കൾ കൊടുത്തയയ്ക്കുന്നതുവരെ ഒരു ഈടുതരുമോ?","p":1},{"v":18,"t":"അവൻ ചോദിച്ചു: ഞാൻ നിനക്കു തരേണ്ട ഈട് എന്താണ്? അവൾ പറഞ്ഞു: താങ്കളുടെ മുദ്രമോതിരവും വളയും കയ്യിലെ വടിയും. അവൾക്ക് അവൻ അവ കൊടുക്കുകയും അവളെ പ്രാപിക്കുകയുംചെയ്തു. അങ്ങനെ അവൾ അവനിൽനിന്നു ഗർഭംധരിച്ചു.","p":1},{"v":19,"t":"അവൾ എഴുന്നേറ്റുപോയി, തന്റെമേലുണ്ടായിരുന്ന മൂടുപടം മാറ്റി വിധവാവസ്ത്രങ്ങൾ ധരിച്ചു.","p":1},{"v":20,"t":"താൻ ഈടുകൊടുത്തവ ആ സ്ത്രീയുടെ കയ്യിൽനിന്നു തിരിച്ചുഎടുക്കാൻ, അതുല്ലാംകാരനായ തന്റെ സ്നേഹിതന്റെ കയ്യിൽ യൂദാ ഒരു ആട്ടിൻകുട്ടിയെ കൊടുത്തയച്ചു. എന്നാൽ, അവളെ അവൻ കണ്ടെത്തിയില്ല.","p":1},{"v":21,"t":"അവൻ അവളുടെ സ്ഥലത്തെ ആളുകളോട് ഇപ്രകാരം അന്വേഷിച്ചു: എനായിമിലെ വഴിവക്കിലുണ്ടായിരുന്ന വേശ്യ എവിടെ? അവർ പറഞ്ഞു: ഇവിടെ ഒരു വേശ്യയുണ്ടായിരുന്നില്ല.","p":1},{"v":22,"t":"അവൻ യൂദായുടെ പക്കൽ തിരിച്ചുചെന്നു പറഞ്ഞു: ഞാൻ അവളെ കണ്ടെത്തിയില്ല. അവിടെ ഒരു വേശ്യയുണ്ടായിരുന്നില്ല എന്നാണ് അവിടുത്തെ ആളുകൾ പറഞ്ഞത്.","p":1},{"v":23,"t":"യൂദാ പറഞ്ഞു: അവൾ അവ സ്വന്തമായി എടുത്തുകൊള്ളട്ടെ. നമ്മൾ പരിഹാസ്യരാകരുതല്ലോ. ഇതാ, ഞാൻ ഈ ആട്ടിൻകുട്ടിയെ കൊടുത്തയച്ചു. നീയാകട്ടെ, അവളെ കണ്ടെത്തിയുമില്ല.","p":1},{"v":24,"t":"ഏകദേശം മൂന്നുമാസം കഴിഞ്ഞപ്പോൾ, യൂദായ്ക്ക് ഇപ്രകാരം അറിയിപ്പുകിട്ടി: നിന്റെ മരുമകൾ താമാർ വേശ്യാവൃത്തിനടത്തി. മാത്രമല്ല, അവളിപ്പോൾ വേശ്യാവൃത്തിയിലൂടെ ഗർഭിണിയുമാണ്.","p":1},{"v":25,"t":"അപ്പോൾ യൂദാ പറഞ്ഞു: അവളെ പുറത്തിറക്കുക, അവൾ ദഹിപ്പിക്കപ്പെടട്ടെ! അവളെ പുറത്തുകൊണ്ടുവന്നപ്പോൾ അവൾ, ഇവ ആരുടേതാണോ അയാളിലൂടെയാണ് ഞാൻ ഗർഭിണിയായത് എന്ന് തന്റെ അമ്മായിയപ്പനോടു പറയാനായി ആളയച്ചു. അവൾ പറഞ്ഞു: ദയചെയ്ത്, ഈ മുദ്രമോതിരവും വളയും വടിയും ആരുടേതെന്നു തിരിച്ചറിഞ്ഞാലും.","p":1},{"v":26,"t":"അവ തിരിച്ചറിഞ്ഞിട്ട് യൂദാ പറഞ്ഞു: അവൾ എന്നെക്കാൾ നീതിമതിയാണ്. ഞാൻ അവളെ എന്റെ മകൻ ഷേലായ്ക്കു കൊടുത്തില്ലെന്നതുതന്നെ കാരണം. അവൻ. അവളെ പിന്നീട് ഒരിക്കലും അറിഞ്ഞില്ല.","p":1},{"v":27,"t":"അവളുടെ പ്രസവത്തിന്റെ സമയത്ത് അവളുടെ ഉദരത്തിൽ ഇതാ, ഇരട്ടകൾ!","p":1},{"v":28,"t":"അവൾ പ്രസവിക്കവേ, ഒരുത്തൻ ഒരു കൈ നീട്ടി. ഇവൻ ആദ്യം പുറത്തുവന്നു എന്നു പറഞ്ഞുകൊണ്ട് സൂതികർമിണി പിടിച്ച് അവന്റെ കൈയിൽ ചുവന്ന ഒരു ചരട് കെട്ടി.","p":1},{"v":29,"t":"അവൻ തന്റെ കൈ പിൻവലിച്ചപ്പോൾ അതാ, അവന്റെ സഹോദരൻ പുറത്തുവന്നു. നീ എങ്ങനെ നിനക്കൊരു വഴി ഭേദിച്ചുണ്ടാക്കി എന്നു ചോദിച്ചുകൊണ്ട് അവൾ അവന് പേരെസ് എന്നു പേരിട്ടു.","p":1},{"v":30,"t":"പിന്നീട് കൈയിൽ ചുവന്ന ചരടുള്ള അവന്റെ സഹോദരൻ പുറത്തുവന്നു. അവന് സേറഹ് എന്നു പേരിട്ടു.","p":1}],"39":[{"v":1,"t":"ജോസഫ് ഈജിപ്തിലേക്ക് നയിക്കപ്പെട്ടു. അവനെ അവിടേക്കു കൊണ്ടുവന്ന ഇസ്‌മായേല്യരുടെ കൈയിൽനിന്ന് ഫറവോയുടെ ഉദ്യോഗസ്ഥനും കാവൽപ്പടയുടെ നായകനുമായ പൊത്തിഫർ എന്ന ഈജിപ്തുകാരൻ അവനെ വാങ്ങി.","p":1},{"v":2,"t":"കർത്താവ് ജോസഫിന്റെകൂടെ ഉണ്ടായിരുന്നു. അവൻ ഐശ്വര്യവാനായിരുന്നു. ഈജിപ്തുകാരനായ തന്റെ യജമാനന്റെ വീട്ടിലായിരുന്നു അവൻ.","p":1},{"v":3,"t":"കർത്താവ് അവന്റെകൂടെ ഉണ്ടെന്നും അവൻ ചെയ്യുന്നതെല്ലാം കർത്താവ് അവന്റെ കരംവഴി മംഗളകരമാക്കുന്നു എന്നും അവന്റെ യജമാനൻ കണ്ടു.","p":1},{"v":4,"t":"ജോസഫ് അയാളുടെ ദൃഷ്ടികളിൽ പ്രീതികണ്ടെത്തി. അവൻ അയാളെ ശുശ്രൂഷിച്ചു. അയാൾ അവനെ തന്റെ ഭവനത്തിന്റെമേൽ നിയോഗിക്കുകയും തനിക്കുള്ളതെല്ലാം അവന്റെ കൈയിൽ ഏൽപ്പിക്കുകയും ചെയ്തു.","p":1},{"v":5,"t":"ജോസഫിനെ ആ ഈജിപ്തുകാരൻ തന്റെ വീട്ടിലും തനിക്കുള്ള എല്ലാറ്റിൻമേലും ചുമതലപ്പെടുത്തിയപ്പോൾമുതൽ അവനെപ്രതി കർത്താവ് അയാളുടെ ഭവനത്തെ അനുഗ്രഹിച്ചു. അയാളുടെ വീട്ടിലും വയലിലുമായി അയാൾക്കുണ്ടായിരുന്ന എല്ലാറ്റിലും കർത്താവിന്റെ അനുഗ്രഹമുണ്ടായി.","p":1},{"v":6,"t":"അയാൾ തനിക്കുണ്ടായിരുന്നതെല്ലാം ജോസഫിന്റെ കൈയിലാണ് വിട്ടുകൊടുത്തിരുന്നത്. താൻ കഴിക്കുന്ന ഭക്ഷണത്തെക്കുറിച്ചല്ലാതെ, തന്നോടൊപ്പമുണ്ടായിരുന്ന മറ്റൊന്നിനെക്കുറിച്ചും അയാൾ ശ്രദ്ധിച്ചിരുന്നില്ല. ജോസഫ് രൂപഭംഗിയുള്ളവനും കാഴ്ചയ്ക്കു സുന്ദരനുമായിരുന്നു.","p":1},{"v":7,"t":"കുറച്ചുനാൾ കഴിഞ്ഞപ്പോൾ അവന്റെ യജമാനന്റെ ഭാര്യ ജോസഫിൽ നോട്ടമിട്ടു. അവൾ പറഞ്ഞു: എന്റെകൂടെ ശയിക്കുക.","p":1},{"v":8,"t":"പക്ഷേ, അവൻ വഴങ്ങിയില്ല. അവൻ തന്റെ യജമാനന്റെ ഭാര്യയോടു പറഞ്ഞു: നോക്കൂ, ഞാൻ ഉള്ളതുകൊണ്ട് എന്റെ യജമാനൻ വീട്ടിലുള്ള ഒന്നിനെക്കുറിച്ചും ശ്രദ്ധിക്കാറില്ല. അദ്ദേഹത്തിനുള്ളതെല്ലാം എന്റെ കൈയിൽ അദ്ദേഹം ഏൽപ്പിച്ചിരിക്കുകയാണ്.","p":1},{"v":9,"t":"എന്നെക്കാൾ വലിയവനായി ആരും ഈ ഭവനത്തിലില്ല. നിങ്ങളെയല്ലാതെ, മറ്റൊന്നും അദ്ദേഹം എന്നിൽനിന്നു മാറ്റി നിർത്തിയിട്ടില്ല. അതു നിങ്ങൾ അദ്ദേഹത്തിന്റെ ഭാര്യയായതുകൊണ്ടാണ്. ഞാൻ എങ്ങനെയാണ് ഈ വലിയ തിന്മ പ്രവർത്തിച്ച് ദൈവത്തിനെതിരെ പാപം ചെയ്യുന്നത്?","p":1},{"v":10,"t":"അനുദിനം അവൾ ജോസഫിനോട് ഇവിധം പറഞ്ഞുകൊണ്ടിരുന്നെങ്കിലും അവളോടുകൂടെ ശയിക്കുന്നതിലോ അവളോടൊപ്പം ആയിരിക്കുന്നതിലോ അവൻ അവളെ അനുസരിച്ചില്ല.","p":1},{"v":11,"t":"അങ്ങനെയിരിക്കേ, ഒരു ദിവസം അവൻ തന്റെ ജോലിചെയ്യാനായി വീട്ടിലേക്കു വന്നു. വീട്ടുകാരആരും അവിടെ, വീട്ടിലില്ലായിരുന്നു.","p":1},{"v":12,"t":"അപ്പോൾ, എന്റെകൂടെ ശയിക്കുക എന്നു പറഞ്ഞുകൊണ്ട് അവനെ അവൾ അവന്റെ മേലങ്കിയിൽ കടന്നുപിടിച്ചു. എന്നാൽ, തന്റെ മേലങ്കി അവളുടെ കൈയിൽ വിട്ടിട്ട് അവൻ പുറത്തേക്ക് ഓടിപ്പോയി.","p":1},{"v":13,"t":"അവന്റെ കുപ്പായം തന്റെ കൈയിൽ വിട്ടിട്ട് അവൻ പുറത്തേക്ക് ഓടിപ്പോയെന്നു കണ്ടപ്പോൾ,","p":1},{"v":14,"t":"അവൾ തന്റെ ഭവനാംഗങ്ങളെ വിളിച്ച് അവരോടു പറഞ്ഞു: നോക്കൂ, നമ്മെ അപമാനിക്കാൻ ഒരു ഹെബ്രായനെ അദ്ദേഹം നമുക്കായി കൊണ്ടുവന്നിരിക്കുന്നു! എന്നോടൊത്തു ശയിക്കാൻ അവൻ എന്നെ സമീപിച്ചു. എന്നാൽ ഞാൻ വലിയ സ്വരത്തിൽ അലറി.","p":1},{"v":15,"t":"ഞാൻ സ്വരമുയർത്തുന്നതും അലറിവിളിക്കുന്നതും കേട്ടപ്പോൾ അവൻ തന്റെ മേലങ്കി എന്റെയരികിൽ ഉപേക്ഷിച്ചിട്ട് പുറത്തേക്കുകടന്നു രക്ഷപ്പെട്ടു.","p":1},{"v":16,"t":"അവന്റെ യജമാനൻ വീട്ടിലേക്കു വരുവോളം അവൾ ആ കുപ്പായം തന്റെപക്കൽ സൂക്ഷിച്ചു.","p":1},{"v":17,"t":"അവൾ അവനോട് അതേകാര്യങ്ങൾ ഇപ്രകാരം പറഞ്ഞു: അങ്ങ് നമുക്കായി കൊണ്ടുവന്ന ആ ഹെബ്രായാദാസൻ എന്നോടു ശൃംഗരിക്കാൻ വന്നു.","p":1},{"v":18,"t":"എന്നാൽ, ഞാൻ സ്വരമുയർത്തുകയും അലറിവിളിക്കുകയും ചെയ്തപ്പോൾ അവൻ തന്റെ മേലങ്കി എന്റെ അരികിൽ ഉപേക്ഷിച്ചിട്ട് പുറത്തേക്ക് ഓടിപ്പോയി.","p":1},{"v":19,"t":"ഇപ്രകാരമുള്ള കാര്യങ്ങളാണ് അങ്ങയുടെ ദാസൻ എന്നോടു ചെയ്തത് എന്നു ഭാര്യ തന്നോടു പറഞ്ഞ വാക്കുകൾ അവന്റെ യജമാനൻ കേട്ടപ്പോൾ അയാളുടെ കോപം ജ്വലിച്ചു.","p":1},{"v":20,"t":"ജോസഫിന്റെ യജമാനൻ അവനെ പിടിച്ച്, രാജാവിന്റെ തടവുകാരെ ബന്ധിച്ചിരുന്ന സ്ഥലത്ത് കാരാഗൃഹത്തിലാക്കി. അങ്ങനെ അവൻ അവിടെ കാരാഗൃഹത്തിലായി.","p":1},{"v":21,"t":"കർത്താവ് ജോസഫിന്റെ കൂടെയുണ്ടായിരുന്നു. അവിടുന്ന് അവനോടു കാരുണ്യം കാണിച്ചു; അവന് കാരാഗൃഹാധിപന്റെ ദൃഷ്ടികളിൽ അവിടുന്ന് പ്രീതി നൽകുകയും ചെയ്തു.","p":1},{"v":22,"t":"കാരാഗൃഹത്തിലുണ്ടായിരുന്ന തടവുകാരെയെല്ലാം കാരാഗൃഹാധിപൻ ജോസഫിന്റെ കയ്യിലേൽപ്പിച്ചു; അവിടെയുള്ള എല്ലാ തൊഴിലാടപാടുകളും അവനാണ് ചെയ്തിരുന്നത്.","p":1},{"v":23,"t":"അവൻ കൈകാര്യം ചെയ്ത ഒന്നിനും കാരാഗൃഹാധിപന്റെ മേൽനോട്ടം വേണ്ടി വന്നില്ല; കാരണം, അവന്റെ കൂടെ കർത്താവ് ഉണ്ടായിരുന്നു. അവൻ ചെയ്യുന്നത് കർത്താവു ശുഭമാക്കിയിരുന്നു.","p":1}],"40":[{"h":"തടവുകാരുടെ സ്വപ്നങ്ങൾ"},{"v":1,"t":"കുറച്ചുനാൾ കഴിഞ്ഞ്, ഈജിപ്തുരാജാവിന്റെ പാനപാത്രവാഹകനും പാചകക്കാരനും തങ്ങളുടെ യജമാനനായ ഈജിപ്തുരാജാവിനെതിരേ തെറ്റുചെയ്തു.","p":1},{"v":2,"t":"ഫറവോ തന്റെ രണ്ട് ഉദ്യോഗസ്ഥരോട്, പാനപാത്രവാഹക പ്രമാണിയോടും പാചക പ്രമാണിയോടും, കുപിതനായി.","p":1},{"v":3,"t":"അദ്ദേഹം അവരെ കാവൽപ്പടനായകന്റെ വീട്ടിലെ തടങ്കലിൽ, ജോസഫ് തടവിലാക്കപ്പെട്ടിരുന്നിടമായ കാരാഗൃഹത്തിൽ, അടച്ചു.","p":1},{"v":4,"t":"കാവൽപ്പടനായകൻ ജോസഫിനെ അവരോടുകൂടെ ആക്കി. അവൻ അവരെ പരിചരിച്ചു. ദിവസങ്ങളോളം അവർ തടങ്കലിലായിരുന്നു.","p":1},{"v":5,"t":"കാരാഗൃഹത്തിൽ തടവുകാരായിരുന്ന അവരിരുവരും, ഈജിപ്തുരാജാവിന്റെ പാനപാത്രവാഹകനും പാചക്കാരനും, ഒരു രാത്രിയിൽ അതതിന്റെ വ്യാഖ്യാനമുള്ള ഓരോ സ്വപ്നം കണ്ടു.","p":1},{"v":6,"t":"ജോസഫ് രാവിലെ അവരുടെയടുക്കൽ ചെന്ന് അവരെ കണ്ടു. ഇതാ, അവർ വിഷാദമൂകരായിരുന്നു.","p":1},{"v":7,"t":"തന്നോടൊപ്പം തന്റെ യജമാനന്റെ വീട്ടിലെ തടങ്കലിൽ കഴിയുന്നവരും ഫറവോയുടെ ഉദ്യോഗസ്ഥരുമായ അവരോട് അവൻ ഇപ്രകാരം ആരാഞ്ഞു: ഇന്നെന്താ നിങ്ങളുടെ മുഖം മ്ലാനമായിരിക്കുന്നത്?","p":1},{"v":8,"t":"അവർ അവനോടു പറഞ്ഞു: ഞങ്ങൾ സ്വപ്നം കണ്ടു; അതു വ്യാഖ്യാനിക്കാൻ ആരുമില്ല. ജോസഫ് അവരോടു പറഞ്ഞു: വ്യാഖ്യാനങ്ങൾ ദൈവത്തിന്റേതല്ലേ? എന്നോടു വിവരിച്ചാലും!","p":1},{"v":9,"t":"പാനപാത്രവാഹകപ്രമാണി തന്റെ സ്വപ്നം ജോസഫിനോടു വിവരിച്ചു. അയാൾ അവനോടു പറഞ്ഞു: എന്റെ സ്വപ്നത്തിൽ ഇതാ, എന്റെ മുൻപിൽ ഒരു മുന്തിരിച്ചെടി!","p":1},{"v":10,"t":"മുന്തിരിച്ചെടിയിൽ മൂന്നു ശാഖകൾ! അതു മൊട്ടിട്ട ഉടനെ പുഷ്പിച്ച് അതിന്റെ കുലകളിൽ മുന്തിരിപ്പഴങ്ങൾ പാകമായി.","p":1},{"v":11,"t":"ഫറവോയുടെ പാനപാത്രം എന്റെ കയ്യിൽ ഉണ്ടായിരുന്നു. ഞാൻ മുന്തിരിപ്പഴങ്ങളെടുത്ത് അവ ഫറവോയുടെ പാനപാത്രത്തിലേക്കു പിഴിഞ്ഞു. എന്നിട്ട് പാനപാത്രം ഫറവോയുടെ കയ്യിൽ കൊടുത്തു.","p":1},{"v":12,"t":"ജോസഫ് അയാളോടു പറഞ്ഞു: അതിന്റെ വ്യാഖ്യാനം ഇതാണ്: മൂന്നു ശാഖകൾ മൂന്നു ദിവസങ്ങളാണ്.","p":1},{"v":13,"t":"മൂന്നു ദിവസത്തിനകം ഫറവോ താങ്കളുടെ ശിരസ്സുയർത്തും; താങ്കളെ ഉദ്യോഗത്തിൽ പുനഃസ്ഥാപിക്കും. അദ്ദേഹത്തിന്റെ പാനപാത്രവാഹകനായിരുന്ന മുൻപത്തെ രീതിയനുസരിച്ചുതന്നെ, ഫറവോയുടെ പാനപാത്രം താങ്കൾ അദ്ദേഹത്തിന്റെ കയ്യിൽ കൊടുക്കും.","p":1},{"v":14,"t":"താങ്കൾക്കു ശ്രേയസ്സുണ്ടാകുമ്പോൾ താങ്കളോടൊപ്പം എന്നെയും ഓർത്ത് എന്നോടു കാരുണ്യം കാണിച്ചാലും! എന്നെപ്പറ്റി ഫറവോയെ ഓർമ്മിപ്പിക്കുകയും ഈ ഭവനത്തിൽനിന്ന് എന്നെ പുറത്തുകൊണ്ടുവരികയും ചെയ്യണം.","p":1},{"v":15,"t":"എന്തെന്നാൽ, സത്യത്തിൽ ഹെബ്രായരുടെ നാട്ടിൽനിന്ന് തട്ടിയെടുക്കപ്പെട്ടവനാണു ഞാൻ. ഇവിടെയും ഞാൻ ഒന്നും ചെയ്തിട്ടില്ല, അവരെന്നെ ഈ കുഴിയിൽ ഇട്ടിരിക്കുന്നത്.","p":1},{"v":16,"t":"വ്യാഖ്യാനം നന്നായിരിക്കുന്നെന്ന് പാചകപ്രമാണി കണ്ടു. അയാൾ ജോസഫിനോടു പറഞ്ഞു: ഞാനും എന്റെ സ്വപ്നത്തിൽ ആയിരുന്നപ്പോൾ ഇതാ, എന്റെ തലയിൽ മൂന്നു കുട്ട നിറയെ അപ്പം!","p":1},{"v":17,"t":"ഏറ്റവും മുകളിലെ കുട്ടയിൽ, പാചകക്കാരൻ ഫറവോയ്ക്കു വേണ്ടി തയ്യാറാക്കിയ എല്ലാത്തരം ഭക്ഷണവുമുണ്ടായിരുന്നു. എന്നാൽ, എന്റെ തലയിലെ കുട്ടയിൽനിന്ന് പക്ഷിക്കൂട്ടം അവ കൊത്തിത്തിന്നുകൊണ്ടിരുന്നു.","p":1},{"v":18,"t":"അപ്പോൾ ജോസഫ് മറുപടിയായി പറഞ്ഞു, അതിന്റെ വ്യാഖ്യാനം ഇതാണ്: മൂന്നു കുട്ടകൾ മൂന്നു ദിവസങ്ങൾതന്നെ.","p":1},{"v":19,"t":"മൂന്നു ദിവസത്തിനകം ഫറവോ നിന്റെ ശിരസ്സ് നിന്റെമേൽനിന്ന് ഉയർത്തും; നിന്നെ മരത്തിൽ കെട്ടിത്തൂക്കും. പക്ഷിക്കൂട്ടം നിന്റെമേൽനിന്ന് നിന്റെ മാംസം തിന്നുകയും ചെയ്യും.","p":1},{"v":20,"t":"മൂന്നാംദിവസം ഫറവോയുടെ പിറന്നാളായിരുന്നു. തന്റെ എല്ലാ ദാസർക്കുമായി അദ്ദേഹം ഒരു വിരുന്നൊരുക്കി. പാനപാത്രവാഹകപ്രമാണിയുടെ ശിരസ്സും പാചകപ്രമാണിയുടെ ശിരസ്സും തന്റെ ദാസർക്കിടയിൽ അദ്ദേഹം ഉയർത്തി.","p":1},{"v":21,"t":"പാനപാത്രവാഹകപ്രമാണിയെ തന്റെ പാനപാത്രവാഹകസ്ഥാനത്ത് അദ്ദേഹം തിരിയെ നിയമിച്ചു; അയാൾ പാനപാത്രം ഫറവോയുടെ കയ്യിൽ കൊടുത്തു.","p":1},{"v":22,"t":"എന്നാൽ, പാചകപ്രമാണിയെ അദ്ദേഹം തൂക്കിക്കൊന്നു. അത് ജോസഫ് അവരോടു വ്യാഖ്യാനിച്ചതുപോലെതന്നെ ആയിരുന്നു.","p":1},{"v":23,"t":"എന്നാൽ, പാനപാത്രവാഹകപ്രമാണി ജോസഫിനെ ഓർമ്മിച്ചില്ല; അയാൾ അവനെ മറന്നുകളഞ്ഞു.","p":1}],"41":[{"h":"ഫറവോയുടെ സ്വപ്നം"},{"v":1,"t":"രണ്ടുവർഷക്കാലം കഴിഞ്ഞപ്പോൾ, ഫറവോ ഒരു സ്വപ്നം കണ്ടു: ഇതാ, അദ്ദേഹം നൈൽതീരത്തു നിൽക്കുന്നു.","p":1},{"v":2,"t":"അപ്പോഴതാ, കാഴ്ചയ്ക്ക് അഴകുള്ള, ശരീരക്കൊഴുത്ത, ഏഴു പശുക്കൾ നദിയിൽനിന്നു കയറിവരുന്നു; അവ ഞാങ്ങണമധ്യേ മേയുന്നു.","p":1},{"v":3,"t":"അതിനുപിന്നാലെ ഇതാ, കാഴ്ചയ്ക്കു വിരൂപമായ, ശരീരമെലിഞ്ഞ, വേറെ ഏഴു പശുക്കൾ നദിയിൽനിന്നു കയറിവരുന്നു; നദിതീരത്ത് അവ മറ്റു പശുക്കളുടെ അരികിൽ വന്നുനിൽക്കുന്നു.","p":1},{"v":4,"t":"എന്നിട്ട് കാഴ്ചയ്ക്കു വിരൂപമായ, ശരീരമെലിഞ്ഞ പശുക്കൾ കാഴ്ചയ്ക്ക് അഴകുള്ള, കൊഴുത്ത ഏഴു പശുക്കളെ വിഴുങ്ങിക്കളയുന്നു. അപ്പോൾ ഫറവോ ഉണർന്നു.","p":1},{"v":5,"t":"അദ്ദേഹം രണ്ടാമതും ഉറങ്ങുകയും സ്വപ്നംകാണുകയും ചെയ്തു: ഇതാ, പുഷ്ടിയും അഴകുമുള്ള ഏഴു ധാന്യക്കതിരുകൾ ഒരേ തണ്ടിൽ വളർന്നുപൊങ്ങുന്നു.","p":1},{"v":6,"t":"അവയ്ക്കു പിന്നാലെ അതാ, ശുഷ്കിച്ചതും കിഴക്കൻകാറ്റിൽ ഉണങ്ങിക്കരിഞ്ഞതുമായ ഏഴു കതിരുകൾകൂടി മുളച്ചുപൊങ്ങുന്നു.","p":1},{"v":7,"t":"ശോഷിച്ച ഏഴു കതിരുകൾ പുഷ്ടിയും സമൃദ്ധിയുമുള്ള കതിരുകളെ വിഴുങ്ങുന്നു. ഫറവോ ഉറക്കമുണർന്നപ്പോൾ, ഇതാ, സ്വപ്നംമാത്രം!","p":1},{"v":8,"t":"പ്രഭാതമായപ്പോൾ അദ്ദേഹത്തിന്റെ ആത്മാവ് അസ്വസ്ഥമായി. ഈജിപ്തിലെ എല്ലാ മന്ത്രവാദികളെയും അവിടുത്തെ എല്ലാ ജ്ഞാനികളെയും ആളയച്ചു വിളിച്ച് ഫറവോ തന്റെ സ്വപ്നം അവരോടു വിവരിച്ചു. എന്നാൽ, ഫറവോയ്ക്ക് അവ വ്യാഖ്യാനിച്ചുകൊടുക്കാൻ ആരുമുണ്ടായില്ല.","p":1},{"v":9,"t":"അപ്പോൾ പാനപാത്രവാഹകപ്രമാണി ഫറവോയോട് ഇപ്രകാരം പറഞ്ഞു: എന്റെ തെറ്റുകൾ ഇന്ന് ഞാൻ ഓർക്കാൻ ഇടയാകുന്നു.","p":1},{"v":10,"t":"ഫറവോ തന്റെ ദാസന്മാരോടു കുപിതനായപ്പോൾ എന്നെയും പാചകപ്രമാണിയെയും കാവൽസേനാനായകന്റെ വീട്ടിലെ തടങ്കലിൽ ഇട്ടിരുന്നല്ലോ.","p":1},{"v":11,"t":"ഒരു രാത്രി ഞാനും അവനും സ്വപ്നം കണ്ടു; വ്യാഖ്യാനം സംബന്ധിച്ച് വ്യത്യസ്തയുള്ള ഓരോ സ്വപ്നമാണ് ഞങ്ങൾ കണ്ടത്.","p":1},{"v":12,"t":"അവിടെ കാവൽസേനാനായകന്റെ ദാസനായ ഒരു ഹെബ്രായാ യുവാവ് ഞങ്ങളുടെകൂടെ ഉണ്ടായിരുന്നു. ഞങ്ങളുടെ സ്വപ്നങ്ങൾ അവനോടു വിവരിച്ചപ്പോൾ അവൻ ഞങ്ങൾക്ക് അവ വ്യാഖ്യാനിച്ചുതന്നു; ഓരോരുത്തരോടും അവനവന്റെ സ്വപ്നത്തിനൊത്താണ് അവൻ വ്യാഖ്യാനിച്ചത്.","p":1},{"v":13,"t":"അവൻ ഞങ്ങൾക്ക് വ്യാഖ്യാനിച്ചുതന്നപോലെതന്നെ സംഭവിച്ചു. എന്നെ എന്റെ ഉദ്യോഗത്തിൽ പുനഃസ്ഥാപിച്ചു; അയാളെ തൂക്കിലിടുകയുംചെയ്തു.","p":1},{"v":14,"t":"അപ്പോൾ ഫറവോ ജോസഫിനെ ആളയച്ചു വിളിച്ചു; അവർ അവനെ കുഴിയിൽനിന്നു തിടുക്കത്തിൽ പുറത്തുകൊണ്ടുവന്നു. അവൻ ക്ഷൗരം ചെയ്ത് തന്റെ വസ്ത്രങ്ങൾമാറി ഫറവോയുടെ പക്കൽ വന്നു.","p":1},{"v":15,"t":"ഫറവോ ജോസഫിനോടു പറഞ്ഞു: ഞാനൊരു സ്വപ്നം കണ്ടു; എന്നാൽ, ആരും അതു വ്യാഖ്യാനിക്കുന്നില്ല. നീ സ്വപ്നം കേട്ടു വ്യാഖ്യാനിക്കാറുണ്ടെന്ന് നിന്നെക്കുറിച്ച് ഞാൻ കേട്ടിരിക്കുന്നു.","p":1},{"v":16,"t":"ജോസഫ് ഫറവോയോട് ഇപ്രകാരം പ്രത്യുത്തരിച്ചു: ഞാനല്ല, ദൈവം ഫറവോയുടെ സമാധാനത്തിന്നുകൂട്ടുന്ന ഉത്തരം നൽകും.","p":1},{"v":17,"t":"ഫറവോ ജോസഫിനോടു പറഞ്ഞു: എന്റെ സ്വപ്നത്തിൽ ഇതാ, ഞാൻ നൈൽതീരത്തു നിൽക്കുകയായിരുന്നു.","p":1},{"v":18,"t":"അപ്പോഴതാ, ശരീരം കൊഴുത്ത, രൂപഭംഗിയുള്ള ഏഴു പശുക്കൾ നദിയിൽനിന്നു കയറിവന്നു; അവ ഞാങ്ങണമധ്യേ മേഞ്ഞു.","p":1},{"v":19,"t":"അവയ്ക്കുപിന്നാലെ ഇതാ, താഴ്ന്നയിനവും തീർത്തും വിരൂപവും ശരീരം മെലിഞ്ഞതുമായ മറ്റ് ഏഴു പശുക്കളും കയറിവന്നു; അവയെപ്പോലെ വികൃതമായവ ഈജിപ്തുനാട്ടിലെങ്ങും ഞാൻ കണ്ടിട്ടില്ല.","p":1},{"v":20,"t":"ശോഷിച്ചു വികൃതമായ ആ പശുക്കൾ ആദ്യത്തെ ഏഴു കൊഴുത്ത പശുക്കളെ വിഴുങ്ങിക്കളഞ്ഞു.","p":1},{"v":21,"t":"എന്നാൽ, അവ അവയുടെ ഉള്ളിലെത്തിയിട്ടും അവ ഉദരത്തിലെത്തിയെന്ന് ആർക്കും തിരിച്ചറിയാൻ കഴിയുമായിരുന്നില്ല; കാരണം, കാഴ്ചയിൽ അവ ആദ്യത്തെപ്പോലെതന്നെ വികൃതമായിരുന്നു. അപ്പോൾ ഞാൻ ഉണർന്നു.","p":1},{"v":22,"t":"വീണ്ടും, എന്റെ സ്വപ്നത്തിൽ ഞാൻ കണ്ടു: ഇതാ, ഒരേ തണ്ടിൽ വളർന്നുനില്ക്കുന്ന പുഷ്ടിയും അഴകുമുള്ള ഏഴു കതിരുകൾ!","p":1},{"v":23,"t":"ഇതാ, അവയ്ക്കുശേഷം മുളച്ചുവരുന്ന ഫലശൂന്യവും ശുഷ്കിച്ചതും കിഴക്കൻകാറ്റിൽ ഉണങ്ങിക്കരിഞ്ഞതുമായ ഏഴു കതിരുകൾ!","p":1},{"v":24,"t":"ശുഷ്കിച്ച കതിരുകൾ ഏഴു നല്ല കതിരുകളെ വിഴുങ്ങിക്കളഞ്ഞു. ഞാൻ മന്ത്രവാദികളോടു പറഞ്ഞു; എന്നാൽ, അത് എനിക്കുവേണ്ടി വിശദീകരിക്കാൻ ആരുമുണ്ടായിരുന്നില്ല.","p":1},{"v":25,"t":"അപ്പോൾ ജോസഫ് ഫറവോയോടു പറഞ്ഞു: ഫറവോയുടെ സ്വപ്നം ഒന്നുതന്നെ! ദൈവം ചെയ്യാൻപോകുന്നതെന്തെന്ന് അവിടുന്ന് ഫറവോയ്ക്കു വെളിപ്പെടുത്തിയിരിക്കുന്നു.","p":1},{"v":26,"t":"ഏഴു നല്ല പശുക്കൾ ഏഴു വർഷങ്ങളാണ്; ഏഴു നല്ല കതിരുകളും ഏഴു വർഷങ്ങൾതന്നെ; സ്വപ്നം ഒന്നുതന്നെ.","p":1},{"v":27,"t":"അവയ്ക്കു പിന്നാലെ കയറിവന്ന മെലിഞ്ഞവയും വിരൂപികളുമായ ഏഴു പശുക്കളും ഏഴു വർഷങ്ങളാണ്. പതിരുനിറഞ്ഞതും കിഴക്കൻകാറ്റിൽ ഉണങ്ങിക്കരിഞ്ഞതുമായ ഏഴു കതിരുകൾ അഞ്ചെട്ടു ഏഴു വർഷങ്ങളാണ്.","p":1},{"v":28,"t":"ഞാൻ ഫറവോയോടു പറഞ്ഞ കാര്യം ഇതാണ്: ദൈവം ചെയ്യാൻപോകുന്നതെന്തെന്ന് അവിടുന്ന് ഫറവോയ്ക്കു കാണിച്ചുതന്നിരിക്കുന്നു.","p":1},{"v":29,"t":"ഇതാ, ഈജിപ്തുനാടു മുഴുവനിലും വൻ സുഭിക്ഷത്തിൻ്റെ ഏഴു വർഷങ്ങളാണു വരുന്നത്.","p":1},{"v":30,"t":"അവയ്ക്കുശേഷം ക്ഷാമത്തിന്റെ ഏഴു വർഷങ്ങൾ ഉയർന്നു വരും; ഈജിപ്തുനാട്ടിലെ സകലസമൃദ്ധിയും വിസ്മൃതമാകും; ക്ഷാമം നാടിനെ കാർന്നെടുക്കും","p":1},{"v":31,"t":"പിന്നാലെ വരുന്ന ആ ക്ഷാമത്തിനു മുമ്പിൽ നാട്ടിലെ സമൃദ്ധി അറിയപ്പെടുകയേയില്ല; കാരണം, അത് അതിരൂക്ഷമായിരിക്കും.","p":1},{"v":32,"t":"ഫറവോയ്ക്ക് സ്വപ്നം തുടർച്ചയായി രണ്ടു തവണ ഉണ്ടായത് ദൈവത്തിന്റെ ഭാഗത്തുനിന്ന് ഇക്കാര്യം ഉറപ്പിച്ചെന്നും ദൈവം അതു നിവർത്തിക്കാൻ തിടുക്കപ്പെടുന്നെന്നും ഉള്ളതുകൊണ്ടാണ്.","p":1},{"v":33,"t":"അതുകൊണ്ട്, ഇപ്പോൾ ഫറവോ വിവേകിയും ബുദ്ധിമാനുമായ ഒരാളെ കണ്ടെത്തി അവനെ ഈജിപ്തുദേശത്തിനുമേൽ നിയമിക്കട്ടെ.","p":1},{"v":34,"t":"രാജ്യത്ത് മേൽനോട്ടക്കാരെ നിയമിച്ച് സമൃദ്ധിയുടെ ഏഴു വർഷങ്ങളിലും ഈജിപ്തുദേശത്തുനിന്ന് അഞ്ചിലൊന്നു ശേഖരിക്കാൻ ഫറവോ നടപടിയെടുക്കട്ടെ.","p":1},{"v":35,"t":"വരാൻപോകുന്ന ഈ നല്ല വർഷങ്ങളുടെ ഭക്ഷ്യവിഭവ മുഴുവൻ അവർ ശേഖരിക്കട്ടെ. ഫറവോയുടെ കരത്തിൻ കീഴിൽ അവർ ഗോതമ്പു സമാഹരിക്കുകയും ഭക്ഷ്യവിഭവം നഗരങ്ങളിൽ സൂക്ഷിച്ചുവെക്കുകയും ചെയ്യട്ടെ.","p":1},{"v":36,"t":"ഈജിപ്തുനാട്ടിൽ ഉണ്ടാകാൻപോകുന്ന ഏഴു ക്ഷാമവർഷങ്ങളിലേക്കുള്ള രാജ്യത്തിന്റെ കരുതൽ ഭക്ഷ്യവിഭവമായിരിക്കും അത്. അങ്ങനെ, നാട് പട്ടിണികൊണ്ടു നശിക്കാതിരിക്കും.","p":1},{"h":"ജോസഫ് ഈജിപ്തിന്റെ മേലുദ്യോഗസ്ഥൻ"},{"v":37,"t":"ഫറവോയുടെ ദൃഷ്ടികളിലും അവന്റെ സേവകരെല്ലാവരുടെയും ദൃഷ്ടികളിലും ഇക്കാര്യം നല്ലതായിരുന്നു.","p":1},{"v":38,"t":"ഫറവോ തന്റെ സേവകരോടു പറഞ്ഞു: ഇവനെപ്പോലെ ദൈവത്തിന്റെ ചൈതന്യം തന്നിലുള്ള ഒരാളെ നമുക്കു കണ്ടെത്താനാകുമോ?","p":1},{"v":39,"t":"എന്നിട്ട് ഫറവോ ജോസഫിനോടു പറഞ്ഞു: ദൈവം നിന്നെ ഇവയെല്ലാം അറിയിച്ചുകഴിഞ്ഞിരിക്കെ, നിന്നെപ്പോലെ ബുദ്ധിമാനും ജ്ഞാനിയുമായി ആരുമില്ല.","p":1},{"v":40,"t":"നീ എന്റെ ഭവനത്തിന് മേലാളനായിരിക്കും എന്റെ ജനം മുഴുവൻ നിൻ്റെ വാക്ക് അനുസരിക്കും സിംഹാസനം സംബന്ധിച്ച് മാത്രം ഞാൻ നിന്നെക്കാൾ വലിയവൻ ആയിരിക്കും","p":1},{"v":41,"t":"ഫറവോ ജോസഫിനോട് തുടർന്ന് പറഞ്ഞു നോക്കൂ ഈജിപ്ത് രാജ്യം മുഴുവന്റെയും മേൽ നിന്നെ ഞാൻ നിയമിച്ചിരിക്കുന്നു","p":1},{"v":42,"t":"ഫറവോ മുദ്രമോതിരം തന്റെ കയ്യിൽനിന്ന് ഊരിയെടുത്ത് ജോസഫിന്റെ കയ്യിലിട്ടുകൊടുത്തു. അവനെ പട്ടുവസ്ത്രങ്ങൾ ധരിപ്പിച്ചു; അവന്റെ കഴുത്തിൽ ഒരു സ്വർണ്ണമാല അണിയിക്കുകയും ചെയ്തു.","p":1},{"v":43,"t":"അദ്ദേഹം തനിക്കുണ്ടായിരുന്ന രണ്ടാം രഥത്തിൽ അവനെ എഴുന്നള്ളിച്ചു. 'അവ്‌റേക്' എന്ന് അവർ അവനുമുമ്പേ വിളിച്ചുപറഞ്ഞുകൊണ്ടിരുന്നു. അങ്ങനെ അദ്ദേഹം അവനെ ഈജിപ്തുരാജ്യം മുഴുവന്റെയുംമേൽ നിയമിച്ചു.","p":1},{"v":44,"t":"ഫറവോ ജോസഫിനോടു പറഞ്ഞു: ഞാൻ ഫറവോയാണ്. നിന്നെക്കൂടാതെ ഈജിപ്തുദേശത്തെങ്ങും ഒരുവനും തന്റെ കയ്യോ കാലോ ഉയർത്തുകയില്ല.","p":1},{"v":45,"t":"ഫറവോ ജോസഫിനെ സാഫ്നത്ത് ഫാനെയ് എന്ന് പേരു വിളിച്ചു; ഓനിലെ പുരോഹിതനായ പൊത്തിഫെറായുടെ മകൾ അസ്‌നത്തിനെ അവന് ഭാര്യയായി കൊടുക്കുകയും ചെയ്തു. ജോസഫ് ഈജിപ്തുരാജ്യത്ത് പര്യടനംനടത്തി.","p":1},{"v":46,"t":"ഈജിപ്തിലെ രാജാവായ ഫറവോയുടെ മുൻപിൽ സ്ഥാനീയനായപ്പോൾ ജോസഫിനു മുപ്പതു വയസ്സായിരുന്നു. ഫറവോയുടെ മുൻപിൽനിന്നു പുറപ്പെട്ട് ജോസഫ് ഈജിപ്തുരാജ്യംമുഴുവൻ സഞ്ചരിച്ചു.","p":1},{"v":47,"t":"സുഭിക്ഷത്തിൻ്റ ഏഴുവർഷം ഭൂമി സമൃദ്ധിയുളവാക്കി.","p":1},{"v":48,"t":"ഈജിപ്തുദേശത്തുണ്ടായിരുന്ന ഏഴുവർഷത്തെ ഭക്ഷ്യവിഭവമെല്ലാം അവൻ ശേഖരിച്ചു. നഗരങ്ങളിൽ ഭക്ഷ്യം സംഭരിച്ചുവെച്ചു. നഗരത്തിനുചുറ്റുമുള്ള വയലുകളിലെ ഭക്ഷ്യം അതിനുള്ളിൽത്തന്നെ സൂക്ഷിച്ചു.","p":1},{"v":49,"t":"അളവെടുപ്പിന് അതീതമായതിനാൽ അളവു നിർത്തിവെക്കുന്നതുവരെ, ജോസഫ് കടൽമണൽപോലെ ധാന്യം ധാരാളമായി കൂമ്പാരംകൂട്ടി.","p":1},{"v":50,"t":"ക്ഷാമവർഷം വരുന്നതിനുമുമ്പ് ജോസഫിന് രണ്ടു പുത്രന്മാർ ജനിച്ചു. ഓനിന്റെ പുരോഹിതനായ പൊത്തിഫെറായുടെ മകൾ അസ്‌നത്താണ് അവനുവേണ്ടി അവരെ പ്രസവിച്ചത്.","p":1},{"v":51,"t":"'എന്റെ എല്ലാ കഷ്ടപ്പാടും പിതൃഭവനം സമസ്തവും മറക്കാൻ ദൈവം ഇടയാക്കിയിരിക്കുന്നു' എന്ന അർത്ഥത്തിൽ ജോസഫ് തന്റെ കടിഞ്ഞൂൽപുത്രന് മനാസ്സെ എന്നു പേരിട്ടു.","p":1},{"v":52,"t":"രണ്ടാമന്, 'എന്റെ കഷ്ടതകളുടെ നാട്ടിൽ ദൈവം എന്നെ സന്താനപുഷ്ടിയുള്ളവനാക്കിയിരിക്കുന്നു' എന്ന അർത്ഥത്തിൽ എഫ്രായിം എന്നു പേരിട്ടു.","p":1},{"v":53,"t":"ഈജിപ്തുദേശത്തു നിലനിന്ന സമൃദ്ധിയുടെ ഏഴുവർഷങ്ങൾ അവസാനിച്ചു.","p":1},{"v":54,"t":"ജോസഫ് പറഞ്ഞതുപോലെ ക്ഷാമത്തിന്റെ ഏഴുവർഷങ്ങൾ ആരംഭിച്ചു. എല്ലാ നാടുകളിലും ക്ഷാമമുണ്ടായി; എന്നാൽ, ഈജിപ്തുദേശത്തെങ്ങും ആഹാരമുണ്ടായിരുന്നു.","p":1},{"v":55,"t":"പിന്നീട്, ഈജിപ്തുനാട്ടിലെല്ലാം ക്ഷാമമായപ്പോൾ ജനം ഫറവോയുടെയടുക്കൽ ആഹാരത്തിനായി കേണപേക്ഷിച്ചു. ഫറവോ ഈജിപ്തുകാരോടെല്ലാമായി പറഞ്ഞു: ജോസഫിന്റെ അടുത്തേക്കു പോകുവിൻ; അവൻ നിങ്ങളോടു പറയുന്നതു ചെയ്യുവിൻ!","p":1},{"v":56,"t":"ഭൂമുഖത്തെല്ലാം ക്ഷാമമുണ്ടായി. അപ്പോൾ ജോസഫ് ധാന്യപ്പുരകളെല്ലാം തുറന്ന് അവയിലുണ്ടായിരുന്ന ധാന്യം ഈജിപ്തുകാർക്ക് വിതരണംചെയ്തു. ഈജിപ്തുദേശത്ത് പട്ടിണി രൂക്ഷമായിരുന്നു.","p":1},{"v":57,"t":"ജോസഫിന്റെപക്കൽനിന്ന് ധാന്യം വാങ്ങാൻ ഭൂമിമുഴുവൻ ഈജിപ്തിലേക്കു വന്നു. കാരണം, എല്ലാ നാട്ടിലും ക്ഷാമം കൊടുമ്പിരിക്കൊണ്ടിരുന്നു.","p":1}],"42":[{"h":"ജോസഫിന്റെ സഹോദരന്മാർ ഈജിപ്തിലേക്ക്"},{"v":1,"t":"ഈജിപ്തിൽ ധാന്യമുണ്ടെന്ന് യാക്കോബു മനസ്സിലാക്കി. അപ്പോൾ യാക്കോബ് തന്റെ മക്കളോടു പറഞ്ഞു: നിങ്ങളെന്താണു പരസ്പരം നോക്കിനിൽക്കുന്നത്?","p":1},{"v":2,"t":"തുടർന്ന് അദ്ദേഹം പറഞ്ഞു: ഇതാ, ഈജിപ്തിൽ ധാന്യമുണ്ടെന്നു ഞാൻ കേട്ടു. അവിടെ ചെന്ന് നമുക്കുവേണ്ടി ധാന്യം വാങ്ങുവിൻ! അങ്ങനെ നാം ജീവിക്കട്ടെ; നമ്മൾ മരിക്കാതിരിക്കട്ടെ.","p":1},{"v":3,"t":"ഈജിപ്തിൽനിന്നു ധാന്യം വാങ്ങാനായി ജോസഫിന്റെ പത്തു സഹോദരന്മാർ ഇറങ്ങിത്തിരിച്ചു.","p":1},{"v":4,"t":"'അവനെന്തെങ്കിലും അപകടം പിണഞ്ഞെങ്കിലോ' എന്നു പറഞ്ഞ് യാക്കോബ്, ജോസഫിന്റെ സഹോദരനായ ബെഞ്ചമിനെ അവന്റെ സഹോദരന്മാരുടെകൂടെ അയച്ചില്ല.","p":1},{"v":5,"t":"അങ്ങനെ, ധാന്യം വാങ്ങാൻ പോകുന്നവരുടെ കൂട്ടത്തിൽ ഇസ്രായേലിന്റെ മക്കളും പോയി. കാരണം, കാനാൻദേശത്തും ക്ഷാമമായിരുന്നു.","p":1},{"v":6,"t":"ജോസഫായിരുന്നു ആ നാട്ടിലെ മേലധികാരി. അവനാണു നാട്ടുകാർക്കെല്ലാം ധാന്യം വിറ്റിരുന്നത്. ജോസഫിന്റെ സഹോദരന്മാർ വന്ന് നിലംപറ്റേ മുഖംതാഴ്ത്തി അവനെ വണങ്ങി.","p":1},{"v":7,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരെ കണ്ടപ്പോൾ തിരിച്ചറിഞ്ഞു. പക്ഷേ, അവൻ അപരിചിതനെന്നപോലെ അവരോടു പെരുമാറുകയും പരുഷമായി അവരോടു സംസാരിക്കുകയും ചെയ്തു. അവൻ അവരോടു ചോദിച്ചു: നിങ്ങൾ എവിടെനിന്നു വരുന്നു? അവർ പറഞ്ഞു: ഭക്ഷ്യധാന്യം വാങ്ങാൻ കാനാൻദേശത്തുനിന്ന്.","p":1},{"v":8,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരെ തിരിച്ചറിഞ്ഞെങ്കിലും അവർ അവനെ തിരിച്ചറിഞ്ഞില്ല.","p":1},{"v":9,"t":"അവരെക്കുറിച്ച് താൻ കണ്ട സ്വപ്നങ്ങൾ ജോസഫ് ഓർത്തു. അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ ചാരന്മാരാണ്; നാടിന്റെ ബലക്ഷയം കണ്ടുപിടിക്കാനാണ് നിങ്ങൾ വന്നിരിക്കുന്നത്","p":1},{"v":10,"t":"അവർ അവനോടു പറഞ്ഞു: അല്ല, എന്റെ യജമാനനേ, അങ്ങയുടെ ദാസന്മാർ വന്നിരിക്കുന്നത് ഭക്ഷ്യധാന്യം വാങ്ങാനാണ്.","p":1},{"v":11,"t":"ഞങ്ങളെല്ലാവരും ഒരാളുടെ മക്കളാണ്; ഞങ്ങൾ സത്യസന്ധരാണ്. അങ്ങയുടെ ദാസന്മാർ ചാരന്മാരല്ല.","p":1},{"v":12,"t":"അവൻ അവരോടു പറഞ്ഞു: അല്ല, തീർച്ചയായും നാടിന്റെ ബലക്ഷയം കണ്ടുപിടിക്കാനാണു നിങ്ങൾ വന്നിരിക്കുന്നത്.","p":1},{"v":13,"t":"അപ്പോൾ അവർ പറഞ്ഞു: അങ്ങയുടെ ദാസന്മാരായ ഞങ്ങൾ പന്ത്രണ്ടു സഹോദരന്മാരാണ്; കാനാൻദേശത്തുള്ള ഒരാളുടെ പുത്രന്മാർ. ഇതാ, ഇളയവൻ ഇന്ന് ഞങ്ങളുടെ പിതാവിന്റെകൂടെയുണ്ട്; എന്നാൽ ഒരുവൻ ഇല്ലാതായി.","p":1},{"v":14,"t":"ജോസഫ് അവരോടു പറഞ്ഞു: അതുകൊണ്ടുതന്നെയാണ് നിങ്ങൾ ചാരന്മാരാണെന്ന് ഞാൻ നിങ്ങളോടു പറഞ്ഞത്.","p":1},{"v":15,"t":"ഇതിനാൽ നിങ്ങൾ പരിശോധിക്കപ്പെടും: നിങ്ങളുടെ ഇളയ സഹോദരൻ ഇവിടെ വന്നിട്ടല്ലാതെ, ഫറവോയുടെ ജീവനാണേ, നിങ്ങൾ ഇവിടം വിട്ടുപോവുകയില്ല.","p":1},{"v":16,"t":"നിങ്ങളുടെ സഹോദരനെ കൊണ്ടുവരാനായി നിങ്ങളിൽനിന്ന് ഒരുവനെ അയക്കുവിൻ. അപ്പോൾ നിങ്ങളാകട്ടെ, തടവിലായിരിക്കും. അങ്ങനെ നിങ്ങളുടെ വാക്കുകൾ സത്യമോ എന്നു തെളിയിക്കപ്പെടട്ടെ. അങ്ങനെയല്ലെങ്കിൽ, ഫറവോയുടെ ജീവനാണേ, നിങ്ങൾ തീർച്ചയായും ചാരന്മാരാണ്.","p":1},{"v":17,"t":"അവൻ അവരെ മൂന്നു ദിവസം തടങ്കലിൽ സൂക്ഷിച്ചു.","p":1},{"v":18,"t":"മൂന്നാംദിവസം ജോസഫ് അവരോടു പറഞ്ഞു: ഇതു ചെയ്യുവിൻ; എങ്കിൽ നിങ്ങൾ ജീവിക്കും. ദൈവത്തെ ഭയപ്പെടുന്നവനാണ് ഞാൻ.","p":1},{"v":19,"t":"നിങ്ങൾ സത്യസന്ധരാണെങ്കിൽ നിങ്ങളുടെ ഒരു സഹോദരൻ കാരാഗൃഹത്തിൽ ബന്ധനസ്ഥനായാൽ മതി. നിങ്ങൾ പോയി വീടുകളിലെ പട്ടിണിക്ക് ധാന്യമെത്തിക്കുവിൻ!","p":1},{"v":20,"t":"നിങ്ങളുടെ ഇളയ സഹോദരനെ എന്റെയടുക്കൽ കൊണ്ടുവരുവിൻ. അപ്പോൾ നിങ്ങളുടെ വാക്കുകൾ സത്യസന്ധമെന്നു തെളിയും; നിങ്ങൾക്കു മരിക്കേണ്ടി വരികയുമില്ല. അവർ അപ്രകാരം ചെയ്തു.","p":1},{"v":21,"t":"അവർ തമ്മിൽത്തമ്മിൽ പറഞ്ഞു: കഷ്ടം! നമ്മുടെ സഹോദരൻ നമ്മോടു കേണപേക്ഷിച്ചപ്പോൾ അവന്റെ സങ്കടം കണ്ടിട്ടും ചെവികൊടുക്കാതിരുന്ന നമ്മൾ അവനെപ്രതി അപരാധികളാണ്. അതുകൊണ്ടാണ് നമുക്ക് ഈ ദുരിതം വന്നിരിക്കുന്നത്.","p":1},{"v":22,"t":"അപ്പോൾ റൂബൻ ഇപ്രകാരം പ്രത്യുത്തരിച്ചു: കുട്ടിക്കെതിരേ തെറ്റുചെയ്യരുതെന്ന് ഞാൻ നിങ്ങളോടു പറഞ്ഞതല്ലേ? എന്നാൽ നിങ്ങൾ കേട്ടില്ല. ഇതാ, അവന്റെ രക്തംതന്നെ പക വീട്ടുകയാണ്","p":1},{"v":23,"t":"ജോസഫിന് അതു മനസ്സിലാകുന്നുണ്ടെന്ന് അവർ കരുതിയില്ല; കാരണം, അവർക്കിടയിൽ ഒരു ദ്വിഭാഷിയുണ്ടായിരുന്നു.","p":1},{"v":24,"t":"അവൻ അവരിൽനിന്നു വിട്ടുമാറി കരഞ്ഞു; അവരുടെപക്കൽ തിരിച്ചെത്തി അവരോടു സംസാരിച്ചു. തുടർന്ന്, അവരുടെ കൂട്ടത്തിൽനിന്ന് ശിമയോനെ പിടിച്ച് അവരുടെ കൺമുമ്പിൽവെച്ചു ബന്ധിച്ചു.","p":1},{"v":25,"t":"ഓരോരുത്തന്റെ ചാക്കിലും അവനവന്റെ പണം തിരിയെവയ്ക്കാനും യാത്രയ്ക്കുവേണ്ടത് അവർക്കു കൊടുക്കാനും ജോസഫ് കൽപ്പിച്ചപ്രകാരം, അവരുടെ ഭാണ്ഡളിൽ അവർ ഗോതമ്പു നിറച്ചു. അങ്ങനെയാണ് അവൻ അവരോടു ചെയ്തത്.","p":1},{"v":26,"t":"ധാന്യം തങ്ങളുടെ കഴുതകളുടെ പുറത്തുകയറ്റി അവർ അവിടെനിന്നു യാത്രതിരിച്ചു.","p":1},{"v":27,"t":"വഴിയമ്പലത്തിൽവെച്ച് ഒരുവൻ കഴുതയ്ക്കു തീറ്റ കൊടുക്കാൻ ചാക്കു തുറന്നപ്പോൾ തന്റെ പണം കണ്ടു; ഇതാ, അത് ചാക്കുകെട്ടിന്റെ വായ്ഭാഗത്ത്!","p":1},{"v":28,"t":"അവൻ തന്റെ സഹോദരന്മാരോടു പറഞ്ഞു: എന്റെ പണം തിരിച്ചെത്തിരിക്കുന്നു! ഇതാ, അത് എന്റെ കെട്ടിൽത്തന്നെയുണ്ട്! അപ്പോൾ അവരുടെ ഹൃദയം ഇടിഞ്ഞുപോയി അവർ ഭയംകൊണ്ട് വിറച്ച്, പരസ്പരം പറഞ്ഞു: എന്താണ് ദൈവം നമ്മോട് ഈ ചെയ്തിരിക്കുന്നത്!","p":1},{"v":29,"t":"കാനാൻദേശത്ത് തങ്ങളുടെ പിതാവായ യാക്കോബിന്റെയടുക്കൽ വന്നെത്തിയപ്പോൾ തങ്ങൾക്കു സംഭവിച്ചതെല്ലാം അവർ അദ്ദേഹത്തോട് ഇപ്രകാരം വിവരിച്ചു:","p":1},{"v":30,"t":"ദേശാധിപനായ ആൾ ഞങ്ങളോടു പരുഷമായി സംസാരിച്ചു; നാടിനെ ഒറ്റുനോക്കാനെത്തിയവരായി അയാൾ ഞങ്ങളെ കണക്കാക്കി.","p":1},{"v":31,"t":"ഞങ്ങൾ അയാളോടു പറഞ്ഞു: ഞങ്ങൾ സത്യസന്ധരാണ്, ചാരന്മാരല്ല.","p":1},{"v":32,"t":"ഞങ്ങൾ പന്ത്രണ്ടു സഹോദരന്മാരാണ്; ഞങ്ങളുടെ പിതാവിന്റെ മക്കൾ. ഒരാൾ ഇല്ലാതായി; ഇളയവൻ ഇന്ന് കാനാൻദേശത്തു ഞങ്ങളുടെ പിതാവിന്റെകൂടെയുണ്ട്.","p":1},{"v":33,"t":"അപ്പോൾ, ദേശാധിപനായ ആൾ ഞങ്ങളോടു പറഞ്ഞു: നിങ്ങൾ സത്യസന്ധരാണോ എന്ന് ഇതുകൊണ്ട് ഞാൻ മനസ്സിലാക്കും: നിങ്ങളുടെ സഹോദരനൊരാളെ എന്റെയടുക്കൽ നിർത്തുവിൻ. നിങ്ങളുടെ ഭവനങ്ങളിലെ പട്ടിണിക്കു വേണ്ടത് എടുത്തുകൊണ്ടു പോകുവിൻ.","p":1},{"v":34,"t":"പിന്നെ നിങ്ങളുടെ ഇളയസഹോദരനെ എന്റെയടുക്കൽ കൊണ്ടുവരുവിൻ. അപ്പോൾ നിങ്ങൾ ചാരന്മാരല്ലെന്നും സത്യസന്ധരാണെന്നും എനിക്കു ബോധ്യമാകും. നിങ്ങളുടെ സഹോദരനെ ഞാൻ നിങ്ങൾക്കു വിട്ടുതരുന്നതുമാണ് നിങ്ങൾക്കു ഈ നാട് പ്രയോജനപ്പെടുത്തുകയുമാകാം.","p":1},{"v":35,"t":"അവർ തങ്ങളുടെ ചാക്കുകളഴിക്കുമ്പോ അതാ, ഓരോരുത്തരുടെയും പണക്കിഴി അവനവൻ്റെ ചാക്കിൽ! അവരും അവരുടെ പിതാവും അവരുടെ പോണ കിഴികൾ കണ്ടു ഭയപ്പെട്ടു","p":1},{"v":36,"t":"അവരുടെ പിതാവായ യാക്കോബ് അവരോടു പറഞ്ഞു: നിങ്ങൾ എന്നെ അനപത്യനാക്കിയിരിക്കുന്നു. ജോസഫ് ഇല്ലാതായി; ശിമയോനും ഇല്ല. ഇനി നിങ്ങൾ ബെഞ്ചമിനെയും കൊണ്ടുപോകും. എല്ലാം എനിക്ക് എതിരായി സംഭവിക്കുന്നു.","p":1},{"v":37,"t":"റൂബൻ തന്റെ പിതാവിനോട് ഇപ്രകാരം പറഞ്ഞു: ഞാൻ അവനെ അങ്ങയുടെപക്കൽ തിരിയെ കൊണ്ടുവന്നില്ലെങ്കിൽ എന്റെ മക്കളെ രണ്ടുപേരെയും അങ്ങേക്കു കൊല്ലാം. അവനെ എന്റെ കൈയിലേല്പിക്കുക, ഞാൻ അവനെ അങ്ങയുടെ അടുത്തു തിരിയെക്കൊണ്ടുവരുന്നതാണ്.","p":1},{"v":38,"t":"അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എന്റെ മകൻ നിങ്ങളുടെ കൂടെ വരുകയില്ല. കാരണം, അവന്റെ സഹോദരൻ മൃതനായി. ഇനി ഇവൻ മാത്രമേ ശേഷിച്ചിട്ടുള്ളൂ. നിങ്ങൾ പോകുന്ന വഴിയിൽ അവന് ആപത്തു സംഭവിച്ചാൽ നിങ്ങൾ എന്റെ വാർദ്ധക്യത്തെ കഠിനദുഃഖത്തിൽ പാതാളത്തിലേക്കു തള്ളിവിടുകയായിരിക്കും.","p":1}],"43":[{"h":"ബെഞ്ചമിനും ഈജിപ്തിലേക്ക്"},{"v":1,"t":"നാട്ടിൽ ക്ഷാമം കൊടുമ്പിരിക്കൊണ്ടു.","p":1},{"v":2,"t":"ഈജിപ്തിൽനിന്ന് കൊണ്ടുവന്ന ധാന്യം അവർ ഭക്ഷിച്ചുതീർന്നപ്പോൾ അവരുടെ പിതാവ് അവരോടു പറഞ്ഞു: നിങ്ങൾ തിരിച്ചുപോയി നമുക്കുവേണ്ടി കുറച്ചുകൂടി ഭക്ഷ്യധാന്യം വാങ്ങിക്കൊണ്ടുവരുവിൻ.","p":1},{"v":3,"t":"അപ്പോൾ യൂദാ അദ്ദേഹത്തോട് ഇപ്രകാരം പറഞ്ഞു: സഹോദരൻ നിങ്ങളോടൊപ്പം ഇല്ലാത്തപക്ഷം നിങ്ങൾ എന്റെ മുഖം ദർശിക്കുകയില്ല എന്ന് അയാൾ ഞങ്ങൾക്ക് കർശനമായി താക്കീതു നൽകിയിട്ടുണ്ട്.","p":1},{"v":4,"t":"സഹോദരനെ ഞങ്ങളോടുകൂടെ അയയ്ക്കുമെങ്കിൽ, ഞങ്ങൾ പോയി അങ്ങേക്കായി ഭക്ഷ്യധാന്യം വാങ്ങിക്കൊണ്ടുവരാം.","p":1},{"v":5,"t":"അങ്ങ് അയയ്ക്കുന്നില്ലെങ്കിൽ, ഞങ്ങൾ പോകുന്നില്ല. കാരണം, സഹോദരൻ നിങ്ങളോടൊപ്പം ഇല്ലാത്തപക്ഷം, നിങ്ങൾ എന്റെ മുഖം ദർശിക്കുകയില്ല എന്ന് അയാൾ ഞങ്ങളോടു പറഞ്ഞിട്ടുണ്ട്.","p":1},{"v":6,"t":"അപ്പോൾ ഇസ്രായേൽ ചോദിച്ചു: നിങ്ങൾക്ക് ഒരു സഹോദരൻ കൂടിയുണ്ടെന്ന് അയാളോടു വിശദീകരിച്ച് എന്തിനാണ് നിങ്ങളെന്നെ ദ്രോഹിച്ചത്?","p":1},{"v":7,"t":"അവർ പറഞ്ഞു: അയാൾ ഞങ്ങളെയും വീട്ടുകാരെയുംകുറിച്ച്, 'നിങ്ങളുടെ പിതാവ് ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നോ, നിങ്ങൾക്ക് ഒരു സഹോദരനുണ്ടോ' എന്നിങ്ങനെ വിശദമായി ചോദ്യംചെയ്തു. അപ്പോൾ ഞങ്ങൾക്ക് അയാളോട് ഇക്കാര്യങ്ങൾ ഇവ്വിധം വിശദീകരിക്കേണ്ടിവന്നു. നിങ്ങളുടെ സഹോദരനെ കൂട്ടിക്കൊണ്ടുവരുവിൻ എന്ന് അയാൾ പറയുമെന്ന് ഞങ്ങൾക്ക് എന്തെങ്കിലും അറിവുണ്ടായിരുന്നോ","p":1},{"v":8,"t":"അപ്പോൾ, യൂദാ തന്റെ പിതാവായ ഇസ്രായേലിനോടു പറഞ്ഞു: ഞങ്ങൾ തയ്യാറായി യാത്രയാകേണ്ടതിന് കുട്ടിയെ എന്നോടൊപ്പം അയച്ചാലും. അങ്ങനെ നമ്മൾ, അങ്ങും ഞങ്ങളും ഞങ്ങളുടെ കുഞ്ഞുങ്ങളും, ജീവനോടെയിരിക്കട്ടെ; നമ്മൾ മരിക്കാതിരിക്കട്ടെ.","p":1},{"v":9,"t":"ഞാൻതന്നെ അവനു ജാമ്യം നിൽക്കാം. എന്റെ കൈയിൽനിന്ന് അങ്ങേക്ക് അവനെ ആവശ്യപ്പെടാം. അവനെ ഞാൻ അങ്ങയുടെപക്കൽ തിരിയെ കൊണ്ടുവന്ന് അങ്ങയുടെമുമ്പിൽ ഹാജരാക്കുന്നില്ലെങ്കിൽ, എക്കാലവും ഞാൻ അങ്ങയോടു തെറ്റുകാരനായിരിക്കും.","p":1},{"v":10,"t":"ഞങ്ങൾ ഇത്രയും വൈകാതിരുന്നെങ്കിൽ, ഞങ്ങളിപ്പോൾ രണ്ടാംപ്രാവശ്യം പോയി തിരിച്ചെത്തുമായിരുന്നു.","p":1},{"v":11,"t":"അപ്പോൾ, അവരുടെ പിതാവായ ഇസ്രായേൽ അവരോടു പറഞ്ഞു: അങ്ങനെയെങ്കിൽ ഇതു ചെയ്യുക, നാടിന്റെ വിശിഷ്ടോൽപ്പന്നങ്ങളിൽനിന്ന് കുറച്ചു തൈലം, കുറച്ചു തേൻ, സുഗന്ധദ്രവ്യങ്ങൾ, മീറാ, ബോഡനണ്ടി, ബദാംപരിപ്പ് എന്നിവ നിങ്ങളുടെ ഭാണ്ഡങ്ങളിലെടുത്ത് അദ്ദേഹത്തിനു കാഴ്ചയായി കൊണ്ടുചെല്ലുക.","p":1},{"v":12,"t":"നിങ്ങളുടെ കൈയിൽ ഇരുമടങ്ങ് പണവും എടുത്തുകൊള്ളണം; നിങ്ങളുടെ കെട്ടുകളിൽ വായ്ഭാഗത്തു തിരിയെവെച്ചിരുന്ന പണവും നിങ്ങളുടെ കൈയിൽ തിരിച്ചു കൊണ്ടുപോകണം. ഒരുപക്ഷേ, അതൊരു നോട്ടപ്പിശകായിരിക്കും.","p":1},{"v":13,"t":"നിങ്ങൾ എഴുന്നേറ്റ് നിങ്ങളുടെ സഹോദരനെയും കൂടെക്കൂട്ടി അദ്ദേഹത്തിന്റെ അടുത്തേക്കു മടങ്ങിച്ചെല്ലുവിൻ.","p":1},{"v":14,"t":"അദ്ദേഹത്തിന്റെമുമ്പിൽ സർവശക്തനായ തമ്പുരാൻ നിങ്ങളോട് അനുകമ്പ കാണിക്കട്ടെ. അങ്ങനെ അദ്ദേഹം നിങ്ങളുടെ മറ്റേ സഹോദരനെയും ബെഞ്ചമിനെയും നിങ്ങൾക്കു വിട്ടുതരട്ടെ. ഞാനാകട്ടെ, അനപത്യനെന്നപോലെ പുത്രവിരഹമനുഭവിക്കുന്നു!","p":1},{"v":15,"t":"അവർ എഴുന്നേറ്റ് കാഴ്ചവസ്തുക്കൾ സംവഹിച്ച്, ഇരട്ടിപ്പണവും കൈയിലെടുത്ത് ബെഞ്ചമിനോടൊത്ത് ഈജിപ്തിലേക്ക് ഇറങ്ങിത്തിരിച്ചു. അവർ ജോസഫിന്റെമുമ്പിൽ സന്നിഹിതരായി.","p":1},{"v":16,"t":"ജോസഫ് ബെഞ്ചമിനെ അവരോടുകൂടെ കണ്ടു. അപ്പോൾ അവൻ തന്റെ വീട്ടുകാര്യസ്ഥനോടു പറഞ്ഞു: ഈ ആളുകളെ വീട്ടിലേക്കു കൊണ്ടുപോകുവിൻ. ഒരു മൃഗത്തെ കൊന്നു തയ്യാറാക്കുവിൻ. എന്തെന്നാൽ, എന്റെകൂടെയായിരിക്കും ഈ ആളുകൾ ഉച്ചഭക്ഷണം കഴിക്കുന്നത്.","p":1},{"v":17,"t":"ജോസഫ് പറഞ്ഞപോലെ അയാൾ ചെയ്തു. അയാൾ ആ ആളുകളെ ജോസഫിന്റെ വീട്ടിലേക്കു കൊണ്ടുപോയി.","p":1},{"v":18,"t":"ജോസഫിന്റെ വീട്ടിലേക്ക് ആനയിക്കപ്പെടുന്നത് കൊണ്ട് അവർക്കു ഭയമായി. അവർ പറഞ്ഞു: കഴിഞ്ഞ തവണ നമ്മുടെ കെട്ടുകളിൽ തിരിയെവെച്ച പണത്തെച്ചൊല്ലി നമ്മുടെമേൽ ചാടിവീഴുന്നതിനും നമ്മെ കീഴ്‌പ്പെടുത്തുന്നതിനും നമ്മെയും നമ്മുടെ കഴുതകളെയും അടിമകളായി പിടിക്കുന്നതിനുവേണ്ടിയാണ് നമ്മെ കൊണ്ടെത്തിച്ചിരിക്കുന്നത്.","p":1},{"v":19,"t":"അതുകൊണ്ട്, അവർ ജോസഫിന്റെ വീട്ടുകാര്യസ്ഥനെ സമീപിച്ച് വീട്ടുവാതിൽക്കൽവെച്ച് അയാളോടു സംസാരിച്ചു.","p":1},{"v":20,"t":"അവർ പറഞ്ഞു: അയ്യോ യജമാനനേ, കഴിഞ്ഞ തവണ ഭക്ഷ്യധാന്യം വാങ്ങുന്നതിന് ഞങ്ങൾ ഇവിടെ വന്നിരുന്നു എന്നത് ശരിയാണ്.","p":1},{"v":21,"t":"എന്നാൽ, ഞങ്ങൾ വഴിയമ്പലത്തിൽ ചെന്ന് ഞങ്ങളുടെ കെട്ടുകൾ അഴിച്ചപ്പോൾ, അതാ, ഓരോരുത്തരുടെയും പണം, ഞങ്ങളുടെ തുക അതേപടി, അവനവന്റെ കെട്ടിന്റെ വായ്ഭാഗത്തുണ്ടായിരുന്നു! ഞങ്ങൾ അത് ഞങ്ങളുടെ കൈവശം തിരിയെക്കൊണ്ടുവന്നിട്ടുണ്ട്.","p":1},{"v":22,"t":"ഭക്ഷ്യധാന്യം വാങ്ങാൻ വേറെ പണവും ഞങ്ങളുടെ കൈവശം കരുതിയിട്ടുണ്ട്. പണം ഞങ്ങളുടെ കെട്ടുകളിൽ തിരിയെവെച്ചത് ആരെന്ന് ഞങ്ങൾക്കറിഞ്ഞുകൂടാ.","p":1},{"v":23,"t":"അപ്പോൾ അയാൾ പറഞ്ഞു: നിങ്ങൾക്ക് സമാധാനം! നിങ്ങൾ ഭയപ്പെടേണ്ട. നിങ്ങളുടെ ദൈവം, നിങ്ങളുടെ പിതാവിന്റെ ദൈവമാണ് നിങ്ങളുടെ കെട്ടുകളിൽ നിങ്ങൾക്കായി നിധി നിക്ഷേപിച്ചത്. നിങ്ങളുടെ പണം എന്റെ പക്കൽ എത്തിയിട്ടുള്ളതാണ്. അയാൾ ശിമയോനെ അവരുടെയടുത്തേക്ക് കൊണ്ടുവന്നു.","p":1},{"v":24,"t":"അനന്തരം അയാൾ അവരെ ജോസഫിന്റെ വീട്ടിനുള്ളിൽ കൊണ്ടുചെന്ന് അവർക്കു വെള്ളം കൊടുത്തു; അവർ തങ്ങളുടെ കാലുകൾ കഴുകി. അയാൾ അവരുടെ കഴുതകൾക്ക് തീറ്റയും കൊടുത്തു.","p":1},{"v":25,"t":"ഉച്ചയ്ക്ക് ജോസഫ് വരുമ്പോഴേക്ക് അവർ കാഴ്ച ഒരുക്കിവെച്ചു. കാരണം, അവിടെയായിരിക്കും തങ്ങൾ ഭക്ഷണം കഴിക്കുകയെന്ന് അവർ കേട്ടിരുന്നു.","p":1},{"v":26,"t":"ജോസഫ് വീട്ടിലേക്കു വന്നപ്പോൾ അവർ അവനുവേണ്ടി തങ്ങളുടെ കൈവശമുണ്ടായിരുന്ന കാഴ്ച വീട്ടിലേക്കു കൊണ്ടുചെന്നു; അവർ അവനെ നിലംപറ്റേ വണങ്ങി.","p":1},{"v":27,"t":"അവൻ അവരോട് കുശലമന്വേഷിച്ചുകൊണ്ട് ചോദിച്ചു: ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നെന്നു നിങ്ങൾ പറഞ്ഞ നിങ്ങളുടെ വൃദ്ധനായ പിതാവിന് സുഖംതന്നെയോ?","p":1},{"v":28,"t":"അവർ പറഞ്ഞു: അങ്ങയുടെ ദാസനായ ഞങ്ങളുടെ പിതാവിന് സുഖംതന്നെ. അദ്ദേഹം ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നു. അവർ കുനിഞ്ഞ് അവനെ വണങ്ങി.","p":1},{"v":29,"t":"അവൻ കണ്ണുകളുയർത്തി നോക്കിയപ്പോൾ തന്റെ സഹോദരൻ ബെഞ്ചമിനെ, തന്റെതന്നെ അമ്മയുടെ മകനെ, കണ്ടു. അവൻ ചോദിച്ചു: ഇവനാണോ നിങ്ങൾ എന്നോടു പറഞ്ഞ നിങ്ങളുടെ ഇളയ സഹോദരൻ? തുടർന്ന് അവൻ പറഞ്ഞു: എന്റെ മകനേ, ദൈവം നിന്നോടു കനിവു കാണിക്കട്ടെ.","p":1},{"v":30,"t":"ജോസഫ് തിടുക്കംകൂട്ടി; കാരണം, സഹോദരനെപ്രതി അവന്റെ ഉള്ളം തുടിച്ചു. അവൻ കരയാൻ വെമ്പി ഉൾമുറിയിലേക്ക് പ്രവേശിച്ച് അവിടെ അവൻ കരഞ്ഞു.","p":1},{"v":31,"t":"പിന്നെ അവൻ മുഖം കഴുകി പുറത്തുവന്ന്, തന്നെത്തന്നെ നിയന്ത്രിച്ചുകൊണ്ട് പറഞ്ഞു: ഭക്ഷണം വിളമ്പുവിൻ.","p":1},{"v":32,"t":"അവനും അവർക്കും പിന്നെ അവനോടൊത്തു ഭക്ഷണം കഴിക്കുന്ന ഈജിപ്തുകാർക്കും അവർ വിളമ്പിയത് പ്രത്യേകംപ്രത്യേകമായാണ്. ഹെബ്രായാരോടൊത്തു ഭക്ഷണംകഴിക്കുന്നത് ഈജിപ്തുകാർക്കു നിഷിദ്ധമായിരുന്നതുകൊണ്ട് ഈജിപ്തുകാർക്ക് അതിനു കഴിയുമായിരുന്നില്ല.","p":1},{"v":33,"t":"അവന്റെ മുമ്പിൽ അവർ ഇരുന്നത് മൂത്തവൻ തന്റെ മൂപ്പനുസരിച്ചും ഇളയവൻ തന്റെ ഇളപ്പമനുസരിച്ചുമാണ്. ആ ആളുകൾ അന്യോന്യം വിസ്മയംപ്രകടിപ്പിച്ചു.","p":1},{"v":34,"t":"അവൻ തന്റെ മുമ്പിലുണ്ടായിരുന്ന പങ്കുകൾ അവർക്കായി വീതിച്ചു. എന്നാൽ, ബെഞ്ചമിന്റെ പങ്ക് എല്ലാവരുടെയും പങ്കുകളെക്കാൾ അഞ്ചുമടങ്ങ് അധികമായിരുന്നു. അവർ അവനോടൊപ്പം പാനംചെയ്തുല്ലസിച്ചു.","p":1}],"44":[{"h":"സഹോദരന്മാർക്ക് അഗ്നി പരീക്ഷ"},{"v":1,"t":"അവൻ തന്റെ വീട്ടുകാര്യസ്ഥനോട് ഇപ്രകാരം കൽപ്പിച്ചു: അവർക്കു സംവഹിക്കാൻ സാധിക്കുന്നത്ര ഭക്ഷ്യധാന്യം അവരുടെ കെട്ടുകളിൽ നിറയ്ക്കുവിൻ. ഓരോരുത്തന്റെയും പണം അവനവന്റെ കെട്ടിന്റെ വായ്ഭാഗത്തു വെയ്ക്കുകയും വേണം.","p":1},{"v":2,"t":"ഇളയവന്റെ കെട്ടിന്റെ വായ്ഭാഗത്ത് എന്റെ പാനപാത്രം, വെള്ളിപ്പാനപാത്രം, അവന്റെ ധാന്യവിലയായ പണത്തിന്റെകൂടെ വെയ്ക്കുക. ജോസഫ് പറഞ്ഞ വാക്കനുസരിച്ച് അയാൾ പ്രവർത്തിച്ചു.","p":1},{"v":3,"t":"രാവിലെ വെട്ടം വീണപ്പോൾ, അവർ - അവരും അവരുടെ കഴുതകളും - യാത്രയാക്കപ്പെട്ടു.","p":1},{"v":4,"t":"അവർ നഗരംവിട്ട് ദൂരത്തായില്ല, അപ്പോൾ ജോസഫ് തന്റെ വീട്ടുകാര്യസ്ഥനോടു പറഞ്ഞു: എഴുന്നേറ്റ് ആ ആളുകളുടെ പിന്നാലെ പായുക. അവരെ മറികടന്നിട്ട് അവരോടു പറയണം: നിങ്ങൾ നന്മയ്ക്കുപകരം തിന്മചെയ്തത് എന്തുകൊണ്ട്?","p":1},{"v":5,"t":"ഇതിൽനിന്നല്ലേ എന്റെ യജമാനൻ പാനംചെയ്യുന്നത്? ഇതുകൊണ്ടുതന്നെയല്ലേ അദ്ദേഹം ഗണിച്ചറിയുന്നത്? നിങ്ങൾ ചെയ്തതു ദുഷ്കൃത്യമായിപ്പോയി.","p":1},{"v":6,"t":"അവരെ മറികടന്നിട്ട് അവൻ അവരോട് ഇക്കാര്യങ്ങൾ പറഞ്ഞു.","p":1},{"v":7,"t":"അപ്പോൾ അവർ അവനോടു പറഞ്ഞു: എന്താണ് എന്റെ യജമാനൻ ഇത്തരം വാക്കുകൾ സംസാരിക്കുന്നത്? ഇത്തരമൊരു കാര്യം ചെയ്യാൻ താങ്കളുടെ ദാസന്മാർക്ക് ഇടയാകാതിരിക്കട്ടെ!","p":1},{"v":8,"t":"നോക്കൂ, ഞങ്ങളുടെ കെട്ടുകളുടെ വായ്ഭാഗത്ത് ഞങ്ങൾ കണ്ടെത്തിയ പണം കാനാൻദേശത്തുനിന്നു ഞങ്ങൾ താങ്കളുടെ അടുത്തു തിരിയെകൊണ്ടുവന്നല്ലോ? അപ്പോൾ പിന്നെ ഞങ്ങൾ താങ്കളുടെ യജമാനന്മാരുടെ വീട്ടിൽനിന്ന് വെള്ളിയോ പൊന്നോ എങ്ങനെ മോഷ്ടിക്കും?","p":1},{"v":9,"t":"അത് താങ്കളുടെ ദാസരിൽ ആരുടെപക്കൽ കണ്ടെത്തപ്പെടുന്നുവോ അവൻ മരിക്കണം; ഞങ്ങളെല്ലാവരും എന്റെ യജമാനന് അടിമകളായിരിക്കുകയും ചെയ്യും.","p":1},{"v":10,"t":"അവൻ പറഞ്ഞു: ഇപ്പോഴും നിങ്ങൾ പറയുന്നപോലെയാവട്ടെ. അത് ആരുടെപക്കൽ കാണപ്പെടുന്നുവോ അവൻ എനിക്ക് അടിമയാകും; നിങ്ങൾ നിരപരാധരായിരിക്കും.","p":1},{"v":11,"t":"അപ്പോൾ ഓരോരുത്തരും തിടുക്കപ്പെട്ട് അവനവന്റെ കെട്ട് നിലത്തിറക്കി; ഓരോരുത്തനും അവനവന്റെ കെട്ടഴിച്ചു.","p":1},{"v":12,"t":"അപ്പോൾ അവൻ മൂത്തവനിൽ ആരംഭിച്ച് ഇളയവനിൽ അവസാനിക്കുംവിധം പരിശോധിച്ചു; ബെഞ്ചമിന്റെ കെട്ടിൽ ചഷകം കണ്ടെത്തുകയും ചെയ്തു.","p":1},{"v":13,"t":"അവർ തങ്ങളുടെ വസ്ത്രം വലിച്ചുകീറി; ഓരോരുത്തനും അവനവന്റെ കഴുതപ്പുറത്ത് ചുമടുകയറ്റി, പട്ടണത്തിലേക്ക് മടങ്ങി.","p":1},{"v":14,"t":"യൂദാ അവന്റെ സഹോദരന്മാരോടൊത്ത് ജോസഫിന്റെ വീട്ടിലേക്കു ചെന്നു. അവൻ അപ്പോഴും അവിടെ ഉണ്ടായിരുന്നു. അവർ അവന്റെമുമ്പിൽ നിലംപറ്റെ വീണു.","p":1},{"v":15,"t":"ജോസഫ് അവരോടു ചോദിച്ചു: ഇതെന്തു പ്രവൃത്തിയാണു നിങ്ങൾ ചെയ്തത്? എന്നെപ്പോലൊരാൾക്ക് തീർച്ചയായും ഗണിച്ചറിയാനാകുമെന്ന് നിങ്ങൾക്കറിഞ്ഞുകൂടേ?","p":1},{"v":16,"t":"അപ്പോൾ യൂദാ പറഞ്ഞു: ഞങ്ങൾ എന്താണ് യജമാനനോടു പറയേണ്ടത്? എന്താണ് സംസാരിക്കേണ്ടത്? എങ്ങനെയാണ് സ്വയം സാധൂകരിക്കേണ്ടത്? ദൈവം അങ്ങയുടെ ദാസരുടെ കുറ്റം കണ്ടുപിടിച്ചിരിക്കുന്നു. ഇതാ, ഞങ്ങൾ യജമാനന് അടിമകളാണ്; ഞങ്ങളും ആരുടെ കൈവശം പാനപാത്രം കണ്ടുപിടിക്കപ്പെട്ടുവോ അവനും.","p":1},{"v":17,"t":"എന്നാൽ, അവൻ പറഞ്ഞു: ഞാൻ അതു ചെയ്യാൻ ഇടയാകാതിരിക്കട്ടെ! ആരുടെ കൈവശം പാനപാത്രം കണ്ടുപിടിക്കപ്പെട്ടുവോ, അവൻമാത്രം എനിക്ക് അടിമയായിരിക്കും. നിങ്ങൾ സമാധാനമായി നിങ്ങളുടെ പിതാവിന്റെ അടുത്തേക്കു പൊയ്ക്കൊള്ളുവിൻ.","p":1},{"v":18,"t":"അപ്പോൾ യൂദാ അവന്റെ അടുത്തുചെന്നു പറഞ്ഞു: അല്ലയോ എന്റെ യജമാനനേ, അങ്ങയുടെ ദാസൻ ഒരു വാക്കുകൂടി യജമാനന്റെ ചെവികളിൽ ഉണർത്തിച്ചുകൊള്ളട്ടെ! അങ്ങയുടെ ദാസന്റെനേരേ അങ്ങയുടെ കോപം ജ്വലിക്കാതിരിക്കട്ടെ. എന്തെന്നാൽ, ഫറവോ എങ്ങനെയോ അതുപോലെയാണ് അങ്ങ്.","p":1},{"v":19,"t":"എന്റെ യജമാനൻ അങ്ങയുടെ ദാസന്മാരോട് ഇപ്രകാരം തിരക്കിയിരുന്നു: നിങ്ങൾക്കു പിതാവോ സഹോദരനോ ഉണ്ടോ?","p":1},{"v":20,"t":"അപ്പോൾ, ഞങ്ങൾ എന്റെ യജമാനനോട്, ഞങ്ങൾക്കു വൃദ്ധനായ പിതാവും വാർദ്ധക്യത്തിലെ മകനായ ഒരു ഇളയവനുമുണ്ട്; അവന്റെ സഹോദരൻ മരിച്ചുപോയി, അവന്റെ അമ്മയുടേതായി അവൻമാത്രമേ ശേഷിച്ചിട്ടുള്ളൂ; അവന്റെ പിതാവ് അവനെ സ്നേഹിക്കുകയും ചെയ്യുന്നു എന്നു പറഞ്ഞിരുന്നു.","p":1},{"v":21,"t":"അപ്പോഴാണ് അങ്ങ് അങ്ങയുടെ ദാസരോട്, അവനെ എന്റെയടുത്തു കൂട്ടിക്കൊണ്ടുവരുക; എനിക്കവനെ നേരിട്ടുകാണണം എന്നു പറഞ്ഞത്.","p":1},{"v":22,"t":"അപ്പോൾ ഞങ്ങൾ യജമാനനോട്, ബാലന് തന്റെ പിതാവിനെ വിട്ടുപോരാൻ വയ്യാ, അവൻ തന്റെ പിതാവിനെ പിരിഞ്ഞാൽ അദ്ദേഹം മരിച്ചുപോകും എന്ന് ഉണർത്തുകയുണ്ടായി.","p":1},{"v":23,"t":"നിങ്ങളുടെ ഇളയ സഹോദരൻ നിങ്ങളോടുകൂടെ വരുന്നില്ലെങ്കിൽ നിങ്ങൾ എന്റെ മുഖം ഇനി കാണുകയുണ്ടാവുകയില്ല എന്ന് അങ്ങ് അങ്ങയുടെ ദാസന്മാരോട് പറഞ്ഞു.","p":1},{"v":24,"t":"പിന്നെ സംഭവിച്ചത് ഇതാണ്: ഞങ്ങൾ അങ്ങയുടെ ദാസനായ എന്റെ പിതാവിന്റെ അടുത്തെത്തി, എന്റെ യജമാനന്റെ വാക്കുകൾ ഞങ്ങൾ അദ്ദേഹത്തോടു വിവരിച്ചു.","p":1},{"v":25,"t":"തിരിച്ചുപോയി നമുക്കായി കുറച്ചു ഭക്ഷ്യധാന്യം വാങ്ങിക്കൊണ്ടുവരുവിൻ എന്ന് പിന്നീട് ഞങ്ങളുടെ പിതാവ് പറഞ്ഞപ്പോൾ","p":1},{"v":26,"t":"ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങൾക്ക് പോകാൻ വയ്യാ; എന്നാൽ, ഞങ്ങളുടെ ഇളയസഹോദരൻ ഞങ്ങളോടൊത്തുണ്ടെങ്കിൽ ഞങ്ങൾ പോകാം. കാരണം, ഞങ്ങളുടെ ഇളയസഹോദരൻ ഞങ്ങളോടൊത്തില്ലെങ്കിൽ ഞങ്ങൾക്ക് അദ്ദേഹത്തിന്റെ മുഖം കാണാൻ സാധിക്കുകയില്ല.","p":1},{"v":27,"t":"അപ്പോൾ അങ്ങയുടെ ദാസനായ, എന്റെ പിതാവ് ഞങ്ങളോടു പറഞ്ഞു: എന്റെ ഭാര്യ എനിക്കുവേണ്ടി രണ്ടു പ്രസവിച്ചു എന്ന് നിങ്ങൾക്കറിയാമല്ലോ.","p":1},{"v":28,"t":"ഒരുവൻ എന്നെ വിട്ടുപോയി. അപ്പോൾ ഞാൻ പറഞ്ഞു: തീർച്ചയായും വന്യമൃഗം ചീന്തിക്കീറിയതുതന്നെ. പിന്നെ ഞാൻ അവനെ ഇതുവരെ കണ്ടിട്ടില്ല.","p":1},{"v":29,"t":"ഇവനെക്കൂടി നിങ്ങൾ എന്റെ മുമ്പിൽനിന്ന് കൊണ്ടുപോവുകയും അവന് ആപത്ത് പിണയുകയും ചെയ്താൽ നിങ്ങൾ എന്റെ വാർദ്ധക്യം ദുരിതത്തോടെ പാതാളത്തിലേക്ക് ആഴ്ത്തുകയായിരിക്കും","p":1},{"v":30,"t":"ഇപ്പോഴാകട്ടെ, അങ്ങയുടെ ദാസനായ, എന്റെ പിതാവിന്റെ അടുത്തേക്കു ഞാൻ ചെല്ലുമ്പോൾ ആ ബാലൻ ഞങ്ങളോടൊത്തുണ്ടാകില്ല; അദ്ദേഹത്തിന്റെ ജീവനോ അവന്റെ ജീവനോടു ബന്ധിക്കപ്പെട്ടുമിരിക്കുന്നു.","p":1},{"v":31,"t":"ബാലനില്ല എന്ന് അദ്ദേഹം കാണുന്നവേളയിൽ അദ്ദേഹം മരിക്കും. അങ്ങനെ അങ്ങയുടെ ദാസന്മാർ അങ്ങയുടെ ദാസനായ ഞങ്ങളുടെ പിതാവിന്റെ വാർദ്ധക്യം ദുഃഖസാന്ദ്രതയിൽ പാതാളത്തിലേക്ക് ആഴ്ത്തുകയായിരിക്കും","p":1},{"v":32,"t":"മാത്രമല്ല, ബാലനെ ഞാൻ അങ്ങയുടെപക്കൽ തിരിച്ചെത്തിക്കുന്നില്ലെങ്കിൽ ജീവിതകാലമുഴുവൻ ഞാൻ എന്റെ പിതാവിനോടു കുറ്റക്കാരനായിരിക്കും എന്നു പറഞ്ഞ് ബാലനുവേണ്ടി എന്റെ പിതാവിന്റെപക്കൽ അങ്ങയുടെ ദാസൻ ജാമ്യംനിന്നിട്ടുമുണ്ട്.","p":1},{"v":33,"t":"അതിനാൽ ഇപ്പോൾ ബാലനുപകരം അങ്ങയുടെ ദാസൻ എന്റെ യജമാനന് അടിമയായി കഴിഞ്ഞുകൊള്ളട്ടെ; ബാലൻ അവന്റെ സഹോദരന്മാരുടെ കൂടെ തിരിച്ചുപോവുകയും ചെയ്യട്ടെ.","p":1},{"v":34,"t":"ബാലൻ എന്നോടൊപ്പമില്ലാതെ ഞാൻ എങ്ങനെ എന്റെ പിതാവിന്റെയടുത്തു ചെല്ലും? എന്റെ പിതാവിനെ പിടികൂടുന്ന ദുരന്തം കാണാൻ എനിക്ക് ഇടയാകരുതല്ലോ.","p":1}],"45":[{"h":"ജോസഫ് സ്വയം വെളിപ്പെടുത്തുന്നു"},{"v":1,"t":"തന്റെ ചുറ്റും നിലകൊണ്ടിരുന്ന എല്ലാവരുടെയുംമുമ്പിൽ സ്വയം നിയന്ത്രിക്കാൻ ജോസഫിനു കഴിഞ്ഞില്ല. അതുകൊണ്ട്, അവൻ വിളിച്ചുപറഞ്ഞു: എല്ലാവരും എന്റെപക്കൽനിന്നു പുറത്തു പോകുവിൻ. അതിനാൽ ജോസഫ് തന്റെ സഹോദരന്മാർക്ക് തന്നെത്തന്നെ വെളിപ്പെടുത്തിയപ്പോൾ ഒരാൾപോലും അവനോടുകൂടെ നിന്നിരുന്നില്ല.","p":1},{"v":2,"t":"അവൻ സ്വരമുയർത്തി കരഞ്ഞു. ഈജിപ്തുകാർ അതു കേട്ടു; ഫറവോയുടെ ഭവനവും കേട്ടു.","p":1},{"v":3,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരോടു പറഞ്ഞു: ഞാൻ ജോസഫാണ്. എന്റെ പിതാവ് ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നുവോ? അവനോടു മറുപടിപറയാൻ അവന്റെ സഹോദരന്മാർക്കു സാധിച്ചില്ല; അവന്റെ മുമ്പിൽ അവർ പരിഭ്രമിച്ചുപോയിരുന്നു.","p":1},{"v":4,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരോടു പറഞ്ഞു: എന്റെയടുത്തേക്കു വന്നാലും. അവർ അടുത്തുചെന്നു. അപ്പോൾ അവൻ പറഞ്ഞു: നിങ്ങൾ ഈജിപ്തിലേക്കു വിറ്റ നിങ്ങളുടെ സഹോദരൻ ജോസഫാണു ഞാൻ.","p":1},{"v":5,"t":"എന്നാലിപ്പോൾ എന്നെ ഇവിടെക്കു വിറ്റതോർത്ത് നിങ്ങൾ നഷ്ടധൈര്യരാകേണ്ട; നിങ്ങളോടുതന്നെ കുപിതരാകുകയുംവേണ്ട. കാരണം, അതിജീവനത്തിനായി ദൈവമാണ് എന്നെ നിങ്ങൾക്കുമുമ്പേ ഇങ്ങോട്ടയച്ചത്.","p":1},{"v":6,"t":"എന്തെന്നാൽ, നാട്ടിൽ ക്ഷാമം ഇതു രണ്ടാം വർഷമാണ്; ഉഴവും കൊയ്ത്തുമില്ലാത്ത അഞ്ചുവർഷങ്ങൾ ഇനിയുമുണ്ട്.","p":1},{"v":7,"t":"നിങ്ങൾക്ക് ഭൂമിയിൽ ഒരു ശിഷ്ടഭാഗം നിലനിർത്താനും നിങ്ങൾക്ക് മഹാവിമോചനത്തിനുവേണ്ടി ജീവൻ സംരക്ഷിക്കാനുമായി ദൈവം എന്നെ നിങ്ങൾക്കുമുമ്പേ അയച്ചതാണ്.","p":1},{"v":8,"t":"അതുകൊണ്ടുതന്നെ നിങ്ങളല്ല എന്നെ ഇങ്ങോട്ടയച്ചത്, പിന്നെയോ, ദൈവമാണ്. അവിടുന്ന് എന്നെ ഫറവോയ്ക്കു പിതാവും അദ്ദേഹത്തിന്റെ വീടിനുമുഴുവനും നാഥനും ഈജിപ്തുദേശത്തിനുമുഴുവനും ഭരണാധിപനുമാക്കിയിരിക്കുന്നു.","p":1},{"v":9,"t":"നിങ്ങൾ വേഗം എന്റെ പിതാവിന്റെയടുത്തുചെന്ന് അദ്ദേഹത്തോടു പറയുക: അങ്ങയുടെ മകൻ ജോസഫ് ഇപ്രകാരം പറയുന്നു, ദൈവം എന്നെ ഈജിപ്തിനുമുഴുവൻ നാഥനാക്കിയിരിക്കുന്നു. എന്റെയടുത്തുവരണം, ഒട്ടും വൈകരുതേ!","p":1},{"v":10,"t":"അങ്ങേക്കു ഗോഷെൻ പ്രദേശത്തു പാർക്കാം. അങ്ങ് എന്റെയടുത്തായിരിക്കും; അങ്ങയോടൊപ്പം, അങ്ങയുടെ മക്കളും മക്കളുടെ മക്കളും അങ്ങയുടെ ആടുമാടുകളും അങ്ങയ്ക്കുള്ള സകലതും.","p":1},{"v":11,"t":"അവിടെ അങ്ങയെ ഞാൻ പോറ്റിക്കൊള്ളാം. എന്തെന്നാൽ, ക്ഷാമം അഞ്ചുകൊല്ലത്തേക്കുകൂടിയുണ്ട്. അങ്ങും അങ്ങയുടെ കുടുംബവും അങ്ങേക്കുള്ളവരും ദാരിദ്ര്യമനുഭവിക്കരുതല്ലോ.","p":1},{"v":12,"t":"ഇതാ, എന്റെ അധരംതന്നെയാണു നിങ്ങളോടു സംസാരിക്കുന്നതെന്ന് നിങ്ങളുടെ നയനങ്ങളും എന്റെ സഹോദരനായ ബെഞ്ചമിന്റെ നയനങ്ങളും കണ്ടുകൊണ്ടിരിക്കുകയാണല്ലോ.","p":1},{"v":13,"t":"ഈജിപ്തിലെ എന്റെ സർവപ്രതാപവും നിങ്ങൾ കണ്ടതുമെല്ലാം പിതാവിനോടു നിങ്ങൾ വിവരിക്കുമല്ലോ. വേഗം എന്റെ പിതാവിനെ ഇവിടേക്ക് കൊണ്ടുവരണം.","p":1},{"v":14,"t":"അവൻ തന്റെ സഹോദരനായ ബെഞ്ചമിന്റെ കഴുത്തിൽവീണു കരഞ്ഞു. ബെഞ്ചമിനും അവന്റെ കഴുത്തിൽചാഞ്ഞു കരഞ്ഞു.","p":1},{"v":15,"t":"അവൻ തന്റെ സഹോദരന്മാരെയെല്ലാവരെയും ചുംബിക്കുകയും അവരുടെ മേൽചാഞ്ഞ് കരയുകയും ചെയ്തു. അനന്തരം അവന്റെ സഹോദരന്മാർ അവനോടു സംസാരിച്ചു.","p":1},{"v":16,"t":"\"ജോസഫിന്റെ സഹോദരന്മാർ വന്നിട്ടുണ്ട് എന്ന് ഫറവോയുടെ ഭവനത്തിൽ ശ്രുതിപരന്നു. ഫറവോയുടെ ദൃഷ്ടികളിലും അദ്ദേഹത്തിന്റെ ദാസരുടെ ദൃഷ്ടികളിലും അത് നന്നായിരുന്നു.","p":1},{"v":17,"t":"ഫറവോ ജോസഫിനോടു പറഞ്ഞു: താങ്കളുടെ സഹോദരന്മാരോട് ഇതു ചെയ്യുവിൻ എന്നു പറയുക: നിങ്ങളുടെ മൃഗങ്ങളുടെമേൽ ചുമടേറ്റുവിൻ; കാനാൻദേശത്തേക്കു വേഗം ചെല്ലുവിൻ.","p":1},{"v":18,"t":"നിങ്ങളുടെ പിതാവിനെയും നിങ്ങളുടെ കുടുംബങ്ങളെയും എന്റെയടുത്തു കൂട്ടിക്കൊണ്ടുവരുവിൻ. ഈജിപ്തുനാട്ടിലെ ഐശ്വര്യം നിങ്ങൾക്കു ഞാൻ സമ്മാനിക്കാം; ദേശത്തിന്റെ പുഷ്ടി നിങ്ങൾക്കു ആസ്വദിക്കുകയും ചെയ്യാം.","p":1},{"v":19,"t":"ഇതാ, താങ്കൾ നിയുക്തനായിരിക്കുന്നു. നിങ്ങൾ ഇതു ചെയ്യുവിൻ: നിങ്ങൾക്കുവേണ്ടി, നിങ്ങളുടെ കുഞ്ഞുങ്ങൾക്കും നിങ്ങളുടെ ഭാര്യമാർക്കുംവേണ്ടി, ഈജിപ്തുനാട്ടിൽനിന്നു വാഹനങ്ങൾ കൊണ്ടുപോകുവിൻ. നിങ്ങളുടെ പിതാവിനെ കയറ്റി നിങ്ങൾ വരുവിൻ.","p":1},{"v":20,"t":"നിങ്ങളുടെ സാധനസാമഗ്രികളെപ്പറ്റി പര്യാകുലരാകേണ്ട; എന്തെന്നാൽ, ഈജിപ്തുനാട്ടിലെങ്ങുമുള്ള ഐശ്വര്യം നിങ്ങളുടേതായിരിക്കും.","p":1},{"v":21,"t":"ഇസ്രായേലിന്റെ പുത്രന്മാർ അങ്ങനെ ചെയ്തു. ഫറവോയുടെ കല്പനപ്രകാരം ജോസഫ് അവർക്കു വാഹനങ്ങൾ കൊടുത്തു; യാത്രയ്ക്കുവേണ്ടതും നൽകി.","p":1},{"v":22,"t":"അവൻ അവർക്ക് ഓരോരുത്തർക്കും വിശിഷ്ടവസ്ത്രങ്ങൾ നൽകി. ബെഞ്ചമിന് അവൻ മൂന്നൂറു വെള്ളിനാണയവും അഞ്ചു വിശിഷ്ടവസ്ത്രങ്ങളും കൊടുത്തു.","p":1},{"v":23,"t":"അവൻ തന്റെ പിതാവിനായി കൊടുത്തയച്ചവ ഇവയാണ്: ഈജിപ്തിലെ വിശിഷ്ടവസ്തുക്കൾ സംവഹിക്കുന്ന പത്തു കഴുതകൾ, ഗോതമ്പും അപ്പവും തന്റെ പിതാവിന്റെ യാത്രയ്ക്കുവേണ്ട ഭക്ഷണവും വഹിക്കുന്ന പത്തു പെൺകഴുതകൾ.","p":1},{"v":24,"t":"അങ്ങനെ അവൻ തന്റെ സഹോദരന്മാരെ യാത്രയാക്കി. അവർ പോകുമ്പോൾ അവൻ അവരോടു പറഞ്ഞു: വഴിക്കുവെച്ചു ശണ്ഠകൂടരുത്.","p":1},{"v":25,"t":"അവർ ഈജിപ്തിൽനിന്നു പുറപ്പെട്ട് കാനാൻദേശത്ത് തങ്ങളുടെ പിതാവായ യാക്കോബിന്റെ അടുത്തെത്തി.","p":1},{"v":26,"t":"അവർ അദ്ദേഹത്തോട് ഇപ്രകാരം വിവരിച്ചു: ജോസഫ് ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നു. അവൻതന്നെയാണ് ഈജിപ്തുദേശംമുഴുവന്റെയും ഭരണാധികാരി. അപ്പോൾ അദ്ദേഹത്തിന്റെ ഹൃദയം ജീവസ്സറ്റതായി; കാരണം, അദ്ദേഹം അവരെ വിശ്വസിച്ചില്ല.","p":1},{"v":27,"t":"എന്നാൽ, ജോസഫ് അവരോടു പറഞ്ഞകാര്യങ്ങളെല്ലാം അവർ അദ്ദേഹത്തോടു പറയുകയും തന്നെ കയറ്റാൻ ജോസഫ് അയച്ച വാഹനങ്ങൾ കാണുകയും ചെയ്തപ്പോൾ, അവരുടെ പിതാവായ യാക്കോബിന്റെ ചൈതന്യം ജീവസ്സുറ്റതായി.","p":1},{"v":28,"t":"അപ്പോൾ ഇസ്രായേൽ പറഞ്ഞു: കൊള്ളാം; എന്റെ മകൻ ജോസഫ് ഇപ്പോഴും ജീവിച്ചിരിക്കുന്നു! ഞാൻ മരിക്കുംമുമ്പ് അവനെ എനിക്ക് കാണാനിടയാകട്ടെ!","p":1}],"46":[{"h":"യാക്കോബും മക്കളും ഈജിപ്തിൽ"},{"v":1,"t":"ഇസ്രായേൽ തനിക്കുള്ള സകലതിനോടുമൊപ്പം യാത്രതിരിച്ചു; ബേർഷെബായിലേക്കു വന്നു. അപ്പോൾ അദ്ദേഹം തന്റെ പിതാവായ ഇസഹാക്കിന്റെ ദൈവത്തിനു ബലികൾ സമർപ്പിച്ചു.","p":1},{"v":2,"t":"നിശാദർശനങ്ങളിലൂടെ ദൈവം ഇസ്രായേലിനോടു സംസാരിച്ചു. അവിടന്നു വിളിച്ചു: യാക്കോബേ, യാക്കോബേ. ഇതാ ഞാൻ, അദ്ദേഹം പറഞ്ഞു.","p":1},{"v":3,"t":"അവിടന്നു പറഞ്ഞു: ഞാൻ ദൈവമാണ്, നിന്റെ പിതാവിന്റെ ദൈവം. ഈജിപ്തിലേക്കു പോകുന്നതുകൊണ്ടു നീ ഭയപ്പെടേണ്ടാ. കാരണം, അവിടെ ഞാൻ നിന്നെ ഒരു വലിയ ജനതയാക്കി സ്ഥാപിക്കും.","p":1},{"v":4,"t":"ഞാൻ നിന്നോടൊപ്പം ഈജിപ്തിലേക്ക് ഇറങ്ങിവരും. നിന്നെ ഞാൻ ഉത്തരോത്തരം ഉയർത്തും. ജോസഫ് നിന്റെ കണ്ണുകളിൽ തന്റെ കൈവെയ്ക്കും.","p":1},{"v":5,"t":"ബേർഷെബായിൽനിന്ന് യാക്കോബ് എഴുന്നേറ്റു. ഇസ്രായേലിന്റെ മക്കൾ തങ്ങളുടെ പിതാവായ യാക്കോബിനെയും കുഞ്ഞുങ്ങളെയും ഭാര്യമാരെയും അദ്ദേഹത്തെ കൊണ്ടുവരാൻ ഫറവോ കൊടുത്തയച്ചിരുന്ന വാഹനങ്ങളിൽ കയറ്റി.","p":1},{"v":6,"t":"തങ്ങളുടെ കന്നുകാലികളും കാനാൻനാട്ടിൽ തങ്ങൾ സമ്പാദിച്ച വസ്തുവകകളും അവർ കൂടെയെടുത്തു. യാക്കോബും അദ്ദേഹത്തോടൊപ്പം അദ്ദേഹത്തിന്റെ ഓരോ സന്തതിയും ഈജിപ്തിലേക്കു പോയി.","p":1},{"v":7,"t":"സ്വപുത്രന്മാരെയും തന്നോടൊപ്പമുള്ള പുത്രന്മാരുടെ പുത്രന്മാരെയും സ്വപുത്രിമാരെയും പുത്രന്മാരുടെ പുത്രിമാരെയും അങ്ങനെ തന്റെ ഓരോ സന്തതിയെയും അദ്ദേഹം തന്നോടൊപ്പം ഈജിപ്തിലേക്കു കൊണ്ടുപോയി.","p":1},{"v":8,"t":"ഈജിപ്തിലേക്കു പോയ ഇസ്രായേല്യരുടെ അതായത്, യാക്കോബിന്റെയും അവന്റെ മക്കളുടെയും പേരുകൾ ഇവയാണ്: യാക്കോബിന്റെ ആദ്യജാതൻ റൂബൻ.","p":1},{"v":9,"t":"റൂബന്റെ പുത്രന്മാർ: ഹനോക്ക്, പല്ലു, ഹെസ്രോൻ, കർമി എന്നിവർ.","p":1},{"v":10,"t":"ശിമയോന്റെ പുത്രന്മാർ: യെമുവേൽ, യാമീൻ, ഓഹദ്, യാക്കീൻ, സോഹാർ, കാനാൻകാരിയുടെ മകൻ സാവൂൾ.","p":1},{"v":11,"t":"ലേവിയുടെ പുത്രന്മാർ: ഗർഷോൻ, കോഹാത്ത്, മെറാറി.","p":1},{"v":12,"t":"യൂദായുടെ പുത്രന്മാർ: ഏർ, ഓനാൻ, ഷേലാഫ്, പേരെസ്, സേറഹ്. ഏറും ഓനാനും കാനാൻദേശത്തുവെച്ചു മരിച്ചിരുന്നു. പേരെസിന്റെ പുത്രന്മാരായിരുന്നു ഹെസ്രോൻ, ഹാമുൽ എന്നിവർ.","p":1},{"v":13,"t":"ഇസ്സാക്കറിന്റെ പുത്രന്മാർ: തോലാ, ഫുവ്വാ, യോബ്, ഷിമ്രോൻ.","p":1},{"v":14,"t":"സെബുലൂണിന്റെ പുത്രന്മാർ: സേരെദ്, ഏലോൻ, യാഹ്ലേൽ.","p":1},{"v":15,"t":"ഇവരും ദീനാ എന്ന യാക്കോബിന്റെ പുത്രിയും പാദാൻആരാമിൽവെച്ച് ലെയാ പ്രസവിച്ച, അവന്റെ മക്കളാണ്. അവന്റെ പുത്രന്മാരും അവന്റെ പുത്രിമാരും ആകെ മുപ്പത്തിമൂന്ന് ആളുകൾ.","p":1},{"v":16,"t":"ഗാദിന്റെ പുത്രന്മാർ: സിഫ്യോൻ, ഹഗ്ഗി, ഷൂനി, എസ്ബോൻ, ഏരി, അരോഡി, അരേലി.","p":1},{"v":17,"t":"ആഷേരിന്റെ പുത്രന്മാർ: ഇമ്നാ, ഇഷ്വാ, ഇഷ്വി, ബെറിയാ; അവരുടെ സഹോദരി സേറഹ്. ബെറിയായുടെ പുത്രന്മാർ: ഹേബെർ, മൽക്കീയേൽ.","p":1},{"v":18,"t":"ലാബാൻ തന്റെ മകളായ ലെയായ്ക്കു പരിചാരികയായിക്കൊടുത്ത സിൽഫായുടെ മക്കളാണിവർ. അവൾ യാക്കോബിനുവേണ്ടി ഈ പതിനാറുപേരെ പ്രസവിച്ചു.","p":1},{"v":19,"t":"യാക്കോബിന്റെ ഭാര്യയായ റാഹേലിന്റെ മക്കളാണ് ജോസഫും ബെഞ്ചമിനും.","p":1},{"v":20,"t":"ഓനിലെ പുരോഹിതനായ പൊത്തിഫെറായുടെ പുത്രി അസ്നത്ത് ജോസഫിനുവേണ്ടി ഈജിപ്തിൽവെച്ച് മനാസ്സെ, എഫ്രായിം എന്നിവരെ പ്രസവിച്ചു.","p":1},{"v":21,"t":"ബെഞ്ചമിന്റെ പുത്രന്മാർ: ബെലാ, ബെക്കെർ, അഷ്ബേൽ, ഗേരാ, നാമാൻ, ഏഹി, റോഷ്, മുപ്പീം, ഹുപ്പീം, ആർദ്ദ്.","p":1},{"v":22,"t":"ഇവർ യാക്കോബിന് റാഹേലിൽ ജനിച്ച മക്കളാണ് - ആകെ പതിനാലുപേർ.","p":1},{"v":23,"t":"ദാനിന്റെ മക്കളാണ് ഹുഷ്യർ","p":1},{"v":24,"t":"നഫ്ത്താലിയുടെ പുത്രന്മാർ: യഹ്സേൽ, ഗൂനി, യേസെർ, ഷില്ലേം.","p":1},{"v":25,"t":"ലാബാൻ തന്റെ മകളായ റാഹേലിനു പരിചാരികയായി കൊടുത്ത ബിൽഹായുടെ പുത്രന്മാരാണിവർ. യാക്കോബിനുവേണ്ടി അവൾ ഇവരെ പ്രസവിച്ചു; ആകെ ഏഴുപേർ.","p":1},{"v":26,"t":"പുത്രന്മാരുടെ ഭാര്യമാരെക്കൂടാതെ, യാക്കോബിനോടൊപ്പം ഈജിപ്തിലേക്ക് തിരിച്ച, യാക്കോബിൽനിന്നുതന്നെ ഉടലെടുത്ത മക്കൾ ആകെ അറുപത്താറുപേരാണ്.","p":1},{"v":27,"t":"ജോസഫിന്റെ പുത്രന്മാർ: ഈജിപ്തിൽ അവനു ജനിച്ച രണ്ടുപേർ. അങ്ങനെ ഈജിപ്തിലേക്കു വന്ന, യാക്കോബിന്റെ കുടുംബത്തിൽപ്പെട്ട ആകെയാളുകൾ എഴുപതുപേരാണ്.","p":1},{"v":28,"t":"തനിക്കുമുമ്പേ ഗോഷെനിലേക്ക് നയിക്കുന്നതിനുവേണ്ടി അദ്ദേഹം ജോസഫിന്റെ പക്കലേക്ക് മുൻകൂറായി യൂദായെ അയച്ചു. അവർ ഗോഷെൻ പ്രദേശത്തേക്കു വന്നു.","p":1},{"v":29,"t":"ജോസഫ് തന്റെ രഥമൊരുക്കി തന്റെ പിതാവായ ഇസ്രായേലിനെ എതിരേല്ക്കാനായി ഗോഷെനിലേക്കു ചെന്നു. അവൻ അദ്ദേഹത്തിന്റെ അടുത്തെത്തി ആശ്ലേഷിച്ചു; അദ്ദേഹത്തിന്റെ തോളിൽ അവൻ തുടരേ കണ്ണീരൊഴുക്കി.","p":1},{"v":30,"t":"ഇസ്രായേൽ ജോസഫിനോടു പറഞ്ഞു: ഒടുവിൽ നിന്റെ മുഖം ഞാൻ കണ്ടുകഴിഞ്ഞിരിക്കെ, ഞാൻ മരിച്ചുകൊള്ളട്ടെ! നീ ഇനിയും ജീവനോടിരിക്കുന്നുവല്ലോ.","p":1},{"v":31,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരോടും തന്റെ പിതൃകുടുംബത്തോടുമായി പറഞ്ഞു: ഞാൻ പോയി ഫറവോയോടു വിവരിക്കട്ടെ. അദ്ദേഹത്തോട് ഞാൻ പറയാം: കാനാൻദേശത്തായിരുന്ന എന്റെ സഹോദരന്മാരും പിതൃകുടുംബംമുഴുവനും എന്റെയടുത്തു വന്നിട്ടുണ്ട്.","p":1},{"v":32,"t":"ഈ ആളുകൾ മൃഗങ്ങളെ മേയ്ക്കുന്നവരാണ്; അതായത്, കന്നുകാലിവളർത്തുകാരാണ്. അവരുടെ ആടുമാടുകളും അവർക്കുള്ളതൊക്കെയും അവർ കൊണ്ടുവന്നിട്ടുണ്ട്.","p":1},{"v":33,"t":"അപ്പോൾ, ഫറവോ നിങ്ങളെ വിളിച്ച് നിങ്ങളുടെ തൊഴിലുകൾ എന്തൊക്കെയാണെന്നു ചോദിക്കുമ്പോൾ","p":1},{"v":34,"t":"നിങ്ങൾ പറയണം: അങ്ങയുടെ ദാസന്മാർ, ഞങ്ങളെപ്പോലെതന്നെ ഞങ്ങളുടെ പൂർവികരും, ഞങ്ങളുടെ ചെറുപ്പംമുതൽ ഇതുവരെ കന്നുകാലിവളർത്തുകാരാണ്. അങ്ങനെയെങ്കിലേ നിങ്ങൾക്ക് ഗോഷെൻനാട്ടിൽ പാർക്കാനൊക്കു. കാരണം ആളിക്കുന്ന എല്ലാവരും ഈജിപ്തുകാർക്ക് മ്ലേച്ഛരാണ്.","p":1}],"47":[{"h":"ഫറവോയുടെ മുമ്പിൽ"},{"v":1,"t":"ജോസഫ് ചെന്ന് ഫറവോയോട് വിവരിച്ചു: എന്റെ പിതാവും സഹോദരന്മാരും അവരുടെ ആടുമാടുകളും അവർക്കുള്ള സകലതും കാനാൻദേശത്തുനിന്ന് എത്തിച്ചേർന്നിരിക്കുന്നു. അവരിതാ, ഗോഷെൻദേശത്തുണ്ട്.","p":1},{"v":2,"t":"അവൻ തന്റെ സഹോദരന്മാർക്കിടയിൽനിന്ന് അഞ്ചുപേരെ തിരഞ്ഞെടുത്ത് അവരെ ഫറവോയുടെമുമ്പിൽ കൊണ്ടുചെന്നു.","p":1},{"v":3,"t":"അവന്റെ സഹോദരന്മാരോടു ഫറവോ ചോദിച്ചു: നിങ്ങളുടെ തൊഴിലുകൾ എന്തൊക്കെയാണ്? അവർ ഫറവോയോടു പറഞ്ഞു: അങ്ങയുടെ ദാസർ, ഞങ്ങളെപ്പോലെതന്നെ ഞങ്ങളുടെ പൂർവികരും, മൃഗങ്ങളെ മേയ്ക്കുന്നവരാണ്.","p":1},{"v":4,"t":"തുടർന്ന് അവർ പറഞ്ഞു: ഇവിടെ തത്കാലവാസത്തിനാണ് ഞങ്ങൾ വന്നിരിക്കുന്നത്. എന്തെന്നാൽ, കാനാൻദേശത്തു ക്ഷാമം രൂക്ഷമായതുകൊണ്ട് അങ്ങയുടെ ദാസരുടെ കാലിക്കൂട്ടത്തിന് തീറ്റയില്ലാതായിരിക്കുന്നു. അതുകൊണ്ട്, ഇപ്പോൾ അങ്ങയുടെ ദാസർ ഗോഷെൻദേശത്തു കുടിപാർക്കാൻ ദയചെയ്യണമേ!","p":1},{"v":5,"t":"അപ്പോൾ ഫറവോ ജോസഫിനോട് ഇപ്രകാരം പറഞ്ഞു: നിന്റെ പിതാവും നിന്റെ സഹോദരന്മാരും നിന്റെയടുത്തേക്കു വന്നിരിക്കുകയാണല്ലോ.","p":1},{"v":6,"t":"ഈജിപ്തുനാടു നിനക്കുമുമ്പിലുണ്ട്. നാടിന്റെ മെച്ചപ്പെട്ട ഭാഗത്ത് നിന്റെ പിതാവിനെയും നിന്റെ സഹോദരന്മാരെയും പാർപ്പിക്കുക. അവർ ഗോഷെൻദേശത്തു താമസിക്കട്ടെ. അവരിൽ കാര്യശേഷിയുള്ളവരുണ്ടെന്നു നിനക്കറിയാമെങ്കിൽ അവരെ എന്റെ കന്നുകാലിക്കൂട്ടത്തിന്റെ മേലാളന്മാരായി നിയോഗിക്കുക.","p":1},{"v":7,"t":"അതിനുശേഷം ജോസഫ് തന്റെ പിതാവായ യാക്കോബിനെ വരുത്തി ഫറവോയുടെ മുമ്പിൽ നിർത്തി. യാക്കോബ് ഫറവോയെ അനുഗ്രഹിച്ചു.","p":1},{"v":8,"t":"താങ്കളുടെ ആയുഷ്കാലസംവത്സരങ്ങൾ എത്രയാണ്? ഫറവോ യാക്കോബിനോടു ചോദിച്ചു.","p":1},{"v":9,"t":"എന്റെ ദേശാന്തരവാസകാലം നൂറ്റിമുപ്പതു വർഷമാണ്. ഹ്രസ്വമെങ്കിലും ദുരിതപൂർണമായിരുന്നു എന്റെ ആയുഷ്കാലസംവത്സരങ്ങൾ. എന്നാൽ, എന്റെ പിതാക്കന്മാരുടെ ദേശാന്തരവാസകാലത്തിലെ അവരുടെ ആയുഷ്കാലസംവത്സരങ്ങളെ അവ മറികടന്നിട്ടില്ല.","p":1},{"v":10,"t":"ഫറവോയെ അനുഗ്രഹിച്ചശേഷം യാക്കോബ് ഫറവോയുടെ സന്നിധിയിൽനിന്ന് പോയി.","p":1},{"v":11,"t":"ഫറവോ കൽപ്പിച്ചപോലെ, ഈജിപ്തുനാട്ടിലെ മെച്ചപ്പെട്ട ഒരു പ്രദേശം റംസേസ്നാട്ടിൽ അവകാശമായി നൽകി, ജോസഫ് തന്റെ പിതാവിനെയും സഹോദരന്മാരെയും അധിവസിപ്പിച്ചു.","p":1},{"v":12,"t":"ജോസഫ് തന്റെ പിതാവിനും സഹോദരന്മാർക്കും തന്റെ പിതൃഭവനം മുഴുവനും, ആശ്രിതരുടെ എണ്ണമനുസരിച്ച്, ആഹാരം കൊടുത്തുപോന്നു.","p":1},{"h":"ക്ഷാമം രൂക്ഷമാകുന്നു"},{"v":13,"t":"ക്ഷാമം ഏറെ രൂക്ഷമായിരുന്നതിനാൽ നാട്ടിലെങ്ങും ആഹാരമില്ലാതായി. ഈജിപ്തുദേശവും കാനാൻദേശവും ക്ഷാമംമൂലം വലഞ്ഞു.","p":1},{"v":14,"t":"ഈജിപ്തുദേശത്തും കാനാൻദേശത്തും ലഭ്യമായ പണമുഴുവൻ അവർ വാങ്ങിയ ധാന്യത്തിനു വിലയായി ജോസഫ് ശേഖരിച്ചു. ആ പണം അവൻ ഫറവോയുടെ ഭവനത്തിലേക്കു മുതൽകൂട്ടി.","p":1},{"v":15,"t":"ഈജിപ്തുദേശത്തും കാനാൻദേശത്തുമുള്ള പണം തീർന്നപ്പോൾ ഈജിപ്തുകാരെല്ലാം ജോസഫിന്റെയടുത്തു വന്നു പറഞ്ഞു: ഞങ്ങൾക്ക് ആഹാരം തരുക. പണം തീർന്നെന്ന കാരണത്താൽ ഞങ്ങൾ എന്തിന് അങ്ങയുടെമുമ്പിൽ മരിക്കണം?","p":1},{"v":16,"t":"ജോസഫ് പറഞ്ഞു: പണം തീർന്നെങ്കിൽ നിങ്ങളുടെ കന്നുകാലികളെ തരുവിൻ; നിങ്ങളുടെ കന്നുകാലികൾക്കു വിലയായി ഞാൻ നിങ്ങൾക്ക് അതു തരാം.","p":1},{"v":17,"t":"തങ്ങളുടെ കന്നുകാലികളെ അവർ ജോസഫിന്റെയടുത്തു കൊണ്ടുവന്നു. കുതിരകൾക്കും ആട്ടിൻപറ്റത്തിനും കന്നുകാലിക്കൂട്ടത്തിനും കഴുതകൾക്കും വിലയായി ജോസഫ് അവർക്ക് ആഹാരം കൊടുത്തു. അവൻ അവരുടെ കന്നുകാലികൾക്കെല്ലാം വിലയായി അവർക്ക് ആ വർഷത്തേക്ക് ആഹാരം വിതരണംചെയ്തു.","p":1},{"v":18,"t":"ആ വർഷം അവസാനിച്ച് രണ്ടാം വർഷം അവർ അവന്റെയടുത്തുചെന്ന് അവനോടു പറഞ്ഞു: പണം തീർന്ന കാര്യം യജമാനനിൽനിന്നു ഞങ്ങൾ മറച്ചുവെക്കുന്നില്ല. മൃഗസമ്പത്ത് യജമാനന്റേതായി; യജമാനസമക്ഷം ഞങ്ങളുടെ ദേഹവും നിലവുമല്ലാതെ ഞങ്ങൾക്കിനി ഒന്നും അവശേഷിക്കുന്നില്ല.","p":1},{"v":19,"t":"ഞങ്ങളെന്തിനു മരിക്കണം? ഞങ്ങളും ഞങ്ങളുടെ നിലവും അങ്ങയുടെ കൺമുമ്പിലുണ്ട്. ആഹാരത്തിനു വിലയായി ഞങ്ങളുടെ നിലം വാങ്ങിയാലും! ഞങ്ങളും ഞങ്ങളുടെ നിലവും ഫറവോയ്ക്ക് അടിമകളായിരിക്കും. ഞങ്ങൾ മരിക്കാതെ ജീവിച്ചുപോകാനും നിലം തരിശാകാതിരിക്കാനുംവേണ്ടി വിത്തു തന്നാലും.","p":1},{"v":20,"t":"അങ്ങനെ ജോസഫ് ഈജിപ്തുകാരുടെ നിലമുഴുവൻ ഫറവോയ്ക്കുവേണ്ടി വാങ്ങി. എന്തെന്നാൽ, ക്ഷാമം തങ്ങളുടെമേൽ ശക്തിപ്രാപിച്ചപ്പോൾ ഈജിപ്തുകാരെല്ലാവരും തങ്ങളുടെ വയൽ വിറ്റു; അങ്ങനെ നാട് ഫറവോയുടേതായി.","p":1},{"v":21,"t":"ജനത്തെയ ആകട്ടെ, ഈജിപ്തിന്റെ അതിർത്തിയുടെ ഒരറ്റംമുതൽ മറ്റേയറ്റംവരെ","p":1},{"v":21,"t":"അവൻ പട്ടണങ്ങളിലേക്ക് ഒഴിപ്പിച്ചു.","p":1},{"v":22,"t":"പുരോഹിതന്മാർക്കായി ഒരു വിഹിതം ഫറവോയിൽനിന്ന് ഉണ്ടായിരുന്നതിനാൽ, പുരോഹിതന്മാരുടെ നിലം മാത്രം അവൻ വാങ്ങിയില്ല. അവരാകട്ടെ, ഫറവോ അവർക്കു നൽകിയിരുന്ന അവരുടെ വിഹിതം ഭക്ഷിച്ചുപോന്നു. അതിനാൽ, അവർ തങ്ങളുടെ നിലം വിറ്റില്ല.","p":1},{"v":23,"t":"ജോസഫ് ജനങ്ങളോടു പറഞ്ഞു: നോക്കൂ, ഇന്ന് ഞാൻ നിങ്ങളെയും നിങ്ങളുടെ നിലവും ഫറവോയ്ക്കായി വാങ്ങിയിരിക്കുന്നു. ഇതാ, നിങ്ങൾക്കുള്ള വിത്ത്; നിങ്ങൾക്ക് നിലംവിതയ്ക്കാം.","p":1},{"v":24,"t":"വിളവുണ്ടാകുമ്പോൾ അഞ്ചിലൊന്ന് നിങ്ങൾ ഫറവോയ്ക്കു കൊടുക്കണം. നാലുഭാഗം നിങ്ങൾക്ക് വയൽവിത്തിനും നിങ്ങളുടെ ഭക്ഷണത്തിനുമാണ്, നിങ്ങളുടെ വീട്ടിലുള്ളവരുടെയും നിങ്ങളുടെ കുഞ്ഞുങ്ങളുടെയും ഭക്ഷണത്തിനുവേണ്ടിയുള്ളത്.","p":1},{"v":25,"t":"അവർ പറഞ്ഞു: അങ്ങ് ഞങ്ങളുടെ ജീവൻ കാത്തു. ഞങ്ങൾ യജമാനന്റെ ദൃഷ്ടികളിൽ പ്രീതി കണ്ടെത്തട്ടെ. ഞങ്ങൾ ഫറവോയ്ക്ക് അടിമകളായിരിക്കും.","p":1},{"v":26,"t":"അങ്ങനെ ജോസഫ് ഈജിപ്തിലെ നിലം സംബന്ധിച്ച് ഇന്നും പ്രാബല്യത്തിലുള്ള, അഞ്ചിലൊന്നു ഫറവോയ്ക്ക് എന്നൊരു നിയമം നടപ്പാക്കി. പുരോഹിതന്മാരുടെ നിലംമാത്രം അവരുടേതുമാത്രമായി; അത് ഫറവോയുടേതായില്ല.","p":1},{"h":"യാക്കോബിന്റെ അന്ത്യാഭിലാഷം"},{"v":27,"t":"ഇസ്രായേൽ ഈജിപ്തുനാട്ടിലെ ഗോഷെൻദേശത്തു പാർത്തു; അവർ അതിൽ അവകാശം സ്ഥാപിച്ചു; ഏറെ പെറ്റുപെരുകുകയും ചെയ്തു.","p":1},{"v":28,"t":"യാക്കോബ് ഈജിപ്തുനാട്ടിൽ പതിനേഴു വർഷം ജീവിച്ചു; യാക്കോബിന്റെ ആയുഷ്കാലം നൂറ്റിനാൽപ്പത്തേഴു വർഷമായിരുന്നു.","p":1},{"v":29,"t":"ഇസ്രായേലിന്റെ മരണത്തിനുള്ള ദിവസങ്ങളടുത്തപ്പോൾ, അദ്ദേഹം തന്റെ മകൻ ജോസഫിനെ വിളിച്ച് അവനോടു പറഞ്ഞു: ഞാൻ നിന്റെ ദൃഷ്ടികളിൽ പ്രീതികണ്ടെത്തിയെങ്കിൽ നിന്റെ കൈ എന്റെ തുടയുടെ കീഴിൽ വച്ചാലും. എന്നോടു കരുണയോടെയും വിശ്വസ്തതയോടെയും പ്രവർത്തിക്കണം. ദയചെയ്ത് എന്നെ ഈജിപ്തിൽ സംസ്കരിക്കരുത്.","p":1},{"v":30,"t":"ഞാൻ എന്റെ പിതാക്കന്മാരോടൊപ്പം കിടക്കുമ്പോൾ എന്നെ ഈജിപ്തിൽനിന്നു സംവഹിച്ച് അവരുടെ കുഴിമാടത്തിൽ സംസ്കരിക്കണം. അവൻ പറഞ്ഞു: അങ്ങയുടെ വാക്കുപോലെ ഞാൻ ചെയ്തുകൊള്ളാം.","p":1},{"v":31,"t":"എന്നോടു ശപഥംചെയ്യുക, അദ്ദേഹം പറഞ്ഞു; അവൻ അദ്ദേഹത്തോട് ശപഥം ചെയ്തു. അപ്പോൾ ഇസ്രായേൽ കട്ടിൽതലയ്ക്കൽ കുമ്പിട്ടു.","p":1}],"48":[{"h":"എഫ്രായിമിനും മനാസ്സെയ്ക്കും അനുഗ്രഹം"},{"v":1,"t":"ഈകാര്യങ്ങൾക്കുശേഷം ജോസഫിനോട് ഒരാൾ പറഞ്ഞു: ഇതാ, നിന്റെ പിതാവ് രോഗിയാണ്. അപ്പോൾ അവൻ തന്റെ രണ്ടു പുത്രന്മാരെ, മനാസ്സെയെയും എഫ്രായിമിനെയും, കൂടെക്കൊണ്ടുപോയി.","p":1},{"v":2,"t":"അവൻ യാക്കോബിനെ അറിയിച്ചുകൊണ്ട് പറഞ്ഞു: ഇതാ അങ്ങയുടെ മകനായ ജോസഫ് അങ്ങയുടെ അടുത്തേക്കു വരുന്നു. അപ്പോൾ ഇസ്രായേൽ ശക്തി സംഭരിച്ച് കിടക്കയിൽ എഴുന്നേറ്റിരുന്നു.","p":1},{"v":3,"t":"യാക്കോബ് ജോസഫിനോടു പറഞ്ഞു: കാനാൻദേശത്തുള്ള ലൂസിൽവെച്ച് ഏൽ ഷദ്ദായ് എനിക്ക് പ്രത്യക്ഷപ്പെട്ട് എന്നെ അനുഗ്രഹിച്ചു.","p":1},{"v":4,"t":"അവിടന്ന് എന്നോട് അരുൾചെയ്തു ഇതാ, ഞാൻ നിന്നെ സന്താനപുഷ്ടിയുള്ളവനാക്കി വർധിപ്പിക്കും. നിന്നെ ഞാൻ ജനങ്ങളുടെ ഒരു സമൂഹമാക്കും. നിനക്കുശേഷം നിന്റെ സന്തതിക്കു നിത്യവകാശമായി ഈ നാട് ഞാൻ നൽകും.","p":1},{"v":5,"t":"ഞാൻ ഈജിപ്തിൽ നിന്റെ അടുത്തേത്തുന്നതിനുമുമ്പ് നിനക്ക് ഈജിപ്തുനാട്ടിൽ ജനിച്ച നിന്റെ പുത്രന്മാരിരുവരും, എഫ്രായിമും മനാസ്സെയും, ഇപ്പോൾ എന്റേതാണ്. റൂബനും ശിമെയോനും എന്നപോലെ അവർ എന്റേതായിരിക്കും.","p":1},{"v":6,"t":"അവർക്കുശേഷം നീ ജനിപ്പിക്കുന്ന നിന്റെ സന്താനങ്ങൾ നിന്റേതായിരിക്കും. അവർ തങ്ങളുടെ അവകാശത്തിൽ തങ്ങളുടെ സഹോദരന്മാരുടെ പേരിലായിരിക്കും അറിയപ്പെടുന്നത്.","p":1},{"v":7,"t":"ഞാൻ പദാനിൽനിന്നു പോരുമ്പോൾ വഴിക്ക് കാനാൻദേശത്തുവെച്ച്, എഫ്രാത്തായിലെത്താൻ ഒരു കിബ്റാ ദുരംകൂടി ഉണ്ടായിരുന്നപ്പോൾ, റാഹേൽ എൻ്റെമേൽ ചാഞ്ഞുമരിച്ചു, എഫ്രാത്തായിലേക്കുള്ള, അതായത് ബേത്ലെഹെമിലേക്കുള്ള വഴിയിൽ, ഞാൻ അവളെ സംസ്കരിച്ചു.","p":1},{"v":8,"t":"ജോസഫിന്റെ പുത്രന്മാരെ കണ്ടപ്പോൾ ഇസ്രായേൽ ചോദിച്ചു: ഇവർ ആരാണ്?","p":1},{"v":9,"t":"ജോസഫ് തന്റെ പിതാവിനോടു പറഞ്ഞു: ഇവിടെ വെച്ച് ദൈവം എനിക്ക് തന്ന എന്റെ മക്കളാണിവർ. അദ്ദേഹം പറഞ്ഞു: ഞാൻ അവരെ അനുഗ്രഹിക്കേണ്ടതിന് അവരെ എന്റെയടുക്കൽ കൊണ്ടുവന്നാലും.","p":1},{"v":10,"t":"പ്രായംകൊണ്ട് കണ്ണുകൾ മ","p":1},{"v":10,"t":"വീങ്ങിയിരുന്നതിനാൽ ഇസ്രായേലിനു കാണാൻ കഴിയുമായിരുന്നില്ല. അദ്ദേഹത്തിന്റെ അടുത്ത് അവൻ അവരെ കൊണ്ടചെന്നു. അദ്ദേഹം അവരെ കെട്ടിപ്പിടിച്ച് ചുംബിച്ചു.","p":1},{"v":11,"t":"ഇസ്രായേൽ ജോസഫിനോടു പറഞ്ഞു: നിന്റെ മുഖം കാണുമെന്നു ഞാൻ വിചാരിച്ചിരുന്നില്ല. എന്നാൽ ഇതാ, നിന്റെ സന്തതിയെക്കൂടി ദൈവം എന്നെ കാണിച്ചിരിക്കുന്നു!","p":1},{"v":12,"t":"അപ്പോൾ, ജോസഫ് അവരെ അദ്ദേഹത്തിന്റെ മുട്ടുകളിൽനിന്ന് മാറ്റിയിട്ട്, നിലംപറ്റെ തന്റെ മുഖം കുനിച്ചു.","p":1},{"v":13,"t":"പിന്നെ ജോസഫ് ഇരുവരെയും എഫ്രായിമിനെ തന്റെ വലത്തുകൈകൊണ്ട് ഇസ്രായേലിന്റെ ഇടത്തുകൈക്കുനേരെയും, മനാസ്സെയെ തന്റെ ഇടത്തുകൈകൊണ്ട് ഇസ്രായേലിന്റെ വലത്തുകൈക്കുനേരെയും നിർത്തി, അദ്ദേഹത്തിന്റെയടുത്തേക്കു കൊണ്ടുചെന്നു.","p":1},{"v":14,"t":"എന്നാൽ, ഇസ്രായേൽ തന്റെ കൈകൾപിണച്ച് വലതുകൈ എഫ്രായിമിന്റെ തലയിലും ഇടതുകൈ മനാസ്സെയുടെ തലയിലുമാണ് വെച്ചത്. മനാസ്സെയായിരുന്നല്ലോ കടിഞ്ഞൂൽ പുത്രൻ.","p":1},{"v":15,"t":"അവൻ ജോസഫിനെ അനുഗ്രഹിച്ചുകൊണ്ട് പറഞ്ഞു: എന്റെ പിതാക്കന്മാരായ അബ്രഹാമും ഇസഹാക്കും ഏതു ദൈവത്തിന്റെമുമ്പിൽ വ്യാപരിച്ചിരുന്നവോ അവിടന്ന്, എന്റെ ആരംഭംമുതൽ ഇന്നുവരെ എന്നെ മേയിച്ചിരുന്ന ദൈവം,","p":1},{"v":16,"t":"തിന്മയായ എല്ലാറ്റിൽനിന്നും എന്നെ വീണ്ടെടുത്ത ദൂതൻ ഈ ബാലന്മാരെ അനുഗ്രഹിക്കട്ടെ! എന്റെ നാമവും എന്റെ പിതാക്കന്മാരായ അബ്രഹാത്തിന്റെയും ഇസഹാക്കിന്റെയും നാമവും അവയിലൂടെ വിളിക്കപ്പെടട്ടെ! അവർ ഭൂമധ്യേ പുരുഷാരമായി നിറയട്ടെ!","p":1},{"v":17,"t":"തന്റെ പിതാവ് തന്റെ വലതുകൈ എഫ്രായിമിന്റെ തലയിൽ വെച്ചിരിക്കുന്നത് ജോസഫ് കണ്ടു; അവന്റെ ദൃഷ്ടികളിൽ അത് അനിഷ്ടകരമായി. എഫ്രായിമിന്റെ തലയിൽനിന്ന് മനാസ്സെയുടെ തലയിലേക്ക് അതു മാറ്റാൻ അവൻ പിതാവിന്റെ കൈയിൽ കടന്നുപിടിച്ചു.","p":1},{"v":18,"t":"ജോസഫ് തന്റെ പിതാവിനോടു പറഞ്ഞു: എന്റെ പിതാവേ, അങ്ങനെയല്ല, ഇവാനാണല്ലോ ആദ്യജാതൻ. അങ്ങയുടെ വലതുകൈ ഇവന്റെ തലയിൽ വെക്കണേ.","p":1},{"v":19,"t":"അവന്റെ പിതാവ് നിരസിച്ചുകൊണ്ട് പറഞ്ഞു: എനിക്കറിയാം, എന്റെ മകനേ, എനിക്കറിയാം. അവനും ഒരു ജനമായിതീരും; അവനും വലിയവനാകും. എന്നാൽ അവന്റെ ഇളയ സഹോദരൻ അവനെക്കാൾ വലിയവനാകും; അവന്റെ സന്തതിയാകട്ടെ, ജനങ്ങളുടെ മഹാഗണവും.","p":1},{"v":20,"t":"അവരെ അനുഗ്രഹിച്ചുകൊണ്ട് ആ ദിവസം അദ്ദേഹം പറഞ്ഞു: നിന്നെക്കൊണ്ട് ഇസ്രായേൽ ഇപ്രകാരം അനുഗ്രഹിക്കും: ദൈവം നിന്നെ എഫ്രായിമിനെയുംപോലെയും മനാസ്സെയെപ്പോലെയും സുസ്ഥാപിതമാക്കട്ടെ! അദ്ദേഹം എഫ്രായിമിനെ മനാസ്സെയ്ക്കു മുമ്പനാക്കി.","p":1},{"v":21,"t":"അതു കഴിഞ്ഞ്, ഇസ്രായേൽ ജോസഫിനോടു പറഞ്ഞു: ഞാൻ ഇതാ, മരിക്കാറായി. ദൈവം നിങ്ങളുടെ കൂടെയുണ്ടാകും. അവിടന്ന് നിങ്ങളെ നിങ്ങളുടെ പിതാക്കന്മാരുടെ നാട്ടിലേക്ക് തിരിയെ കൊണ്ടുചെന്നാക്കും.","p":1},{"v":22,"t":"എന്റെ വാളും വില്ലുംകൊണ്ട് അമോര്യരുടെ കയ്യിൽനിന്ന് പിടിച്ചെടക്കിയ ഷെക്കെം, നിന്റെ സഹോദരന്മാർക്കുള്ളതിനേക്കാൾ ഒന്നുകൂടുതലായി, നിനക്കു ഞാൻ തരുന്നു.","p":1}],"49":[{"h":"യാക്കോബിന്റെ അനുഗ്രഹം"},{"v":1,"t":"യാക്കോബ് തന്റെ മക്കളെ വിളിച്ച് പറഞ്ഞു: ഒന്നിച്ചുകൂടുവിൻ. വരുംകാലങ്ങളിൽ നിങ്ങൾക്ക് എന്തു സംഭവിക്കുമെന്ന് ഞാൻ നിങ്ങളോട് വിശദീകരിക്കാം.","p":1},{"v":2,"t":"യാക്കോബിന്റെ പുത്രന്മാരേ, ഒന്നിച്ചുകൂടി കേൾക്കുവിൻ. നിങ്ങളുടെ പിതാവായ ഇസ്രായേലിനെ ശ്രദ്ധിക്കുവിൻ.","p":1},{"v":3,"t":"റൂബൻ, നീ എന്റെ ആദ്യജാതനാണ്; എന്റെ ശക്തിയും എന്റെ പൗരുഷത്തിന്റെ ആരംഭവും; പ്രാഗല്ഭ്യത്തിന്റെ മഹത്വവും ശക്തിയുടെ മഹത്വവും.","p":1},{"v":4,"t":"വെള്ളംപോലെ അസ്ഥിരനായ നീ പ്രഥമസ്ഥാനീയനാകില്ല. എന്തെന്നാൽ, നീ നിന്റെ പിതാവിന്റെ കിടക്കയിൽ കയറി - അതെ, എന്റെ ശയ്യ നീ അശുദ്ധമാക്കിയ കയറ്റം!","p":1},{"v":5,"t":"ശിമയോനും ലേവിയും സഹോദരന്മാരാണ്. അവരുടെ വാളുകൾ അക്രമത്തിന്റെ ആയുധങ്ങളാണ്.","p":1},{"v":6,"t":"അവരുടെ ഗൂഢാലോചനയിൽ എന്റെ ആത്മാവ് പങ്കുകൊള്ളാതിരിക്കട്ടെ അവരുടെ സമ്മേളനത്തിൽ എന്റെ മഹത്വം ചേരാതിരിക്കട്ടെ. എന്തെന്നാൽ, തങ്ങളുടെ കോപത്തിൽ അവർ മനുഷ്യനെ കൊന്നു. തങ്ങളുടെ സ്വാർഥസന്തോഷത്തിന് അവർ കാളകളുടെ കുതിഞരമ്പ് വെട്ടി.","p":1},{"v":7,"t":"ശക്തമായിരുന്നതുകൊണ്ട് അവരുടെ കോപവും ഉഗ്രമായിരുന്നതുകൊണ്ട് അവരുടെ ക്രോധവും ശപിക്കപ്പെടട്ടെ! ഞാൻ അവരെ യാക്കോബിൽ വീതംവെക്കും; ഇസ്രായേലിൽ ഞാൻവരെ ചിതറിക്കുകയും ചെയ്യും.","p":1},{"v":8,"t":"നീയോ യൂദാ, നിന്റെ സഹോദരന്മാർ നിന്നെ അംഗീകരിക്കും; നിന്റെ കൈ നിന്റെ ശത്രുക്കളുടെ പിടലിയിലായിരിക്കും. നിന്റെ പിതാവിന്റെ പുത്രന്മാർ നിന്നെ കുമ്പിടും.","p":1},{"v":9,"t":"യൂദാ ഒരു യുവസിംഹമാണ്. എന്റെ മകനേ, നീ ഇരയിൽനിന്ന് ഉയർന്നുവരുന്നു. അവൻ ഒരു സിംഹത്തെപ്പോലെയും സിംഹിയെപ്പോലെയും പതുങ്ങിവിശ്രമിക്കുന്നു. അവനെ ആര് ഉണർത്തും?","p":1},{"v":10,"t":"യൂദായിൽനിന്ന് ചെങ്കോൽ വിട്ടകലുകയില്ല; അധികാരദണ്ഡ് അവന്റെ പാദങ്ങൾക്കിടയിൽ നിന്നും. അവൻ ശീലോയിൽ വന്നുയെത്തുന്നതുവരെ ജനങ്ങളുടെ അനുസരണം അവനു സ്വന്തമായിരിക്കും.","p":1},{"v":11,"t":"അവൻ തന്റെ കഴുതയെ മുന്തിരിവള്ളിയിൽ കെട്ടിയിടും; തന്റെ കഴുതക്കുട്ടിയെ ദ്രാക്ഷാവള്ളിയിലും. അവൻ തന്റെ ഉടുപ്പ് മുന്തിരിച്ചാറിൽ കഴുകും; തന്റെ മേലങ്കി ദ്രാക്ഷാരസത്തിലും.","p":1},{"v":12,"t":"വീഞ്ഞിനെക്കാൾ തിളക്കമുള്ള കണ്ണിണ പാലിനെക്കാൾ വെളുത്ത ദംഷ്ട്രദ്വയം.","p":1},{"v":13,"t":"സെബുലൂണാകട്ടെ, കടൽത്തീരത്തു വസിക്കും; അവൻ കപ്പലുകൾക്കു തീരമായിരിക്കും; സീദോനുമേലും അവന്റെ അതിർത്തിയായിരിക്കും.","p":1},{"v":14,"t":"ഇസ്സാക്കർ എല്ലുള്ള ഒരു കഴുതയാണ്; അവൻ രണ്ട് ആലകങ്ങൾക്കിടയിൽ വിശ്രമിക്കുന്നു.","p":1},{"v":15,"t":"വിശ്രമസ്ഥലം നല്ലതെന്ന് അവൻ കണ്ടു, ദേശം മനോഹരമാണെന്നും. അതുകൊണ്ട് അവൻ ചുമടെടുക്കാൻ തന്റെ ചുമൽ കുനിച്ചു; കൂലിവേലചെയ്യുന്ന ഒരു കരാറുപണിക്കാരനായി.","p":1},{"v":16,"t":"ദാൻ സ്വജനത്തിനു ന്യായം നടത്തിക്കൊടുക്കും, ഇസ്രായേലിലെ ഗോത്രങ്ങളിലൊന്നിനെപ്പോലെ.","p":1},{"v":17,"t":"ദാൻ വഴിവക്കിൽ സർപ്പമായിരിക്കട്ടെ; പാതയോരത്ത് അണലിയും. അവൻ കുതിരയുടെ കുതികാലുകൾ കടിക്കും; കുതിരക്കാരൻ മലർന്നുവീഴുകയും ചെയ്യും.","p":1},{"v":18,"t":"കർത്താവേ, ഞാൻ അങ്ങയുടെ രക്ഷയ്ക്കായി കാത്തിരിക്കുന്നു.","p":1},{"v":19,"t":"ഗാദിനെപ്പറ്റി: കവർച്ചക്കാർ അവനെ കൊള്ളയടിക്കും; എന്നാൽ, അവൻ പതിയിരുന്ന് ആക്രമിക്കും.","p":1},{"v":20,"t":"ആശേറിനെപ്പറ്റി: അവന്റെ ആഹാരം സമൃദ്ധമായിരിക്കും; രാജാവിനുള്ള വിശിഷ്ടഭവനങ്ങൾ അവൻ പ്രദാനം ചെയ്യും.","p":1},{"v":21,"t":"നഫ്താലി സ്വച്ഛന്ദതയുള്ള ഒരു പേടമാനാണ്; അവൻ മൃദുലോകതികൽ പൊഴിക്കുന്നു.","p":1},{"v":22,"t":"ജോസഫ് ഒരു ഫലവൃക്ഷകുമാരനാണ്; നീരുറവയ്ക്കുമീതെയുള്ള ഫലവൃക്ഷകുമാരൻ; ശാഖാകുമാരികൾ മതിലിനുമീതെ പന്തലിക്കുന്നു.","p":1},{"v":23,"t":"വില്ലാളിവീരന്മാർ അമ്പെയ്ത് അവനെ തിക്തതയിലാഴ്ത്തി; അവർ അവനോടു ശത്രുത പുലർത്തി.","p":1},{"v":24,"t":"എന്നാൽ, അവന്റെ വില്ല് ഉറച്ചുനിന്നു; അവന്റെ കൈപ്പത്തികൾ അയവുള്ളതായി,","p":1},{"v":24,"t":"യാക്കോബിന്റെ ശക്തനായവന്റെ കൈകളിൽനിന്ന്, ഇസ്രായേലിന്റെ പാറയായ ഇടയൻ ഉള്ള ഇടത്തുനിന്ന്,","p":1},{"v":25,"t":"നിന്നെ സഹായിക്കുന്ന നിന്റെ പിതാവിന്റെ ദൈവത്തിൽനിന്ന്, നിന്നെ അനുഗ്രഹിക്കുന്ന സർവശക്തനോടൊത്ത് ഉന്നതത്തിൽനിന്ന് ആകാശങ്ങളുടെ അനുഗ്രഹങ്ങൾ, അഗാധത്തിൽ വിശ്രമിക്കുന്ന ആഴത്തിന്റെ അനുഗ്രഹങ്ങൾ, മാരിടത്തിന്റെയും ഉദരത്തിന്റെയും അനുഗ്രഹങ്ങൾ,","p":1},{"v":26,"t":"നിന്റെ പിതാവിന്റെ അനുഗ്രഹങ്ങൾ, എന്റെ പർവതങ്ങളുടെ അനുഗ്രഹങ്ങൾക്കുമേൽ നിത്യശ്യംഗങ്ങളുടെ സീമവരെ വളരുന്നു. അവ ജോസഫിന്റെ ശിരസ്സിൽ ആയിരിക്കട്ടെ! സ്വസഹോദരരുടെ നേതാവിന്റെ മൂർധാവിൽത്തന്നെ!"},{"v":27,"t":"ബെഞ്ചമിൻ ആർത്തിയുള്ള ഒരു ചെന്നായാണ്. അവൻ രാവിലെ കൊള്ളയടിക്കുകയും വൈകുന്നേരം കവർച്ചമുതൽ പങ്കിടുകയും ചെയ്യും.","p":1},{"v":28,"t":"ഇവരെല്ലാമാണ് ഇസ്രായേലിലെ പന്ത്രണ്ടു ഗോത്രങ്ങൾ. അവരുടെ പിതാവ് അവരോടു പറഞ്ഞതാണിത്; അദ്ദേഹം അവരെ പ്രത്യേകം പ്രത്യേകം അനുഗ്രഹിച്ചു, തന്റെ സംപ്രീതിക്കനുസൃതം അവരെ അനുഗ്രഹിച്ചു.","p":1},{"h":"യാക്കോബിന്റെ മരണവും സംസ്കാരവും"},{"v":29,"t":"അദ്ദേഹം അവരോടു കൽപ്പിച്ചരുളി: ഞാൻ എന്റെ ജനത്തോടു ചേരുകയാണ്. എന്റെ പിതാക്കന്മാരുടെ അടുത്ത്, ഹിത്യനായ എഫ്രോണിന്റെ പറമ്പിലുള്ള ഗുഹയിൽ, എന്നെ സംസ്കരിക്കണം;","p":1},{"v":30,"t":"കാനാൻദേശത്ത് മാമ്രേക്കു മുമ്പിലായി മക്പെലായുടെ പറമ്പിലുള്ള ആ ഗുഹയിൽതന്നെ. അബ്രഹാം കല്ലറയ്ക്കുള്ള അവകാശമായി ഹിത്യനായ എഫ്രോണിൽനിന്ന് വാങ്ങിയതാണ് ആ പറമ്പ്.","p":1},{"v":31,"t":"അബ്രഹാമും അദ്ദേഹത്തിന്റെ ഭാര്യ സാറായെയും അവിടെയാണ് അവർ അടക്കംചെയ്തത്. അവിടെതന്നെയാണ് ഇസഹാക്കിനെയും അദ്ദേഹത്തിന്റെ ഭാര്യ റബേക്കായെയും സംസ്കരിച്ചത്. ഞാൻ ലെയായെ സംസ്കരിച്ചതും അവിടെതന്നെ.","p":1},{"v":32,"t":"ആ പറമ്പിന്റെയും അതിലുള്ള ഗുഹയുടെയും കൈവശാവകാശം ഹിത്യരുടെപക്കൽ നിന്നുള്ളതാണ്.","p":1},{"v":33,"t":"തന്റെ പുത്രന്മാരോടു കൽപ്പിക്കാനുള്ളതു പൂർത്തിയാക്കി, യാക്കോബ് തന്റെ കാലുകൾ കിടക്കയോടു ചേർത്തു. അദ്ദേഹം അന്ത്യശ്വാസംവലിച്ച് തന്റെ ജനങ്ങളോടു ചേർന്നു.","p":1}],"50":[{"v":1,"t":"ജോസഫ് തന്റെ പിതാവിന്റെ മുഖത്തേക്കു വീണു; അദ്ദേഹത്തെ പ്രതി വിലപിക്കുകയും അദ്ദേഹത്തെ ചുംബിക്കുകയും ചെയ്തു.","p":1},{"v":2,"t":"ജോസഫ് തന്റെ ദാസന്മാരായ വൈദ്യന്മാരോട് തന്റെ പിതാവിനെ സുരഭീകരിക്കാൻ ആജ്ഞാപിച്ചു. വൈദ്യന്മാർ ഇസ്രായേലിനെ തൈലംപൂശി.","p":1},{"v":3,"t":"നാല്പതുദിവസംകൊണ്ട് അദ്ദേഹത്തിനു വേണ്ടി അവർ അതു പൂർത്തിയാക്കി. കാരണം, അങ്ങനെയാണ് അവർ സുരഭീകരണദിനങ്ങൾ പൂർത്തിയാക്കിയിരുന്നത്. ഈജിപ്തുകാർ എഴുപതു ദിവസം അദ്ദേഹത്തെപ്രതി വിലപിച്ചു.","p":1},{"v":4,"t":"അദ്ദേഹത്തിനുവേണ്ടിയുള്ള വിലാപദിനങ്ങൾ പിന്നിട്ടപ്പോൾ, ജോസഫ് ഫറവോയുടെ കുടുംബത്തോടു ഇപ്രകാരം പറഞ്ഞു: നിങ്ങളുടെ ദൃഷ്ടികളിൽ ഞാൻ സംപ്രീതി കണ്ടെത്തിയിട്ടുണ്ടെങ്കിൽ, ഫറവോയുടെ ചെവികളിൽ ഇപ്രകാരം ഉണർത്തിച്ചാലും:","p":1},{"v":5,"t":"എന്റെ പിതാവ് എന്നെക്കൊണ്ട് ഒരു പ്രതിജ്ഞ ചെയ്യിച്ചിരുന്നു. 'ഇതാ, ഞാൻ മരിക്കാറായി; എനിക്കുവേണ്ടി ഞാൻ കാനാൻദേശത്തു തയ്യാറാക്കിയിരിക്കുന്ന എന്റെ കല്ലറയിൽത്തന്നെ നീ എന്നെ സംസ്കരിക്കണം' എന്നാണ് അവൻ പറഞ്ഞത്.","p":1},{"v":6,"t":"അതുകൊണ്ട്, ഇപ്പോൾ 'ഞാൻ പോയി എന്റെ പിതാവിനെ സംസ്കരിച്ചു തിരിച്ചുവരട്ടെ'. ഫറവോ പറഞ്ഞു: അദ്ദേഹം നിന്നെക്കൊണ്ട് പ്രതിജ്ഞചെയ്യിച്ചതനുസരിച്ച് നീ പോയി നിന്റെ പിതാവിനെ സംസ്കരിക്കുക.","p":1},{"v":7,"t":"അങ്ങനെ ജോസഫ് തന്റെ പിതാവിനെ സംസ്കരിക്കാൻ പോയി. അവനോടൊപ്പം ഫറവോയുടെ എല്ലാ ദാസന്മാരും അവന്റെ വീട്ടിലെ കാരണവന്മാരും ഈജിപ്തുദേശത്തെ എല്ലാ മുതിർന്നവരും പോയി;","p":1},{"v":8,"t":"കൂടാതെ, ജോസഫിന്റെ കുടുംബം മുഴുവനും അവന്റെ സഹോദരന്മാരും അവന്റെ പിതാവിൻ്റെ കുടുംബവും തങ്ങളുടെ കുട്ടികളെയും ആടുമാടുകളെയും മാത്രമേ അവർ ഗോഷെൻ ദേശത്ത് നിർത്തിയുള്ളൂ","p":1},{"v":9,"t":"രഥവും കുതിരക്കാരും അവനോടൊപ്പം പോയി; അങ്ങനെ ആ വ്യൂഹം അതി സാന്ദ്രമായിരുന്നു","p":1},{"v":10,"t":"ജോർദാന് അക്കരെയുള്ള അത്താദിലെ മെതിക്കളംവരെ അവരെത്തി. അവിടെ അവർ വിപുലവും അതിതീവ്രവുമായ ഒരു ദുഖാചരണം നടത്തി. അവൻ ഏഴു ദിവസം തന്റെ പിതാനുവേണ്ടി വിലാപം അനുഷ്ഠിച്ചു.","p":1},{"v":11,"t":"അന്നാട്ടിൽ നിവസിച്ചിരുന്ന കാനാൻകാർ അത്താദിന്റെ മെതിക്കളത്തിൽ നടന്ന വിലാപം കണ്ടപ്പോൾ പറഞ്ഞു: ഇത് ഈജിപ്തുകാർക്ക് ഗൗരവമേറിയ ഒരു വിലാപംതന്നെ. അതുകൊണ്ട്, ജോർദ്ദാനക്കരയുള്ള ആബേൽ മിസ്രയിം എന്ന് അതിനെ പേരുവിളിക്കുന്നു.","p":1},{"v":12,"t":"എന്നിട്ട്, അദ്ദേഹത്തിന്റെ പുത്രന്മാർ, തങ്ങളോടു കൽപ്പിച്ചിരുന്നപോലെതന്നെ അദ്ദേഹത്തിനായി പ്രവർത്തിച്ചു.","p":1},{"v":13,"t":"അദ്ദേഹത്തിന്റെ പുത്രന്മാർ അദ്ദേഹത്തെ കാനാൻദേശത്തേക്കു സംവഹിച്ച് മക്പെലായുടെ പറമ്പിലെ ഗുഹയിൽ അവർ അദ്ദേഹത്തെ സംസ്കരിച്ചു. അബ്രഹാം മാമ്രേക്കു മുമ്പിലായി ഹിത്യനായ എഫ്രോണിൽനിന്ന് കല്ലറയ്ക്കുള്ള അവകാശമായി വാങ്ങിയതാണ് ആ പറമ്പ്.","p":1},{"v":14,"t":"തന്റെ പിതാവിനെ സംസ്കരിച്ചശേഷം ജോസഫ്, അവനും അവന്റെ സഹോദരന്മാരും അവന്റെ പിതാവിനെ സംസ്കരിക്കാനായി അവനോടുകൂടെ ഇറങ്ങിത്തിരിച്ച എല്ലാവരും, ഈജിപ്തിലേക്ക് മടങ്ങി.","p":1},{"h":"ജോസഫിന്റെ ഹൃദയവിശാലത"},{"v":15,"t":"തങ്ങളുടെ പിതാവ് മരിച്ചെന്നു കണ്ട് ജോസഫിന്റെ സഹോദരന്മാർ പറഞ്ഞു: ഇനി മിക്കവാറും ജോസഫ് നമ്മെ വെറുക്കുകയും നാം അവനോടു ചെയ്ത ദ്രോഹത്തിനെല്ലാം നമ്മോട് നിശ്ചയമായും പകരം വീട്ടുകയും ചെയ്യും.","p":1},{"v":16,"t":"അവർ ജോസഫിന് ഇപ്രകാരം ഒരു സന്ദേശം നൽകി: അങ്ങയുടെ പിതാവ് തന്റെ മരണത്തിനുമുമ്പ് ഇങ്ങനെ കൽപ്പിച്ചിരുന്നു:","p":1},{"v":17,"t":"ജോസഫിനോട് നിങ്ങൾ ഇപ്രകാരം പറയണം: ദയയുണ്ടാകണമെ! അങ്ങയുടെ സഹോദരന്മാരുടെ അതിക്രമവും പാപവും സന്ദയം ക്ഷമിക്കണമേ. എന്തെന്നാൽ, അവർ അങ്ങയോടു ദ്രോഹംചെയ്തു. എന്നാൽ, ഇപ്പോൾ അങ്ങയുടെ പിതാവിന്റെ ദൈവത്തിന്റെ ദാസന്മാരുടെ അതിക്രമം സദയം പൊറുക്കണമെ. തന്നോട് അവർ പറഞ്ഞതിനെപ്പറ്റി ജോസഫ് കരഞ്ഞുപോയി.","p":1},{"v":18,"t":"പിന്നീട് അവന്റെ സഹോദരന്മാർതന്നെവന്ന് അവന്റെ മുമ്പിൽ വീണു. അവർ പറഞ്ഞു: ഇതാ ഞങ്ങൾ അങ്ങേക്ക് അടിമകളാണ്.","p":1},{"v":19,"t":"ജോസഫ് അവരോടു പറഞ്ഞു: നിങ്ങൾ പേടിക്കേണ്ടയോ, ഞാനെന്താ ദൈവത്തിന്റെ സ്ഥാനത്താണോ?","p":1},{"v":20,"t":"നിങ്ങൾ എനിക്കെതിരെ തിന്മ വിഭാവനം ചെയ്തു. ദൈവമാകട്ടെ, അതു നന്മക്കായി പരിഗണിച്ചു. ഒരു വലിയ ജനത്തിന്റെ ഇന്നത്തെപോലുള്ള ജീവസന്ധാരണത്തിനുവേണ്ടിയാണ് അവിടുന്നു പ്രവർത്തിച്ചത്.","p":1},{"v":21,"t":"ആകയാൽ ഇപ്പോൾ നിങ്ങൾ ഭയപ്പെടേണ്ടാ, നിങ്ങളെയും നിങ്ങളുടെ കുഞ്ഞുങ്ങളെയും ഞാൻ പോറ്റിക്കൊള്ളാം. അങ്ങനെ, അവൻ അവരെ സാന്ത്വനപ്പെടുത്തുകയും അവരോടു ഹൃദ്യമായി സംസാരിക്കുകയും ചെയ്തു.","p":1},{"h":"ജോസഫിന്റെ മരണം"},{"v":22,"t":"ജോസഫ് അവന്റെ പിതാവിന്റെ കുടുംബത്തോടൊപ്പം ഈജിപ്തിൽ പാർത്തു. ജോസഫ് നൂറ്റിപ്പത്തു വർഷം ജീവിച്ചു. എഫ്രായിമിന്റെ മൂന്നാം തലമുറയിലെ മക്കളെ ജോസഫ് കണ്ടു. മനാസ്സെയുടെ മകനായ മാക്കിറിന്റെ കുഞ്ഞുങ്ങളും ജനിച്ചത് ജോസഫിന്റെ മുട്ടുകളിലാണ്.","p":1},{"v":23,"t":"ജോസഫ് തന്റെ സഹോദരന്മാരോടു പറഞ്ഞു: ഞാൻ മരിക്കുകയാണ്. എന്നാൽ, ദൈവം നിങ്ങളെ തീർച്ചയായും സന്ദർശിക്കും. അവിടുന്നു നിങ്ങളെ ഈ നാട്ടിൽനിന്ന് അബ്രഹാമിനോടും ഇസഹാക്കിനോടും യാക്കോബിനോടും വാഗ്ദാനംചെയ്ത നാട്ടിലേക്ക് കൊണ്ടുപോകും.","p":1},{"v":24,"t":"തുടർന്ന്, 'ദൈവം നിങ്ങളെ തീർച്ചയായും സന്ദർശിക്കും. അപ്പോൾ, നിങ്ങൾ എന്റെ അസ്ഥികൾ ഇവിടെന്നു കൊണ്ടുപോകണം' എന്നുപറഞ്ഞ് ജോസഫ് ഇസ്രായേലിന്റെ പുത്രന്മാരെക്കൊണ്ട് പ്രതിജ്ഞ ചെയ്യിച്ചു.","p":1},{"v":25,"t":"നൂറ്റിപ്പത്തുവർഷം പ്രായമായപ്പോൾ ജോസഫ് മരിച്ചു. അവർ അവനെ സുഗന്ധലേപനം ചെയ്ത്, ഒരു പേടകത്തിൽ ഈജിപ്തിൽ സൂക്ഷിച്ചു.","p":1}]}},{"id":"EXO","name":"പുറപ്പാട്","chapters":{"1":[{"h":"ഈജിപ്തിലെ അടിമത്തം"},{"v":1,"t":"ഇസ്രായേല്യരിലെ ഓരോരുത്തനും അവനവന്റെ കുടുംബവും യാക്കോബിനോടൊപ്പം ഈജിപ്തിലേക്കു വന്നു. അവരുടെ പേരുകൾ ഇവയാണ്:","p":1},{"v":2,"t":"റൂബൻ, ശിമയോൻ, ലേവി, യൂദാ;"},{"v":3,"t":"ഇസ്സാക്കർ, സെബുലൂൺ, ബെഞ്ചമിൻ;"},{"v":4,"t":"ദാൻ, നഫ്താലി; ഗാദ്, ആഷേർ."},{"v":5,"t":"യാക്കോബിൽനിന്നുതന്നെ ഉടലെടുത്ത ആളുകൾ ആകെ എഴുപതുപേരായിരുന്നു. ജോസഫാകട്ടെ, ഈജിപ്തിലായിരുന്നു."},{"v":6,"t":"ജോസഫും അവന്റെ എല്ലാ സഹോദരന്മാരും ആ തലമുറമുഴുവനും മരിച്ചു."},{"v":7,"t":"ഇസ്രായേല്യർ പെറ്റുപെരുകി; അവർ വർധിച്ചു വളരെയധികം ശക്തിപ്രാപിച്ചു. ദേശം അവരെക്കൊണ്ടു നിറഞ്ഞു."},{"v":8,"t":"ജോസഫിനെ അറിയാത്ത ഒരു പുതിയ രാജാവ് ഈജിപ്തിൽ ഉയർന്നുവന്നു.","p":1},{"v":9,"t":"അവൻ തന്റെ ജനത്തോടു പറഞ്ഞു: ഇതാ, ഇസ്രായേല്യജനം നമ്മെക്കാൾ വലുതും പ്രബലവുമാണ്."},{"v":10,"t":"വരു! അവൻ പെരുകാതിരിക്കാൻ നമുക്ക് അവനോടു കൗശലംപ്രയോഗിക്കാം. അല്ലെങ്കിൽ, ഒരു യുദ്ധം നേരിടേണ്ടിവന്നാൽ അവൻ നമ്മെ വെറുക്കുന്നവരോടുചേർന്ന് നമുക്കെതിരേ പൊരുതുകയും രാജ്യത്തുനിന്നു വിട്ടുപോവുകയും ചെയ്തേക്കാം."},{"v":11,"t":"തങ്ങളുടെ കഠിനജോലികൾകൊണ്ട് അവനെ ഞെരുക്കാൻ നിർബന്ധിതവേലകൾക്കുള്ള കങ്കാണിമാരെ അവർ അവന്റെമേൽ നിയമിച്ചു. അങ്ങനെ അവൻ ഫറവോയ്ക്കുവേണ്ടി പിത്തോം, റമ്സേസ് എന്നീ സംഭരണനഗരങ്ങൾ നിർമിച്ചു."},{"v":12,"t":"എന്നാൽ, അവർ അവനെ എത്രമാത്രം പീഡിപ്പിച്ചുവോ അത്രയ്ക്ക് അവൻ പെരുകുകയും അതനുസരിച്ച് അവൻ വ്യാപിക്കുകയും ചെയ്തു. ഇസ്രായേല്യർനിമിത്തം അവർ പരിഭ്രാന്തരായി."},{"v":13,"t":"ഈജിപ്തുകാർ ഇസ്രായേല്യരെ ദണ്ഡനംകൊണ്ട് അടിമവേല ചെയ്യിച്ചു."},{"v":14,"t":"കുമ്മായവും ഇഷ്ടികയും കൊണ്ടുള്ള കഠിനജോലികൊണ്ടും വയലിലെ ജോലിയെല്ലാംകൊണ്ടും അവരുടെ ജീവിതങ്ങൾ അവർ കയ്പുള്ളതാക്കി. അക്കൂട്ടരുടെയിടയിൽ അവർ ചെയ്ത ഓരോ അടിമവേലയും കാഠിന്യമുള്ളതായിരുന്നു."},{"v":15,"t":"ഈജിപ്തുരാജാവ് ഹെബ്രായസൂതികർമിണികളോടു സംസാരിച്ചു. അതിലൊരുവളുടെ പേര് ഷിഫ്റാ, രണ്ടാമത്തവളുടെ പേര് പൂവാ.","p":1},{"v":16,"t":"അവൻ പറഞ്ഞു: നിങ്ങൾ ഹെബ്രായസ്ത്രീകളുടെ പ്രസവമെടുക്കുമ്പോൾ ലിംഗവ്യത്യാസം ശ്രദ്ധിക്കണം. പുത്രനാണെങ്കിൽ അവനെ വധിക്കണം; പുത്രിയാണെങ്കിൽ അവൾ ജീവിച്ചുകൊള്ളട്ടെ."},{"v":17,"t":"എന്നാൽ, ആ സൂതികർമിണികൾ ദൈവത്തെ ഭയപ്പെട്ടിരുന്നതിനാൽ ഈജിപ്തുരാജാവ് അവരോടു പറഞ്ഞതുപോലെ ചെയ്തില്ല; അവർ ആൺകുഞ്ഞുങ്ങളെ ജീവിക്കാനനുവദിച്ചു."},{"v":18,"t":"ആകയാൽ, ഈജിപ്തുരാജാവ് സൂതികർമിണികളെ വിളിച്ച് അവരോടു ചോദിച്ചു: നിങ്ങൾ ഇക്കാര്യം ചെയ്ത് ആൺകുഞ്ഞുങ്ങളെ ജീവിക്കാനനുവദിച്ചത് എന്തുകൊണ്ട്?"},{"v":19,"t":"സൂതികർമിണികൾ ഫറവോയോടു പറഞ്ഞു: ഈജിപ്തുകാരികളെപ്പോലെയല്ല ഹെബ്രായസ്ത്രീകൾ. അവർ ഓജസ്സുറ്റവരാകയാൽ, സൂതികർമിണി അവരുടെപക്കൽ എത്തും മുമ്പേ പ്രസവിച്ചിരിക്കും."},{"v":20,"t":"ദൈവം സൂതികർമിണികൾക്കു നന്മ വരുത്തി. ജനം പെരുകി; അവർ ഏറെ ശക്തരായി."},{"v":21,"t":"സൂതികർമിണികൾ ദൈവത്തെ ഭയപ്പെട്ടിരുന്നതുകൊണ്ട് അവിടന്ന് അവർക്കായി കുടുംബങ്ങൾ സംസ്ഥാപിച്ചു."},{"v":22,"t":"അപ്പോൾ ഫറവോ തന്റെ സകലജനത്തോടും ഇപ്രകാരം കല്പിച്ചു: ജനിക്കുന്ന ഓരോ പുത്രനെയും നദിയിലേക്ക് എറിയുവിൻ; ഓരോ പുത്രിയും ജീവിച്ചുകൊള്ളട്ടെ."}],"2":[{"h":"മോശയുടെ ജനനം"},{"v":1,"t":"ലേവികുടുംബത്തിൽപ്പെട്ട ഒരാൾ ചെന്ന് ലേവിയുടെ ഒരു പുത്രിയെ സ്വീകരിച്ചു.","p":1},{"v":2,"t":"ആ സ്ത്രീ ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിച്ചു. അവൻ കോമളനാണെന്നു കണ്ട് അവനെ അവൾ മൂന്നുമാസം ഒളിപ്പിച്ചു."},{"v":3,"t":"അവനെ ഇനിയും ഒളിപ്പിക്കാൻ സാധിക്കാതായപ്പോൾ അവൾ അവനായി ഒരു പപ്പീറസ് പെട്ടകമെടുത്ത് കളിമണ്ണും താറും പൂശി, അതിൽ ശിശുവിനെ കിടത്തി, നൈൽതീരത്ത് ഞാങ്ങണയ്ക്കിടയിൽ വച്ചു."},{"v":4,"t":"അവനോട് എന്തു ചെയ്യുമെന്ന് അറിയാനായി അവന്റെ സഹോദരി അകലെയായി നിന്നിരുന്നു."},{"v":5,"t":"അപ്പോൾ ഫറവോയുടെ പുത്രി കുളിക്കാനായി നദിയിലിറങ്ങി. അവളുടെ ഭൃത്യകൾ നദീതീരത്തു നടക്കുകയായിരുന്നു. അവൾ ഞാങ്ങണയ്ക്കിടയിൽ ആ പെട്ടകം കണ്ടു. തന്റെ ഒരു ദാസിയെ അയച്ച് അവൾ അതെടുത്തു."},{"v":6,"t":"അവൾ അതു തുറന്നപ്പോൾ ശിശുവിനെ കണ്ടു. അതാ, കുട്ടി കരയുകയായിരുന്നു. അവന്റെമേൽ അനുകമ്പതോന്നി അവൾ പറഞ്ഞു: ഇവൻ ഹെബ്രായശിശുക്കളിൽപ്പെട്ടവനാണ്."},{"v":7,"t":"അപ്പോൾ അവന്റെ സഹോദരി ഫറവോയുടെ പുത്രിയോടു ചോദിച്ചു: ഞാൻ പോയി നിനക്കുവേണ്ടി ഹെബ്രായസ്ത്രീകളിൽനിന്ന് മുലയൂട്ടുന്ന ഒരുവളെ വിളിക്കട്ടെയോ? അവൾ നിനക്കുവേണ്ടി ശിശുവിനെ മുലയൂട്ടും."},{"v":8,"t":"പോവുക, ഫറവോയുടെ പുത്രി അവളോടു പറഞ്ഞു. ആ പെൺകുട്ടി പോയി ശിശുവിന്റെ അമ്മയെ വിളിച്ചു."},{"v":9,"t":"ഫറവോയുടെ പുത്രി അവളോടു പറഞ്ഞു: ഈ ശിശുവിനെ കൊണ്ടുപോയി എനിക്കുവേണ്ടി മുലയൂട്ടുക. ഞാൻ നിന്റെ ശമ്പളം തന്നുകൊള്ളാം. ആ സ്ത്രീ ശിശുവിനെ സ്വീകരിച്ച് അവനെ മുലയൂട്ടി."},{"v":10,"t":"ശിശു വളർന്നപ്പോൾ അവൾ അവനെ ഫറവോയുടെ പുത്രിയുടെപക്കൽ കൊണ്ടുവന്നു. അവൻ അവൾക്കു പുത്രനായി. ഞാൻ അവനെ വെള്ളത്തിൽനിന്ന് എടുത്തതുകൊണ്ട് എന്നു പറഞ്ഞ് അവൾ അവനു മോശ എന്നു പേരിട്ടു."},{"h":"മോശയുടെ പലായനം"},{"v":11,"t":"മോശ വളർച്ചയെത്തിയ ആ ദിനങ്ങളിൽ തന്റെ സഹോദരങ്ങളുടെയടുത്തേക്കു ചെല്ലാനും അവരുടെ കഠിനജോലികൾക്കു ദൃക്സാക്ഷിയാകാനും ഇടയായി. സ്വന്തം സഹോദരരിൽപ്പെട്ട ഒരു ഹെബ്രായനെ ഒരു ഈജിപ്തുകാരൻ പ്രഹരിക്കുന്നതും അവൻ കണ്ടു.","p":1},{"v":12,"t":"അവൻ അപ്പുറമിപ്പുറം തിരിഞ്ഞ്, ഒരാളുമില്ലെന്നു കണ്ടപ്പോൾ ആ ഈജിപ്തുകാരനെ കൊന്ന് മണലിൽ മറവുചെയ്തു."},{"v":13,"t":"രണ്ടാംദിവസം അവൻ പുറത്തിറങ്ങിയപ്പോൾ ഇതാ, ഹെബ്രായരായ രണ്ടാളുകൾ ശണ്ഠകൂടുന്നു! അക്രമിയോട് അവൻ ചോദിച്ചു: നീ എന്തിനാണ് നിന്റെ അയല്ക്കാരനെ പ്രഹരിക്കുന്നത്?"},{"v":14,"t":"അപ്പോൾ അവൻ ചോദിച്ചു: ആരാണ് നിന്നെ ഞങ്ങളുടെമേൽ അധികാരിയും ന്യായാധിപനുമായി നിയമിച്ചത്? ഈജിപ്തുകാരനെ കൊന്നപോലെ എന്നെയും കൊല്ലാനാണോ നീ ഉദ്ദേശിക്കുന്നത്? അപ്പോൾ മോശ ഭയപ്പെട്ടു. അവൻ ആത്മഗതംചെയ്തു: അക്കാര്യം പരസ്യമായിരിക്കുന്നു, തീർച്ച!"},{"v":15,"t":"ഫറവോ ഇക്കാര്യം കേട്ടപ്പോൾ മോശയെ വധിക്കാനുദ്യമിച്ചു. പക്ഷേ, മോശ ഫറവോയുടെ മുമ്പിൽനിന്ന് ഒളിച്ചോടി മിദിയാൻദേശത്തു വസിച്ചു. അവൻ കിണറ്റിൻകരയിൽ ഇരുന്നു."},{"v":16,"t":"മിദിയാനിലെ പുരോഹിതന് ഏഴു പെൺമക്കളുണ്ടായിരുന്നു. തങ്ങളുടെ പിതാവിന്റെ ആടുകൾക്കു കുടിക്കാൻകൊടുക്കാനായി അവർ വന്ന് തൊട്ടികളിൽ വെള്ളം കോരിനിറയ്ക്കുമ്പോൾ"},{"v":17,"t":"ആട്ടിടയന്മാർ വന്ന് അവരെ ആട്ടിപ്പായിച്ചു. എന്നാൽ, മോശ എഴുന്നേറ്റ് അവരെ രക്ഷിക്കുകയും അവരുടെ ആടുകളെ വെള്ളം കുടിപ്പിക്കുകയും ചെയ്തു."},{"v":18,"t":"അവർ തങ്ങളുടെ പിതാവായ റവുവേലിന്റെയടുക്കൽ വന്നപ്പോൾ അവൻ ചോദിച്ചു: നിങ്ങൾ ഇന്ന് നേരത്തേ വരാൻ ഇടയായതെങ്ങനെ?"},{"v":19,"t":"അവർ പറഞ്ഞു: ഈജിപ്തുകാരനായ ഒരാൾ ഞങ്ങളെ ഇടയന്മാരുടെ കൈയിൽനിന്നു മോചിപ്പിച്ചു. ഞങ്ങൾക്കുവേണ്ടി വെള്ളംകോരുകപോലും ചെയ്ത് അയാൾ ആടുകളെ കുടിപ്പിച്ചു."},{"v":20,"t":"അവൻ തന്റെ പുത്രിമാരോടു ചോദിച്ചു: എന്നിട്ട് അയാൾ എവിടെ? ഇതെന്താ, നിങ്ങൾ അയാളെ ഉപേക്ഷിച്ചുപോന്നത്? ഭക്ഷണം കഴിക്കാനായി അയാളെ ക്ഷണിക്കുവിൻ."},{"v":21,"t":"അങ്ങനെ മോശ അവനോടൊപ്പം താമസിക്കാൻ സമ്മതിച്ചു. അവൻ തന്റെ മകൾ സിപ്പോറായെ മോശയ്ക്കു നല്കി."},{"v":22,"t":"അവൾ ഒരു പുത്രനെ പ്രസവിച്ചു. 'ഞാൻ അന്യനാട്ടിൽ പ്രവാസിയായിരിക്കുന്നു' എന്നു പറഞ്ഞ് മോശ അവന് ഗെർഷോം എന്നു പേരിട്ടു."},{"v":23,"t":"ആ നീണ്ട നാളുകൾക്കിടയിൽ ഈജിപ്തുരാജാവ് മരിച്ചു. അടിമത്തംമൂലം ഇസ്രായേല്യർ നെടുവീർപ്പിട്ടു; അവർ നിലവിളിച്ചു. അടിമത്തംമൂലമുള്ള അവരുടെ മുറവിളി ദൈവത്തിങ്കലേക്കുയർന്നു.","p":1},{"v":24,"t":"ദൈവം അവരുടെ ദീനരോദനം ശ്രവിച്ചു. അബ്രാഹത്തോടും ഇസഹാക്കിനോടും യാക്കോബിനോടുമുള്ള തന്റെ ഉടമ്പടി ദൈവം ഓർത്തു."},{"v":25,"t":"ദൈവം ഇസ്രായേല്യരെ കടാക്ഷിച്ചു; അവരുടെ ദൈന്യം അറിയുകയും ചെയ്തു."}],"3":[{"h":"മോശയെ വിളിക്കുന്നു"},{"v":1,"t":"മോശ തന്റെ അമ്മായിയപ്പനായ മിദിയാനിലെ പുരോഹിതൻ ജത്രോയുടെ ആടുകളെ മേയിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അവൻ മരുഭൂമിക്കപ്പുറത്തേക്ക് ആടുകളെ നയിക്കവേ, ദൈവത്തിന്റെ മലയായ ഹോറെബിലേക്ക് വന്നെത്തി.","p":1},{"v":2,"t":"അപ്പോൾ, മുൾപ്പടർപ്പിന്റെ മധ്യേ അഗ്നിജ്വാലയിൽ കർത്താവിന്റെ ദൂതൻ അവനു പ്രത്യക്ഷപ്പെട്ടു. അവൻ കണ്ടു: അതാ, മുൾപ്പടർപ്പ് അഗ്നിയാൽ എരിയുന്നു; എങ്കിലും ആ മുൾപ്പടർപ്പ് ചാമ്പലാകുന്നില്ല!"},{"v":3,"t":"അപ്പോൾ മോശ ആത്മഗതംചെയ്തു: ഞാൻ അങ്ങോട്ടു ചെന്ന് ഈ മഹാദൃശ്യം കാണട്ടെ. എന്തുകൊണ്ട് മുൾപ്പടർപ്പ് എരിഞ്ഞമരുന്നില്ല?"},{"v":4,"t":"അവൻ അതു കാണാൻ തിരിയുന്നു എന്ന് കർത്താവു കണ്ടു. മുൾപ്പടർപ്പിന്റെ മധ്യത്തിൽനിന്ന് ദൈവം അവനെ വിളിച്ചുകൊണ്ടു പറഞ്ഞു: മോശേ, മോശേ. അവൻ പറഞ്ഞു: ഇതാ, ഞാൻ!"},{"v":5,"t":"അവിടന്ന് അരുൾചെയ്തു: ഇങ്ങോട്ട് അടുക്കരുത്. നിന്റെ പാദങ്ങളിൽനിന്ന് ചെരുപ്പുകൾ അഴിക്കുക. എന്തെന്നാൽ,"}]}},{"id":"MAT","name":"മത്തായി","chapters":{"1":[{"h":"യേശുവിന്റെ വംശാവലി"},{"v":1,"t":"ദാവീദിൻ്റെ പുത്രനും അബ്രാഹത്തിൻ്റെ പുത്രനുമായ യേശുക്രിസ്‌തുവിൻ്റെ ഉദ്ഭവ ചരിത്രഗ്രന്ഥം.","p":1},{"v":2,"t":"അബ്രാഹം ഇസഹാക്കിൻ്റെ പിതാവായിരുന്നു. ഇസഹാക്ക് യാക്കോബിൻ്റെ പിതാവായിരുന്നു. യാക്കോബ് യൂദായുടെയും സഹോദരന്മാരുടെയും പിതാവായിരുന്നു.","p":1},{"v":3,"t":"യൂദാ, താമാറിൽനിന്നുള്ള പേരെസിൻ്റെയും സേറായുടെയും പിതാവായിരുന്നു. പേരെസ് ഹെസ്‌റോൻ്റെ പിതാവായിരുന്നു. ഹെസ് റോൻ ആരാമിന്റെ പിതാവായിരുന്നു.","p":1},{"v":4,"t":"ആരാം അമിനാ ദാബിന്റെ പിതാവായിരുന്നു. അമിനാദാബ് നഹ് ഷോന്റെ പിതാവായിരുന്നു. നഹ്ഷോൻ സൽമോന്റെ പിതാവായിരുന്നു.","p":1},{"v":5,"t":"സൽമോൻ റാഹാബിൽ നിന്നുള്ള ബോവാസിൻ്റെ പിതാവായിരുന്നു. ബോവാസ് റൂത്തിൽ നിന്നുളള ഓബദിൻ്റെ പിതാവായിരുന്നു. ഓബദ് ജസ്സെയുടെ പിതാവായിരുന്നു.","p":1},{"v":6,"t":"ജസ്സെ ദാവീദ് രാജാവിന്റെ പിതാവായിരുന്നു. ദാവീദ് ഊറിയായുടെ ഭാര്യയിൽ നിന്നുളള സോളമൻ്റെ പിതാവായിരുന്നു.","p":1},{"v":7,"t":"സോളമൻ റഹോബോവാമിൻ്റെ പിതാവായിരുന്നു. റഹോബോവാം അബിയായുടെ പിതാവായിരുന്നു. അബിയാ ആസായുടെ പിതാവായിരുന്നു.","p":1},{"v":8,"t":"ആസാ യോസഫാത്തിന്റെ പിതാവായിരുന്നു. യോസഫാത്ത് യോറാമിൻ്റെ പിതാവായിരുന്നു. യോറാം ഓസിയാ യുടെ പിതാവായിരുന്നു. ഓസിയാ യോഥാമിൻ്റെ പിതാവായിരുന്നു.","p":1},{"v":9,"t":"യോഥാം ആഹാസിൻ്റെ പിതാവായിരുന്നു. ആഹാസ് ഹെസെക്കിയായുടെ പിതാവായി രുന്നു.","p":1},{"v":10,"t":"ഹെസെക്കിയാ മനാസ്സെയുടെ പിതാവായി രുന്നു. മനാസ്സെ ആമോസിൻ്റെ പിതാവായിരുന്നു. ആമോസ് ജോസിയായുടെ പിതാവായിരുന്നു.","p":1},{"v":11,"t":"ജോസിയാ, ബാബിലോൺ പ്രവാസകാലത്തുളള യാക്കോണിയായുടെയും സഹോദരന്മാരുടെയും പിതാവായിരുന്നു.","p":1},{"v":12,"t":"യാക്കോണിയാ ബാബിലോൺ പ്രവാസത്തിനു ശേഷമുള്ള സലാത്തിയേലിൻ്റെ പിതാവായിരുന്നു. സലാത്തിയേൽ സൊറൊബാബേലിൻ്റെ പിതാവായി","p":1},{"v":12,"t":"രുന്നു.","p":1},{"v":13,"t":"സൊറൊബാബേൽ അബിയൂദിൻ്റെ പിതാവായിരുന്നു. അബിയൂദ് എലിയാക്കിമിന്റെ പിതാവായിരുന്നു. എലിയാക്കിം ആസോറിന്റെ പിതാവായിരുന്നു.","p":1},{"v":14,"t":"ആസാർ സാദോക്കിൻ്റെ പിതാവായിരുന്നു. സാദോക്ക് അക്കീമിൻ്റെ പിതാവായിരുന്നു. അക്കീം ഏലിയൂദിൻ്റെ പിതാവായിരുന്നു.","p":1},{"v":15,"t":"എലിയൂദ് എലെയാസറിന്റെ പിതാവായിരുന്നു. എലെയാസർ മഥാൻ്റെ പിതാവായിരുന്നു മഥാൻ യാക്കോബിന്റെ പിതാവായിരുന്നു.","p":1},{"v":16,"t":"യാക്കോബ് മറിയത്തിന്റെ ഭർത്താവായ ജോസഫിന്റെ പിതാവായിരുന്നു. അവളിൽ നിന്ന് ക്രിസ്‌തു എന്നു വിളിക്കപ്പെടുന്ന യേശു ജനിച്ചു.","p":1},{"v":17,"t":"\"ഇങ്ങനെ, അബ്രാഹം മുതൽ ദാവീദുവരെ പതിനാലു തലമുറകളും ദാവീദ് മുതൽ ബാബിലോൺ പ്രവാസംവരെ പതിനാലു തലമുറകളും ബാബി ലോൺ പ്രവാസം മുതൽ ക്രിസ്‌തുവരെ പതിനാലു തലമുറകളുമാണ് ആകെയുള്ളത്.","p":1},{"h":"യേശുവിന്റെ ജനനം"},{"v":18,"t":"'യേശുക്രിസ്‌തുവിൻ്റെ ജനനം ഇപ്രകാരമായിരുന്നു: അവന്റെ മാതാവായ മറിയവും ജോസഫും തമ്മിലുള്ള വിവാഹനിശ്ചയം കഴിഞ്ഞിരിക്കേ, അവർ സഹവസിക്കുന്നതിനുമുമ്പ് അവൾ പരിശുദ്ധാത്മാവാൽ ഗർഭിണിയായി കാണപ്പെട്ടു.","p":1},{"v":19,"t":"അവളുടെ ഭർത്താവായ ജോസഫ് നീതിമാനാകയാലും അവളെ അപമാ നിതയാക്കാൻ ഇഷ്‌ടപ്പെടായ്‌കയാലും അവളെ രഹസ്യത്തിൽ ഉപേക്ഷിക്കാൻ തീരുമാനിച്ചു.","p":1},{"v":20,"t":"അവൻ ഇതെക്കുറിച്ച് ആലോചിച്ചുകൊണ്ടിരിക്കേ, കർത്താവിൻ്റെ ദൂതൻ സ്വപ്‌നത്തിൽ പ്രത്യക്ഷപ്പെട്ട് അവനോടു പറഞ്ഞു: ദാവീദിൻ്റെ പുത്രനായ ജോസഫ്, നിൻ്റെ ഭാര്യയായ മറിയത്തെ സ്വീകരിക്കാൻ ഭയപ്പെ ടേണ്ടാ. അവൾ ഗർഭംധരിച്ചിരിക്കുന്നത് പരിശുദ്ധാത്മാവിൽനിന്നാണ്.","p":1},{"v":21,"t":"അവൾ ഒരു പുത്രനെ പ്രസവിക്കും നീ അവനെ യേശു എന്നു പേര് വിളിക്കണം.. എന്തെന്നാൽ, അവൻ തൻ്റെ ജനത്തെ അവരുടെ പാപങ്ങളിൽ നിന്നു രക്ഷിക്കും.","p":1},{"v":22,"t":"കന്യക ഗർഭംധരിച്ച് ഒരു പുത്രനെ പ്രസവിക്കും.","p":1},{"v":23,"t":"ദൈവം നമ്മോടുകൂടെ എന്നർത്ഥമുള്ള എമ്മാനുവേൽ എന്ന് അവൻ വിളിക്കപ്പെടും.എന്ന് കർത്താവ് പ്രവാചകൻമുഖേന അരുൾ ചെയ്തതു പൂർത്തിയാകാൻ വേണ്ടിയാണ് ഇതെല്ലാം സംഭവിച്ചത്.","p":1},{"v":24,"t":"ജോസഫ് നിദ്രയിൽനിന്നുണർന്ന്. കർത്താവിന്റെ ദൂതൻ കല്പ്‌പിച്ചപോലെ പ്രവർത്തിച്ചു; അവൻ തന്റെ ഭാര്യയെ സ്വീകരിച്ചു.","p":1},{"v":25,"t":"പുത്രനെ പ്രസവിക്കുന്നതുവരെ അവൻ അവളെ അറിഞ്ഞില്ല; അവൻ യേശു എന്ന് അവനെ പേരു വിളിച്ചു.","p":1}],"2":[{"h":"ജ്ഞാനികളുടെ സന്ദർശനം"},{"v":1,"t":"ഹേറോദേസ് രാജാവിന്റെ കാലത്ത് യൂദയാ യിലെ ബേ‌ഹെമിൽ യേശു ജനിച്ചപ്പോൾ പൗരസ്ത്യദേശത്തുനിന്നു ജ്ഞാനികൾ ജറുസലേമി ലെത്തി.","p":1},{"v":2,"t":"അവർ അന്വേഷിച്ചു: എവിടെയാണ് യഹൂ ദന്മാരുടെ രാജാവായി ജനിച്ചവൻ? കാരണം, ഞങ്ങൾ കിഴക്ക് അവൻ്റെ നക്ഷത്രം കണ്ട് അവനെ ആരാധിക്കാൻ വന്നിരിക്കുകയാണ്.","p":1},{"v":3,"t":"'ഇതുകേട്ട് ഹേറോദേസ് രാജാവ് അസ്വസ്ഥനായി; അവനോടൊപ്പം ജറുസലേം മുഴുവനും.","p":1},{"v":4,"t":"അവൻ സകല പുരോഹിതപ്രമുഖന്മാരെയും ജനത്തിന്റെ നിയമജ്ഞരെയും വിളിച്ചുകൂട്ടി, ക്രിസ്തു‌ എവിടെയാണു ജനിക്കുന്നതെന്ന് അന്വേഷിച്ചു.","p":1},{"v":5,"t":"അവർ പറഞ്ഞു: യൂദയായിലെ ബേ‌ലെഹെമിൽ. എന്തെന്നാൽ, പ്രവാചകനിലൂടെ ഇപ്രകാരം എഴുതപ്പെട്ടിരിക്കുന്നു:","p":1},{"v":6,"t":"യൂദയായിലെ ബേത്ലെ ഹൈമേ, നീ യൂദയായിലെ പ്രമുഖനഗരങ്ങളിൽ ഒട്ടും താഴേയല്ല; എന്റെ ജനമായ ഇസ്രായേലിനെ മേയിക്കാനുള്ളവൻ നിന്നിൽ നിന്നാണ് ഉദ്ഭവിക്കുന്നത്.","p":1},{"v":7,"t":"അപ്പോൾ ഹേറോദേസ് ആ ജ്ഞാനികളെ രഹസ്യത്തിൽ വിളിച്ച്, നക്ഷത്രം പ്രത്യക്ഷപ്പെട്ട സമയം സൂക്ഷ്മമായി അവരിൽനിന്ന് അന്വേഷിച്ചറിഞ്ഞു.","p":1},{"v":8,"t":"അവൻ അവരെ ബേത്ലഹെമിലേക്ക് അയച്ചു കൊണ്ടു പറഞ്ഞു: പോയി ശിശുവിനെപ്പറ്റി സൂക്ഷ്‌മമായി അന്വേഷിക്കുക; കണ്ടുകഴിയുമ്പോൾ ഞാനും ചെന്ന് അവനെ ആരാധിക്കുന്നതിന് എന്നെ അറിയിക്കുക.","p":1},{"v":9,"t":"രാജാവിനെ കേട്ടശേഷം അവർ പുറപ്പെട്ടു. അവർ കിഴക്കുകണ്ട നക്ഷത്രം, ശിശു കിടക്കുന്ന സ്ഥലത്തിനു മുകളിൽ വന്നു നില്ക്കുന്നതുവരെ, അവർക്കുമുമ്പേ നീങ്ങിക്കൊണ്ടിരുന്നു.","p":1},{"v":10,"t":"\"നക്ഷത്രംകണ്ടപ്പോൾ അവർ അത്യധികം സന്തോഷിച്ചു.","p":1},{"v":11,"t":"അവർ ഭവനത്തിൽ പ്രവേശിച്ച്, ശിശുവിനെ അവൻ്റെ അമ്മയായ മറിയത്തോടൊപ്പം കണ്ട് മുട്ടിന്മേൽവീണ് ആരാധിക്കുകയും അവരുടെ നിക്ഷേപപാത്രങ്ങൾ.തുറന്ന് പൊന്ന്, മീറ, കുന്തുരുക്കം എന്നീ കാഴ്‌ചകൾ \"അവന് അർപ്പിക്കുകയും ചെയ്‌തു.","p":1},{"v":12,"t":"ഹേറോദേസിൻ്റെ അടുത്തേക്കു മടങ്ങിപ്പോകരുതെന്ന് സ്വപ്‌നത്തിൽ","p":1},{"v":12,"t":"മുന്നറിയിപ്പു ലഭിച്ചതനുസരിച്ച് അവർ മറ്റൊരു വഴിയേ സ്വദേശത്തേക്കു തിരിച്ചുപോയി.","p":1},{"h":"ഈജിപ്‌തിലേക്കുള്ള പലായനം"},{"v":13,"t":"അവർ പൊയ്ക്കഴിഞ്ഞപ്പോൾ കർത്താവിൻ്റെ ദൂതൻ സ്വപ്‌നത്തിൽ പ്രത്യക്ഷപ്പെട്ട് ജോസഫിനോട പറഞ്ഞു: എഴുന്നേററ് ശിശുവിനെയും അമ്മയെയും കൂട്ടി ഈജിപ്‌തിലേക്കു പലായനം ചെയ്യുക. ഞാൻ പറയുന്നതുവരെ അവിടെ താമസിക്കുക. കാരണം, ഹേറോദേസ് ശിശുവിനെ വധിക്കാനായി അന്വേഷണം തുടങ്ങാൻ പോകുകയാണ്.","p":1},{"v":14,"t":"അവൻ ഉണർന്ന് ശിശുവിനെയും അമ്മയെയുംകൂട്ടി, ആ രാത്രിതന്നെ ഈജിപ്‌തിലേക്കു പോയി;","p":1},{"v":15,"t":"ഹേറോദേസിൻ്റെ മരണം, വരെ അവൻ അവിടെ താമസിച്ചു. ഈജിപ്‌തിൽനിന്ന് ഞാൻ എൻ്റെ പുത്രനെ വിളിച്ചു എന്നു പ്രവാചകൻഅരുൾചെയ്‌തത് പൂർത്തിയാകേണ്ട തിനായിരുന്നു ഇത്.","p":1},{"v":16,"t":"തന്നെ ജ്ഞാനികൾ കബളിപ്പിച്ചെന്നുകണ്ടപ്പോൾ ഹേറോദേസ് അതീവം രോഷാകുലനായി. അവരിൽനിന്നു സൂക്ഷ്‌മമായി മനസ്സിലക്കിയ സമയമനുസരിച്ച് അവൻ ബേത്ലെഹെമിലെയും എല്ലാ സമീപപ്രദേശങ്ങളിലെയും രണ്ടും അതിൽ താഴേയും വയസ്സുള്ള എല്ലാ ആൺകുട്ടിളെയും ആളയച്ചു വധിച്ചു.","p":1},{"v":17,"t":"ജറെമിയാപ്രവാചകൻ വഴി അരുൾചെയ്യപ്പെട്ടത് ഇങ്ങനെ പൂർത്തിയായി.","p":1},{"v":18,"t":"റാമായിൽ ഒരുസ്വരം കേട്ടു. വലിയ കരച്ചിലും മുറ വിളിയും. റാഹേൽ അവളുടെ സന്താനങ്ങളെക്കുറിച്ചു കരയുന്നു. ആശ്വസിപ്പിക്കപ്പെടാൻ അവൾ സമ്മതി ക്കുന്നില്ല. എന്തെന്നാൽ, അവർ ഇല്ലാതായിരിക്കുന്നു.","p":1},{"h":"തിരിച്ചുവരവ്"},{"v":19,"t":"ഹേറോദേസിൻ്റെ മരണത്തിനുശേഷം ഈജിപിതിൽ വച്ച് കർത്താവിന്റെ ദൂതൻ ജോസഫിന് സ്വപനത്തിൽ പ്രത്യക്ഷപ്പെട്ടു പറഞ്ഞു:","p":1},{"v":20,"t":"എഴുന്നേറ്റ് ശിശുവിനെയും അവന്റെ അമ്മയെയും കൂട്ടി, ഇസ്രാരയേൽ ദേശത്തേക്കു മടങ്ങുക; കാരണം, ശിശുവിൻ്റെ ജീവർ അന്വേഷിച്ചവർ മരിച്ചിരിക്കുന്നു","p":1},{"v":21,"t":"അവൻ എഴുന്നേറ്റ് ശിശുവിനെയും അമ്മയെയും കൂട്ടി, ഇസ്രായേൽ ദേശത്തേക്കു പോയി.","p":1},{"v":22,"t":"അർക്കലാവോസ് അവന്റെ പിതാവായ ഹേറോദേസിന്റെ സ്ഥാനത്ത് യൂദയാ ഭരിക്കുന്നു. എന്നു കേട്ടപ്പോൾ അവിടേക്കു പോകാൻ ജോസഫ് ഭയപ്പെട്ടു. സ്വപ്‌നത്തിൽ ലഭിച്ച മുന്നറിയിപ്പനുസരിച്ച് അവൻ ഗലീലിപ്രദേശത്തേക്കു പൊയി.","p":1},{"v":23,"t":"അവൻ നസ്രായൻ എന്ന് വിളിക്കപ്പെടും എന്ന് പ്രവാചകന്മാർ വഴി അരുൾ ചെയ്യപ്പെട്ടത് പൂർത്തിയാകേണ്ടതിന് അവൻ നസറത്ത് എന്ന പട്ടണത്തിൽ പോയി വസിച്ചു.","p":1}],"3":[{"h":"സ്‌നാപകയോഹന്നാന്റെ സാക്ഷ്യം"},{"v":1,"t":"ആ ദിവസങ്ങളിൽ, യോഹന്നാൻ പ്രഘോഷിച്ചുകൊണ്ട് യൂദയായിലെ മരുഭൂമിയിൽ എത്തിച്ചേർന്നു:","p":1},{"v":2,"t":"മാനസാന്തരപ്പെടുവിൻ; എന്തെന്നാൽ സ്വർഗരാജ്യം സമീപിച്ചിരിക്കുന്നു.","p":1},{"v":3,"t":"ഏശയ്യാ പ്രവാചകനിലൂടെ അരുൾചെയ്യപ്പെട്ടത് അവനെക്കുറിച്ചാണ്: മരുഭൂമിയിൽ വിളിച്ചുപറയുന്നവന്റെ ശബ്ദം - കർത്താവിന്റെ വഴിയൊരുക്കുവിൻ; അവന്റെ പാതകൾ നേരേ യാക്കുവിൻ.","p":1},{"v":4,"t":"യോഹന്നാൻ ഒട്ടകരോമം കൊണ്ടുള്ള വസ്ത്രവും അരയിൽ തോൽവാറും ധരിച്ചിരുന്നു. വെട്ടുക്കിളിയും കാട്ടുതേനുമായിരുന്നു അവന്റെ ഭക്ഷണം. '","p":1},{"v":5,"t":"ജറുസലേമിലും യൂദയാ മുഴുവനിലും ജോർദാന്റെ ചുറ്റുമുളള എല്ലാ പ്രദേശങ്ങളിലും നിന്നുളളവർ അവന്റെ അടുത്തെത്തി.","p":1},{"v":6,"t":"അവർ പാപങ്ങൾ ഏറ്റുപറഞ്ഞ്, ജോർദാൻ നദിയിൽവച്ച് അവനിൽനിന്നു സ്‌നാനം സ്വീകരിച്ചു.","p":1},{"v":7,"t":"അനേകം ഫരിസേയരും സദുക്കായരും സ്നാന മേല്ക്കാൻ വരുന്നതുകണ്ട്, യോഹന്നാൻ അവരോടു പറഞ്ഞു: അണലിസന്തതികളേ, ആസന്നമായ ക്രോധത്തിൽനിന്ന് ഓടിയകലാൻ നിങ്ങൾക്കു മുന്നറിയിപ്പു നല്കിയതാരാണ് ?","p":1},{"v":8,"t":"\"മാനസാന്തരത്തിനു യോജിച്ച ഫലം പുറപ്പെടുവിക്കുവിൻ.","p":1},{"v":9,"t":"ഞങ്ങൾക്കു പിതാവായി അബ്രാഹമുണ്ട് എന്നു പറഞ്ഞ് അഭിമാനി ക്കേണ്ടാ. കാരണം, ഈ കല്ലുകളിൽനിന്ന് അബ്രാഹത്തിനുവേണ്ടി സന്താനങ്ങളെ പുറപ്പെടുവിക്കാൻ ദൈവത്തിനു കഴിയുമെന്നു ഞാൻ നിങ്ങളോടു പറയുന്നു.","p":1},{"v":10,"t":"വൃക്ഷങ്ങളുടെ വേരിനു കോടാലി വച്ചു കഴിഞ്ഞു. അതിനാൽ, നല്ല ഫലം നല്കാത്ത വൃക്ഷങ്ങളെല്ലാം വെട്ടി തീയിലെറിയപ്പെടും.","p":1},{"v":11,"t":"\"മാനസാന്തരത്തിനായി ഞാൻ ജലം കൊണ്ടു നിങ്ങളെ സ്നാനപ്പെടുത്തുന്നു. എന്റെ പിന്നാലെ വരുന്നവൻ എന്നെക്കാൾ ശക്തൻ; അവൻ്റെ ചെരിപ്പുവഹിക്കാൻപോലും ഞാൻ യോഗ്യനല്ല; അവൻ പരിശുദ്ധാത്മാവാലും അഗ്നിയാലും നിങ്ങളെ സ്നാനപ്പെടുത്തും. വീശുമുറം അവൻ്റെ കൈയിലുണ്ട്.","p":1},{"v":12,"t":"അവൻ കളം വെടിപ്പാക്കി, തന്റെ ഗോതമ്പ് അറപ്പുരയിൽ ശേഖരിക്കും; പതിര് കെടാത്ത തീയിൽ കത്തിച്ചുകളയുകയും ചെയ്യും..","p":1},{"h":"യേശുവിന്റെ ജ്ഞാനസ്നാനം"},{"v":13,"t":"അനന്തരം യേശു ഗലീലിയിൽനിന്ന് ജോർദാനിൽ യോഹന്നാന്റെ അടുത്തേക്ക് അവനിൽനിന്ന് സ്നാനമേല്ക്കാൻ വന്നു.","p":1},{"v":14,"t":"\"യോഹന്നാൻ അവനെ തടഞ്ഞു","p":1},{"v":14,"t":"കൊണ്ടു പറഞ്ഞു: ഞാൻ നിന്നിൽനിന്ന് സ്നാന മേല്ക്കേണ്ടത് ആവശ്യമായിരിക്കേ, നീ എൻ്റെ അടുത്തേക്കു വരുന്നുവോ?","p":1},{"v":15,"t":"യേശു മറുപടിയായി അവനോടു പറഞ്ഞു: ഇപ്പോൾ ഇതു സമ്മതിക്കുക; എന്തു കൊണ്ടെന്നാൽ അങ്ങനെ സർവനീതിയും പൂർത്തിയാക്കുക നമുക്ക് ഉചിതമാണ്. അപ്പോൾ അവൻ സമ്മതിച്ചു.","p":1},{"v":16,"t":"സ്ന‌ാനം കഴിഞ്ഞയുടൻ യേശു വെള്ളത്തിൽ നിന്നു കയറി. അപ്പോൾ സ്വർഗം തുറക്കപ്പെട്ടു. ദൈവാത്മാവ് പ്രാവിനെപ്പോലെ അവന്റെമേൽ ഇറങ്ങിവരുന്നതു കണ്ടു.","p":1},{"v":17,"t":"സ്വർഗത്തിൽനിന്ന് ഒരു സ്വരമുണ്ടായി: ഇവൻ എന്റെ പ്രിയപുത്രൻ; ഇവനിൽ ഞാൻ പ്രസാദിച്ചിരിക്കുന്നു.","p":1}],"4":[{"h":"മരുഭൂമിയിലെ പ്രലോഭനം"},{"v":1,"t":"അനന്തരം, പിശാചിനാൽ പരീക്ഷിക്കപ്പെടാൻ ആത്മാവ് യേശുവിനെ മരുഭൂമിയിലേക്കു നയിച്ചു.","p":1},{"v":2,"t":"നാല്പ‌തു പകലും നാല്പതു രാവും ഉപവ സിച്ചു കഴിഞ്ഞപ്പോൾ അവനു വിശന്നു."},{"v":3,"t":"പ്രലോഭകൻ അവനെ സമീപിച്ചു പറഞ്ഞു: നീ ദൈവപുത്രനാണെങ്കിൽ ഈ കല്ലുകൾ അപ്പമാകാൻ പറയുക.","p":1},{"v":4,"t":"അവൻ പ്രതിവചിച്ചു: മനുഷ്യൻ അപ്പംകൊണ്ടു മാത്രമല്ല, ദൈവത്തിൻ്റെ വായിൽനിന്നു പുറപ്പെടുന്ന ഓരോ വാക്കുകൊണ്ടുമാണു ജീവിക്കുന്നത് എന്ന് എഴുതപ്പെട്ടിരിക്കുന്നു.","p":1},{"v":5,"t":"'അനന്തരം, പിശാച് അവനെ വിശുദ്ധ നഗരത്തിലേക്കു കൂട്ടിക്കൊണ്ടുപോയി ദേവാലയത്തിൻ്റെ അഗ്രത്തിൽ കയറ്റിനിറുത്തിയിട്ടു പറഞ്ഞു:","p":1},{"v":6,"t":"നീ ദൈവപുത്രനാണെങ്കിൽ താഴേക്കു ചാടുക. എന്തെന്നാൽ, നിന്നെക്കുറിച്ച് അവൻ തൻ്റെ ദൂത ന്മാർക്കു കല്പ്‌പന നല്‌കും; നിന്റെ പാദം കല്ലിൽ തട്ടാതിരിക്കാൻ അവർ നിന്നെ കൈകളിൽ താങ്ങിക്കൊള്ളും എന്ന് എഴുതപ്പെട്ടിരിക്കുന്നു.","p":1},{"v":7,"t":"യേശു അവനോട് പറഞ്ഞു: നിൻ്റെ ദൈവമായ കർത്താവിനെ പരീക്ഷിക്കരുത് എന്നുകൂടി എഴുതപ്പെട്ടിരിക്കുന്നു.","p":1},{"v":8,"t":"വീണ്ടും, പിശാച് ഏറെ ഉയർന്ന ഒരു മലയിലേക്ക് അവനെ കൂട്ടിക്കൊണ്ടു പോയി, ലോകത്തിലെ എല്ലാ രാജ്യ ങ്ങളും അവയുടെ മഹത്ത്വവും അവനെ കാണിച്ചു കൊണ്ട് അവനോടു പറഞ്ഞു:","p":1},{"v":9,"t":"നീ മുട്ടിന്മേൽ വീണ് എന്നെ ആരാധിച്ചാൽ ഇവയെല്ലാം നിനക്കു ഞാൻ നല്‌കാം.","p":1},{"v":10,"t":"യേശു കല്‌പിച്ചു: സാത്താനേ, ദൂരെ പ്പോകൂ; എന്തെന്നാൽ, നിൻ്റെ ദൈവമായ കർത്താവിനെ ആരാധിക്കണം; അവിടത്തെ മാത്രമേ പൂജി ക്കാവൂ എന്ന് എഴുതപ്പെട്ടിരിക്കുന്നു."},{"v":11,"t":"അപ്പോൾ പിശാച് അവനെ വിട്ടുപോയി. ദൈവദൂതന്മാർ അടുത്തുവന്ന് അവനെ ശുശ്രൂഷിച്ചു."},{"h":"യേശു ദൗത്യമാരംഭിക്കുന്നു"},{"v":12,"t":"യോഹന്നാൻ ബന്ധനസ്ഥനായെന്നു കേട്ടപ്പോൾ യേശു ഗലീലിയിലേക്കു പിൻവാങ്ങി.","p":1},{"v":13,"t":"അവൻ നസറത്തുവിട്ട് സെബുലൂണിൻ്റെയും നഫ്‌താലിയുടെയും അതിർത്തിയിൽ, സമുദ്രതീരത്തുള്ള കഫർണാമിൽ ചെന്നു പാർത്തു.","p":1},{"v":14,"t":"ഇത് ഏശയ്യാപ്രവാചകൻ വഴി അരുൾചെയ്യപ്പെട്ടത് പൂർത്തിയാകാൻ വേണ്ടിയാണ്:","p":1},{"v":15,"t":"സമുദ്രത്തിലേക്കുള്ള വഴിയിൽ, ജോർദാൻ്റെ മറു കരയിൽ, സെബുലൂൺ, നഫ്താലി പ്രദേശങ്ങൾ-- ജനതകളുടെ ഗലീലി--"},{"v":16,"t":"അന്ധകാരത്തിലിരുന്ന ജനം വലിയ പ്രകാശം കണ്ടു. മരണത്തിൻ്റെ നാട്ടിലും നിഴ ലിലുമിരുന്നവർക്കായി പ്രകാശം ഉദയംചെയ്‌തു.","p":1},{"v":17,"t":"അപ്പോൾ മുതൽ യേശു പ്രഘോഷിക്കാൻ തുടങ്ങി: മാനസാന്തരപ്പെടുവിൻ; സ്വർഗരാജ്യം സമീപിച്ചിരി ക്കുന്നു.","p":1},{"h":"ആദ്യത്തെ നാലു ശിഷ്യന്മാർ"},{"v":17,"t":"* അവൻ ഗലീലിക്കടൽത്തീരത്തു നടക്കുമ്പോൾ, കടലിൽ വലവീശിക്കൊണ്ടിരുന്ന രണ്ടു സഹോദരന്മാരെ കണ്ടു - പത്രോസ് എന്നു വിളിക്കപ്പെടുന്ന ശിമയോനെയും സഹോദരൻ അന്ത്രയോസിനെയും. അവർ മീൻപിടിത്തക്കാരായിരുന്നു. \"അവൻ അവ രോടു പറഞ്ഞു: എന്നെ അനുഗമിക്കുക; ഞാൻ നിങ്ങളെ മനുഷ്യരെപ്പിടിക്കുന്നവരാക്കും. \"തത് ക്ഷണം അവർ വലകളുപേക്ഷിച്ച് അവനെ അനു ഗമിച്ചു. \"അവർ അവിടെനിന്നു മുന്നോട്ടു നീങ്ങിയപ്പോൾ വേറെ രണ്ടു സഹോദരന്മാരെ - സെബദി പുത്രനായ യാക്കോബിനെയും സഹോദരൻ യോഹന്നാനെയും - കണ്ടു. അവർ പിതാവായ സെബദിയുമൊത്ത് വഞ്ചിയിലിരുന്നു വല നന്നാക്കുകയായിരുന്നു\"അവരെയും അവൻ വിളിച്ചു. തത്ക്ഷണം അവർ വഞ്ചിയും അവരുടെ പിതാവിനെയും ഉപേക്ഷിച്ച് അവനെ അനുഗമിച്ചു.","p":1},{"h":"യേശു രോഗികളെ സുഖപ്പെടുത്തുന്നു"},{"v":17,"t":"\" അവൻ അവരുടെ സിനഗോഗുകളിൽ പഠിപ്പിച്ചും രാജ്യത്തിൻ്റെ സുവിശേഷം പ്രഘോഷിച്ചും ജനങ്ങളുടെഎല്ലാ രോഗങ്ങളും വ്യാധികളും സുഖപ്പെടുത്തിയും ഗലീലിമുഴുവൻ ചുറ്റിസഞ്ചരിച്ചു. ?അവൻ്റെ കീർത്തി സിറിയയിലെങ്ങും വ്യാപിച്ചു വിവിധ വ്യാധികളാലും വ്യഥകളാലും അവശ രായവരെയും പിശാചുബാധിതർ, അപസ്മാരരോഗികൾ, തളർവാതക്കാർ എന്നിവരെയും അവർ അവന്റെ അടുത്തുകൊണ്ടുവന്നു. അവരെ അവൻ സുഖപ്പെടുത്തി ഗലീലി, ദക്കാപ്പോളിസ്, ജറുസലേലം യുദയ ജോർദാൻ്റെ മറുകര എന്നിവിടങ്ങളിൽനിന്ന് വലിയ ജനക്കൂട്ടം അവനെ അനുഗമിച്ചു","p":1}],"5":[{"h":"സുവിശേഷഭാഗ്യങ്ങൾ"},{"v":1,"t":"ജനക്കൂട്ടത്തെക്കണ്ട് യേശു മലയിലേക്കുകയറി അവൻ ഇരുന്നപ്പോൾ ശിഷ്യന്മാർ അടുത്തെത്തി \"","p":1},{"v":2,"t":"അവൻ അധരം തുറന്ന് അവരെ പഠിപ്പിച്ചു തുടങ്ങി '","p":1},{"v":3,"t":"ആത്മാവിൽ ദരിദ്രർ അനുഗൃഹീതർ; എന്തെന്നാൽ സ്വർഗരാജ്യം അവരുടേതാണ്.","p":1},{"v":4,"t":"വിലപിക്കുന്നവർ അനുഗൃഹീതർ; എന്തെന്നാൽ അവർ ആശ്വസിപ്പിക്കപ്പെടും."},{"v":5,"t":"ശാന്തശീലർ അനുഗൃഹീതർ; എന്തെന്നാൽ അവർ ഭൂമി അവകാശമാക്കും"},{"v":6,"t":"നീതിക്കുവേണ്ടി വിശ ക്കുകയും ദാഹിക്കുകയും ചെയ്യുന്നവർ അനുഗ്രഹീതർ; എന്തെന്നാൽ അവർ സംതൃപ്‌തരാകും","p":1},{"v":7,"t":"കരുണയുള്ളവർ അനുഗൃഹീതർ; എന്തെന്നാൽ അവർക്കു കരുണ ലഭിക്കും.","p":1},{"v":8,"t":"ഹൃദയശുദ്ധിയുള്ളവർ അനുഗ്രഹീതർ; എന്തെന്നാൽ അവർ ദൈവത്തെ കാണും","p":1},{"v":8,"t":"'","p":1},{"v":9,"t":"സമാധാനസ്ഥാപകർ അനുഗൃഹീതർ; എന്തെന്നാട് അവർ ദൈവപുത്രന്മാരെന്നു വിളിക്കപ്പെടും."},{"v":10,"t":"നീതി ക്കുവേണ്ടി പീഡനമേല്ക്കുന്നവർ അനുഗൃഹീതർ എന്തെന്നാൽ സ്വർഗരാജ്യം അവരുടേതാണ്.","p":1},{"v":11,"t":"എന്നെപ്രതി മനുഷ്യർ നിങ്ങളെ അവഹേളിക്കുകയും പീഡിപ്പിക്കുകയും എല്ലാവിധ തിന്മകളും നിങ്ങൾക്കെതിരേ വ്യാജമായി പറയുകയും ചെയ്യുമ്പോൾ നിങ്ങൾ അനുഗൃഹീതർ.","p":1},{"v":12,"t":"നിങ്ങൾ ആനന്ദിക്കുവിൻ, ആഹ്ലാദിക്കുവിൻ. എന്തെന്നാൽ സ്വർഗത്തിൽ നിങ്ങളുടെ പ്രതി ഫലം വലുതായിരിക്കും. നിങ്ങൾക്കു മുമ്പുണ്ടായിരുന്ന പ്രവാചകന്മാരെയും അവർ ഇപ്രകാരം പീഡിപ്പിച്ചിട്ടുണ്ട്.","p":1},{"h":"ഭൂമിയുടെ ഉപ്പും ലോകത്തിൻ്റെ പ്രകാശവും"},{"v":13,"t":"നിങ്ങൾ ഭൂമിയുടെ ഉപ്പാകുന്നു. ഉറ കെട്ടുപോയാൻ ഉപ്പിന് എങ്ങനെ വീണ്ടും ഉറകൂട്ടും? പുറത്തേക്കു വലിച്ചെറിഞ്ഞ് മനുഷ്യരാൽ ചവിട്ടപ്പെടാനല്ലാതെ മറെറാന്നിനും അതു കൊള്ളുകയില്ല.","p":1},{"v":14,"t":"നിങ്ങൾ ലോകത്തിൻ്റെ പ്രകാശമാകുന്നു. മലമുകളിൽ പണി തുയർത്തിയ പട്ടണം മറച്ചുവയ്ക്കുക സാദ്ധ്യമല്ല.","p":1},{"v":15,"t":"വിളക്ക് കൊളുത്തി ആരും പറയുടെ കീഴിൽ ചവയ്ക്കാറില്ല. ദീപപീഠത്തിന്മേലാണു വയ്ക്കുക. അപ്പോൾ അത് ഭവനത്തിലുള്ള എല്ലാവർക്കും വെളിച്ചമേകുന്നു.","p":1},{"v":16,"t":"അപ്രകാരം, മനുഷ്യർ നിങ്ങളുടെ സത്പ്രവൃത്തികൾ കണ്ട്, സ്വർഗസ്ഥനായ നിങ്ങളുടെ പിതാവിനെ മഹത്ത്വപ്പെടുത്തേണ്ടതിന് നിങ്ങളുടെ","p":1},{"v":16,"t":"വെളിച്ചം അവരുടെ മുമ്പിൽ പ്രകാശിക്കട്ടെ.","p":1},{"h":"നിയമത്തിന്റെ പൂർത്തീകരണം"},{"v":17,"t":"നിയമത്തെയോ പ്രവാചകരെയോ ഇല്ലാതാക്കാ നാണു ഞാൻ വന്നതെന്നു നിങ്ങൾ വിചാരിക്കരുത്. ഇല്ലാതാക്കാനല്ല, പൂർത്തിയാക്കാനാണ് ഞാൻ വന്നത്.","p":1},{"v":18,"t":"ആകാശവും ഭൂമിയും കടന്നുപോകുന്നതു വരെ, സമസ്‌തവും സംഭവിക്കുവോളം നിയമത്തിൽ നിന്നു വള്ളിയോ പുള്ളിയോ മാറുകയില്ലെന്നു സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു.","p":1},{"v":19,"t":"ഈ പ്രമാണങ്ങളിൽ ഏറ്റവും നിസ്സാരമായ ഒന്ന് ലംഘിക്കുകയും അപ്രകാരം മററുള്ളവരെ പഠിപ്പിക്കുകയും ചെയ്യുന്നവൻ സ്വർഗരാജ്യത്തിൽ ചെറിയവനെന്നു വിളിക്ക പ്പെടും. എന്നാൽ, അത് അനുസരിക്കുകയും പഠിപ്പിക്കുകയും ചെയ്യുന്നവൻ സ്വർഗരാജ്യത്തിൽ വലിയവനെന്നു വിളിക്കപ്പെടും.","p":1},{"v":20,"t":"കാരണം, നിങ്ങളുടെ നീതി നിയമജ്ഞരുടെയും ഫരിസേയരുടെയും നീതിയെ കവിഞ്ഞു നില്ക്കുന്നില്ലെങ്കിൽ, നിങ്ങൾ ഒരിക്കലും സ്വർഗരാജ്യത്തിൽ പ്രവേശിക്കുകയില്ലെന്നു ഞാൻ നിങ്ങളോടു പറയുന്നു.","p":1},{"h":"സഹോദരനുമായി രമ്യതപ്പെടുക"},{"v":21,"t":"കൊല്ലരുത്; കൊല്ലുന്നവൻ ന്യായവിധിക്കു വിധേയനാകും എന്നു പൂർവികരോടു പറയപ്പെട്ടതായി നിങ്ങൾ കേട്ടിട്ടുണ്ടല്ലോ.","p":1},{"v":22,"t":"എന്നാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു: സഹോദരനോടു കോപിക്കുന്നവൻ ന്യായവിധിക്കു വിധേയനാകും; സഹോദരനെ ഭോഷാ എന്നു വിളിക്കുന്നവൻ ന്യായാധിപസംഘത്തിനും വിഡ്ഢ‌ി എന്നു വിളിക്കുന്നവൻ നരകാഗ്നിക്കും വിധേയനാകും.","p":1},{"v":23,"t":"അതിനാൽ, നീ ബലിപീഠത്തിൽ കാഴ്ച യർപ്പിക്കുമ്പോൾ നിൻ്റെ സഹോദരന് നിന്നോട് എന്തെങ്കിലും വിരോധമുണ്ടെന്ന് അവിടെവച്ച് ഓർത്താൽ,","p":1},{"v":24,"t":"കാഴ്ചവസ്തു ബലിപീഠത്തിനുമുമ്പിൽ വച്ച ശേഷം, പോയി സഹോദരനോട് രമ്യതപ്പെടുക; പിന്നെ വന്ന് കാഴ്ചയർപ്പിക്കുക.","p":1},{"v":25,"t":"നീ പ്രതിയോഗിയോട് വഴി ക്കുവച്ചുതന്നെ വേഗം സൗഹൃദത്തിലാകുക. അല്ലെ ങ്കിൽ പ്രതിയോഗി നിന്നെ ന്യായാധിപനും ന്യായാധിപൻ സേവകനും ഏല്പിച്ചുകൊടുക്കും. അങ്ങനെ നീ കാരാഗൃഹത്തിൽ അടയ്ക്കപ്പെടും.","p":1},{"v":26,"t":"അവസാനത്തെ ചില്ലിക്കാശും കൊടുത്തുവീട്ടുവോളം നീഅവിടെനിന്നു പുറത്തുവരുകയില്ലെന്നു സത്യമായി ഞാൻ നിന്നോടു പറയുന്നു.","p":1},{"h":"വ്യഭിചാരം ചെയ്യരുത്"},{"v":27,"t":"വ്യഭിചാരം ചെയ്യരുത് എന്നു കല്പ്പിച്ചിട്ടുള്ളത് നിങ്ങൾ കേട്ടിട്ടുണ്ടല്ലോ.","p":1},{"v":28,"t":"എന്നാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു: ആസക്തിയോടെ സ്ത്രീയെ നോക്കുന്നവൻ ഹൃദയത്തിൽ അവളുമായി വ്യഭിചാരം ചെയ്തുകഴിഞ്ഞു.","p":1},{"v":29,"t":"വലത്തുകണ്ണ് നിനക്കു പാപ \" ഹേതുവാകുന്നെങ്കിൽ അതു ചുഴന്നെടുത്ത് എറിഞ്ഞു കളയുക. കാരണം, ശരീരം മുഴുവൻ നരകത്തിലേക്ക് എറിയപ്പെടുന്നതിനെക്കാൾ നല്ലത്, അവയവങ്ങളിലൊന്നു നഷ്ടപ്പെടുകയാണ്.","p":1},{"v":30,"t":"വലത്തുകരം നിനക്കു പാപഹേതുവാകുന്നെങ്കിൽ അതു വെട്ടി ദൂരെ എറി യുക. കാരണം, ശരീരം മുഴുവൻ നരകത്തിൽ പതിക്കു ന്നതിനെക്കാൾ നല്ലത്, അവയവങ്ങളിലൊന്നു നഷ്ടപ്പെടുകയാണ്","p":1},{"h":"വിവാഹമോചനം"},{"v":31,"t":"ഭാര്യയെ ഉപേക്ഷിക്കുന്നവൻ അവൾക്ക് ഉപേക്ഷാ പത്രം കൊടുക്കണം എന്നു കല്‌പിച്ചിട്ടുണ്ടല്ലോ.","p":1},{"v":32,"t":"എന്നാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു: പരസംഗം മൂലമല്ലാതെ ഭാര്യയെ ഉപേക്ഷിക്കുന്നവൻ അവളെക്കൊണ്ട് വ്യഭിചാരം ചെയ്യിക്കുന്നു; ഉപേക്ഷിക്കപ്പെട്ടവളെ പരിഗ്രഹിക്കുന്നവനും വ്യഭിചാരം ചെയ്യുന്നു.","p":1},{"h":"ആണയിടരുത്"},{"v":33,"t":"വ്യാജമായി ആണയിടരുത്; കർത്താവിനോടു ചെയ്ത ശപഥം നിറവേറ്റണം എന്നു പൂർവികരോടു കല്പ്പിച്ചിട്ടുള്ളതായി നിങ്ങൾ കേട്ടിട്ടുണ്ടല്ലോ.","p":1},{"v":34,"t":"എന്നാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു: ആണയിടുകയേ അരുത്. സ്വർഗത്തെക്കൊണ്ട് ആണയിടരുത്; കാരണം, അത് ദൈവത്തിൻ്റെ സിംഹാസനമാണ്.","p":1},{"v":35,"t":"ഭൂമിയെക്കൊണ്ടും ആണയിടരുത്, കാരണം, അത് അവിടത്തെ പാദപീഠമാണ്. ജറുസലേമിനെക്കൊണ്ടും അരുത്; കാരണം, അത് മഹാരാജാവിൻ്റെ നഗരമാണ്.","p":1},{"v":36,"t":"നിൻ്റെ ശിരസ്സിനെക്കൊണ്ടും ആണയിടരുത്; കാരണം, അതിലെ ഒരു മുടിയിഴ വെളുപ്പിക്കാനോ കറുപ്പി ക്കാനോ നിനക്കു സാധിക്കുകയില്ല.","p":1},{"v":37,"t":"എന്നാൽ, നിങ്ങളുടെ വാക്ക് അതേ, അതേ എന്നോ അല്ല, അല്ല എന്നോ ആയിരിക്കട്ടെ. ഇതിനപ്പുറമുള്ളതു തിന്മയിൽനിന്നു വരുന്നു.","p":1},{"h":"തിന്മയെ നന്മകൊണ്ടു ജയിക്കുക"},{"v":38,"t":"കണ്ണിനുപകരം കണ്ണ്, പല്ലിനുപകരം പല്ല് എന്നു പറഞ്ഞിട്ടുള്ളതു നിങ്ങൾ കേട്ടിട്ടുണ്ടല്ലോ.","p":1},{"v":39,"t":"എന്നാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു: ദുഷ്‌ടനെ എതിർക്കരുത്. വലത്തുകരണത്തടിക്കുന്നവന് മറ്റേകരണം കൂടി കാണിച്ചുകൊടുക്കുക.","p":1},{"v":40,"t":"നിന്നോടു വ്യവഹരിച്ച് നിന്റെ ഉടുപ്പു കരസ്ഥമാക്കാനുദ്യമിക്കുന്നവന് മേലങ്കികൂടി കൊടുത്തേക്കുക.","p":1},{"v":41,"t":"ഒരുമൈൽ പോകാൻ നിന്നെ നിർബന്ധിക്കുന്നവനോടുകൂടെ രണ്ടു മൈൽ പോകുക.","p":1},{"v":42,"t":"യാചിക്കുന്നവനു കൊടുക്കുക. നിന്നോടു കടം ചോദിക്കാൻ ആഗ്രഹിക്കുന്നവനിൽനിന്ന് ഒഴി ഞ്ഞുമാറരുത്.","p":1},{"h":"ശത്രുക്കളെ സ്നേഹിക്കുക"},{"v":43,"t":"അയല്ക്കാരനെ സ്നേഹിക്കുക, ശത്രുവിനെ ദ്വേഷിക്കുക എന്നുപറഞ്ഞിട്ടുള്ളത് നിങ്ങൾ കേട്ടിട്ടുണ്ടല്ലോ.","p":1},{"v":44,"t":"എന്നാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു ശത്രുക്കളെ സ്നേഹിക്കുവിൻ; നിങ്ങളെ പീഡിപ്പിക്കുന്നവർ ക്കുവേണ്ടി പ്രാർഥിക്കുവിൻ,","p":1},{"v":45,"t":"അങ്ങനെ, നിങ്ങൾ നിങ്ങളുടെ സ്വർഗസ്ഥനായ പിതാവിൻ്റെ മക്കളായി ത്തീരും. എന്തുകൊണ്ടെന്നാൽ, അവിടന്ന് ശിഷ്ടരുടെയും ദുഷ്ടരുടെയും മേൽ സൂര്യനെ ഉദിപ്പിക്കുകയും നീതിമാന്മാരുടെയും നീതിരഹിതരുടെയും മേൽ മഴപെയ്യിക്കുകയും ചെയ്യുന്നു.","p":1},{"v":46,"t":"എങ്കിൽ, നിങ്ങളെ സ്നേഹിക്കുന്നവരെ നിങ്ങൾ സ്നേഹിച്ചാൽ നിങ്ങ ൾക്ക് എന്തു പ്രതിഫലമാണു ലഭിക്കുക? ചുങ്കക്കാർ പോലും അതു ചെയ്യുന്നില്ലേ?","p":1},{"v":47,"t":"സഹോദരങ്ങളെ മാത്രമേ നിങ്ങൾ അഭിവാദനം ചെയ്യുന്നുള്ളൂവെങ്കിൽ, വിശേഷവിധിയായി എന്താണു നിങ്ങൾ ചെയ്യുന്നത്? വിജാതീയർ പോലും അതു ചെയ്യുന്നില്ലേ?","p":1},{"v":48,"t":"അതു കൊണ്ട്, നിങ്ങളുടെ സ്വർഗസ്ഥനായ പിതാവ് പരി പൂർണനായിരിക്കുന്നപോലെ നിങ്ങളും പരിപൂർണ രായിരിക്കുവിൻ.","p":1}],"6":[{"h":"ധർമദാനം"},{"v":1,"t":"നിങ്ങളുടെ സത്‌കർമ്മങ്ങൾ മറ്റുള്ളവരെ കാണി ക്കാൻവേണ്ടി അവരുടെ മുമ്പിൽവച്ച് അനുഷ്‌ഠി ക്കാതിരിക്കാൻ സൂക്ഷിക്കുക. അല്ലാത്തപക്ഷം, നിങ്ങളുടെ സ്വർഗസ്ഥനായ പിതാവിൻ്റെ പക്കൽ നിങ്ങൾക്കു പ്രതിഫലമുണ്ടാകില്ല.","p":1},{"v":2,"t":"മറ്റുള്ളവരിൽനിന്നു പ്രശംസ ലഭിക്കാൻ, കപടനാട്യക്കാർ സിനഗോഗുകളിലും തെരുവീഥികളിയും ചെയ്യുന്നപോലെ, നീ ഭിക്ഷ കൊടുക്കുമ്പോൾ നിൻ്റെ മുമ്പിൽ കാഹളം മുഴക്കരുത്. അവർക്കു പ്രതിഫലം ലഭിച്ച കഴിഞ്ഞു.","p":1},{"v":3,"t":"നീ ധർമദാനം ചെയ്യുമ്പോൾ നിൻ്റെ വലത്തുകൈ ചെയ്യുന്നത് ഇടത്തുകൈ അറിയാതിരി ക്കട്ടെ","p":1},{"v":4,"t":"'അങ്ങനെ നിൻ്റെ ധർമദാനം രഹസ്യമായിരി ക്കട്ടെ. രഹസ്യത്തിൽ കാണുന്ന നിൻ്റെ പിതാവ് നിനക്കു പ്രതിഫലം നല്‌കും.","p":1},{"h":"പ്രാർഥന"},{"v":5,"t":"നിങ്ങൾ പ്രാർഥിക്കുമ്പോൾ കപടനാട്യക്കാരെ പ്പോലെ ആകരുത്, അവർ മറ്റുള്ളവരെ കാണിക്കാൻ വേണ്ടി സിനഗോഗുകളിലും തെരുവീഥികളുടെ കോണുകളിലും നിന്നു പ്രാർഥിക്കാനാണ് ഇഷ്ടപ്പെടുന്നത്. സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു! അവർക്കു പ്രതിഫലം ലഭിച്ചുകഴിഞ്ഞു.","p":1},{"v":6,"t":"എന്നാൽ നീ പ്രാർഥിക്കുമ്പോൾ നിൻ്റെ മുറിയിൽ കടന്ന്, കതകടച്ച്, അദ്യശ്യനായ നിൻ്റെ പിതാവിനോടു പ്രാർഥിക്കുക; രഹസ്യത്തിൽ കാണുന്ന നിൻ്റെ പിതാവ് നിനക്കു പ്രതിഫലം നല്‌കും.","p":1},{"v":7,"t":"അതുപോലെ, പ്രാർഥിക്കുമ്പോൾ വിജാതീയരെപ്പോലെ നിങ്ങൾ ജല്പനം ചെയ്യരുത്. എന്തെന്നാൽ, അതിഭാഷണംവഴി തങ്ങളുടെ പ്രാർഥന കേൾക്കപ്പെടുമെന്ന് അവർ കരുതുന്നു.","p":1},{"v":8,"t":"നിങ്ങൾ അവരെപ്പോലെ ആകരുത്. എന്തെന്നാൽ, നിങ്ങൾ ചോദിക്കുന്നതിനുമുമ്പുതന്നെ നിങ്ങളുടെ ആവശ്യം നിങ്ങളുടെ പിതാവ് അറിയുന്നു.","p":1},{"h":"യേശു പഠിപ്പിച്ച പ്രാർഥന"},{"v":9,"t":"നിങ്ങൾ ഇപ്രകാരം പ്രാർഥിക്കുവിൻ സ്വർഗസ്ഥനായ ഞങ്ങളുടെ പിതാവേ, അങ്ങയുടെ നാമം പരിശുദ്ധമാക്കപ്പെടണമേ, അങ്ങയുടെ രാജ്യം വരണമേ.","p":1},{"v":10,"t":"അങ്ങയുടെ ഹിതം സ്വർഗത്തിലെപ്പോലെ ഭൂമിയിലുമാകണമേ.","p":1},{"v":11,"t":"അന്നന്നുവേണ്ട ആഹാരം ഇന്നു ഞങ്ങൾക്കു നല്കണമേ.","p":1},{"v":12,"t":"ഞങ്ങളുടെ കടക്കാരോടു ഞങ്ങൾ ക്ഷമിച്ചപോലെ ഞങ്ങളുടെ കടങ്ങൾ ഞങ്ങളോടും. \" ക്ഷമിക്കണമേ. തിന്മയിൽനിന്നു ഞങ്ങളെ രക്ഷിക്കണമേ.","p":1},{"v":13,"t":"ഞങ്ങളെ പ്രലോഭനത്തിൽ ഉൾപ്പെടുത്തരുതേ. തിന്മയിൽ നിന്ന് ഞങ്ങളെ രക്ഷിക്കേണമേ","p":1},{"v":14,"t":"മറ്റുള്ളവരുടെ തെററുകൾ നിങ്ങൾ ക്ഷമിക്കുമെങ്കിൽ, സ്വർഗസ്ഥനായ നിങ്ങളുടെ പിതാവ് നിങ്ങളോടുംക്ഷമിക്കും.","p":1},{"v":15,"t":"മററുള്ളവരോടു നിങ്ങൾ ക്ഷമികുകയില്ലെങ്കിൽ, നിങ്ങളുടെ പിതാവ് നിങ്ങളുടെ തെറ്റുകളും ക്ഷമിക്കുകയില്ല.","p":1},{"h":"ഉപവാസം"},{"v":16,"t":"നിങ്ങൾ ഉപവസിക്കുമ്പോൾ കപടനാട്യക്കാരെപ്പോലെ വിഷാദം ഭാവിക്കരുത്. തങ്ങൾ ഉപവസിക്കുന്നുവെന്ന് അന്യരെ കാണിക്കാൻവേണ്ടി അവർ മുഖം വിരൂപമാക്കുന്നു. സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു. അവർക്കു പ്രതിഫലം ലഭിച്ചുകഴിഞ്ഞു.","p":1},{"v":17,"t":"എന്നാൽ, നീ ഉപവസിക്കുമ്പോൾ ശിരസ്സിൽ തൈലം പുരട്ടുകയും മുഖം കഴുകുകയും ചെയ്യുക.","p":1},{"v":18,"t":"അങ്ങനെ. ഉപവസിക്കുന്നവനായി നിന്നെ അദൃശ്യനായ പിതാവല്ലാതെ മറ്റാരും കാണാതിരിക്കട്ടെ. രഹസ്യത്തിൽക്കാണുന്ന നിൻ്റെ പിതാവ് നിനക്ക് പ്രതിഫലം നല്കും","p":1},{"h":"യഥാർഥനിക്ഷേപം"},{"v":19,"t":"ഭൂമിയിൽ നിങ്ങൾക്കുവേണ്ടി നിക്ഷേപം കരുതി വയ്ക്കരുത്. തുരുമ്പും കീടങ്ങളും അവ നശിപ്പിക്കും. കള്ളന്മാർ തുരന്നെടുക്കുകയും മോഷ്ടിക്കുകയും ചെയ്യും.","p":1},{"v":20,"t":"എന്നാൽ, സ്വർഗത്തിൽ നിക്ഷേപങ്ങൾ","p":1},{"v":20,"t":"കരുതി വയ്ക്കുക അവിടെ തുരുമ്പും കീടങ്ങളും അവ നശിപ്പിക്കുകയില്ല.","p":1},{"v":21,"t":"കള്ളന്മാർ തുരന്നെടുക്കുകയോ മോഷ്ടിക്കുകയോ ഇല്ല എവിടെയാണോ നിങ്ങളുടെ നിക്ഷേപം അവിടെ ആയിരിക്കും നിങ്ങളുടെ ഹൃദയവും","p":1},{"h":"കണ്ണ് ശരീരത്തിന്റെ വിളക്ക്"},{"v":22,"t":"കണ്ണാണ് ശരീരത്തിൻ്റെ വിളക്ക്. ആകയാൽ നിൻ്റെ കണ്ണ് അന്യൂനമെങ്കിൽ ശരീരം പ്രകാശപൂർണമായിരിക്കും.","p":1},{"v":23,"t":"കണ്ണ് ദുഷ്ടമാണെങ്കിലോ, ശരീരം അന്ധ കാരത്തിലായിരിക്കും. അതിനാൽ, നിന്നിലെ പ്രകാശം അന്ധകാരമാണെങ്കിൽ ആ അന്ധകാരം എത്രയോ വലുതായിരിക്കും!","p":1},{"h":"രണ്ടു യജമാനന്മാർ"},{"v":24,"t":"രണ്ട് യജമാനന്മാരെ സേവിക്കാൻ ആർക്കും സാധിക്കുകയില്ല. കാരണം, ഒന്നുകിൽ, ഒരുവനെ ദ്വേഷിക്കുകയും അപരനെ സ്നേഹിക്കുകയും ചെയ്യും; അല്ലെങ്കിൽ, ഒരുവനെ ബഹുമാനിക്കുകയും അപരനെ നിന്ദിക്കുകയും ചെയ്യും. ദൈവത്തെയും മാമോനെയും ഒരുമിച്ചു സേവിക്കാൻ നിങ്ങൾക്കു സാധിക്കുകയില്ല.","p":1},{"h":"ദൈവപരിപാലനത്തിൽ ആശ്രയിക്കുക"},{"v":25,"t":"അതിനാൽ ഞാൻ നിങ്ങളോടു പറയുന്നു. എന്തു ഭക്ഷിക്കും, എന്തു പാനം ചെയ്യും എന്നു ജീവനെ ക്കുറിച്ചോ എന്തു ധരിക്കും എന്നു ശരീരത്തെകുറിച്ചോ നിങ്ങൾ ഉത്‌കണ്‌ഠാകുലരാകേണ്ടാ ഭക്ഷണത്തെക്കാൾ ജീവനും വസ്ത്രത്തെക്കാൾ ശരീരവും ശ്രേഷ്‌ഠമല്ലേ?","p":1},{"v":26,"t":"ആകാശപ്പറവകളെ നോക്കൂ വിൻ, അവ വിതയ്ക്കുന്നില്ല. കൊയ്യുന്നില്ല, കളപ്പുരയിൽ ശേഖരിക്കുന്നുമില്ല. എങ്കിലും, നിങ്ങളുടെ സ്വർഗസ്ഥനായ പിതാവ് അവയെ തീറ്റിപ്പോററുന്നു. അവയെക്കാൾ എത്രയോ വിലപ്പെട്ടവരാണു നിങ്ങൾ","p":1},{"v":27,"t":"ഉത്‌കണ്ഠമൂലം ആയുസ്സ് ഒരു വിനാഴികയെങ്കിലും കൂട്ടാൻ നിങ്ങളിലാർക്കെങ്കിലും സാധിക്കുമോ?","p":1},{"v":28,"t":"വസ്ത്രത്തെപ്പറ്റിയും നിങ്ങൾ എന്തിന് ആക ലരാകുന്നു? വയലിലെ ലില്ലികൾ എങ്ങനെ വളരുന്നു എന്നു നോക്കുക; അവ അധ്വാനിക്കുന്നില്ല, നൂല്കുന്നുമില്ല.","p":1},{"v":29,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു. സോളമൻപോലും തൻ്റെ സർവമഹത്ത്വത്തിലും ഇവയിൽ ഒന്നിനെപ്പോലെ അലംകൃതനായിരുന്നില്ല.","p":1},{"v":30,"t":"ഇന്നുള്ളതും നാളെ അടുപ്പിൽ എറിയപ്പെടുന്നതുമായ പുല്ലിനെ ദൈവം ഇപ്രകാരം അലങ്കരിക്കുന്നെങ്കിൽ അല്പവിശ്വാസികളേ നിങ്ങളെ അവിടന്ന് എത്രയധികം അലങ്കരിക്കുകയില്ല!","p":1},{"v":31,"t":"അതിനാൽ എന്തു ഭക്ഷിക്കും, എന്തു പാനംചെയ്യും, എന്തുധരിക്കും എന്നു വിചാരിച്ചു നിങ്ങൾ ആകുലരാകേണ്ടാ.","p":1},{"v":32,"t":"വിജാതീയരാണ് ഇവയെല്ലാം അന്വേഷിക്കുന്നത്. നിങ്ങൾക്കിവയെല്ലാം ആവശ്യമാണെന്ന് നിങ്ങളുടെ സ്വർഗീയപിതാവ് അറിയുന്നു.","p":1},{"v":33,"t":"നിങ്ങളാകട്ടെ, ആദ്യം അവിടത്തെ രാജ്യവും അവിടത്തെ നീതിയും അന്വേഷിക്കുവിൻ. അതോടൊപ്പം മറ്റുള്ള വയെല്ലാം നിങ്ങൾക്കു നല്കപ്പെടും.","p":1},{"v":34,"t":"അതിനാൽ നാളെയെക്കുറിച്ചു നിങ്ങൾ ആകുലരാകരുത്, നാളത്തെ ദിനംതന്നെ അതിനെക്കുറിച്ച് ആകുലപ്പെട്ടുകൊള്ളും.. ഓരോ ദിവസത്തിനും അതതിന്റെ ക്ലേശം മതി.","p":1}],"7":[{"v":1,"t":"വിധിക്കപ്പെടാതിരിക്കാൻ നിങ്ങളും വിധിക്കരുത്.","p":1},{"v":2,"t":"നിങ്ങൾ വിധിക്കുന്ന വിധിയാൽതന്നെ നിങ്ങളും വിധിക്കപ്പെടും. നിങ്ങൾ അളക്കുന്ന അളവുകൊണ്ടുതന്നെ നിങ്ങൾക്കും അളന്നുകിട്ടും.","p":1},{"v":3,"t":"നീ സഹോദരന്റെ കണ്ണിലെ കരടു കാണുകയും നിന്റെ കണ്ണിലെ തടിക്കഷ്ണം ശ്രദ്ധിക്കാതിരിക്കുകയും ചെയ്യുന്നതെന്തുകൊണ്ട്?","p":1},{"v":4,"t":"അഥവാ, നിന്റെ കണ്ണിൽ തടിക്കഷ്ണം ഇരിക്കേ, സഹോദരനോട്, ഞാൻ നിന്റെ കണ്ണിൽനിന്നു കരടെടുത്തു കളയട്ടെ എന്ന് എങ്ങനെ ചോദിക്കും?","p":1},{"v":5,"t":"കപടനാട്യക്കാരാ, ആദ്യം സ്വന്തം കണ്ണിൽനിന്നു തടിക്കഷ്ണം എടുത്തു മാറ്റുക അപ്പോൾ നിന്റെ സഹോദരന്റെ കണ്ണിലെ കരടെടുത്തുകളയാൻ തക്കവിധം വ്യക്തമായി നീ കാണും","p":1},{"v":6,"t":"വിശുദ്ധമായതു നായികൾക്കു കൊടുക്കരുത് നിങ്ങളുടെ മുത്തുകൾ പന്നികളുടെ മുൻപിൽ ഇട്ടുകൊടുക്കരുത് അവ മുത്തുകൾ ചവിട്ടി നശിപ്പിക്കുകയും തിരിഞ്ഞ് നിങ്ങളെ ആക്രമിക്കുകയും ചെയ്തേക്കാംപ്രാർത്ഥനയുടെ ശക്തി"},{"v":7,"t":"ചോദിക്കുവിൻ, നിങ്ങൾക്കു നൽകപ്പെടും; അന്വേഷിക്കുവിൻ, നിങ്ങൾ കണ്ടെത്തും; മുട്ടുവിൻ, നിങ്ങൾക്കു തുറന്നുകിട്ടും"},{"v":8,"t":"കാരണം, ചോദിക്കുന്ന ആർക്കും ലഭിക്കുന്നു; അന്വേഷിക്കുന്നവൻ കണ്ടെത്തുന്നു; മുട്ടുന്നവനു തുറക്കപ്പെടുകയും ചെയ്യുന്നു"},{"v":9,"t":"മകൻ അപ്പം ചോദിച്ചാൽ കല്ലുകൊടുക്കുന്ന ആരെങ്കിലും നിങ്ങളിലുണ്ടോ?"},{"v":10,"t":"അഥവാ, മീൻ ചോദിച്ചാൽ പാമ്പിനെ കൊടുക്കുമോ?","p":1},{"v":11,"t":"അതിനാൽ, മക്കൾക്കു നല്ലവസ്തുക്കൾ കൊടുക്കണമെന്ന് ദുഷ്ടരായ നിങ്ങൾക്കറിയാമെങ്കിൽ, നിങ്ങളുടെ സ്വർഗസ്ഥനായ പിതാവ്, തന്നോട് ചോദിക്കുന്നവർക്ക് എത്രയോ കൂടുതൽ നന്മകൾ നൽകും!","p":1},{"v":12,"t":"അതുകൊണ്ട്, മനുഷ്യർ നിങ്ങൾക്ക് ചെയ്തുതരണമെന്ന് നിങ്ങൾ ആഗ്രഹിക്കുന്നതെല്ലാം നിങ്ങളും അവർക്കു ചെയ്തുവിൻ ഇതാണ് നിയമവും പ്രവാചകന്മാരും ഇടുങ്ങിയ വാതിൽ","p":1},{"v":13,"t":"ഇടുങ്ങിയ വാതിലിലൂടെ പ്രവേശിക്കുവിൻ; വിനാശത്തിലേക്ക് നയിക്കുന്ന വാതിൽ വിസ്തൃതവും വഴി വിശാലവുമാണ്അതിലേ കടന്നുപോകുന്നവർ ഏറെയാണുതാനും"},{"v":14,"t":"എന്നാൽ, ജീവനിലേക്ക് നയിക്കുന്ന വാതിൽ ഇടുങ്ങിയതും വഴി ഞെരുങ്ങിയതുമാണ് അതു കണ്ടെത്തുന്നവരോ ചുരുക്കം വ്യാജപ്രവാചകന്മാർ"},{"v":15,"t":"ആടുകളുടെ വേഷത്തിൽ വരുന്ന വ്യാജപ്രവാചകന്മാരെ സൂക്ഷിക്കുക ഉള്ളുകൊണ്ടു, അവർ കടിച്ചുചീന്തുന്ന ചെന്നായ്ക്കളാണ്"},{"v":16,"t":"ഫലങ്ങളിൽനിന്ന് അവരെ തിരിച്ചറിയാംമുൾച്ചെടിയിൽ നിന്ന് മുന്തിരിപ്പഴമോ ഞെരിഞ്ഞിലിൽ നിന്ന് അത്തിപ്പഴമോ പറിക്കാറുണ്ടോ?"},{"v":17,"t":"നല്ലവൃക്ഷം നല്ലഫലവും ചീത്തവൃക്ഷം ചീത്തഫലവും നൽകുന്നു","p":1},{"v":18,"t":"നല്ലവൃക്ഷത്തിനു ചീത്തഫലങ്ങളോ ചീത്തവൃക്ഷത്തിനു നല്ലഫലങ്ങളോ പുറപ്പെടുവിക്കാൻ സാധിക്കുകയുമില്ല."},{"v":19,"t":"നല്ലഫലം നല്കാത്ത വൃക്ഷങ്ങളെല്ലാം വെട്ടി തീയിലിറിയപ്പെടും.","p":1},{"v":20,"t":"അവരുടെ ഫലങ്ങളിൽനിന്ന് നിങ്ങൾ അവരെ തിരിച്ചറിയും.","p":1},{"h":"യഥാർഥശിഷ്യൻ"},{"v":21,"t":"കർത്താവേ, കർത്താവേ എന്ന് എന്നെ വിളിക്കുന്ന ഏവരുമല്ല, സ്വർഗസ്ഥനായ എന്റെ പിതാവിന്റെ ഇഷ്ടം നിറവേറ്റുന്നവനാണ്, സ്വർഗരാജ്യത്തിൽ പ്രവേശിക്കുന്നത്.","p":1},{"v":22,"t":"അന്ന് പലരും എന്നോട് ചോദിക്കും: കർത്താവേ, കർത്താവേ, ഞങ്ങൾ നിന്റെ നാമത്തിൽ പ്രവചിക്കുകയും നിന്റെ നാമത്തിൽ പിശാചുക്കളെ പുറത്താക്കുകയും നിന്റെ നാമത്തിൽ നിരവധി അത്ഭുതങ്ങൾ പ്രവർത്തിക്കുകയും ചെയ്തില്ലേ?","p":1},{"v":23,"t":"അപ്പോൾ ഞാൻ അവരോട് പറയും: നിങ്ങളെ ഞാൻ ഒരിക്കലും അറിഞ്ഞിട്ടില്ല; അനീതി പ്രവർത്തിക്കുന്നവരേ, നിങ്ങൾ എന്നിൽ നിന്ന് അകന്നുപോകൂവിൻ രണ്ട് അടിസ്ഥാനങ്ങൾ","p":1},{"v":24,"t":"അതിനാൽ, എന്റെ ഈ വചനങ്ങൾ ശ്രദ്ധിക്കുകയും അവ അനുസരിക്കുകയും ചെയ്യുന്നവൻ പാറമേൽ ഭവനം പണിത വിവേകമതിയായ മനുഷ്യനു തുല്യനായിരിക്കും."},{"v":25,"t":"മഴപെയ്തു, വെള്ളപ്പൊക്കമുണ്ടായി; കാറ്റൂതി, അതു ഭവനത്തിന്മേൽ ആഞ്ഞടിച്ചു. എന്നിട്ടും അതു വീണില്ല. എന്തുകൊണ്ടെന്നാൽ, അതു പാറമേൽ സ്ഥാപിതമായിരുന്നു.","p":1},{"v":26,"t":"എന്റെ ഈ വചനങ്ങൾ കേൾക്കുകയും എന്നാൽ അവ അനുസരിക്കാതിരിക്കുകയും ചെയ്യുന്നവൻ മണൽപ്പുറത്തു ഭവനം പണിത ഭോഷനു തുല്യനായിരിക്കും.","p":1},{"v":27,"t":"മഴപെയ്തു, വെള്ളപ്പൊക്കമുണ്ടായി; കാറ്റൂതി, അതു ഭവനത്തിന്മേൽ ആഞ്ഞടിച്ചു, അതു വീണുപോയി. അതിന്റെ വീഴ്ച വലുതായിരുന്നു.","p":1},{"v":28,"t":"അങ്ങനെ യേശു ഈ വചനങ്ങൾ അവസാനിപ്പിച്ചപ്പോൾ, ജനക്കൂട്ടം അവന്റെ പ്രബോധനത്തെപ്പറ്റി വിസ്മയിച്ചു. എന്തെന്നാൽ അവരുടെ നിയമജ്ഞരെപ്പോലെയല്ല, അധികാരമുള്ളവനെപ്പോലെയാണ് അവൻ പഠിപ്പിച്ചത്.","p":1}],"8":[{"h":"കുഷ്ഠരോഗിക്ക് സൗഖ്യം ലഭിക്കുന്നു"},{"v":1,"t":"യേശു മലയിൽനിന്ന് ഇറങ്ങിവന്നപ്പോൾ വലിയ ജനക്കൂട്ടം അവനെ അനുഗമിച്ചു.","p":1},{"v":2,"t":"അപ്പോൾ ഒരുകുഷ്ഠരോഗി അടുത്തുവന്ന് താണുവണങ്ങിപ്പറഞ്ഞു. കർത്താവേ, അങ്ങു മനസ്സാകുന്നെങ്കിൽ എന്നെ ശുദ്ധനാക്കാൻ കഴിയും.","p":1},{"v":3,"t":"യേശു കൈനീട്ടി അവനെ സ്‌പർശിച്ചുകൊണ്ട് അരുൾ ചെയ്തു‌: ഞാൻ മനസ്സാകുന്നു, നീ ശുദ്ധനാകട്ടെ. തത്ക്ഷണം അവൻ്റെ കുഷ്ഠരോഗം ശുദ്ധമാക്കപ്പെട്ടു.","p":1},{"v":4,"t":"യേശു അവനോടു പറഞ്ഞു: നീ ഇത് ആരോടും പറയരുത്, പോയി നിന്നെത്തന്നെ പുരോഹിതനു കാണിച്ചുകൊടുക്കുകയും മോശ കല്പ്‌പിച്ചിട്ടുള്ള കാഴ്‌ച അവരുടെ സാക്ഷ്യത്തിനായി സമർപ്പിക്കുകയും ചെയ്യുക.","p":1},{"h":"ശതാധിപന്റെ ഭൃത്യൻ"},{"v":5,"t":"യേശു കഫർണാമിൽ പ്രവേശിച്ചപ്പോൾ ഒരു ശതാധിപൻ അവന്റെ അടുക്കൽ വന്ന് യാചിച്ചു:","p":1},{"v":6,"t":"കർത്താവേ, എൻ്റെ ഭൃത്യൻ തളർവാതം പിടിപെട്ട്, കഠിനവേദനയനുഭവിച്ച് വീട്ടിൽ കിടക്കുന്നു. '","p":1},{"v":7,"t":"യേശു അവനോടു പറഞ്ഞു: ഞാൻവന്ന് അവനെ സുഖപ്പെടുത്താം.","p":1},{"v":8,"t":"അപ്പോൾ ശതാധിപൻ പ്രതിവചിച്ചു: കർത്താവേ, നീ എന്റെ ഭവനത്തിൽ പ്രവേശിക്കാൻ ഞാൻ യോഗ്യനല്ല. നീ ഒരു വാക്ക് ഉച്ചരിച്ചാൽ മാത്രം മതി, എൻ്റെ ഭൃത്യൻ സുഖപ്പെടും.","p":1},{"v":9,"t":"കാരണം, ഞാനും അധികാരത്തിനു കീഴ്പ്പെട്ടവനാണ്. എൻ്റെ കീഴിലും പടയാളികളുണ്ട്. ഞാൻ ഒരുവനോടു പോകാൻ പറയുന്നു, അവൻ പോകുന്നു; അപരനോട് വരാൻപറയുന്നു, അവൻ വരുന്നു. എൻ്റെ ദാസനോട് ഇതു ചെയ്യാൻ പറയുന്നു, അവൻ ചെയ്യുന്നു.","p":1},{"v":10,"t":"യേശു ഇതു കേട്ട് ആശ്ചര്യപ്പെട്ട്, തന്നെ അനുഗമിച്ചിരുന്നവരോടു പറഞ്ഞു: സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ഇത്ര വലിയ വിശ്വാസം ഇസ്രായേലിൽ ഒരുവനിലും ഞാൻ കണ്ടിട്ടില്ല.","p":1},{"v":11,"t":"വീണ്ടും ഞാൻ നിങ്ങളോടു പറയുന്നു, കിഴക്കുനിന്നും പടിഞ്ഞാറുനിന്നും നിരവധിയാളുകൾ വന്ന് അബ്രാഹത്തോടും ഇസഹാക്കിനോടും യാക്കോബിനോടും കൂടെ സ്വർഗരാജ്യത്തിൽ വിരുന്നിനിരിക്കും.","p":1},{"v":12,"t":"രാജ്യത്തിൻ്റെ മക്കളാകട്ടെ, പുറത്തുള്ള അന്ധകാരത്തിലേക്ക് എറിയപ്പെടും. അവിടെ കരച്ചിലും പല്ലു കടിയുമായിരിക്കും."},{"v":13,"t":"യേശു ശതാധിപനോടു പറഞ്ഞു: പൊയ്ക്കൊൾക; വിശ്വസിച്ചപോലെ നിനക്കു ഭവിക്കട്ടെ. ആ സമയംതന്നെ ഭൃത്യൻ സൗഖ്യം","p":1},{"h":"പത്രോസിൻ്റെ ഭവനത്തിൽ"},{"v":14,"t":"യേശു പത്രോസിൻ്റെ വീട്ടിലെത്തിയപ്പോൾ അവൻ്റെ അമ്മായിയമ്മ പനി പിടിച്ചുകിടക്കുന്നതു കണ്ടു.","p":1},{"v":15,"t":"അവൻ അവളുടെ കൈയിൽ സ്‌പർശിച്ചു: പനി അവളെ വിട്ടുമാറി. അവൾ എഴുന്നേറ്റ് അവനെ ശുശ്രൂ ഷിച്ചു.","p":1},{"v":16,"t":"സായാഹ്നമായപ്പോൾ അനേകം പിശാചു ബാധിതരെ അവർ അവൻ്റെയടുത്തു കൊണ്ടുവന്നു. അവൻ അശുദ്ധാത്മാക്കളെ ഒരു വാക്കുകൊണ്ടു പുറത്താക്കുകയും എല്ലാ രോഗികളെയും സുഖപ്പെടുത്തുകയും ചെയ്‌തു.","p":1},{"v":17,"t":"അവൻ നമ്മുടെ ബലഹീനതകൾ ഏറെറടുക്കുകയും രോഗങ്ങൾ വഹിക്കുകയും ചെയ്‌തു എന്ന് ഏശയ്യാ പ്രവാചകനിലൂടെ പറയ പ്പെട്ടത് അങ്ങനെ പൂർത്തിയായി.","p":1},{"h":"ശിഷ്യത്വം ത്യാഗം ആവശ്യപ്പെടുന്നു"},{"v":18,"t":"തൻ്റെ ചുററും ജനക്കൂട്ടത്തെ കണ്ടപ്പോൾ മറുകരയ്ക്കു പുറപ്പെടാൻ യേശു കല്പിച്ചു.","p":1},{"v":19,"t":"ഒരു നിയമജ്ഞൻ അവനെ സമീപിച്ചുപറഞ്ഞു: ഗുരോ, നീ പോകുന്നിടത്തെല്ലാം ഞാൻ നിന്നെ അനുഗമിക്കും.","p":1},{"v":20,"t":"യേശു പറഞ്ഞു: കുറുനരികൾക്കു മാളങ്ങളും ആകാശപ്പറവകൾക്കു കൂടുകളുമുണ്ട്; എന്നാൽ, മനുഷ്യപുത്രനു തലചായ്ക്കാൻ ഇടമില്ല","p":1},{"v":21,"t":"ശിഷ്യന്മാരിൽ മറ്റൊരുവൻ അവനോടു പറഞ്ഞു: കർത്താവേ, പോയി. എൻ്റെ പിതാവിനെ സംസ്കരിച്ചിട്ടുവരാൻ എന്നെ അനുവദിക്കണമേ."},{"v":22,"t":"എന്നാൽ, യേശു അവനോടു പറഞ്ഞു: എന്നെ അനുഗമിക്കുക; മരിച്ചവർ തങ്ങളുടെ മരിച്ചവരെ സംസ്കരിക്കട്ടെ.","p":1},{"h":"കൊടുങ്കാറ്റു ശാന്തമാക്കുന്നു"},{"v":23,"t":"യേശു തോണിയിൽ കയറിയപ്പോൾ ശിഷ്യന്മാർ അവനെ അനുഗമിച്ചു.","p":1},{"v":24,"t":"കടലിൽ ഉഗ്രമായ കൊടുങ്കാ ററുണ്ടായി. തോണി മുങ്ങത്തക്കവിധം തിരമാലകൾ ഉയർന്നു. അവൻ ഉറങ്ങുകയായിരുന്നു.","p":1},{"v":25,"t":"ശിഷ്യന്മാർ അടുത്തുചെന്ന് അവനെ ഉണർത്തി അപേക്ഷിച്ചു: കർത്താവേ, രക്ഷിക്കണമേ. ഞങ്ങൾ ഇതാ നശിക്കുന്നു.","p":1},{"v":26,"t":"അവൻ പറഞ്ഞു: അല്പ‌വിശ്വാസികളേ, നിങ്ങളെന്തിനു ഭയപ്പെടുന്നു? അവൻ എഴുന്നേറ്റ്, കാറ്റിനെയും കടലിനെയും ശാസിച്ചു; വലിയ ശാന്തതയുണ്ടായി.","p":1},{"v":27,"t":"അവർ ആശ്ചര്യപ്പെട്ടു പറഞ്ഞു: ഇവൻ ആര്? കാറ്റും കടലുംപോലും ഇവനെ അനുസരിക്കു ന്നല്ലോ!","p":1},{"h":"പിശാചുബാധിതരെ സുഖപ്പെടുത്തുന്നു"},{"v":28,"t":"യേശു മറുകരെ, ഗദറായരുടെ ദേശത്തെത്തി യപ്പോൾ, ശവക്കല്ലറകളിൽ നിന്ന് ഇറങ്ങിവന്ന രണ്ടു പിശാചുബാധിതർ അവനെ കണ്ടുമുട്ടി. ആർക്കും ആ വഴി സഞ്ചരിക്കാൻ സാധിക്കാത്തവിധം അവർ അപകടകാരികളായിരുന്നു.","p":1},{"v":29,"t":"അവർ അട്ടഹസിച്ചു പറഞ്ഞു: ദൈവപുത്രാ, ഞങ്ങൾക്കും നിനക്കുമെന്ത്? സമയത്തിനുമുമ്പ് ഞങ്ങളെ പീഡിപ്പിക്കാൻ നീ ഇവിടെ വന്നിരിക്കുകയാണോ?","p":1},{"v":30,"t":"അവരിൽനിന്ന് അല്പമകലെ വലിയൊരു പന്നിക്കൂട്ടം തീറ്റതിന്നുന്നുണ്ടായിരുന്നു.","p":1},{"v":31,"t":"പിശാചുക്കൾ അവനോട് അപേക്ഷിച്ചു: നീ ഞങ്ങളെ പുറത്താക്കുന്നെങ്കിൽ ആ പന്നിക്കൂട്ടത്തിലേക്കയയ്കണമെ","p":1},{"v":32,"t":"അവൻ പറഞ്ഞു പൊയ്ക്കൊള്ളൂ. അവ പുറത്തുവന്ന് പന്നികളിൽ പ്രവേശിച്ചു. പന്നിക്കൂട്ടം മുഴുവൻ കീഴ്ക്കാംതൂക്കായ ചരിവിലൂടെ പാഞ്ഞുചെന്ന് കടലിൽ മുങ്ങിച്ചത്തു.","p":1},{"v":33,"t":"പന്നിയെ തീറ്റുന്നവർ ഭയപ്പെട്ടോടി, പട്ടണത്തിലെത്തി; എല്ലാക്കാര്യങ്ങളും, പിശാചുബാധിതർക്കു സംഭവിച്ചതും, അറിയിച്ചു.","p":1},{"v":34,"t":"അപ്പോൾ, പട്ടണം മുഴുവൻ യേശുവിനെ കാണാൻ പുറപ്പെട്ടുവന്നു. അവർ അവനെ കണ്ട പ്പോൾ തങ്ങളുടെ അതിർത്തി വിട്ടുപോകണമെന്ന് അപേക്ഷിച്ചു.","p":1}],"9":[{"h":"തളർവാതരോഗിയെ സുഖപ്പെടുത്തുന്നു"},{"v":1,"t":"യേശു തോണിയിൽക്കയറി അക്കരയ്ക്കു കടന്ന് സ്വന്തം പട്ടണത്തിലെത്തി.","p":1},{"v":2,"t":"അവർ ഒരു തളർവാതരോഗിയെ കിടക്കയോടെ അവൻ്റെ അടുക്കൽ കൊണ്ടുവന്നു. അവരുടെ വിശ്വാസം കണ്ട് അവൻ തളർവാതരോഗിയോട് അരുൾചെയ്‌തു: മകനേ, ധൈര്യത്തോടെയിരിക്കുക; നിന്റെ പാപങ്ങൾ ക്ഷമിക്കപ്പെട്ടിരിക്കുന്നു.","p":1},{"v":3,"t":"അപ്പോൾ നിയമജ്ഞരിൽ ചിലർ പരസ്‌പരം പറഞ്ഞു: ഇവൻ ദൈവദൂഷണം പറയുന്നു.","p":1},{"v":4,"t":"അവരുടെ വിചാരങ്ങൾ ഗ്രഹിച്ച യേശു ചോദിച്ചു: നിങ്ങൾ ഹൃദയത്തിൽ തിന്മ വിചാരിക്കുന്നതെന്ത്?","p":1},{"v":5,"t":"ഏതാണ് എളുപ്പം; നിൻ്റെ പാപങ്ങൾ ക്ഷമിക്കപ്പെട്ടിരിക്കുന്നു എന്നു പറയുന്നതോ എഴുന്നേറ്റുനടക്കുക എന്നു പറയുന്നതോ?","p":1},{"v":6,"t":"ഭൂമിയിൽ പാപങ്ങൾ ക്ഷമിക്കാൻ മനുഷ്യപുത്രന് അധികാരമുണ്ടെന്നു നിങ്ങൾ അറിയേണ്ടതിന് അവൻ അപ്പോൾ തളർവാതരോഗിയോടു പറഞ്ഞു -എഴുന്നേറ്റ് കിടക്കയെടുത്ത് നിൻ്റെ വീട്ടിലേക്കുപോകുക.","p":1},{"v":7,"t":"അവൻ എഴുന്നേറ്റ് വീട്ടിലേക്കു പോയി."},{"v":8,"t":"ജനക്കൂട്ടം ഇതുകണ്ടു ഭയപ്പെട്ട്, മനുഷ്യർക്ക് ഇത്തരം അധികാരം നല്കിയ ദൈവത്തെ മഹത്ത്വപ്പെടുത്തി.","p":1},{"h":"മത്തായിയെ വിളിക്കുന്നു"},{"v":9,"t":"യേശു അവിടെനിന്നു നടന്നുനീങ്ങവേ, മത്തായി എന്നൊരാൾ ചുങ്കസ്ഥലത്ത് ഇരിക്കുന്നതുകണ്ടു. യേശു അവനോടു പറഞ്ഞു: എന്നെ അനുഗമിക്കുക. അവൻ എഴുന്നേറ്റ് യേശുവിനെ അനുഗമിച്ചു.","p":1},{"v":10,"t":"യേശു അവന്റെ ഭവനത്തിൽ ഭക്ഷണത്തിനിരുന്നപ്പോൾ അനേകം ചുങ്കക്കാരും പാപികളും വന്ന്, അവനോടും ശിഷ്യന്മാരോടുംകൂടെ ഭക്ഷണത്തിനിരുന്നു.","p":1},{"v":11,"t":"ഫരിസേയർ ഇതുകണ്ട് ശിഷ്യന്മാരോടു ചോദിച്ചു നിങ്ങളുടെ ഗുരു ചുങ്കക്കാരോടും പാപികളോടും കൂടെ ഭക്ഷിക്കുന്നതെന്തുകൊണ്ട്."},{"v":12,"t":"ഇതുകേട്ട അവൻ പറഞ്ഞു: ആരോഗ്യമുള്ളവർക്കല്ല രോഗികൾക്കാണ് വൈദ്യനെക്കൊണ്ട് ആവശ്യം.","p":1},{"v":13,"t":"ബലിയല്ല. കരുണയാണു ഞാൻ ആഗ്രഹിക്കുന്നത് എന്നതിൻ്റെ അർഥം നിങ്ങൾ പോയി പഠിക്കുവിൻ. എന്തെന്നാൽ ഞാൻ വന്നത് നീതിമാന്മാരെയല്ല, പാപികളെ വിളിക്കാനാണ്.","p":1},{"h":"ഉപവാസത്തെക്കുറിച്ച് തർക്കം"},{"v":14,"t":"യോഹന്നാന്റെ ശിഷ്യന്മാർ യേശുവിന്റെ അടുത്തു വന്നു ചോദിച്ചു: ഞങ്ങളും ഫരിസേയരും ഉപവസിക്കുകയും നിന്റെ ശിഷ്യന്മാർ ഉപവസിക്കാതിരിക്കു കയും ചെയ്യുന്നത് എന്തുകൊണ്ട്?","p":1},{"v":15,"t":"അവൻ അവരോടു പറഞ്ഞു: മണവാളൻ കൂടെയുള്ളപ്പോൾ മണ വറത്തോഴർക്ക് ദുഃഖമാചരിക്കാനാകുമോ? മണവാളൻ അവരിൽനിന്ന് എടുക്കപ്പെടുന്ന ദിവസങ്ങൾ വരും അപ്പോൾ അവർ ഉപവസിക്കും.","p":1},{"v":16,"t":"ആരും പഴയ വസ്ത്രത്തിൽ പുതിയ തുണിക്കഷണം തുന്നിപ്പിടിപ്പിക്കാറില്ല. അങ്ങനെ ചെയ്‌താൽ, തയ്ച്ചുചേർത്ത തുണി ക്കഷണം വസ്ത്രത്തിൽ നിന്നു കീറിപ്പോരുകയും കീറൽ വലുതാകുകയും ചെയ്യും.","p":1},{"v":17,"t":"ആരും പുതിയ വീഞ്ഞ് പഴയ തോല്‌ക്കുടങ്ങളിൽ ഒഴിച്ചുവയ്ക്കാറില്ല അങ്ങനെ ചെയ്‌താൽ തോല്ക്കുടങ്ങൾ പൊട്ടി വീഞ്ഞ് ഒഴുകിപ്പോകുകയും കുടങ്ങൾ നഷ്ടപ്പെടു കയും ചെയ്യും. അതിനാൽ, പുതിയ വീഞ്ഞ് പുതിയ തോല്ക്കുടങ്ങളിലാണ് ഒഴിച്ചുവയ്ക്കുന്നത്. അപ്പോൾ രണ്ടും ഭദ്രമായിരിക്കും.","p":1},{"v":17,"t":"രക്തസ്രാവക്കാരി; ഭരണാധിപൻ്റെ മകൾ","p":1},{"v":18,"t":"\"അവൻ അവരോടു സംസാരിച്ചുകൊണ്ടിരിക്കു മ്പോൾ ഒരു ഭരണാധികാരി അവനെ സമീപിച്ച് താണു വണങ്ങിക്കൊണ്ടു പറഞ്ഞു: എന്റെ മകൾ ഇപ്പോൾ മരിച്ചതേയുള്ളൂ. എന്നാൽ, നീ വന്ന് അവളുടെമേൽ കൈവയ്ക്കുമെങ്കിൽ അവൾ ജീവിക്കും.","p":1},{"v":19,"t":"യേശുവും ശിഷ്യന്മാരും അവനോടൊപ്പം പോയി.","p":1},{"v":20,"t":"പന്ത്രണ്ടുവർഷമായി രക്തസ്രാവം നിമിത്തം കഷ്ടപ്പെട്ടിരുന്ന \" ഒരു സ്ത്രീ പിന്നിലൂടെ വന്ന് അവൻ്റെ വസ്ത്രത്തിൻ്റെ വിളുമ്പിൽ സ്‌പർശിച്ചു.","p":1},{"v":21,"t":"അവൻ്റെ വസ്ത്രത്തിൽ ഒന്നു സ്‌പർശിച്ചാൽ മാത്രം മതി, താൻ സുഖംപ്രാ പിക്കും എന്ന് അവൾ ഉള്ളിൽ വിചാരിച്ചിരുന്നു."},{"v":22,"t":"യേശു തിരിഞ്ഞ് അവളെ നോക്കി അരുൾ ചെയ്തു.മകളേ, ധൈര്യത്തോടെയിരിക്കുക; നിൻ്റെ വിശ്വാസം നിന്നെ രക്ഷിച്ചിരിക്കുന്നു. ആ നിമിഷം അവൾ സുഖം പ്രാപിച്ചു.","p":1},{"v":23,"t":"യേശു ഭരണാധികാരിയുടെ ഭവനത്തിലെത്തി, കുഴലൂത്തുകാരെയും ആരവമുണ്ടാക്കുന്ന ജനക്കൂട്ടത്തെയും കണ്ട് പറഞ്ഞു:","p":1},{"v":24,"t":"നിങ്ങൾ പുറത്തു പോകുവിൻ, ബാലിക മരിച്ചിട്ടില്ല; അവൾ ഉറങ്ങുകയാണ്. അവരാകട്ടെ, അവനെ പരിഹസിച്ചു.","p":1},{"v":25,"t":"ജനക്കൂട്ടത്തെ പുറത്താക്കിയശേഷം അവൻ അകത്തു കടന്ന്, അവളെ കൈപിടിച്ച് ഉയർത്തി. അപ്പോൾ ബാലിക എഴുന്നേററു.","p":1},{"v":26,"t":"ഈ വാർത്ത ആ നാട്ടിലെങ്ങും പരന്നു.","p":1},{"h":"അന്ധർക്കു കാഴ്‌ചനല്‌കുന്നു"},{"v":27,"t":"യേശു അവിടെനിന്നു കടന്നുപോകുമ്പോൾ, രണ്ട് അന്ധന്മാർ, ദാവീദിൻ്റെ പുത്രാ, ഞങ്ങളിൽ കനിയണമേ എന്ന് കരഞ്ഞപേക്ഷിച്ചുകൊണ്ട് അവനെ അനുഗമിച്ചു.","p":1},{"v":28,"t":"അവൻ ഭവനത്തിലെത്തിയപ്പോൾ ആ അന്ധന്മാർ അവന്റെ സമീപംചെന്നു. യേശു അവരോടു ചോദിച്ചു: എനിക്ക് ഇതു ചെയ്യാൻ കഴിയുമെന്ന് നിങ്ങൾ വിശ്വസിക്കുന്നുവോ? ഉവ്വ്, കർത്താവേ എന്ന് അവർ മറുപടി പറഞ്ഞു.","p":1},{"v":29,"t":"നിങ്ങളുടെ വിശ്വാസം പോലെ നിങ്ങൾക്കു ഭവിക്കട്ടെ എന്നു പറഞ്ഞു കൊണ്ട് അവൻ അവരുടെ കണ്ണുകളിൽ സ്‌പർശിച്ചു. അവരുടെ കണ്ണുകൾ തുറക്കപ്പെട്ടു.","p":1},{"v":30,"t":"ഇത് ആരും അറി യാനിടയാകരുതെന്ന് യേശു അവരോടു കർക്കശമായി നിർദേശിച്ചു.","p":1},{"v":31,"t":"എന്നാൽ, അവർ പോയി അവൻ്റെ കീർത്തി നാടെങ്ങും പരത്തി. ഔ","p":1},{"v":31,"t":"ഊമയെ സുഖമാക്കുന്നു.","p":1},{"v":32,"t":"അവർ പൊയ്ക്കഴിഞ്ഞപ്പോൾ പിശാചുബാധിതനായ ഒരു ഊമയെ ജനങ്ങൾ അവന്റെയടുക്കൽ കൊണ്ടുവന്നു.","p":1},{"v":33,"t":"അവൻ പിശാചിനെ പുറത്താക്കിയപ്പോൾ ആ ഊമ സംസാരിച്ചു. ജനങ്ങൾ അദ്ഭുതപ്പെട്ടു പറഞ്ഞു: ഇതുപോലൊരു സംഭവം ഇസ്രായേലിൽ ഒരിക്കലും കണ്ടിട്ടില്ല.","p":1},{"v":34,"t":"എന്നാൽ, ഫരിസേയർ പറഞ്ഞു: അവൻ പിശാചുക്കളുടെ തലവനെക്കൊണ്ടാണ് പിശാചുക്കളെ ബഹിഷ്‌കരിക്കുന്നത്."},{"h":"വിളവിന്റെ നാഥനോടു പ്രാർഥിക്കുവിൻ"},{"v":35,"t":"യേശു അവരുടെ സിനഗോഗുകളിൽ പഠിപ്പിച്ചും രാജ്യത്തിന്റെ സുവിശേഷം പ്രഘോഷിച്ചും എല്ലാ രോഗങ്ങളും വ്യാധികളും സുഖപ്പെടുത്തിയും എല്ലാനഗരങ്ങളിലും ഗ്രാമങ്ങളിലും ചുറ്റി സഞ്ചരിച്ചു.","p":1},{"v":36,"t":"ജനക്കൂട്ടത്തെ കണ്ടപ്പോൾ, യേശുവിന് അവരോട് അനുകമ്പതോന്നി, അവർ ഇടയനില്ലാത്ത ആടുകളെപ്പോലെ പരിഭ്രാന്തരും നിസ്സഹായരുമായിരുന്നു.","p":1},{"v":37,"t":"അവൻ ശിഷ്യന്മാരോടു പറഞ്ഞു: വിളവധികം; വേലക്കാരോ ചുരുക്കം അതിനാൽ തൻ്റെ വിളഭൂമിയിലേക്കു വേലക്കാരെ അയയ്ക്കാൻ വിളവിന്റെ നാഥനോടു പ്രാർഥിക്കുവിൻ.","p":1}],"10":[{"h":"അപ്പസ്തോലന്മാരെ അയക്കുന്നു"},{"v":1,"t":"അവൻ തന്റെ പന്ത്രണ്ടുശിഷ്യന്മാരെ വിളിച്ച്, അശുദ്ധാത്മാക്കളെ ബഹിഷ്കരിക്കാനും എല്ലാ രോഗങ്ങളും വ്യാധികളും സുഖപ്പെടുത്താനുമായി അവർക്ക് അധികാരം നൽകി.","p":1},{"v":2,"t":"ആ പന്ത്രണ്ടു അപ്പസ്തോലന്മാരുടെ പേരുകൾ: ഒന്നാമൻ, പത്രോസ് എന്നു വിളിക്കപ്പെടുന്ന ശിമയോൻ, അവന്റെ സഹോദരൻ അന്ത്രയോസ്, സെബദിയുടെ പുത്രനായ യാക്കോബ്.","p":1},{"v":3,"t":"അവന്റെ സഹോദരൻ യോഹന്നാൻ, പീലിപ്പോസ്, ബർത്ഥലോമിയോ, തോമസ്, ചുങ്കക്കാരൻ മത്തായി, ഹെൽപെയീ പുത്രൻ യാക്കോബ്.","p":1},{"v":4,"t":"തദ്ദേവുസ്, കാനാൻകാരൻ ശിമയോൻ, യേശുവിനെ ഒറ്റിക്കൊടുത്ത യൂദാസ് സ്കറിയോത്താ.","p":1},{"v":5,"t":"ഈ പന്ത്രണ്ടുപേരെയും യേശു ഇപ്രകാരം ചുമതലപ്പെടുത്തി അയച്ചു: നിങ്ങൾ ജനങ്ങളുടെയടുത്തേക്കു പോകരുത്; സമരിയാക്കാരുടെ പട്ടണത്തിൽ പ്രവേശിക്കുകയും അരുത്.","p":1},{"v":6,"t":"പ്രത്യുത, ഇസ്രായേൽ ഭവനത്തിലെ നഷ്ടപ്പെട്ടുപോയ ആടുകളുടെ അടുത്തേക്കു പോകുവിൻ.","p":1},{"v":7,"t":"പോകുമ്പോൾ, സ്വർഗരാജ്യം സമീപിച്ചിരിക്കുന്നു എന്നു പ്രഘോഷിക്കവിൻ.","p":1},{"v":8,"t":"രോഗികളെ സുഖപ്പെടുത്തുകയും മരിച്ചവരെ ഉയിർപ്പിക്കുകയും കുഷ്ഠരോഗികളെ ശുദ്ധരാക്കുകയും പിശാചുകളെ ബഹിഷ്കരിക്കുകയും ചെയ്തുവിൻ. ദാനമായി നിങ്ങൾക്കു കിട്ടി; ദാനമായിത്തന്നെ കൊടുക്കുവിൻ.","p":1},{"v":9,"t":"നിങ്ങളുടെ അരപ്പട്ടയിൽ പൊന്നോ വെള്ളിയോ ചെമ്പോ കരുതിവയ്ക്കരുത്.","p":1},{"v":10,"t":"യാത്രയ്ക്കു സഞ്ചിയോ രണ്ട് ഉടുപ്പുകളോ ചെരിപ്പോ വടിയോ എടുക്കരുത്. കാരണം വേലചെയ്യുന്നവൻ ആഹാരത്തിന് അർഹനാണ്.","p":1},{"v":11,"t":"നിങ്ങൾ ഏതെങ്കിലും പട്ടണത്തിലോ ഗ്രാമത്തിലോ പ്രവേശിക്കുമ്പോൾ, അവിടെ അർഹതയുള്ളവൻ ആരെന്ന് അന്വേഷിക്കുകയും അവിടെ വിടുന്നതുവരെ അവനോടുകൂടെ താമസിക്കുകയും ചെയ്യുവിൻ.","p":1},{"v":12,"t":"നിങ്ങൾ ആ ഭവനത്തിൽ പ്രവേശിക്കുമ്പോൾ അതിനു സമാധാനം ആശംസിക്കണം.","p":1},{"v":13,"t":"ആ ഭവനം അർഹതയുള്ളതാണെങ്കിൽ, നിങ്ങളുടെ സമാധാനം അതിൽ വസിക്കട്ടെ. അർഹതയില്ലാത്തതെങ്കിൽ, നിങ്ങളുടെ സമാധാനം നിങ്ങളിലേക്കുതന്നെ മടങ്ങട്ടെ.","p":1},{"v":14,"t":"ആരെങ്കിലും നിങ്ങളെ സ്വീകരിക്കാതെയോ നിങ്ങളുടെ വചനം ശ്രവിക്കാതെയോ ഇരുന്നാൽ, ആ ഭവനം അഥവാ പട്ടണം വിട്ടുപോരുമ്പോൾ നിങ്ങളുടെ പാദങ്ങളിലെ പൊടി തട്ടിക്കളയുവിൻ.","p":1},{"v":15,"t":"വിധിദിവസത്തിൽ ആ പട്ടണത്തെക്കാൾ സോദോം-ഗൊമോറാ ദേശങ്ങൾക്ക് കൂടുതൽ ആശ്വാസമുണ്ടാകുമെന്ന് സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു","p":1},{"h":"പീഡകളുടെ കാലം"},{"v":16,"t":"ചെന്നായ്ക്കളുടെ ഇടയിലേക്ക് ആടുകളെ എന്നപോലെ ഞാൻ നിങ്ങളെ അയക്കുന്നു. അതിനാൽ, നിങ്ങൾ സർപ്പങ്ങളെപ്പോലെ വിവേകികളും പ്രാവുകളെപ്പോലെ നിഷ്കളങ്കരുമായിരിക്കുവിൻ.","p":1},{"v":17,"t":"മനുഷ്യരെ സൂക്ഷിച്ചുകൊള്ളുവിൻ; അവർ നിങ്ങളെ ന്യായധിപസംഘങ്ങൾക്ക് ഏൽപിച്ചുകൊടുക്കും. തങ്ങളുടെ സിനഗോഗുകളിൽവച്ച് അവർ നിങ്ങളെ ചമ്മട്ടികൊണ്ടടിക്കും.","p":1},{"v":18,"t":"നിങ്ങൾ എന്നെപ്രതി നാടുവാഴികളുടെയും രാജാക്കന്മാരുടെയും സന്നിധിയിലേക്ക് വലിച്ചിഴയ്ക്കപ്പെടും. അവിടെ അവരുടെയും ജനതകളുടെയും മുമ്പാകെ നിങ്ങൾ സാക്ഷ്യമാകും.","p":1},{"v":19,"t":"അവർ നിങ്ങളെ ഏൽപിച്ചുകൊടുക്കുമ്പോൾ, എങ്ങനെ പറയണമെന്നോ എന്തുപറയണമെന്നോ നിങ്ങൾ ആകുലപ്പെടേണ്ട. നിങ്ങൾ പറയേണ്ടത് ആ സമയത്തു നിങ്ങൾക്ക് നൽകപ്പെടും.","p":1},{"v":20,"t":"എന്തെന്നാൽ, നിങ്ങളല്ല, നിങ്ങളിലൂടെ നിങ്ങളുടെ പിതാവിന്റെ ആത്മാവാണ് സംസാരിക്കുന്നത്.","p":1},{"v":21,"t":"സഹോദരൻ സഹോദരനെയും പിതാവ് മകനെയും മരണത്തിന് ഏൽപിച്ചുകൊടുക്കും; മക്കൾ മാതാപിതാക്കന്മാരെ എതിർക്കുകയും അവരെ വധിക്കുകയും ചെയ്യും.","p":1},{"v":22,"t":"എന്റെ നാമംമൂലം നിങ്ങൾ സർവരാലും ദേഷിക്കപ്പെടും. അവസാനംവരെ സഹിച്ചുനിൽക്കുന്നവൻ രക്ഷപെടും.","p":1},{"v":23,"t":"ഒരു പട്ടണത്തിൽ അവർ നിങ്ങളെ പീഡിപ്പിക്കുമ്പോൾ മറ്റൊന്നിലേക്ക് പലായനം ചെയ്യുവിൻ. സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു; മനുഷ്യപുത്രന്റെ ആഗമനത്തിനുമുമ്പ്, നിങ്ങൾ ഇസ്രായേലിലെ പട്ടണങ്ങളെല്ലാം ഓടിത്തീർക്കുകയില്ല.","p":1},{"v":24,"t":"ശിഷ്യൻ ഗുരുവിനേക്കാൾ മേലെയല്ല; ഭൃത്യൻ യജമാനനേക്കാളും.","p":1},{"v":25,"t":"ശിഷ്യൻ ഗുരുവിനെപ്പോലെയും ഭൃത്യൻ യജമാനനെപ്പോലെയും ആയാൽ മതി. ഗൃഹനാഥനെ അവർ ബേൽസെബൂൽ എന്ന് വിളിച്ചെങ്കിൽ അവൻ്റെ കുടുംബാംഗങ്ങളെ എന്തുതന്നെ വിളിക്കുകയില്ല.","p":1},{"h":"നിർഭയം സാക്ഷ്യം നൽകുക"},{"v":26,"t":"അതിനാൽ, നിങ്ങൾ അവരെ ഭയപ്പെടേണ്ടാ. കാരണം, മറഞ്ഞിരിക്കുന്നതൊന്നും വെളിപ്പെടാതിരിക്കുകയില്ല, നിഗൂഢമായതൊന്നും അറിയപ്പെടാതിരിക്കുകയുമില്ല.","p":1},{"v":27,"t":"അന്ധകാരത്തിൽ നിങ്ങളോട് ഞാൻ പറയുന്നവ പ്രകാശത്തിൽ പറയൂവിൻ; ചെവിയിൽ മന്ത്രിപ്പത് പുരമുകളിൽനിന്ന് പ്രഘോഷിക്കുവിൻ.","p":1},{"v":28,"t":"ശരീരത്തെ കൊല്ലുകയും എന്നാൽ ആത്മാവിനെ കൊല്ലാൻ കഴിയാതിരിക്കുകയും ചെയ്യുന്നവരെ നിങ്ങൾ ഭയപ്പെടേണ്ടാ. മറിച്ച്, ആത്മാവിനെയും ശരീരത്തെയും നരകത്തിനിരയാക്കാൻ കഴിയുന്നവനെ ഭയപ്പെടുവിൻ.","p":1},{"v":29,"t":"ഒരു നാണയത്തുട്ടിന് രണ്ടു കുരുവികൾ വില്ക്കപ്പെടുന്നില്ലേ? നിങ്ങളുടെ പിതാവറിയാതെ അവയിലൊന്നുപോലും നിലത്തു വീഴുകയില്ല.","p":1},{"v":30,"t":"നിങ്ങളുടെ തലയിലെ ഓരോ മുടിയിഴയും എണ്ണപ്പെട്ടിരിക്കുന്നു.","p":1},{"v":31,"t":"അതിനാൽ, ഭയപ്പെടേണ്ടാ. നിങ്ങൾ അനേകം കുരുവികളെക്കാൾ വിലയുള്ളവരാണല്ലോ.","p":1},{"v":32,"t":"മനുഷ്യരുടെ മുമ്പിൽ എന്നെ ഏറ്റുപറയുന്നവനെ സ്വർഗസ്ഥനായ എന്റെ പിതാവിന്റെ മുമ്പിൽ ഞാനും ഏറ്റുപറയും.","p":1},{"v":33,"t":"മനുഷ്യരുടെ മുമ്പിൽ എന്നെ തള്ളിപ്പറയുന്നവനെ സ്വർഗസ്ഥനായ എന്റെ പിതാവിന്റെ മുമ്പിൽ ഞാനും തള്ളിപ്പറയും.","p":1},{"v":34,"t":"ഭൂമിയിൽ സമാധാനം കൊണ്ടുവരാനാണ് ഞാൻ വന്നത് എന്നു നിങ്ങൾ വിചാരിക്കരുത്. ഞാൻ വന്നത് സമാധാനമല്ല, പിന്നെയോ വാൾ കൊണ്ടുവരാനാണ്.","p":1},{"v":35,"t":"എന്തെന്നാൽ, ഒരു മനുഷ്യനെ തന്റെ പിതാവിനെതിരായി മകളെ അമ്മക്കെതിരായി മരുമകളെ അമ്മായിയമ്മക്കെതിരായി ഭിന്നിപ്പിക്കാനാണ് ഞാൻ വന്നിരിക്കുന്നത്.","p":1},{"v":36,"t":"ഒരു മനുഷ്യന്റെ ശത്രുക്കൾ സ്വന്തം കുടുംബത്തിൽപെട്ടവർ തന്നെയായിരിക്കും.","p":1},{"v":37,"t":"പിതാവിനേയോ മാതാവിനേയോ എന്നെക്കാൾ അധികം സ്നേഹിക്കുന്നവൻ എനിക്ക് യോഗ്യനല്ല; പുത്രനെയോ പുത്രിയെയോ എന്നെക്കാൾ അധികം സ്നേഹിക്കുന്നവനും എനിക്ക് യോഗ്യനല്ല.","p":1},{"v":38,"t":"സ്വന്തം കുരിശെടുത്ത് എന്നെ അനുഗമിക്കാത്തവൻ എനിക്ക് യോഗ്യനല്ല.","p":1},{"v":39,"t":"സ്വന്തം ജീവൻ കണ്ടെത്തുന്നവൻ അതു നഷ്ടപ്പെടുത്തും. എന്നെപ്രതി സ്വന്തം ജീവൻ നഷ്ടപ്പെടുത്തുന്നവൻ അതു കണ്ടെത്തും.","p":1},{"h":"പ്രതിഫലവാഗ്ദാനം"},{"v":40,"t":"നിങ്ങളെ സ്വീകരിക്കുന്നവൻ എന്നെ സ്വീകരിക്കുന്നു; എന്നെ സ്വീകരിക്കുന്നവൻ എന്നെ അയച്ചവനെ സ്വീകരിക്കുന്നു.","p":1},{"v":41,"t":"പ്രവാചകനെ, പ്രവാചകനെന്ന നിലയിൽ സ്വീകരിക്കുന്നവന് പ്രവാചകന്റെ പ്രതിഫലവും നീതിമാനെ, നീതിമാനെന്ന നിലയിൽ സ്വീകരിക്കുന്നവന് നീതിമാന്റെ പ്രതിഫലവും ലഭിക്കും.","p":1},{"v":42,"t":"ഈ ചെറിയവരിൽ ഒരുവന് ശിഷ്യനെന്ന നിലയിൽ ഒരു പാത്രം പച്ചവെള്ളമെങ്കിലും കൊടുക്കുന്നവൻ പ്രതിഫലം നഷ്ടപ്പെടുകയില്ലെന്ന് സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു.","p":1}],"11":[{"h":"സ്നാപകന്റെ ശിഷ്യന്മാർ"},{"v":1,"t":"അങ്ങനെ യേശു തന്റെ പന്ത്രണ്ടു ശിഷ്യന്മാർക്ക് പ്രബോധനങ്ങൾ നൽകുന്നതവസാനിപ്പിച്ച്, അവരുടെ പട്ടണങ്ങളിൽ പഠിപ്പിക്കാനും പ്രസംഗിക്കാനുമായി അവിടെനിന്നു പുറപ്പെട്ടു.","p":1},{"v":2,"t":"യോഹന്നാൻ काराഗൃഹത്തുവെച്ച് ക്രിസ്തുവിന്റെ പ്രവർത്തനങ്ങളെക്കുറിച്ച് കേട്ടപ്പോൾ അവന്റെ ശിഷ്യന്മാരെ അയച്ച് അവനോടു ചോദിച്ചു:","p":1},{"v":3,"t":"വരാനിരിക്കുന്നവൻ നീ തന്നെയോ, അതോ ഞങ്ങൾ മറ്റൊരുവനെ പ്രതീക്ഷിക്കണോ?","p":1},{"v":4,"t":"യേശു പറഞ്ഞു: നിങ്ങൾ കേൾക്കുന്നതും കാണുന്നതും പോയി യോഹന്നാനെ അറിയിക്കുക.","p":1},{"v":5,"t":"അന്ധർ കാണുകയും മുടന്തർ നടക്കുകയും ചെയ്യുന്നു; കുഷ്ഠരോഗികൾ ശുദ്ധരാക്കപ്പെടുകയും ബധിരർ കേൾക്കുകയും ചെയ്യുന്നു; മരിച്ചവർ ഉത്ഥിതരാകുകയും ദരിദ്രോടു സദ്വാർത്ത അറിയിക്കപ്പെടുകയും ചെയ്യുന്നു.","p":1},{"v":6,"t":"എന്നാൽ എന്നിൽ ഇടർച്ച ഉണ്ടാകാത്തവൻ അനുഗൃഹീതൻ.","p":1},{"h":"സ്നാപകനെ കുറിച്ച് സാക്ഷ്യം"},{"v":7,"t":"അവർ പോയശേഷം യേശു ജനക്കൂട്ടത്തോട് യോഹന്നാനെക്കുറിച്ച് സംസാരിക്കാൻ തുടങ്ങി എന്തു കാണാനാണ് നിങ്ങൾ മരുഭൂമിയിലേക്ക് പോയത്? കാറ്റിൽ ഉലയുന്ന ഞാങ്ങണയോ?","p":1},{"v":8,"t":"അല്ലെെങ്കിൽ, എന്തു കാണാനാണ് നിങ്ങൾ പോയത്? മൃദുലവസ്ത്രങ്ങൾ ധരിച്ച മനുഷ്യനെയോ? മൃദുലവസ്ത്രങ്ങൾ ധരിക്കുന്നവർ രാജമന്ദിരങ്ങളിലാണുളളത്.","p":1},{"v":9,"t":"അല്ലെെങ്കിൽ, എന്തു കാണാനാണ് നിങ്ങൾ പോയത്? പ്രവാചകനെയോ? അതെ ഞാൻ നിങ്ങളോടു പറയുന്നു, പ്രവാചകനേക്കാൾ വലിയവനെ.","p":1},{"v":10,"t":"ഇവനെപ്പറ്റിയാണ് ഇങ്ങനെ എഴുതിയിരിക്കുന്നത്: ഇതാ, നിനക്കു മുൻപിൽ എന്റെ ദൂതനെ ഞാൻ അയക്കുന്നു. അവൻ നിന്റെ മുൻപിൽ നിനക്കു വഴിയൊരുക്കും.","p":1},{"v":11,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു: സ്ത്രീകളിൽനിന്നു ജനിച്ചവരിൽ സ്നാപകയോഹന്നാനെക്കാൾ വലിയവൻ ഉണ്ടായിട്ടില്ല. എങ്കിലും സ്വർഗരാജ്യത്തിലെ ഏറ്റവും ചെറിയവൻ അവനേക്കാൾ വലിയവനാണ്.","p":1},{"v":12,"t":"സ്നാപകയോഹന്നാന്റെ നാളുകൾമുതൽ ഇന്നുവരെ സ്വർഗരാജ്യം ബലപ്രയോഗത്തിനു വിധേയമായിരിക്കുന്നു. ബലവാന്മാർ അതു കവർന്നെടുക്കുന്നു.","p":1},{"v":13,"t":"എന്തെന്നാൽ, യോഹന്നാൻവരെ സകല പ്രവാചകന്മാരും നിയമവും പ്രവചിച്ചു.","p":1},{"v":14,"t":"നിങ്ങൾക്ക് സ്വീകരിക്കാൻ മനസ്സുണ്ടെങ്കിൽ, ഇവനാണ് വരാനിരിക്കുന്ന ഏലിയാ.","p":1},{"v":15,"t":"ചെവിയുള്ളവൻ കേൾക്കട്ടെ.","p":1},{"v":16,"t":"എന്നാൽ ഈ തലമുറയെ എന്തിനോടാണ് ഞാൻ ഉപമിക്കേണ്ടത്? അതു ചന്തസ്ഥലത്തിരുന്നു, മറ്റുള്ളവരെ വിളിക്കുന്ന കുട്ടികൾക്കു സമാനമാണ്.","p":1},{"v":17,"t":"അവർ പറയുന്നു: ഞങ്ങൾ നിങ്ങൾക്കു വേണ്ടി കുഴലൂതി, എങ്കിലും നിങ്ങൾ നൃത്തം ചെയ്തില്ല; ഞങ്ങൾ വിലാപഗാനം ആലപിച്ചു, എങ്കിലും നിങ്ങൾ വിലാപപിച്ചില്ല.","p":1},{"v":18,"t":"യോഹന്നാൻ ഭഭക്ഷിക്കാത്തവനും പാന്ചെയ്യാത്തവനുമായി വന്നു. അപ്പോൾ അവർ പറയുന്നു: അവൻ പിശാചുബാധിതനാണ്!"},{"v":19,"t":"മനുഷ്യപുത്രൻ ഭക്ഷിക്കുന്നവനും പാനംചെയ്യുന്നവനുമായി വന്നു. അപ്പോൾ അവർ പറയുന്നു: ഇതാ ഭോജനപ്രിയനും വീഞ്ഞുകുടിയനും ചുങ്കക്കാരുടെയും പാപികളുടെയും സ്നേഹിതനുമായ മനുഷ്യൻ! എങ്കിലും ജ്ഞാനം അതിന്റെ പ്രവൃത്തികളാൽ നീതീമത്കരിക്കപ്പെട്ടിരിക്കുന്നു.","p":1},{"h":"അനുഭവിക്കാത്ത നഗരങ്ങൾ"},{"v":20,"t":"അപ്പോൾ യേശു താൻ ഏറ്റവും കൂടുതൽ അത്ഭുതങ്ങൾ പ്രവർത്തിച്ച നഗരങ്ങൾ മാനസാന്തരപ്പെടാത്തതിനാൽ അവയെ ശാസിക്കാൻ തുടങ്ങി","p":1},{"v":21,"t":"കൊറാസീൻ നിനക്ക് ദുരിതം! ബേത്സയ്ദാ നിനക്ക് ദുരിതം! നിന്നിൽ നടന്ന അത്ഭുതങ്ങൾ ടയറിലും സീതോണിലും നടന്നിരുന്നെങ്കിൽ അവ എത്ര പണ്ടേ ചാരം പൂശി അനുതപിക്കുമായിരുന്നു.","p":1},{"v":22,"t":"എന്നാൽ ഞാൻ നിങ്ങളോട് പറയുന്നു വിധി ദിനത്തിൽ ടയറിന്റെയും സീദോന്റെയും അവസ്ഥ നിങ്ങളുടേതിനേക്കാൾ സഹനിയമായിരിക്കും","p":1},{"h":"ക്ലേശിതർക്ക് ആശ്വാസം"},{"v":25,"t":"ആ സമയത്ത് യേശു പറഞ്ഞു: സ്വർഗത്തിന്റെയും ഭൂമിയുടെയും നാഥനായ പിതാവേ, നീ ഇക്കാര്യങ്ങൾ ബുദ്ധിമാന്മാരിലും വിവേകികളിൽനിന്നു മറച്ച്, ശിശുക്കൾക്കു വെളിപ്പെടുത്തിയതിനാൽ ഞാൻ നിന്നെ സ്തുതിക്കുന്നു.","p":1},{"v":26,"t":"അതേ, പിതാവേ, ഇപ്രകാരമായിരുന്നു അവിടുത്തെ തിരുഉള്ളം.","p":1},{"v":27,"t":"സർവവും എന്റെ പിതാവ് എന്നെ ഭരമേല്പിച്ചിരിക്കുന്നു. പിതാവല്ലാതെ മറ്റാരും പുത്രനെ അറിയുന്നില്ല; പുത്രനും പുത്രൻ ആർക്കു വെളിപ്പെടുത്തിക്കൊടുക്കാൻ മനസ്സുന്നുവോ അവനുമല്ലാതെ മറ്റാരും പിതാവിനെയും അറിയുന്നില്ല.","p":1},{"v":28,"t":"അദ്ധ്വാനിക്കുന്നവരും ഭാരവഹിക്കുന്നവരുമായ നിങ്ങളെല്ലാവരും എന്റെ അടുക്കൽ വരുവിൻ; ഞാൻ നിങ്ങൾക്ക് വിശ്രമം നല്കാം.","p":1},{"v":29,"t":"എന്റെ നുകംവഹിക്കുകയും എന്നിൽനിന്ന് പഠിക്കുകയും ചെയ്യുവിൻ. എന്തെന്നാൽ ഞാൻ ശാന്തശീലനും വിനീതഹൃദയനുമാണ്. അങ്ങനെ നിങ്ങളുടെ ആത്മാക്കൾക്ക് നിങ്ങൾ വിശ്രമം കണ്ടെത്തും.","p":1},{"v":30,"t":"കാരണം, എന്റെ നുകം മൃദുവും ഭാരം ലഘുവുമാകുന്നു.","p":1}],"12":[{"h":"സാബത്തിനെപ്പറ്റിയുള്ള വിവാദം"},{"v":1,"t":"അക്കാലത്ത്, ഒരു സാബത്തിൽ യേശു ഗോതമ്പുവയലിലൂടെ കടന്നുപോകുകയായിരുന്നു. അപ്പോൾ അവന്റെ ശിഷ്യന്മാർക്കു വിശന്നു. അവർ കതിരുകൾ പറിച്ചുതിന്നാൻ തുടങ്ങി.","p":1},{"v":2,"t":"ഫരിസേയർ ഇതു കണ്ട് അവനോടു പറഞ്ഞു: നോക്കൂ, നിന്റെ ശിഷ്യന്മാർ സാബത്തിൽ നിഷിദ്ധമായതു ചെയ്യുന്നു.","p":1},{"v":3,"t":"അവൻ പറഞ്ഞു: വിശന്നപ്പോൾ ദാവീദും ക്ഷമിക്കണം, ചിത്രത്തിലെ വാക്യസംഖ്യകൾ ചേർക്കാൻ വിട്ടുപോയതാണ്. ചിത്രത്തിൽ നൽകിയിരിക്കുന്നതുപോലെ വാക്യസംഖ്യകൾ ഉൾപ്പെടുത്തി വാക്യം വാക്യമായി താഴെ നൽകുന്നു:","p":1},{"v":3,"t":"അനുചരന്മാരും എന്താണ് ചെയ്തതെന്ന് നിങ്ങൾ വായിച്ചിട്ടില്ലേ?","p":1},{"v":4,"t":"അവൻ ദൈവഭവനത്തിൽ പ്രവേശിച്ച്, പുരോഹിതന്മാർക്കല്ലാതെ തനിക്കോ സഹചരന്മാർക്കോ ഭക്ഷിക്കാൻ അനുവാദമില്ലാത്ത കാഴ്ചയപ്പം ഭക്ഷിച്ചതെങ്ങനെ?","p":1},{"v":5,"t":"അല്ലെങ്കിൽ, സാബത്തുദിവസം ദേവാലയത്തിലെ പുരോഹിതന്മാർ സാബത്തു ലംഘിക്കുകയും അതേസമയം കുറ്റമറ്റവരായിരിക്കുകയും ചെയ്യുന്നതെങ്ങനെയെന്ന് നിങ്ങൾ നിയമത്തിൽ വായിച്ചിട്ടില്ലേ?","p":1},{"v":6,"t":"എന്നാൽ, ഞാൻ നിങ്ങളോട് പറയുന്നു, ദേവാലയത്തെക്കാൾ ശ്രേഷ്ഠമായത് ഇവിടെയുണ്ട്.","p":1},{"v":7,"t":"ബലിയല്ല, കരുണയാണ് ഞാൻ ആഗ്രഹിക്കുന്നത് എന്നതിന്റെ അർത്ഥം മനസ്സിലാക്കിയിരുന്നെങ്കിൽ നിങ്ങൾ നിരപരാധരെ കുറ്റംവിധിക്കുമായിരുന്നില്ല.","p":1},{"v":8,"t":"എന്തെന്നാൽ, മനുഷ്യപുത്രൻ സാബത്തിന്റെയും കർത്താവാണ്.","p":1},{"h":"സാബത്തിൽ രോഗശാന്തി നൽകുന്നു"},{"v":9,"t":"അനന്തരം, യേശു അവിടെനിന്ന് യാത്രതിരിച്ച് അവരുടെ സിനഗോഗിലെത്തി.","p":1},{"v":10,"t":"അവിടെ കൈശോഷിച്ച ഒരുവൻ ഉണ്ടായിരുന്നു.","p":1},{"v":10,"t":"യേശുവിൽ കുറ്റമാരോപിക്കണമെന്ന ഉദ്ദേശ്യത്തോടെ അവർ അവനോടു ചോദിച്ചു: സാബത്തിൽ രോഗശാന്തി നൽകുന്നത് അനുവദനീയമാണോ?","p":1},{"v":11,"t":"അവൻ പറഞ്ഞു: നിങ്ങളിൽ ആരുണ്ട്, തന്റെ ആട് സാബത്തിൽ കുഴിയിൽ വീണാൽ പിടിച്ചുയർത്താത്തതായി?","p":1},{"v":12,"t":"ആടിനെക്കാൾ എത്രയേറെ വിലപ്പെട്ടവനാണ് മനുഷ്യൻ! അതിനാൽ, സാബത്തിൽ നന്മചെയ്യുന്നത് അനുവദനീയമാണ്.","p":1},{"v":13,"t":"അനന്തരം, അവൻ ആ മനുഷ്യനോടു പറഞ്ഞു: കൈ നീട്ടുക.","p":1},{"v":13,"t":"അവൻ കൈനീട്ടി.","p":1},{"v":13,"t":"ഉടനെ അതു സുഖം പ്രാപിക്കപ്പെട്ടു, മറ്റേ കൈ പോലെയായി.","p":1},{"v":14,"t":"ഫരിസേയരാകട്ടെ, അവിടെനിന്ന് പോയി, അവനെ നശിപ്പിക്കേണ്ടത് എങ്ങനെയെന്ന് കൂടിയാലോചന നടത്തി.","p":1},{"h":"ദൈവത്തിന്റെ തിരഞ്ഞെടുക്കപ്പെട്ട ദാസൻ"},{"v":15,"t":"ഇതു മനസ്സിലാക്കിയ യേശു അവിടെനിന്ന് പിൻവാങ്ങി.","p":1},{"v":15,"t":"അനേകംപേർ അവനെ അനുഗമിച്ചു.","p":1},{"v":15,"t":"അവരെയെല്ലാം അവൻ സുഖപ്പെടുത്തി.","p":1},{"v":16,"t":"തന്നെ പരസ്യപ്പെടുത്തുന്നതിൽനിന്ന് അവൻ അവരെ വിലക്കി.","p":1},{"v":17,"t":"ഇത് ഏശയ്യാപ്രവാചകൻ വഴി അരുളച്ചെയ്യപ്പെട്ടതു പൂർത്തിയാകാനാണ്:","p":1},{"v":18,"t":"ഇതാ, ഞാൻ തിരഞ്ഞെടുത്ത എന്റെ ദാസൻ, എന്റെ ആത്മാവു പ്രസാദിച്ച എന്റെ പ്രിയപ്പെട്ടവൻ!","p":1},{"v":18,"t":"ഞാൻ അവന്റെമേൽ എന്റെ ആത്മാവിനെ അയക്കും; അവൻ ജനതകളെ ന്യായവിധി അറിയിക്കും.","p":1},{"v":19,"t":"അവൻ തർക്കിക്കുകയോ ഒച്ചവയ്ക്കൂകയോ ഇല്ല; തെരുവീഥികളിൽ അവന്റെ ശബ്ദം ആരും കേൾക്കുകയുമില്ല.","p":1},{"v":20,"t":"നീതിയെ വിജയത്തിലെത്തിക്കുന്നതുവരെ അവൻ ചതഞ്ഞ ഞാണണ ഒടിക്കുകയില്ല; പുകഞ്ഞ തിരി കെടുത്തുകയില്ല.","p":1},{"v":21,"t":"അവന്റെ നാമത്തിൽ ജനതകൾ പ്രത്യാശ വെയ്ക്കും.","p":1},{"h":"യേശുവും ബേൽസെബൂലും"},{"v":22,"t":"അനന്തരം, അന്ധനും ഊമയുമായ ഒരു പിശാചുബാധിതനെ അവർ യേശുവിന്റെ അടുത്തുകൊണ്ടുവന്നു.","p":1},{"v":22,"t":"യേശു അവനെ സുഖപ്പെടുത്തി, അവൻ സംസാരിക്കുകയും കാണുകയും ചെയ്തു.","p":1},{"v":23,"t":"ജനക്കൂട്ടമെല്ലാം അത്ഭുതപ്പെട്ടു ചോദിച്ചുകൊണ്ടിരുന്നു; ഇവനായിരിക്കുമോ ദാവീദിന്റെ പുത്രൻ!","p":1},{"v":24,"t":"എന്നാൽ, ഇതു കേട്ടപ്പോൾ ഫരിസേയർ പറഞ്ഞു: ഇവൻ പിശാചുക്കളുടെ തലവനായ ബേൽസെബൂലിനെക്കൊണ്ടു തന്നെയാണ് പിശാചുകളെ ബഹിഷ്കരിക്കുന്നത്.","p":1},{"v":25,"t":"അവരുടെ വിചാരങ്ങൾ മനസ്സിലാക്കിയ യേശു അവരോടു പറഞ്ഞു: അന്തശ്ഛിദ്രമുള്ള ഏതു രാജ്യവും നശിച്ചു പോകും.","p":1},{"v":25,"t":"അന്തശ്ഛിദ്രമുള്ള നഗരമോ ഭവനമോ നിലനിൽക്കുകയില്ല.","p":1},{"v":26,"t":"സാത്താൻ സാത്താനെ ബഹിഷ്കരിക്കുന്നുവെങ്കിൽ, അവൻ തനിക്കെതിരായി തന്നെ ഭിന്നിക്കുകയാണ്.","p":1},{"v":26,"t":"അങ്ങനെയാണെങ്കിൽ അവന്റെ രാജ്യം എങ്ങനെ നിലനിൽക്കും?","p":1},{"v":27,"t":"ബേൽസെബൂലിനെക്കൊണ്ടാണ് ഞാൻ പിശാചുകളെ ബഹിഷ്കരിക്കുന്നതെങ്കിൽ, നിങ്ങളുടെ പുത്രന്മാർ ആരെക്കൊണ്ടാണ് അവയെ ബഹിഷ്കരിക്കുന്നത്?","p":1},{"v":27,"t":"അതുകൊണ്ട് അവർ നിങ്ങളുടെ വിധിക്കർത്താക്കളായിരിക്കും.","p":1},{"v":28,"t":"എന്നാൽ, ദൈവാത്മാവിനെക്കൊണ്ടാണ് ഞാൻ പിശാചുകളെ ബഹിഷ്കരിക്കുന്നതെങ്കിൽ, ദൈവരാജ്യം നിങ്ങളുടെ അടുത്തെത്തിയിരിക്കുന്നു.","p":1},{"v":29,"t":"അഥവാ, ശക്തനായ ഒരു മനുഷ്യന്റെ ഭവനത്തിൽ പ്രവേശിച്ച് വസ്തുക്കൾ കവർച്ചചെയ്യാൻ, ആദ്യംതന്നെ അവനെ ബന്ധിക്കാതെ സാധിക്കുമോ?","p":1},{"v":29,"t":"അപ്പോൾ അവന്റെ ഭവനം കവർച്ചചെയ്യാൻ കഴിയും.","p":1},{"v":30,"t":"എന്നോടുകൂടെയല്ലാത്തവൻ എന്റെ എതിരാളിയാണ്.","p":1},{"v":30,"t":"എന്നോടുകൂടെ ശേഖരിക്കാത്തവൻ ചിതറിച്ചുകളയുന്നു.","p":1},{"v":31,"t":"അതുകൊണ്ട്, ഞാൻ നിങ്ങളോട് പറയുന്നു: മനുഷ്യന്റെ എല്ലാ പാപവും ദൈവദൂഷണവും क्षമിക്കപ്പെടും; എന്നാൽ ആത്മാവിനെതിരായ ദൂഷണം ക്ഷമിക്കപ്പെടുകയില്ല.","p":1},{"v":32,"t":"മനുഷ്യപുത്രനെതിരായി ആരെങ്കിലും ഒരു വാക്കു പറഞ്ഞാൽ അത് ക്ഷമിക്കപ്പെടും.","p":1},{"v":32,"t":"എന്നാൽ, പരിശുദ്ധാത്മാവിനെതിരായി ആരെങ്കിലും സംസാരിച്ചാൽ, ഈ യുഗത്തിലോ വരാനിരിക്കുന്ന യുഗത്തിലോ അത് ക്ഷമിക്കപ്പെടുകയില്ല.","p":1},{"v":33,"t":"ഒന്നുകിൽ വൃക്ഷം നല്ലത്, ഫലവും നല്ലത്. അല്ലെങ്കിൽ വൃക്ഷം ചീത്ത, ഫലവും ചീത്ത. കാരണം, ഫലത്തിൽനിന്നാണ് വൃക്ഷത്തെ അറിയുന്നത്.","p":1},{"v":34,"t":"അണലിസന്തതികളെ, ദുഷ്ടരായിരിക്കെ നല്ല കാര്യങ്ങൾ പറയാൻ നിങ്ങൾക്ക് എങ്ങനെ കഴിയും? ഹൃദയത്തിന്റെ നിറവിൽ നിന്നാണല്ലോ അധരം സംസാരിക്കുന്നത്.","p":1},{"v":35,"t":"നല്ല മനുഷ്യൻ നന്മയുടെ ശേഖരത്തിൽനിന്ന് നന്മ പുറപ്പെടുവിക്കുന്നു. ദുഷ്ടനാകട്ടെ, തിന്മയുടെ ശേഖരത്തിൽനിന്ന് തിന്മ പുറപ്പെടുവിക്കുന്നു.","p":1},{"v":36,"t":"ഞാൻ നിങ്ങളോടു പറയുന്നു: മനുഷ്യർ പറയുന്ന ഓരോ വ്യർഥവാക്കിനും വിധിദിവസം കണക്കുകൊടുകേണ്ടിവരും.","p":1},{"v":37,"t":"കാരണം, നിന്റെ വാക്കുകളാൽ നീ നീതിമത്കരിക്കപ്പെടും; നിന്റെ വാക്കുകളാൽത്തന്നെ നീ കുറ്റം വിധിക്കപ്പെടുകയും ചെയ്യും.","p":1},{"h":"യോനാപ്രവാചകന്റെ അടയാളം"},{"v":38,"t":"അപ്പോൾ ചില നിയമജ്ഞരും ഫരിസേയരും അവനോടു പറഞ്ഞു: ഗുരോ, നിന്നിൽനിന്ന് ഒരു അടയാളം കാണാൻ ഞങ്ങൾ ആഗ്രഹിക്കുന്നു.","p":1},{"v":39,"t":"അവൻ മറുപടി പറഞ്ഞു: ദുഷിച്ചതും അവിശ്വാസ്തവുമായ തലമുറ അടയാളം അന്വേഷിക്കുന്നു. യോനാപ്രവാചകന്റെ അടയാളമല്ലാതെ മറ്റൊരടയാളവും അതിനു നൽകപ്പെടുകയില്ല.","p":1},{"v":40,"t":"യോനാ മൂന്നു രാവും മൂന്നു പകലും തിമിംഗലത്തിന്റെ ഉദരത്തിൽ കിടന്നപോലെ, മനുഷ്യപുത്രനും മൂന്നു രാവും മൂന്നു പകലും ഭൂമിക്കുള്ളിലായിരിക്കും.","p":1},{"v":41,"t":"നിനെവേ നിവാസികൾ വിധിദിവസം ഈ തലമുറയോടൊത്ത് എഴുന്നേറ്റ് ഇതിനെ കുറ്റം വിധിക്കും. എന്തെന്നാൽ, യോനായുടെ പ്രസംഗം കേട്ട് അവർ അനുതപിച്ചു. ഇതാ, ഇവിടെ യോനായെക്കാൾ വലിയവൻ!","p":1},{"v":42,"t":"ദക്ഷിണദേശത്തെ രാജ്ഞി വിധിദിവസം ഈ തലമുറയോടൊത്ത് ഉയിർത്തെഴുന്നേൽക്കുകയും ഇതിനെ കുറ്റംവിധിക്കുകയും ചെയ്യും. എന്തെന്നാൽ, സോളമന്റെ വിജ്ഞാനം ശ്രവിക്കാൻ അവൾ ഭൂമിയുടെ അതിർത്തികളിൽനിന്നു വന്നെത്തി, ഇതാ ഇവിടെ സോളമനെക്കാൾ വലിയവൻ!","p":1},{"h":"അശുദ്ധാരൂപി തിരിച്ചുവരുന്നു"},{"v":43,"t":"അശുദ്ധാരൂപി ഒരു മനുഷ്യനെ വിട്ടുപോകുമ്പോൾ അത് ആശ്വാസംതേടി വരണ്ടസ്ഥലങ്ങളിലൂടെ അലഞ്ഞു നടക്കുന്നു; എന്നാൽ കണ്ടെത്തുന്നില്ല.","p":1},{"v":44,"t":"അപ്പോൾ അതു പറയുന്നു: ഞാൻ ഇറങ്ങിപ്പോന്ന എന്റെ താമസസ്ഥലത്തേക്കു തിരിച്ചുചെല്ലും.","p":1},{"v":44,"t":"മടങ്ങിവരുമ്പോൾ ആ സ്ഥലം ആളൊഴിഞ്ഞും അടിച്ചുവാരി സജ്ജീകരിക്കപ്പെട്ടും കാണുന്നു.","p":1},{"v":45,"t":"അപ്പോൾ അതു പുറപ്പെട്ടുചെന്ന് തന്നെക്കാൾ ദുഷ്ടരായ ഏഴ് അരൂപികളെക്കൂടി തന്നോടൊത്ത് കൊണ്ടുവരുകയും അവിടെ പ്രവേശിച്ച് വാസമുറപ്പിക്കുകയും ചെയ്യുന്നു.","p":1},{"v":45,"t":"അങ്ങനെ ആ മനുഷ്യന്റെ അവസാനത്തെ സ്ഥിതി ആദ്യത്തേതിനേക്കാൾ শোചനീയമായിത്തീരുന്നു.","p":1},{"v":45,"t":"ഈ ദുഷിച്ച തലമുറയ്ക്കും ഇതുതന്നെയായിരിക്കും സ്ഥിതി.","p":1},{"v":45,"t":"യേശുവിന്റെ അമ്മയും സഹോദരന്മാരും (മർക്കോസ് 3,31-35; ലൂക്കാ 8,19-21)","p":1},{"v":46,"t":"അവൻ തുടർന്ന് ജനക്കൂട്ടത്തോട് സംസാരിച്ചുകൊണ്ടിരുന്നപ്പോൾ അവന്റെ അമ്മയും സഹോദരന്മാരും അവനോടു സംസാരിക്കാൻ ആഗ്രഹിച്ച് പുറത്തുനിന്നിരുന്നു.","p":1},{"v":47,"t":"ഒരുവൻ അവനോടു പറഞ്ഞു: ഇതാ, നിന്റെ അമ്മയും സഹോദരന്മാരും നിന്നോടു സംസാരിക്കാനാഗ്രഹിച്ച് പുറത്തുനിൽക്കുന്നു.","p":1},{"v":48,"t":"യേശു അവനോടു പറഞ്ഞു: ആരാണ് എന്റെ അമ്മ? ആരാണ് എന്റെ സഹോദരൻ?","p":1},{"v":49,"t":"തന്റെ ശിഷ്യരുടെ നേരെ കൈ നീട്ടിക്കൊണ്ട് അവൻ പറഞ്ഞു: ഇതാ, എന്റെ അമ്മയും സഹോദരന്മാരും.","p":1},{"v":50,"t":"സ്വർഗസ്ഥനായ എന്റെ പിതാവിന്റെ ഹിതം നിറവേറ്റുന്നവനോ, അവനാണ് എന്റെ സഹോദരനും സഹോദരിയും അമ്മയും.","p":1}],"13":[{"h":"വിതക്കാരന്റെ ഉപമ"},{"v":1,"t":"ആ ദിവസം യേശു വീട്ടിൽനിന്നു പുറത്തുവന്ന്, കടൽത്തീരത്തിരുന്നു.","p":1},{"v":2,"t":"വലിയ ജനക്കൂട്ടം അവന്റെ ചുറ്റുംകൂടി. തന്നിമിത്തം അവൻ ഒരു തോണിയിൽക്കയറി ഇരുന്നു. ജനക്കൂട്ടം മുഴുവൻ തീരത്തുനിന്നു.","p":1},{"v":3,"t":"അപ്പോൾ അവൻ ഏറെക്കാര്യങ്ങൾ ഉപമകൾവഴി അവരോടു പറഞ്ഞു: ഇതാ, വിതക്കാരൻ വിതയ്ക്കാൻ പുറപ്പെട്ടു.","p":1},{"v":4,"t":"അവൻ വിതച്ചപ്പോൾ കുറെ വിത്തുകൾ വഴിയരികിൽ വീണു. പക്ഷികൾ വന്ന് അവ തിന്നുകളഞ്ഞു.","p":1},{"v":5,"t":"എന്നാൽ, ചിലത് മണ്ണ് അധികമില്ലാത്ത പാറമേൽ വീണു. മണ്ണിന് താഴ്ചയില്ലാതിരുന്നതിനാൽ പെട്ടെന്ന് മുളച്ചുപൊങ്ങി.","p":1},{"v":6,"t":"സൂര്യനുദിച്ചപ്പോൾ അവ വെയിലേറ്റ് വാടുകയും വേരില്ലാതിരുന്നതിനാൽ കരിഞ്ഞുപോകുകയും ചെയ്തു.","p":1},{"v":7,"t":"എന്നാൽ, വേറെ ചിലത് മുൾച്ചെടികൾക്കിടയിൽ വീണു. മുൾച്ചെടികൾ വളർന്ന് അവയെ ഞെരുക്കിക്കളഞ്ഞു.","p":1},{"v":8,"t":"മറ്റു ചിലതാകട്ടെ, നല്ല നിലത്തു വീണു. അവ നൂറു മേനിയും അറുപത് മേനിയും മുപ്പതു മേനിയും വിളവു നൽകി","p":1},{"v":9,"t":"ചെവിയുള്ളവൻ കേൾക്കട്ടെ ഉപമകളുടെ ഉദ്ദേശ്യം"},{"v":10,"t":"അപ്പോൾ ശിഷ്യന്മാർ അടുത്തെത്തി അവനോടു ചോദിച്ചു: എന്തുകൊണ്ടാണ് നീ അവരോട് ഉപമകൾ വഴി സംസാരിക്കുന്നത്?"},{"v":11,"t":"അവൻ മറുപടിപറഞ്ഞു: നിങ്ങൾക്കാണ് സ്വർഗരാജ്യത്തിന്റെ രഹസ്യങ്ങൾ അറിയാൻ വരം നൽകപ്പെട്ടിരിക്കുന്നത്; അവർക്കാകട്ടെ, നൽകപ്പെട്ടിട്ടില്ല.","p":1},{"v":12,"t":"കാരണം, ഉള്ളവനു നൽകപ്പെടും; അവനു സമൃദ്ധിയുണ്ടാകുകയും ചെയ്യും. ഇല്ലാത്തവനിൽനിന്ന് ഉള്ളതുപോലും എടുക്കപ്പെടും.","p":1},{"v":13,"t":"അതുകൊണ്ടാണ് ഞാൻ അവരോട് ഉപമകൾ വഴി സംസാരിക്കുന്നത്. എന്തെന്നാൽ, അവർ കാണുന്നെങ്കിലും കാണുന്നില്ല; കേൾക്കുന്നെങ്കിലും കേൾക്കുന്നില്ല, ഗ്രഹിക്കുന്നുന്നുമില്ല.","p":1},{"v":14,"t":"ഏശയ്യായുടെ പ്രവചനം അവരിൽ പൂർത്തിയായിരിക്കുന്നു: നിങ്ങൾ തീർച്ചയായും കേൾക്കും, എന്നാൽ മനസ്സിലാക്കുകയില്ല; നിങ്ങൾ തീർച്ചയായും കാണും, എന്നാൽ ഗ്രഹിക്കുകയില്ല.","p":1},{"v":15,"t":"കാരണം, അവർ കണ്ണുകൊണ്ട് കണ്ട്, കാതുകൊണ്ട് കേട്ട്, ഹൃദയംകൊണ്ട് മനസ്സിലാക്കി മാനസാന്തരപ്പെടുകയും ഞാൻ അവരെ സുഖപ്പെടുത്തുകയും അസാധ്യമാകുംവിധം, ഈ ജനതയുടെ ഹൃദയം കഠിനമായിതീർന്നിരിക്കുന്നു; ചെവിയുടെ കേൾവി മന്ദീഭവിച്ചിരിക്കുന്നു; കണ്ണ് അവർ അടച്ചുകളഞ്ഞിരിക്കുന്നു.","p":1},{"v":16,"t":"എന്നാൽ, നിങ്ങളുടെ കണ്ണുകൾ ഭാഗ്യമുളളവ; എന്തെന്നാൽ, അവ കാണുന്നു. നിങ്ങളുടെ കാതുകൾ ഭാഗ്യമുളളവ; എന്തെന്നാൽ, അവ കേൾക്കുന്നു.","p":1},{"v":17,"t":"കാരണം, സത്യമായി ഞാൻ നിങ്ങളോട് പറയുന്നു: അനേകം പ്രവാചകന്മാരും നീതിമാന്മാരും നിങ്ങൾ കാണുന്നവ കാണാൻ ആഗ്രഹിച്ചു, എങ്കിലും കണ്ടില്ല; നിങ്ങൾ കേൾക്കുന്നവ കേൾക്കാൻ ആഗ്രഹിച്ചു, എങ്കിലും കേട്ടില്ല.","p":1},{"h":"വിതക്കാരന്റെ ഉപമ വിശദമാക്കുന്നു"},{"v":18,"t":"ആകയാൽ, വിതക്കാരന്റെ ഉപമ നിങ്ങൾ കേട്ടുകൊള്ളുവിൻ.","p":1},{"v":19,"t":"ഒരുവൻ രാജ്യത്തിന്റെ വചനം കേട്ട് മനസ്സിലാക്കാതിരിക്കുമ്പോൾ ദുഷ്ടൻ വന്ന് അവന്റെ ഹൃദയത്തിൽ വിതയ്ക്കപ്പെട്ടത് അപഹരിക്കുന്നു. ഇതാണ് വഴിയരികിൽ വീണ വിത്ത്.","p":1},{"v":20,"t":"പാറപ്പുറത്തു വിതയ്ക്കപ്പെട്ട വിത്താകട്ടെ, വചനം കേട്ട് ഉടനെ സസന്തോഷം സ്വീകരിക്കുന്നവനാണ്.","p":1},{"v":21,"t":"എന്നാൽ, തന്നിൽ വേരില്ലാത്തതിനാൽ അല്പനേരം മാത്രം നിന്നിട്ട് ,വചനത്തെപ്രതി ക്ലേശവും പീഡയും ഉണ്ടാവുമ്പോൾ അവൻ തത്ക്ഷണം ഇടറിപ്പോകുന്നു","p":1},{"v":22,"t":"മറ്റൊരുവൻ വചനം ശ്രവിക്കുന്നു എന്നാൽ ഈ ലോകത്തിൻ്റെ ഉത്കണ്ഠയും ധനത്തിന്റെ ആകർഷകത്വവും വചനത്തെ ഞെരുകയും അത് ഫല ശൂന്യമാക്കുകയും ചെയ്യുന്നു അവനാണ് മുള്ളുകൾക്കിടയിൽ വീണ വിത്ത്"},{"v":23,"t":"എന്നാൽ വചനം കേട്ടു ഗ്രഹിക്കുന്നവനാണ് നല്ല നിലത്ത് വിതയ്ക്കപ്പെട്ട വിത്ത് അവൻ നിശ്ചയമായും ഫലം പുറപ്പെടുവിക്കുന്നു ചിലപ്പോൾ നൂറു മീനിയും അറുപത് മേനിയും മറ്റു ചിലപ്പോൾ മുപ്പതു മേനിയും."},{"h":"കളകളുടെ ഉപമ"},{"v":24,"t":"അവൻ അവരോട് മറ്റൊരു ഉപമ പറഞ്ഞു: തൻ്റെ വയലിൽ നല്ല വിത്തു വിതയ്ക്കുന്ന മനുഷ്യനോട് സ്വർഗരാജ്യത്തെ ഉപമിക്കാം.","p":1},{"v":25,"t":"ആളുകൾ ഉറക്കമായപ്പോൾ അവന്റെ ശത്രു വന്ന്, ഗോതമ്പിനിടയിൽ കള വിതച്ചിട്ടു കടന്നുകളഞ്ഞു.","p":1},{"v":26,"t":"ചെടികൾ വളർന്ന് കതിരായപ്പോൾ കളകളും പ്രത്യക്ഷപ്പെട്ടു.","p":1},{"v":27,"t":"വേലക്കാർ ചെന്ന് വീട്ടുടമസ്ഥനോട് ചോദിച്ചു: യജമാനനേ, നീ വയലിൽ നല്ല വിത്തല്ലേ വിതച്ചത്? പിന്നെ കളകളുണ്ടായത് എവിടെനിന്ന്?","p":1},{"v":28,"t":"അവൻ പറഞ്ഞു: ശത്രുവായ ഒരു മനുഷ്യനാണ് ഇതുചെയ്തത്. വേലക്കാർ ചോദിച്ചു: അതിനാൽ, ഞങ്ങൾ പോയി കളകൾ പറിച്ചുകൂട്ടണമെന്ന് നീ ആഗ്രഹിക്കുന്നുവോ?","p":1},{"v":29,"t":"അവൻ പറഞ്ഞു: ഇല്ല; കളകൾ പറിച്ചെടുക്കുമ്പോൾ അവയോടൊപ്പം ഗോതമ്പ് ചെടികളും നിങ്ങൾ പിഴുതുകളഞ്ഞെന്നു വരും.","p":1},{"v":30,"t":"കൊയ്ത്തുവരെ അവ ഒരുമിച്ചു വളരാൻ അനുവദിക്കുക. കൊയ്ത്തുകാലത്ത് ഞാൻ കൊയ്ത്തുകാരോട് പറയും: ആദ്യമേ കളകൾ ശേഖരിച്ച്, തീയിൽ ചുട്ടുകളയാൻ അവ കെട്ടുകളാക്കി വയ്ക്കുവിൻ; ഗോതമ്പ് എന്റെ ധാന്യപ്പുരയിൽ ശേഖരിക്കുവിൻ.","p":1},{"h":"കടുകുമണിയുടെയും പുളിമാവിന്റെയും ഉപമ"},{"v":31,"t":"അവൻ അവരോട് വേറൊരു ഉപമ പറഞ്ഞു: സ്വർഗ്ഗ രാജ്യം ഒരുവൻ വയലിൽ പാകിയ കടുകുമണിക്ക് സദൃശ്യം.","p":1},{"v":32,"t":"അത് എല്ലാ വിത്തിനെയുംകാൾ ചെറുതാണ്; എന്നാൽ, വളർന്നു കഴിയുമ്പോൾ അത് മറ്റു ചെടികളെക്കാൾ വലുതായി, ആകാശപ്പറവകൾ വന്ന് അതിന്റെ ശിഖരങ്ങളിൽ ചേക്കേറാൻ തക്കവിധം മരമായിത്തീരുന്നു.","p":1},{"v":33,"t":"മറ്റൊരുപമ അവൻ അവരോട് അരുൾച്ചെയ്തു: മൂന്ന് അളവ് മാവിൽ അതു പുളിക്കുവോളം ഒരു സ്ത്രീ ചേർത്ത പുളിമാവിന് സദൃശ്യമാണ് സ്വർഗരാജ്യം.","p":1},{"v":34,"t":"ഇവയെല്ലാം ഉപമകൾവഴിയാണ് യേശു ജനക്കൂട്ടത്തോട് പറഞ്ഞത്. ഉപമകളിലൂടെയല്ലാതെ അവൻഒന്നും അവരോട് പറഞ്ഞിരുന്നില്ല.","p":1},{"v":35,"t":"ഞാൻ ഉപമകൾ വഴി സംസാരിക്കും, ലോകസ്ഥാപനം മുതൽ നിഗൂഢമായിരുന്നവ ഞാൻ വെളിപ്പെടുത്തും എന്ന് പ്രവാചകനിലൂടെ പറയപ്പെട്ടത് പൂർത്തിയാകാനായിരുന്നു ഇത്.","p":1},{"h":"കളകളുടെ ഉപമ - വിശദീകരണം"},{"v":36,"t":"പിന്നീട് അവൻ ജനക്കൂട്ടത്തെ പറഞ്ഞയച്ചിട്ട് വീട്ടിലേക്കു വന്നു. ശിഷ്യന്മാർ അവന്റെ അടുത്തുവന്നു പറഞ്ഞു: വയലിലെ കളകൾ സംബന്ധിക്കുന്ന ഉപമ ഞങ്ങൾക്ക് വിശദീകരിച്ചുതന്നാലും.","p":1},{"v":37,"t":"അവൻ മറുപടി പറഞ്ഞു: നല്ല വിത്തു വിതയ്ക്കുന്നവൻ മനുഷ്യപുത്രനാണ്;","p":1},{"v":38,"t":"വയൽ ലോകവും. നല്ല വിത്ത് രാജ്യത്തിന്റെ പുത്രന്മാരും കളകൾ ദുഷ്ടന്റെ പുത്രന്മാരുമാണ്.","p":1},{"v":39,"t":"അവ വിതച്ച ശത്രു പിശാചാണ്; കൊയ്ത്ത് യുഗാന്ത്യമാണ്; കൊയ്ത്തുകാർ ദൈവദൂതന്മാരും","p":1},{"v":40,"t":"കളകൾ ശേഖരിച്ച് അഗ്നിക്കിരയാക്കുന്നതെങ്ങനെയോ അങ്ങനെ തന്നെയായിരിക്കും യുഗാന്തത്തിലും."},{"v":41,"t":"മനുഷ്യപുത്രൻ തന്റെ ദൂതന്മാരെ അയക്കുകയും അവർ അവന്റെ രാജ്യത്തുനിന്ന് എല്ലാ പാപഹേതുക്കളെയും അനീതി പ്രവർത്തിക്കുന്നവരെയും ഒരുമിച്ചുകൂട്ടി അഗ്നികുണ്ഡത്തിലേക്കെറിയുകയും ചെയ്യും.","p":1},{"v":42,"t":"അവിടെ കരച്ചിലും പല്ലുകടിയുമായിരിക്കും.","p":1},{"v":43,"t":"അപ്പോൾ നീതിമാന്മാർ തങ്ങളൂടെ പിതാവിന്റെ രാജ്യത്ത് സൂര്യനെപ്പോലെ പ്രകാശിക്കും. ചെവിയുള്ളവൻ കേൾക്കട്ടെ.","p":1},{"h":"നിധിയുടെയും രത്നത്തിന്റെയും വലയുടെയും ഉപമകൾ"},{"v":44,"t":"സ്വർഗരാജ്യം, വയലിൽ ഒളിഞ്ഞിരിക്കുന്ന നിധിക്കു തുല്യം. അതു കണ്ടെത്തുന്ന മനുഷ്യൻ അത് മറച്ചുവെയ്ക്കുകയും സന്തോഷത്തോടെ പോയി, തനിക്കുള്ളതെല്ലാം വിറ്റ് ആ വയൽ വാങ്ങുകയും ചെയ്യുന്നു.","p":1},{"v":45,"t":"വീണ്ടും, സ്വർഗരാജ്യം നല്ല രത്നങ്ങൾ തേടുന്ന വ്യാപാരിക്ക് തുല്യം.","p":1},{"v":46,"t":"അവൻ വിലയേറിയ ഒരു രത്നം കണ്ടെത്തുമ്പോൾ പോയി, തനിക്കുള്ളതെല്ലാം വിറ്റ് അതു വാങ്ങുന്നു.","p":1},{"v":47,"t":"സ്വർഗ്ഗരാജ്യം എല്ലാത്തരം മത്സ്യങ്ങളെയും ശേഖരിക്കാൻ കടലിൽ എറിയപ്പെട്ട വലയ്ക്ക് തുല്യം.","p":1},{"v":48,"t":"വല നിറഞ്ഞപ്പോൾ അവർ അതു കരയ്ക്കുവലിച്ച് കയറ്റി, അവിടെയിരുന്ന്, നല്ല മത്സ്യങ്ങൾ പാത്രങ്ങളിൽ ശേഖരിക്കുകയും ചീത്ത മത്സ്യങ്ങൾ പുറത്തേക്ക് എറിയുകയും ചെയ്തു.","p":1},{"v":49,"t":"യുഗാന്തത്തിലും ഇതുപോലെയായിരിക്കും. ദൈവദൂതന്മാർ പുറപ്പെട്ട് ചെന്ന് ദുഷ്ടന്മാരെ നീതിമാന്മാരിൽനിന്ന് വേർതിരിക്കുകയും അഗ്നികുണ്ഡത്തിലേക്കെറിയുകയും ചെയ്യും.","p":1},{"v":50,"t":"അവിടെ കരച്ചിലും പല്ലുകടിയുമായിരിക്കും.","p":1},{"v":51,"t":"നിങ്ങൾ ഇതെല്ലാം ഗ്രഹിച്ചുവോ, അവൻ ചോദിച്ചു. ഉവ്വ്, അവർ പറഞ്ഞു.","p":1},{"v":52,"t":"അവൻ അവരോടു പറഞ്ഞു: അതിനാൽ സ്വർഗരാജ്യത്തിന്റെ ശിഷ്യനായിത്തീർന്ന ഓരോ നിയമജ്ഞനും തന്റെ നിക്ഷേപത്തിൽനിന്ന് പുതിയതും പഴയതും പുറത്തെടുക്കുന്ന വീട്ടുടമസ്ഥനു തുല്യനാകുന്നു.","p":1},{"h":"സ്വന്തനാട്ടിൽ അവഗണിക്കപ്പെടുന്നു"},{"v":53,"t":"അങ്ങനെ, യേശു ഈ ഉപമകൾ അവസാനിപ്പിച്ചപ്പോൾ, അവിടെനിന്ന് പുറപ്പെട്ട്","p":1},{"v":54,"t":"സ്വദേശത്തു വന്ന്, അവരുടെ സിനഗോഗിൽ പഠിപ്പിച്ചു. അവർ വിസ്മയഭരിതരായി ചോദിച്ചു: ഇവന് ഈ ജ്ഞാനവും ശക്തിയും എവിടെനിന്ന്?"},{"v":55,"t":"ഇവൻ ആ തച്ചന്റെ മകനല്ലേ? ഇവന്റെ അമ്മ മറിയം എന്നു വിളിക്കപ്പെടുന്നവളല്ലേ? യാക്കോബ്, ജോസഫ്, ശിമയോൻ, യൂദാസ് എന്നിവരല്ലേ ഇവന്റെ സഹോദരന്മാർ?","p":1},{"v":56,"t":"ഇവന്റെ സഹോദരിമാരെല്ലാം നമ്മുടെ കൂട്ടത്തിലുണ്ടല്ലോ. പിന്നെ ഇവന് ഇതെല്ലാം എവിടെനിന്ന്?","p":1},{"v":57,"t":"അവർക്ക് അവനിൽ ഇടർച്ചയുണ്ടായി. യേശു അവരോടു പറഞ്ഞു: പ്രവാചകൻ സ്വദേശത്തും സ്വഭവനത്തിലുമല്ലാതെ മറ്റെങ്ങും അവമതിക്കപ്പെടുന്നില്ല.","p":1},{"v":58,"t":"അവരുടെ അവിശ്വാസം നിമിത്തം അവൻ അവിടെ കൂടുതൽ അത്ഭുതങ്ങൾ പ്രവർത്തിച്ചില്ല.","p":1}],"14":[{"h":"സ്നാപകന്റെ ശിരച്ഛേദം"},{"v":1,"t":"അക്കാലത്ത്, സാമന്തരാജാവായ ഹേറോദേസ് യേശുവിന്റെ കീർത്തിയെപ്പറ്റി കേട്ട്","p":1},{"v":2,"t":"തന്റെ സേവകന്മാരോടു പറഞ്ഞു: ഇവൻ സ്നാപക യോഹന്നാനാണ്. മരിച്ചവരിൽനിന്ന് അവൻ ഉത്ഥിതനായിരിക്കുന്നു. അതുകൊണ്ടാണ്, ഈ ശക്തി ഇവനിൽ പ്രവർത്തിക്കുന്നത്.","p":1},{"v":3,"t":"ഹേരോധേസ് യോഹന്നാനെ ബന്ധിച്ച് കാരാഗൃഹത്തിൽ അടച്ചിരുന്നു. സ്വന്തം സഹോദരനായ പിലിപ്പോസിന്റെ ഭാര്യ ഹേരോദിയാ നിമിത്തമാണ് അവൻ ഇതുചെയ്തത്.","p":1},{"v":4,"t":"എന്തെന്നാൽ, യോഹന്നാൻ അവനോടു പറഞ്ഞിരുന്നു: അവളെ നീ സ്വന്തമാക്കുന്നത് നിയമാനുസുമല്ല.","p":1},{"v":5,"t":"ഹേറോദേസിന് അവനെ വധിക്കണമെന്നുണ്ടായിരുന്നു. എങ്കിലും, അവൻ ജനങ്ങളെ ഭയപ്പെട്ടു; എന്തെന്നാൽ, അവർ യോഹന്നാനെ പ്രവാചകനായി പരിഗണിച്ചിരുന്നു.","p":1},{"v":6,"t":"ഹേറോദേസിന്റെ ജന്മദിനത്തിൽ ഹേറോദിയായുടെ പുത്രി രാജസദസ്സിൽ നൃത്തംചെയ്ത് അവനെ സന്തോഷിപ്പിച്ചു. തന്മൂലം അവൾ ചോദിക്കുന്നതെന്തും നൽകാമെന്ന് രാജാവ് അവളോട് ആണയിട്ടു വാഗ്ദാനം ചെയ്തു.","p":1},{"v":8,"t":"അവൾ അമ്മയുടെ നിർബന്ധത്താൽ പറഞ്ഞു: സ്നാപകയോഹന്നാന്റെ ശിരസ്സ് ഒരു തളികയിൽവച്ച് എനിക്ക് തരുക.","p":1},{"v":9,"t":"രാജാവ് ദുഃഖിതനായി; എങ്കിലും തന്റെ ശപഥത്തെയും അതിഥികളെയും പരിഗണിച്ച് അത് അവൾക്കു നൽകാൻ അവൻ ആജ്ഞാപിച്ചു.","p":1},{"v":10,"t":"അവൻ കാരാഗൃഹത്തിൽ ആളയച്ച് യോഹന്നാൻ്റെ തല വെട്ടിയെടുത്തു.","p":1},{"v":11,"t":"അത് ഒരു തളികയിൽവച്ച് പെൺകുട്ടിക്ക് നൽകി. അവൾ അത് അമ്മയുടെ അടുത്തേക്കു കൊണ്ടുപോയി.","p":1},{"v":12,"t":"അവന്റെ ശിഷ്യർ ചെന്നു മൃതശരീരമെടുത്ത് സംസ്കരിച്ചു. അനന്തരം, അവർ പോയി യേശുവിനെ വിവരമറിയിച്ചു.","p":1},{"h":"അഞ്ചപ്പം അയ്യായിരംപേർക്ക്"},{"v":13,"t":"യേശു ഇതുകേട്ട് അവിടെനിന്നു പിൻവാങ്ങി, വഞ്ചിയിൽ കയറി, തനിച്ച് ഒരു വിജനസ്ഥലത്തേക്കു പോയി. ഇതറിഞ്ഞ ജനക്കൂട്ടം പട്ടണങ്ങളിൽനിന്ന് കരമാർഗം അവനെ പിൻതുടർന്നു.","p":1},{"v":14,"t":"അവൻ കരയ്ക്ക് ഇറങ്ങിയപ്പോൾ വലിയ ഒരു ജനക്കൂട്ടത്തെ കണ്ടു, അവരോട് അവന് അനുകമ്പ തോന്നി. അവരുടെയിടയിലെ രോഗികളെ അവൻ സുഖപ്പെടുത്തി.","p":1},{"v":15,"t":"സയാഹ്നമായപ്പോൾ ശിഷ്യന്മാർ അവനെ സമീപിച്ചുപറഞ്ഞു: ഇതൊരു വിജനസ്ഥലമാണ്; നേരം വൈകിയിയിരിക്കുന്നു. ഗ്രാമങ്ങളിൽ പോയി തങ്ങൾക്ക് ഭക്ഷണം വാങ്ങാൻ ഈ ജനക്കൂട്ടത്തെ പറഞ്ഞയക്കുക.","p":1},{"v":16,"t":"എന്നാൽ യേശു പറഞ്ഞു: അവർ പോകേണ്ട ആവശ്യമില്ല; നിങ്ങൾതന്നെ അവർക്ക് ഭക്ഷണം കൊടുക്കുവിൻ.","p":1},{"v":17,"t":"അവർ പറഞ്ഞു: അഞ്ചപ്പവും രണ്ടു മത്സ്യവുമല്ലാതെ ഞങ്ങൾക്ക് ഇവിടെ ഒന്നുമില്ല.","p":1},{"v":18,"t":"അപ്പോൾ അവൻ പറഞ്ഞു: അത് എന്റെ അടുത്തു കൊണ്ടുവരുക.","p":1},{"v":19,"t":"അവൻ ജനക്കൂട്ടത്തോട് പുൽത്തകിടിയിൽ ഇരിക്കാൻ കൽപ്പിച്ചശേഷം ആ അഞ്ചപ്പവും രണ്ടു മത്സ്യവും എടുത്ത്, സ്വർഗത്തിലേക്ക് നോക്കി വാഴ്ത്തി, മുറിച്ച്, ശിഷ്യന്മാരെ ഏൽപ്പിച്ചു; അവർ അതു ജനങ്ങൾക്ക് വിളമ്പി.","p":1},{"v":20,"t":"അവരെല്ലാവരും ഭക്ഷിച്ചു തൃപ്തരായി. ബാക്കിവന്ന കഷണങ്ങൾ പന്ത്രണ്ടു കുട്ടനിറയെ ശേഖരിച്ചു.","p":1},{"v":21,"t":"ഭക്ഷിച്ചവർ, സ്ത്രീകളും കുട്ടികളുമൊഴികെ, അയ്യായിരത്തോളം പുരുഷന്മാരായിയിരുന്നു.","p":1},{"h":"വെള്ളത്തിന്മേൽ നടക്കുന്നു"},{"v":22,"t":"ജനക്കൂട്ടത്തെ പറഞ്ഞുവിടുന്നതിനിടയിൽ, തനിക്കു മുമ്പേ വഞ്ചിയിൽ കയറി ഉടനെ മറുകരയ്ക്കു പോകാൻ അവൻ ശിഷ്യന്മാരെ നിർബന്ധിച്ചു.","p":1},{"v":23,"t":"അവൻ ജനക്കൂട്ടത്തെ പിരിച്ചുവിട്ടശേഷം ഏകാന്തതയിൽ പ്രാർത്ഥിക്കാൻ മലയിലേക്ക് കയറി. സായാഹ്നം ആയപ്പോഴേക്കും അവൻ അവിടെ തനിയെ ആയിരുന്നു","p":1},{"v":24,"t":"ഇതിനിടെ വഞ്ചി കരയിൽ നിന്ന് ഏറെ അകലെയായി കഴിഞ്ഞിരുന്നു കാറ്റ് പ്രതികൂലമായിരുന്നതിനാൽ തിരമാലകളിൽപ്പെട്ട് അത് വല്ലാതെ ഉലഞ്ഞു"},{"v":25,"t":"രാത്രിയുടെ നാലാം യാമത്തിൽ അവൻ കടലിനുമീതേ നടന്നു അവരുടെ അടുത്തേക്ക് ചെന്നു.","p":1},{"v":26,"t":"അവൻ കടലിനുമീതേ നടക്കുന്നതു കൊണ്ട് ശിഷ്യന്മാർ പരിഭ്രാന്തനായി ഇതാ ഭൂതം എന്ന് പറഞ്ഞ് ഭയം നിമിത്തം നിലവിളിച്ചു","p":1},{"v":27,"t":"ഉടനെ അവൻ അവരോട് സംസാരിച്ചു: ധൈര്യത്തോടിരിക്കുവിൻ, ഞാനാണ്, ഭയപ്പെടേണ്ട.","p":1},{"v":28,"t":"പത്രോസ് അവനോടു പറഞ്ഞു: കർത്താവേ, അങ്ങാണെങ്കിൽ ഞാൻ ജലത്തിനു മീതേകൂടി അങ്ങയുടെ അടുത്തേക്കു വരാൻ എന്നോട് കല്പിക്കുക.","p":1},{"v":28,"t":"വരൂ, അവൻ പറഞ്ഞു.","p":1},{"v":29,"t":"പത്രോസ് വഞ്ചിയിൽനിന്ന് ഇറങ്ങി വെള്ളത്തിനു മുകളിലൂടെ നടന്ന് യേശുവിന്റെ അടുത്തേക്കു ചെന്നു.","p":1},{"v":30,"t":"എന്നാൽ, ശക്തമായ കാറ്റു കണ്ട് അവൻ ഭയന്നു. ജലത്തിൽ മുങ്ങിത്താഴാൻ തുടങ്ങിയപ്പോൾ അവൻ നിലവിളിച്ചു പറഞ്ഞു: കർത്താവേ, എന്നെ രക്ഷിക്കണേ!","p":1},{"v":31,"t":"ഉടനെ യേശു കൈനീട്ടി അവനെ പിടിച്ചുകൊണ്ടു ചോദിച്ചു: അല്പവിശ്വാസി, നീ എന്തുകൊണ്ട് സംശയിച്ചു?","p":1},{"v":32,"t":"അവർ വഞ്ചിയിൽ കയറിയപ്പോൾ കാറ്റു ശമിച്ചു.","p":1},{"v":33,"t":"വഞ്ചിയിലുണ്ടായിരുന്നവർ അവനെ ആരാധിച്ചുകൊണ്ട്, സത്യമായും നീ ദൈവപുത്രനാണ് എന്നു പറഞ്ഞു.","p":1},{"h":"ഗനേസറത്തിലെ അത്ഭുതങ്ങൾ"},{"v":34,"t":"അനന്തരം, അവർ അക്കരയ്ക്ക് കടന്ന് ഗനേസരാത്ത് പ്രദേശത്തെത്തി.","p":1},{"v":35,"t":"ആ സ്ഥലത്തെ ആളുകൾ അവനെ തിരിച്ചറിഞ്ഞ്, ചുറ്റുമുള്ള പ്രദേശങ്ങളിലെല്ലാം ആളയച്ച് സകല രോഗികളെയും അവന്റെയടുത്തു കൊണ്ടുവന്നു.","p":1},{"v":36,"t":"അവന്റെ വസ്ത്രത്തിന്റെ വിളുമ്പിലെങ്കിലും തൊടട്ടേയെന്ന് അവർ അവനോട് യാചിച്ചുകൊണ്ടിരുന്നു. സ്പർശിച്ചവരെല്ലാം സുഖംപ്രാപിക്കുകയും ചെയ്തു.","p":1}],"15":[{"h":"പാരമ്പര്യത്തെക്കുറിച്ച് തർക്കം"},{"v":1,"t":"അനന്തരം ജെറുസലേമിൽ നിന്ന് ഫരിസേയരും നിയമജ്ഞരും യേശുവിൻ്റെ അടുത്ത് വന്നു പറഞ്ഞു.","p":1},{"v":2,"t":"നിന്റെ ശിഷ്യന്മാർ പൂർവികരുടെ പാരമ്പര്യം ലംഘിക്കുന്നതെന്തുകൊണ്ട് ഭക്ഷണം","p":1},{"v":2,"t":"കഴിക്കുന്നതിനുമുമ്പ് അവർ കൈകഴുകുന്നില്ലല്ലോ.","p":1},{"v":3,"t":"അവൻ മറുപടി പറഞ്ഞു: നിങ്ങളുടെ പാരമ്പര്യത്തിന്റെ പേരിൽ നിങ്ങൾ ദൈവത്തിന്റെ പ്രമാണം ലംഘിക്കുന്നതെന്തുകൊണ്ട്?","p":1},{"v":4,"t":"എന്തെന്നാൽ, പിതാവിനെയും മാതാവിനെയും ബഹുമാനിക്കുക; പിതാവിനെയോ മാതാവിനെയോ നിന്ദിക്കുന്നവൻ മരിക്കണം എന്നു ദൈവം കല്പിച്ചിരിക്കുന്നു.","p":1},{"v":5,"t":"എന്നാൽ, നിങ്ങൾ പറയുന്നു, ആരെങ്കിലും തന്റെ പിതാവിനോടോ മാതാവിനോടോ, എന്നിൽനിന്നു നിങ്ങൾക്ക് ലഭിക്കേണ്ടത്, ദൈവത്തിന് അർപ്പിതം എന്നു പറഞ്ഞാൽ പിന്നെ അവൻ തന്റെ പിതാവിനെ ബഹുമാനിക്കേണ്ടതില്ല.","p":1},{"v":6,"t":"ഇങ്ങനെ, നിങ്ങളുടെ പാരമ്പര്യത്തിനുവേണ്ടി ദൈവവചനം നിങ്ങൾ വ്യർത്ഥമാക്കിയിരിക്കുന്നു.","p":1},{"v":7,"t":"കപടനാട്യക്കാരെ, ഏശയ്യാ നിങ്ങളെപ്പറ്റി ശരിയായിത്തന്നെ പ്രവചിച്ചു:","p":1},{"v":8,"t":"ഈ ജനം അധരംകൊണ്ട് എന്നെ ബഹുമാനിക്കുന്നു; എന്നാൽ, അവരുടെ ഹൃദയം എന്നിൽനിന്ന് ഏറെ അകലെയാണ്.","p":1},{"v":9,"t":"അവർ മനുഷ്യനിയമങ്ങൾ കല്പനകളായി പഠിപ്പിച്ചുകൊണ്ട് വ്യർത്ഥമായി എന്നെ ആരാധിക്കുന്നു."},{"h":"ആന്തരികവും ബാഹ്യവുമായ ശുദ്ധി"},{"v":10,"t":"അവൻ ജനങ്ങളെ തന്റെ അടുത്തു വിളിച്ചു പറഞ്ഞു:","p":1},{"v":11,"t":"നിങ്ങൾ കേട്ടുമനസ്സിലാക്കുവിൻ; വായിലേക്ക് പ്രവേശിക്കുന്നതല്ല, വായിൽനിന്നു വരുന്നതാണ് ഒരുവനെ അശുദ്ധനാക്കുന്നത്.","p":1},{"v":12,"t":"അപ്പോൾ ശിഷ്യന്മാർ അടുത്തു വന്നു പറഞ്ഞു: ഈ വചനം ഫരിസേയർക്ക് ഇടർച്ചയുണ്ടാക്കിയെന്ന് നീ അറിയുന്നുവോ?","p":1},{"v":13,"t":"അവൻ മറുപടി പറഞ്ഞു: എന്റെ സ്വർഗീയപിതാവ് നട്ടതല്ലാത്ത ചെടികളൊക്കെയും പിഴുതുമാറ്റപ്പെടും.","p":1},{"v":14,"t":"അവരെ വിട്ടേക്കു; അവർ അന്ധർക്ക് വഴികാട്ടികളായ അന്ധരാണ്. അന്ധൻ അന്ധനെ നയിച്ചാൽ ഇരുവരും കുഴിയിൽ വീഴും.","p":1},{"v":15,"t":"മറുപടിയായി പത്രോസ് അപേക്ഷിച്ചു: ഈ ഉപമ ഞങ്ങൾക്കു വിശദീകരിച്ചിതരണം.","p":1},{"v":16,"t":"അവൻ പറഞ്ഞു: നിങ്ങൾ ഇപ്പോഴും ഗ്രഹണശക്തിയില്ലാത്തവരാണോ?","p":1},{"v":17,"t":"വായിൽ പ്രവേശിക്കുന്നവ ഉദരത്തിലേക്ക് പോകുന്നുവെന്നും അവിടെനിന്ന് അത് വിസർജ്ജിക്കപ്പെടുന്നുവെന്നും നിങ്ങൾ ഗ്രഹിക്കുന്നില്ലേ?","p":1},{"v":18,"t":"എന്നാൽ, വായിൽനിന്നു വരുന്നത് ഹൃദയത്തിൽനിന്നാണു പുറപ്പെടുന്നത്.","p":1},{"v":18,"t":"അത് മനുഷ്യനെ അശുദ്ധനാക്കുന്നു.","p":1},{"v":19,"t":"കാരണം, ദുഷ്ചിന്തകൾ, കൊലപാതകം, പരസംഗം, വ്യഭിചാരം, മോഷണം, കള്ളസാക്ഷ്യം, ദൈവദൂഷണം എന്നിവയെല്ലാം ഹൃദയത്തിൽനിന്നാണു പുറപ്പെടുന്നത്.","p":1},{"v":20,"t":"ഇവയാണ് മനുഷ്യനെ അശുദ്ധനാക്കുന്നത് എന്നാൽ കഴുകാത്ത കൈകൊണ്ട് ഭക്ഷിക്കുന്നത് ആരെയും അശുദ്ധനാക്കുന്നില്ല.","p":1},{"h":"കാനാൻകാരിയുടെ വിശ്വാസം"},{"v":21,"t":"യേശു അവിടെനിന്ന് പുറപ്പെട്ട് ടയിർ സീദോൺ എന്നീ പ്രദേശങ്ങളിലേക്കു പോയി.","p":1},{"v":22,"t":"അപ്പോൾ ആ പ്രദേശത്തുനിന്ന് ഒരു കാനാൻകാരി വന്ന് കരഞ്ഞുകൊണ്ട് പറഞ്ഞു: കർത്താവേ, ദാവീദിന്റെ പുത്രാ, എന്നിൽ കനിയണമേ! എന്റെ മകളെ പിശാച് കഠിനമായി ബാധിച്ചിരിക്കുന്നു.","p":1},{"v":23,"t":"എന്നാൽ, അവൻ ഒരു വാക്കുപോലും ഉത്തരം പറഞ്ഞില്ല. ശിഷ്യന്മാർ വന്ന് അവനോട് അഭ്യർത്ഥിച്ചു: അവളെ പറഞ്ഞയച്ചാലും; അവൾ നമ്മുടെ പിന്നാലെ വന്ന് നിലവിളിക്കുന്നുണ്ടല്ലോ.","p":1},{"v":24,"t":"അവൻ മറുപടി പറഞ്ഞു: ഇസ്രായേൽ ഭവനത്തിലെ നഷ്ടപ്പെട്ട ആടുകളുടെ അടുത്തേക്കു മാത്രമാണ് ഞാൻ അയക്കപ്പെട്ടിരിക്കുന്നത്.","p":1},{"v":25,"t":"എന്നാൽ, അവൾ വന്ന് അവന്റെ മുമ്പിൽ സാഷ്ടാംഗം പ്രണമിച്ചുകൊണ്ട് പറഞ്ഞു: കർത്താവേ, എന്നെ സഹായിക്കണമേ.","p":1},{"v":26,"t":"അവൻ പറഞ്ഞു: മക്കളുടെ അപ്പമെടുത്ത് നായ്ക്കുട്ടികൾക്ക് എറിഞ്ഞുകൊടുക്കുന്നത് ഉചിതമല്ല.","p":1},{"v":27,"t":"പക്ഷേ, അവൾ പറഞ്ഞു: അതേ കർത്താവേ, നായ്ക്കുട്ടികൾപോലും യജമാനന്മാരുടെ മേശയിൽ നിന്ന് വീഴുന്ന അപ്പക്കഷണങ്ങൾ തിന്നുന്നുണ്ടല്ലോ.","p":1},{"v":28,"t":"അപ്പോൾ യേശു പറഞ്ഞു: സ്ത്രീയേ, നിന്റെ വിശ്വാസം വലുതാണ്. നീ ആഗ്രഹിക്കുന്നപോലെ നിനക്കു ഭവിക്കട്ടെ. ആ സമയംമുതൽ അവളുടെ പുത്രി സൗഖ്യമുള്ളവളായി.","p":1},{"h":"അനേകർക്കു രോഗശാന്തി"},{"v":29,"t":"യേശു അവിടെനിന്ന് പുറപ്പെട്ട് ഗലീലക്കടലിന്റെ തീരത്തുവന്ന് ഒരു മലയിൽക്കറി അവിടെ ഇരുന്നു.","p":1},{"v":30,"t":"അപ്പോൾ വലിയ ജനക്കൂട്ടം അവന്റെ അടുക്കലേക്കു വന്നു. അവരുടെ കൂടെയുള്ള മുടന്തർ, വികലാംഗർ, അന്ധർ, ഊമകൾ എന്നിവരെയും മറ്റനേകപേരെയും അവന്റെ പാദത്തിങ്കൽ കിടത്തി. അവൻ അവരെ സുഖപ്പെടുത്തി.","p":1},{"v":31,"t":"ഊമകൾ സംസാരിക്കുന്നതും വികലാംഗർ സുഖപ്രാപിക്കുന്നതും മുടന്തർ നടക്കുന്നതും അന്ധർ കാഴ്ചപ്രാപിക്കുന്നതും കണ്ട് ജനക്കൂട്ടം വിസ്മയിച്ചു. അവർ ഇസ്രായേലിന്റെ ദൈവത്തെ മഹത്വപ്പെടുത്തി.","p":1},{"h":"ഏഴപ്പം നാലായിരംപേർക്ക്"},{"v":32,"t":"പിന്നീട് യേശു തന്റെ ശിഷ്യന്മാരെ അടുക്കലേക്ക് വിളിച്ചുപറഞ്ഞു: ഈ ജനക്കൂട്ടത്തോട് എനിക്ക് അനുകമ്പ തോന്നുന്നു. എന്തെന്നാൽ, മൂന്നദിവസമായി അവർ എന്നോടുകൂടെയാണ്; അവർക്കു ഭക്ഷിക്കാൻ ഒന്നുമില്ല. വഴിയിൽ തളർന്നുവീഴാനിടയുള്ളതിനാൽ, വിശക്കുന്നവരായി അവരെ പറഞ്ഞയക്കാൻ എനിക്ക് മനസ്സുവരുന്നില്ല.","p":1},{"v":33,"t":"ശിഷ്യന്മാർ ചോദിച്ചു: ഇത്ര വലിയ ജനക്കൂട്ടത്തെ തൃപ്തിപ്പെടുത്താൻ വേണ്ടത്ര അപ്പം ഈ മരുഭൂമിയിൽ നമുക്ക് എവിടെനിന്നു കിട്ടും?","p":1},{"v":34,"t":"യേശു അവരോട് ചോദിച്ചു: നിങ്ങളുടെ പക്കൽ എത്ര അപ്പമുണ്ട്? അവർ പറഞ്ഞു: ഏഴ്; കുറെ ചെറിയ മത്സ്യവും ഉണ്ട്.","p":1},{"v":35,"t":"ജനക്കൂട്ടത്തോട് നിലത്തിരിക്കാൻ ആജ്ഞാപിച്ചിട്ട്,","p":1},{"v":36,"t":"അവൻ ഏഴപ്പവും മത്സ്യവും എടുത്ത് കൃതജ്ഞതാസ്തോത്രം ചെയ്ത്, മുറിച്ച് ശിഷ്യന്മാർക്കു കൊടുത്തു. ശിഷ്യന്മാരാകട്ടെ, ജനക്കൂട്ടത്തിനു വിളമ്പി. എല്ലാവരും ഭക്ഷിച്ചുതൃപ്തരായി.","p":1},{"v":37,"t":"ബാക്കി വന്ന കഷണങ്ങൾ ഏഴുകുട്ടനിറയെ അവർ ശേഖരിച്ചു.","p":1},{"v":38,"t":"ഭക്ഷിച്ചവർ, സ്ത്രീകളും കുട്ടികളും ഒഴികെ, നാലായിരം പുരുഷന്മാരായിരുന്നൂ.","p":1},{"v":39,"t":"ജനക്കൂട്ടത്തെ പറഞ്ഞയച്ചിട്ട്, അവൻ വഞ്ചിയിൽ കയറി മഗദാൻ പ്രദേശത്തേക്കു പോയി.","p":1}],"16":[{"h":"കാലത്തിന്റെ അടയാളങ്ങൾ"},{"v":1,"t":"(മർക്കോ 8,11-13; ലൂക്കാ 12,54-56) അനന്തരം ഫരിസേയരും സദ്ദുക്കായരും അവനെ പരീക്ഷിക്കാൻ അടുക്കലെത്തി, സ്വർഗ്ഗത്തിൽനിന്ന് ഒരു അടയാളം തങ്ങളെ കാണിച്ചുതരണമെന്ന് ആവശ്യപ്പെട്ടു.","p":1},{"v":2,"t":"അവൻ മറുപടി പറഞ്ഞു: വൈകുന്നേരമാകുമ്പോൾ നിങ്ങൾ പറയുന്നു, നല്ല കാലാവസ്ഥയായിരിക്കും. കാരണം, ആകാശം ചെമന്നിരിക്കുന്നു.","p":1},{"v":3,"t":"എന്നാൽ, പ്രഭാതത്തിൽ നിങ്ങൾ പറയുന്നു, ഇന്ന് കാറ്റും കോളുമുണ്ടാകും. കാരണം, ആകാശം ചെമന്നുമൂടിയിരിക്കുന്നു. ആകാശത്തിന്റെ ഭാവഭേദങ്ങൾ വിവേചിച്ചറിയാൻ നിങ്ങൾക്കു കഴിയുന്നു. എന്നാൽ, കാലത്തിന്റെ അടയാളങ്ങൾ തിരിച്ചറിയാൻ നിങ്ങൾക്കു കഴിയുകയില്ലേ?","p":1},{"v":4,"t":"ദുഷിച്ചതും അവിശ്വസ്തവുമായ തലമുറ അടയാളം അന്വേഷിക്കുന്നു. യോനായുടെ അടയാളമല്ലാതെ മറ്റൊരു അടയാളവും അതിനു നൽകപ്പെടുകയില്ല. അനന്തരം അവൻ അവരെ വിട്ടുപോയി.","p":1},{"h":"ഫരിസേയരുടേയും സദ്ദുക്കായരുടെയും പുളിമാവ്"},{"v":4,"t":"(മർക്കോസ് 8,14-21)","p":1},{"v":5,"t":"പിന്നീട് മറുകരയിലേക്ക് പോകുമ്പോൾ അപ്പമെടുക്കാൻ ശിഷ്യന്മാർ മറന്നിരുന്നു.","p":1},{"v":6,"t":"യേശു പറഞ്ഞു: ഫരിസേയരുടെയും സദ്ദുക്കായരുടെയും പുളിമാവിനെ ശ്രദ്ധയോടെ സൂക്ഷിച്ചുകൊള്ളുവിൻ.","p":1},{"v":7,"t":"നാം അപ്പമൊന്നും എടുക്കാത്തതുകൊണ്ടായിരിക്കാം എന്ന് അവർ പരസ്പരം പറഞ്ഞു.","p":1},{"v":8,"t":"യേശു ഇത് അറിഞ്ഞ് അവരോട് ചോദിച്ചു: അല്പവിശ്വാസികളേ, അപ്പമില്ലാത്തതിനെപ്പറ്റി നിങ്ങൾ പരസ്പരം സംസാരിക്കുന്നതെന്തിന്?","p":1},{"v":9,"t":"നിങ്ങൾ ഗ്രഹിക്കുന്നില്ലയോ? അയ്യായിരം പേരുടെ അഞ്ചപ്പം നിങ്ങൾ ഓർമ്മിക്കുന്നില്ലേ? എത്ര കൂട്ട അപ്പക്കഷണങ്ങൾ നിങ്ങൾ ശേഖരിച്ചു?","p":1},{"v":10,"t":"നാലായിരം പേരുടെ ഏഴപ്പവും നിങ്ങൾ ഓർമ്മിക്കുന്നില്ലേ? അന്ന് എത്ര കൂട്ടകളാണ് നിങ്ങൾ നിറച്ചത്?","p":1},{"v":11,"t":"ഞാൻ അപ്പത്തെപ്പറ്റിയല്ല സംസാരിച്ചതെന്ന് നിങ്ങൾ മനസ്സിലാക്കാത്തതെന്തുകൊണ്ട്? ഫരിസേയരുടെയും സദ്ദുക്കായരുടെയും പുളിമാവിനെ സൂക്ഷിച്ചുകൊള്ളുവിൻ.","p":1},{"v":12,"t":"അപ്പത്തിന്റെ പുളിമാവിനെപ്പറ്റിയല്ല, ഫരിസേയരുടെയും സദ്ദുക്കായരുടെയും പ്രബോധനത്തെപ്പറ്റിയാണ് സൂക്ഷിച്ചുകൊള്ളാൻ അവൻ അരുൾചെയ്തതെന്ന് അവർക്ക് അപ്പോൾ മനസ്സിലായി.","p":1},{"v":12,"t":"പത്രോസിന്റെ വിശ്വാസപ്രഖ്യാപനം (മർക്കോസ് 8,27-30; ലൂക്കാ 9,18-21)","p":1},{"v":13,"t":"കേസറിയാ ഫിലിപ്പിപ്രദേശത്ത് എത്തിയപ്പോൾ യേശു തന്റെ ശിഷ്യന്മാരോട് ചോദിച്ചു: മനുഷ്യപുത്രൻ ആരെന്നാണ് ആളുകൾ പറയുന്നത്?","p":1},{"v":14,"t":"അവർ പറഞ്ഞു: ചിലർ സ്നാപകയോഹന്നാൻ എന്നും മറ്റു ചിലർ ഏലിയാ എന്നും വേറെ ചിലർ ജെറമിയാ അല്ലെങ്കിൽ പ്രവാചകന്മാരിലൊരുവൻ എന്നും പറയുന്നു.","p":1},{"v":15,"t":"അവൻ അവരോട് ചോദിച്ചു: എന്നാൽ ഞാൻ ആരെെന്നാണ് നിങ്ങൾ പറയുന്നത്?","p":1},{"v":16,"t":"ശിമയോൻ പത്രോസ് പറഞ്ഞു: നീ ജീവിക്കുന്ന ദൈവത്തിന്റെ പുത്രനായ ക്രിസ്തുവാണ്.","p":1},{"v":17,"t":"യേശു അവനോട് അരുൾചെയ്തു: യോനായുടെ പുത്രനായ ശിമയോനേ, നീ അനുഗൃഹീതൻ! എന്തെന്നാൽ, മാംസവും രക്തവുമല്ല, സ്വർഗസ്ഥനായ എന്റെ പിതാവാണ് നിനക്ക് ഇത് വെളിപ്പെടുത്തിത്തന്നത്.","p":1},{"v":18,"t":"ഞാൻ നിന്നോട് പറയുന്നു: നീ പത്രോസാണ്, ഈ പാറമേൽ എന്റെ സഭ ഞാൻ പണിയും. നരകകവാടങ്ങൾ അതിനെതിരെ പ്രബലപ്പെടുകയില്ല.","p":1},{"v":19,"t":"സ്വർഗരാജ്യത്തിന്റെ താക്കോലുകൾ നിനക്ക് ഞാൻ തരും. നീ ഭൂമിയിൽ കെട്ടുന്നതെല്ലാം സ്വർഗത്തിലും കെട്ടപ്പെട്ടിരിക്കും; നീ ഭൂമിയിൽ അഴിക്കുന്നതെല്ലാം സ്വർഗ്ഗത്തിലും അഴിക്കപ്പെട്ടിരിക്കും","p":1},{"v":20,"t":"അനന്തരം ക്രിസ്തുവാണെന്ന് ആരോടും പറയരുതെന്ന് അവൻ ശിഷ്യന്മാരോട് കൽപ്പിച്ചു","p":1},{"v":20,"t":"പീഡാനുഭവവും ഉത്ഥാനവും - ഒന്നാംപ്രവചനം (മർക്കോസോ 8,31-9,1; ലൂക്കാ 9,22-27)","p":1},{"v":21,"t":"അപ്പോൾ മുതൽ യേശു, തനിക്കു ജെറുസലേമിലേക്കു പോകേണ്ടിയിരിക്കുന്നുവെന്നും ശ്രേഷ്ഠന്മാരിൽനിന്നും പുരോഹിതപ്രമുഖന്മാരിൽനിന്നും നിയമജ്ഞരിൽനിന്നും വളരെയേറെ സഹിക്കേണ്ടിവരുമെന്നും താൻ വധിക്കപ്പെടുമെന്നും എന്നാൽ മൂന്നാംദിവസം ഉയിർപ്പിക്കപ്പെടുമെന്നും ശിഷ്യന്മാരെ അറിയിച്ചു തുടങ്ങി.","p":1},{"v":22,"t":"പത്രോസ് അവനെ മാറ്റിനിർത്തി തടസ്സം പറയാൻ തുടങ്ങി: ദൈവം കനിയട്ടെ! കർത്താവേ, ഇതൊരിക്കലും നിനക്കു ഭവിക്കാതിരിക്കട്ടെ.","p":1},{"v":23,"t":"യേശു തിരിഞ്ഞ് പത്രോസിനോട് പറഞ്ഞു: സാത്താനേ, നീ എന്റെ പിന്നിലേക്കു പോകൂ, നീ എനിക്ക് തടസ്സമാണ്. കാരണം, നീ ചിന്തിക്കുന്നത് ദൈവികകാര്യങ്ങളല്ല, മാനുഷികകാര്യങ്ങളാണ്.","p":1},{"v":24,"t":"അനന്തരം, യേശു തന്റെ ശിഷ്യന്മാരോട് അരുൾചെയ്തു: ആരെങ്കിലും എന്റെ പിന്നാലെ വരാൻ ആഗ്രഹിക്കുന്നുവെങ്കിൽ അവൻ സ്വയംപരിത്യജിച്ച്, തന്റെ കുരിശെടുത്ത് എന്നെ അനുഗമിക്കട്ടെ.","p":1},{"v":25,"t":"എന്തെന്നാൽ, സ്വന്തംജീവൻ രക്ഷിക്കാൻ ആഗ്രഹിക്കുന്നവൻ അതു നഷ്ടപ്പെടുത്തും; എന്നാൽ, ആരെങ്കിലും എനിക്ക് വേണ്ടി സ്വന്തംജീവൻ നഷ്ടപ്പെടുത്തിയാൽ അവൻ അതു കണ്ടെത്തും.","p":1},{"v":26,"t":"ഒരുവൻ ലോകം മുഴുവൻ നേടിയാലും സ്വന്തംജീവൻ നഷ്ടപ്പെടുത്തിയാൽ അവന് എന്തു പ്രയോജനം? കാരണം, ഒരുവൻ സ്വന്തംജീവനു പകരമായി എന്തു കൊടുക്കും?","p":1},{"v":27,"t":"മനുഷ്യപുത്രൻ തന്റെ പിതാവിന്റെ മഹത്വത്തിൽ ദൂതന്മാരോടുകൂടെ വരാൻ പോകുന്നു. അപ്പോൾ അവൻ ഓരോരുത്തർക്കും താന്താങ്ങളുടെ പ്രവൃത്തിക്കനുസരിച്ചു പ്രതിഫലം നൽകും.","p":1},{"v":28,"t":"സത്യമായി ഞാൻ നിങ്ങളോട് പറയുന്നു: മനുഷ്യപുത്രൻ തന്റെ രാജ്യത്തിൽ വരുന്നത് ദർശിക്കുന്നതിനു മുൻപ് ഇവിടെ നിൽക്കുന്നവരിൽ ചിലർ മരിക്കുകയില്ല.","p":1}],"17":[{"h":"യേശു രൂപാന്തരപ്പെടുന്നു"},{"v":1,"t":"യേശു, ആറുദിവസം കഴിഞ്ഞ് പത്രോസ്, യാക്കോബ്, അവന്റെ സഹോദരൻ യോഹന്നാൻ എന്നിവരെ മാത്രം കൂട്ടിക്കൊണ്ട് ഒരു ഉയർന്ന മലയിലേക്കു പോയി.","p":1},{"v":2,"t":"അവൻ അവരുടെ മുമ്പിൽവച്ചു രൂപാന്തരപ്പെട്ടു. അവന്റെ മുഖം സൂര്യനെപ്പോലെ വെട്ടിത്തിളങ്ങി. അവന്റെ വസ്ത്രങ്ങൾ പ്രകാശംപോലെ ധവളമായി."},{"v":3,"t":"മോശയും ഏലിയായും അവനോടു സംസാരിക്കുന്നതായി അവർക്കു കാണപ്പെട്ടു."},{"v":4,"t":"പത്രോസ് യേശുവിനോടു പറഞ്ഞു: കർത്താവേ, നാം ഇവിടെയായിരിക്കുന്നതു നല്ലതാണ്. നിനക്കു സമ്മതമാണെങ്കിൽ ഞാൻ ഇവിടെ മൂന്നു കൂടാരങ്ങൾ ഉണ്ടാക്കാം - ഒന്നു നിനക്ക്, ഒന്നു മോശയ്ക്ക്, ഒന്ന് ഏലിയായ്ക്ക്."},{"v":5,"t":"അവൻ സംസാരിച്ചുകൊണ്ടിരിക്കുമ്പോൾ തിളക്കമേറിയ ഒരു മേഘംവന്ന് അവരെ ആവരണംചെയ്തു. മേഘത്തിൽനിന്ന് ഇങ്ങനെയൊരു സ്വരമുണ്ടായി: ഇവൻ എന്റെ പ്രിയപുത്രൻ; ഇവനിൽ ഞാൻ പ്രസാദിച്ചിരിക്കുന്നു. ഇവനെ ശ്രവിക്കുവിൻ!"},{"v":6,"t":"ഇതുകേട്ടപ്പോൾ ശിഷ്യന്മാർ കമിഴ്ന്നുവീണു. അവർ അത്യധികം ഭയപ്പെട്ടിരുന്നു."},{"v":7,"t":"യേശു സമീപിച്ച് അവരെ സ്പർശിച്ചുകൊണ്ടു പറഞ്ഞു: എഴുന്നേല്ക്കുവിൻ, ഭയപ്പെടേണ്ടാ."},{"v":8,"t":"അവർ കണ്ണുകളുയർത്തി നോക്കിയപ്പോൾ യേശുവിനെയല്ലാതെ മറ്റാരെയും കണ്ടില്ല."},{"h":"ഏലിയായുടെ ആഗമനം"},{"v":9,"t":"മലയിൽനിന്ന് ഇറങ്ങുമ്പോൾ യേശു അവരോട് ആജ്ഞാപിച്ചു: മനുഷ്യപുത്രൻ മരിച്ചവരിൽനിന്ന് ഉയിർപ്പിക്കപ്പെടുന്നതുവരെ നിങ്ങൾ ഈ ദർശനത്തെപ്പറ്റി ആരോടും പറയരുത്.","p":1},{"v":10,"t":"ശിഷ്യന്മാർ അവനോടു ചോദിച്ചു: ആദ്യം ഏലിയാ വരണമെന്ന് നിയമജ്ഞർ പറയുന്നതെന്തുകൊണ്ട്?"},{"v":11,"t":"അവൻ പറഞ്ഞു: ഏലിയാ വന്ന് എല്ലാം പുനഃസ്ഥാപിക്കുകതന്നെ ചെയ്യും."},{"v":12,"t":"എന്നാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു, ഏലിയാ വന്നു കഴിഞ്ഞു. എങ്കിലും അവർ അവനെ തിരിച്ചറിഞ്ഞില്ല. മാത്രമല്ല, തോന്നിയതെല്ലാം അവർ അവനോടു ചെയ്തു. അതുപോലെ, മനുഷ്യപുത്രനും അവരിൽനിന്നു പീഡകളേല്ക്കാൻ പോകുന്നു."},{"v":13,"t":"സ്നാപകയോഹന്നാനെപ്പറ്റിയാണ് അവൻ തങ്ങളോടു സംസാരിച്ചതെന്ന് അപ്പോൾ ശിഷ്യന്മാർക്കു മനസ്സിലായി."},{"h":"അപസ്മാരരോഗിയെ സുഖപ്പെടുത്തുന്നു"},{"v":14,"t":"അവർ ജനക്കൂട്ടത്തിന്റെ അടുത്തേക്കു വന്നപ്പോൾ ഒരാൾ കടന്നുവന്ന് അവന്റെ മുമ്പിൽ മുട്ടുകുത്തിക്കൊണ്ടു പറഞ്ഞു:","p":1},{"v":15,"t":"കർത്താവേ, എന്റെ പുത്രനിൽ കനിയണമേ; അവൻ അപസ്മാരം പിടിപെട്ട് വല്ലാതെ കഷ്ടപ്പെടുന്നു. കാരണം, പലപ്പോഴും അവൻ തീയിലും വെള്ളത്തിലും വീഴുന്നു."},{"v":16,"t":"ഞാൻ അവനെ നിന്റെ ശിഷ്യന്മാരുടെ അടുത്തുകൊണ്ടുവന്നു. പക്ഷേ, അവനെ സുഖപ്പെടുത്താൻ അവർക്കു കഴിഞ്ഞില്ല."},{"v":17,"t":"യേശു പ്രതിവചിച്ചു: വിശ്വാസമില്ലാത്തതും വഴിപിഴച്ചതുമായ തലമുറയേ, എത്രനാൾ ഞാൻ നിങ്ങളുടെ കൂടെയുണ്ടായിരിക്കും! എത്രനാൾ ഞാൻ നിങ്ങളെ സഹിക്കണം! അവനെ ഇവിടെ എന്റെ അടുത്തു കൊണ്ടുവരുക."},{"v":18,"t":"യേശു അതിനെ ശാസിച്ചു. പിശാച് അവനെ വിട്ടുപോയി. തത്ക്ഷണം ബാലൻ സുഖം പ്രാപിച്ചു."},{"v":19,"t":"അനന്തരം, ശിഷ്യന്മാർ മാത്രമായി യേശുവിനെ സമീപിച്ചു ചോദിച്ചു: എന്തുകൊണ്ടാണ് അതിനെ ബഹിഷ്കരിക്കാൻ ഞങ്ങൾക്കു കഴിയാതെ പോയത്?"},{"v":20,"t":"യേശു പറഞ്ഞു: നിങ്ങളുടെ അല്പവിശ്വാസം കൊണ്ടുതന്നെ. സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, നിങ്ങൾക്കു കടുകുമണിയോളം വിശ്വാസമുണ്ടെങ്കിൽ ഈ മലയോട്, ഇവിടെനിന്നു മാറി മറ്റൊരു സ്ഥലത്തേക്കു നീങ്ങുക എന്നു പറഞ്ഞാൽ അതു നീങ്ങിപ്പോകും."},{"v":21,"t":"നിങ്ങൾക്ക് ഒന്നും തന്നെ അസാധ്യമായിരിക്കുകയില്ല."},{"h":"പീഡാനുഭവവും ഉത്ഥാനവും - രണ്ടാംപ്രവചനം"},{"v":22,"t":"അവർ ഗലീലിയിൽ ഒരുമിച്ചുകൂടിയപ്പോൾ യേശു അവരോടു പറഞ്ഞു: മനുഷ്യപുത്രൻ മനുഷ്യരുടെ കൈകളിൽ ഏല്പിക്കപ്പെടാൻ പോകുന്നു.","p":1},{"v":23,"t":"അവർ അവനെ വധിക്കും; എന്നാൽ മൂന്നാം ദിവസം അവൻ ഉയിർപ്പിക്കപ്പെടും. അപ്പോൾ അവർ അതീവം ദുഃഖിതരായിത്തീർന്നു."},{"h":"നികുതിയെക്കുറിച്ച്"},{"v":24,"t":"അവർ കഫർണാമിലെത്തിയപ്പോൾ ദേവാലയനികുതി പിരിക്കുന്നവർ പത്രോസിന്റെ അടുത്തുചെന്നു ചോദിച്ചു: നിങ്ങളുടെ ഗുരു നികുതികൊടുക്കുന്നില്ലേ?","p":1},{"v":25,"t":"അവൻ പറഞ്ഞു: ഉവ്വ്. പിന്നീടു വീട്ടിലെത്തിയപ്പോൾ യേശു ചോദിച്ചു: ശിമയോനേ, നിനക്കെന്തു തോന്നുന്നു, ഭൂമിയിലെ രാജാക്കന്മാർ ആരിൽ നിന്നാണ് ചുങ്കമോ നികുതിയോ പിരിക്കുന്നത്? തങ്ങളുടെ പുത്രന്മാരിൽനിന്നോ അന്യരിൽനിന്നോ?"},{"v":26,"t":"പത്രോസ് മറുപടി പറഞ്ഞു: അന്യരിൽനിന്ന്. യേശു തുടർന്നു: അപ്പോൾ പുത്രന്മാർ ഒഴിവു ലഭിച്ചവരാണല്ലോ."},{"v":27,"t":"എങ്കിലും, അവർക്ക് ഇടർച്ച നല്കാതിരിക്കാൻ നീ കടലിൽപോയി ചൂണ്ടയിടുക; ആദ്യം ലഭിക്കുന്ന മത്സ്യത്തിന്റെ വായ് തുറക്കുമ്പോൾ ഒരു നാണയം കണ്ടെത്തും. അതെടുത്ത് എനിക്കും നിനക്കും വേണ്ടി അവർക്കു കൊടുക്കുക."}],"18":[{"h":"സ്വർഗരാജ്യത്തിലെ വലിയവൻ"},{"v":1,"t":"ആ സമയത്ത്, ശിഷ്യന്മാർ യേശുവിനെ സമീപിച്ചു ചോദിച്ചു: സ്വർഗരാജ്യത്തിൽ വലിയവൻ ആരാണ്?","p":1},{"v":2,"t":"യേശു ഒരു ശിശുവിനെ വിളിച്ച് അവരുടെ മധ്യേ നിറുത്തിക്കൊണ്ട് അരുൾചെയ്തു:"},{"v":3,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, നിങ്ങൾ മനസ്സുതിരിഞ്ഞ് ശിശുക്കളെപ്പോലെ ആകുന്നില്ലെങ്കിൽ, സ്വർഗരാജ്യത്തിൽ പ്രവേശിക്കുകയില്ല."},{"v":4,"t":"ഈ ശിശുവിനെപ്പോലെ സ്വയം ചെറുതാകുന്നവനാണ് സ്വർഗരാജ്യത്തിലെ ഏറ്റവും വലിയവൻ."},{"v":5,"t":"ഇതുപോലുള്ള ഒരു ശിശുവിനെ എന്റെ നാമത്തിൽ സ്വീകരിക്കുന്നവൻ എന്നെ സ്വീകരിക്കുന്നു."},{"h":"ഇടർച്ചകൾ"},{"v":6,"t":"എന്നിൽ വിശ്വസിക്കുന്ന ഈ ചെറിയവരിൽ ഒരുവന് ഇടർച്ചനല്കുന്നവൻ ആരായാലും അവനു കൂടുതൽ നല്ലത്, കഴുത്തിൽ ഒരു വലിയ തിരികല്ലുകെട്ടി കടലിന്റെ ആഴത്തിൽ താഴ്ത്തപ്പെടുകയായിരിക്കും.","p":1},{"v":7,"t":"ഇടർച്ചകൾ നിമിത്തം ലോകത്തിനു ദുരിതം! നിശ്ചയമായും ഇടർച്ചകൾ വരേണ്ടതാണ്; എന്നാൽ, ആരുമൂലം ഇടർച്ചകൾ വരുന്നുവോ, അവനു ദുരിതം!"},{"v":8,"t":"നിന്റെ കൈയോ കാലോ നിനക്ക് ഇടർച്ചയ്ക്കു കാരണമാകുന്നെങ്കിൽ അതു മുറിച്ച് നിന്നിൽ നിന്ന് എറിഞ്ഞു കളയുക. ഇരുകൈകളും ഇരുകാലുകളും ഉള്ളവനായി നിത്യാഗ്നിയിൽ എറിയപ്പെടുന്നതിനെക്കാൾ നിനക്കു നല്ലത്, അംഗഹീനനോ മുടന്തനോ ആയി ജീവനിലേക്കു പ്രവേശിക്കുന്നതാണ്."},{"v":9,"t":"നിന്റെ കണ്ണ് നിനക്ക് ഇടർച്ചയ്ക്കു കാരണമാകുന്നെങ്കിൽ അതു ചുഴന്നെടുത്ത് നിന്നിൽനിന്ന് എറിഞ്ഞു കളയുക. ഇരുകണ്ണുകളുമുള്ളവനായി നരകാഗ്നിയിൽ എറിയപ്പെടുന്നതിനെക്കാൾ നിനക്കു നല്ലത്, ഒരു കണ്ണുള്ളവനായി ജീവനിലേക്കു പ്രവേശിക്കുന്നതാണ്."},{"h":"വഴിതെറ്റിയ ആടിന്റെ ഉപമ"},{"v":10,"t":"ഈ ചെറിയവരിൽ ഒരുവനെയും നിന്ദിക്കാതിരിക്കാൻ സൂക്ഷിച്ചുകൊള്ളുക.","p":1},{"v":11,"t":"കാരണം, സ്വർഗത്തിൽ അവരുടെ മാലാഖമാർ സ്വർഗസ്ഥനായ എന്റെ പിതാവിന്റെ മുഖം എപ്പോഴും ദർശിച്ചുകൊണ്ടിരിക്കുകയാണെന്ന് ഞാൻ നിങ്ങളോടു പറയുന്നു."},{"v":12,"t":"നിങ്ങൾക്ക് എന്തു തോന്നുന്നു? ഒരാൾക്ക് നൂറ് ആടുകൾ ഉണ്ടായിരിക്കേ, അതിലൊന്ന് വഴിതെറ്റിപ്പോയാൽ തൊണ്ണൂറ്റൊൻപതിനെയും മലയിൽവിട്ടിട്ട്, വഴിതെറ്റിയതിനെ അവൻ അന്വേഷിച്ചുപോകുകയില്ലേ?"},{"v":13,"t":"അതിനെ കണ്ടെത്തിയാൽ, വഴിതെറ്റിപ്പോകാത്ത തൊണ്ണൂറ്റൊൻപതിനെക്കുറിച്ച് എന്നതിനെക്കാൾ അതിനെക്കുറിച്ച് അവൻ സന്തോഷിക്കുമെന്ന് സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു."},{"v":14,"t":"ഇതുപോലെ, ഈ ചെറിയവരിൽ ഒരുവൻപോലും നശിച്ചുപോകുക എന്നത് സ്വർഗസ്ഥനായ നിങ്ങളുടെ പിതാവിന്റെ ഹിതമല്ല."},{"h":"പരസ്പരം തിരുത്തുക"},{"v":15,"t":"നിന്റെ സഹോദരൻ നിനക്കെതിരേ തെറ്റുചെയ്താൽ, നീയും അവനും മാത്രമായിരിക്കുമ്പോൾ ചെന്ന് ആ തെറ്റ് അവനെ ബോധ്യപ്പെടുത്തിക്കൊടുക്കുക. അവൻ നിന്റെ വാക്കു കേൾക്കുന്നെങ്കിൽ, നീ നിന്റെ സഹോദരനെ നേടിക്കഴിഞ്ഞു.","p":1},{"v":16,"t":"അവൻ കേൾക്കുന്നില്ലെങ്കിലോ, ഓരോ വാക്കും രണ്ടോ മൂന്നോ സാക്ഷികളാൽ സ്ഥിരീകരിക്കപ്പെടുന്നതിനുവേണ്ടി, നിന്നോടൊപ്പം ഒന്നോ രണ്ടോ പേരെ കൊണ്ടുപോകുക."},{"v":17,"t":"അവൻ അവരെയും കേൾക്കാൻ വിസമ്മതിക്കുന്നെങ്കിൽ സഭയോടു പറയുക. സഭയെയും കേൾക്കാൻ വിസമ്മതിക്കുന്നെങ്കിൽ, അവൻ നിനക്ക് വിജാതീയനെപ്പോലെയും ചുങ്കക്കാരനെപ്പോലെയും ആയിരിക്കട്ടെ."},{"v":18,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു: നിങ്ങൾ ഭൂമിയിൽ കെട്ടുന്നതെല്ലാം സ്വർഗത്തിലും കെട്ടപ്പെട്ടിരിക്കും; നിങ്ങൾ ഭൂമിയിൽ അഴിക്കുന്നതെല്ലാം സ്വർഗത്തിലും അഴിക്കപ്പെട്ടിരിക്കും."},{"v":19,"t":"വീണ്ടും ഞാൻ നിങ്ങളോടു പറയുന്നു: ഭൂമിയിൽ നിങ്ങളിൽ രണ്ടുപേർ യാചിക്കുന്ന ഏതുകാര്യത്തിലും ഏകമനസ്കരാണെങ്കിൽ, സ്വർഗസ്ഥനായ എന്റെ പിതാവ് നിറവേറ്റിത്തരും."},{"v":20,"t":"എന്തെന്നാൽ, രണ്ടോ മൂന്നോ പേർ എന്റെ നാമത്തിൽ ഒരുമിച്ചുകൂടുന്നിടത്ത് അവരുടെ മധ്യേ ഞാൻ ഉണ്ടായിരിക്കും."},{"h":"നിർദയനായ ഭൃത്യന്റെ ഉപമ"},{"v":21,"t":"അപ്പോൾ പത്രോസ് അടുത്തുവന്ന് അവനോടു ചോദിച്ചു: കർത്താവേ, എന്റെ സഹോദരൻ എന്നോടു തെറ്റുചെയ്താൽ എത്രപ്രാവശ്യം ഞാൻ അവനോടു ക്ഷമിക്കണം; ഏഴു പ്രാവശ്യമോ?","p":1},{"v":22,"t":"യേശു അരുൾചെയ്തു: ഏഴല്ല, ഏഴ് എഴുപതുപ്രാവശ്യം എന്നു ഞാൻ നിന്നോടു പറയുന്നു."},{"v":23,"t":"സ്വർഗരാജ്യം, തന്റെ സേവകന്മാരുടെ കണക്കുതീർക്കാൻ ആഗ്രഹിച്ച ഒരു രാജാവിനു സദൃശം."},{"v":24,"t":"കണക്കു തീർക്കാനാരംഭിച്ചപ്പോൾ പതിനായിരം താലന്ത് കടപ്പെട്ടിരുന്ന ഒരുവനെ അവർ അവന്റെ മുമ്പിൽ കൊണ്ടുവന്നു."},{"v":25,"t":"അവന് അതു വീട്ടാൻ നിർവാഹമില്ലാതിരുന്നതുകൊണ്ട് അവനെയും ഭാര്യയെയും മക്കളെയും അവനുള്ള സമസ്തവും വിറ്റ് കടംവീട്ടാൻ യജമാനൻ കല്പിച്ചു."},{"v":26,"t":"അതിനാൽ, സേവകൻ വീണു പ്രണമിച്ചുകൊണ്ടു പറഞ്ഞു: പ്രഭോ, എനിക്ക് സാവകാശം തരണമേ. ഞാൻ നിനക്ക് എല്ലാം തന്നു വീട്ടിക്കൊള്ളാം."},{"v":27,"t":"ആ സേവകന്റെ യജമാനൻ കരുണതോന്നി അവനെ വിട്ടയയ്ക്കുകയും കടം ഇളച്ചുകൊടുക്കുകയും ചെയ്തു."},{"v":28,"t":"അവൻ പുറത്തിറങ്ങിയപ്പോൾ, തനിക്ക് നൂറു ദനാറ കടപ്പെട്ടിരുന്ന സഹസേവകരിലൊരുവനെ കണ്ടുമുട്ടി. അവന്റെ കഴുത്തു പിടിച്ചു ഞെക്കിക്കൊണ്ട് അവൻ പറഞ്ഞു: നീ കടപ്പെട്ടത് തന്നുതീർക്കുക."},{"v":29,"t":"അപ്പോൾ ആ സഹസേവകൻ അവനോട് കേണപേക്ഷിച്ചു: എനിക്കു സാവകാശം തരണമേ. നിനക്ക് തന്നുതീർത്തുകൊള്ളാം."},{"v":30,"t":"എന്നാൽ, അവൻ സമ്മതിച്ചില്ല; മറിച്ച്, അവൻ പോയി, കടം വീട്ടുന്നതുവരെ അവനെ കാരാഗൃഹത്തിലേക്കു തള്ളി."},{"v":31,"t":"അതിനാൽ അവന്റെ സഹസേവകർ, സംഭവിച്ചതുകണ്ട് ഏറെ സങ്കടപ്പെട്ട്, യജമാനന്റെ അടുക്കൽ പോയി നടന്നതെല്ലാം വിവരിച്ചു."},{"v":32,"t":"യജമാനൻ അവനെ വിളിച്ചു പറഞ്ഞു: ദുഷ്ടനായ സേവകാ, നീ എന്നോടു കേണപേക്ഷിച്ചതുകൊണ്ട് ആ കടമെല്ലാം നിനക്ക് ഞാൻ ഇളച്ചുതന്നു."},{"v":33,"t":"ഞാൻ നിന്നോടു കരുണ കാണിച്ചപോലെ നീയും നിന്റെ സഹസേവകനോടു കരുണ കാണിക്കേണ്ടതായിരുന്നില്ലേ?"},{"v":34,"t":"അവന്റെ യജമാനൻ കോപിച്ച് കടം മുഴുവൻ വീട്ടുന്നതുവരെ അവനെ ദണ്ഡകർക്ക് ഏല്പിച്ചുകൊടുത്തു."},{"v":35,"t":"ആകയാൽ നിങ്ങൾ ഓരോരുത്തരും സഹോദരനോടു ഹൃദയപൂർവം ക്ഷമിക്കുന്നില്ലെങ്കിൽ, സ്വർഗസ്ഥനായ എന്റെ പിതാവും നിങ്ങളോട് ഇതുപോലെതന്നെ ചെയ്യും."}],"19":[{"h":"വിവാഹമോചനം സംബന്ധിച്ച്"},{"v":1,"t":"അങ്ങനെ, യേശു ഈ വാക്കുകൾ അവസാനിപ്പിച്ചപ്പോൾ ഗലീലിവിട്ട് ജോർദാന് അക്കരെ യൂദയാ പ്രദേശങ്ങളിലെത്തി.","p":1},{"v":2,"t":"വലിയ ജനക്കൂട്ടം അവനെ അനുഗമിക്കുകയും അവിടെവച്ച് അവൻ അവരെ സുഖപ്പെടുത്തുകയും ചെയ്തു."},{"v":3,"t":"ഫരിസേയർ അടുത്തുചെന്ന് അവനെ പരീക്ഷിച്ചുകൊണ്ടു ചോദിച്ചു: ഏതെങ്കിലും കാരണത്താൽ ഒരുവൻ തന്റെ ഭാര്യയെ ഉപേക്ഷിക്കുന്നത് നിയമാനുസൃതമാണോ?","p":1},{"v":4,"t":"അവൻ മറുപടി പറഞ്ഞു: നിങ്ങൾ വായിച്ചിട്ടില്ലേ? സ്രഷ്ടാവ് ആദിമുതൽതന്നെ അവരെ പുരുഷനും സ്ത്രീയുമായി സൃഷ്ടിച്ചു."},{"v":5,"t":"അവൻ തുടർന്നു: ഇക്കാരണത്താൽ പുരുഷൻ പിതാവിനെയും മാതാവിനെയും വിട്ട് ഭാര്യയോടു ചേർന്നിരിക്കും. അവരിരുവരും ഏകശരീരമായിത്തീരും."},{"v":6,"t":"തൻമൂലം, മേലിൽ അവർ രണ്ടല്ല, ഒരു ശരീരമായിരിക്കും. ആകയാൽ, ദൈവം യോജിപ്പിച്ചത് മനുഷ്യൻ വേർപെടുത്താതിരിക്കട്ടെ."},{"v":7,"t":"അവർ അവനോടു ചോദിച്ചു: അങ്ങനെയെങ്കിൽ ഉപേക്ഷാപത്രം നല്കി ഭാര്യയെ ഉപേക്ഷിക്കാമെന്നു മോശ വിധിച്ചതെന്തുകൊണ്ട്?"},{"v":8,"t":"അവൻ പറഞ്ഞു: നിങ്ങളുടെ ഹൃദയകാഠിന്യം നിമിത്തമാണ് ഭാര്യമാരെ ഉപേക്ഷിക്കാൻ മോശ നിങ്ങൾക്ക് അനുമതി നല്കിയത്. പക്ഷേ, ആദിമുതൽതന്നെ അങ്ങനെയായിരുന്നില്ല."},{"v":9,"t":"എന്നാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു, പരസംഗം മൂലമല്ലാതെ മറ്റേതെങ്കിലും കാരണത്താൽ ഭാര്യയെ ഉപേക്ഷിച്ച് മറ്റൊരുവളെ വിവാഹം ചെയ്യുന്നവൻ വ്യഭിചാരംചെയ്യുന്നു."},{"v":10,"t":"ശിഷ്യന്മാർ അവനോടു പറഞ്ഞു: ഭാര്യാഭർതൃബന്ധം ഇത്തരത്തിലുള്ളതെങ്കിൽ, വിവാഹം ചെയ്യാതിരിക്കുന്നതാണല്ലോ ഭേദം."},{"v":11,"t":"അവൻ അവരോടു പറഞ്ഞു: ആർക്കു നല്കപ്പെട്ടുവോ, അവരല്ലാതെ മറ്റാരും ഈ വചനം ഗ്രഹിക്കുന്നില്ല."},{"v":12,"t":"എന്തെന്നാൽ, മാതാവിന്റെ ഉദരത്തിൽനിന്നുതന്നെ ഷണ്ഡരായി ജനിക്കുന്നവരുണ്ട്; മനുഷ്യരാൽ ഷണ്ഡരാക്കപ്പെടുന്നവരുണ്ട്; സ്വർഗരാജ്യത്തെപ്രതി തങ്ങളെത്തന്നെ ഷണ്ഡരാക്കുന്നവരുമുണ്ട്. ഗ്രഹിക്കാൻ കഴിവുള്ളവൻ ഗ്രഹിക്കട്ടെ."},{"h":"ശിശുക്കളെ അനുഗ്രഹിക്കുന്നു"},{"v":13,"t":"അപ്പോൾ അവരുടെമേൽ കൈകൾവച്ചു പ്രാർഥിക്കുന്നതിനായി ചിലർ ശിശുക്കളെ അവന്റെ അടുത്തു കൊണ്ടുവന്നു. ശിഷ്യന്മാർ അവരെ ശകാരിച്ചു.","p":1},{"v":14,"t":"എന്നാൽ യേശു പറഞ്ഞു: ശിശുക്കളെ എന്റെ അടുക്കൽ വരാൻ അനുവദിക്കുവിൻ; അവരെ തടയേണ്ടാ. എന്തെന്നാൽ, സ്വർഗരാജ്യം അവരെപ്പോലെയുള്ളവരുടേതാണ്."},{"v":15,"t":"അവൻ അവരുടെമേൽ കൈകൾവച്ചശേഷം അവിടെനിന്ന് പോയി."},{"h":"ധനികനായ യുവാവ്"},{"v":16,"t":"അപ്പോൾ ഒരുവൻ അവനെ സമീപിച്ചു ചോദിച്ചു: ഗുരോ, നിത്യജീവൻ പ്രാപിക്കാൻ ഞാൻ എന്തു നന്മ ചെയ്യണം?","p":1},{"v":17,"t":"അവൻ പറഞ്ഞു: നന്മയെപ്പറ്റി നീ എന്നോടു ചോദിക്കുന്നതെന്തിന്? നല്ലവൻ ഒരുവൻ മാത്രം. ജീവനിൽ പ്രവേശിക്കാൻ അഭിലഷിക്കുന്നെങ്കിൽ പ്രമാണങ്ങൾ പാലിക്കുക."},{"v":18,"t":"അവൻ ചോദിച്ചു: ഏതെല്ലാം? യേശു പ്രതിവചിച്ചു: കൊല്ലരുത്, വ്യഭിചാരം ചെയ്യരുത്, മോഷ്ടിക്കരുത്, കള്ളസാക്ഷ്യം നല്കരുത്."},{"v":19,"t":"പിതാവിനെയും മാതാവിനെയും ബഹുമാനിക്കുക, നിന്നെപ്പോലെ നിന്റെ അയല്ക്കാരനെയും സ്നേഹിക്കുക."},{"v":20,"t":"ആ യുവാവ് അവനോടു പറഞ്ഞു: ഇവയെല്ലാം ഞാൻ പാലിച്ചിട്ടുണ്ട്; ഇനിയും എന്താണ് എനിക്കു കുറവ്?"},{"v":21,"t":"യേശു അവനോടു പറഞ്ഞു: നീ പൂർണനാകാൻ ആഗ്രഹിക്കുന്നെങ്കിൽ, പോയി നിനക്കുള്ളതെല്ലാം വിറ്റ് ദരിദ്രർക്കു കൊടുക്കുക. അപ്പോൾ സ്വർഗത്തിൽ നിനക്കു നിക്ഷേപമുണ്ടാകും. പിന്നെ വന്ന് എന്നെ അനുഗമിക്കുക."},{"v":22,"t":"എന്നാൽ ഈ വചനം കേട്ട് ആ യുവാവ് ദുഃഖിതനായി തിരിച്ചുപോയി; എന്തെന്നാൽ അവന് വളരെയേറെ സമ്പത്തുണ്ടായിരുന്നു."},{"v":23,"t":"യേശു ശിഷ്യന്മാരോട് അരുൾചെയ്തു: സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ധനവാൻ സ്വർഗരാജ്യത്തിൽ പ്രവേശിക്കുന്നത് ദുഷ്കരമാണ്.","p":1},{"v":24,"t":"വീണ്ടും ഞാൻ നിങ്ങളോടുപറയുന്നു, ധനവാൻ സ്വർഗരാജ്യത്തിൽ പ്രവേശിക്കുന്നതിനെക്കാൾ എളുപ്പം, ഒട്ടകം സൂചിക്കുഴയിലൂടെ കടക്കുന്നതാണ്."},{"v":25,"t":"ശിഷ്യന്മാർ ഇതുകേട്ട് വിസ്മയഭരിതരായി അവനോടു ചോദിച്ചു: അങ്ങനെയെങ്കിൽ രക്ഷപ്പെടാൻ ആർക്കു സാധിക്കും?"},{"v":26,"t":"യേശു അവരെ നോക്കിക്കൊണ്ടു പറഞ്ഞു: മനുഷ്യർക്ക് ഇത് അസാധ്യമാണ്; എന്നാൽ ദൈവത്തിന് എല്ലാം സാധ്യമാണ്."},{"v":27,"t":"അപ്പോൾ പത്രോസ് പറഞ്ഞു: ഇതാ, ഞങ്ങൾ എല്ലാമുപേക്ഷിച്ച് നിന്നെ അനുഗമിച്ചിരിക്കുന്നു. ഞങ്ങൾക്കെന്താണു ലഭിക്കുക?"},{"v":28,"t":"യേശു അവരോടു പറഞ്ഞു: സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, പുതിയജീവിതത്തിൽ മനുഷ്യപുത്രൻ തന്റെ മഹത്ത്വത്തിന്റെ സിംഹാസനത്തിൽ ഉപവിഷ്ടനാകുമ്പോൾ, എന്നെ അനുഗമിച്ച നിങ്ങൾ ഇസ്രായേലിന്റെ പന്ത്രണ്ടുഗോത്രങ്ങളെ വിധിച്ചുകൊണ്ട് പന്ത്രണ്ടുസിംഹാസനങ്ങളിൽ ഇരിക്കും."},{"v":29,"t":"എന്റെ നാമത്തെപ്രതി ഭവനങ്ങളെയോ സഹോദരന്മാരെയോ സഹോദരിമാരെയോ പിതാവിനെയോ മാതാവിനെയോ മക്കളെയോ വയലുകളെയോ പരിത്യജിക്കുന്ന ആർക്കും നൂറിരട്ടി ലഭിക്കും; അവൻ നിത്യജീവൻ അവകാശമാക്കുകയും ചെയ്യും."},{"v":30,"t":"എന്നാൽ, മുമ്പന്മാരായ അനേകർ പിമ്പന്മാരും പിമ്പന്മാർ മുമ്പന്മാരുമാകും."}],"20":[{"h":"മുന്തിരിത്തോട്ടത്തിലെ ജോലിക്കാർ"},{"v":1,"t":"അതിനാൽ സ്വർഗരാജ്യം, തന്റെ മുന്തിരിത്തോട്ടത്തിലേക്ക് കൂലിക്ക് ജോലിക്കാരെ വിളിക്കാൻ അതിരാവിലേ പുറപ്പെട്ട വീട്ടുടമസ്ഥനു സദൃശം.","p":1},{"v":2,"t":"ദിവസം ഒരു ദനാറവീതം വേതനം നല്കാമെന്ന കരാറിൽ അവൻ അവരെ തന്റെ മുന്തിരിത്തോട്ടത്തിലേക്കയച്ചു."},{"v":3,"t":"ഏകദേശം മൂന്നാം മണിക്കൂറിൽ അവൻ പുറത്തേക്കിറങ്ങിയപ്പോൾ ചിലർ ചന്തസ്ഥലത്ത് അലസരായി നില്ക്കുന്നതു കണ്ട്,"},{"v":4,"t":"അവരോടു പറഞ്ഞു: നിങ്ങളും മുന്തിരിത്തോട്ടത്തിലേക്കു ചെല്ലുവിൻ; ന്യായമായ വേതനം നിങ്ങൾക്കു ഞാൻ തരാം."},{"v":5,"t":"അവരും പോയി. വീണ്ടും ഏകദേശം ആറാംമണിക്കൂറിലും ഒൻപതാംമണിക്കൂറിലും പുറത്തേക്കിറങ്ങിയപ്പോഴും അവൻ ഇതുപോലെതന്നെ ചെയ്തു."},{"v":6,"t":"ഏകദേശം പതിനൊന്നാംമണിക്കൂറിൽ അവൻ പുറത്തേക്കിറങ്ങിയപ്പോഴും അവിടെ ചിലർ നില്ക്കുന്നതു കണ്ട് അവരോടു ചോദിച്ചു: നിങ്ങൾ ദിവസംമുഴുവൻ അലസരായി നില്ക്കുന്നതെന്ത്?"},{"v":7,"t":"ഞങ്ങളെ ആരും വേലയ്ക്കു വിളിക്കാത്തതുകൊണ്ട് എന്ന് അവർ മറുപടി നല്കി. അവൻ പറഞ്ഞു: നിങ്ങളും മുന്തിരിത്തോട്ടത്തിലേക്കു ചെല്ലുവിൻ."},{"v":8,"t":"വൈകുന്നേരമായപ്പോൾ മുന്തിരിത്തോട്ടത്തിന്റെ ഉടമസ്ഥൻ കാര്യസ്ഥനോടു പറഞ്ഞു: ജോലിക്കാരെ വിളിച്ച് അവസാനത്തെ ആളുകൾക്കുതുടങ്ങി ആദ്യത്തെ ആളുകൾക്കുവരെ കൂലികൊടുക്കുക."},{"v":9,"t":"പതിനൊന്നാംമണിക്കൂറിൽ വന്നവർക്ക് ഓരോ ദനാറവീതം ലഭിച്ചു."},{"v":10,"t":"തങ്ങൾക്ക് കൂടുതൽ ലഭിക്കുമെന്ന് ആദ്യം വന്നവർ വിചാരിച്ചു. എന്നാൽ, അവർക്കും ഓരോ ദനാറതന്നെ കിട്ടി."},{"v":11,"t":"അതു വാങ്ങുമ്പോൾ അവർ വീട്ടുടമസ്ഥനെതിരേ പിറുപിറുത്തു:"},{"v":12,"t":"ഈ അവസാനത്തെ ആളുകൾ ഒരു മണിക്കൂറേ ജോലി ചെയ്തുള്ളു; എന്നിട്ടും ദിവസത്തിന്റെ ഭാരവും ചൂടും സഹിച്ച ഞങ്ങളോട് അവരെ നീ തുല്യരാക്കിയല്ലോ."},{"v":13,"t":"അവൻ അവരിലൊരുവനോട് മറുപടി പറഞ്ഞു: സ്നേഹിതാ, ഞാൻ നിന്നോട് ഒരനീതിയും ചെയ്യുന്നില്ല. ഒരു ദനാറയ്ക്കല്ലേ നീ എന്നോടു സമ്മതിച്ചിരുന്നത്?"},{"v":14,"t":"നിനക്കുള്ളതു വാങ്ങിക്കൊണ്ടു പൊയ്ക്കൊള്ളുക. നിനക്കെന്നപോലെ അവസാനത്തെയാൾക്കും കൊടുക്കാൻ ഞാൻ ഇച്ഛിക്കുന്നു."},{"v":15,"t":"എനിക്കുള്ളവകൊണ്ട് ഞാൻ ഇച്ഛിക്കുന്നതു ചെയ്യാൻ എനിക്കു പാടില്ലെന്നോ? ഞാൻ നല്ലവനായതുകൊണ്ട് നീ എന്തിന് അസൂയപ്പെടുന്നു?"},{"v":16,"t":"ഇപ്രകാരം, പിമ്പന്മാർ മുമ്പന്മാരും മുമ്പന്മാർ പിമ്പന്മാരുമാകും."},{"h":"പീഡാനുഭവവും ഉത്ഥാനവും - മൂന്നാംപ്രവചനം"},{"v":17,"t":"യേശു ജറുസലേമിലേക്കു കയറുമ്പോൾ പന്ത്രണ്ടു ശിഷ്യന്മാരെമാത്രം കൂടെ കൊണ്ടുപോയി. വഴിയിൽവച്ച് അവരോട് അരുൾചെയ്തു:","p":1},{"v":18,"t":"ഇതാ, നാം ജറുസലേമിലേക്കു കയറുന്നു. മനുഷ്യപുത്രൻ പുരോഹിതപ്രമുഖന്മാർക്കും നിയമജ്ഞന്മാർക്കും ഏല്പിക്കപ്പെടും. അവർ അവനെ മരണത്തിനു വിധിക്കും."},{"v":19,"t":"അവർ അവനെ പരിഹസിക്കാനും പ്രഹരിക്കാനും ക്രൂശിക്കാനുമായി ജനതകൾക്ക് ഏല്പിച്ചുകൊടുക്കും. എന്നാൽ, മൂന്നാംദിവസം അവൻ ഉയിർപ്പിക്കപ്പെടും."},{"h":"സെബദിപുത്രന്മാരുടെ അഭ്യർഥന"},{"v":20,"t":"അപ്പോൾ സെബദിപുത്രന്മാരുടെ അമ്മ തന്റെ പുത്രന്മാരോടുകൂടെ വന്ന് മുട്ടുകുത്തി അവനോട് എന്തോ യാചിച്ചു.","p":1},{"v":21,"t":"അപ്പോൾ അവൻ അവളോടു ചോദിച്ചു: നീ എന്താണ് ആഗ്രഹിക്കുന്നത്? അവൾ പറഞ്ഞു: നിന്റെ രാജ്യത്തിൽ എന്റെ ഈ രണ്ടു പുത്രന്മാരിൽ ഒരുവൻ നിന്റെ വലത്തുവശത്തും അപരൻ ഇടത്തുവശത്തും ഇരിക്കുന്നതിനു കല്പിക്കണമേ!"},{"v":22,"t":"യേശു മറുപടി നല്കി: നിങ്ങൾ ചോദിക്കുന്നതെന്താണെന്ന് നിങ്ങൾ അറിയുന്നില്ല. ഞാൻ കുടിക്കാൻ പോകുന്ന പാനപാത്രം കുടിക്കാൻ നിങ്ങൾക്കു കഴിയുമോ? അവർ പറഞ്ഞു: ഞങ്ങൾക്കു കഴിയും."},{"v":23,"t":"അവൻ അവരോടു പറഞ്ഞു: എന്റെ പാനപാത്രം തീർച്ചയായും നിങ്ങൾ കുടിക്കും. എന്നാൽ എന്റെ വലത്തുവശത്തും ഇടത്തുവശത്തും ഇരിക്കാനുള്ള വരം നിങ്ങൾക്കു നല്കേണ്ടതു ഞാനല്ല; അത് ആർക്കുവേണ്ടി എന്റെ പിതാവാൽ ഒരുക്കപ്പെട്ടിരിക്കുന്നുവോ അവർക്കുള്ളതാണ്."},{"v":24,"t":"ഇതുകേട്ടപ്പോൾ ബാക്കി പത്തുപേർക്കും ആ രണ്ടു സഹോദരന്മാരോട് അമർഷം തോന്നി."},{"v":25,"t":"എന്നാൽ, യേശു അവരെ അടുത്തുവിളിച്ച് ഇപ്രകാരം പറഞ്ഞു: ജനതകളുടെ ഭരണകർത്താക്കൾ അവരുടെമേൽ യജമാനത്വം പുലർത്തുന്നെന്നും അവരുടെ പ്രമാണികൾ അവരുടെമേൽ അധികാരം പ്രയോഗിക്കുന്നെന്നും നിങ്ങൾക്കറിയാമല്ലോ."},{"v":26,"t":"എന്നാൽ, നിങ്ങളുടെയിടയിൽ അങ്ങനെയാകരുത്. നിങ്ങളിൽ വലിയവനാകാൻ ആഗ്രഹിക്കുന്നവൻ നിങ്ങളുടെ ശുശ്രൂഷകനും"},{"v":27,"t":"നിങ്ങളിൽ ഒന്നാമനാകാൻ ആഗ്രഹിക്കുന്നവൻ നിങ്ങളുടെ ദാസനുമായിരിക്കണം."},{"v":28,"t":"മനുഷ്യപുത്രൻ, ശുശ്രൂഷിക്കപ്പെടാനല്ല, പ്രത്യുത, ശുശ്രൂഷിക്കാനും അനേകർക്ക് മോചനദ്രവ്യമായി സ്വജീവൻകൊടുക്കാനും വന്നിരിക്കുന്നപോലെതന്നെ."},{"h":"അന്ധർക്കു കാഴ്ച"},{"v":29,"t":"അവർ ജറീക്കോയിൽനിന്നു യാത്ര പുറപ്പെട്ടപ്പോൾ വലിയ ഒരു ജനക്കൂട്ടം അവനെ അനുഗമിച്ചു.","p":1},{"v":30,"t":"യേശു ആ വഴി കടന്നുപോകുന്നെന്നു കേട്ടപ്പോൾ, വഴിയരികിലിരുന്ന രണ്ട് അന്ധന്മാർ ഉച്ചത്തിൽ നിലവിളിച്ചു: കർത്താവേ, ദാവീദിന്റെ പുത്രാ, ഞങ്ങളിൽ കനിയണമേ!"},{"v":31,"t":"എന്നാൽ, മിണ്ടാതിരിക്കാൻ ജനക്കൂട്ടം അവരെ ശാസിച്ചു. അവരാകട്ടെ, കർത്താവേ, ദാവീദിന്റെ പുത്രാ, ഞങ്ങളിൽ കനിയണമേ എന്ന് കൂടുതൽ ഉച്ചത്തിൽ നിലവിളിച്ചുപറഞ്ഞു."},{"v":32,"t":"യേശു നിന്ന്, അവരെ വിളിച്ചുചോദിച്ചു: ഞാൻ നിങ്ങൾക്ക് എന്തുചെയ്യണമെന്നാണ് നിങ്ങൾ ആഗ്രഹിക്കുന്നത്?"},{"v":33,"t":"അവർ പറഞ്ഞു: കർത്താവേ, ഞങ്ങളുടെ കണ്ണുകൾ തുറന്നു കിട്ടണം."},{"v":34,"t":"യേശു ഉള്ളലിഞ്ഞ് അവരുടെ കണ്ണുകളിൽ സ്പർശിച്ചു. തത്ക്ഷണം അവർക്കു കാഴ്ച കിട്ടുകയും അവർ അവനെ അനുഗമിക്കുകയും ചെയ്തു."}],"21":[{"h":"ജറുസലേമിലേക്ക് രാജകീയപ്രവേശം"},{"v":1,"t":"അവർ ജറുസലേമിനെ സമീപിച്ച് ഒലിവുമലയിലെ ബേത്ഫഗെയിൽ എത്തിയപ്പോൾ യേശു രണ്ടു ശിഷ്യന്മാരെ നിയോഗിച്ചയച്ചു.","p":1},{"v":2,"t":"അവൻ അവരോടു പറഞ്ഞു: എതിരേ കാണുന്ന ഗ്രാമത്തിലേക്കു പോകുവിൻ. അവിടെ ഒരു കഴുതയെയും അടുത്ത് അതിന്റെ കുട്ടിയെയും കെട്ടിയിരിക്കുന്നത് ഉടനെ നിങ്ങൾ കാണും. അവയെ അഴിച്ച് എന്റെ അടുക്കൽ കൊണ്ടുവരുക."},{"v":3,"t":"ആരെങ്കിലും നിങ്ങളോട് എന്തെങ്കിലും ചോദിച്ചാൽ, കർത്താവിന് അവയെക്കൊണ്ട് ആവശ്യമുണ്ടെന്നു പറയുക; അവൻ ഉടനെ അവയെ വിട്ടുതരും."},{"v":4,"t":"പ്രവാചകൻവഴി പറയപ്പെട്ട വചനം പൂർത്തിയാകാനാണ് ഇതു സംഭവിച്ചത്."},{"v":5,"t":"സീയോൻ പുത്രിയോടു പറയുക: ഇതാ, നിന്റെ രാജാവ് വിനയാന്വിതനായി കഴുതയുടെയും കഴുതക്കുട്ടിയുടെയും പുറത്ത് നിന്റെ അടുത്തേക്കുവരുന്നു."},{"v":6,"t":"ശിഷ്യന്മാർ പോയി യേശു കല്പിച്ചപോലെ ചെയ്തു."},{"v":7,"t":"അവർ കഴുതയെയും കഴുതക്കുട്ടിയെയും കൊണ്ടുവന്ന് അവയുടെമേൽ വസ്ത്രങ്ങൾ വിരിച്ചു. അവൻ കയറി ഇരുന്നു."},{"v":8,"t":"ജനക്കൂട്ടത്തിൽ വളരെപ്പേർ വഴിയിൽ തങ്ങളുടെ മേലങ്കികൾ വിരിച്ചു; മറ്റുചിലരാകട്ടെ, വൃക്ഷങ്ങളിൽനിന്നു ചില്ലകൾ മുറിച്ച് വഴിയിൽ നിരത്തി."},{"v":9,"t":"യേശുവിനു മുമ്പിലും പിമ്പിലും നടന്നിരുന്ന ജനക്കൂട്ടം ആർത്തുവിളിച്ചു: ദാവീദിന്റെ പുത്രന് ഹോസാന! കർത്താവിന്റെ നാമത്തിൽ വരുന്നവൻ അനുഗൃഹീതൻ! ഉന്നതങ്ങളിൽ ഹോസാന!"},{"v":10,"t":"അവൻ ജറുസലേമിൽ പ്രവേശിച്ചപ്പോൾ നഗരം മുഴുവൻ ഇളകിവശായി, ആരാണിവൻ എന്നു ചോദിച്ചു."},{"v":11,"t":"ജനക്കൂട്ടം പറഞ്ഞുകൊണ്ടിരുന്നു: ഇവൻ ഗലീലിയിലെ നസറത്തിൽ നിന്നുള്ള പ്രവാചകനായ യേശുവാണ്."},{"h":"ദേവാലയശുദ്ധീകരണം"},{"v":12,"t":"യേശു ദേവാലയത്തിൽ പ്രവേശിച്ച് അവിടെ വില്ക്കുകയും വാങ്ങുകയും ചെയ്യുന്നവരെയെല്ലാം പുറത്താക്കി. നാണയമാറ്റക്കാരുടെ മേശകളും പ്രാവു വില്പനക്കാരുടെ ഇരിപ്പിടങ്ങളും അവൻ തട്ടിമറിച്ചിട്ടു.","p":1},{"v":13,"t":"അവൻ അവരോടു പറഞ്ഞു: എന്റെ ഭവനം പ്രാർഥനാലയം എന്നു വിളിക്കപ്പെടും എന്ന് എഴുതപ്പെട്ടിരിക്കുന്നു. നിങ്ങളോ, അതു കവർച്ചക്കാരുടെ ഗുഹയാക്കുന്നു."},{"v":14,"t":"അന്ധന്മാരും മുടന്തന്മാരും ദേവാലയത്തിൽ അവന്റെ അടുത്തെത്തി. അവൻ അവരെ സുഖപ്പെടുത്തി."},{"v":15,"t":"അവൻ ചെയ്ത വിസ്മയകരമായ പ്രവൃത്തികൾ കണ്ടും ദാവീദിന്റെ പുത്രനു ഹോസാന എന്ന് ഉദ്ഘോഷിച്ച് ദേവാലയത്തിൽ ആർപ്പുവിളിക്കുന്ന കുട്ടികളെ കണ്ടും പുരോഹിതപ്രമുഖന്മാരും നിയമജ്ഞരും രോഷാകുലരായി."},{"v":16,"t":"അവർ അവനോടു പറഞ്ഞു: ഇവരെന്താണു പറയുന്നതെന്ന് നീ കേൾക്കുന്നില്ലേ? യേശു പ്രതിവചിച്ചു: ഉവ്വ്; ശിശുക്കളുടെയും മുലകുടിക്കുന്നവരുടെയും അധരങ്ങൾ നിന്റെ സ്തുതിക്കായി നീ സജ്ജമാക്കിയെന്ന് നിങ്ങൾ ഒരിക്കലും വായിച്ചിട്ടില്ലേ?"},{"v":17,"t":"അനന്തരം അവൻ അവരെ വിട്ട് നഗരത്തിനു വെളിയിൽ ബഥാനിയായിലേക്കു പോയി, അവിടെ രാത്രി ചെലവഴിച്ചു."},{"h":"അത്തിവൃക്ഷത്തെ ശപിക്കുന്നു"},{"v":18,"t":"പ്രഭാതത്തിൽ നഗരത്തിലേക്കു പോകുമ്പോൾ അവനു വിശന്നു.","p":1},{"v":19,"t":"വഴിയരികിൽ ഒരു അത്തിവൃക്ഷം കണ്ട് അവൻ അതിന്റെ അടുത്തെത്തി. എന്നാൽ, അതിൽ ഇലകളല്ലാതെ ഒന്നും കണ്ടില്ല. അവൻ അതിനോടു പറഞ്ഞു: ഇനി ഒരിക്കലും നിന്നിൽ ഫലമുണ്ടാകാതിരിക്കട്ടെ. ആ നിമിഷംതന്നെ ആ അത്തിവൃക്ഷം ഉണങ്ങിപ്പോയി."},{"v":20,"t":"ഇതുകണ്ട് ശിഷ്യന്മാർ അദ്ഭുതപ്പെട്ടു; ആ അത്തിവൃക്ഷം ഈ നിമിഷംതന്നെ ഉണങ്ങിപ്പോയതെങ്ങനെ എന്നു ചോദിച്ചു."},{"v":21,"t":"യേശു അവരോടു പറഞ്ഞു: സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, നിങ്ങൾക്ക് വിശ്വാസമുണ്ടായിരിക്കുകയും സംശയിക്കാതിരിക്കുകയും ചെയ്താൽ അത്തിവൃക്ഷത്തോടു ചെയ്തതു മാത്രമല്ല നിങ്ങൾക്കു ചെയ്യാൻ കഴിയുക; ഈ മലയോട് ഇവിടെനിന്ന് ഉയർത്തപ്പെട്ട് കടലിൽ എറിയപ്പെടുക എന്നു പറഞ്ഞാലും സംഭവിക്കും."},{"v":22,"t":"ആകയാൽ, വിശ്വസിച്ചുകൊണ്ട് പ്രാർഥനയിൽ യാചിക്കുന്നവയെല്ലാം നിങ്ങൾക്കു ലഭിക്കും."},{"h":"യേശുവിന്റെ അധികാരം"},{"v":23,"t":"അവൻ ദേവാലയത്തിലെത്തി പഠിപ്പിച്ചുകൊണ്ടിരിക്കുമ്പോൾ പുരോഹിതപ്രമുഖന്മാരും ജനപ്രമാണികളും അവനെ സമീപിച്ചു ചോദിച്ചു: എന്തധികാരത്താലാണ് നീ ഇവയൊക്കെ ചെയ്യുന്നത്? നിനക്ക് ഈ അധികാരം നല്കിയത് ആരാണ്?","p":1},{"v":24,"t":"യേശു അവരോടു മറുപടിയായി പറഞ്ഞു: ഞാനും നിങ്ങളോട് ഒരുകാര്യം ചോദിക്കട്ടെ. നിങ്ങൾ എന്നോട് ഉത്തരം പറഞ്ഞാൽ, എന്തധികാരത്താലാണ് ഞാൻ ഇവയൊക്കെ ചെയ്യുന്നതെന്നു നിങ്ങളോടും പറയാം."},{"v":25,"t":"യോഹന്നാന്റെ ജ്ഞാനസ്നാനം എവിടെ നിന്നായിരുന്നു? സ്വർഗത്തിൽനിന്നോ മനുഷ്യരിൽനിന്നോ? അവരാകട്ടെ, പരസ്പരം ആലോചിച്ചുകൊണ്ടു പറഞ്ഞു: സ്വർഗത്തിൽനിന്ന് എന്നു നാം പറഞ്ഞാൽ, പിന്നെ എന്തുകൊണ്ട് നിങ്ങൾ അവനെ വിശ്വസിച്ചില്ല എന്ന് അവൻ നമ്മോടു ചോദിക്കും."},{"v":26,"t":"മനുഷ്യരിൽനിന്ന് എന്നു പറഞ്ഞാലോ, നാം ജനക്കൂട്ടത്തെ ഭയപ്പെടുന്നു. എന്തെന്നാൽ, എല്ലാവരും യോഹന്നാനെ ഒരു പ്രവാചകനായി പരിഗണിക്കുന്നു."},{"v":27,"t":"അതിനാൽ, അവർ യേശുവിനോട് മറുപടി പറഞ്ഞു: ഞങ്ങൾക്കറിഞ്ഞുകൂടാ. അപ്പോൾ അവൻ പറഞ്ഞു: എന്തധികാരത്താലാണ് ഞാൻ ഇവയെല്ലാം ചെയ്യുന്നത് എന്ന് ഞാനും നിങ്ങളോടു പറയുന്നില്ല."},{"h":"രണ്ടു പുത്രന്മാരുടെ ഉപമ"},{"v":28,"t":"നിങ്ങൾക്ക് എന്തു തോന്നുന്നു? ഒരു മനുഷ്യന് രണ്ടു പുത്രന്മാരുണ്ടായിരുന്നു. അവൻ ഒന്നാമന്റെ അടുത്തു ചെന്നു പറഞ്ഞു: മകനേ, പോയി ഇന്ന് മുന്തിരിത്തോട്ടത്തിൽ ജോലിചെയ്യുക.","p":1},{"v":29,"t":"അവൻ മറുപടി പറഞ്ഞു: എനിക്കു മനസ്സില്ല. എന്നാൽ പിന്നീട് മനസ്സുമാറ്റി അവൻ പോയി."},{"v":30,"t":"അവൻ രണ്ടാമന്റെ അടുത്തു ചെന്ന് ഇതുപോലെതന്നെ പറഞ്ഞു. അവൻ പറഞ്ഞു: ഞാൻ പോകാം, പിതാവേ. പക്ഷേ, അവൻ പോയില്ല."},{"v":31,"t":"ഈ രണ്ടുപേരിൽ ആരാണ് പിതാവിന്റെ ഇഷ്ടം നിറവേറ്റിയത്? അവർ പറഞ്ഞു: ഒന്നാമൻ. യേശു പറഞ്ഞു: സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ചുങ്കക്കാരും വേശ്യകളുമായിരിക്കും നിങ്ങൾക്കു മുമ്പേ സ്വർഗരാജ്യത്തിൽ പ്രവേശിക്കുന്നത്.","p":1},{"v":32,"t":"എന്തെന്നാൽ, യോഹന്നാൻ നീതിമാർഗത്തിലൂടെ നിങ്ങളെ സമീപിച്ചു; നിങ്ങൾ അവനെ വിശ്വസിച്ചില്ല. എന്നാൽ ചുങ്കക്കാരും വേശ്യകളും അവനെ വിശ്വസിച്ചു. നിങ്ങൾ അതു കണ്ടിട്ടും, അവനെ വിശ്വസിക്കത്തക്കവിധം പിന്നീടും മനസ്സുമാറ്റിയില്ല."},{"h":"മുന്തിരിത്തോട്ടത്തിലെ കൃഷിക്കാരുടെ ഉപമ"},{"v":33,"t":"മറ്റൊരു ഉപമ കേട്ടുകൊള്ളുക. വീട്ടുടമസ്ഥനായ ഒരു മനുഷ്യൻ മുന്തിരിത്തോട്ടം നട്ടുപിടിപ്പിച്ചു. അതിനുചുറ്റും വേലികെട്ടി. അതിൽ മുന്തിരിച്ചക്കു സ്ഥാപിക്കുകയും ഗോപുരം നിർമിക്കുകയും ചെയ്തു. അനന്തരം, അതു കൃഷിക്കാരെ ഏല്പിച്ചിട്ട് അവൻ യാത്രപോയി.","p":1},{"v":34,"t":"വിളവെടുപ്പുകാലം വന്നപ്പോൾ അവൻ ഫലങ്ങൾ ശേഖരിക്കാൻ ഭൃത്യന്മാരെ കൃഷിക്കാരുടെ അടുത്തേക്കയച്ചു."},{"v":35,"t":"എന്നാൽ, കൃഷിക്കാർ ഭൃത്യന്മാരിൽ ഒരുവനെപ്പിടിച്ച് അടിക്കുകയും മറ്റൊരുവനെ കൊല്ലുകയും വേറൊരുവനെ കല്ലെറിയുകയും ചെയ്തു."},{"v":36,"t":"വീണ്ടും അവൻ ആദ്യത്തേതിൽ കൂടുതൽ ഭൃത്യന്മാരെ അയച്ചു. അവരോടും കൃഷിക്കാർ അപ്രകാരം തന്നെ പ്രവർത്തിച്ചു."},{"v":37,"t":"ഏറ്റവും ഒടുവിൽ, എന്റെ പുത്രനെ അവർ ബഹുമാനിക്കും എന്നു പറഞ്ഞ് അവൻ സ്വപുത്രനെ അവരുടെ അടുത്തേക്കയച്ചു."},{"v":38,"t":"പുത്രനെക്കണ്ടപ്പോൾ കൃഷിക്കാർ പരസ്പരം പറഞ്ഞു: ഇവനാണ് അവകാശി; വരുവിൻ, നമുക്കിവനെ കൊന്ന് അവകാശം കരസ്ഥമാക്കാം."},{"v":39,"t":"അവർ അവനെ പിടിച്ച് മുന്തിരിത്തോട്ടത്തിനു വെളിയിലേക്കെറിഞ്ഞ് കൊന്നുകളഞ്ഞു."},{"v":40,"t":"ആകയാൽ, മുന്തിരിത്തോട്ടത്തിന്റെ ഉടമസ്ഥൻ വരുമ്പോൾ അവൻ ആ കൃഷിക്കാരോട് എന്തു ചെയ്യും?"},{"v":41,"t":"അവർ പറഞ്ഞു: അവൻ ആ ദുഷ്ടരെ നിഷ്ഠുരമായി നശിപ്പിക്കുകയും യഥാകാലം ഫലങ്ങൾ കൊടുക്കുന്ന മറ്റുകൃഷിക്കാരെ അത് ഏല്പിക്കുകയും ചെയ്യും."},{"v":42,"t":"യേശു അവരോടു പറഞ്ഞു: പണിക്കാർ ഉപേക്ഷിച്ചുകളഞ്ഞ കല്ലുതന്നെ മൂലക്കല്ലായിത്തീർന്നു. ഇതു കർത്താവിന്റെ പ്രവൃത്തിയാണ്. നമ്മുടെ ദൃഷ്ടികൾക്ക് ഇത് അദ്ഭുതകരമായിരിക്കുന്നു എന്ന് വിശുദ്ധലിഖിതങ്ങളിൽ നിങ്ങൾ ഒരിക്കലും വായിച്ചിട്ടില്ലേ?"},{"v":43,"t":"അതുകൊണ്ട് ഞാൻ നിങ്ങളോടു പറയുന്നു, ദൈവരാജ്യം നിങ്ങളിൽ നിന്നെടുക്കപ്പെട്ട് ഫലങ്ങൾ പുറപ്പെടുവിക്കുന്ന ജനതയ്ക്കു നല്കപ്പെടും."},{"v":44,"t":"ഈ കല്ലിൽ വീഴുന്നവൻ തകർക്കപ്പെടും. ഇത് ആരുടെമേൽ വീഴുന്നുവോ, അത് അവനെ ധൂളിയാക്കും."},{"v":45,"t":"പുരോഹിതപ്രമുഖന്മാരും ഫരിസേയരും അവന്റെ ഉപമകൾ കേട്ടപ്പോൾ, അവൻ തങ്ങളെപ്പറ്റിയാണു സംസാരിക്കുന്നതെന്നു മനസ്സിലാക്കി."},{"v":46,"t":"അവർ അവനെ പിടികൂടാൻ നോക്കിയെങ്കിലും ജനക്കൂട്ടത്തെ ഭയപ്പെട്ടു. കാരണം, അവർ അവനെ ഒരു പ്രവാചകനായി പരിഗണിച്ചിരുന്നു."}],"22":[{"h":"വിവാഹവിരുന്നിന്റെ ഉപമ"},{"v":1,"t":"യേശു വീണ്ടും ഉപമകൾവഴി അവരോടു സംസാരിച്ചു:","p":1},{"v":2,"t":"സ്വർഗരാജ്യം, തന്റെ പുത്രനുവേണ്ടി വിവാഹവിരുന്നൊരുക്കിയ രാജാവിനു സദൃശം."},{"v":3,"t":"ക്ഷണിക്കപ്പെട്ടവരെ വിവാഹവിരുന്നിനു വിളിക്കാൻ അവൻ ഭൃത്യന്മാരെ അയച്ചു; എന്നാൽ, വരാൻ അവർ വിസമ്മതിച്ചു."},{"v":4,"t":"വീണ്ടും അവൻ വേറെ ഭൃത്യന്മാരെ അയച്ചുകൊണ്ടു പറഞ്ഞു: ക്ഷണിക്കപ്പെട്ടവരോട് ചെന്നു പറയുവിൻ, ഇതാ എന്റെ വിരുന്ന് ഞാൻ ഒരുക്കിയിരിക്കുന്നു; എന്റെ കാളകളെയും കൊഴുത്ത മൃഗങ്ങളെയും കൊന്നിരിക്കുന്നു. എല്ലാം തയ്യാറായിക്കഴിഞ്ഞു; വിവാഹവിരുന്നിനു വരുക."},{"v":5,"t":"എന്നാൽ, അവർ അതു വകവയ്ക്കാതെ ഒരുവൻ വയലിലേക്കും വേറൊരുവൻ വ്യാപാരത്തിനും പൊയ്ക്കളഞ്ഞു."},{"v":6,"t":"മറ്റുള്ളവർ ആ ഭൃത്യന്മാരെ പിടികൂടി അവരെ അപമാനിക്കുകയും വധിക്കുകയും ചെയ്തു."},{"v":7,"t":"രാജാവ് ക്രുദ്ധനായി, സൈന്യത്തെ അയച്ച് ആ കൊലപാതകികളെ നശിപ്പിച്ചു; അവരുടെ നഗരം അഗ്നിക്കിരയാക്കി."},{"v":8,"t":"അനന്തരം, അവൻ ഭൃത്യന്മാരോടു പറഞ്ഞു: വിവാഹവിരുന്നു തയ്യാറായിരിക്കുന്നു; എന്നാൽ ക്ഷണിക്കപ്പെട്ടവർ അയോഗ്യരായിരുന്നു."},{"v":9,"t":"അതിനാൽ, നിങ്ങൾ വഴിക്കവലകളിൽ ചെന്ന് അവിടെ കണ്ടെത്തുന്നവരെയെല്ലാം വിവാഹവിരുന്നിനു ക്ഷണിക്കുവിൻ."},{"v":10,"t":"ആ ഭൃത്യന്മാർ നിരത്തുകളിൽച്ചെന്ന് ദുഷ്ടരും ശിഷ്ടരും ഉൾപ്പെടെ കണ്ടെത്തിയവരെയെല്ലാം വിളിച്ചുകൂട്ടി. അങ്ങനെ വിരുന്നുശാല അതിഥികളെക്കൊണ്ടു നിറഞ്ഞു."},{"v":11,"t":"അതിഥികളെക്കാണാൻ രാജാവ് എഴുന്നള്ളിയപ്പോൾ വിവാഹവസ്ത്രം ധരിക്കാത്ത ഒരാളെ അവിടെ കണ്ടു."},{"v":12,"t":"രാജാവ് അവനോടു ചോദിച്ചു: സ്നേഹിതാ, വിവാഹവസ്ത്രമില്ലാതെ നീ ഇവിടെ പ്രവേശിച്ചതെങ്ങനെ? അവൻ മൗനം അവലംബിച്ചു."},{"v":13,"t":"അപ്പോൾ രാജാവ് പരിചാരകന്മാരോടു പറഞ്ഞു: അവനെ കൈകാലുകൾകെട്ടി പുറത്തെ അന്ധകാരത്തിലേക്ക് വലിച്ചെറിയുക; അവിടെ കരച്ചിലും പല്ലുകടിയുമായിരിക്കും."},{"v":14,"t":"എന്തെന്നാൽ, വിളിക്കപ്പെട്ടവർ അനേകം; തിരഞ്ഞെടുക്കപ്പെട്ടവരോ ചുരുക്കം."},{"h":"സീസറിനുനികുതി"},{"v":15,"t":"അപ്പോൾ ഫരിസേയർ പോയി, യേശുവിനെ എങ്ങനെ വാക്കിൽക്കുടുക്കാം എന്ന് കൂടിയാലോചന നടത്തി.","p":1},{"v":16,"t":"അവർ തങ്ങളുടെ അനുയായികളെ ഹേറോദ്യരോടൊപ്പം അവന്റെ അടുക്കലേക്കയച്ചു പറഞ്ഞു: ഗുരോ, നീ സത്യവാനാണെന്നും ദൈവത്തിന്റെവഴി സത്യത്തിൽ പഠിപ്പിക്കുന്നവനാണെന്നും ആരാലും സ്വാധീനിക്കപ്പെടാത്തവനാണെന്നും ആരുടെയും മുഖം നോക്കാത്തവനാണെന്നും ഞങ്ങൾ അറിയുന്നു."},{"v":17,"t":"അതുകൊണ്ടു ഞങ്ങളോടു പറയുക: നിനക്ക് എന്തു തോന്നുന്നു, സീസറിനു നികുതി കൊടുക്കുന്നതു നിയമാനുസൃതമോ അല്ലയോ?"},{"v":18,"t":"അവരുടെ ദുരുദ്ദേശ്യം മനസ്സിലാക്കിക്കൊണ്ട് യേശുപറഞ്ഞു: കപടനാട്യക്കാരേ, നിങ്ങൾ എന്നെ പരീക്ഷിക്കുന്നതെന്ത്?"},{"v":19,"t":"നികുതിക്കുള്ള നാണയം എന്നെ കാണിക്കുക. അവർ ഒരു ദനാറ അവന്റെ അടുക്കൽ കൊണ്ടുവന്നു."},{"v":20,"t":"യേശു ചോദിച്ചു: ഈ രൂപവും ലിഖിതവും ആരുടേതാണ്?"},{"v":21,"t":"സീസറിന്റേത് എന്ന് അവർ പറഞ്ഞു. അപ്പോൾ അവൻ അവരോട് അരുൾചെയ്തു: സീസറിന്റേതു സീസറിനും ദൈവത്തിന്റേതു ദൈവത്തിനും കൊടുക്കുക."},{"v":22,"t":"ഇതു കേട്ട് അവർ വിസ്മയഭരിതരായി അവനെ വിട്ടുപോയി."},{"h":"ഉത്ഥാനത്തെക്കുറിച്ച്"},{"v":23,"t":"ഉത്ഥാനമില്ലെന്നുപറഞ്ഞുകൊണ്ട് സദ്ദുക്കായർ അന്നുതന്നെ അവനെ സമീപിച്ചു ചോദിച്ചു:","p":1},{"v":24,"t":"ഗുരോ, ഒരുവൻ സന്താനമില്ലാതെ മരിച്ചാൽ അവന്റെ സഹോദരൻ ആ വിധവയെ വിവാഹം ചെയ്ത് സഹോദരനു സന്താനങ്ങളെ ഉത്പാദിപ്പിക്കണമെന്ന് മോശ പറഞ്ഞിട്ടുണ്ട്."},{"v":25,"t":"ഞങ്ങളുടെയിടയിൽ ഏഴു സഹോദരന്മാർ ഉണ്ടായിരുന്നു. ഒന്നാമൻ വിവാഹം ചെയ്ത് മരണമടഞ്ഞു. അവൻ സന്താനമില്ലാതെ ഭാര്യയെ തന്റെ സഹോദരനുവിട്ടു."},{"v":26,"t":"ഇങ്ങനെതന്നെ രണ്ടാമനും മൂന്നാമനും, അങ്ങനെ ഏഴാമനും വരെ."},{"v":27,"t":"ഒടുവിൽ, ആ സ്ത്രീയും മരിച്ചു."},{"v":28,"t":"അതിനാൽ, ഉത്ഥാനത്തിൽ അവൾ ഈ ഏഴുപേരിൽ ആരുടെ ഭാര്യയായിരിക്കും? കാരണം, അവർക്കെല്ലാം അവൾ ഭാര്യയായിരുന്നല്ലോ."},{"v":29,"t":"യേശു മറുപടി പറഞ്ഞു: വിശുദ്ധലിഖിതങ്ങളോ ദൈവത്തിന്റെ ശക്തിയോ മനസ്സിലാക്കാത്തതിനാൽ നിങ്ങൾക്കു തെറ്റുപറ്റിയിരിക്കുന്നു."},{"v":30,"t":"ഉത്ഥാനത്തിൽ അവർ വിവാഹം ചെയ്യുകയോ വിവാഹം ചെയ്തുകൊടുക്കുകയോ ഇല്ല. പിന്നെയോ, സ്വർഗത്തിൽ അവർ മാലാഖമാരെപ്പോലെയായിരിക്കും."},{"v":31,"t":"മരിച്ചവരുടെ ഉത്ഥാനത്തെപ്പറ്റി ദൈവം നിങ്ങളോട് അരുൾചെയ്തിരിക്കുന്നതു നിങ്ങൾ വായിച്ചിട്ടില്ലേ? ഞാൻ അബ്രാഹത്തിന്റെ ദൈവവും ഇസഹാക്കിന്റെ ദൈവവും യാക്കോബിന്റെ ദൈവവുമാണ്."},{"v":32,"t":"അവിടന്ന് മരിച്ചവരുടെ ദൈവമല്ല, ജീവിക്കുന്നവരുടേതാണ്."},{"v":33,"t":"ജനക്കൂട്ടം ഇതു കേട്ടപ്പോൾ അവന്റെ പ്രബോധനത്തെപ്പറ്റി ആശ്ചര്യപ്പെട്ടു."},{"h":"സുപ്രധാന കല്പനകൾ"},{"v":34,"t":"യേശു സദ്ദുക്കായരെ വാക്കുമുട്ടിച്ചെന്നു കേട്ടപ്പോൾ ഫരിസേയർ ഒന്നിച്ചു കൂടി.","p":1},{"v":35,"t":"അവരിൽ ഒരു നിയമപണ്ഡിതൻ അവനെ പരീക്ഷിച്ചുകൊണ്ടു ചോദിച്ചു:"},{"v":36,"t":"ഗുരോ, നിയമത്തിലെ ഏറ്റവും വലിയ കല്പന ഏതാണ്?"},{"v":37,"t":"അവൻ പറഞ്ഞു: നീ നിന്റെ ദൈവമായ കർത്താവിനെ പൂർണഹൃദയത്തോടും പൂർണാത്മാവോടും പൂർണമനസ്സോടുംകൂടെ സ്നേഹിക്കുക."},{"v":38,"t":"ഇതാണ് ഏറ്റവും വലുതും ഒന്നാമത്തേതുമായ കല്പന."},{"v":39,"t":"രണ്ടാമത്തേതും ഇതിനുതുല്യം തന്നെ; നിന്നെപ്പോലെ നിന്റെ അയല്ക്കാരനെയും സ്നേഹിക്കുക."},{"v":40,"t":"ഈ രണ്ടു കല്പനകളിൽ സമസ്തനിയമവും പ്രവാചകന്മാരും അധിഷ്ഠിതമായിരിക്കുന്നു."},{"h":"ക്രിസ്തു ദാവീദിന്റെ പുത്രൻ"},{"v":41,"t":"ഫരിസേയർ ഒരുമിച്ചുകൂടിയപ്പോൾ യേശു അവരോടു ചോദിച്ചു:","p":1},{"v":42,"t":"നിങ്ങൾ ക്രിസ്തുവിനെപ്പറ്റി എന്തു വിചാരിക്കുന്നു? അവൻ ആരുടെ പുത്രനാണ്? ദാവീദിന്റെ എന്ന് അവർ പറഞ്ഞു."},{"v":43,"t":"അവൻ ചോദിച്ചു: അങ്ങനെയെങ്കിൽ ദാവീദ് ആത്മാവിൽ അവനെ കർത്താവ് എന്നു വിളിക്കുന്നതെങ്ങനെ?"},{"v":44,"t":"അവൻ പറയുന്നു: കർത്താവ് എന്റെ കർത്താവിനോട് അരുൾചെയ്തു, ഞാൻ നിന്റെ ശത്രുക്കളെ നിന്റെ പാദങ്ങൾക്കു കീഴിലാക്കുവോളം നീ എന്റെ വലത്തുഭാഗത്തിരിക്കുക."},{"v":45,"t":"അതിനാൽ, ദാവീദ് അവനെ കർത്താവേ എന്നു വിളിക്കുന്നെങ്കിൽ അവൻ അവന്റെ പുത്രനാകുന്നത് എങ്ങനെ?"},{"v":46,"t":"അവനോട് ഉത്തരമായി ഒരു വാക്കുപോലും പറയാൻ ആർക്കും കഴിഞ്ഞില്ല. അന്നു മുതൽ അവനോട് എന്തെങ്കിലും ചോദിക്കാൻ ആരും ധൈര്യപ്പെട്ടതുമില്ല."}],"23":[{"h":"നിയമജ്ഞരുടെയും ഫരിസേയരുടെയും കപടനാട്യം"},{"v":1,"t":"അപ്പോൾ യേശു ജനക്കൂട്ടത്തോടും തന്റെ ശിഷ്യന്മാരോടും അരുൾചെയ്തു:","p":1},{"v":2,"t":"നിയമജ്ഞരും ഫരിസേയരും മോശയുടെ സിംഹാസനത്തിൽ ഇരിക്കുന്നു."},{"v":3,"t":"അതിനാൽ, അവർ നിങ്ങളോടു പറയുന്നതെല്ലാം നിങ്ങൾ പ്രവർത്തിക്കുകയും പാലിക്കുകയും ചെയ്യുവിൻ. എന്നാൽ, അവരുടെ പ്രവൃത്തികൾ നിങ്ങൾ ചെയ്യരുത്. എന്തെന്നാൽ അവർ പറയുന്നു, പക്ഷേ, പ്രവർത്തിക്കുന്നില്ല."},{"v":4,"t":"അവർ ഭാരമുള്ളതും ദുർവഹവുമായ ചുമടുകൾ മനുഷ്യരുടെ ചുമലുകളിൽ കെട്ടിവച്ചുകൊടുക്കുന്നു. അവർ, വിരൽകൊണ്ടുപോലും അവ നീക്കാനാകട്ടെ, തയ്യാറാകുന്നുമില്ല."},{"v":5,"t":"മനുഷ്യരാൽ കാണപ്പെടാൻ വേണ്ടിയാണ് അവർ തങ്ങളുടെ പ്രവൃത്തികളെല്ലാം ചെയ്യുന്നത്. അവർ തങ്ങളുടെ നെറ്റിപ്പട്ടകൾക്കു വീതിയും വസ്ത്രത്തിന്റെ തൊങ്ങലുകൾക്കു നീളവും കൂട്ടുന്നു."},{"v":6,"t":"വിരുന്നുകളിൽ പ്രമുഖസ്ഥാനവും സിനഗോഗുകളിൽ പ്രധാനപീഠങ്ങളും"},{"v":7,"t":"പൊതുസ്ഥലങ്ങളിൽ അഭിവാദനവും മനുഷ്യരാൽ റബ്ബീ എന്ന സംബോധനവും അവർ ഇഷ്ടപ്പെടുന്നു."},{"v":8,"t":"എന്നാൽ, നിങ്ങൾ റബ്ബീ എന്നു വിളിക്കപ്പെടരുത്. എന്തെന്നാൽ, നിങ്ങൾക്ക് ഗുരുവൊന്നേയുള്ളു. നിങ്ങളെല്ലാം സഹോദരന്മാരാണ്."},{"v":9,"t":"ഭൂമിയിൽ ആരെയും നിങ്ങൾ പിതാവെന്നു വിളിക്കരുത്. എന്തെന്നാൽ, നിങ്ങൾക്ക് പിതാവൊന്നേയുള്ളു, സ്വർഗസ്ഥനായവൻ."},{"v":10,"t":"നിങ്ങൾ ആചാര്യന്മാർ എന്നും വിളിക്കപ്പെടരുത്. എന്തെന്നാൽ, നിങ്ങൾക്ക് ആചാര്യൻ ഒന്നേയുള്ളു, ക്രിസ്തു."},{"v":11,"t":"നിങ്ങളിൽ ഏറ്റവും വലിയവൻ നിങ്ങളുടെ ശുശ്രൂഷകനായിരിക്കണം."},{"v":12,"t":"തന്നെത്തന്നെ ഉയർത്തുന്നവൻ താഴ്ത്തപ്പെടും; തന്നെത്തന്നെ താഴ്ത്തുന്നവൻ ഉയർത്തപ്പെടും."},{"v":13,"t":"കപടനാട്യക്കാരായ നിയമജ്ഞരേ, ഫരിസേയരേ, നിങ്ങൾക്കു ദുരിതം! നിങ്ങൾ മനുഷ്യരുടെ മുമ്പിൽ സ്വർഗരാജ്യം അടച്ചുകളയുന്നു.","p":1},{"v":14,"t":"കാരണം, നിങ്ങൾ അതിൽ പ്രവേശിക്കുന്നില്ല; പ്രവേശിക്കാൻ വരുന്നവരെ അനുവദിക്കുന്നുമില്ല."},{"v":15,"t":"കപടനാട്യക്കാരായ നിയമജ്ഞരേ, ഫരിസേയരേ, നിങ്ങൾക്കു ദുരിതം! ഒരുവനെ നിങ്ങളുടെ മതത്തിൽ ചേർക്കാൻ നിങ്ങൾ കടലും കരയും ചുറ്റി സഞ്ചരിക്കുന്നു. ചേർന്നു കഴിയുമ്പോൾ നിങ്ങൾ അവനെ നിങ്ങളെക്കാൾ ഇരട്ടിയായി നരകസന്തതിയാക്കിത്തീർക്കുന്നു."},{"v":16,"t":"അന്ധരായ വഴികാട്ടികളേ, നിങ്ങൾക്കു ദുരിതം! നിങ്ങൾ പറയുന്നു: ഒരുവൻ ദേവാലയത്തെക്കൊണ്ട് ആണയിട്ടാൽ ഒന്നുമില്ല, ദേവാലയത്തിലെ സ്വർണത്തെക്കൊണ്ട് ആണയിട്ടാൽ അവൻ കടപ്പെട്ടവനാണ്!"},{"v":17,"t":"മൂഢരും അന്ധരുമായവരേ, ഏതാണു വലുത്? സ്വർണമോ സ്വർണത്തെ പവിത്രമാക്കുന്ന ദേവാലയമോ?"},{"v":18,"t":"നിങ്ങൾ പറയുന്നു: ഒരുവൻ ബലിപീഠത്തെക്കൊണ്ട് ആണയിട്ടാൽ ഒന്നുമില്ല; എന്നാൽ ബലിപീഠത്തിലെ കാഴ്ചവസ്തുവിനെക്കൊണ്ട് ആണയിട്ടാൽ അവൻ കടപ്പെട്ടവനാണ്!"},{"v":19,"t":"അന്ധരേ, ഏതാണു വലുത്? കാഴ്ചവസ്തുവോ കാഴ്ചവസ്തുവിനെ പവിത്രമാക്കുന്ന ബലിപീഠമോ?"},{"v":20,"t":"ബലിപീഠത്തെക്കൊണ്ട് ആണയിടുന്നവൻ അതിനെക്കൊണ്ടും അതിന്മേലുള്ള എല്ലാവസ്തുക്കളെക്കൊണ്ടും ആണയിടുന്നു."},{"v":21,"t":"ദേവാലയത്തെക്കൊണ്ട് ആണയിടുന്നവൻ അതിനെക്കൊണ്ടും അതിൽ വസിക്കുന്നവനെക്കൊണ്ടും ആണയിടുന്നു."},{"v":22,"t":"സ്വർഗത്തെക്കൊണ്ട് ആണയിടുന്നവൻ ദൈവത്തിന്റെ സിംഹാസനത്തെക്കൊണ്ടും അതിൽ ഇരിക്കുന്നവനെക്കൊണ്ടും ആണയിടുന്നു."},{"v":23,"t":"കപടനാട്യക്കാരായ നിയമജ്ഞരേ, ഫരിസേയരേ, നിങ്ങൾക്കു ദുരിതം! നിങ്ങൾ കർപ്പൂരത്തുളസി, ചതകുപ്പ, ജീരകം എന്നിവയ്ക്കു ദശാംശം കൊടുക്കുകയും നിയമത്തിലെ ഗൗരവമേറിയ കാര്യങ്ങളായ നീതി, കാരുണ്യം, വിശ്വസ്തത എന്നിവ അവഗണിക്കുകയും ചെയ്യുന്നു. ഇവയാണു നിങ്ങൾ ചെയ്യേണ്ടിയിരുന്നത്, മറ്റുള്ളവ അവഗണിക്കാതെതന്നെ."},{"v":24,"t":"അന്ധരായ വഴികാട്ടികളേ, കൊതുകിനെ അരിച്ചുനീക്കുകയും ഒട്ടകത്തെ വിഴുങ്ങുകയും ചെയ്യുന്നവരാണു നിങ്ങൾ!"},{"v":25,"t":"കപടനാട്യക്കാരായ നിയമജ്ഞരേ, ഫരിസേയരേ, നിങ്ങൾക്കു ദുരിതം! നിങ്ങൾ പാനപാത്രത്തിന്റെയും ഭക്ഷണപാത്രത്തിന്റെയും പുറം വെടിപ്പാക്കുന്നു; എന്നാൽ, അവയുടെ ഉള്ള് കവർച്ചയും അത്യാർത്തിയും കൊണ്ട് നിറഞ്ഞിരിക്കുന്നു."},{"v":26,"t":"അന്ധനായ ഫരിസേയാ, പാനപാത്രത്തിന്റെയും ഭക്ഷണപാത്രത്തിന്റെയും പുറംകൂടി ശുദ്ധമാകാൻ വേണ്ടി ആദ്യമേ അകം ശുദ്ധമാക്കുക."},{"v":27,"t":"കപടനാട്യക്കാരായ നിയമജ്ഞരേ, ഫരിസേയരേ, നിങ്ങൾക്കു ദുരിതം! നിങ്ങൾ വെള്ളയടിച്ച കുഴിമാടങ്ങൾക്കു സദൃശരാണ്. അവ പുറമേ മനോഹരമായി കാണപ്പെടുന്നെങ്കിലും അവയ്ക്കുള്ളിൽ മരിച്ചവരുടെ അസ്ഥികളും സർവവിധ മാലിന്യങ്ങളും നിറഞ്ഞു കിടക്കുന്നു."},{"v":28,"t":"അതുപോലെ, ബാഹ്യമായി മനുഷ്യർക്ക് നീതിമാന്മാരായി കാണപ്പെടുന്ന നിങ്ങൾ, ഉള്ളിൽ കാപട്യവും അനീതിയും നിറഞ്ഞവരാണ്."},{"v":29,"t":"കപടനാട്യക്കാരായ നിയമജ്ഞരേ, ഫരിസേയരേ, നിങ്ങൾക്കു ദുരിതം! നിങ്ങൾ പ്രവാചകന്മാർക്കു ശവകുടീരങ്ങൾ നിർമിക്കുകയും നീതിമാന്മാരുടെ സ്മാരകങ്ങൾ അലങ്കരിക്കുകയും ചെയ്തുകൊണ്ടു പറയുന്നു,"},{"v":30,"t":"ഞങ്ങൾ ഞങ്ങളുടെ പിതാക്കന്മാരുടെ കാലത്തു ജീവിച്ചിരുന്നെങ്കിൽ, പ്രവാചകന്മാരുടെ രക്തത്തിൽ അവരുടെ പങ്കാളികളാകുമായിരുന്നില്ല."},{"v":31,"t":"അങ്ങനെ നിങ്ങൾ പ്രവാചകന്മാരെ വധിച്ചവരുടെ സന്താനങ്ങളാണെന്ന്, നിങ്ങൾക്കുതന്നെ എതിരായി സാക്ഷ്യംനല്കുന്നു."},{"v":32,"t":"നിങ്ങളുടെ പിതാക്കന്മാരുടെ പാപത്തിന്റെ അളവ് നിങ്ങൾ പൂർത്തിയാക്കുവിൻ!"},{"v":33,"t":"സർപ്പങ്ങളേ, അണലിസന്തതികളേ, നരകവിധിയിൽ നിന്ന് നിങ്ങളെങ്ങനെ ഓടിയകലും?"},{"v":34,"t":"അതുകൊണ്ട്, ഇതാ, പ്രവാചകന്മാരെയും ജ്ഞാനികളെയും നിയമജ്ഞരെയും ഞാൻ നിങ്ങളുടെ അടുക്കലേക്കയയ്ക്കുന്നു. അവരിൽ ചിലരെ നിങ്ങൾ വധിക്കുകയും ക്രൂശിക്കുകയും ചെയ്യും; ചിലരെ നിങ്ങൾ നിങ്ങളുടെ സിനഗോഗുകളിൽ വച്ച് ചമ്മട്ടികൊണ്ടടിക്കുകയും പട്ടണംതോറും പിന്തുടർന്നു പീഡിപ്പിക്കുകയുംചെയ്യും."},{"v":35,"t":"അങ്ങനെ, നീതിമാനായ ആബേലിന്റെ രക്തംമുതൽ, ദേവാലയത്തിനും ബലിപീഠത്തിനും മധ്യേവച്ച് നിങ്ങൾ വധിച്ച ബറാക്കിയായുടെ പുത്രൻ സഖറിയായുടെ രക്തംവരെ, ഭൂമിയിൽ ചൊരിയപ്പെട്ട നീതിയുടെ രക്തം മുഴുവൻ നിങ്ങളുടെമേൽ പതിക്കും."},{"v":36,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ഇവയെല്ലാം ഈ തലമുറയ്ക്കു സംഭവിക്കുകതന്നെ ചെയ്യും."},{"h":"യേശു ജറുസലേമിനെക്കുറിച്ചു വിലപിക്കുന്നു"},{"v":37,"t":"ജറുസലേം, ജറുസലേം, പ്രവാചകൻമാരെ വധിക്കുകയും നിന്റെ അടുത്തേക്ക് അയയ്ക്കപ്പെടുന്നവരെ കല്ലെറിയുകയും ചെയ്യുന്നവളേ, പിടക്കോഴി കുഞ്ഞുങ്ങളെ ചിറകിൻകീഴിൽ കാത്തുകൊള്ളുന്നപോലെ, നിന്റെ സന്തതികളെ ഒരുമിച്ചുകൂട്ടാൻ ഞാൻ എത്രയോ പ്രാവശ്യം ആഗ്രഹിച്ചു. പക്ഷേ, നിങ്ങൾ സമ്മതിച്ചില്ല.","p":1},{"v":38,"t":"ഇതാ, നിങ്ങളുടെ ഭവനം പരിത്യക്തവും ശൂന്യവുമായിത്തീർന്നിരിക്കുന്നു."},{"v":39,"t":"അതിനാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു, കർത്താവിന്റെ നാമത്തിൽ വരുന്നവൻ അനുഗൃഹീതനാണ് എന്നു നിങ്ങൾ പറയുന്നതുവരെ നിങ്ങൾ ഇനി എന്നെ കാണുകയില്ല."}],"24":[{"h":"ദേവാലയത്തിന്റെ നാശം"},{"v":1,"t":"പിന്നെ യേശു പുറത്തിറങ്ങി. ദേവാലയത്തിൽ നിന്നു പോകുമ്പോൾ ദേവാലയത്തിന്റെ പണിത്തരങ്ങൾ അവനു കാണിച്ചു കൊടുക്കാൻ ശിഷ്യന്മാർ അടുത്തെത്തി.","p":1},{"v":2,"t":"അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ ഇവയെല്ലാം കാണുന്നല്ലോ. സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ഇവിടെ കല്ലിന്മേൽ കല്ലു ശേഷിക്കാതെ എല്ലാം തകർക്കപ്പെടും."},{"h":"വേദനകളുടെ ആരംഭം"},{"v":3,"t":"അവൻ ഒലിവുമലയിൽ ഇരിക്കുമ്പോൾ ശിഷ്യന്മാർ മാത്രമായി അവനെ സമീപിച്ചു പറഞ്ഞു: ഇതെല്ലാം എപ്പോൾ സംഭവിക്കുമെന്നും നിന്റെ ആഗമനത്തിന്റെയും യുഗാന്തത്തിന്റെയും അടയാളമെന്താണെന്നും ഞങ്ങൾക്കു പറഞ്ഞു തരണമേ.","p":1},{"v":4,"t":"യേശു അവരോടു പറഞ്ഞു: ആരും നിങ്ങളെ വഴിതെറ്റിക്കാതിരിക്കാൻ സൂക്ഷിച്ചുകൊള്ളുവിൻ."},{"v":5,"t":"പലരും എന്റെ നാമത്തിൽ വന്ന്, ഞാൻ ക്രിസ്തുവാണ് എന്നുപറയുകയും അനേകരെ വഴിതെറ്റിക്കുകയും ചെയ്യും."},{"v":6,"t":"നിങ്ങൾ യുദ്ധങ്ങളെപ്പറ്റി കേൾക്കാനിരിക്കുന്നു; അവയെപ്പറ്റിയുള്ള കിംവദന്തികളും. എന്നാൽ, അസ്വസ്ഥരാകാതെ സൂക്ഷിക്കുവിൻ. കാരണം, ഇതെല്ലാം സംഭവിക്കേണ്ടതാണ്. എന്നാൽ അവസാനം ഇനിയുമായിട്ടില്ല."},{"v":7,"t":"ജനം ജനത്തിനെതിരായും രാജ്യം രാജ്യത്തിനെതിരായും അണിനിരക്കും. ക്ഷാമവും ഭൂകമ്പങ്ങളും പല സ്ഥലങ്ങളിലുമുണ്ടാകും."},{"v":8,"t":"ഇവയെല്ലാം ഈറ്റുനോവിന്റെ ആരംഭം മാത്രം."},{"v":9,"t":"അവർ നിങ്ങളെ പീഡനത്തിന് ഏല്പിച്ചുകൊടുക്കുകയും കൊല്ലുകയും ചെയ്യും. എന്റെ നാമം നിമിത്തം സർവജനങ്ങളാലും നിങ്ങൾ വെറുക്കപ്പെടും."},{"v":10,"t":"അപ്പോൾ അനേകർ ഇടർച്ചയ്ക്കു വിധേയരാകുകയും പരസ്പരം ഒറ്റിക്കൊടുക്കുകയും വെറുക്കുകയും ചെയ്യും."},{"v":11,"t":"നിരവധി വ്യാജപ്രവാചകന്മാർ ഉണ്ടാകുകയും അനേകരെ വഴിതെറ്റിക്കുകയും ചെയ്യും."},{"v":12,"t":"അനീതി പെരുകുന്നതിനാൽ പലരുടെയും സ്നേഹം തണുത്തുപോകും."},{"v":13,"t":"എന്നാൽ, അവസാനംവരെ സഹിച്ചു നില്ക്കുന്നവൻ ആരോ, അവൻ രക്ഷിക്കപ്പെടും."},{"v":14,"t":"എല്ലാ ജനതകളുടെയും സാക്ഷ്യത്തിനായി രാജ്യത്തിന്റെ ഈ സുവിശേഷം ലോകമെങ്ങും പ്രസംഗിക്കപ്പെടും. അപ്പോൾ അവസാനം വരും."},{"h":"ഭീകരദുരിതങ്ങൾ"},{"v":15,"t":"ദാനിയേൽപ്രവാചകൻ പറഞ്ഞ വിനാശത്തിന്റെ മ്ലേച്ഛത വിശുദ്ധസ്ഥലത്തായിരിക്കുന്നതു നിങ്ങൾ കാണുമ്പോൾ - വായിക്കുന്നവൻ ഗ്രഹിക്കട്ടെ -","p":1},{"v":16,"t":"യൂദയായിലുള്ളവർ പർവതങ്ങളിലേക്കു പലായനം ചെയ്യട്ടെ."},{"v":17,"t":"പുരമുകളിലായിരിക്കുന്നവൻ വീട്ടിൽനിന്ന് എന്തെങ്കിലും എടുക്കാൻ താഴേക്ക് ഇറങ്ങാതിരിക്കട്ടെ."},{"v":18,"t":"വയലിലായിരിക്കുന്നവൻ മേലങ്കിയെടുക്കാൻ പിൻതിരിയാതിരിക്കട്ടെ."},{"v":19,"t":"ആ ദിവസങ്ങളിൽ ഗർഭിണികൾക്കും മുലയൂട്ടുന്നവർക്കും ദുരിതം!"},{"v":20,"t":"നിങ്ങളുടെ പലായനം ശീതകാലത്തോ സാബത്തിലോ ആകാതിരിക്കാൻ പ്രാർഥിക്കുവിൻ."},{"v":21,"t":"എന്തെന്നാൽ, ലോകാരംഭം മുതൽ ഇന്നുവരെ ഉണ്ടായിട്ടില്ലാത്ത, ഇനി ഉണ്ടാകാനിടയില്ലാത്ത ഉഗ്രപീഡനം അന്നുണ്ടാകും."},{"v":22,"t":"ആ ദിവസങ്ങൾ ചുരുക്കപ്പെടുന്നില്ലെങ്കിൽ ഒരുവനും രക്ഷപ്പെടുകയില്ല. എന്നാൽ, തിരഞ്ഞെടുക്കപ്പെട്ടവരെപ്രതി ആ ദിവസങ്ങൾ ചുരുക്കപ്പെടും."},{"v":23,"t":"അപ്പോൾ ഇതാ, ക്രിസ്തു ഇവിടെ, അല്ലെങ്കിൽ അവിടെ എന്ന് ആരെങ്കിലും പറഞ്ഞാൽ നിങ്ങൾ വിശ്വസിക്കരുത്."},{"v":24,"t":"കാരണം, കള്ളക്രിസ്തുമാരും വ്യാജപ്രവാചകന്മാരും ഉണ്ടാകുകയും സാധിക്കുമെങ്കിൽ തിരഞ്ഞെടുക്കപ്പെട്ടവരെപ്പോലും വഴിതെറ്റിക്കത്തക്കവിധം വലിയ അടയാളങ്ങളും അദ്ഭുതങ്ങളും കാണിക്കുകയും ചെയ്യും."},{"v":25,"t":"ഇതാ, ഞാൻ മുൻകൂട്ടി നിങ്ങളോടു പറഞ്ഞിരിക്കുന്നു."},{"v":26,"t":"അതുകൊണ്ട്, ഇതാ, അവൻ മരുഭൂമിയിലുണ്ടെന്ന് അവർ നിങ്ങളോടു പറഞ്ഞാൽ നിങ്ങൾ പുറപ്പെടരുത്. ഇതാ, അവൻ മുറിക്കുള്ളിലുണ്ട് എന്നു പറഞ്ഞാലും നിങ്ങൾ വിശ്വസിക്കരുത്."},{"v":27,"t":"കിഴക്കുനിന്നു പടിഞ്ഞാറോട്ടു പായുന്ന മിന്നൽപ്പിണർ പോലെയായിരിക്കും മനുഷ്യപുത്രന്റെ ആഗമനം."},{"v":28,"t":"ശവം എവിടെയുണ്ടോ, അവിടെ കഴുകന്മാർ വന്നുകൂടും."},{"h":"മനുഷ്യപുത്രന്റെ ആഗമനം"},{"v":29,"t":"ആ ദിനങ്ങളിലെ പീഡനത്തിനുശേഷം പൊടുന്നനേ സൂര്യൻ ഇരുണ്ടുപോകും. ചന്ദ്രൻ അതിന്റെ പ്രകാശം തരുകയില്ല. നക്ഷത്രങ്ങൾ ആകാശത്തിൽനിന്നു നിപതിക്കും. ആകാശശക്തികൾ ഇളകുകയും ചെയ്യും.","p":1},{"v":30,"t":"അപ്പോൾ ആകാശത്തിൽ മനുഷ്യപുത്രന്റെ അടയാളം പ്രത്യക്ഷപ്പെടും; ഭൂമിയിലെ സകലഗോത്രങ്ങളും വിലപിക്കുകയും മനുഷ്യപുത്രൻ വാനമേഘങ്ങളിൽ ശക്തിയോടും സർവമഹത്ത്വത്തോടുംകൂടെ വരുന്നതു കാണുകയും ചെയ്യും."},{"v":31,"t":"വലിയ കാഹളധ്വനിയോടെ അവൻ തന്റെ ദൂതന്മാരെ അയയ്ക്കും. അവർ ആകാശത്തിന്റെ ഒരറ്റംമുതൽ മറ്റേ അറ്റംവരെ നാലു ദിക്കുകളിലുംനിന്ന് അവന്റെ തിരഞ്ഞെടുക്കപ്പെട്ടവരെ ഒരുമിച്ചുകൂട്ടും."},{"v":32,"t":"അത്തിമരത്തിൽനിന്ന് നിങ്ങൾ ഒരു ഉപമ പഠിക്കുവിൻ. അതിന്റെ കൊമ്പുകൾ ഇളതാവുകയും തളിർക്കുകയും ചെയ്യുമ്പോൾ വേനല്ക്കാലം അടുത്തിരിക്കുന്നെന്നു നിങ്ങൾ മനസ്സിലാക്കുന്നു."},{"v":33,"t":"അതുപോലെ, നിങ്ങളും ഇവയെല്ലാം കാണുമ്പോൾ അവൻ സമീപത്ത്, വാതില്ക്കലെത്തിയിരിക്കുന്നു എന്നു മനസ്സിലാക്കിക്കൊള്ളുവിൻ."},{"v":34,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ഇവയെല്ലാം സംഭവിക്കുന്നതുവരെ ഈ തലമുറ കടന്നുപോകുകയില്ല."},{"v":35,"t":"ആകാശവും ഭൂമിയും കടന്നുപോകും; എന്നാൽ, എന്റെ വചനങ്ങൾ കടന്നുപോകുകയില്ല."},{"h":"സദാ ജാഗരൂകരായിരിക്കുവിൻ"},{"v":36,"t":"ആ ദിവസത്തെക്കുറിച്ചോ മണിക്കൂറിനെക്കുറിച്ചോ പിതാവിനല്ലാതെ മറ്റാർക്കും, സ്വർഗത്തിലെ ദൂതന്മാർക്കോ പുത്രനുപോലുമോ, അറിഞ്ഞുകൂടാ.","p":1},{"v":37,"t":"നോഹയുടെ ദിവസങ്ങളിലേതുപോലെ ആയിരിക്കും, മനുഷ്യപുത്രന്റെ ആഗമനം."},{"v":38,"t":"ജലപ്രളയത്തിനു മുമ്പുള്ള ദിവസങ്ങളിൽ, നോഹ പെട്ടകത്തിൽ പ്രവേശിച്ച ദിവസംവരെ, അവർ തിന്നും കുടിച്ചും വിവാഹം ചെയ്തും ചെയ്യിച്ചും കഴിഞ്ഞുപോന്നു."},{"v":39,"t":"ജലപ്രളയം വന്ന് സർവരെയും സംഹരിക്കുന്നതുവരെ അവർ ഒന്നുമറിഞ്ഞില്ല. ഇപ്രകാരംതന്നെയായിരിക്കും മനുഷ്യപുത്രന്റെ ആഗമനവും."},{"v":40,"t":"അപ്പോൾ രണ്ടുപേർ വയലിലായിരിക്കും; ഒരാൾ എടുക്കപ്പെടും, മറ്റെയാൾ ഉപേക്ഷിക്കപ്പെടും."},{"v":41,"t":"രണ്ടു സ്ത്രീകൾ തിരികല്ലിൽ പൊടിച്ചുകൊണ്ടിരിക്കും. ഒരുവൾ എടുക്കപ്പെടും, മറ്റവൾ ഉപേക്ഷിക്കപ്പെടും."},{"v":42,"t":"ആകയാൽ, ജാഗരൂകരായിരിക്കുവിൻ. നിങ്ങളുടെ കർത്താവ് ഏതുദിവസം വരുമെന്ന് നിങ്ങൾ അറിയുന്നില്ല."},{"v":43,"t":"അതിനാൽ ഇത് നിങ്ങൾ അറിയുവിൻ. കള്ളൻ രാത്രിയുടെ ഏതു യാമത്തിൽ വരുമെന്ന് ഗൃഹനാഥൻ അറിഞ്ഞിരുന്നെങ്കിൽ, അവൻ ഉണർന്നിരിക്കുകയും ഭവനഭേദനം ചെയ്യാൻ ഇടകൊടുക്കാതിരിക്കുകയും ചെയ്യുമായിരുന്നു."},{"v":44,"t":"അതിനാൽ, നിങ്ങളും തയ്യാറായിരിക്കണം. നിങ്ങൾ പ്രതീക്ഷിക്കാത്ത മണിക്കൂറിലായിരിക്കും മനുഷ്യപുത്രൻ വരുന്നത്."},{"v":45,"t":"തന്റെ ഭവനത്തിലുള്ളവർക്ക് കൃത്യസമയത്തു ഭക്ഷണം കൊടുക്കാൻ യജമാനൻ നിയോഗിച്ച വിശ്വസ്തനും വിവേകിയുമായ ഭൃത്യൻ ആരാണ്?"},{"v":46,"t":"തന്റെ യജമാനൻ വരുമ്പോൾ അപ്രകാരം ചെയ്യുന്നതായി കാണപ്പെടുന്ന ആ ഭൃത്യൻ ഭാഗ്യവാൻ."},{"v":47,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, യജമാനൻ അവനെ തന്റെ വസ്തുക്കളുടെയെല്ലാം മേല്നോട്ടക്കാരനാക്കും."},{"v":48,"t":"എന്നാൽ, ദുഷ്ടനായ ഭൃത്യൻ എന്റെ യജമാനൻ താമസിച്ചേ വരൂ എന്ന് ഉള്ളിൽ പറഞ്ഞ്,"},{"v":49,"t":"തന്റെ സഹഭൃത്യന്മാരെ മർദിക്കാനും മദ്യപന്മാരോടുകൂടെ ഭക്ഷിക്കാനും പാനം ചെയ്യാനും തുടങ്ങിയാൽ,"},{"v":50,"t":"പ്രതീക്ഷിക്കാത്ത ദിവസത്തിലും അറിയാത്തമണിക്കൂറിലും ആ ഭൃത്യന്റെ യജമാനൻ വന്ന്,"},{"v":51,"t":"അവനെ അതിനിഷ്ഠുരമായി ശിക്ഷിക്കുകയും കപടനാട്യക്കാരുടെ കൂട്ടത്തിൽ തള്ളുകയും ചെയ്യും. അവിടെ കരച്ചിലും പല്ലുകടിയുമായിരിക്കും."}],"25":[{"h":"പത്തുകന്യകമാരുടെ ഉപമ"},{"v":1,"t":"സ്വർഗരാജ്യം, വിളക്കുകളെടുത്ത് മണവാളന്റെ എതിരേല്പിനു പുറപ്പെട്ട പത്തു കന്യകമാർക്കു സദൃശം.","p":1},{"v":2,"t":"അവരിൽ അഞ്ചുപേർ വിവേകശൂന്യരും അഞ്ചുപേർ ബുദ്ധിമതികളുമായിരുന്നു."},{"v":3,"t":"വിവേകശൂന്യർ അവരുടെ വിളക്കുകൾ എടുത്തപ്പോൾ, കൂടെ എണ്ണ എടുത്തിരുന്നില്ല."},{"v":4,"t":"ബുദ്ധിമതികളാകട്ടെ, വിളക്കുകളോടൊപ്പം പാത്രങ്ങളിൽ എണ്ണയും എടുത്തിരുന്നു."},{"v":5,"t":"മണവാളൻ വരാൻ വൈകിയപ്പോൾ നിദ്രാഭാരത്താൽ എല്ലാവരും കിടന്നുറങ്ങി."},{"v":6,"t":"അർധരാത്രിയിൽ, ആർപ്പുവിളിയുണ്ടായി: ഇതാ, മണവാളൻ! അവന്റെ എതിരേല്പിന് പുറത്തുവരുവിൻ!"},{"v":7,"t":"ആ കന്യകമാരെല്ലാം ഉണർന്ന് അവരവരുടെ വിളക്കുകൾ ഒരുക്കി."},{"v":8,"t":"വിവേകശൂന്യർ ബുദ്ധിമതികളോടു പറഞ്ഞു: ഞങ്ങളുടെ വിളക്കുകൾ അണഞ്ഞുപോകുന്നതിനാൽ നിങ്ങളുടെ എണ്ണയിൽ കുറെ ഞങ്ങൾക്കു തരുക."},{"v":9,"t":"ബുദ്ധിമതികൾ മറുപടിപറഞ്ഞു: ഞങ്ങൾക്കും നിങ്ങൾക്കും മതിയാകാതെ വരുമെന്നതിനാൽ നിങ്ങൾ വില്പനക്കാരുടെ അടുത്തുപോയി വാങ്ങിക്കൊള്ളുവിൻ."},{"v":10,"t":"അവർ വാങ്ങാൻ പോയപ്പോൾ മണവാളൻ വന്നു. ഒരുങ്ങിയിരുന്നവർ അവനോടൊത്തു വിവാഹവിരുന്നിന് അകത്തുപ്രവേശിച്ചു; വാതിൽ അടയ്ക്കപ്പെടുകയും ചെയ്തു."},{"v":11,"t":"പിന്നീട് മറ്റു കന്യകമാർ വന്ന്, കർത്താവേ, കർത്താവേ, ഞങ്ങൾക്കു തുറന്നുതരണമേ എന്ന് അപേക്ഷിച്ചു."},{"v":12,"t":"അവൻ പ്രതിവചിച്ചു: സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ഞാൻ നിങ്ങളെ അറിയുകയില്ല."},{"v":13,"t":"അതിനാൽ, ജാഗരൂകരായിരിക്കുവിൻ; ആ ദിവസമോ മണിക്കൂറോ നിങ്ങൾ അറിയുന്നില്ല."},{"h":"താലന്തുകളുടെ ഉപമ"},{"v":14,"t":"ഒരു മനുഷ്യൻ യാത്രപുറപ്പെടുന്നതിനുമുമ്പ് ഭൃത്യന്മാരെ വിളിച്ച് തന്റെ സമ്പത്ത് അവരെ ഭരമേല്പിച്ചതു പോലെയാണ് സ്വർഗരാജ്യം.","p":1},{"v":15,"t":"അവൻ ഓരോരുത്തന്റെയും കഴിവനുസരിച്ച് ഒരുവന് അഞ്ചു താലന്തും മറ്റൊരുവന് രണ്ടും വേറൊരുവന് ഒന്നും കൊടുത്തശേഷം യാത്രപുറപ്പെട്ടു."},{"v":16,"t":"അഞ്ചു താലന്തു ലഭിച്ചവൻ ഉടനെ പോയി വ്യാപാരംചെയ്ത് അഞ്ചു താലന്തുകൂടി സമ്പാദിച്ചു."},{"v":17,"t":"അതുപോലെ, രണ്ടു താലന്തു കിട്ടിയവൻ രണ്ടുകൂടി നേടി."},{"v":18,"t":"എന്നാൽ, ഒരു താലന്തു ലഭിച്ചവൻ പോയി നിലംകുഴിച്ച് യജമാനന്റെ പണം മറച്ചുവച്ചു."},{"v":19,"t":"ഏറെക്കാലത്തിനു ശേഷം ആ ഭൃത്യന്മാരുടെ യജമാനൻ വന്ന് അവരുമായി കണക്കുതീർത്തു."},{"v":20,"t":"അഞ്ചു താലന്തു കിട്ടിയവൻ വന്ന്, അഞ്ചുകൂടി സമർപ്പിച്ച്, യജമാനനേ, നീ എനിക്ക് അഞ്ചു താലന്താണല്ലോ നല്കിയത്; ഇതാ, ഞാൻ അഞ്ചുകൂടി സമ്പാദിച്ചിരിക്കുന്നു എന്നുപറഞ്ഞു."},{"v":21,"t":"അവന്റെ യജമാനൻ പറഞ്ഞു: കൊള്ളാം, നല്ലവനും വിശ്വസ്തനുമായ ഭൃത്യാ, അല്പകാര്യങ്ങളിൽ വിശ്വസ്തനായിരുന്നതിനാൽ അനേകകാര്യങ്ങൾ നിന്നെ ഞാൻ ഭരമേല്പിക്കും. നിന്റെ യജമാനന്റെ സന്തോഷത്തിലേക്കു നീ പ്രവേശിക്കുക."},{"v":22,"t":"രണ്ടു താലന്തു കിട്ടിയവനും വന്നു പറഞ്ഞു: യജമാനനേ, നീ എനിക്ക് രണ്ടു താലന്താണല്ലോ നല്കിയത്. ഇതാ, ഞാൻ രണ്ടുകൂടി സമ്പാദിച്ചിരിക്കുന്നു."},{"v":23,"t":"അവന്റെ യജമാനൻ പറഞ്ഞു: കൊള്ളാം, നല്ലവനും വിശ്വസ്തനുമായ ഭൃത്യാ, അല്പകാര്യങ്ങളിൽ വിശ്വസ്തനായിരുന്നതിനാൽ അനേകകാര്യങ്ങൾ നിന്നെ ഞാൻ ഭരമേല്പിക്കും. നിന്റെ യജമാനന്റെ സന്തോഷത്തിലേക്കു നീ പ്രവേശിക്കുക."},{"v":24,"t":"ഒരു താലന്തു കിട്ടിയവൻ വന്നു പറഞ്ഞു: യജമാനനേ, നീ വിതയ്ക്കാത്തിടത്തുനിന്നു കൊയ്യുകയും വിതറാത്തിടത്തുനിന്നു ശേഖരിക്കുകയും ചെയ്യുന്ന കഠിനമനുഷ്യനാണെന്ന് ഞാൻ മനസ്സിലാക്കി."},{"v":25,"t":"അതിനാൽ, ഞാൻ ഭയപ്പെട്ട് നിന്റെ താലന്ത് മണ്ണിൽ മറച്ചുവച്ചു. ഇതാ, നിന്റേത് എടുത്തുകൊള്ളുക."},{"v":26,"t":"അവന്റെ യജമാനൻ അവനോടു പറഞ്ഞു: ദുഷ്ടനും മടിയനുമായ ഭൃത്യാ, ഞാൻ വിതയ്ക്കാത്തിടത്തുനിന്നു കൊയ്യുന്നവനും വിതറാത്തിടത്തുനിന്നു ശേഖരിക്കുന്നവനും ആണെന്നു നീ മനസ്സിലാക്കിയിരുന്നല്ലോ."},{"v":27,"t":"അതിനാൽ, എന്റെ പണം നീ പണമിടപാടുകാരുടെ പക്കൽ നിക്ഷേപിക്കേണ്ടതായിരുന്നു. ഞാൻ വന്ന് എന്റെ പണം പലിശസഹിതം വാങ്ങുമായിരുന്നു."},{"v":28,"t":"ആ താലന്ത് അവനിൽ നിന്നെടുത്ത്, പത്തു താലന്തുള്ളവനു കൊടുക്കുക."},{"v":29,"t":"ഉള്ളവനു നല്കപ്പെടും; അവനു സമൃദ്ധിയുണ്ടാകുകയും ചെയ്യും. ഇല്ലാത്തവനിൽനിന്ന് ഉള്ളതുപോലും എടുക്കപ്പെടും."},{"v":30,"t":"പ്രയോജനമില്ലാത്ത ആ ഭൃത്യനെ പുറത്ത് അന്ധകാരത്തിലേക്കു തള്ളിക്കളയുക. അവിടെ കരച്ചിലും പല്ലുകടിയുമായിരിക്കും."},{"h":"അവസാനവിധി"},{"v":31,"t":"എല്ലാ ദൂതന്മാരോടുംകൂടെ, മനുഷ്യപുത്രൻ മഹത്ത്വത്തിൽ എഴുന്നള്ളുമ്പോൾ അവൻ തന്റെ മഹിമയുടെ സിംഹാസനത്തിൽ ഉപവിഷ്ടനാകും.","p":1},{"v":32,"t":"അവന്റെ മുമ്പിൽ എല്ലാ ജനതകളും ഒരുമിച്ചുകൂട്ടപ്പെടും. ഇടയൻ ചെമ്മരിയാടുകളെ കോലാടുകളിൽനിന്നു വേർതിരിക്കുന്നപോലെ അവൻ അവരെ തമ്മിൽ വേർതിരിക്കും."},{"v":33,"t":"അവൻ ചെമ്മരിയാടുകളെ തന്റെ വലത്തുവശത്തും കോലാടുകളെ ഇടത്തുവശത്തും നിറുത്തും."},{"v":34,"t":"അനന്തരം, രാജാവ് തന്റെ വലത്തു ഭാഗത്തുള്ളവരോട് അരുൾചെയ്യും: എന്റെ പിതാവാൽ അനുഗ്രഹിക്കപ്പെട്ടവരേ, വരുവിൻ; ലോകസ്ഥാപനം മുതൽ നിങ്ങൾക്കായി സജ്ജമാക്കിയിരിക്കുന്ന രാജ്യം അവകാശപ്പെടുത്തുവിൻ."},{"v":35,"t":"എന്തെന്നാൽ, എനിക്കു വിശന്നു, നിങ്ങൾ ഭക്ഷിക്കാൻ തന്നു. എനിക്കു ദാഹിച്ചു, നിങ്ങൾ കുടിക്കാൻ തന്നു. ഞാൻ പരദേശിയായിരുന്നു, നിങ്ങൾ എന്നെ സ്വീകരിച്ചു."},{"v":36,"t":"ഞാൻ നഗ്നനായിരുന്നു, നിങ്ങൾ എന്നെ ഉടുപ്പിച്ചു. ഞാൻ രോഗിയായിരുന്നു, നിങ്ങൾ എന്നെ സന്ദർശിച്ചു. ഞാൻ കാരാഗൃഹത്തിലായിരുന്നു, നിങ്ങൾ എന്റെയടുത്തു വന്നു."},{"v":37,"t":"അപ്പോൾ നീതിമാന്മാർ ഇങ്ങനെ മറുപടി പറയും: കർത്താവേ, നിന്നെ വിശക്കുന്നവനായിക്കണ്ട് ഞങ്ങൾ ഭക്ഷിക്കാൻ നല്കിയതും ദാഹിക്കുന്നവനായിക്കണ്ട് കുടിക്കാൻ നല്കിയതും എപ്പോൾ?"},{"v":38,"t":"നിന്നെ പരദേശിയായിക്കണ്ട് സ്വീകരിച്ചതും നഗ്നനായിക്കണ്ട് ഉടുപ്പിച്ചതും എപ്പോൾ?"},{"v":39,"t":"നിന്നെ ഞങ്ങൾ രോഗാവസ്ഥയിലോ കാരാഗൃഹത്തിലോ കണ്ട്, സന്ദർശിച്ചത് എപ്പോൾ?"},{"v":40,"t":"രാജാവ് മറുപടി പറയും: സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, എന്റെ ഏറ്റവും എളിയ ഈ സഹോദരന്മാരിൽ ഒരുവന് നിങ്ങൾ ഇതു ചെയ്തുകൊടുത്തപ്പോൾ എനിക്കുതന്നെയാണു ചെയ്തുതന്നത്."},{"v":41,"t":"അനന്തരം, അവൻ തന്റെ ഇടത്തുഭാഗത്തുള്ളവരോടു പറയും: ശപിക്കപ്പെട്ടവരേ, നിങ്ങൾ എന്നിൽനിന്നകന്ന് പിശാചിനും അവന്റെ ദൂതന്മാർക്കുമായി ഒരുക്കിയിരിക്കുന്ന നിത്യാഗ്നിയിലേക്കു പോകുവിൻ.","p":1},{"v":42,"t":"എനിക്കു വിശന്നു, നിങ്ങൾ ഭക്ഷിക്കാൻ തന്നില്ല. എനിക്കു ദാഹിച്ചു, നിങ്ങൾ കുടിക്കാൻ തന്നില്ല."},{"v":43,"t":"ഞാൻ പരദേശിയായിരുന്നു, നിങ്ങൾ എന്നെ സ്വീകരിച്ചില്ല. ഞാൻ നഗ്നനായിരുന്നു, നിങ്ങൾ എന്നെ ഉടുപ്പിച്ചില്ല. രോഗാവസ്ഥയിലും കാരാഗൃഹത്തിലും ആയിരുന്നു, നിങ്ങൾ എന്നെ സന്ദർശിച്ചില്ല."},{"v":44,"t":"അപ്പോൾ അവർ ചോദിക്കും: കർത്താവേ, ഞങ്ങൾ നിന്നെ വിശക്കുന്നവനോ ദാഹിക്കുന്നവനോ പരദേശിയോ നഗ്നനോ രോഗിയോ കാരാഗൃഹത്തിൽ കഴിയുന്നവനോ ആയി കണ്ടതും നിനക്കു ശുശ്രൂഷചെയ്യാതിരുന്നതും എപ്പോൾ?"},{"v":45,"t":"അവൻ മറുപടി പറയും: സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ഈ ഏറ്റവും എളിയവരിൽ ഒരുവന് നിങ്ങൾ ഇതു ചെയ്യാതിരുന്നപ്പോൾ എനിക്കുതന്നെയാണു ചെയ്യാതിരുന്നത്."},{"v":46,"t":"ഇവർ നിത്യശിക്ഷയിലേക്കും നീതിമാന്മാർ നിത്യജീവനിലേക്കും പ്രവേശിക്കും."}],"26":[{"h":"യേശുവിനെ വധിക്കാൻ ആലോചന"},{"v":1,"t":"അങ്ങനെ യേശു ഈ വചനങ്ങളെല്ലാം അവസാനിപ്പിച്ചപ്പോൾ തന്റെ ശിഷ്യന്മാരോടു പറഞ്ഞു:","p":1},{"v":2,"t":"രണ്ടുദിവസം കഴിഞ്ഞ് പെസഹായാണെന്നു നിങ്ങൾക്കറിയാമല്ലോ. മനുഷ്യപുത്രൻ ക്രൂശിക്കപ്പെടാനായി ഏല്പിക്കപ്പെടും."},{"v":3,"t":"പുരോഹിതപ്രമുഖന്മാരും ജനപ്രമാണികളും കയ്യാഫാസ് എന്നു പേരുള്ള പ്രധാനപുരോഹിതന്റെ കൊട്ടാരത്തിൽ സമ്മേളിച്ച്,"},{"v":4,"t":"യേശുവിനെ ചതിയിൽ പിടികൂടി വധിക്കേണ്ടതെങ്ങനെയെന്ന് കൂടിയാലോചിച്ചു."},{"v":5,"t":"അവർ പറഞ്ഞു: തിരുനാൾദിവസം വേണ്ടാ; ജനങ്ങൾ ബഹളമുണ്ടാക്കും."},{"h":"ബഥാനിയായിലെ തൈലാഭിഷേകം"},{"v":6,"t":"യേശു ബഥാനിയായിൽ കുഷ്ഠരോഗിയായ ശിമയോന്റെ ഭവനത്തിൽ ഇരിക്കുമ്പോൾ,","p":1},{"v":7,"t":"വിലയേറിയ സുഗന്ധതൈലം നിറച്ച ഒരു വെൺകല്പാത്രവുമായി ഒരു സ്ത്രീ അവനെ സമീപിച്ചു. അവൻ ഭക്ഷണത്തിനിരിക്കുമ്പോൾ അവൾ തൈലം അവന്റെ ശിരസ്സിൽ ഒഴിച്ചു."},{"v":8,"t":"ഇതുകണ്ട ശിഷ്യന്മാർ നീരസത്തോടെ പറഞ്ഞു: എന്തിന് ഈ പാഴ്ച്ചെലവ്?"},{"v":9,"t":"എന്തെന്നാൽ, ഇതു നല്ലവിലയ്ക്കു വിറ്റ് ദരിദ്രർക്കു കൊടുക്കാമായിരുന്നല്ലോ."},{"v":10,"t":"യേശു ഇതുഗ്രഹിച്ച് അവരോടു പറഞ്ഞു: എന്തിനു നിങ്ങൾ ഈ സ്ത്രീയെ വിഷമിപ്പിക്കുന്നു? ഇവൾ എനിക്കുവേണ്ടി ഒരു നല്ല കാര്യം ചെയ്തിരിക്കുന്നു."},{"v":11,"t":"കാരണം, ദരിദ്രർ എപ്പോഴും നിങ്ങളോടുകൂടെയുണ്ട്. ഞാനാകട്ടെ, എപ്പോഴും നിങ്ങളോടുകൂടെ ഉണ്ടായിരിക്കുകയില്ല."},{"v":12,"t":"അതിനാൽ, എന്നെ സംസ്കരിക്കുന്നതിനുള്ള ഒരുക്കമായാണ് ഇവൾ എന്റെ ശരീരത്തിൽ തൈലം പൂശിയത്."},{"v":13,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു: ലോകത്തിൽ എവിടെയെല്ലാം ഈ സദ്വാർത്ത പ്രഘോഷിക്കപ്പെടുമോ, അവിടെയെല്ലാം ഇവൾ ചെയ്തകാര്യവും ഇവളുടെ സ്മരണയ്ക്കായി പ്രസ്താവിക്കപ്പെടും."},{"h":"യൂദാസിന്റെ വഞ്ചന"},{"v":14,"t":"പന്ത്രണ്ടുപേരിൽ ഒരുവനായ യൂദാസ് സ്കറിയോത്താ പുരോഹിതപ്രമുഖന്മാരുടെ അടുത്തു ചെന്നു ചോദിച്ചു:","p":1},{"v":15,"t":"ഞാൻ അവനെ നിങ്ങൾക്ക് ഏല്പിച്ചു തന്നാൽ നിങ്ങൾ എനിക്ക് എന്തു തരും? അവർ മുപ്പതു വെള്ളിക്കാശിന് അവനുമായി കരാറുറപ്പിച്ചു."},{"v":16,"t":"അപ്പോൾമുതൽ അവൻ യേശുവിനെ ഒറ്റിക്കൊടുക്കാൻ അവസരം അന്വേഷിച്ചുകൊണ്ടിരുന്നു."},{"h":"പെസഹാ ആചരിക്കുന്നു"},{"v":17,"t":"പുളിപ്പില്ലാത്ത അപ്പത്തിന്റെ ഒന്നാം ദിവസം ശിഷ്യന്മാർ യേശുവിന്റെ അടുത്തുവന്നു ചോദിച്ചു: നിനക്കു പെസഹാ എവിടെ ഞങ്ങൾ ഒരുക്കണമെന്നാണ് നീ ആഗ്രഹിക്കുന്നത്?","p":1},{"v":18,"t":"അവൻ പറഞ്ഞു: നിങ്ങൾ പട്ടണത്തിൽ പോയി നിർദേശിക്കപ്പെട്ടയാളുടെ അടുത്തു ചെന്നു പറയുക: ഗുരു പറയുന്നു, എന്റെ സമയം അടുത്തിരിക്കുന്നു; ഞാൻ എന്റെ ശിഷ്യന്മാരോടുകൂടെ നിന്റെ അടുക്കലാണ് പെസഹാ ആചരിക്കുന്നത്."},{"v":19,"t":"യേശു നിർദേശിച്ചപോലെ ശിഷ്യന്മാർ പെസഹാ ഒരുക്കി."},{"v":20,"t":"വൈകുന്നേരമായപ്പോൾ അവൻ പന്ത്രണ്ടുപേരോടുമൊത്ത് ഭക്ഷണത്തിനിരുന്നു."},{"v":21,"t":"ഭക്ഷിച്ചുകൊണ്ടിരിക്കേ, അവൻ പറഞ്ഞു: സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, നിങ്ങളിൽ ഒരുവൻ എന്നെ ഒറ്റിക്കൊടുക്കും."},{"v":22,"t":"അവർ അതീവം ദുഃഖിതരായി, കർത്താവേ, അതു ഞാനല്ലല്ലോ എന്ന് ഓരോരുത്തരും അവനോടു ചോദിക്കാൻ തുടങ്ങി."},{"v":23,"t":"അവൻ പ്രതിവചിച്ചു: എന്നോടുകൂടെ പാത്രത്തിൽ കൈമുക്കുന്നവൻതന്നെ എന്നെ ഒറ്റിക്കൊടുക്കും."},{"v":24,"t":"മനുഷ്യപുത്രൻ, അവനെക്കുറിച്ച് എഴുതപ്പെട്ടിരിക്കുന്നപോലെ കടന്നുപോകുന്നു. എന്നാൽ, മനുഷ്യപുത്രനെ ആര് ഒറ്റിക്കൊടുക്കുന്നുവോ, അവനു ദുരിതം! ആ മനുഷ്യൻ ജനിക്കാതിരുന്നെങ്കിൽ അവനു നന്നായിരുന്നു."},{"v":25,"t":"അവനെ ഒറ്റിക്കൊടുക്കാനിരുന്ന യൂദാസ് അവനോടു ചോദിച്ചു: ഗുരോ, അതു ഞാനല്ലല്ലോ? അവൻ പറഞ്ഞു: നീ പറഞ്ഞുകഴിഞ്ഞു."},{"h":"പുതിയ ഉടമ്പടി"},{"v":26,"t":"അവർ ഭക്ഷിച്ചുകൊണ്ടിരിക്കുമ്പോൾ യേശു അപ്പമെടുത്ത്, വാഴ്ത്തി, മുറിച്ച്, ശിഷ്യന്മാർക്കു കൊടുത്തുകൊണ്ട് അരുൾചെയ്തു: എടുത്തു ഭക്ഷിക്കുവിൻ; ഇത് എന്റെ ശരീരമാകുന്നു.","p":1},{"v":27,"t":"അനന്തരം, പാനപാത്രമെടുത്ത് കൃതജ്ഞതാസ്തോത്രം ചെയ്ത് അവർക്കു കൊടുത്തുകൊണ്ടു പറഞ്ഞു: എല്ലാവരും ഇതിൽനിന്നു പാനംചെയ്യുവിൻ."},{"v":28,"t":"എന്തെന്നാൽ, ഇതു പാപമോചനത്തിന് അനേകർക്കുവേണ്ടി ചിന്തപ്പെടുന്ന, ഉടമ്പടിയുടെ എന്റെ രക്തമാണ്."},{"v":29,"t":"ഞാൻ നിങ്ങളോടു പറയുന്നു, എന്റെ പിതാവിന്റെ രാജ്യത്തിൽ നിങ്ങളോടൊത്ത് പുതുതായി ഇതു പാനംചെയ്യുന്ന ദിവസംവരെ മുന്തിരിയുടെ ഈ ഫലത്തിൽ നിന്നു ഞാൻ വീണ്ടും കുടിക്കുകയില്ല."},{"v":30,"t":"സ്തോത്രഗീതം ആലപിച്ചശേഷം അവർ ഒലിവുമലയിലേക്കു പോയി."},{"h":"പത്രോസ് ഗുരുവിനെ നിഷേധിക്കും"},{"v":31,"t":"അപ്പോൾ, യേശു അവരോടു പറഞ്ഞു: ഈ രാത്രി നിങ്ങളെല്ലാവരും എന്നിൽ ഇടറും. എന്തെന്നാൽ, ഞാൻ ഇടയനെ അടിക്കും; ആട്ടിൻപറ്റം ചിതറിപ്പോകും എന്നെഴുതപ്പെട്ടിരിക്കുന്നു.","p":1},{"v":32,"t":"എന്നാൽ ഞാൻ ഉയിർപ്പിക്കപ്പെട്ടശേഷം നിങ്ങൾക്കുമുമ്പേ ഗലീലിയിലേക്കു പോകും."},{"v":33,"t":"അപ്പോൾ പത്രോസ് അവനോടു പറഞ്ഞു: എല്ലാവരും നിന്നിൽ ഇടറിയാലും ഞാൻ ഒരിക്കലും ഇടറുകയില്ല."},{"v":34,"t":"യേശു പറഞ്ഞു: സത്യമായി ഞാൻ നിന്നോടു പറയുന്നു, ഈ രാത്രി കോഴി കൂകുന്നതിനു മുമ്പ് നീ എന്നെ മൂന്നുപ്രാവശ്യം നിഷേധിച്ചു പറയും."},{"v":35,"t":"പത്രോസ് പറഞ്ഞു: നിന്നോടുകൂടെ മരിക്കേണ്ടി വന്നാൽപ്പോലും ഞാൻ നിന്നെ നിഷേധിച്ചു പറയുകയില്ല. ഇങ്ങനെതന്നെ ശിഷ്യന്മാരെല്ലാവരും പറഞ്ഞു."},{"h":"ഗത്സേമനിയിൽ പ്രാർഥിക്കുന്നു"},{"v":36,"t":"അനന്തരം, യേശു അവരോടൊത്ത് ഗത്സേമനി എന്ന സ്ഥലത്തെത്തി. അവൻ ശിഷ്യന്മാരോടു പറഞ്ഞു: ഞാൻ അവിടെപ്പോയി പ്രാർഥിക്കുവോളം നിങ്ങൾ ഇവിടെ ഇരിക്കുക.","p":1},{"v":37,"t":"അവൻ പത്രോസിനെയും സെബദിയുടെ ഇരുപുത്രന്മാരെയും കൂടെക്കൊണ്ടു പോയി, ദുഃഖിക്കാനും വ്യാകുലപ്പെടാനും തുടങ്ങി."},{"v":38,"t":"അവൻ അവരോടു പറഞ്ഞു: എന്റെ ആത്മാവ് തീവ്രദുഃഖത്താൽ മരണത്തോളം എത്തിയിരിക്കുന്നു. നിങ്ങൾ ഇവിടെ എന്നോടൊത്ത് ഉണർന്നിരിക്കുക."},{"v":39,"t":"അവൻ അല്പദൂരം മുന്നോട്ടു ചെന്ന് കമിഴ്ന്നുവീണു പ്രാർഥിച്ചു: എന്റെ പിതാവേ, സാധ്യമെങ്കിൽ ഈ പാനപാത്രം എന്നിൽനിന്നകന്നു പോകട്ടെ. എങ്കിലും ഞാൻ ഇച്ഛിക്കുന്നപോലെയല്ല, നീ ഇച്ഛിക്കുന്ന പോലെയാകട്ടെ."},{"v":40,"t":"അനന്തരം, അവൻ ശിഷ്യന്മാരുടെ അടുത്തേക്കുവന്നു. അപ്പോൾ അവർ ഉറങ്ങുന്നതു കണ്ടു. അവൻ പത്രോസിനോടു ചോദിച്ചു: എന്നോടുകൂടെ ഒരു മണിക്കൂർ ഉണർന്നിരിക്കാൻ നിങ്ങൾക്കു കഴിഞ്ഞില്ലേ?"},{"v":41,"t":"പ്രലോഭനത്തിൽ അകപ്പെടാതിരിക്കാൻ നിങ്ങൾ ഉണർന്നിരുന്നു പ്രാർഥിക്കുവിൻ; ആത്മാവു സന്നദ്ധം; ശരീരം ദുർബലം."},{"v":42,"t":"രണ്ടാം പ്രാവശ്യവും അവൻ പോയി പ്രാർഥിച്ചു: എന്റെ പിതാവേ, ഞാൻ കുടിക്കാതെ ഇത് കടന്നുപോകാൻ സാധ്യമല്ലെങ്കിൽ നിന്റെഹിതം ഭവിക്കട്ടെ."},{"v":43,"t":"അവൻ വീണ്ടും വന്നപ്പോൾ അവർ ഉറങ്ങുന്നതുകണ്ടു. അവരുടെ കണ്ണുകൾ നിദ്രാഭാരമുള്ളവയായിരുന്നു."},{"v":44,"t":"അവൻ മൂന്നാംപ്രാവശ്യവും അവരെവിട്ടുപോയി അതേ വാക്കുകൾ പറഞ്ഞു പ്രാർഥിച്ചു."},{"v":45,"t":"അനന്തരം, അവൻ ശിഷ്യന്മാരുടെ അടുത്തുവന്നു പറഞ്ഞു: നിങ്ങൾ ഇനിയും ഉറങ്ങി വിശ്രമിച്ചുകൊള്ളുക. ഇതാ, സമയം അടുത്തിരിക്കുന്നു. മനുഷ്യപുത്രൻ പാപികളുടെ കൈകളിൽ ഏല്പിക്കപ്പെടുന്നു."},{"v":46,"t":"എഴുന്നേല്ക്കുവിൻ, നമുക്കു പോകാം. എന്നെ ഒറ്റിക്കൊടുക്കുന്നവൻ അടുത്തെത്തിയിരിക്കുന്നു."},{"h":"യേശുവിനെ ഒറ്റിക്കൊടുക്കുന്നു"},{"v":47,"t":"അവൻ സംസാരിച്ചുകൊണ്ടിരിക്കുമ്പോൾത്തന്നെ പന്ത്രണ്ടുപേരിൽ ഒരുവനായ യൂദാസ് അവിടെയെത്തി. അവനോടുകൂടെ പുരോഹിതപ്രമുഖന്മാരുടെയും ജനപ്രമാണികളുടെയും അടുക്കൽനിന്ന് വാളുകളും വടികളുമായി വലിയ ഒരു ജനക്കൂട്ടവും വന്നിരുന്നു.","p":1},{"v":48,"t":"ഒറ്റുകാരൻ അവർക്ക് ഈ അടയാളം നല്കിയിരുന്നു: ഞാൻ ആരെ ചുംബിക്കുന്നുവോ അവൻ തന്നെ. അവനെ പിടിച്ചുകൊള്ളുക."},{"v":49,"t":"അവൻ പെട്ടെന്ന് യേശുവിന്റെ അടുത്തുചെന്ന്, ഗുരോ, സ്വസ്തി എന്നു പറഞ്ഞ് അവനെ ചുംബിച്ചു."},{"v":50,"t":"യേശു അവനോടു ചോദിച്ചു: സ്നേഹിതാ, നീ എന്തിനാണു വന്നത്? അപ്പോൾ അവർ മുന്നോട്ടുവന്ന് യേശുവിനെ പിടിച്ചു."},{"v":51,"t":"യേശുവിനോടുകൂടെ ഉണ്ടായിരുന്നവരിൽ ഒരുവൻ കൈനീട്ടി, വാൾ ഊരി പ്രധാനപുരോഹിതന്റെ സേവകനെ വെട്ടി, അവന്റെ ചെവി ഛേദിച്ചുകളഞ്ഞു."},{"v":52,"t":"യേശു അവനോടു പറഞ്ഞു: വാൾ ഉറയിലിടുക; എന്തെന്നാൽ, വാളെടുക്കുന്നവരെല്ലാം വാളാൽ നശിക്കും."},{"v":53,"t":"എനിക്ക് എന്റെ പിതാവിനോട് അപേക്ഷിക്കാൻ കഴിയുകയില്ലെന്നും ഉടൻതന്നെ അവിടന്ന് എനിക്ക് തന്റെ ദൂതന്മാരുടെ പന്ത്രണ്ടിലേറെ വ്യൂഹങ്ങൾ അയച്ചു തരുകയില്ലെന്നും നീ വിചാരിക്കുന്നുവോ?"},{"v":54,"t":"അങ്ങനെയെങ്കിൽ, ഇപ്രകാരം സംഭവിക്കണമെന്ന വിശുദ്ധലിഖിതങ്ങൾ എങ്ങനെ നിറവേറും?"},{"v":55,"t":"ആ സമയത്ത് യേശു ജനക്കൂട്ടത്തോടു പറഞ്ഞു: കവർച്ചക്കാരനെതിരേ എന്നപോലെ വാളുകളും വടികളുമായി നിങ്ങൾ എന്നെ ബന്ധിക്കാൻ വന്നിരിക്കുന്നുവോ? ഞാൻ ദിവസവും ദേവാലയത്തിലിരുന്നു നിങ്ങളെ പഠിപ്പിച്ചിരുന്നു; നിങ്ങൾ എന്നെ പിടിച്ചില്ല."},{"v":56,"t":"പ്രവാചകന്മാരുടെ ലിഖിതങ്ങൾ പൂർത്തിയാകാൻ വേണ്ടിയാണ് ഇതൊക്കെയും സംഭവിച്ചത്. അപ്പോൾ ശിഷ്യന്മാരെല്ലാവരും അവനെ ഉപേക്ഷിച്ച് ഓടിപ്പോയി."},{"h":"ന്യായാധിപസംഘത്തിനു മുമ്പിൽ"},{"v":57,"t":"യേശുവിനെ പിടിച്ചുബന്ധിച്ചവർ പ്രധാനപുരോഹിതനായ കയ്യാഫാസിന്റെ അടുത്തേക്ക് അവനെ കൊണ്ടുപോയി. അവിടെ നിയമജ്ഞരും ശ്രേഷ്ഠന്മാരും സമ്മേളിച്ചിരുന്നു.","p":1},{"v":58,"t":"പ്രധാനപുരോഹിതന്റെ അകത്തളംവരെ പത്രോസ് അവനെ അല്പം ദൂരെയായി അനുഗമിച്ചു. അനന്തരം, അവൻ അകത്തുകടന്ന് അവസാനം എന്തെന്നു കാണാൻ പരിചാരകന്മാരുടെകൂടെ ഇരുന്നു."},{"v":59,"t":"പുരോഹിതപ്രമുഖന്മാരും ന്യായാധിപസംഘം മുഴുവനും യേശുവിനെ മരണത്തിനേല്പിച്ചു കൊടുക്കേണ്ടതിന് അവനെതിരേ കള്ളസാക്ഷ്യം അന്വേഷിച്ചുകൊണ്ടിരുന്നു."},{"v":60,"t":"അനേകം കള്ളസാക്ഷികൾ വന്നെങ്കിലും അവർക്കു സാക്ഷ്യമൊന്നും കിട്ടിയില്ല. അവസാനം, രണ്ടുപേർ മുന്നോട്ടുവന്നു പറഞ്ഞു:"},{"v":61,"t":"ഈ ദേവാലയം നശിപ്പിക്കാനും മൂന്നുദിവസംകൊണ്ടു നിർമിക്കാനും എനിക്കു സാധിക്കും എന്ന് ഇവൻ പറഞ്ഞിട്ടുണ്ട്."},{"v":62,"t":"പ്രധാനപുരോഹിതൻ എഴുന്നേറ്റു നിന്ന് അവനോടു ചോദിച്ചു: നീ ഒരു മറുപടിയും പറയുന്നില്ലേ? ഇവർ നിനക്കെതിരേ സാക്ഷ്യപ്പെടുത്തുന്നതെന്ത്?"},{"v":63,"t":"യേശുവാകട്ടെ, നിശ്ശബ്ദനായിരുന്നു. അപ്പോൾ പ്രധാനപുരോഹിതൻ അവനോടു പറഞ്ഞു: ജീവിക്കുന്ന ദൈവത്തെക്കൊണ്ട് ആണയിട്ടു ഞാൻ നിന്നോടു ചോദിക്കുന്നു, നീ ദൈവപുത്രനായ ക്രിസ്തുവാണോ എന്നു ഞങ്ങളോടു പറയുക."},{"v":64,"t":"യേശു അവനോടു പറഞ്ഞു: നീ പറഞ്ഞുവല്ലോ; എന്നാൽ, ഞാൻ നിന്നോടു പറയുന്നു, ഇപ്പോൾ മുതൽ മനുഷ്യപുത്രൻ ശക്തിയുടെ വലത്തുഭാഗത്ത് ഉപവിഷ്ടനായിരിക്കുന്നതും വാനമേഘങ്ങളിൽ വരുന്നതും നിങ്ങൾ കാണും."},{"v":65,"t":"അപ്പോൾ പ്രധാനപുരോഹിതൻ മേലങ്കി കീറിക്കൊണ്ടു പറഞ്ഞു: ഇവൻ ദൈവദൂഷണം പറഞ്ഞിരിക്കുന്നു. ഇനി സാക്ഷികളെക്കൊണ്ടു നമുക്കെന്താവശ്യം? ഇതാ, ദൈവദൂഷണം നിങ്ങൾ ഇപ്പോൾ കേട്ടുവല്ലോ!"},{"v":66,"t":"നിങ്ങൾക്കെന്തു തോന്നുന്നു? അവർ പ്രതിവചിച്ചു: അവൻ മരണാർഹനാണ്."},{"v":67,"t":"അനന്തരം, അവർ അവന്റെ മുഖത്തു തുപ്പുകയും അവനെ അടിക്കുകയും ചെയ്തു."},{"v":68,"t":"ക്രിസ്തുവേ, നിന്നെ അടിച്ചതാരെന്നു ഞങ്ങളോടു പ്രവചിക്കുക എന്നു പറഞ്ഞുകൊണ്ട് അവർ അവന്റെ കരണത്തടിച്ചു."},{"h":"പത്രോസ് യേശുവിനെ തള്ളിപ്പറയുന്നു"},{"v":69,"t":"പത്രോസ് പുറത്ത്, തളത്തിലിരിക്കുകയായിരുന്നു. ഒരു പരിചാരിക അവനെ സമീപിച്ച്, നീയും ആ ഗലീലിക്കാരനായ യേശുവിനോടുകൂടെയായിരുന്നല്ലോ എന്നുപറഞ്ഞു.","p":1},{"v":70,"t":"എന്നാൽ, നീ പറയുന്നതെന്താണെന്നു ഞാൻ അറിയുന്നില്ല എന്ന് അവരുടെയെല്ലാം മുമ്പാകേ അവൻ നിഷേധിച്ചുപറഞ്ഞു."},{"v":71,"t":"അവൻ കവാടത്തിലേക്കു പോയപ്പോൾ മറ്റൊരു പരിചാരിക അവനെക്കണ്ടു. അവൾ അടുത്തുനിന്നവരോടു പറഞ്ഞു: ഈ മനുഷ്യനും നസറായനായ യേശുവിന്റെ കൂടെയായിരുന്നു."},{"v":72,"t":"ഞാൻ ആ മനുഷ്യനെ അറിയുകയില്ല എന്ന് വീണ്ടും അവൻ ആണയിട്ടു നിഷേധിച്ചു."},{"v":73,"t":"കുറച്ചുകഴിഞ്ഞപ്പോൾ, അടുത്തുനിന്നിരുന്നവർ പത്രോസിനെ സമീപിച്ചു പറഞ്ഞു: നീ സത്യമായും അവരിൽ ഒരുവനാണ്; കാരണം, നിന്റെ ഉച്ചാരണരീതി അത് തെളിയിക്കുന്നു."},{"v":74,"t":"പത്രോസാകട്ടെ, ഞാൻ ആ മനുഷ്യനെ അറിയുകയില്ല എന്നു പറഞ്ഞ് ശപിക്കാനും ആണയിടാനും തുടങ്ങി. ഉടനെ കോഴികൂകി."},{"v":75,"t":"കോഴി കൂകുന്നതിനുമുമ്പ് മൂന്നുപ്രാവശ്യം നീ എന്നെ നിഷേധിക്കും എന്ന് യേശു പറഞ്ഞ വാക്കുകൾ അപ്പോൾ പത്രോസ് ഓർമിച്ചു. അവൻ പുറത്തുപോയി മനംനൊന്ത് കരഞ്ഞു."}],"27":[{"h":"യേശു പീലാത്തോസിന്റെ മുമ്പിൽ"},{"v":1,"t":"പ്രഭാതമായപ്പോൾ പുരോഹിതപ്രമുഖന്മാരും ജനപ്രമാണിമാരും യേശുവിനെ വധിക്കേണ്ടതിന് അവനെതിരേ കൂടിയാലോചന നടത്തി.","p":1},{"v":2,"t":"അവർ അവനെ ബന്ധിച്ചുകൊണ്ടുപോയി ദേശാധികാരിയായ പീലാത്തോസിനെ ഏല്പിച്ചു."},{"h":"യൂദാസിന്റെ അന്ത്യം"},{"v":3,"t":"അപ്പോൾ അവനെ ഒറ്റിക്കൊടുത്ത യൂദാസ്, അവൻ ശിക്ഷയ്ക്കുവിധിക്കപ്പെട്ടു എന്നറിഞ്ഞപ്പോൾ മനസ്സുമാറ്റി, ആ മുപ്പതുവെള്ളിനാണയങ്ങൾ പുരോഹിതപ്രമുഖന്മാരെയും പ്രമാണിമാരെയും തിരിച്ചേല്പിച്ചുകൊണ്ടു പറഞ്ഞു:","p":1},{"v":4,"t":"നിഷ്കളങ്കരക്തം ഒറ്റിക്കൊടുത്ത് ഞാൻ പാപം ചെയ്തിരിക്കുന്നു. അവർ അവനോടു പറഞ്ഞു: അതിനു ഞങ്ങൾക്കെന്ത്? അതു നിന്റെ കാര്യമാണ്."},{"v":5,"t":"വെള്ളിനാണയങ്ങൾ ദേവാലയത്തിലേക്കു വലിച്ചെറിഞ്ഞിട്ട് അവൻ തിരിച്ചുപോയി തൂങ്ങിമരിച്ചു."},{"v":6,"t":"പുരോഹിതപ്രമുഖന്മാർ ആ വെള്ളിനാണയങ്ങൾ എടുത്തുകൊണ്ടു പറഞ്ഞു: ഇതു രക്തത്തിന്റെ വിലയാകയാൽ ഭണ്ഡാരത്തിൽ നിക്ഷേപിക്കുന്നത് അനുവദനീയമല്ല."},{"v":7,"t":"അതുകൊണ്ട്, അവർ കൂടിയാലോചിച്ച്, ആ പണം കൊടുത്ത് പരദേശികളെ സംസ്കരിക്കാൻ കുശവന്റെ നിലംവാങ്ങി."},{"v":8,"t":"അത് ഇന്നും രക്തനിലം എന്ന് അറിയപ്പെടുന്നു."},{"v":9,"t":"പ്രവാചകനായ ജറെമിയാവഴി അരുൾചെയ്യപ്പെട്ടത് അപ്പോൾ പൂർത്തിയായി: അവന്റെ വിലയായി ഇസ്രായേൽ മക്കൾ നിശ്ചയിച്ച മുപ്പതുവെള്ളിനാണയങ്ങളെടുത്ത്,"},{"v":10,"t":"കർത്താവ് എന്നോടു കല്പിച്ചപോലെ, അവർ കുശവന്റെ നിലത്തിനായി കൊടുത്തു."},{"h":"വിചാരണയും വിധിയും"},{"v":11,"t":"അപ്പോൾ യേശു ദേശാധികാരിയുടെ മുമ്പിൽനിന്നു. ദേശാധികാരി അവനോടു ചോദിച്ചു: നീ യഹൂദരുടെ രാജാവാണോ? യേശു പറഞ്ഞു: നീ തന്നെ പറയുന്നുവല്ലോ.","p":1},{"v":12,"t":"പുരോഹിതപ്രമുഖന്മാരും പ്രമാണികളും അവനിൽ കുറ്റമാരോപിച്ചപ്പോൾ അവൻ ഒരു മറുപടിയും പറഞ്ഞില്ല."},{"v":13,"t":"അപ്പോൾ പീലാത്തോസ് വീണ്ടും ചോദിച്ചു: അവർ എന്തെല്ലാം കാര്യങ്ങൾ നിനക്കെതിരേ സാക്ഷ്യപ്പെടുത്തുന്നു എന്നു നീ കേൾക്കുന്നില്ലേ?"},{"v":14,"t":"എന്നാൽ, അവൻ ഒരു ആരോപണത്തിനും മറുപടി പറഞ്ഞില്ല. തത്ഫലമായി ദേശാധികാരി അത്യധികം ആശ്ചര്യപ്പെട്ടു."},{"v":15,"t":"ജനക്കൂട്ടം ആഗ്രഹിക്കുന്ന ഒരു തടവുകാരനെ ദേശാധികാരി അവർക്കു തിരുനാളിൽ വിട്ടുകൊടുക്കുക പതിവായിരുന്നു."},{"v":16,"t":"അന്ന് അവർക്ക് ബറാബ്ബാസ് എന്നുപേരുള്ള ഒരു കുപ്രസിദ്ധ തടവുപുള്ളിയുണ്ടായിരുന്നു."},{"v":17,"t":"അതുകൊണ്ട്, അവർ ഒരുമിച്ചു കൂടിയപ്പോൾ പീലാത്തോസ് അവരോടു ചോദിച്ചു: ഞാൻ ആരെ വിട്ടുതരണമെന്നാണ് നിങ്ങൾ ആഗ്രഹിക്കുന്നത്, ബറാബ്ബാസിനെയോ ക്രിസ്തു എന്നു വിളിക്കപ്പെടുന്ന യേശുവിനെയോ?"},{"v":18,"t":"എന്തെന്നാൽ, അസൂയനിമിത്തമാണ് അവർ അവനെ ഏല്പിച്ചുകൊടുത്തതെന്ന് അവൻ അറിഞ്ഞിരുന്നു."},{"v":19,"t":"മാത്രമല്ല, അവൻ ന്യായാസനത്തിൽ ഉപവിഷ്ടനായിരിക്കുമ്പോൾ അവന്റെ ഭാര്യ അവന്റെ അടുത്തേക്ക് ആളയച്ച് അറിയിച്ചു: ആ നീതിമാന്റെ കാര്യത്തിൽ ഇടപെടരുത്. എന്തെന്നാൽ, അവൻമൂലം സ്വപ്നത്തിൽ ഞാൻ ഇന്നു വളരെയേറെ ക്ലേശിച്ചു."},{"v":20,"t":"പുരോഹിതപ്രമുഖന്മാരും പ്രമാണിമാരും ബറാബ്ബാസിനെ വിട്ടുതരാനും യേശുവിനെ ഇല്ലാതാക്കാനും ആവശ്യപ്പെടാൻ ജനക്കൂട്ടത്തെ പ്രേരിപ്പിച്ചു."},{"v":21,"t":"ദേശാധികാരി വീണ്ടും അവരോടു ചോദിച്ചു: ഇവർ രണ്ടുപേരിൽ ആരെ വിട്ടുതരണമെന്നാണ് നിങ്ങൾ ആഗ്രഹിക്കുന്നത്? അവർ പറഞ്ഞു: ബറാബ്ബാസിനെ."},{"v":22,"t":"പീലാത്തോസ് അവരോടു ചോദിച്ചു: അപ്പോൾ, ക്രിസ്തു എന്നു വിളിക്കപ്പെടുന്ന യേശുവിനെ ഞാനെന്തു ചെയ്യണം? എല്ലാവരും പറഞ്ഞു: അവൻ ക്രൂശിക്കപ്പെടട്ടെ.","p":1},{"v":23,"t":"അവൻ അവരോടു ചോദിച്ചു: അവൻ എന്തു തിന്മയാണു ചെയ്തത്? അപ്പോൾ അവർ കൂടുതൽ ഉച്ചത്തിൽ വിളിച്ചുപറഞ്ഞു: അവൻ ക്രൂശിക്കപ്പെടട്ടെ."},{"v":24,"t":"ബഹളം വർധിക്കുന്നതല്ലാതെ പ്രയോജനമൊന്നും ഉണ്ടാകുന്നില്ലെന്നു മനസ്സിലാക്കിയ പീലാത്തോസ് വെള്ളമെടുത്ത് ജനക്കൂട്ടത്തിന്റെ മുമ്പിൽവച്ചു കൈകഴുകിക്കൊണ്ടു പറഞ്ഞു: ഈ മനുഷ്യന്റെ രക്തത്തിൽ ഞാൻ നിർദോഷിയാണ്; ബാക്കി നിങ്ങളുടെ കാര്യം."},{"v":25,"t":"അപ്പോൾ ജനംമുഴുവൻ വിളിച്ചുപറഞ്ഞു: അവന്റെ രക്തം ഞങ്ങളുടെമേലും ഞങ്ങളുടെ സന്തതികളുടെമേലും ആയിക്കൊള്ളട്ടെ!"},{"v":26,"t":"അപ്പോൾ അവൻ ബറാബ്ബാസിനെ അവർക്കു വിട്ടുകൊടുക്കുകയും യേശുവിനെ ചമ്മട്ടികൊണ്ടടിപ്പിച്ച് ക്രൂശിക്കാൻ ഏല്പിച്ചുകൊടുക്കുകയും ചെയ്തു."},{"h":"യേശുവിനെ പരിഹസിക്കുന്നു"},{"v":27,"t":"അനന്തരം, ദേശാധികാരിയുടെ പടയാളികൾ പ്രത്തോറിയത്തിലേക്ക് യേശുവിനെ കൊണ്ടുപോയി. ഒരു സൈന്യവിഭാഗം മുഴുവൻ അവനുചുറ്റും ഒരുമിച്ചു കൂടി.","p":1},{"v":28,"t":"അവർ അവന്റെ വസ്ത്രം ഉരിഞ്ഞുമാറ്റി ഒരു ചെമന്നമേലങ്കി പുതപ്പിച്ചു."},{"v":29,"t":"ഒരു മുൾക്കിരീടം മെടഞ്ഞ് അവന്റെ ശിരസ്സിൽവച്ചു. വലത്തുകൈയിൽ ഒരു ഞാങ്ങണയും കൊടുത്തു. അവന്റെ മുമ്പിൽ മുട്ടുകുത്തിക്കൊണ്ട്, യഹൂദരുടെ രാജാവേ, സ്വസ്തി എന്നുപറഞ്ഞ് അവർ അവനെ പരിഹസിച്ചു."},{"v":30,"t":"അവർ അവന്റെമേൽ തുപ്പുകയും ഞാങ്ങണ എടുത്ത് അവന്റെ ശിരസ്സിലടിക്കുകയും ചെയ്തു."},{"v":31,"t":"അവനെ പരിഹസിച്ചശേഷം മേലങ്കി എടുത്തുമാറ്റി, അവന്റെ വസ്ത്രം വീണ്ടും ധരിപ്പിച്ച് കുരിശിൽ തറയ്ക്കാൻ കൊണ്ടുപോയി."},{"h":"യേശുവിനെ കുരിശിൽ തറയ്ക്കുന്നു"},{"v":32,"t":"അവർ പോകുന്ന വഴി ശിമയോൻ എന്ന ഒരു സൈറീൻകാരനെ കണ്ടുമുട്ടി. യേശുവിന്റെ കുരിശു ചുമക്കാൻ അവർ ഇവനെ നിർബന്ധിച്ചു.","p":1},{"v":33,"t":"തലയോടിടം എന്നർത്ഥമുള്ള ഗോൽഗോഥായിലെത്തിയപ്പോൾ,"},{"v":34,"t":"അവർ അവന് കയ്പു കലർത്തിയ വീഞ്ഞ് കുടിക്കാൻ കൊടുത്തു. അവൻ അതു രുചിച്ചു നോക്കിയെങ്കിലും കുടിക്കാൻ ഇഷ്ടപ്പെട്ടില്ല."},{"v":35,"t":"അവനെ കുരിശിൽ തറച്ചശേഷം അവർ അവന്റെ വസ്ത്രങ്ങൾ കുറിയിട്ടു ഭാഗിച്ചെടുത്തു."},{"v":36,"t":"അനന്തരം, അവർ അവിടെ അവനു കാവലിരുന്നു."},{"v":37,"t":"ഇവൻ യഹൂദരുടെ രാജാവായ യേശുവാണ് എന്ന അവന്റെ കുറ്റപത്രം അവർ അവന്റെ ശിരസ്സിനു മുകളിൽ എഴുതിവച്ചു."},{"v":38,"t":"അവനോടുകൂടെ രണ്ടു കള്ളന്മാരെയും അവർ കുരിശിൽത്തറച്ചു, ഒരുവനെ വലത്തും അപരനെ ഇടത്തും."},{"v":39,"t":"അതിലേ കടന്നുപോയവർ തലകുലുക്കിക്കൊണ്ട് അവനെ ദുഷിച്ചു പറഞ്ഞു:"},{"v":40,"t":"ദേവാലയം നശിപ്പിച്ച് മൂന്നു ദിവസം കൊണ്ട് അതു പണിയുന്നവനേ, നിന്നെത്തന്നെ രക്ഷിക്കുക; നീ ദൈവപുത്രനാണെങ്കിൽ കുരിശിൽ നിന്നിറങ്ങിവരുക."},{"v":41,"t":"അപ്രകാരംതന്നെ പുരോഹിതപ്രമുഖന്മാർ നിയമജ്ഞരോടും ശ്രേഷ്ഠരോടുമൊത്ത് അവനെ പരിഹസിച്ചു കൊണ്ടു പറഞ്ഞു:"},{"v":42,"t":"ഇവൻ, മറ്റുള്ളവരെ രക്ഷിച്ചു; തന്നെത്തന്നെ രക്ഷിക്കാൻ ഇവനു സാധിക്കുന്നില്ല. ഇവൻ ഇസ്രായേലിന്റെ രാജാവാണല്ലോ, ഇപ്പോൾ കുരിശിൽ നിന്നിറങ്ങിവരട്ടെ. ഞങ്ങൾ ഇവനിൽ വിശ്വസിക്കാം."},{"v":43,"t":"ഇവൻ ദൈവത്തിലാശ്രയിച്ചു. ദൈവത്തിന് വേണമെങ്കിൽ, ഇപ്പോൾ ഇവനെ രക്ഷിക്കട്ടെ. ഞാൻ ദൈവപുത്രനാണ് എന്നാണല്ലോ ഇവൻ പറഞ്ഞിരുന്നത്."},{"v":44,"t":"അവനോടൊപ്പം ക്രൂശിക്കപ്പെട്ട കള്ളന്മാരും ഇപ്രകാരംതന്നെ അവനെ പരിഹസിച്ചു."},{"h":"യേശുവിന്റെ മരണം"},{"v":45,"t":"ആറാംമണിക്കൂർ മുതൽ ഒമ്പതാംമണിക്കൂർ വരെ ഭൂമിയിലെങ്ങും അന്ധകാരംവ്യാപിച്ചു.","p":1},{"v":46,"t":"ഏകദേശം ഒമ്പതാം മണിക്കൂറായപ്പോൾ യേശു ഉച്ചത്തിൽ നിലവിളിച്ചു: ഏലീ, ഏലീ, ല്മാ സബക്ഥാനി! അതായത്, എന്റെ ദൈവമേ, എന്റെ ദൈവമേ, എന്തുകൊണ്ട് നീ എന്നെ ഉപേക്ഷിച്ചു!"},{"v":47,"t":"അടുത്തുനിന്നിരുന്നവരിൽ ചിലർ ഇതുകേട്ടു പറഞ്ഞു: അവൻ ഏലിയായെ വിളിക്കുന്നു."},{"v":48,"t":"ഉടനെ അവരിലൊരാൾ ഓടിച്ചെന്ന് നീർപ്പഞ്ഞിയെടുത്ത് ചവർപ്പുള്ള വീഞ്ഞിൽ മുക്കി, ഒരു ഞാങ്ങണമേൽ ചുറ്റി അവനു കുടിക്കാൻ കൊടുത്തു."},{"v":49,"t":"അപ്പോൾ മറ്റുള്ളവർ പറഞ്ഞു: നില്ക്കൂ, ഏലിയാ വന്ന് അവനെ രക്ഷിക്കുമോ എന്നു നമുക്കു കാണാം."},{"v":50,"t":"യേശു ഉച്ചത്തിൽ നിലവിളിച്ചുകൊണ്ടു പ്രാണൻ വെടിഞ്ഞു."},{"v":51,"t":"അപ്പോൾ ദേവാലയത്തിലെ തിരശ്ശീല മുകൾ മുതൽ അടിവരെ രണ്ടായി കീറി; ഭൂമി കുലുങ്ങി; പാറകൾ പിളർന്നു;"},{"v":52,"t":"ശവകുടീരങ്ങൾ തുറക്കപ്പെടുകയും നിദ്രപ്രാപിച്ച അനേകം വിശുദ്ധരുടെ ശരീരങ്ങൾ ഉയിർപ്പിക്കപ്പെടുകയും ചെയ്തു."},{"v":53,"t":"അവന്റെ ഉത്ഥാനത്തിനുശേഷം അവർ ശവകുടീരങ്ങളിൽ നിന്നു പുറത്തുവന്ന് വിശുദ്ധനഗരത്തിൽ പ്രവേശിച്ച് പലർക്കും പ്രത്യക്ഷപ്പെട്ടു."},{"v":54,"t":"യേശുവിനു കാവൽ നിന്നിരുന്ന ശതാധിപനും അവന്റെകൂടെ ഉണ്ടായിരുന്നവരും ഭൂകമ്പവും മറ്റു സംഭവങ്ങളും കണ്ട് അത്യധികം ഭയപ്പെട്ടു പറഞ്ഞു: സത്യമായും ഇവൻ ദൈവപുത്രനായിരുന്നു."},{"v":55,"t":"ഗലീലിയിൽനിന്ന് യേശുവിനെ അനുഗമിച്ചവരും അവനു ശുശ്രൂഷ ചെയ്തിരുന്നവരുമായ അനേകം സ്ത്രീകൾ അകലെ ഇക്കാര്യങ്ങൾ നോക്കിക്കൊണ്ടു നിന്നിരുന്നു."},{"v":56,"t":"അക്കൂട്ടത്തിൽ മഗ്ദലേനമറിയവും യാക്കോബിന്റെയും ജോസഫിന്റെയും അമ്മയായ മറിയവും സെബദിപുത്രന്മാരുടെ അമ്മയും ഉണ്ടായിരുന്നു."},{"h":"യേശുവിനെ സംസ്കരിക്കുന്നു"},{"v":57,"t":"വൈകുന്നേരമായപ്പോൾ അരിമത്തെയാക്കാരൻ ജോസഫ് എന്ന ധനികൻ അവിടെയെത്തി. അവനും യേശുവിനു ശിഷ്യപ്പെട്ടിരുന്നു.","p":1},{"v":58,"t":"അവൻ പീലാത്തോസിന്റെ അടുത്തുചെന്ന് യേശുവിന്റെ ശരീരം ആവശ്യപ്പെട്ടു. അത് അവനു വിട്ടുകൊടുക്കാൻ പീലാത്തോസ് കല്പിച്ചു."},{"v":59,"t":"ജോസഫ് ശരീരമെടുത്ത് വൃത്തിയുള്ള ഒരു തുണിയിൽ പൊതിഞ്ഞ്,"},{"v":60,"t":"പാറയിൽ വെട്ടിയുണ്ടാക്കിയ തന്റെ പുതിയ കല്ലറയിൽ സംസ്കരിച്ചു. കല്ലറയുടെ വാതില്ക്കൽ ഒരു വലിയ കല്ലുരുട്ടിവച്ചിട്ട് അവൻ പോയി."},{"v":61,"t":"മഗ്ദലേനമറിയവും മറ്റേ മറിയവും ശവകുടീരത്തിനഭിമുഖമായി അവിടെ ഇരിക്കുന്നുണ്ടായിരുന്നു."},{"h":"കല്ലറയ്ക്കു കാവൽ"},{"v":62,"t":"പിറ്റേദിവസം, അതായത്, ഒരുക്കദിനത്തിനുശേഷം, പുരോഹിതപ്രമുഖന്മാരും ഫരിസേയരും പീലാത്തോസിന്റെ അടുക്കൽ ഒരുമിച്ചുകൂടി.","p":1},{"v":63,"t":"അവർ പറഞ്ഞു: യജമാനനേ, മൂന്നുദിവസം കഴിഞ്ഞ് ഞാൻ ഉയിർത്തെഴുന്നേല്ക്കുമെന്ന് ആ വഞ്ചകൻ ജീവിച്ചിരുന്നപ്പോൾ പറഞ്ഞത് ഞങ്ങൾ ഇപ്പോൾ ഓർമിക്കുന്നു."},{"v":64,"t":"അതിനാൽ, മൂന്നാംദിവസംവരെ ശവകുടീരത്തിനു കാവലേർപ്പെടുത്താൻ ആജ്ഞാപിക്കുക. അല്ലെങ്കിൽ അവന്റെ ശിഷ്യന്മാർവന്ന് അവനെ മോഷ്ടിക്കുകയും അവൻ മരിച്ചവരിൽനിന്ന് ഉത്ഥാനം ചെയ്തു എന്ന് ജനങ്ങളോടുപറയുകയും ചെയ്തെന്നുവരും. അങ്ങനെ അവസാനത്തെ ചതി ആദ്യത്തേതിനെക്കാൾ ദോഷകരമായിത്തീരുകയും ചെയ്യും."},{"v":65,"t":"പീലാത്തോസ് അവരോടു പറഞ്ഞു: നിങ്ങൾക്ക് ഒരു കാവൽ സേനയുണ്ടല്ലോ; നിങ്ങൾ പോയി ആവുംവിധം ഭദ്രമാക്കുവിൻ."},{"v":66,"t":"അവർ പോയി കല്ലിനു മുദ്രവച്ച്, കാവല്ക്കാരിലൂടെ കല്ലറ ഭദ്രമാക്കി."}],"28":[{"h":"ഉത്ഥാനം"},{"v":1,"t":"സാബത്തിനുശേഷം ആഴ്ചയുടെ ഒന്നാം ദിവസം പുലരുമ്പോഴേക്കും മഗ്ദലേനമറിയവും മറ്റേ മറിയവും ശവകുടീരം സന്ദർശിക്കാൻ വന്നു.","p":1},{"v":2,"t":"അപ്പോൾ വലിയ ഒരു ഭൂകമ്പമുണ്ടായി. കർത്താവിന്റെ ദൂതൻ സ്വർഗത്തിൽ നിന്നിറങ്ങിവന്ന്, കല്ലുരുട്ടിമാറ്റി, അതിൻമേൽ ഇരുന്നു."},{"v":3,"t":"അവന്റെ രൂപം മിന്നൽപ്പിണർപോലെ ആയിരുന്നു; വസ്ത്രം മഞ്ഞുപോലെ വെളുത്തതും."},{"v":4,"t":"അവനെക്കുറിച്ചുള്ള ഭയം നിമിത്തം കാവല്ക്കാർ വിറപൂണ്ട് മരിച്ചവരെപ്പോലെയായി."},{"v":5,"t":"ദൂതൻ സ്ത്രീകളോടു പറഞ്ഞു: നിങ്ങൾ ഭയപ്പെടേണ്ടാ; ക്രൂശിക്കപ്പെട്ട യേശുവിനെയാണ് നിങ്ങൾ അന്വേഷിക്കുന്നതെന്ന് എനിക്കറിയാം."},{"v":6,"t":"അവൻ ഇവിടെയില്ല; താൻ അരുൾചെയ്തപോലെ, അവൻ ഉയിർപ്പിക്കപ്പെട്ടു. അവൻ കിടന്ന സ്ഥലം വന്നു കാണുവിൻ."},{"v":7,"t":"വേഗം പോയി അവന്റെ ശിഷ്യന്മാരോട്, അവൻ മരിച്ചവരുടെയിടയിൽനിന്ന് ഉയിർപ്പിക്കപ്പെട്ടെന്നും നിങ്ങൾക്കുമുമ്പേ ഗലീലിയിലേക്കു പോകുന്നെന്നും അവിടെവച്ച് നിങ്ങൾ അവനെ കാണുമെന്നും പറയുവിൻ. ഇതാ, ഞാൻ നിങ്ങളോടു പറഞ്ഞിരിക്കുന്നു."},{"v":8,"t":"അവർ വേഗം കല്ലറവിട്ട് ഭയത്തോടും വലിയ സന്തോഷത്തോടുംകൂടെ അവന്റെ ശിഷ്യന്മാരെ വിവരമറിയിക്കാൻ ഓടി."},{"v":9,"t":"അപ്പോൾ യേശു അവർക്ക് എതിരേവന്ന് നിങ്ങൾക്ക് അഭിവാദനങ്ങൾ എന്നു പറഞ്ഞു. അവർ അവനെ സമീപിച്ച് പാദങ്ങളിൽ കെട്ടിപ്പിടിച്ച് ആരാധിച്ചു."},{"v":10,"t":"അപ്പോൾ യേശു അവരോടു പറഞ്ഞു: ഭയപ്പെടേണ്ടാ; നിങ്ങൾ ചെന്ന് എന്റെ സഹോദരന്മാരോട് ഗലീലിയിലേക്കു പോകണമെന്നും അവിടെ അവർ എന്നെ കാണുമെന്നും പറയുക."},{"h":"കാവല്ക്കാരുടെ വ്യാജപ്രസ്താവം"},{"v":11,"t":"അവർ പോയപ്പോൾ കാവല്ക്കാരിൽ ചിലർ പട്ടണത്തിൽ ചെന്ന് സംഭവിച്ചതെല്ലാം പുരോഹിതപ്രമുഖന്മാരെ അറിയിച്ചു.","p":1},{"v":12,"t":"അവരും പ്രമാണിമാരും കൂടിയാലോചിച്ചശേഷം പടയാളികൾക്കു വേണ്ടത്ര പണം കൊടുത്തിട്ടു പറഞ്ഞു:"},{"v":13,"t":"ഞങ്ങൾ ഉറങ്ങിയപ്പോൾ രാത്രി അവന്റെ ശിഷ്യന്മാർ വന്ന് അവനെ മോഷ്ടിച്ചുകൊണ്ടുപോയി എന്നു പറയുവിൻ."},{"v":14,"t":"ദേശാധികാരിയുടെ ചെവിയിലെത്തിയാൽ, ഞങ്ങൾ അവനെ സ്വാധീനിച്ച് നിങ്ങൾക്ക് ഉപദ്രവമുണ്ടാകാതെ നോക്കിക്കൊള്ളാം."},{"v":15,"t":"അവർ പണം വാങ്ങി, നിർദേശമനുസരിച്ചു പ്രവർത്തിച്ചു. ഈ കഥ ഇന്നും യഹൂദരുടെ ഇടയിൽ പ്രചാരത്തിലിരിക്കുന്നു."},{"h":"പ്രേഷിതദൗത്യം"},{"v":16,"t":"അനന്തരം, യേശു നിർദേശിച്ചപോലെ, പതിനൊന്നു ശിഷ്യന്മാരും ഗലീലിയിലെ മലയിലേക്കു പോയി.","p":1},{"v":17,"t":"അവനെക്കണ്ടപ്പോൾ അവർ അവനെ ആരാധിച്ചു; ചിലരാകട്ടെ, സംശയിച്ചു."},{"v":18,"t":"യേശു അവരെ സമീപിച്ച് അരുൾചെയ്തു: സ്വർഗത്തിലും ഭൂമിയിലുമുള്ള എല്ലാ അധികാരവും എനിക്കു നല്കപ്പെട്ടിരിക്കുന്നു."},{"v":19,"t":"ആകയാൽ, നിങ്ങൾ പോയി എല്ലാ ജനതകളെയും ശിഷ്യപ്പെടുത്തുവിൻ. പിതാവിന്റെയും പുത്രന്റെയും പരിശുദ്ധാത്മാവിന്റെയും നാമത്തിൽ അവരെ സ്നാനപ്പെടുത്തുവിൻ."},{"v":20,"t":"ഞാൻ നിങ്ങളോടു കല്പിച്ചവയെല്ലാം പാലിക്കാൻ അവരെ പഠിപ്പിക്കുവിൻ. ഇതാ, യുഗാന്തംവരെ എല്ലായ്പോഴും ഞാൻ നിങ്ങളോടുകൂടെ ഉണ്ടായിരിക്കും."}]}},{"id":"MRK","name":"മർക്കോസ്","chapters":{"1":[{"h":"സ്നാപകന്റെ പ്രഭാഷണം"},{"v":1,"t":"ദൈവപുത്രനായ യേശുക്രിസ്തുവിന്റെ സുവിശേഷത്തിന്റെ ആരംഭം.","p":1},{"v":2,"t":"ഏശയ്യാപ്രവാചകന്റെ ഗ്രന്ഥത്തിൽ എഴുതപ്പെട്ടിരിക്കുന്നപോലെ, ഇതാ, നിനക്കു മുമ്പേ ഞാൻ എന്റെ ദൂതനെ അയയ്ക്കുന്നു. അവൻ നിന്റെ വഴി ഒരുക്കും."},{"v":3,"t":"മരുഭൂമിയിൽ വിളിച്ചുപറയുന്നവന്റെ ശബ്ദം: കർത്താവിന്റെ വഴി ഒരുക്കുവിൻ. അവന്റെ പാതകൾ നേരേയാക്കുവിൻ."},{"v":4,"t":"പാപമോചനത്തിനുള്ള മാനസാന്തരത്തിന്റെ സ്നാനം പ്രഘോഷിച്ചുകൊണ്ട് സ്നാപകയോഹന്നാൻ മരുഭൂമിയിൽ പ്രത്യക്ഷനായി."},{"v":5,"t":"യൂദയാപ്രദേശം മുഴുവനും ജറുസലേം നിവാസികളെല്ലാവരും അവന്റെ അടുത്തേക്കു പോയി. അവർ പാപങ്ങൾ ഏറ്റുപറഞ്ഞ് ജോർദാൻനദിയിൽവച്ച് അവനിൽനിന്ന് സ്നാനം സ്വീകരിച്ചു."},{"v":6,"t":"ഒട്ടകരോമംകൊണ്ടുള്ള വസ്ത്രമാണു യോഹന്നാൻ ധരിച്ചിരുന്നത്; അവന്റെ അരയിൽ തോല്പട്ടയും. വെട്ടുക്കിളിയും കാട്ടുതേനുമാണ് അവൻ ഭക്ഷിച്ചിരുന്നത്."},{"v":7,"t":"അവൻ ഇപ്രകാരം പ്രഘോഷിച്ചു: എന്നെക്കാൾ ശക്തനായവൻ എന്റെ പിന്നാലെ വരുന്നു. കുനിഞ്ഞ് അവന്റെ ചെരിപ്പിന്റെ വള്ളിയഴിക്കാൻപോലും ഞാൻ യോഗ്യനല്ല."},{"v":8,"t":"ഞാൻ നിങ്ങളെ ജലംകൊണ്ട് സ്നാനപ്പെടുത്തി; അവനോ, പരിശുദ്ധാത്മാവാൽ നിങ്ങളെ സ്നാനപ്പെടുത്തും."},{"h":"യേശുവിന്റെ ജ്ഞാനസ്നാനം"},{"v":9,"t":"അന്നാളുകളിൽ, യേശു ഗലീലിയിലെ നസറത്തിൽനിന്നുവന്ന്, ജോർദാനിൽവച്ച് യോഹന്നാനിൽനിന്നു സ്നാനം സ്വീകരിച്ചു.","p":1},{"v":10,"t":"വെള്ളത്തിൽനിന്നു കയറിയ ഉടനേ, ആകാശം പിളരുന്നതും ആത്മാവ് പ്രാവിന്റെ രൂപത്തിൽ തന്റെമേൽ ഇറങ്ങിവരുന്നതും അവൻ കണ്ടു."},{"v":11,"t":"സ്വർഗത്തിൽനിന്ന് ഒരു സ്വരമുണ്ടായി: നീ എന്റെ പ്രിയപുത്രൻ; നിന്നിൽ ഞാൻ പ്രസാദിച്ചിരിക്കുന്നു."},{"h":"മരുഭൂമിയിലെ പ്രലോഭനം"},{"v":12,"t":"ഉടനെ ആത്മാവ് അവനെ മരുഭൂമിയിലേക്കു കൊണ്ടുപോയി.","p":1},{"v":13,"t":"സാത്താനാൽ പരീക്ഷിക്കപ്പെട്ട് നാല്പതു ദിവസം അവൻ മരുഭൂമിയിൽ ആയിരുന്നു. അവൻ വന്യമൃഗങ്ങളോടുകൂടെയായിരുന്നു. ദൈവദൂതന്മാർ അവനെ ശുശ്രൂഷിച്ചു."},{"h":"ദൗത്യമാരംഭിക്കുന്നു"},{"v":14,"t":"യോഹന്നാൻ ബന്ധനസ്ഥനായശേഷം യേശു ദൈവത്തിന്റെ സുവിശേഷം പ്രഘോഷിച്ചുകൊണ്ട് ഗലീലിയിലേക്കു വന്നു.","p":1},{"v":15,"t":"അവൻ പറഞ്ഞു: സമയം പൂർത്തിയായി, ദൈവരാജ്യം സമീപിച്ചിരിക്കുന്നു. മാനസാന്തരപ്പെടുവിൻ; സുവിശേഷത്തിൽ വിശ്വസിക്കുവിൻ."},{"h":"ആദ്യശിഷ്യന്മാർ"},{"v":16,"t":"അവൻ ഗലീലിക്കടൽത്തീരത്തുകൂടെ കടന്നുപോകുമ്പോൾ, കടലിൽ വലയെറിഞ്ഞുകൊണ്ടിരുന്ന ശിമയോനെയും അവന്റെ സഹോദരൻ അന്ത്രയോസിനെയും കണ്ടു. എന്തെന്നാൽ, അവർ മീൻപിടിത്തക്കാരായിരുന്നു.","p":1},{"v":17,"t":"യേശു അവരോടു പറഞ്ഞു: എന്റെ പിന്നാലെ വരുക; ഞാൻ നിങ്ങളെ മനുഷ്യരെ പിടിക്കുന്നവരാക്കും."},{"v":18,"t":"ഉടനെ വലയുപേക്ഷിച്ച് അവർ അവനെ അനുഗമിച്ചു."},{"v":19,"t":"കുറച്ചുകൂടി മുന്നോട്ടു പോയപ്പോൾ സെബദിയുടെ പുത്രനായ യാക്കോബിനെയും അവന്റെ സഹോദരൻ യോഹന്നാനെയും കണ്ടു. അവർ വഞ്ചിയിലിരുന്ന് വലയുടെ കേടുപോക്കുകയായിരുന്നു."},{"v":20,"t":"ഉടനെ അവൻ അവരെയും വിളിച്ചു. തങ്ങളുടെ പിതാവായ സെബദിയെ സേവകരോടൊപ്പം വഞ്ചിയിൽവിട്ട് അവർ അവനെ അനുഗമിച്ചു."},{"h":"പിശാചുബാധിതനെ സുഖപ്പെടുത്തുന്നു"},{"v":21,"t":"അവർ കഫർണാമിലെത്തി. സാബത്തിൽ അവൻ സിനഗോഗിൽ പ്രവേശിച്ചു പഠിപ്പിച്ചു.","p":1},{"v":22,"t":"അവന്റെ പ്രബോധനത്തിൽ അവർ വിസ്മയഭരിതരായി. കാരണം, നിയമജ്ഞരെപ്പോലെയല്ല, അധികാരമുള്ളവനെപ്പോലെയാണ് അവൻ പഠിപ്പിച്ചത്."},{"v":23,"t":"അശുദ്ധാത്മാവു ബാധിച്ച ഒരു മനുഷ്യൻ അവരുടെ സിനഗോഗിൽ ഉണ്ടായിരുന്നു. അവൻ അലറി:"},{"v":24,"t":"നസറായനായ യേശുവേ, ഞങ്ങൾക്കും നിനക്കുമെന്ത്? ഞങ്ങളെ നശിപ്പിക്കാനാണോ നീ വന്നിരിക്കുന്നത്? നീ ആരാണെന്ന് എനിക്കറിയാം - ദൈവത്തിന്റെ പരിശുദ്ധൻ."},{"v":25,"t":"യേശു അവനെ ശാസിച്ചു: നിശ്ശബ്ദനായിരിക്കുക; അവനെ വിട്ടു നീ പുറത്തുവരുക."},{"v":26,"t":"അശുദ്ധാത്മാവ് അവനെ കോച്ചിവലിച്ച് ഉച്ചത്തിൽ അലറിക്കൊണ്ട് പുറത്തുവന്നു."},{"v":27,"t":"എല്ലാവരും അദ്ഭുതപ്പെട്ടു പരസ്പരം പറഞ്ഞു: ഇതെന്ത്? അധികാരത്തോടെയുള്ള പുതിയ പ്രബോധനം! അശുദ്ധാത്മാക്കളോടുപോലും അവൻ ആജ്ഞാപിക്കുന്നു; അവ അവനെ അനുസരിക്കുകയും ചെയ്യുന്നു!"},{"v":28,"t":"അവന്റെ പ്രശസ്തി ഉടനെ ഗലീലിയുടെ സമീപപ്രദേശങ്ങളിലെല്ലാം വ്യാപിച്ചു."},{"h":"ശിമയോന്റെ അമ്മായിയമ്മയെ സുഖപ്പെടുത്തുന്നു"},{"v":29,"t":"യേശു സിനഗോഗിൽനിന്നിറങ്ങി യാക്കോബിനോടും യോഹന്നാനോടുംകൂടെ ശിമയോന്റെയും അന്ത്രയോസിന്റെയും ഭവനത്തിലെത്തി.","p":1},{"v":30,"t":"ശിമയോന്റെ അമ്മായിയമ്മ പനിപിടിച്ചു കിടപ്പായിരുന്നു. അവളെക്കുറിച്ച് ഉടനെ അവർ അവനോടു പറഞ്ഞു."},{"v":31,"t":"അവൻ അടുത്തുചെന്ന് അവളെ കൈക്കുപിടിച്ച് എഴുന്നേല്പിച്ചു. പനി അവളെ വിട്ടുമാറി. അവൾ അവരെ ശുശ്രൂഷിച്ചു."},{"v":32,"t":"വൈകുന്നേരം സൂര്യാസ്തമയമായപ്പോൾ, രോഗികളും പിശാചുബാധിതരുമായ എല്ലാവരെയും അവർ അവന്റെ അടുത്തു കൊണ്ടുവന്നു."},{"v":33,"t":"നഗരം മുഴുവൻ വാതില്ക്കൽ ഒത്തുകൂടി."},{"v":34,"t":"വിവിധ രോഗങ്ങൾ ബാധിച്ചിരുന്ന ഏറെപ്പേരെ അവൻ സുഖപ്പെടുത്തി. അനേകം പിശാചുക്കളെ പുറത്താക്കി. പിശാചുക്കൾ തന്നെ അറിഞ്ഞിരുന്നതുകൊണ്ട്, സംസാരിക്കാൻ അവയെ അവൻ അനുവദിച്ചില്ല."},{"h":"സിനഗോഗുകളിൽ പ്രസംഗിക്കുന്നു"},{"v":35,"t":"അതിരാവിലെ അവൻ എഴുന്നേറ്റ് പുറത്തിറങ്ങി, ഒരു വിജനസ്ഥലത്തേക്കു പോയി. അവിടെ അവൻ പ്രാർഥിച്ചുകൊണ്ടിരുന്നു.","p":1},{"v":36,"t":"ശിമയോനും കൂടെയുണ്ടായിരുന്നവരും അവനെ തേടിച്ചെന്നു."},{"v":37,"t":"അവനെ കണ്ടെത്തിയപ്പോൾ അവർ അവനോടു പറഞ്ഞു: എല്ലാവരും നിന്നെ അന്വേഷിക്കുന്നു."},{"v":38,"t":"അവൻ അവരോടു പറഞ്ഞു: നമുക്ക് അടുത്ത പട്ടണങ്ങളിലേക്കു പോകാം. അവിടെയും എനിക്കു പ്രഘോഷിക്കാനുണ്ട്. ഇതിനാണു ഞാൻ വന്നത്."},{"v":39,"t":"അവരുടെ സിനഗോഗുകളിൽ പ്രഘോഷിച്ചുകൊണ്ടും പിശാചുക്കളെ പുറത്താക്കിക്കൊണ്ടും അവൻ ഗലീലിമുഴുവൻ സഞ്ചരിച്ചു."},{"h":"കുഷ്ഠരോഗിയെ സുഖപ്പെടുത്തുന്നു"},{"v":40,"t":"ഒരു കുഷ്ഠരോഗി അവന്റെ അടുത്തെത്തി മുട്ടുകുത്തി അപേക്ഷിച്ചു: അങ്ങേക്കു മനസ്സുണ്ടെങ്കിൽ എന്നെ ശുദ്ധനാക്കാൻ കഴിയും.","p":1},{"v":41,"t":"അവൻ മനസ്സലിഞ്ഞ് കൈനീട്ടി അവനെ സ്പർശിച്ചുകൊണ്ടു പറഞ്ഞു: എനിക്കു മനസ്സുണ്ട്; നീ ശുദ്ധനാക്കപ്പെടട്ടെ."},{"v":42,"t":"ഉടനെ അവനിൽനിന്ന് കുഷ്ഠം മാറി; അവൻ ശുദ്ധനാക്കപ്പെട്ടു."},{"v":43,"t":"യേശു അവനെ താക്കീതുനല്കി പറഞ്ഞയച്ചു:"},{"v":44,"t":"നീ ഇതെപ്പറ്റി ആരോടും ഒന്നും സംസാരിക്കരുത്. എന്നാൽ പോയി, പുരോഹിതനു നിന്നെത്തന്നെ കാണിച്ചുകൊടുക്കുക. അവർക്കു സാക്ഷ്യത്തിനായി, നിന്റെ ശുദ്ധീകരണത്തിന് മോശ കല്പിച്ച കാഴ്ചകൾ അർപ്പിക്കുകയും ചെയ്യുക."},{"v":45,"t":"എന്നാൽ, അവൻ പുറത്തുചെന്ന് ഏറെക്കാര്യങ്ങൾ പ്രഘോഷിക്കാനും ഇത് പറഞ്ഞുപരത്താനും തുടങ്ങി. തന്മൂലം, പിന്നീട് പട്ടണത്തിൽ പരസ്യമായി പ്രവേശിക്കാൻ യേശുവിനു സാധിച്ചില്ല. അവൻ പുറത്ത് വിജനപ്രദേശങ്ങളിൽ തങ്ങി. ആളുകളാകട്ടെ, എല്ലായിടങ്ങളിലുംനിന്ന് അവന്റെ അടുത്തു വന്നുകൊണ്ടിരുന്നു."}],"2":[{"h":"തളർവാതരോഗിയെ സുഖപ്പെടുത്തുന്നു"},{"v":1,"t":"കുറെദിവസങ്ങൾ കഴിഞ്ഞ്, യേശു കഫർണാമിൽ വീണ്ടും എത്തിയപ്പോൾ, അവൻ വീട്ടിലുണ്ടെന്ന ശ്രുതിപരന്നു.","p":1},{"v":2,"t":"വാതില്ക്കൽപ്പോലും നില്ക്കാൻ സ്ഥലം തികയാത്തവിധം നിരവധിയാളുകൾ അവിടെക്കൂടി. അവൻ അവരോടു വചനം പ്രസംഗിച്ചുകൊണ്ടിരുന്നു."},{"v":3,"t":"അപ്പോൾ, നാലുപേർ ഒരു തളർവാതരോഗിയെ എടുത്ത് അവന്റെ പക്കലേക്കു കൊണ്ടുവന്നു."},{"v":4,"t":"എന്നാൽ ജനക്കൂട്ടം നിമിത്തം അവന്റെ അടുത്തെത്താൻ കഴിയാതെ, അവൻ ഇരുന്ന സ്ഥലത്തിന്റെ മേൽക്കൂര പൊളിച്ച്, തളർവാതരോഗിയെ അവർ കിടക്കയോടെ താഴോട്ടിറക്കി."},{"v":5,"t":"അവരുടെ വിശ്വാസം കണ്ട് യേശു തളർവാതരോഗിയോടു പറഞ്ഞു: മകനേ, നിന്റെ പാപങ്ങൾ മോചിക്കപ്പെട്ടിരിക്കുന്നു."},{"v":6,"t":"നിയമജ്ഞരിൽ ചിലർ അവിടെ ഇരിക്കുന്നുണ്ടായിരുന്നു. അവർ തങ്ങളുടെ ഹൃദയത്തിൽ ചിന്തിച്ചുകൊണ്ടിരുന്നു:"},{"v":7,"t":"എന്തുകൊണ്ടാണ് ഇവൻ ഇപ്രകാരം സംസാരിക്കുന്നത്? ഇവൻ ദൈവദൂഷണം പറയുന്നു. ദൈവം ഒരുവനല്ലാതെ മറ്റാർക്കാണ് പാപംമോചിക്കാൻ സാധിക്കുക?"},{"v":8,"t":"അവർ ഇപ്രകാരം ചിന്തിക്കുന്നെന്നു മനസ്സിലാക്കി പെട്ടെന്ന് യേശു അവരോടു ചോദിച്ചു: എന്തുകൊണ്ടാണു നിങ്ങൾ ഇക്കാര്യങ്ങൾ നിങ്ങളുടെ ഹൃദയത്തിൽ ചിന്തിക്കുന്നത്?"},{"v":9,"t":"ഏതാണ് എളുപ്പം? തളർവാതരോഗിയോട് നിന്റെ പാപങ്ങൾ മോചിപ്പിക്കപ്പെട്ടിരിക്കുന്നു എന്നു പറയുന്നതോ എഴുന്നേറ്റ് നിന്റെ കിടക്കയെടുത്തു നടക്കുക എന്നു പറയുന്നതോ?"},{"v":10,"t":"എന്നാൽ, ഭൂമിയിൽ പാപങ്ങൾ മോചിക്കാൻ മനുഷ്യപുത്രന് അധികാരമുണ്ടെന്നു നിങ്ങൾ അറിയേണ്ടതിന് -"},{"v":11,"t":"അവൻ തളർവാതരോഗിയോടു പറഞ്ഞു: ഞാൻ നിന്നോടു പറയുന്നു, എഴുന്നേല്ക്കുക. നിന്റെ കിടക്കയെടുത്ത്, വീട്ടിലേക്കു പോകുക."},{"v":12,"t":"അവൻ എഴുന്നേറ്റ്, ഉടനെ കിടക്കയെടുത്ത്, എല്ലാവരും കാൺകേ പുറത്തേക്കുപോയി. എല്ലാവരും ആശ്ചര്യപ്പെട്ടു. ഇതുപോലൊന്ന് ഞങ്ങൾ ഒരിക്കലും കണ്ടിട്ടില്ല എന്നു പറഞ്ഞ് അവർ ദൈവത്തെ മഹത്ത്വപ്പെടുത്തി."},{"h":"ലേവിയെ വിളിക്കുന്നു"},{"v":13,"t":"അവൻ വീണ്ടും കടൽത്തീരത്തേക്കുപോയി. ജനക്കൂട്ടം മുഴുവൻ അവന്റെ അടുത്തേക്കു വന്നു. അവൻ അവരെ പഠിപ്പിച്ചുകൊണ്ടിരുന്നു.","p":1},{"v":14,"t":"അവൻ കടന്നുപോയപ്പോൾ ഹൽപൈയുടെ പുത്രനായ ലേവി ചുങ്കസ്ഥലത്ത് ഇരിക്കുന്നതുകണ്ട് അവനോടു പറഞ്ഞു: എന്നെ അനുഗമിക്കുക. അവൻ എഴുന്നേറ്റ് യേശുവിനെ അനുഗമിച്ചു."},{"v":15,"t":"അവൻ അവന്റെ ഭവനത്തിൽ ഭക്ഷണത്തിനിരിക്കുമ്പോൾ അനേകം ചുങ്കക്കാരും പാപികളും അവന്റെയും ശിഷ്യന്മാരുടെയും കൂടെ ഇരുന്നു. കാരണം, അവനെ അനുഗമിച്ചവർ നിരവധിയായിരുന്നു."},{"v":16,"t":"അവൻ പാപികളോടും ചുങ്കക്കാരോടുമൊപ്പം ഭക്ഷണം കഴിക്കുന്നതുകണ്ട് ഫരിസേയരിൽപ്പെട്ട ചില നിയമജ്ഞർ അവന്റെ ശിഷ്യന്മാരോടു ചോദിച്ചു: അവൻ ചുങ്കക്കാരുടെയും പാപികളുടെയും കൂടെ ഭക്ഷിക്കുന്നതെന്ത്?"},{"v":17,"t":"ഇതു കേട്ട് യേശു അവരോടു പറഞ്ഞു: വൈദ്യനെക്കൊണ്ടാവശ്യം ആരോഗ്യമുള്ളവർക്കല്ല; പ്രത്യുത, രോഗികൾക്കാണ്. ഞാൻ വന്നത് നീതിമാന്മാരെയല്ല, പാപികളെ വിളിക്കാനാണ്."},{"h":"ഉപവാസം സംബന്ധിച്ചുതർക്കം"},{"v":18,"t":"യോഹന്നാന്റെ ശിഷ്യന്മാരും ഫരിസേയരും ഉപവസിക്കുകയായിരുന്നു. ആളുകൾ വന്ന് യേശുവിനോടു ചോദിച്ചു: യോഹന്നാന്റെയും ഫരിസേയരുടെയും ശിഷ്യന്മാർ ഉപവസിക്കുകയും നിന്റെ ശിഷ്യന്മാർ ഉപവസിക്കാതിരിക്കുകയും ചെയ്യുന്നത് എന്തുകൊണ്ട്?","p":1},{"v":19,"t":"യേശു അവരോടു പറഞ്ഞു: മണവാളൻ കൂടെയുള്ളപ്പോൾ വിവാഹാതിഥികൾക്ക് ഉപവസിക്കാൻ സാധിക്കുമോ? മണവാളൻ കൂടെയുള്ളിടത്തോളംകാലം അവർക്ക് ഉപവസിക്കാനാകില്ല."},{"v":20,"t":"മണവാളൻ അവരിൽനിന്ന് അകറ്റപ്പെടുന്ന നാളുകൾ വരും; ആ നാളിൽ അവർ ഉപവസിക്കും."},{"v":21,"t":"ആരും പഴയവസ്ത്രത്തിൽ പുതിയ കഷണം തുന്നിപ്പിടിപ്പിക്കാറില്ല. അങ്ങനെ ചെയ്താൽ തുന്നിപ്പിടിപ്പിച്ചത്, പഴയതിൽനിന്നു കീറിപ്പോരുകയും കീറൽ കൂടുതൽ വലുതാകുകയും ചെയ്യും."},{"v":22,"t":"ആരും പുതിയ വീഞ്ഞ് പഴയ തോല്ക്കുടങ്ങളിൽ ഒഴിച്ചുവയ്ക്കാറില്ല. അങ്ങനെ ചെയ്താൽ വീഞ്ഞ് തോല്ക്കുടങ്ങൾ പിളർക്കുകയും വീഞ്ഞും തോല്ക്കുടങ്ങളും നഷ്ടപ്പെടുകയും ചെയ്യും. പുതിയ വീഞ്ഞാകട്ടെ, പുതിയ തോല്ക്കുടങ്ങളിലാണു വേണ്ടത്."},{"h":"സാബത്താചരണത്തെക്കുറിച്ചു വിവാദം"},{"v":23,"t":"ഒരു സാബത്തിൽ അവൻ, വിളഞ്ഞുകിടക്കുന്ന ഒരു വയലിലൂടെ പോകുകയായിരുന്നു. പോകുമ്പോൾ, ശിഷ്യന്മാർ കതിരുകൾ പറിക്കാൻ തുടങ്ങി.","p":1},{"v":24,"t":"ഫരിസേയർ അവനോടു പറഞ്ഞു: സാബത്തിൽ നിഷിദ്ധമായത് അവർ ചെയ്യുന്നത് എന്തുകൊണ്ട്?"},{"v":25,"t":"അവൻ ചോദിച്ചു: ദാവീദും അനുചരന്മാരും ഒന്നുമില്ലാതെ വിശന്നുവലഞ്ഞപ്പോൾ എന്തുചെയ്തുവെന്ന് നിങ്ങൾ ഒരിക്കലും വായിച്ചിട്ടില്ലേ?"},{"v":26,"t":"അബിയാഥർ പ്രധാന പുരോഹിതനായിരിക്കേ ദാവീദ് ദൈവഭവനത്തിൽ പ്രവേശിച്ച്, പുരോഹിതന്മാർക്കല്ലാതെ മറ്റാർക്കും ഭക്ഷിക്കാൻ അനുവാദമില്ലാത്ത കാഴ്ചയപ്പം ഭക്ഷിക്കുകയും കൂടെയുണ്ടായിരുന്നവർക്കു കൊടുക്കുകയും ചെയ്തില്ലേ?"},{"v":27,"t":"അവൻ അവരോടു പറഞ്ഞു: സാബത്ത് മനുഷ്യനുവേണ്ടിയാണ്; മനുഷ്യൻ സാബത്തിനുവേണ്ടിയല്ല."},{"v":28,"t":"അതിനാൽ, മനുഷ്യപുത്രൻ സാബത്തിന്റെയും കർത്താവാണ്."}],"3":[{"h":"സാബത്തിൽ രോഗശാന്തി"},{"v":1,"t":"യേശു വീണ്ടും സിനഗോഗിൽ പ്രവേശിച്ചു. കൈ ശോഷിച്ച ഒരു മനുഷ്യൻ അവിടെയുണ്ടായിരുന്നു.","p":1},{"v":2,"t":"യേശുവിൽ കുറ്റമാരോപിക്കാൻ, സാബത്തിൽ അവൻ രോഗശാന്തി നല്കുമോ എന്നറിയാൻ, അവർ ഉറ്റുനോക്കിക്കൊണ്ടിരുന്നു."},{"v":3,"t":"കൈശോഷിച്ചവനോട് അവൻ പറഞ്ഞു: എഴുന്നേറ്റ് നടുക്കുനില്ക്കുക."},{"v":4,"t":"അനന്തരം, അവൻ അവരോടു ചോദിച്ചു: സാബത്തിൽ നന്മ ചെയ്യുന്നതോ തിന്മ ചെയ്യുന്നതോ ജീവൻ രക്ഷിക്കുന്നതോ നശിപ്പിക്കുന്നതോ ഏതാണ് അനുവദനീയം? അവർ നിശ്ശബ്ദരായിരുന്നു."},{"v":5,"t":"അവരുടെ ഹൃദയകാഠിന്യത്തിൽ ദുഃഖിച്ച്, അവരെ ക്രോധത്തോടെ നോക്കിക്കൊണ്ട്, യേശു അവനോടു പറഞ്ഞു: കൈനീട്ടുക. അവൻ നീട്ടി; അവന്റെ കൈ സുഖമാക്കപ്പെട്ടു."},{"v":6,"t":"ഫരിസേയർ ഉടനെ പുറത്തേക്കിറങ്ങി, യേശുവിനെ നശിപ്പിക്കേണ്ടതെങ്ങനെയെന്ന് ഹേറോദേസ് പക്ഷക്കാരുമായി കൂടിയാലോചന നടത്തി."},{"h":"കടൽത്തീരത്തെ അദ്ഭുതങ്ങൾ"},{"v":7,"t":"യേശു തന്റെ ശിഷ്യന്മാരോടുകൂടെ കടൽത്തീരത്തേക്കു പോയി. ഗലീലിയിൽനിന്ന് ഒരു വലിയ സംഘം അവനെ അനുഗമിച്ചു.","p":1},{"v":8,"t":"യൂദയാ, ജറുസലേം, ഇദുമെയാ എന്നിവിടങ്ങളിൽനിന്നും ജോർദാന്റെ മറുകരെനിന്നും ടയിർ, സിദോൻ എന്നിവയുടെ പരിസരങ്ങളിൽനിന്നും വലിയസംഘം, അവൻ ചെയ്തതെല്ലാം കേട്ട്, അവന്റെ അടുത്തെത്തി."},{"v":9,"t":"ജനക്കൂട്ടം തന്നെ ഞെരുക്കാതിരിക്കാൻ, ഒരു വള്ളം ഒരുക്കിനിറുത്താൻ ശിഷ്യന്മാരോട് അവൻ ആവശ്യപ്പെട്ടു."},{"v":10,"t":"എന്തെന്നാൽ, അവൻ അനേകരെ സുഖപ്പെടുത്തിയതുമൂലം, അവനെ സ്പർശിക്കാൻ, രോഗമുണ്ടായിരുന്നവരെല്ലാം തിക്കിത്തിരക്കിക്കൊണ്ടിരുന്നു."},{"v":11,"t":"അശുദ്ധാത്മാക്കൾ അവനെക്കണ്ടപ്പോഴൊക്കെ അവന്റെ മുമ്പിൽ വീണ്, നീ ദൈവപുത്രനാണ് എന്നു വിളിച്ചുപറഞ്ഞു."},{"v":12,"t":"തന്നെ വെളിപ്പെടുത്തരുതെന്ന് അവൻ അവയെ കർശനമായി ശാസിച്ചു."},{"h":"അപ്പസ്തോലന്മാരെ തിരഞ്ഞെടുക്കുന്നു"},{"v":13,"t":"പിന്നെ, അവൻ മലയിലേക്കു കയറി തനിക്ക് ഇഷ്ടമുള്ളവരെ അടുത്തേക്കു വിളിച്ചു. അവർ അവന്റെ സമീപത്തേക്കു ചെന്നു.","p":1},{"v":14,"t":"അവൻ പന്ത്രണ്ടുപേരെ - അവരെയാണ് അപ്പസ്തോലന്മാർ എന്നും അവൻ വിളിച്ചത് - തന്നോടുകൂടെ ആയിരിക്കുന്നതിനും പ്രഘോഷിക്കാൻ അയയ്ക്കുന്നതിനും"},{"v":15,"t":"പിശാചുക്കളെ ബഹിഷ്കരിക്കാൻ അധികാരം ഉണ്ടായിരിക്കുന്നതിനുമായി നിയോഗിച്ചു."},{"v":16,"t":"അവർ, പത്രോസ് എന്ന് അവൻ പേരുനല്കിയ ശിമയോൻ,","p":1},{"v":17,"t":"ബൊവനെർഗെസ് - ഇടിമുഴക്കത്തിന്റെ പുത്രന്മാർ - എന്ന് പേരുനല്കിയ സെബദിപുത്രന്മാരായ യാക്കോബും സഹോദരൻ യോഹന്നാനും"},{"v":18,"t":"അന്ത്രയോസ്, പീലിപ്പോസ്, ബർത്തലോമിയോ, മത്തായി, തോമസ്, ഹൽപൈയുടെ പുത്രൻ യാക്കോബ്, തദ്ദേവൂസ്, കാനാൻകാരനായ ശിമയോൻ,"},{"v":19,"t":"അവനെ ഒറ്റിക്കൊടുത്ത യൂദാസ് സ്കറിയോത്താ."},{"h":"യേശുവും ബേൽസെബൂലും"},{"v":20,"t":"അനന്തരം, അവൻ സ്വഭവനത്തിലേക്കു വന്നു. ജനങ്ങൾ വീണ്ടും വന്നുകൂടിക്കൊണ്ടിരുന്നു. തന്മൂലം, ഭക്ഷണം കഴിക്കാൻപോലും അവർക്കു സാധിച്ചില്ല.","p":1},{"v":21,"t":"അവന്റെ സ്വന്തക്കാർ ഇതുകേട്ട്, അവനെ പിടിച്ചുകൊണ്ടുപോകാൻ പുറപ്പെട്ടു. കാരണം, അവനു സുബോധം നഷ്ടപ്പെട്ടിരിക്കുന്നെന്ന് അവർ പറഞ്ഞിരുന്നു."},{"v":22,"t":"ജറുസലേമിൽനിന്നു വന്ന നിയമജ്ഞർ പറഞ്ഞു: അവനെ ബേൽസെബൂൽ ആവേശിച്ചിരിക്കുന്നു. പിശാചുക്കളുടെ തലവനെക്കൊണ്ടാണ് അവൻ പിശാചുക്കളെ ബഹിഷ്കരിക്കുന്നത്."},{"v":23,"t":"അവൻ അവരെ അടുത്തു വിളിച്ച്, ഉപമകൾവഴി അവരോടു പറഞ്ഞു: സാത്താന് എങ്ങനെയാണ് സാത്താനെ പുറത്താക്കാൻ കഴിയുക?"},{"v":24,"t":"അന്തശ്ഛിദ്രമുള്ള രാജ്യം നിലനില്ക്കുക സാധ്യമല്ല."},{"v":25,"t":"അന്തശ്ഛിദ്രമുള്ള ഭവനവും നിലനില്ക്കുക സാധ്യമല്ല."},{"v":26,"t":"തനിക്കുതന്നെ എതിരായി നില്ക്കുകയും ഭിന്നിക്കുകയും ചെയ്താൽ സാത്താനു നിലനില്ക്കുക സാധ്യമല്ല. മറിച്ച്, അത് അവന്റെ അവസാനമായിരിക്കും."},{"v":27,"t":"ശക്തനായ ഒരുവന്റെ ഭവനത്തിൽ പ്രവേശിച്ച് അവന്റെ വസ്തുക്കൾ കവർച്ചചെയ്യണമെങ്കിൽ, ആദ്യം അവനെ ബന്ധിക്കണം. അനന്തരം അവന്റെ വീട് കവർച്ച ചെയ്യാം."},{"v":28,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു: മനുഷ്യമക്കളുടെ എല്ലാ പാപങ്ങളും അവർ പറയുന്ന ദൂഷണങ്ങളും മോചിപ്പിക്കപ്പെടും."},{"v":29,"t":"എന്നാൽ, പരിശുദ്ധാത്മാവിനെതിരായി ദൂഷണം പറയുന്നവന് ഒരുകാലത്തും മോചനമില്ല. അവൻ നിത്യപാപത്തിന് ഉത്തരവാദിയാകും."},{"v":30,"t":"എന്തെന്നാൽ, അവന് അശുദ്ധാത്മാവുണ്ടെന്ന് അവർ പറഞ്ഞിരുന്നു."},{"h":"യേശുവിന്റെ അമ്മയും സഹോദരരും"},{"v":31,"t":"അവന്റെ അമ്മയും സഹോദരന്മാരും വന്നു; അവർ പുറത്തുനിന്നുകൊണ്ട് അവനെ വിളിക്കാൻ ആളയച്ചു.","p":1},{"v":32,"t":"ജനക്കൂട്ടം അവനുചുറ്റും ഇരിക്കുകയായിരുന്നു. അവർ പറഞ്ഞു: നിന്റെ അമ്മയും സഹോദരന്മാരും സഹോദരിമാരും പുറത്ത് നിന്നെ അന്വേഷിക്കുന്നു."},{"v":33,"t":"അവൻ ചോദിച്ചു: ആരാണ് എന്റെ അമ്മയും സഹോദരങ്ങളും?"},{"v":34,"t":"ചുറ്റും ഇരിക്കുന്നവരെ നോക്കിക്കൊണ്ട് അവൻ പറഞ്ഞു: ഇതാ, എന്റെ അമ്മയും എന്റെ സഹോദരങ്ങളും!"},{"v":35,"t":"ദൈവത്തിന്റെ ഹിതം പ്രാവർത്തികമാക്കുന്നവനാരോ അവനാണ് എന്റെ സഹോദരനും സഹോദരിയും അമ്മയും."}],"4":[{"h":"വിതക്കാരന്റെ ഉപമ"},{"v":1,"t":"കടൽത്തീരത്തുവച്ച് യേശു വീണ്ടും പഠിപ്പിക്കാൻ തുടങ്ങി. വളരെ വലിയ ഒരു ജനക്കൂട്ടം അവന്റെ അടുത്തു വന്നുകൂടി. അതിനാൽ, കടലിൽ ഒരു വഞ്ചിയിൽക്കയറി അവൻ ഇരുന്നു. ജനക്കൂട്ടമെല്ലാം കരയിൽ കടലിനഭിമുഖമായി നിന്നു.","p":1},{"v":2,"t":"അവൻ ഉപമകളിൽ അനേകം കാര്യങ്ങൾ അവരെ പഠിപ്പിച്ചു. പ്രബോധനത്തിൽ അവൻ അവരോടു പറഞ്ഞു:"},{"v":3,"t":"കേൾക്കുവിൻ, ഇതാ, ഒരു വിതക്കാരൻ വിതയ്ക്കാൻ പുറപ്പെട്ടു."},{"v":4,"t":"വിതച്ചപ്പോൾ വിത്തുകളിൽ ചിലത് വഴിയരികിൽ വീണു; പക്ഷികൾ വന്ന് അവ തിന്നുകളഞ്ഞു."},{"v":5,"t":"മറ്റുചിലത് മണ്ണ് അധികമില്ലാത്ത പാറപ്പുറത്തു വീണു. മണ്ണിന് ആഴമില്ലാതിരുന്നതിനാൽ അവ പെട്ടെന്നു മുളച്ചുപൊങ്ങി."},{"v":6,"t":"സൂര്യനുദിച്ചപ്പോൾ അവ വെയിലേറ്റുവാടുകയും വേരില്ലാതിരുന്നതിനാൽ കരിഞ്ഞുപോകുകയും ചെയ്തു."},{"v":7,"t":"വേറെ ചിലതു മുൾച്ചെടികൾക്കിടയിൽ വീണു. മുൾച്ചെടികൾ വളർന്ന് അതിനെ ഞെരുക്കിക്കളഞ്ഞു. അതു ഫലം നല്കിയില്ല."},{"v":8,"t":"മറ്റുള്ള വിത്തുകൾ നല്ല മണ്ണിൽ പതിച്ചു. അവ മുളച്ചുപൊങ്ങി വളർന്ന് ഫലം നല്കി. മുപ്പതുമേനിയും അറുപതുമേനിയും നൂറുമേനിയും വിളവുനല്കി."},{"v":9,"t":"അവൻ പറഞ്ഞു: കേൾക്കാൻ ചെവിയുള്ളവൻ കേൾക്കട്ടെ."},{"h":"ഉപമകളുടെ ഉദ്ദേശ്യം"},{"v":10,"t":"അവൻ തനിച്ചായപ്പോൾ, പന്ത്രണ്ടുപേരോടുംകൂടെ ചുറ്റുമുണ്ടായിരുന്നവർ ഉപമകളെക്കുറിച്ച് അവനോടു ചോദിച്ചു.","p":1},{"v":11,"t":"അവൻ പറഞ്ഞു: നിങ്ങൾക്കാണ് ദൈവരാജ്യത്തിന്റെ രഹസ്യം നല്കപ്പെട്ടിരിക്കുന്നത്; പുറത്തുള്ളവർക്കാകട്ടെ, എല്ലാം ഉപമകളിൽമാത്രം."},{"v":12,"t":"അവർ കണ്ടിട്ടും ദർശിക്കാതിരിക്കാനും കേട്ടിട്ടും ഗ്രഹിക്കാതിരിക്കാനും അങ്ങനെ അവർ മനസ്സുതിരിഞ്ഞ് മോചിതരാകാതിരിക്കാനുമാണത്."},{"h":"വിതക്കാരന്റെ ഉപമ - വിശദീകരണം"},{"v":13,"t":"അവൻ അവരോടു ചോദിച്ചു: ഈ ഉപമ നിങ്ങൾ ഗ്രഹിക്കുന്നില്ലേ? എങ്കിൽ, ഉപമകളെല്ലാം നിങ്ങൾ എങ്ങനെ മനസ്സിലാക്കും?","p":1},{"v":14,"t":"വിതക്കാരൻ വചനം വിതയ്ക്കുന്നു."},{"v":15,"t":"വഴിയരികിൽ വിതയ്ക്കപ്പെട്ട വിത്ത് ഇവരാണ്: വചനം ശ്രവിക്കുമ്പോൾത്തന്നെ സാത്താൻ വന്ന്, അവരിൽ വിതയ്ക്കപ്പെട്ട വചനം നീക്കംചെയ്യുന്നു."},{"v":16,"t":"പാറപ്പുറത്തു വിതയ്ക്കപ്പെട്ട വിത്ത് ഇവരാണ്: അവർ വചനം കേൾക്കുമ്പോൾ സന്തോഷപൂർവം സ്വീകരിക്കുന്നു."},{"v":17,"t":"വേരില്ലാത്തതിനാൽ, അവ അല്പസമയത്തേക്കുമാത്രം നിലനില്ക്കുന്നു. വചനത്തെപ്രതി ക്ലേശവും പീഡയുമുണ്ടാകുമ്പോൾ ഉടനെ അവർ വീണുപോകുന്നു."},{"v":18,"t":"മുൾച്ചെടികൾക്കിടയിൽ വിതയ്ക്കപ്പെട്ടവരാണ് മറ്റുള്ളവർ. അവർ വചനം ശ്രവിക്കുന്നു."},{"v":19,"t":"എന്നാൽ, ലൗകികവ്യഗ്രതയും സമ്പത്തിന്റെ വശീകരണവും മറ്റുള്ളവയ്ക്കുവേണ്ടിയുള്ള ആസക്തിയും അവരിൽ കടന്നുകൂടി വചനത്തെ ഞെരുക്കുകയും അതു ഫലശൂന്യമാകുകയും ചെയ്യുന്നു."},{"v":20,"t":"നല്ല മണ്ണിൽ വിതയ്ക്കപ്പെട്ട വിത്താകട്ടെ, വചനം ശ്രവിക്കുകയും സ്വീകരിക്കുകയും മുപ്പതുമേനിയും അറുപതുമേനിയും നൂറുമേനിയും ഫലം പുറപ്പെടുവിക്കുകയും ചെയ്യുന്നവരാണ്."},{"h":"ദീപം മറച്ചുവയ്ക്കരുത്"},{"v":21,"t":"അവൻ അവരോടു പറഞ്ഞു: വിളക്കുകൊണ്ടുവരുന്നത് പറയുടെ കീഴിലോ കട്ടിലിന്റെ അടിയിലോ വയ്ക്കാനാണോ? ദീപപീഠത്തിന്മേൽ വയ്ക്കാനല്ലേ?","p":1},{"v":22,"t":"വെളിപ്പെടുത്തപ്പെടാതെ മറഞ്ഞിരിക്കുന്ന ഒന്നുമില്ല. വെളിച്ചത്തുവരാതെ രഹസ്യമായിരിക്കുന്നതും ഒന്നുമില്ല."},{"v":23,"t":"കേൾക്കാൻ ചെവിയുള്ളവൻ കേൾക്കട്ടെ."},{"v":24,"t":"അവൻ അവരോടുപറഞ്ഞു: നിങ്ങൾ കേൾക്കുന്നത് ശ്രദ്ധിക്കുവിൻ. നിങ്ങൾ അളക്കുന്ന അളവിൽത്തന്നെ നിങ്ങൾക്കും അളന്നുകിട്ടും; കൂടുതലും ലഭിക്കും."},{"v":25,"t":"ഉള്ളവനു നല്കപ്പെടും; ഇല്ലാത്തവനിൽനിന്ന് ഉള്ളതും എടുക്കപ്പെടും."},{"h":"വിത്തിന്റെ ഉപമ"},{"v":26,"t":"അവൻ പറഞ്ഞു: ദൈവരാജ്യം, ഒരുവൻ നിലത്ത് വിത്തുവിതയ്ക്കുന്നതിനു സദൃശം.","p":1},{"v":27,"t":"അവൻ രാവും പകലും ഉറങ്ങിയും ഉണർന്നും കഴിയുന്നു. അവൻ അറിയാതെതന്നെ വിത്തുകൾ പൊട്ടിമുളച്ചു വളരുന്നു."},{"v":28,"t":"ആദ്യം ഇല, പിന്നെ കതിർ, തുടർന്ന് കതിരിൽ ധാന്യമണികൾ - ഇങ്ങനെ ഭൂമി സ്വയമേവ ഫലം പുറപ്പെടുവിക്കുന്നു."},{"v":29,"t":"ധാന്യം വിളയുമ്പോൾ ഉടനേ അവൻ അരിവാൾവയ്ക്കുന്നു. എന്തെന്നാൽ കൊയ്ത്തുവന്നു കഴിഞ്ഞു."},{"h":"കടുകുമണിയുടെ ഉപമ"},{"v":30,"t":"അവൻ വീണ്ടും പറഞ്ഞു: ദൈവരാജ്യത്തെ നമ്മൾ എന്തിനോടു താരതമ്യപ്പെടുത്തും? എന്ത് ഉപമകൊണ്ട് അത് അവതരിപ്പിക്കും?","p":1},{"v":31,"t":"അത് ഒരു കടുകുമണിക്കു സദൃശമാണ്. നിലത്തു പാകുമ്പോൾ അതു ഭൂമിയിലുള്ള എല്ലാ വിത്തുകളെയുംകാൾ ചെറുതാണ്."},{"v":32,"t":"എന്നാൽ, പാകിക്കഴിയുമ്പോൾ അതു വളർന്ന് എല്ലാ ചെടികളെയുംകാൾ വലുതാകുകയും വലിയ ശാഖകൾ പുറപ്പെടുവിക്കുകയും ചെയ്യുന്നു. അങ്ങനെ, ആകാശത്തിലെ പക്ഷികൾക്ക് അതിന്റെ തണലിൽ ചേക്കേറാൻ കഴിയുന്നു."},{"v":33,"t":"അവർക്കു മനസ്സിലാകുംവിധം ഇത്തരം അനേകം ഉപമകളിലൂടെ അവൻ വചനം പ്രസംഗിച്ചു."},{"v":34,"t":"ഉപമകളിലൂടെയല്ലാതെ അവൻ അവരോടു സംസാരിച്ചിരുന്നില്ല. എന്നാൽ, ശിഷ്യന്മാർക്കു മാത്രമായി എല്ലാം വിശദമാക്കിക്കൊടുത്തിരുന്നു."},{"h":"കടലിനെ ശാന്തമാക്കുന്നു"},{"v":35,"t":"അന്നു സായാഹ്നമായപ്പോൾ അവൻ അവരോടു പറഞ്ഞു: നമുക്ക് അക്കരയ്ക്കുപോകാം.","p":1},{"v":36,"t":"അവർ ജനക്കൂട്ടത്തെ പറഞ്ഞുവിട്ട്, അവൻ ഇരുന്ന വഞ്ചിയിൽത്തന്നെ അവനെ അക്കരയ്ക്കു കൊണ്ടുപോയി. വേറെ വഞ്ചികളും കൂടെയുണ്ടായിരുന്നു."},{"v":37,"t":"അപ്പോൾ ഒരു കൊടുങ്കാറ്റുണ്ടായി. തിരമാലകൾ വഞ്ചിയിലേക്ക് ആഞ്ഞടിച്ചുകയറി. വഞ്ചിയിൽ വെള്ളം നിറഞ്ഞുകൊണ്ടിരുന്നു."},{"v":38,"t":"യേശു അമരത്തു തലയണവച്ച് ഉറങ്ങുകയായിരുന്നു. അവർ അവനെ വിളിച്ചുണർത്തി പറഞ്ഞു: ഗുരോ, ഞങ്ങൾ നശിക്കാൻ പോകുന്നതു ഗൗനിക്കുന്നില്ലേ?"},{"v":39,"t":"അവൻ ഉണർന്ന് കാറ്റിനെ ശാസിച്ചുകൊണ്ട് കടലിനോടു പറഞ്ഞു: അടങ്ങുക; ശാന്തമാകുക. കാറ്റു ശമിച്ചു; വലിയ ശാന്തതയുണ്ടായി."},{"v":40,"t":"അവൻ അവരോടു ചോദിച്ചു: നിങ്ങൾ ഭയപ്പെടുന്നതെന്ത്? നിങ്ങൾക്കു വിശ്വാസമില്ലേ?"},{"v":41,"t":"അവർ അത്യധികം ഭയന്ന് പരസ്പരം പറഞ്ഞു: ഇവൻ ആരാണ്? കാറ്റുംകടലുംപോലും ഇവനെ അനുസരിക്കുന്നല്ലോ!"}],"5":[{"h":"പിശാചുബാധിതനെ സുഖപ്പെടുത്തുന്നു"},{"v":1,"t":"അവർ കടലിന്റെ മറുകരയിൽ ഗെരസേനരുടെ ദേശത്തെത്തി.","p":1},{"v":2,"t":"അവൻ വഞ്ചിയിൽനിന്ന് ഇറങ്ങിയ ഉടനെ, അശുദ്ധാത്മാവുള്ള ഒരു മനുഷ്യൻ ശവകുടീരങ്ങൾക്കിടയിൽനിന്ന് അവന്റെ നേരെ വന്നു."},{"v":3,"t":"ശവകുടീരങ്ങൾക്കിടയിൽ താമസിച്ചിരുന്ന അവനെ ചങ്ങലകൊണ്ടുപോലും ബന്ധിച്ചിടാൻ ആർക്കും കഴിഞ്ഞിരുന്നില്ല."},{"v":4,"t":"പലപ്പോഴും അവനെ കാൽവിലങ്ങുകളാലും ചങ്ങലകളാലും ബന്ധിച്ചിരുന്നെങ്കിലും അവൻ ചങ്ങലകൾ വലിച്ചുപൊട്ടിക്കുകയും കാൽവിലങ്ങുകൾ തകർത്തുകളയുകയും ചെയ്തിരുന്നു. അവനെ കീഴ്പ്പെടുത്താൻ ആർക്കും ശക്തിയില്ലായിരുന്നു."},{"v":5,"t":"അലറുകയും കല്ലുകൊണ്ടു തന്നെത്തന്നെ മുറിപ്പെടുത്തുകയും ചെയ്തുകൊണ്ട് അവൻ രാപകൽ കല്ലറകൾക്കിടയിലും മലകളിലും കഴിഞ്ഞിരുന്നു."},{"v":6,"t":"അകലെവച്ചുതന്നെ അവൻ യേശുവിനെക്കണ്ട്, ഓടിവന്ന് അവനെ താണുവണങ്ങി."},{"v":7,"t":"ഉച്ചത്തിൽനിലവിളിച്ചുകൊണ്ട് അവൻ പറഞ്ഞു: അത്യുന്നതനായ ദൈവത്തിന്റെ പുത്രാ, യേശുവേ, എനിക്കും നിനക്കുമെന്ത്? ഞാൻ നിന്നോട് ദൈവത്തെക്കൊണ്ട് ആണയിട്ടപേക്ഷിക്കുന്നു; നീ എന്നെ പീഡിപ്പിക്കരുതേ!"},{"v":8,"t":"കാരണം, അവനോട് യേശു ആജ്ഞാപിച്ചിരുന്നു: അശുദ്ധാത്മാവേ, ഈ മനുഷ്യനിൽനിന്നു പുറത്തുവരൂ."},{"v":9,"t":"യേശു ചോദിച്ചു: നിന്റെ പേരെന്താണ്? അവൻ പറഞ്ഞു: എന്റെ പേര് ലെഗിയോൻ; ഞങ്ങൾ അനേകരുണ്ട്."},{"v":10,"t":"തങ്ങളെ ആ ദേശത്തുനിന്നു പുറത്താക്കരുതേ എന്ന് അവൻ കേണപേക്ഷിച്ചു."},{"v":11,"t":"വലിയ ഒരു പന്നിക്കൂട്ടം മലയരികിൽ തീറ്റിതിന്നുന്നുണ്ടായിരുന്നു."},{"v":12,"t":"അവർ അവനോട് അപേക്ഷിച്ചു: ഞങ്ങളെ ആ പന്നിക്കൂട്ടത്തിലേക്കയയ്ക്കുക, ഞങ്ങൾ അവയിൽ പ്രവേശിച്ചുകൊള്ളട്ടെ."},{"v":13,"t":"അവൻ അനുവാദം നല്കി. അശുദ്ധാത്മാക്കൾ പുറത്തുവന്ന്, പന്നിക്കൂട്ടത്തിൽ പ്രവേശിച്ചു. ഏകദേശം രണ്ടായിരം പന്നികൾ കീഴ്ക്കാംതൂക്കായ ചരിവിലൂടെ പാഞ്ഞുചെന്ന് കടലിൽ മുങ്ങിച്ചത്തു."},{"v":14,"t":"അവയെ തീറ്റിക്കൊണ്ടിരുന്നവർ ഓടിപ്പോയി നഗരങ്ങളിലും നാട്ടിൻപുറങ്ങളിലും വിവരമറിയിച്ചു. സംഭവിച്ചതെന്തെന്നു കാണാൻ ആളുകൾ വന്നുകൂടി."},{"v":15,"t":"അവർ യേശുവിന്റെ അടുത്തെത്തി, ലെഗിയോനുണ്ടായിരുന്ന പിശാചുബാധിതൻ വസ്ത്രം ധരിച്ച്, സുബോധത്തോടെ അവിടെയിരിക്കുന്നതു കണ്ടു. അവർ ഭയപ്പെട്ടു."},{"v":16,"t":"പിശാചുബാധിതനും പന്നികൾക്കും സംഭവിച്ചതു കണ്ടവർ അക്കാര്യങ്ങൾ അവരോടു വിവരിച്ചു."},{"v":17,"t":"തങ്ങളുടെപ്രദേശം വിട്ടുപോകണമെന്ന് അവർ യേശുവിനോട് അപേക്ഷിക്കാൻ തുടങ്ങി."},{"v":18,"t":"അവൻ വഞ്ചിയിൽ കയറുമ്പോൾ, അവനോടുകൂടെ പോകാൻ പിശാചുബാധിച്ചിരുന്നവൻ അനുവാദം ചോദിച്ചു."},{"v":19,"t":"എന്നാൽ, യേശു അനുവദിച്ചില്ല. അവൻ പറഞ്ഞു: നീ വീട്ടിൽ സ്വന്തക്കാരുടെ അടുത്തേക്കു പോകുക. കർത്താവു നിനക്കുവേണ്ടി ചെയ്തതൊക്കെയും നിന്നോടു കരുണകാണിച്ചതും അവരെ അറിയിക്കുക."},{"v":20,"t":"അവൻ പോയി, യേശു തനിക്കുവേണ്ടി ചെയ്തതൊക്കെ ദെക്കാപ്പോളിസിൽ പ്രഘോഷിക്കാൻ തുടങ്ങി. എല്ലാവരും അദ്ഭുതപ്പെട്ടു."},{"h":"ജായ്റോസിന്റെ മകൾ; രക്തസ്രാവക്കാരി"},{"v":21,"t":"യേശു വീണ്ടും വഞ്ചിയിൽ മറുകരയെത്തിയപ്പോൾ ഒരു വലിയ ജനക്കൂട്ടം അവനു ചുറ്റും കൂടി. അവൻ കടൽത്തീരത്തു നില്ക്കുകയായിരുന്നു.","p":1},{"v":22,"t":"അപ്പോൾ, സിനഗോഗധികാരികളിൽ ഒരുവനായ ജായ്റോസ് അവിടെ വന്നു. അവൻ യേശുവിനെക്കണ്ട് കാല്ക്കൽ വീണ്,"},{"v":23,"t":"അവനോടു കേണപേക്ഷിച്ചു: എന്റെ ഓമനമകൾ മരിക്കാറായിക്കിടക്കുന്നു. അവൾ സൗഖ്യം പ്രാപിച്ച് ജീവിക്കാനായി അങ്ങുവന്ന് അവളുടെമേൽ കൈകൾ വയ്ക്കണമേ."},{"v":24,"t":"യേശു അവന്റെകൂടെ പോയി. വലിയൊരു ജനക്കൂട്ടം അവനെ അനുഗമിക്കുകയും തിക്കിഞെരുക്കുകയും ചെയ്തു."},{"v":25,"t":"പന്ത്രണ്ടുവർഷമായി രക്തസ്രാവമുള്ള ഒരു സ്ത്രീ ഉണ്ടായിരുന്നു.","p":1},{"v":26,"t":"പല വൈദ്യന്മാരിലുംനിന്ന് ഏറെ കഷ്ടപ്പാടുകൾ സഹിക്കുകയും അവൾക്കുള്ളതെല്ലാം ചെലവഴിക്കുകയും ചെയ്തിട്ടും പ്രയോജനപ്പെട്ടില്ലെന്നു മാത്രമല്ല, കൂടുതൽ മോശമാകുകയുമാണു ചെയ്തത്."},{"v":27,"t":"യേശുവിനെക്കുറിച്ചു കേട്ടിരുന്ന അവൾ ജനക്കൂട്ടത്തിനിടയിലൂടെ അവന്റെ പിന്നിൽചെന്ന്, വസ്ത്രത്തിൽ തൊട്ടു."},{"v":28,"t":"കാരണം, അവൾ പറഞ്ഞിരുന്നു: അവന്റെ വസ്ത്രത്തിൽ ഒന്നു തൊട്ടാൽ മാത്രം മതി, ഞാൻ സുഖംപ്രാപിക്കും."},{"v":29,"t":"ഉടനെ അവളുടെ രക്തസ്രാവം നിലച്ചു. താൻ വ്യാധിയിൽനിന്ന് സുഖംപ്രാപിച്ചിരിക്കുന്നെന്ന് അവൾക്കു ശരീരത്തിൽ അനുഭവപ്പെട്ടു."},{"v":30,"t":"ഉടനെ യേശു, തന്നിൽനിന്നു ശക്തിപുറപ്പെട്ടെന്നറിഞ്ഞ്, തിരിഞ്ഞ് ജനമധ്യത്തിൽനിന്നുകൊണ്ടു ചോദിച്ചു: ആരാണ് എന്റെ വസ്ത്രത്തിൽ തൊട്ടത്?"},{"v":31,"t":"ശിഷ്യന്മാർ അവനോടു പറഞ്ഞു: ജനക്കൂട്ടം നിന്നെ തിക്കിഞെരുക്കുന്നതു കാണുന്നില്ലേ? എന്നിട്ടും, ആരാണ് എന്നെ തൊട്ടത് എന്നു നീ ചോദിക്കുന്നുവോ?"},{"v":32,"t":"ഇതു ചെയ്തത് ആരെന്നു കാണാൻ അവൻ ചുറ്റും നോക്കി."},{"v":33,"t":"ആ സ്ത്രീ തനിക്കു സംഭവിച്ചതറിഞ്ഞ്, ഭയന്നുവിറച്ച്, വന്ന്, അവന്റെ മുമ്പിൽ വീണ് സത്യം മുഴുവൻ അവനോടു പറഞ്ഞു."},{"v":34,"t":"അവൻ അവളോടു പറഞ്ഞു: മകളേ, നിന്റെ വിശ്വാസം നിന്നെ രക്ഷിച്ചിരിക്കുന്നു; സമാധാനത്തിൽ പോകുക; വ്യാധിയിൽനിന്നു വിമുക്തയായിരിക്കുക."},{"v":35,"t":"യേശു സംസാരിച്ചുകൊണ്ടിരിക്കേ, സിനഗോഗധികാരിയുടെ വീട്ടിൽനിന്ന് ചിലർ വന്നു പറഞ്ഞു: നിന്റെ മകൾ മരിച്ചു; ഗുരുവിനെ ഇനിയും എന്തിനു ബുദ്ധിമുട്ടിക്കുന്നു?"},{"v":36,"t":"ആ വാക്കു കാര്യമാക്കാതെ യേശു സിനഗോഗധികാരിയോടു പറഞ്ഞു: ഭയപ്പെടേണ്ടാ, വിശ്വസിക്കുകമാത്രം ചെയ്യുക."},{"v":37,"t":"പത്രോസും യാക്കോബും യാക്കോബിന്റെ സഹോദരൻ യോഹന്നാനുമൊഴികെ മറ്റാരും തന്നോടുകൂടെപ്പോരാൻ അവൻ അനുവദിച്ചില്ല."},{"v":38,"t":"അവർ സിനഗോഗധികാരിയുടെ വീട്ടിലെത്തി. അവിടെ ബഹളവും വിലാപവും ഉച്ചത്തിലുള്ള അലമുറയും അവൻ കണ്ടു."},{"v":39,"t":"അകത്തു പ്രവേശിച്ച് അവൻ അവരോടു പറഞ്ഞു: എന്തിനാണു നിങ്ങൾ ബഹളം വയ്ക്കുകയും വിലപിക്കുകയും ചെയ്യുന്നത്? കുട്ടി മരിച്ചിട്ടില്ല, ഉറങ്ങുകയാണ്."},{"v":40,"t":"അവർ അവനെ പരിഹസിച്ചു. അവനാകട്ടെ, അവരെ എല്ലാവരെയും പുറത്താക്കിക്കൊണ്ട് കുട്ടിയുടെ മാതാപിതാക്കന്മാരെയും തന്റെ കൂടെയുണ്ടായിരുന്നവരെയും കൂട്ടിക്കൊണ്ട് കുട്ടിയുടെ അടുത്തേക്കു ചെന്നു."},{"v":41,"t":"അവൻ കുട്ടിയുടെ കൈപിടിച്ചുകൊണ്ട് അവളോടു പറഞ്ഞു: തലീത്താകും - ബാലികേ, എഴുന്നേല്ക്കൂ എന്നർഥം."},{"v":42,"t":"ഉടനെ, ബാലിക എഴുന്നേറ്റു നടന്നു. അവൾക്കു പന്ത്രണ്ടുവയസ്സായിരുന്നു. അവർ അത്യന്തം ആശ്ചര്യപ്പെട്ടു."},{"v":43,"t":"ആരും ഈ വിവരം അറിയരുതെന്ന് യേശു അവർക്കു കർശനമായ ആജ്ഞ നല്കി. അവൾക്കു ഭക്ഷിക്കാൻ കൊടുക്കുവിൻ എന്നും അവൻ പറഞ്ഞു."}],"6":[{"h":"യേശു സ്വദേശത്ത് അവഗണിക്കപ്പെടുന്നു"},{"v":1,"t":"യേശു അവിടെനിന്നു പോയി, സ്വദേശത്തു വന്നു. ശിഷ്യന്മാർ അവനെ അനുഗമിച്ചു.","p":1},{"v":2,"t":"സാബത്തായപ്പോൾ അവൻ സിനഗോഗിൽ പഠിപ്പിക്കാനാരംഭിച്ചു. അവന്റെ വാക്കുകേട്ട അനേകംപേർ ആശ്ചര്യപ്പെട്ടു പറഞ്ഞു: ഇവന് ഇതെല്ലാം എവിടെനിന്ന്? ഇവനു കിട്ടിയ ഈ ജ്ഞാനം എന്ത്? എന്തെന്ത് അദ്ഭുതങ്ങളാണ് ഇവന്റെ കരങ്ങൾവഴി സംഭവിക്കുന്നത്!"},{"v":3,"t":"ഇവൻ മറിയത്തിന്റെ മകനും യാക്കോബ്, യോസെ, യൂദാസ്, ശിമയോൻ എന്നിവരുടെ സഹോദരനുമായ മരപ്പണിക്കാരനല്ലേ? ഇവന്റെ സഹോദരിമാരും ഇവിടെ നമ്മുടെകൂടെയില്ലേ? ഇങ്ങനെ പറഞ്ഞ് അവർ അവനിൽ ഇടറി."},{"v":4,"t":"യേശു അവരോടു പറഞ്ഞു: സ്വദേശത്തും ബന്ധുജനങ്ങളുടെയിടയിലും സ്വഭവനത്തിലുമല്ലാതെ മറ്റെങ്ങും പ്രവാചകൻ അവമതിക്കപ്പെടുന്നില്ല."},{"v":5,"t":"ഏതാനും രോഗികളുടെമേൽ കൈകൾവച്ചു സുഖപ്പെടുത്താനല്ലാതെ മറ്റ് അദ്ഭുതമൊന്നും അവിടെ ചെയ്യാൻ അവനു സാധിച്ചില്ല."},{"v":6,"t":"അവരുടെ വിശ്വാസരാഹിത്യത്തെക്കുറിച്ച് അവൻ അദ്ഭുതപ്പെട്ടു. അവൻ പഠിപ്പിച്ചുകൊണ്ട് ഗ്രാമപ്രദേശങ്ങളിൽ ചുറ്റിസഞ്ചരിച്ചുകൊണ്ടിരുന്നു."},{"h":"ശിഷ്യന്മാരെ അയയ്ക്കുന്നു"},{"v":7,"t":"അവൻ പന്ത്രണ്ടുപേരെ അടുത്തു വിളിച്ച് രണ്ടുപേരെ വീതം അയയ്ക്കാൻ തുടങ്ങി. അശുദ്ധാത്മാക്കളുടെമേൽ അവർക്ക് അധികാരവും കൊടുത്തു.","p":1},{"v":8,"t":"അവൻ കല്പിച്ചു: യാത്രയ്ക്കു വടിയല്ലാതെ മറ്റൊന്നും, അപ്പമോ സഞ്ചിയോ അരപ്പട്ടയിൽ പണമോ, കരുതരുത്."},{"v":9,"t":"എന്നാൽ, ചെരിപ്പുധരിക്കാം, രണ്ട് ഉടുപ്പുകൾ ധരിക്കരുത്."},{"v":10,"t":"അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ ഏതെങ്കിലും സ്ഥലത്ത് ഒരു വീട്ടിൽ പ്രവേശിച്ചാൽ, അവിടംവിട്ടുപോകുന്നതുവരെ ആ വീട്ടിൽ താമസിക്കുവിൻ."},{"v":11,"t":"ഏതെങ്കിലും സ്ഥലത്ത് നിങ്ങളെ സ്വീകരിക്കാതിരിക്കുകയോ നിങ്ങളെ ശ്രവിക്കാതിരിക്കുകയോ ചെയ്താൽ അവിടം വിട്ടുപോരുമ്പോൾ അവർക്കു സാക്ഷ്യത്തിനായി നിങ്ങളുടെ പാദങ്ങളിലെ പൊടി തട്ടിക്കളയുവിൻ."},{"v":12,"t":"ശിഷ്യന്മാർ പുറപ്പെട്ട്, ആളുകൾ മാനസാന്തരപ്പെടേണ്ടതിന് പ്രഘോഷിച്ചു."},{"v":13,"t":"അനേകം പിശാചുക്കളെ പുറത്താക്കി; അനേകം രോഗികളെ തൈലം പൂശി സുഖപ്പെടുത്തി."},{"h":"സ്നാപകയോഹന്നാന്റെ ശിരച്ഛേദം"},{"v":14,"t":"യേശുവിന്റെ പേര് പ്രസിദ്ധമായിക്കഴിഞ്ഞിരുന്നതിനാൽ, ഹേറോദേസ്‌രാജാവും അവനെക്കുറിച്ചു കേട്ടു. ചിലർ പറഞ്ഞു: സ്നാപകയോഹന്നാൻ മരിച്ചവരിൽനിന്ന് ഉയിർത്തിരിക്കുന്നു. അതുകൊണ്ടാണ് ഈ ശക്തികൾ ഇവനിൽ പ്രവർത്തിക്കുന്നത്.","p":1},{"v":15,"t":"മറ്റു ചിലർ പറഞ്ഞു: ഇവൻ ഏലിയാ ആണ്, വേറെ ചിലർ പറഞ്ഞു: പ്രവാചകരിൽ ഒരുവനെപ്പോലെ ഇവനും ഒരു പ്രവാചകനാണ്."},{"v":16,"t":"എന്നാൽ, ഇതെല്ലാം കേട്ടപ്പോൾ ഹേറോദേസ് പറഞ്ഞു: ഞാൻ ശിരച്ഛേദംചെയ്ത യോഹന്നാൻ ഉയിർപ്പിക്കപ്പെട്ടിരിക്കുന്നു."},{"v":17,"t":"ഹേറോദേസ് ആളയച്ച് യോഹന്നാനെ പിടിപ്പിക്കുകയും കാരാഗൃഹത്തിൽ ബന്ധിക്കുകയും ചെയ്തിരുന്നു. ഇത് സ്വന്തം സഹോദരനായ പീലിപ്പോസിന്റെ ഭാര്യ ഹേറോദിയാ നിമിത്തമാണ്. അവൻ അവളെ വിവാഹം ചെയ്തിരുന്നു."},{"v":18,"t":"യോഹന്നാൻ ഹേറോദേസിനോടു പറഞ്ഞു: സഹോദരന്റെ ഭാര്യയെ നീ സ്വന്തമാക്കുന്നതു നിഷിദ്ധമാണ്."},{"v":19,"t":"തന്മൂലം, ഹേറോദിയായ്ക്ക് യോഹന്നാനോടു പകയുണ്ടായി. അവനെ വധിക്കാൻ അവൾ ആഗ്രഹിച്ചു. എന്നാൽ അവൾക്കു സാധിച്ചില്ല."},{"v":20,"t":"എന്തെന്നാൽ, യോഹന്നാൻ നീതിമാനും വിശുദ്ധനുമാണെന്ന് അറിഞ്ഞിരുന്നതുകൊണ്ട്, ഹേറോദേസ് അവനെ ഭയപ്പെടുകയും സംരക്ഷിക്കുകയും ചെയ്തു. അവനെ കേൾക്കുമ്പോൾ അവൻ അസ്വസ്ഥനായിരുന്നെങ്കിലും, സന്തോഷത്തോടെ അവനെ ശ്രവിക്കുമായിരുന്നു."},{"v":21,"t":"ഹേറോദേസ് തന്റെ ജന്മദിനത്തിൽ രാജസേവകന്മാർക്കും സഹസ്രാധിപന്മാർക്കും ഗലീലിയിലെ പ്രമാണിമാർക്കും വിരുന്നുനല്കിയപ്പോൾ അനുകൂലമായ ഒരവസരം വന്നുചേർന്നു."},{"v":22,"t":"ഹേറോദിയായുടെ മകൾ വന്ന് നൃത്തംചെയ്ത് ഹേറോദേസിനെയും വിരുന്നുകാരെയും പ്രീതിപ്പെടുത്തി. രാജാവു പെൺകുട്ടിയോടു പറഞ്ഞു: നീ ആഗ്രഹിക്കുന്നതെന്തും ചോദിച്ചുകൊള്ളുക. അതു ഞാൻ നിനക്കു തരും."},{"v":23,"t":"അവൻ അവളോടു ശപഥം ചെയ്തു: നീ എന്തുതന്നെ ചോദിച്ചാലും, എന്റെ രാജ്യത്തിന്റെ പകുതിപോലും ഞാൻ നിനക്കു തരും."},{"v":24,"t":"അവൾ പോയി അമ്മയോടു ചോദിച്ചു: ഞാൻ എന്താണ് ആവശ്യപ്പെടേണ്ടത്? അവൾ പറഞ്ഞു: സ്നാപകയോഹന്നാന്റെ ശിരസ്സ്."},{"v":25,"t":"അവൾ ഉടനെ ബദ്ധപ്പെട്ട് അകത്തുവന്ന് രാജാവിനോട് ആവശ്യപ്പെട്ടു: ഇപ്പോൾത്തന്നെ സ്നാപകയോഹന്നാന്റെ ശിരസ്സ് ഒരു തളികയിൽവച്ചുകൊണ്ടുവന്ന് എനിക്കു തരണമെന്ന് ഞാൻ ആഗ്രഹിക്കുന്നു."},{"v":26,"t":"രാജാവ് അതീവ ദുഃഖിതനായി. എങ്കിലും, തന്റെ ശപഥത്തെയും വിരുന്നുകാരെയുംപ്രതി അവളുടെ ആഗ്രഹം നിരസിക്കാൻ അവനു തോന്നിയില്ല."},{"v":27,"t":"അവന്റെ തല കൊണ്ടുവരാൻ ആജ്ഞാപിച്ച് ഒരു കാവൽപടയാളിയെ രാജാവ് ഉടനെ അയച്ചു. അവൻ കാരാഗൃഹത്തിൽ ചെന്ന് യോഹന്നാന്റെ തലവെട്ടിയെടുത്തു."},{"v":28,"t":"അത് ഒരു തളികയിൽവച്ചു കൊണ്ടുവന്ന് പെൺകുട്ടിക്കു കൊടുത്തു. പെൺകുട്ടി അത് അമ്മയ്ക്കു കൊടുത്തു."},{"v":29,"t":"ഈ വിവരമറിഞ്ഞ യോഹന്നാന്റെ ശിഷ്യന്മാർ വന്ന് മൃതദേഹമെടുത്ത് കല്ലറയിൽ സംസ്കരിച്ചു."},{"h":"അപ്പം വർധിപ്പിക്കുന്നു"},{"v":30,"t":"അപ്പസ്തോലന്മാർ യേശുവിന്റെ അടുത്ത് ഒരുമിച്ചുകൂടി, തങ്ങൾ ചെയ്തതും പഠിപ്പിച്ചതുമെല്ലാം അവനെ അറിയിച്ചു.","p":1},{"v":31,"t":"അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ തനിച്ച് ഒരു വിജനസ്ഥലത്തേക്കു വരുവിൻ; അല്പം വിശ്രമിക്കുവിൻ. എന്തെന്നാൽ, അനേകമാളുകൾ വരുകയും പോകുകയും ചെയ്തുകൊണ്ടിരുന്നു. തന്മൂലം ഭക്ഷണം കഴിക്കാൻപോലും അവർക്ക് അവസരമുണ്ടായിരുന്നില്ല."},{"v":32,"t":"അവർ തനിച്ച് വഞ്ചിയിൽ ഒരു വിജനസ്ഥലത്തേക്കു പോയി."},{"v":33,"t":"അവർ പോകുന്നത് പലരും കാണുകയും തിരിച്ചറിയുകയും ചെയ്തു. എല്ലാ പട്ടണങ്ങളിലുംനിന്ന് ആളുകൾ കരവഴി ഓടി അവർക്കുമുമ്പേ അവിടെയെത്തി."},{"v":34,"t":"അവൻ കരയ്ക്കിറങ്ങിയപ്പോൾ വലിയ ഒരു ജനക്കൂട്ടത്തെ കണ്ടു. അവരോട് അവന് അനുകമ്പ തോന്നി. കാരണം, അവർ ഇടയനില്ലാത്ത ആടുകളെപ്പോലെയായിരുന്നു. അവൻ അവരെ പല കാര്യങ്ങളും പഠിപ്പിക്കാൻ തുടങ്ങി."},{"v":35,"t":"നേരം വൈകിയപ്പോൾ ശിഷ്യന്മാർ അവന്റെയടുത്തു വന്നു പറഞ്ഞു: ഇത് ഒരു വിജനപ്രദേശമാണല്ലോ; സമയവും വൈകിയിരിക്കുന്നു."},{"v":36,"t":"ചുറ്റുമുള്ള നാട്ടിൻപുറങ്ങളിലും ഗ്രാമങ്ങളിലുംചെന്ന്, ഭക്ഷിക്കാൻ എന്തെങ്കിലും വാങ്ങാൻ അവരെ പറഞ്ഞയയ്ക്കുക."},{"v":37,"t":"അവൻ അവരോടു മറുപടി പറഞ്ഞു: നിങ്ങൾതന്നെ അവർക്കു ഭക്ഷിക്കാൻ കൊടുക്കുവിൻ. അവർ അവനോടു പറഞ്ഞു: ഞങ്ങൾ ചെന്ന്, ഇരുനൂറു ദനാറയ്ക്ക് അപ്പം വാങ്ങിക്കൊണ്ടുവന്ന് അവർക്കു ഭക്ഷിക്കാൻ കൊടുക്കട്ടെയോ?"},{"v":38,"t":"അവൻ ചോദിച്ചു: നിങ്ങൾക്ക് എത്ര അപ്പമുണ്ട്; ചെന്നുനോക്കുവിൻ. അവർ നോക്കിയിട്ടു പറഞ്ഞു: അഞ്ച്, രണ്ടു മീനും."},{"v":39,"t":"എല്ലാവരും പച്ചപ്പുല്ലിൽ കൂട്ടംകൂട്ടമായി ഇരിക്കാൻ അവൻ നിർദേശം നല്കി."},{"v":40,"t":"നൂറും അൻപതും വീതമുള്ള പന്തികളായി അവർ ഇരുന്നു."},{"v":41,"t":"അവൻ അഞ്ചപ്പവും രണ്ടു മീനും എടുത്ത് സ്വർഗത്തിലേക്കു നോക്കി, വാഴ്ത്തി അപ്പംമുറിച്ചശേഷം അവർക്കു വിളമ്പാൻ ശിഷ്യന്മാരെ ഏല്പിച്ചു. ആ രണ്ടു മീനും അവൻ എല്ലാവർക്കുമായി വിഭജിച്ചു."},{"v":42,"t":"അവരെല്ലാവരും ഭക്ഷിച്ചു തൃപ്തരായി."},{"v":43,"t":"ബാക്കിവന്ന അപ്പക്കഷണങ്ങളും മീനും പന്ത്രണ്ടുകുട്ട നിറയെ അവർ ശേഖരിച്ചു."},{"v":44,"t":"അപ്പം ഭക്ഷിച്ചവർ അയ്യായിരം പുരുഷന്മാരായിരുന്നു."},{"h":"യേശു വെള്ളത്തിനുമീതേ നടക്കുന്നു"},{"v":45,"t":"ജനക്കൂട്ടത്തെ പിരിച്ചുവിടുമ്പോഴേക്കും വഞ്ചിയിൽ കയറി തനിക്കുമുമ്പേ മറുകരയിലുള്ള ബേത്സയ്ദായിലേക്കു പോകാൻ അവൻ ഉടനെ ശിഷ്യന്മാരെ നിർബന്ധിച്ചു.","p":1},{"v":46,"t":"ആളുകളോടു യാത്ര പറഞ്ഞശേഷം അവൻ പ്രാർഥിക്കാൻ മലയിലേക്കു പോയി."},{"v":47,"t":"വൈകുന്നേരമായപ്പോൾ വഞ്ചി നടുക്കടലിലായിരുന്നു; അവൻ തനിച്ചു കരയിലും."},{"v":48,"t":"അവർ വഞ്ചിതുഴഞ്ഞ് അവശരായി എന്ന് അവൻ മനസ്സിലാക്കി. കാരണം, കാറ്റു പ്രതികൂലമായിരുന്നു. ഏകദേശം രാത്രി നാലാംയാമത്തിൽ അവൻ കടലിനുമീതേ നടന്ന് അവരുടെ അടുത്തെത്തി, അവരെ കടന്നുപോകാൻ ഭാവിച്ചു."},{"v":49,"t":"അവൻ കടലിനുമീതേ നടക്കുന്നതുകണ്ട്, അത് ഒരു ഭൂതമായിരിക്കുമെന്നു കരുതി അവർ നിലവിളിച്ചു."},{"v":50,"t":"എന്തെന്നാൽ, അവരെല്ലാവരും അവനെക്കണ്ട് പരിഭ്രമിച്ചിരുന്നു. ഉടനെ അവൻ അവരോടു സംസാരിച്ചു: ധൈര്യത്തോടെയിരിക്കുവിൻ, ഞാനാകുന്നു; ഭയപ്പെടേണ്ടാ."},{"v":51,"t":"അവൻ അവരുടെ അടുക്കലേക്ക്, വഞ്ചിയിലേക്ക് കയറി. അപ്പോൾ കാറ്റു ശമിച്ചു. അവർ അത്യന്തം ആശ്ചര്യഭരിതരായി."},{"v":52,"t":"കാരണം, അപ്പത്തെക്കുറിച്ച് അവർ ഗ്രഹിച്ചിരുന്നില്ല. അവരുടെ ഹൃദയം കഠിനമാക്കപ്പെട്ടിരുന്നു."},{"h":"ഗനേസറത്തിലെ അദ്ഭുതങ്ങൾ"},{"v":53,"t":"അവർ അക്കരെ കടന്ന്, ഗനേസറത്തിൽ എത്തി, വഞ്ചി അടുപ്പിച്ചു.","p":1},{"v":54,"t":"അവർ വഞ്ചിയിൽനിന്ന് പുറത്തിറങ്ങിയപ്പോൾ ആളുകൾ അവനെ ഉടനെ തിരിച്ചറിഞ്ഞു."},{"v":55,"t":"അവർ സമീപപ്രദേശങ്ങളിലെല്ലാം ഓടിനടന്ന്, രോഗികളെ കിടക്കയിലെടുത്ത്, അവൻ ഉണ്ടെന്നു കേട്ടിടത്തേക്കു കൊണ്ടുവരാൻ തുടങ്ങി."},{"v":56,"t":"ഗ്രാമങ്ങളിലോ നഗരങ്ങളിലോ നാട്ടിൻപുറങ്ങളിലോ അവൻ ചെന്നിടത്തൊക്കെ, ആളുകൾ രോഗികളെ കൊണ്ടുവന്ന് പൊതുസ്ഥലങ്ങളിൽ കിടത്തി, അവന്റെ വസ്ത്രത്തിന്റെ വിളുമ്പിലെങ്കിലും തൊടാൻ അനുവദിക്കണമെന്ന് അപേക്ഷിച്ചുകൊണ്ടിരുന്നു. അവനെ തൊട്ടവരെല്ലാം സുഖം പ്രാപിച്ചു."}],"7":[{"h":"പാരമ്പര്യത്തെക്കുറിച്ചു തർക്കം"},{"v":1,"t":"ഫരിസേയരും ജറുസലേമിൽനിന്നുവന്ന ചില നിയമജ്ഞരും യേശുവിനു ചുറ്റുംകൂടി.","p":1},{"v":2,"t":"അവന്റെ ശിഷ്യന്മാരിൽ ചിലർ അശുദ്ധമായ കരങ്ങളോടെ, അതായത്, ക്ഷാളനം നടത്താതെ ഭക്ഷണം കഴിക്കുന്നത് അവർ കണ്ടു."},{"v":3,"t":"ശ്രേഷ്ഠന്മാരുടെ പാരമ്പര്യമനുസരിച്ച് ഫരിസേയരും യഹൂദരുമെല്ലാം കൈകഴുകാതെ ഭക്ഷണം കഴിക്കാറില്ല."},{"v":4,"t":"പൊതുസ്ഥലത്തുനിന്നു വരുമ്പോഴും സ്വയം ശുദ്ധിവരുത്താതെ അവർ ഭക്ഷണം കഴിക്കാറില്ല. കോപ്പകളുടെയും കലങ്ങളുടെയും ഓട്ടുപാത്രങ്ങളുടെയും ക്ഷാളനം തുടങ്ങി മറ്റു പല പാരമ്പര്യങ്ങളും അവർ അനുഷ്ഠിച്ചുപോന്നു."},{"v":5,"t":"ഫരിസേയരും നിയമജ്ഞരും അവനോടു ചോദിച്ചു: നിന്റെ ശിഷ്യന്മാർ ശ്രേഷ്ഠന്മാരുടെ പാരമ്പര്യമനുസരിച്ചു നടക്കാതെ അശുദ്ധമായ കൈകൊണ്ട് അപ്പം ഭക്ഷിക്കുന്നതെന്ത്?"},{"v":6,"t":"അവൻ അവരോടു പറഞ്ഞു: കപടനാട്യക്കാരായ നിങ്ങളെക്കുറിച്ച് ഏശയ്യാ ശരിയായിത്തന്നെ പ്രവചിച്ചു. എഴുതപ്പെട്ടിരിക്കുന്നപോലെ, ഈ ജനം അധരങ്ങൾകൊണ്ട് എന്നെ ബഹുമാനിക്കുന്നു. എന്നാൽ, അവരുടെ ഹൃദയം എന്നിൽനിന്നു വളരെ ദൂരെയാണ്."},{"v":7,"t":"വ്യർഥമായി അവർ എന്നെ ആരാധിക്കുന്നു; മനുഷ്യരുടെ കല്പനകൾ പ്രമാണങ്ങളായി പഠിപ്പിക്കുകയും ചെയ്യുന്നു."},{"v":8,"t":"ദൈവത്തിന്റെ കല്പന ഉപേക്ഷിച്ച്, മനുഷ്യരുടെ പാരമ്പര്യം നിങ്ങൾ മുറുകെപ്പിടിക്കുന്നു."},{"v":9,"t":"അവൻ അവരോടു പറഞ്ഞു: നിങ്ങളുടെ പാരമ്പര്യം പാലിക്കാൻവേണ്ടി നിങ്ങൾ കൗശലപൂർവം ദൈവകല്പന അവഗണിക്കുന്നു."},{"v":10,"t":"എന്തെന്നാൽ, നിന്റെ പിതാവിനെയും മാതാവിനെയും ബഹുമാനിക്കുക. പിതാവിനെയോ മാതാവിനെയോ ദുഷിച്ചുപറയുന്നവൻ മരിക്കട്ടെ എന്നു മോശ പറഞ്ഞിട്ടുണ്ട്."},{"v":11,"t":"എന്നാൽ, ഒരുവൻ തന്റെ പിതാവിനോടോ മാതാവിനോടോ, നിങ്ങൾക്ക് എന്നിൽനിന്നു ലഭിക്കേണ്ടത് കൊർബാൻ, അതായത് അർപ്പിതം എന്നു പറഞ്ഞാൽ മതി എന്നു നിങ്ങൾ പറയുന്നു."},{"v":12,"t":"പിന്നെ പിതാവിനോ മാതാവിനോവേണ്ടി ഒന്നും ചെയ്യാൻ നിങ്ങൾ അവനെ ഒരിക്കലും അനുവദിക്കുന്നുമില്ല."},{"v":13,"t":"അങ്ങനെ, നിങ്ങൾ കൈമാറുന്ന നിങ്ങളുടെ പാരമ്പര്യംവഴി ദൈവവചനം നിങ്ങൾ ശൂന്യമാക്കുന്നു. ഇതുപോലെ പലതും നിങ്ങൾ ചെയ്യുന്നു."},{"h":"ആന്തരികവും ബാഹ്യവുമായ ശുദ്ധി"},{"v":14,"t":"ജനക്കൂട്ടത്തെ വീണ്ടും അടുത്തേക്കു വിളിച്ച് അവൻ അവരോടു പറഞ്ഞു: നിങ്ങളെല്ലാവരും എന്റെ വാക്കു കേട്ടു മനസ്സിലാക്കുവിൻ.","p":1},{"v":15,"t":"പുറമേനിന്ന് ഉള്ളിലേക്കു കടന്ന്, മനുഷ്യനെ അശുദ്ധനാക്കാൻ ഒന്നിനും കഴിയുകയില്ല. എന്നാൽ, മനുഷ്യന്റെ ഉള്ളിൽനിന്നു പുറപ്പെടുന്നവയാണ് അവനെ അശുദ്ധനാക്കുന്നത്."},{"v":16,"t":"കേൾക്കാൻ ചെവിയുള്ളവൻ കേൾക്കട്ടെ."},{"v":17,"t":"അവൻ ജനക്കൂട്ടത്തെവിട്ട് ഭവനത്തിലെത്തിയപ്പോൾ ഈ ഉപമയെക്കുറിച്ച് അവന്റെ ശിഷ്യന്മാർ ചോദിച്ചു."},{"v":18,"t":"അവൻ പറഞ്ഞു: നിങ്ങളും ഗ്രഹണശക്തിയില്ലാത്തവരാണോ? പുറമേനിന്നു മനുഷ്യന്റെ ഉള്ളിൽ പ്രവേശിക്കുന്ന ഒന്നിനും അവനെ അശുദ്ധനാക്കാൻ സാധിക്കില്ലെന്ന് നിങ്ങൾ മനസ്സിലാക്കുന്നില്ലേ?"},{"v":19,"t":"കാരണം, അവ മനുഷ്യന്റെ ഹൃദയത്തിൽ പ്രവേശിക്കുന്നില്ല. പിന്നെയോ, ഉദരത്തിലേക്കു കടക്കുകയും വിസർജിക്കപ്പെടുകയും ചെയ്യുന്നു. എല്ലാ ഭക്ഷണപദാർഥങ്ങളും ശുദ്ധമാണെന്ന് അങ്ങനെ അവൻ പ്രഖ്യാപിച്ചു."},{"v":20,"t":"അവൻ തുടർന്നു: മനുഷ്യന്റെ ഉള്ളിൽനിന്നു പുറപ്പെടുന്ന കാര്യങ്ങളാണ് അവനെ അശുദ്ധനാക്കുന്നത്."},{"v":21,"t":"എന്തെന്നാൽ, ഉള്ളിൽനിന്നാണ്, മനുഷ്യരുടെ ഹൃദയത്തിൽനിന്നാണ് ദുശ്ചിന്ത, പരസംഗം, മോഷണം, കൊലപാതകം,"},{"v":22,"t":"വ്യഭിചാരം, ദുരാഗ്രഹം, ദുഷ്ടത, വഞ്ചന, ഭോഗാസക്തി, അസൂയ, ദൂഷണം, അഹങ്കാരം, മൂഢത എന്നിവ പുറപ്പെടുന്നത്."},{"v":23,"t":"ഈ തിന്മകളെല്ലാം ഉള്ളിൽനിന്നുവരുകയും മനുഷ്യനെ അശുദ്ധനാക്കുകയും ചെയ്യുന്നു."},{"h":"സീറോ-ഫിനീഷ്യൻ സ്ത്രീയുടെ വിശ്വാസം"},{"v":24,"t":"അവൻ അവിടെനിന്ന് എഴുന്നേറ്റ് ടയിർപ്രദേശത്തേക്കു പോയി. അവിടെ ഒരു വീട്ടിൽ പ്രവേശിച്ചു. തന്നെ ആരും തിരിച്ചറിയാതിരിക്കണമെന്ന് അവൻ ആഗ്രഹിച്ചു. എങ്കിലും, അവനു മറഞ്ഞിരിക്കാൻ കഴിഞ്ഞില്ല.","p":1},{"v":25,"t":"ഉടനേ, ഒരു സ്ത്രീ അവനെക്കുറിച്ചു കേട്ട് അവിടെയെത്തി. അവൾക്ക് അശുദ്ധാത്മാവു ബാധിച്ച ഒരു കൊച്ചുമകൾ ഉണ്ടായിരുന്നു. ആ സ്ത്രീ വന്ന് അവന്റെ പാദത്തിങ്കൽ വീണു."},{"v":26,"t":"അവൾ സീറോ-ഫിനീഷ്യൻ വംശത്തിൽപ്പെട്ട ഒരു ഗ്രീക്കുകാരിയായിരുന്നു. തന്റെ മകളിൽനിന്നു പിശാചിനെ ബഹിഷ്കരിക്കണമെന്ന് അവൾ അവനോട് അപേക്ഷിച്ചു."},{"v":27,"t":"അവൻ പറഞ്ഞു: ആദ്യം മക്കൾ ഭക്ഷിച്ചു തൃപ്തരാകട്ടെ. മക്കളുടെ അപ്പമെടുത്ത് നായ്ക്കൾക്ക് എറിഞ്ഞുകൊടുക്കുന്നതു നന്നല്ല."},{"v":28,"t":"അവൾ മറുപടി പറഞ്ഞു: കർത്താവേ, എങ്കിലും, മേശയ്ക്കു കീഴേനിന്ന് നായ്ക്കളും മക്കളുടെ അപ്പക്കഷണങ്ങൾ തിന്നുന്നുണ്ടല്ലോ."},{"v":29,"t":"അവൻ അവളോടു പറഞ്ഞു: ഈ വാക്കുമൂലം, നീ പൊയ്ക്കൊള്ളുക; പിശാച് നിന്റെ മകളെ വിട്ടുപോയിരിക്കുന്നു."},{"v":30,"t":"അവൾ വീട്ടിലേക്കു പോയി. കുട്ടി കട്ടിലിൽ കിടക്കുന്നത് അവൾ കണ്ടു. പിശാച് അവളെ വിട്ടുപോയിരുന്നു."},{"h":"ബധിരനെ സുഖപ്പെടുത്തുന്നു"},{"v":31,"t":"അവൻ വീണ്ടും ടയിർപ്രദേശത്തുനിന്നു പുറപ്പെട്ട്, സിദോൻ കടന്ന്, ദെക്കാപ്പോളീസ് പ്രദേശത്തുകൂടെ ഗലീലിക്കടൽത്തീരത്തേക്കുപോയി.","p":1},{"v":32,"t":"ബധിരനും മൂകനുമായ ഒരുവനെ അവർ അവന്റെയടുത്തു കൊണ്ടുവന്നു. അവന്റെമേൽ കൈകൾവയ്ക്കണമെന്ന് അവർ അവനോട് അപേക്ഷിച്ചു."},{"v":33,"t":"യേശു അവനെ ജനക്കൂട്ടത്തിൽനിന്നു തനിച്ച് മാറ്റിനിറുത്തി, അവന്റെ ചെവികളിൽ വിരലുകളിട്ടു; തുപ്പലുകൊണ്ട് അവന്റെ നാവിൽ തൊട്ടു."},{"v":34,"t":"സ്വർഗത്തിലേക്കു നോക്കി നെടുവീർപ്പിട്ടുകൊണ്ട് അവനോടു പറഞ്ഞു: എഫ്ഫാത്ത, അതായത്, തുറക്കപ്പെടട്ടെ."},{"v":35,"t":"ഉടനെ അവന്റെ ചെവികൾ തുറന്നു. നാവിന്റെ കെട്ടഴിഞ്ഞു. അവൻ സ്ഫുടമായി സംസാരിച്ചു."},{"v":36,"t":"ഇക്കാര്യം ആരോടും പറയരുതെന്ന് അവൻ അവരോടു കല്പിച്ചു. എന്നാൽ, എത്രയേറെ അവൻ കല്പിച്ചുവോ, അത്രയേറെ അവർ അതു പ്രഘോഷിച്ചു."},{"v":37,"t":"അവർ അളവറ്റ വിസ്മയത്തോടെ പറഞ്ഞു: അവൻ എല്ലാം നന്നായിച്ചെയ്യുന്നു; ബധിരർ കേൾക്കാനും ഊമകൾ സംസാരിക്കാനും ഇടയാക്കുന്നു."}],"8":[{"h":"വീണ്ടും അപ്പം വർധിപ്പിക്കുന്നു"},{"v":1,"t":"ആ ദിവസങ്ങളിൽ വീണ്ടും ഒരു വലിയ ജനക്കൂട്ടമുണ്ടായി. അവർക്കു ഭക്ഷിക്കാൻ ഒന്നുമില്ലായിരുന്നു. അവൻ ശിഷ്യന്മാരെ വിളിച്ച് അവരോടു പറഞ്ഞു:","p":1},{"v":2,"t":"ഈ ജനക്കൂട്ടത്തോട് എനിക്ക് അനുകമ്പ തോന്നുന്നു. കാരണം, ഇവർ മൂന്നു ദിവസമായി എന്നോടുകൂടെയാണ്; അവർക്കു ഭക്ഷിക്കാൻ ഒന്നുമില്ല."},{"v":3,"t":"അവരെ, വിശക്കുന്നവരായി വീട്ടിലേക്കു പറഞ്ഞയച്ചാൽ വഴിയിൽ തളർന്നുവീഴാം. അവരിൽ ചിലർ ദൂരെനിന്നു വന്നവരാണ്."},{"v":4,"t":"ശിഷ്യന്മാർ അവനോടു ചോദിച്ചു: ഈ വിജനസ്ഥലത്ത് ആർക്ക്, എവിടെനിന്ന്, ഇവർക്ക് അപ്പം കൊടുക്കാനാകും?"},{"v":5,"t":"അവൻ ചോദിച്ചു: നിങ്ങൾക്ക് എത്ര അപ്പമുണ്ട്? അവർ പറഞ്ഞു: ഏഴ്."},{"v":6,"t":"അവൻ ജനക്കൂട്ടത്തോട് നിലത്തിരിക്കാൻ ആജ്ഞാപിച്ചു. പിന്നീട്, അവൻ ആ ഏഴപ്പം എടുത്ത്, കൃതജ്ഞതാസ്തോത്രം ചെയ്ത്, മുറിച്ച്, വിളമ്പാൻ തന്റെ ശിഷ്യന്മാരെ ഏല്പിച്ചു. അവർ അതു ജനക്കൂട്ടത്തിനു വിളമ്പി."},{"v":7,"t":"കുറെ ചെറിയ മത്സ്യങ്ങളും അവർക്കുണ്ടായിരുന്നു. അവൻ അവയും വാഴ്ത്തി; വിളമ്പാൻ പറഞ്ഞു."},{"v":8,"t":"ജനക്കൂട്ടം ഭക്ഷിച്ചു തൃപ്തരായി. ശേഷിച്ച കഷണങ്ങൾ ഏഴു കുട്ട ഉണ്ടായിരുന്നു."},{"v":9,"t":"ഭക്ഷിച്ചവർ ഏകദേശം നാലായിരമായിരുന്നു. അവൻ അവരെ പറഞ്ഞയച്ചു."},{"v":10,"t":"ഉടനെ, അവൻ ശിഷ്യന്മാരോടൊപ്പം ഒരു വഞ്ചിയിൽ കയറി ദൽമാനൂത്താ പ്രദേശത്തേക്കു വന്നു."},{"h":"ഫരിസേയർ അടയാളം ആവശ്യപ്പെടുന്നു"},{"v":11,"t":"ഫരിസേയർ വന്ന് അവനുമായി തർക്കിക്കാൻ തുടങ്ങി. അവർ അവനെ പരീക്ഷിച്ചുകൊണ്ട് സ്വർഗത്തിൽനിന്ന് ഒരു അടയാളം ആവശ്യപ്പെട്ടു.","p":1},{"v":12,"t":"അവൻ ആത്മാവിൽ നെടുവീർപ്പിട്ടുകൊണ്ടു പറഞ്ഞു: എന്തുകൊണ്ടാണ് ഈ തലമുറ അടയാളമന്വേഷിക്കുന്നത്? സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ഈ തലമുറയ്ക്ക് അടയാളം നല്കപ്പെടുകയില്ല."},{"v":13,"t":"അവൻ അവരെ വിട്ട്, വീണ്ടും വഞ്ചിയിൽ കയറി മറുകരയിലേക്കുപോയി."},{"h":"ഫരിസേയരുടെ പുളിമാവ്"},{"v":14,"t":"ശിഷ്യന്മാർ അപ്പമെടുക്കാൻ മറന്നുപോയിരുന്നു. വഞ്ചിയിൽ അവരുടെ പക്കൽ ഒരപ്പമേ ഉണ്ടായിരുന്നുള്ളു.","p":1},{"v":15,"t":"അവൻ അവരെ അനുശാസിച്ചു: നിങ്ങൾ ജാഗരൂകരായിരിക്കുവിൻ. ഫരിസേയരുടെയും ഹേറോദേസിന്റെയും പുളിമാവിനെക്കുറിച്ച് കരുതലോടെയിരിക്കുവിൻ."},{"v":16,"t":"അവർക്ക് അപ്പമില്ലെന്ന് അവർ പരസ്പരം പറഞ്ഞു."},{"v":17,"t":"ഇതു മനസ്സിലാക്കിയ യേശു അവരോടു പറഞ്ഞു: നിങ്ങൾക്ക് അപ്പമില്ലാത്തതിനെക്കുറിച്ച് എന്തിനു തർക്കിക്കുന്നു? ഇനിയും നിങ്ങൾ മനസ്സിലാക്കുകയും ഗ്രഹിക്കുകയും ചെയ്യുന്നില്ലേ? നിങ്ങളുടെ ഹൃദയം കഠിനമാക്കപ്പെട്ടിരിക്കുന്നുവോ?"},{"v":18,"t":"കണ്ണുണ്ടായിട്ടും നിങ്ങൾ കാണുന്നില്ലേ? ചെവിയുണ്ടായിട്ടും നിങ്ങൾ കേൾക്കുന്നില്ലേ? നിങ്ങൾ ഓർമിക്കുന്നില്ലേ,"},{"v":19,"t":"അഞ്ചപ്പം ഞാൻ അയ്യായിരംപേർക്കായി മുറിച്ചപ്പോൾ എത്ര കുട്ടനിറയെ കഷണങ്ങൾ നിങ്ങൾ എടുത്തു? അവർ പറഞ്ഞു: പന്ത്രണ്ട്."},{"v":20,"t":"നാലായിരം പേർക്കായി ഏഴപ്പംകൊണ്ട് എത്ര കുട്ട നിറയെ കഷണങ്ങൾ നിങ്ങൾ ശേഖരിച്ചു? അവർ മറുപടി പറഞ്ഞു: ഏഴ്."},{"v":21,"t":"അവൻ ചോദിച്ചു: എന്നിട്ടും നിങ്ങൾ ഗ്രഹിക്കുന്നില്ലേ?"},{"h":"അന്ധനു കാഴ്ച"},{"v":22,"t":"പിന്നീട് അവൻ ബേത്സയ്ദായിലെത്തി. കുറെപ്പേർ ഒരു അന്ധനെ അവന്റെയടുത്തു കൊണ്ടുവന്ന്, അവനെ തൊടണമെന്ന് യേശുവിനോട് അപേക്ഷിച്ചു.","p":1},{"v":23,"t":"അവൻ അന്ധനെ കൈപിടിച്ച് ഗ്രാമത്തിനു വെളിയിലേക്കു കൊണ്ടുപോയി. അവന്റെ കണ്ണുകളിൽ തുപ്പിയശേഷം അവന്റെമേൽ കൈകൾവച്ചുകൊണ്ടു ചോദിച്ചു: നീ എന്തെങ്കിലും കാണുന്നുണ്ടോ?"},{"v":24,"t":"നോക്കിയിട്ട് അവൻ പറഞ്ഞു: ഞാൻ മനുഷ്യരെ കാണുന്നു, നടക്കുന്ന അവരെ മരങ്ങളെപ്പോലെയാണു ഞാൻ കാണുന്നത്."},{"v":25,"t":"വീണ്ടും യേശു അവന്റെ കണ്ണുകളിൽ കൈകൾവച്ചു. അവൻ ഉറ്റുനോക്കി; പൂർവസ്ഥിതിയിലായി; അവൻ എല്ലാം വ്യക്തമായി കാണുകയും ചെയ്തു."},{"v":26,"t":"ഗ്രാമത്തിൽ പ്രവേശിക്കുകപോലും ചെയ്യരുത് എന്നുപറഞ്ഞ് യേശു അവനെ വീട്ടിലേക്കയച്ചു."},{"h":"പത്രോസിന്റെ വിശ്വാസപ്രഖ്യാപനം"},{"v":27,"t":"യേശുവും ശിഷ്യന്മാരും കേസറിയാഫിലിപ്പിയിലെ ഗ്രാമങ്ങളിലേക്കു പുറപ്പെട്ടു. വഴിമധ്യേ അവൻ ശിഷ്യന്മാരോടു ചോദിച്ചു: ഞാൻ ആരെന്നാണ് ആളുകൾ പറയുന്നത്?","p":1},{"v":28,"t":"അവർ പറഞ്ഞു: ചിലർ സ്നാപകയോഹന്നാൻ എന്നും മറ്റുചിലർ ഏലിയാ എന്നും വേറേ ചിലർ പ്രവാചകന്മാരിൽ ഒരുവൻ എന്നും പറയുന്നു."},{"v":29,"t":"അവൻ ചോദിച്ചു: എന്നാൽ ഞാൻ ആരെന്നാണ് നിങ്ങൾ പറയുന്നത്? പത്രോസ് മറുപടി പറഞ്ഞു: നീ ക്രിസ്തുവാണ്."},{"v":30,"t":"തന്നെക്കുറിച്ച് ആരോടും പറയരുതെന്ന് അവൻ അവരോടു കല്പിച്ചു."},{"h":"പീഡാനുഭവവും ഉത്ഥാനവും - ഒന്നാം പ്രവചനം"},{"v":31,"t":"മനുഷ്യപുത്രൻ വളരെയേറെ സഹിക്കുകയും ശ്രേഷ്ഠന്മാർ, പുരോഹിതപ്രമുഖന്മാർ, നിയമജ്ഞർ എന്നിവരാൽ തിരസ്കരിക്കപ്പെടുകയും വധിക്കപ്പെടുകയും മൂന്നുദിവസത്തിനുശേഷം ഉയിർത്തെഴുന്നേല്ക്കുകയും ചെയ്യേണ്ടിയിരിക്കുന്നെന്ന് അവൻ അവരെ പഠിപ്പിക്കാൻ തുടങ്ങി.","p":1},{"v":32,"t":"അവൻ ഇക്കാര്യം തുറന്നുപറഞ്ഞു. അപ്പോൾ, പത്രോസ് അവനെ മാറ്റിനിറുത്തിക്കൊണ്ട് ശാസിക്കാൻ തുടങ്ങി."},{"v":33,"t":"യേശു പിൻതിരിഞ്ഞു നോക്കിയപ്പോൾ ശിഷ്യന്മാർ നില്ക്കുന്നതു കണ്ട് പത്രോസിനെ ശാസിച്ചുകൊണ്ടു പറഞ്ഞു: സാത്താനേ, നീ എന്റെ പിന്നിലേക്കു പോകൂ. നീ ചിന്തിക്കുന്നത് ദൈവത്തിന്റെ കാര്യങ്ങളല്ല, മനുഷ്യരുടേതാണ്."},{"v":34,"t":"അവൻ ശിഷ്യന്മാരോടൊപ്പം ജനക്കൂട്ടത്തെയും തന്റെ അടുത്തേക്കു വിളിച്ചുവരുത്തി അവരോടു പറഞ്ഞു: ആരെങ്കിലും എന്നെ അനുഗമിക്കാൻ ആഗ്രഹിക്കുന്നെങ്കിൽ അവൻ തന്നെത്തന്നെ പരിത്യജിച്ച് തന്റെ കുരിശെടുത്ത് എന്നെ അനുഗമിക്കട്ടെ."},{"v":35,"t":"എന്തെന്നാൽ, സ്വന്തം ജീവൻ രക്ഷിക്കാനാഗ്രഹിക്കുന്നവൻ അതു നഷ്ടപ്പെടുത്തും; ആരെങ്കിലും എനിക്കോ സുവിശേഷത്തിനോവേണ്ടി സ്വന്തം ജീവൻ നഷ്ടപ്പെടുത്തിയാൽ അവൻ അതിനെ രക്ഷിക്കും."},{"v":36,"t":"കാരണം, ഒരുവൻ ലോകം മുഴുവൻ നേടിയാലും സ്വന്തം ജീവൻ നഷ്ടപ്പെടുത്തിയാൽ അതുകൊണ്ട് അവന് എന്തു പ്രയോജനം?"},{"v":37,"t":"മനുഷ്യൻ സ്വന്തം ജീവനു പകരമായി എന്തു കൊടുക്കും?"},{"v":38,"t":"വഴിപിഴച്ചതും പാപം നിറഞ്ഞതുമായ ഈ തലമുറയിൽ എന്നെക്കുറിച്ചോ എന്റെ വചനങ്ങളെക്കുറിച്ചോ ലജ്ജിക്കുന്നവനെപ്പറ്റി മനുഷ്യപുത്രനും തന്റെ പിതാവിന്റെ മഹത്ത്വത്തിൽ വിശുദ്ധ ദൂതന്മാരോടുകൂടെ വരുമ്പോൾ ലജ്ജിക്കും."}],"9":[{"v":1,"t":"അവൻ അവരോടു പറഞ്ഞു: ദൈവരാജ്യം ശക്തിയോടെ സമാഗതമാകുന്നതു കാണുന്നതുവരെ മരിക്കുകയില്ലാത്ത ചിലർ ഇവിടെ നില്ക്കുന്നവരിലുണ്ടെന്ന് സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു.","p":1},{"h":"യേശു രൂപാന്തരപ്പെടുന്നു"},{"v":2,"t":"ആറു ദിവസം കഴിഞ്ഞ്, യേശു പത്രോസിനെയും യാക്കോബിനെയും യോഹന്നാനെയും മാത്രമായി ഒരു ഉയർന്ന മലയിലേക്കു കൊണ്ടുപോയി. അവൻ അവരുടെ മുമ്പിൽവച്ചു രൂപാന്തരപ്പെട്ടു.","p":1},{"v":3,"t":"അവന്റെ വസ്ത്രങ്ങൾ ഭൂമിയിലെ ഒരു അലക്കുകാരനും വെളുപ്പിക്കാൻ കഴിയാത്തപോലെ അത്യധികം തിളക്കമാർന്നു വെണ്മയുള്ളതായി."},{"v":4,"t":"ഏലിയായും മോശയും അവർക്കു പ്രത്യക്ഷപ്പെട്ടു. അവർ യേശുവിനോടു സംസാരിച്ചുകൊണ്ടിരുന്നു."},{"v":5,"t":"അപ്പോൾ, പത്രോസ് യേശുവിനോടു പറഞ്ഞു: ഗുരോ, നാം ഇവിടെയായിരിക്കുന്നതു നല്ലതാണ്. ഞങ്ങൾ മൂന്നുകൂടാരങ്ങൾ ഉണ്ടാക്കാം: ഒന്നു നിനക്ക്, ഒന്നു മോശയ്ക്ക്, ഒന്ന് ഏലിയായ്ക്ക്."},{"v":6,"t":"എന്താണു പറയേണ്ടതെന്ന് അവന് അറിഞ്ഞുകൂടായിരുന്നു. കാരണം, അവർ അത്രയ്ക്ക് ഭയപ്പെട്ടിരുന്നു."},{"v":7,"t":"അപ്പോൾ ഒരു മേഘം വന്ന് അവരെ ആവരണം ചെയ്തു. മേഘത്തിൽനിന്ന് ഒരു സ്വരം പുറപ്പെട്ടു: ഇവൻ എന്റെ പ്രിയപുത്രൻ; ഇവനെ ശ്രവിക്കുവിൻ."},{"v":8,"t":"പെട്ടെന്ന്, അവർ ചുറ്റുംനോക്കിയപ്പോൾ യേശുവിനെയല്ലാതെ ആരെയും തങ്ങളോടുകൂടെ കണ്ടില്ല."},{"v":9,"t":"അവർ കണ്ട കാര്യങ്ങൾ, മനുഷ്യപുത്രൻ മരിച്ചവരിൽനിന്ന് ഉയിർക്കുന്നതുവരെ ആരോടും പറയരുതെന്ന്, മലയിൽനിന്നിറങ്ങിപ്പോരുമ്പോൾ അവൻ അവരോടു കല്പിച്ചു."},{"v":10,"t":"മരിച്ചവരിൽനിന്ന് ഉയിർക്കുകയെന്നത് എന്താണെന്നു ചിന്തിച്ചുകൊണ്ട് അവർ ഈ വചനം തങ്ങളിൽത്തന്നെ സൂക്ഷിച്ചു."},{"v":11,"t":"അവർ അവനോടു ചോദിച്ചു: ഏലിയാ ആദ്യം വരേണ്ടതാണെന്ന് നിയമജ്ഞർ പറയുന്നത് എന്തുകൊണ്ടാണ്?"},{"v":12,"t":"അവൻ പറഞ്ഞു: ഏലിയാ ആദ്യമേ വന്ന് എല്ലാം പുനഃസ്ഥാപിക്കും. മനുഷ്യപുത്രൻ ഏറെ പീഡകൾ സഹിക്കുകയും നിന്ദിക്കപ്പെടുകയും ചെയ്യണമെന്ന് എഴുതപ്പെട്ടിരിക്കുന്നത് എന്തുകൊണ്ട്?"},{"v":13,"t":"എന്നാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു: ഏലിയാ വന്നുകഴിഞ്ഞു. അവനെക്കുറിച്ച് എഴുതപ്പെട്ടിരിക്കുന്നപോലെതന്നെ, തങ്ങൾക്കിഷ്ടമുള്ളതെല്ലാം അവർ അവനോടു ചെയ്തു."},{"h":"അശുദ്ധാത്മാവു ബാധിച്ച ബാലനെ സുഖപ്പെടുത്തുന്നു"},{"v":14,"t":"അവർ ശിഷ്യന്മാരുടെ അടുത്തെത്തിയപ്പോൾ വലിയ ഒരു ജനക്കൂട്ടം അവരുടെ ചുറ്റും കൂടിയിരിക്കുന്നതും നിയമജ്ഞർ അവരോടു തർക്കിച്ചുകൊണ്ടിരിക്കുന്നതും കണ്ടു.","p":1},{"v":15,"t":"അവനെ കണ്ടയുടനെ വിസ്മയഭരിതരായി ജനക്കൂട്ടം മുഴുവൻ ഓടിച്ചെന്ന് അവനെ അഭിവാദ്യം ചെയ്തു."},{"v":16,"t":"അവൻ അവരോടു ചോദിച്ചു: നിങ്ങൾ എന്താണ് അവരുമായി തർക്കിക്കുന്നത്?"},{"v":17,"t":"ജനക്കൂട്ടത്തിൽ ഒരാൾ മറുപടി പറഞ്ഞു: ഗുരോ, ഞാൻ എന്റെ മകനെ അങ്ങയുടെ അടുത്തു കൊണ്ടുവന്നിട്ടുണ്ട്. മൂകാത്മാവ് അവനെ ആവേശിച്ചിരിക്കുന്നു."},{"v":18,"t":"അത് എവിടെവച്ച് പിടികൂടിയാലും അവനെ തള്ളി വീഴ്ത്തുന്നു. അപ്പോൾ അവൻ പല്ലുകടിക്കുകയും നുരയും പതയും പുറപ്പെടുവിക്കുകയും മരവിച്ചുപോകുകയും ചെയ്യുന്നു. അതിനെ ബഹിഷ്കരിക്കാൻ അങ്ങയുടെ ശിഷ്യന്മാരോട് ഞാൻ അപേക്ഷിച്ചു; അവർക്കു കഴിഞ്ഞില്ല."},{"v":19,"t":"അവൻ അവരോടു പ്രതിവചിച്ചു: വിശ്വാസമില്ലാത്ത തലമുറയേ, എത്രനാൾ ഞാൻ നിങ്ങളോടുകൂടെയുണ്ടായിരിക്കും? എത്രനാൾ ഞാൻ നിങ്ങളെ സഹിക്കണം? അവനെ എന്റെ അടുക്കൽ കൊണ്ടുവരുക."},{"v":20,"t":"അവർ അവനെ അവന്റെ അടുക്കൽ കൊണ്ടുവന്നു. കണ്ടയുടനെ ആത്മാവ് അവനെ തള്ളിയിട്ടു. നുരയും പതയും പുറപ്പെടുവിച്ച് അവൻ നിലത്തുവീണ് ഉരുണ്ടു."},{"v":21,"t":"യേശു അവന്റെ പിതാവിനോടു ചോദിച്ചു: ഇതു തുടങ്ങിയിട്ട് എത്ര കാലമായി? അവൻ പറഞ്ഞു: ശൈശവം മുതൽ."},{"v":22,"t":"പലപ്പോഴും അത് അവനെ നശിപ്പിക്കാൻ തീയിലും വെള്ളത്തിലും വീഴ്ത്തിയിട്ടുണ്ട്. എന്തെങ്കിലും ചെയ്യാൻ നിനക്കു കഴിയുമെങ്കിൽ ഞങ്ങളുടെമേൽ മനസ്സലിഞ്ഞ് ഞങ്ങളെ സഹായിക്കണമേ!"},{"v":23,"t":"യേശു പറഞ്ഞു: കഴിയുമെങ്കിലെന്നോ! വിശ്വസിക്കുന്നവന് എല്ലാക്കാര്യങ്ങളും സാധിക്കും."},{"v":24,"t":"ഉടനെ കുട്ടിയുടെ പിതാവു വിളിച്ചുപറഞ്ഞു: ഞാൻ വിശ്വസിക്കുന്നു. എന്റെ അവിശ്വാസത്തിൽ സഹായിക്കണമേ!"},{"v":25,"t":"ജനങ്ങൾ ഓടിക്കൂടുന്നതു കണ്ട് യേശു അശുദ്ധാത്മാവിനെ ശകാരിച്ചു: മൂകനും ബധിരനുമായ ആത്മാവേ, നിന്നോടു ഞാൻ ആജ്ഞാപിക്കുന്നു, അവനിൽനിന്നു പുറത്തുപോകുക. ഇനിയൊരിക്കലും അവനിൽ പ്രവേശിക്കരുത്."},{"v":26,"t":"അപ്പോൾ അവനെ ശക്തമായി തള്ളിയിടുകയും ഉച്ചത്തിൽ നിലവിളിക്കുകയും ചെയ്തുകൊണ്ട് അത് പുറത്തുപോയി. അവൻ മൃതപ്രായനായതിനാൽ പലരും പറഞ്ഞു: അവൻ മരിച്ചുപോയി."},{"v":27,"t":"യേശു അവനെ കൈക്കുപിടിച്ചുയർത്തി; അവൻ എഴുന്നേറ്റു."},{"v":28,"t":"യേശു വീട്ടിലെത്തിയപ്പോൾ ശിഷ്യന്മാർ സ്വകാര്യമായി അവനോടു ചോദിച്ചു: എന്തുകൊണ്ടാണ് അതിനെ ബഹിഷ്കരിക്കാൻ ഞങ്ങൾക്കു കഴിയാതെപോയത്?"},{"v":29,"t":"അവൻ അവരോടു പറഞ്ഞു: പ്രാർഥനകൊണ്ടല്ലാതെ മറ്റൊന്നുകൊണ്ടും ഈ വർഗം പുറത്തുപോകുകയില്ല."},{"h":"പീഡാനുഭവവും ഉത്ഥാനവും - രണ്ടാം പ്രവചനം"},{"v":30,"t":"അവർ അവിടെനിന്നു യാത്രതിരിച്ച് ഗലീലിയിലൂടെ കടന്നുപോയി. ഇക്കാര്യം ആരും അറിയരുതെന്ന് അവൻ ആഗ്രഹിച്ചു.","p":1},{"v":31,"t":"അവനാകട്ടെ, ശിഷ്യന്മാരെ പഠിപ്പിക്കുകയായിരുന്നു. അവൻ പറഞ്ഞു: മനുഷ്യപുത്രൻ മനുഷ്യരുടെ കൈകളിൽ ഏല്പിക്കപ്പെടുകയും അവർ അവനെ വധിക്കുകയും ചെയ്യും. അവൻ വധിക്കപ്പെട്ട് മൂന്നുദിവസം കഴിയുമ്പോൾ ഉയിർത്തെഴുന്നേല്ക്കും."},{"v":32,"t":"ഈ വചനം അവർക്കു മനസ്സിലായില്ല. എങ്കിലും, അവനോടു ചോദിക്കാൻ അവർ ഭയപ്പെട്ടു."},{"h":"സ്വർഗരാജ്യത്തിലെ വലിയവൻ"},{"v":33,"t":"അവർ പിന്നീട് കഫർണാമിലെത്തി. അവൻ വീട്ടിലായിരിക്കുമ്പോൾ അവരോടു ചോദിച്ചു: വഴിയിൽവച്ച് എന്തിനെക്കുറിച്ചാണു നിങ്ങൾ തമ്മിൽ തർക്കിച്ചിരുന്നത്?","p":1},{"v":34,"t":"അവർ നിശ്ശബ്ദരായിരുന്നതേയുള്ളു. കാരണം, തങ്ങളിൽ ആരാണു വലിയവൻ എന്നതിനെക്കുറിച്ചാണ് വഴിയിൽവച്ച് അവർ തർക്കിച്ചത്."},{"v":35,"t":"അവൻ ഇരുന്നിട്ട് പന്ത്രണ്ടുപേരെയും വിളിച്ച് അവരോടു പറഞ്ഞു: ആരെങ്കിലും ഒന്നാമനാകാൻ ആഗ്രഹിക്കുന്നെങ്കിൽ അവൻ എല്ലാവരിലും അവസാനത്തെയാളും എല്ലാവരുടെയും ശുശ്രൂഷകനുമായിരിക്കട്ടെ."},{"v":36,"t":"അവൻ ഒരു ശിശുവിനെ എടുത്ത് അവരുടെ മധ്യേ നിറുത്തി, അവനെ കരങ്ങളിൽ എടുത്തുകൊണ്ടു പറഞ്ഞു:"},{"v":37,"t":"ഇതുപോലുള്ള ഒരു ശിശുവിനെ എന്റെ നാമത്തിൽ സ്വീകരിക്കുന്നവൻ എന്നെ സ്വീകരിക്കുന്നു. എന്നെ സ്വീകരിക്കുന്നവൻ എന്നെയല്ല, എന്നെ അയച്ചവനെയാണു സ്വീകരിക്കുന്നത്."},{"h":"നമുക്ക് എതിരല്ലാത്തവൻ"},{"v":38,"t":"യോഹന്നാൻ അവനോടു പറഞ്ഞു: ഗുരോ, നിന്റെ നാമത്തിൽ പിശാചുക്കളെ ബഹിഷ്കരിക്കുന്ന ഒരാളെ ഞങ്ങൾ കണ്ടു. ഞങ്ങൾ അവനെ തടഞ്ഞു. കാരണം, അവൻ നമ്മെ അനുഗമിച്ചിരുന്നില്ല.","p":1},{"v":39,"t":"യേശു പറഞ്ഞു: അവനെ തടയേണ്ടാ. ഒരുവന് എന്റെ നാമത്തിൽ അദ്ഭുതപ്രവൃത്തി ചെയ്യാനും ഉടനേ എന്നെക്കുറിച്ചു ദൂഷണം പറയാനും സാധിക്കുകയില്ല."},{"v":40,"t":"നമുക്ക് എതിരല്ലാത്തവൻ നമ്മുടെ പക്ഷത്താണ്."},{"v":41,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു: നിങ്ങൾ ക്രിസ്തുവിന്റേതാകയാൽ അവന്റെ നാമത്തിൽ ആരെങ്കിലും നിങ്ങൾക്ക് ഒരു പാത്രം വെള്ളം കുടിക്കാൻ തന്നാൽ അവന് തന്റെ പ്രതിഫലം നഷ്ടമാകുകയില്ല."},{"h":"ഇടർച്ച നല്കാതിരിക്കുക"},{"v":42,"t":"വിശ്വസിക്കുന്ന ഈ ചെറിയവരിൽ ഒരുവന് ഇടർച്ച വരുത്തുന്നവൻ ആരായാലും, അവനു കൂടുതൽ നല്ലത്, ഒരു വലിയ തിരികല്ല് കഴുത്തിൽ കെട്ടി കടലിൽ എറിയപ്പെടുന്നതാണ്.","p":1},{"v":43,"t":"നിന്റെ കൈ നിനക്ക് ഇടർച്ച വരുത്തുന്നെങ്കിൽ, അതു വെട്ടിക്കളയുക."},{"v":44,"t":"ഇരുകൈകളുമുള്ളവനായി നരകത്തിലെ കെടാത്ത അഗ്നിയിൽ നിപതിക്കുന്നതിനെക്കാൾ നല്ലത്, അംഗഹീനനായി ജീവനിലേക്കു പ്രവേശിക്കുന്നതാണ്."},{"v":45,"t":"നിന്റെ പാദം നിനക്ക് ഇടർച്ച വരുത്തുന്നെങ്കിൽ, അതു മുറിച്ചുകളയുക."},{"v":46,"t":"രണ്ടു പാദങ്ങളും ഉള്ളവനായി നരകത്തിൽ എറിയപ്പെടുന്നതിനെക്കാൾ നല്ലത്, മുടന്തനായി ജീവനിലേക്കു പ്രവേശിക്കുന്നതാണ്."},{"v":47,"t":"നിന്റെ കണ്ണ് നിനക്ക് ഇടർച്ച വരുത്തുന്നെങ്കിൽ അതു ചൂഴ്ന്നെടുത്തു കളയുക. ഇരുകണ്ണുകളുമുള്ളവനായി നരകത്തിലേക്ക് എറിയപ്പെടുന്നതിനെക്കാൾ നല്ലത്, ഒരു കണ്ണോടുകൂടെ ദൈവരാജ്യത്തിലേക്കു പ്രവേശിക്കുന്നതാണ്."},{"v":48,"t":"അവിടെ അവരുടെ പുഴു ചാകുന്നില്ല. തീ കെടുന്നുമില്ല."},{"v":49,"t":"കാരണം, എല്ലാവരും അഗ്നിയാൽ ഉറകൂട്ടപ്പെടും."},{"v":50,"t":"ഉപ്പ് നല്ലതാണ്. എന്നാൽ, ഉപ്പ് ഉറകെട്ടുപോയാൽ പിന്നെ എന്തുകൊണ്ട് അതിന് ഉറകൂട്ടും? നിങ്ങളിൽ ഉപ്പ് ഉണ്ടായിരിക്കട്ടെ. പരസ്പരം സമാധാനത്തിൽ വർത്തിക്കുകയും ചെയ്യുവിൻ."}],"10":[{"h":"വിവാഹമോചനം"},{"v":1,"t":"അവൻ എഴുന്നേറ്റ് അവിടംവിട്ട് യൂദയാപ്രദേശങ്ങളിലേക്കും ജോർദാന്റെ മറുകരയിലേക്കും പോയി. വീണ്ടും ജനക്കൂട്ടം അവന്റെയടുക്കൽ ഒരുമിച്ചുകൂടി. പതിവുപോലെ അവൻ വീണ്ടും അവരെ പഠിപ്പിച്ചു.","p":1},{"v":2,"t":"ഫരിസേയർ വന്ന് അവനെ പരീക്ഷിച്ചുകൊണ്ടു ചോദിച്ചു: ഒരുവൻ ഭാര്യയെ ഉപേക്ഷിക്കുന്നത് നിയമാനുസൃതമാണോ?"},{"v":3,"t":"അവൻ അവരോടു മറുപടി പറഞ്ഞു: മോശ എന്താണു നിങ്ങളോടു കല്പിച്ചത്?"},{"v":4,"t":"അവർ പറഞ്ഞു: മോചനപത്രമെഴുതി അവളെ ഉപേക്ഷിക്കാൻ മോശ അനുവദിച്ചിട്ടുണ്ട്."},{"v":5,"t":"യേശു അവരോടു പറഞ്ഞു: നിങ്ങളുടെ ഹൃദയകാഠിന്യംകൊണ്ടാണ് ഈ കല്പന അവൻ നിങ്ങൾക്കുവേണ്ടി എഴുതിയത്."},{"v":6,"t":"എന്നാൽ, സൃഷ്ടിയുടെ ആരംഭംമുതലേ ദൈവം അവരെ പുരുഷനും സ്ത്രീയുമായി സൃഷ്ടിച്ചു."},{"v":7,"t":"ഇക്കാരണത്താൽ, പുരുഷൻ പിതാവിനെയും മാതാവിനെയും വിടുകയും ഭാര്യയോടു ചേരുകയും ചെയ്യും."},{"v":8,"t":"അവർ ഇരുവരും ഒരു ശരീരമായിത്തീരും. തന്മൂലം, പിന്നീടൊരിക്കലും അവർ രണ്ടല്ല, ഒറ്റ ശരീരമായിരിക്കും."},{"v":9,"t":"അതിനാൽ, ദൈവം യോജിപ്പിച്ചത് മനുഷ്യൻ വേർപെടുത്താതിരിക്കട്ടെ."},{"v":10,"t":"ഇക്കാര്യത്തെക്കുറിച്ച് ശിഷ്യന്മാർ വീട്ടിൽവച്ച് വീണ്ടും അവനോടുചോദിച്ചു."},{"v":11,"t":"അവൻ അവരോടു പറഞ്ഞു: ഒരുവൻ തന്റെ ഭാര്യയെ ഉപേക്ഷിച്ച് മറ്റൊരുവളെ വിവാഹം ചെയ്യുമ്പോൾ അവളുമായി വ്യഭിചാരം ചെയ്യുന്നു."},{"v":12,"t":"ഒരുവൾ തന്റെ ഭർത്താവിനെ ഉപേക്ഷിച്ച് മറ്റൊരാളെ വിവാഹം ചെയ്യുമ്പോൾ അവളും വ്യഭിചാരം ചെയ്യുന്നു."},{"h":"ശിശുക്കളെ അനുഗ്രഹിക്കുന്നു"},{"v":13,"t":"അവൻ തൊടുന്നതിനുവേണ്ടി ശിശുക്കളെ അവന്റെ അടുക്കൽ അവർ കൊണ്ടുവന്നു. ശിഷ്യന്മാരാകട്ടെ, അവരെ ശകാരിച്ചു.","p":1},{"v":14,"t":"ഇതു കണ്ടപ്പോൾ യേശു അമർഷംപൂണ്ട് അവരോടു പറഞ്ഞു: ശിശുക്കൾ എന്റെയടുത്തുവരാൻ അനുവദിക്കുവിൻ. അവരെ തടയരുത്. എന്തെന്നാൽ, ദൈവരാജ്യം അവരെപ്പോലുള്ളവരുടേതാണ്."},{"v":15,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ശിശുവിനെപ്പോലെ ദൈവരാജ്യം സ്വീകരിക്കാത്ത ആരും അതിൽ പ്രവേശിക്കുകയില്ല."},{"v":16,"t":"അവൻ ശിശുക്കളെ എടുത്ത്, അവരുടെമേൽ കൈകൾവച്ച് അനുഗ്രഹിച്ചു."},{"h":"ധനികനും ദൈവരാജ്യവും"},{"v":17,"t":"യേശു വഴിയിലേക്കിറങ്ങിയപ്പോൾ ഒരുവൻ ഓടിവന്ന് അവന്റെ മുമ്പിൽ മുട്ടുകുത്തി ചോദിച്ചു: നല്ലവനായ ഗുരോ, നിത്യജീവൻ അവകാശമാക്കാൻ ഞാൻ എന്തുചെയ്യണം?","p":1},{"v":18,"t":"യേശു അവനോടു ചോദിച്ചു: എന്തുകൊണ്ടാണ് നീ എന്നെ നല്ലവൻ എന്നുവിളിക്കുന്നത്? ദൈവം ഒരുവനല്ലാതെ നല്ലവനായി ആരുമില്ല."},{"v":19,"t":"പ്രമാണങ്ങൾ നിനക്കറിയാമല്ലോ: കൊല്ലരുത്, വ്യഭിചാരം ചെയ്യരുത്, മോഷ്ടിക്കരുത്, കള്ളസാക്ഷ്യം നല്കരുത്, വഞ്ചിക്കരുത്, പിതാവിനെയും മാതാവിനെയും ബഹുമാനിക്കുക."},{"v":20,"t":"അവൻ പറഞ്ഞു: ഗുരോ, എന്റെ ചെറുപ്പംമുതൽ ഞാൻ ഇവയെല്ലാം പാലിക്കുന്നുണ്ട്."},{"v":21,"t":"യേശു അവനെ നോക്കി, സ്നേഹംതോന്നി അവനോടു പറഞ്ഞു: ഒരു കാര്യം നിനക്കു കുറവുണ്ട്. പോയി നിനക്കുള്ളതെല്ലാം വിറ്റ് ദരിദ്രർക്കു കൊടുക്കുക. അപ്പോൾ സ്വർഗത്തിൽ നിനക്കു നിക്ഷേപമുണ്ടാകും. പിന്നെ വന്ന് എന്നെ അനുഗമിക്കുക."},{"v":22,"t":"ഈ വചനം മൂലം മുഖംവാടി അവൻ സങ്കടത്തോടെ തിരിച്ചുപോയി. കാരണം, അവന് വളരെയേറെ സമ്പത്തുണ്ടായിരുന്നു."},{"v":23,"t":"യേശു ചുറ്റും നോക്കി തന്റെ ശിഷ്യരോടു പറഞ്ഞു: സമ്പന്നർ ദൈവരാജ്യത്തിൽ പ്രവേശിക്കുക എത്രയോ ദുഷ്കരം!"},{"v":24,"t":"അവന്റെ വാക്കുകളിൽ ശിഷ്യന്മാർ വിസ്മയിച്ചു. യേശു വീണ്ടും അവരോടു പറഞ്ഞു: മക്കളേ, ദൈവരാജ്യത്തിൽ പ്രവേശിക്കുക എത്രയോ ദുഷ്കരം!"},{"v":25,"t":"ധനവാൻ ദൈവരാജ്യത്തിൽ പ്രവേശിക്കുന്നതിനെക്കാൾ എളുപ്പം, ഒട്ടകം സൂചിക്കുഴയിലൂടെ കടക്കുന്നതാണ്."},{"v":26,"t":"അവർ അത്യന്തം വിസ്മയഭരിതരായി തങ്ങളോടുതന്നെ ചോദിച്ചു: അങ്ങനെയെങ്കിൽ, രക്ഷിക്കപ്പെടാൻ ആർക്കാണ് സാധ്യമാകുക?"},{"v":27,"t":"യേശു അവരെ നോക്കി പറഞ്ഞു: മനുഷ്യർക്ക് ഇത് അസാധ്യമാണ്; എന്നാൽ ദൈവത്തിന് അല്ല. എന്തെന്നാൽ, ദൈവത്തിന് എല്ലാം സാധ്യമാണ്."},{"v":28,"t":"പത്രോസ് അവനോടു പറയാൻ തുടങ്ങി: ഇതാ, എല്ലാം ഉപേക്ഷിച്ച് ഞങ്ങൾ നിന്നെ അനുഗമിച്ചിരിക്കുന്നു."},{"v":29,"t":"യേശു പ്രതിവചിച്ചു: സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, എന്നെപ്രതിയും സുവിശേഷത്തെപ്രതിയും ഭവനത്തെയോ സഹോദരന്മാരെയോ സഹോദരിമാരെയോ മാതാവിനെയോ പിതാവിനെയോ മക്കളെയോ വയലുകളെയോ ത്യജിക്കുന്നവരിലാർക്കും","p":1},{"v":30,"t":"ഇവിടെ വച്ചുതന്നെ നൂറിരട്ടി ലഭിക്കാതിരിക്കില്ല. ഭവനങ്ങളും സഹോദരന്മാരും സഹോദരിമാരും മാതാക്കളും മക്കളും വയലുകളും അവയോടൊപ്പം പീഡനങ്ങളും വരാനിരിക്കുന്ന യുഗത്തിൽ നിത്യജീവനും."},{"v":31,"t":"എന്നാൽ, മുമ്പന്മാരിൽ പലരും പിമ്പന്മാരാകും; പിമ്പന്മാരിൽ പലരും മുമ്പന്മാരും."},{"h":"പീഡാനുഭവവും ഉത്ഥാനവും - മൂന്നാം പ്രവചനം"},{"v":32,"t":"അവർ ജറുസലേമിലേക്കുള്ള വഴിയേ കയറിപ്പോകുകയായിരുന്നു. യേശു അവരുടെ മുമ്പിൽ നടന്നിരുന്നു. അവർ വിസ്മയിച്ചു. അനുയാത്ര ചെയ്തിരുന്നവർ ഭയപ്പെടുകയും ചെയ്തു. അവൻ പന്ത്രണ്ടുപേരെയും വീണ്ടും അടുത്തു വിളിച്ച്, തനിക്കു സംഭവിക്കാനിരിക്കുന്ന കാര്യങ്ങൾ പറയാൻതുടങ്ങി.","p":1},{"v":33,"t":"ഇതാ, നമ്മൾ ജറുസലേമിലേക്കു പോകുന്നു. മനുഷ്യപുത്രൻ പുരോഹിതപ്രമുഖന്മാർക്കും നിയമജ്ഞന്മാർക്കും ഏല്പിക്കപ്പെടും. അവർ അവനെ മരണത്തിനു വിധിക്കുകയും ജനതകൾക്ക് ഏല്പിച്ചുകൊടുക്കുകയും ചെയ്യും."},{"v":34,"t":"അവർ അവനെ പരിഹസിക്കുകയും അവന്റെമേൽ തുപ്പുകയും അവനെ ചമ്മട്ടികൊണ്ടടിക്കുകയും വധിക്കുകയും ചെയ്യും. മൂന്നുദിവസത്തിനുശേഷം അവൻ ഉയിർത്തെഴുന്നേല്ക്കും."},{"h":"സെബദിപുത്രന്മാരുടെ അഭ്യർഥന"},{"v":35,"t":"സെബദിപുത്രന്മാരായ യാക്കോബും യോഹന്നാനും അവനെ സമീപിച്ച് അപേക്ഷിച്ചു: ഗുരോ, ഞങ്ങൾ അങ്ങയോട് അപേക്ഷിക്കുന്നതെന്തും ഞങ്ങൾക്കു ചെയ്തുതരണമെന്ന് ഞങ്ങൾ ആഗ്രഹിക്കുന്നു.","p":1},{"v":36,"t":"അവൻ അവരോടു ചോദിച്ചു: നിങ്ങൾക്കുവേണ്ടി ഞാൻ എന്തുചെയ്യണമെന്നാണ് നിങ്ങൾ ആഗ്രഹിക്കുന്നത്?"},{"v":37,"t":"അവർ പറഞ്ഞു: അങ്ങയുടെ മഹത്ത്വത്തിൽ ഞങ്ങളിൽ ഒരാൾ അങ്ങയുടെ വലത്തുവശത്തും മറ്റേയാൾ ഇടത്തുവശത്തും ഉപവിഷ്ടരാകാൻ അനുവദിക്കണമേ!"},{"v":38,"t":"യേശു അവരോടു പ്രതിവചിച്ചു: നിങ്ങൾ ചോദിക്കുന്നത് എന്താണെന്നു നിങ്ങൾ അറിയുന്നില്ല. ഞാൻ കുടിക്കുന്ന പാനപാത്രം കുടിക്കാനോ ഞാൻ സ്വീകരിക്കുന്ന സ്നാനം സ്വീകരിക്കാനോ നിങ്ങൾക്കു കഴിയുമോ?"},{"v":39,"t":"അവർ മറുപടി പറഞ്ഞു: ഞങ്ങൾക്കു കഴിയും. യേശു അവരോടു പറഞ്ഞു: ഞാൻ കുടിക്കുന്ന പാനപാത്രം നിങ്ങൾ കുടിക്കും; ഞാൻ സ്വീകരിക്കുന്ന സ്നാനം നിങ്ങൾ സ്വീകരിക്കും."},{"v":40,"t":"എന്നാൽ, എന്റെ വലത്തുവശത്തോ ഇടത്തുവശത്തോ ഇരിക്കാൻ അനുവദിക്കേണ്ടത് ഞാനല്ല. അത് ഒരുക്കപ്പെട്ടവർക്കു വേണ്ടിയുള്ളതാണ്."},{"v":41,"t":"ഇതുകേട്ടപ്പോൾ ബാക്കി പത്തുപേർക്കും യാക്കോബിനോടും യോഹന്നാനോടും അമർഷം തോന്നി."},{"v":42,"t":"യേശു അവരെ അടുത്തു വിളിച്ചു പറഞ്ഞു: വിജാതീയരെ ഭരിക്കുന്നു എന്നു കരുതുന്നവർ അവരുടെമേൽ ആധിപത്യം പുലർത്തുന്നെന്നും അവരുടെ പ്രമാണിമാർ അവരുടെമേൽ അധികാരം പ്രയോഗിക്കുന്നെന്നും നിങ്ങൾക്കറിയാമല്ലോ."},{"v":43,"t":"എന്നാൽ, നിങ്ങളുടെയിടയിൽ അങ്ങനെയാകരുത്. പ്രത്യുത, നിങ്ങളിൽ വലിയവനാകാൻ ആഗ്രഹിക്കുന്നവൻ നിങ്ങളുടെ ശുശ്രൂഷകനായിരിക്കണം."},{"v":44,"t":"നിങ്ങളിൽ ഒന്നാമനാകാൻ ആഗ്രഹിക്കുന്നവൻ എല്ലാവരുടെയും ദാസനുമായിരിക്കണം."},{"v":45,"t":"കാരണം, മനുഷ്യപുത്രൻ വന്നിരിക്കുന്നത്, ശുശ്രൂഷിക്കപ്പെടാനല്ല, ശുശ്രൂഷിക്കാനും സ്വന്തം ജീവൻ അനേകർക്കുവേണ്ടി മോചനദ്രവ്യമായി നല്കാനുമത്രേ."},{"h":"ബർതിമേയൂസിനു കാഴ്ച"},{"v":46,"t":"അവർ ജറീക്കോയിലെത്തി. അവൻ ശിഷ്യരോടും വലിയ ഒരു ജനാവലിയോടുംകൂടെ ജറീക്കോ വിട്ടുപോകുമ്പോൾ തിമേയൂസിന്റെ പുത്രനായ ബർതിമേയൂസ് എന്ന അന്ധയാചകൻ വഴിയരികിൽ ഇരിപ്പുണ്ടായിരുന്നു.","p":1},{"v":47,"t":"നസറായനായ യേശുവാണു പോകുന്നതെന്നു കേട്ടപ്പോൾ അവൻ ഉച്ചത്തിൽ വിളിച്ചുപറയാൻ തുടങ്ങി: ദാവീദിന്റെ പുത്രനായ യേശുവേ, എന്നിൽ കനിയണമേ!"},{"v":48,"t":"നിശ്ശബ്ദനായിരിക്കാൻ പലരും അവനെ ശാസിച്ചു. എന്നാൽ, അവൻ കൂടുതൽ ഉച്ചത്തിൽ വിളിച്ചുകൊണ്ടിരുന്നു: ദാവീദിന്റെ പുത്രാ, എന്നിൽ കനിയണമേ!"},{"v":49,"t":"യേശു നിന്നിട്ടു പറഞ്ഞു: അവനെ വിളിക്കുക. അവർ അന്ധനെ വിളിച്ച് അവനോടു പറഞ്ഞു: ധൈര്യത്തോടെയിരിക്കൂ, എഴുന്നേല്ക്കുക; യേശു നിന്നെ വിളിക്കുന്നു."},{"v":50,"t":"അവൻ തന്റെ പുറങ്കുപ്പായം ദൂരേയെറിഞ്ഞ്, കുതിച്ചുചാടിക്കൊണ്ട് യേശുവിന്റെ അടുത്തെത്തി."},{"v":51,"t":"യേശു അവനോടു ചോദിച്ചു: ഞാൻ നിനക്കുവേണ്ടി എന്തുചെയ്യണമെന്നാണ് നീ ആഗ്രഹിക്കുന്നത്? അന്ധൻ അവനോടു പറഞ്ഞു: ഗുരോ, എനിക്കു കാഴ്ച വീണ്ടുകിട്ടണം."},{"v":52,"t":"യേശു പറഞ്ഞു: നീ പൊയ്ക്കൊള്ളുക, നിന്റെ വിശ്വാസം നിന്നെ രക്ഷിച്ചിരിക്കുന്നു. തത്ക്ഷണം അവനു കാഴ്ച ലഭിക്കുകയും വഴിയിൽ അവനെ അനുഗമിക്കുകയും ചെയ്തു."}],"11":[{"h":"രാജകീയപ്രവേശം"},{"v":1,"t":"അവർ ജറുസലേമിനടുത്ത്, ഒലിവുമലയ്ക്കു സമീപമുള്ള ബേത്ഫഗെയിലും ബഥാനിയായിലും എത്തിയപ്പോൾ അവൻ രണ്ടു ശിഷ്യന്മാരെ അയച്ചുകൊണ്ട്","p":1},{"v":2,"t":"അവരോടു പറഞ്ഞു: എതിരേ കാണുന്ന ഗ്രാമത്തിലേക്കു ചെല്ലുവിൻ. അതിൽ പ്രവേശിക്കുമ്പോൾത്തന്നെ, ആരും ഒരിക്കലും കയറിയിട്ടില്ലാത്ത ഒരു കഴുതക്കുട്ടിയെ കെട്ടിയിരിക്കുന്നതു കാണും. അതിനെ അഴിച്ചുകൊണ്ടുവരുവിൻ."},{"v":3,"t":"നിങ്ങളെന്തിനാണ് ഇങ്ങനെ ചെയ്യുന്നതെന്ന് ആരെങ്കിലും ചോദിച്ചാൽ പറയുക: കർത്താവിന് അതിനെക്കൊണ്ട് ആവശ്യമുണ്ട്; ഉടനെ അതിനെ തിരിച്ചയയ്ക്കുന്നതാണ്."},{"v":4,"t":"അവർ പോയി, തെരുവിൽ ഒരു പടിവാതില്ക്കൽ ഒരു കഴുതക്കുട്ടിയെ കെട്ടിയിരിക്കുന്നതു കണ്ടു. അവർ അതിനെ അഴിക്കുമ്പോൾ"},{"v":5,"t":"അവിടെ നിന്നിരുന്നവരിൽ ചിലർ അവരോടു ചോദിച്ചു: നിങ്ങളെന്തിനാണ് കഴുതക്കുട്ടിയെ അഴിക്കുന്നത്?"},{"v":6,"t":"യേശു പറഞ്ഞതുപോലെ ശിഷ്യന്മാർ മറുപടി പറഞ്ഞു. അവർ അവരെ അനുവദിച്ചു."},{"v":7,"t":"അവർ കഴുതക്കുട്ടിയെ യേശുവിന്റെ അടുത്തു കൊണ്ടുവന്ന്, അതിന്റെ പുറത്ത് തങ്ങളുടെ വസ്ത്രങ്ങൾ വിരിച്ചു. അവൻ അതിന്മേൽ കയറിയിരുന്നു."},{"v":8,"t":"വളരെയാളുകൾ തെരുവീഥിയിൽ തങ്ങളുടെ വസ്ത്രങ്ങൾ വിരിച്ചു; മറ്റുള്ളവരാകട്ടെ, വയലിൽനിന്ന് മുറിച്ച പച്ചിലക്കൊമ്പുകളും."},{"v":9,"t":"അവന്റെ മുമ്പിലും പിമ്പിലും നടന്നിരുന്നവർ വിളിച്ചുപറഞ്ഞു: ഹോസാന! കർത്താവിന്റെ നാമത്തിൽ വരുന്നവൻ അനുഗൃഹീതൻ!"},{"v":10,"t":"നമ്മുടെ പിതാവായ ദാവീദിന്റെ വരാനിരിക്കുന്ന രാജ്യം അനുഗൃഹീതം! ഉന്നതങ്ങളിൽ ഹോസാന!"},{"v":11,"t":"അവൻ ജറുസലേമിൽ പ്രവേശിച്ച് ദേവാലയത്തിനുള്ളിലേക്കു പോയി. ചുറ്റുംനോക്കി എല്ലാം കണ്ടശേഷം, നേരം വൈകിയിരുന്നതിനാൽ, പന്ത്രണ്ടുപേരോടുംകൂടെ ബഥാനിയായിലേക്കു പോയി."},{"h":"അത്തിവൃക്ഷത്തെ ശപിക്കുന്നു"},{"v":12,"t":"അടുത്ത ദിവസം അവർ ബഥാനിയായിൽനിന്നു വരുമ്പോൾ അവനു വിശന്നു.","p":1},{"v":13,"t":"അകലെ, ഇലകളുള്ള ഒരു അത്തിമരം കണ്ട് അതിൽ എന്തെങ്കിലും കാണും എന്നു വിചാരിച്ച് അടുത്തുചെന്നു. എന്നാൽ, ഇലകളല്ലാതെ മറ്റൊന്നും കണ്ടില്ല. അത് അത്തിപ്പഴങ്ങളുടെ കാലമല്ലായിരുന്നു."},{"v":14,"t":"അവൻ പറഞ്ഞു: ആരും ഇനിയൊരിക്കലും നിന്നിൽനിന്നു പഴം തിന്നാതിരിക്കട്ടെ! അവന്റെ ശിഷ്യന്മാർ ഇതുകേട്ടു."},{"h":"ദേവാലയശുദ്ധീകരണം"},{"v":15,"t":"അവർ ജറുസലേമിലെത്തി. അവൻ ദേവാലയത്തിൽ പ്രവേശിച്ച്, അവിടെ ക്രയവിക്രയം ചെയ്തുകൊണ്ടിരുന്നവരെ പുറത്താക്കാൻ തുടങ്ങി. നാണയമാറ്റക്കാരുടെ മേശകളും പ്രാവുവില്പനക്കാരുടെ ഇരിപ്പിടങ്ങളും അവൻ തട്ടിമറിച്ചിട്ടു.","p":1},{"v":16,"t":"ദേവാലയത്തിലൂടെ പാത്രങ്ങൾ ചുമന്നുകൊണ്ടുപോകാൻ ആരെയും അവൻ അനുവദിച്ചില്ല."},{"v":17,"t":"പഠിപ്പിച്ചുകൊണ്ട് അവൻ അവരോടു പറഞ്ഞു: എന്റെ ഭവനം എല്ലാ ജനതകൾക്കുമുള്ള പ്രാർഥനാലയം എന്നു വിളിക്കപ്പെടും എന്ന് എഴുതപ്പെട്ടിട്ടില്ലേ? എന്നാൽ, നിങ്ങൾ അതിനെ കവർച്ചക്കാരുടെ ഗുഹയാക്കിത്തീർത്തിരിക്കുന്നു."},{"v":18,"t":"പുരോഹിതപ്രമുഖന്മാരും നിയമജ്ഞരും ഇതു കേട്ട്, അവനെ എങ്ങനെ നശിപ്പിക്കാമെന്ന് അന്വേഷിച്ചു; കാരണം, അവനെ അവർ ഭയപ്പെട്ടു. ജനക്കൂട്ടം മുഴുവൻ അവന്റെ പ്രബോധനങ്ങളെക്കുറിച്ച് വിസ്മയിച്ചിരുന്നു."},{"v":19,"t":"വൈകുന്നേരമായപ്പോൾ അവർ നഗരത്തിനു വെളിയിലേക്കു പോയി."},{"h":"വിശ്വാസത്തിന്റെ ശക്തി"},{"v":20,"t":"അവർ രാവിലെ അത്തിമരത്തിന്റെ സമീപത്തുകൂടെ കടന്നുപോകുമ്പോൾ അതു സമൂലം ഉണങ്ങിപ്പോയിരിക്കുന്നതു കണ്ടു.","p":1},{"v":21,"t":"അപ്പോൾ അവനെ അനുസ്മരിപ്പിച്ചുകൊണ്ട് പത്രോസ് പറഞ്ഞു: ഗുരോ, നോക്കൂ, നീ ശപിച്ച അത്തിമരം ഉണങ്ങിപ്പോയിരിക്കുന്നു!"},{"v":22,"t":"യേശു അവരോടു പ്രതിവചിച്ചു: ദൈവത്തിൽ വിശ്വാസമുള്ളവരായിരിക്കുക."},{"v":23,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ആരെങ്കിലും ഈ മലയോട് ഉയർന്ന് കടലിൽ പതിക്കട്ടെ എന്നുപറയുകയും ഹൃദയത്തിൽ സംശയിക്കാതെ, താൻ പറയുന്നതു സംഭവിക്കുമെന്നു വിശ്വസിക്കുകയും ചെയ്താൽ അവന് അതു സാധിച്ചുകിട്ടും."},{"v":24,"t":"അതിനാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു: പ്രാർഥിക്കുകയും യാചിക്കുകയും ചെയ്യുന്ന എന്തും ലഭിക്കുമെന്നു വിശ്വസിക്കുവിൻ; അതു നിങ്ങൾക്കു സാധിച്ചുകിട്ടും."},{"v":25,"t":"നിങ്ങൾ പ്രാർഥിച്ചുകൊണ്ടു നില്ക്കുമ്പോൾ നിങ്ങൾക്ക് ആരോടെങ്കിലും എന്തെങ്കിലും വിരോധമുണ്ടെങ്കിൽ, ക്ഷമിക്കുവിൻ."},{"v":26,"t":"അപ്പോൾ സ്വർഗത്തിലുള്ള നിങ്ങളുടെ പിതാവ് നിങ്ങളുടെ തെറ്റുകളും ക്ഷമിക്കും."},{"h":"യേശുവിന്റെ അധികാരം"},{"v":27,"t":"അവർ വീണ്ടും ജറുസലേമിൽ വന്നു. അവൻ ദേവാലയത്തിലൂടെ നടക്കുമ്പോൾ പുരോഹിതപ്രമുഖന്മാരും നിയമജ്ഞരും ശ്രേഷ്ഠന്മാരും അവന്റെ അടുത്തെത്തി.","p":1},{"v":28,"t":"അവർ അവനോടു ചോദിച്ചു: എന്തധികാരത്താലാണ് നീ ഇവയൊക്കെ ചെയ്യുന്നത്? ഇവ ചെയ്യുന്നതിന് ആരാണ് നിനക്ക് ഈ അധികാരം നല്കിയത്?"},{"v":29,"t":"യേശു അവരോടു പറഞ്ഞു: ഞാൻ നിങ്ങളോട് ഒരു കാര്യം ചോദിക്കാം. എന്നോട് ഉത്തരം പറയുവിൻ. എങ്കിൽ, എന്തധികാരത്താലാണ് ഞാൻ ഇവ ചെയ്യുന്നതെന്നു പറയാം."},{"v":30,"t":"യോഹന്നാന്റെ സ്നാനം സ്വർഗത്തിൽനിന്നോ മനുഷ്യരിൽനിന്നോ? ഉത്തരം പറയുവിൻ."},{"v":31,"t":"അവർ പരസ്പരം ആലോചിച്ചു: സ്വർഗത്തിൽനിന്ന് എന്നു പറഞ്ഞാൽ, പിന്നെ എന്തുകൊണ്ട് നിങ്ങൾ അവനെ വിശ്വസിച്ചില്ല എന്ന് അവൻ ചോദിക്കും."},{"v":32,"t":"എന്നാൽ, മനുഷ്യരിൽനിന്ന് എന്നു പറഞ്ഞാലോ? അവർക്കു ജനക്കൂട്ടത്തെ ഭയമായിരുന്നു. കാരണം, യോഹന്നാൻ യഥാർഥത്തിൽ ഒരു പ്രവാചകനാണെന്ന് എല്ലാവരും കരുതിയിരുന്നു."},{"v":33,"t":"അതിനാൽ, അവർ യേശുവിനോടു പറഞ്ഞു: ഞങ്ങൾക്ക് അറിഞ്ഞുകൂടാ. അപ്പോൾ യേശു പറഞ്ഞു: എന്തധികാരത്താലാണ് ഞാൻ ഇവ ചെയ്യുന്നതെന്ന് ഞാനും നിങ്ങളോടു പറയുന്നില്ല."}],"12":[{"h":"മുന്തിരിത്തോട്ടത്തിലെ കൃഷിക്കാർ"},{"v":1,"t":"യേശു അവരോട് ഉപമകൾവഴി സംസാരിക്കാൻ തുടങ്ങി. ഒരു മനുഷ്യൻ ഒരു മുന്തിരിത്തോട്ടം നട്ടുപിടിപ്പിച്ചു; അതിനുചുറ്റും വേലികെട്ടി; മുന്തിരിച്ചക്കു സ്ഥാപിച്ചു; ഒരു ഗോപുരവും പണിതു. അതു കൃഷിക്കാരെ പാട്ടത്തിനേല്പിച്ചിട്ട് അവൻ യാത്രപോയി.","p":1},{"v":2,"t":"സമയമായപ്പോൾ മുന്തിരിഫലങ്ങളിൽനിന്ന് തന്റെ ഓഹരി ശേഖരിക്കാൻ അവൻ കൃഷിക്കാരുടെ അടുത്തേക്കു ഭൃത്യനെ അയച്ചു."},{"v":3,"t":"എന്നാൽ, അവർ അവനെ പിടിച്ച് അടിക്കുകയും വെറുംകൈയോടെ പറഞ്ഞയയ്ക്കുകയും ചെയ്തു."},{"v":4,"t":"വീണ്ടും അവൻ മറ്റൊരു ഭൃത്യനെ അയച്ചു. അവർ അവനെ തലയ്ക്കു പരിക്കേല്പിക്കുകയും അപമാനിച്ചയയ്ക്കുകയും ചെയ്തു."},{"v":5,"t":"അവൻ വീണ്ടും ഒരുവനെ അയച്ചു. അവനെ അവർ കൊന്നുകളഞ്ഞു. മറ്റു പലരെയും അയച്ചു. ചിലരെ അവർ അടിക്കുകയും ചിലരെ കൊല്ലുകയും ചെയ്തു."},{"v":6,"t":"അവന് ഇനി ഒരുവൻ മാത്രം അവശേഷിച്ചു - തന്റെ പ്രിയപുത്രൻ. എന്റെ പുത്രനെ അവർ മാനിക്കും എന്നു പറഞ്ഞ് അവസാനം അവനെയും അവരുടെയടുത്തേക്ക് അയച്ചു."},{"v":7,"t":"കൃഷിക്കാർ പരസ്പരം പറഞ്ഞു: ഇവനാണ് അവകാശി; വരൂ, ഇവനെ നമുക്കു കൊന്നുകളയാം; അവകാശം നമ്മുടേതാകും."},{"v":8,"t":"അവർ അവനെ പിടിച്ചുകൊന്ന് മുന്തിരിത്തോട്ടത്തിനു വെളിയിലേക്കെറിഞ്ഞു."},{"v":9,"t":"ഇനി മുന്തിരിത്തോട്ടത്തിന്റെ ഉടമസ്ഥൻ എന്തു ചെയ്യും? അവൻ വന്ന് ആ കൃഷിക്കാരെ നശിപ്പിച്ച് മുന്തിരിത്തോട്ടം വേറെ ആളുകളെ ഏല്പിക്കും."},{"v":10,"t":"ഈ വിശുദ്ധ ലിഖിതം നിങ്ങൾ വായിച്ചിട്ടില്ലേ? പണിക്കാർ ഉപേക്ഷിച്ച കല്ലുതന്നെ മൂലക്കല്ലായിത്തീർന്നു."},{"v":11,"t":"ഇതു കർത്താവിന്റെ പ്രവൃത്തിയാണ്. നമ്മുടെ ദൃഷ്ടിയിൽ ഇത് അദ്ഭുതകരമായിരിക്കുന്നു."},{"v":12,"t":"തങ്ങൾക്കെതിരേയാണ് ഈ ഉപമ അവൻ പറഞ്ഞതെന്നു മനസ്സിലാക്കി അവർ അവനെ പിടിക്കാൻ ശ്രമിച്ചു. എന്നാൽ, ജനക്കൂട്ടത്തെ അവർ ഭയപ്പെട്ടു. അതുകൊണ്ട്, അവർ അവനെ വിട്ടുപോയി.","p":1},{"h":"സീസറിനു നികുതി"},{"v":13,"t":"അവനെ വാക്കിൽ കുടുക്കുന്നതിനുവേണ്ടി കുറെ ഫരിസേയരെയും ഹേറോദ്യരെയും അവർ അവന്റെ അടുത്തേക്കയച്ചു.","p":1},{"v":14,"t":"അവർ വന്ന് അവനോടു പറഞ്ഞു: ഗുരോ, നീ സത്യവാനാണെന്നും ആരാലും സ്വാധീനിക്കപ്പെടാത്തവനാണെന്നും ആരുടെയും മുഖംനോക്കാതെ നിർഭയം ദൈവത്തിന്റെ വഴി സത്യമായി പഠിപ്പിക്കുന്നവനാണെന്നും ഞങ്ങൾ അറിയുന്നു. സീസറിനു നികുതി കൊടുക്കുന്നതു നിയമാനുസൃതമോ അല്ലയോ? ഞങ്ങൾ കൊടുക്കണമോ വേണ്ടയോ?"},{"v":15,"t":"അവരുടെ കാപട്യം മനസ്സിലാക്കി അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ എന്തിന് എന്നെ പരീക്ഷിക്കുന്നു? ഒരു ദനാറ എന്റെയടുത്തു കൊണ്ടുവരുക. ഞാൻ കാണട്ടെ."},{"v":16,"t":"അവർ അതു കൊണ്ടുവന്നപ്പോൾ അവൻ അവരോടു ചോദിച്ചു: ഈ രൂപവും ലിഖിതവും ആരുടേതാണ്? അവർ അവനോടു പറഞ്ഞു: സീസറിന്റേത്."},{"v":17,"t":"യേശു അവരോടു പറഞ്ഞു: സീസറിനുള്ളതു സീസറിനും ദൈവത്തിനുള്ളതു ദൈവത്തിനും കൊടുക്കുക. അപ്പോൾ, അവർ അവനെക്കുറിച്ച് വിസ്മയിച്ചു."},{"h":"ഉത്ഥാനത്തെക്കുറിച്ചു വിവാദം"},{"v":18,"t":"അനന്തരം, ഉത്ഥാനം ഇല്ല എന്നു പറഞ്ഞിരുന്ന സദുക്കായർ അവനെ സമീപിച്ചു ചോദിച്ചു:","p":1},{"v":19,"t":"ഗുരോ, ഒരുവൻ സന്താനമില്ലാതെ മരിക്കുകയും ഭാര്യ ജീവിച്ചിരിക്കുകയും ചെയ്യുന്നെങ്കിൽ അവന്റെ സഹോദരൻ അവളെ ഭാര്യയായി സ്വീകരിച്ച്, അവനുവേണ്ടി സന്താനങ്ങളെ ഉത്പാദിപ്പിക്കണമെന്ന് മോശ എഴുതിയിട്ടുണ്ട്."},{"v":20,"t":"ഒരിടത്ത് ഏഴു സഹോദരന്മാരുണ്ടായിരുന്നു. ഒന്നാമൻ ഒരുവളെ വിവാഹംചെയ്തു. അവൻ സന്താനമില്ലാതെ മരിച്ചു."},{"v":21,"t":"രണ്ടാമൻ അവളെ സ്വീകരിച്ചു. അവനും സന്താനമില്ലാതെ മരിച്ചു. മൂന്നാമനും അങ്ങനെതന്നെ."},{"v":22,"t":"ഇങ്ങനെ ഏഴുപേരും സന്താനമില്ലാതെ മരിച്ചു. ഏറ്റവും അവസാനം ആ സ്ത്രീയും മരിച്ചു."},{"v":23,"t":"ഉത്ഥാനത്തിൽ, അവർ ഉയിർത്തെഴുന്നേല്ക്കുമ്പോൾ, അവൾ ആരുടെ ഭാര്യയായിരിക്കും? കാരണം, അവൾ ഏഴുപേരുടെയും ഭാര്യയായിരുന്നല്ലോ."},{"v":24,"t":"യേശു അവരോടു പറഞ്ഞു: വിശുദ്ധലിഖിതങ്ങളോ ദൈവത്തിന്റെ ശക്തിയോ അറിയാത്തതുകൊണ്ടല്ലേ, നിങ്ങൾക്കു തെറ്റുപറ്റുന്നത്?"},{"v":25,"t":"എന്തെന്നാൽ, മരിച്ചവരിൽനിന്ന് ഉയിർത്തെഴുന്നേല്ക്കുമ്പോൾ അവർ വിവാഹം ചെയ്യുകയോ ചെയ്തുകൊടുക്കുകയോ ഇല്ല. മറിച്ച്, അവർ സ്വർഗത്തിലെ ദൂതന്മാരെപ്പോലെയാണ്."},{"v":26,"t":"മരിച്ചവർ ഉയിർത്തെഴുന്നേല്ക്കുന്നതിനെക്കുറിച്ച്, ദൈവം മുൾപ്പടർപ്പിൽനിന്ന് മോശയോട് അരുൾചെയ്തതെന്താണെന്ന് മോശയുടെ പുസ്തകത്തിൽ നിങ്ങൾ വായിച്ചിട്ടില്ലേ? അവിടന്നു പറഞ്ഞു: ഞാൻ അബ്രാഹത്തിന്റെ ദൈവവും ഇസഹാക്കിന്റെ ദൈവവും യാക്കോബിന്റെ ദൈവവുമാണ്."},{"v":27,"t":"അവിടന്ന് മരിച്ചവരുടെ ദൈവമല്ല, പ്രത്യുത, ജീവിക്കുന്നവരുടെയാണ്. നിങ്ങൾക്കു വലിയ തെറ്റുപറ്റിയിരിക്കുന്നു."},{"h":"സുപ്രധാനകല്പനകൾ"},{"v":28,"t":"ഒരു നിയമജ്ഞൻ വന്ന് അവരുടെ വിവാദം കേട്ടു. അവൻ നന്നായി അവരോട് ഉത്തരം പറയുന്നെന്നു മനസ്സിലാക്കി അവനോടു ചോദിച്ചു: എല്ലാറ്റിലും പ്രഥമമായ കല്പന ഏതാണ്?","p":1},{"v":29,"t":"യേശു പ്രതിവചിച്ചു: ഒന്നാമത്തേത് ഇതാണ്: ഇസ്രായേലേ, കേൾക്കുക! നമ്മുടെ ദൈവമായ കർത്താവ് ഏക കർത്താവാണ്."},{"v":30,"t":"നീ നിന്റെ ദൈവമായ കർത്താവിനെ നിന്റെ പൂർണഹൃദയത്തോടും പൂർണാത്മാവോടും പൂർണമനസ്സോടും പൂർണശക്തിയോടുംകൂടെ സ്നേഹിക്കുക."},{"v":31,"t":"രണ്ടാമത്തേത് ഇതാണ്: നിന്നെപ്പോലെതന്നെ നിന്റെ അയല്ക്കാരനെയും സ്നേഹിക്കുക. ഇവയെക്കാൾ വലിയ കല്പന വേറേയില്ല."},{"v":32,"t":"നിയമജ്ഞൻ അവനോടു പറഞ്ഞു: ഗുരോ, ശരിതന്നെ. അങ്ങു സത്യമായി പറഞ്ഞു; അവിടന്ന് ഏകനാണെന്നും അവിടന്നല്ലാതെ വേറൊരുവനില്ലെന്നും"},{"v":33,"t":"അവിടത്തെ പൂർണഹൃദയത്തോടും പൂർണമനസ്സോടും പൂർണശക്തിയോടുംകൂടെ സ്നേഹിക്കുന്നതും തന്നെപ്പോലെതന്നെ അയല്ക്കാരനെ സ്നേഹിക്കുന്നതും എല്ലാ ദഹനബലികളെയും യാഗങ്ങളെയുംകാൾ മഹനീയമാണെന്നും."},{"v":34,"t":"അവൻ ബുദ്ധിപൂർവം മറുപടിപറഞ്ഞു എന്നു മനസ്സിലാക്കി യേശു പറഞ്ഞു: നീ ദൈവരാജ്യത്തിൽനിന്ന് അകലെയല്ല. പിന്നീട് യേശുവിനോട് ആരും ഒന്നും ചോദിക്കാൻ മുതിർന്നില്ല."},{"h":"ക്രിസ്തു ദാവീദിന്റെ പുത്രൻ"},{"v":35,"t":"ദേവാലയത്തിൽ പഠിപ്പിച്ചുകൊണ്ടിരുന്നപ്പോൾ യേശു ചോദിച്ചു: ക്രിസ്തു, ദാവീദിന്റെ പുത്രനാണെന്ന് നിയമജ്ഞർ പറയുന്നതെങ്ങനെ?","p":1},{"v":36,"t":"പരിശുദ്ധാത്മാവിൽ ദാവീദുതന്നെ പറഞ്ഞിട്ടുണ്ട്: കർത്താവ് എന്റെ കർത്താവിനോട് അരുൾചെയ്തു, ഞാൻ നിന്റെ ശത്രുക്കളെ നിന്റെ പാദങ്ങൾക്കു കീഴിലാക്കുവോളം നീ എന്റെ വലത്തുഭാഗത്ത് ഉപവിഷ്ടനാകുക."},{"v":37,"t":"ദാവീദുതന്നെ അവനെ കർത്താവ് എന്നു വിളിക്കുന്നു. പിന്നെ എങ്ങനെയാണ് അവൻ അവന്റെ പുത്രനാകുന്നത്? വലിയ ജനക്കൂട്ടം സന്തോഷപൂർവം അവനെ ശ്രവിച്ചു."},{"h":"നിയമജ്ഞരെ വിമർശിക്കുന്നു"},{"v":38,"t":"അവൻ ഇങ്ങനെ പഠിപ്പിച്ചു: നിങ്ങൾ നിയമജ്ഞരെ സൂക്ഷിച്ചുകൊള്ളുവിൻ. നീണ്ടമേലങ്കികൾ ധരിച്ചുനടക്കാൻ അവർ ആഗ്രഹിക്കുന്നു; കൂടാതെ, പൊതുസ്ഥലങ്ങളിൽ അഭിവാദ്യവും","p":1},{"v":39,"t":"സിനഗോഗുകളിൽ ഉന്നതപീഠങ്ങളും വിരുന്നുകളിൽ പ്രമുഖസ്ഥാനങ്ങളും."},{"v":40,"t":"എന്നാൽ, അവർ വിധവകളുടെ ഭവനങ്ങൾ വിഴുങ്ങുകയും ദീർഘമായി പ്രാർഥിക്കുന്നെന്നു നടിക്കുകയും ചെയ്യുന്നു. ഇവർക്ക് കൂടുതൽ കഠിനമായ ശിക്ഷാവിധി ലഭിക്കും."},{"h":"വിധവയുടെ കാണിക്ക"},{"v":41,"t":"അവൻ ഭണ്ഡാരത്തിന് എതിർവശത്തിരുന്ന് ജനക്കൂട്ടം ഭണ്ഡാരത്തിൽ നാണയത്തുട്ടുകൾ ഇടുന്നതു ശ്രദ്ധിച്ചു. പല ധനവാന്മാരും അധികം നിക്ഷേപിച്ചു.","p":1},{"v":42,"t":"അപ്പോൾ, ദരിദ്രയായ ഒരു വിധവ വന്ന് ചില്ലിക്കാശിന്റെ രണ്ടു ചെമ്പുനാണയങ്ങൾ ഇട്ടു."},{"v":43,"t":"അവൻ തന്റെ ശിഷ്യന്മാരെ അടുത്തുവിളിച്ച് അവരോടു പറഞ്ഞു: സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ഭണ്ഡാരത്തിൽ ഇട്ട എല്ലാവരെയുംകാൾ കൂടുതലായി ഈ ദരിദ്രവിധവ ഇട്ടിരിക്കുന്നു."},{"v":44,"t":"എന്തെന്നാൽ, അവരെല്ലാവരും തങ്ങളുടെ സമൃദ്ധിയിൽനിന്ന് ഇട്ടു. ഇവളാകട്ടെ, തന്റെ ദാരിദ്ര്യത്തിൽനിന്ന് തനിക്കുണ്ടായിരുന്നതെല്ലാം, തന്റെ ഉപജീവനത്തിനുള്ള വക മുഴുവനും, ഇട്ടിരിക്കുന്നു."}],"13":[{"h":"ദേവാലയത്തിന്റെ നാശത്തെക്കുറിച്ച്"},{"v":1,"t":"യേശു ദേവാലയത്തിൽനിന്നു പുറത്തുവന്നപ്പോൾ, ശിഷ്യന്മാരിൽ ഒരുവൻ പറഞ്ഞു: ഗുരോ, നോക്കൂ, എത്ര വലിയ കല്ലുകൾ! എത്ര വലിയ സൗധങ്ങൾ!","p":1},{"v":2,"t":"യേശു അവനോടു പറഞ്ഞു: ഈ മഹാസൗധങ്ങൾ നീ കാണുന്നില്ലേ? എന്നാൽ ഇവിടെ കല്ലിന്മേൽ കല്ലു ശേഷിക്കാതെ എല്ലാം തകർക്കപ്പെടും."},{"h":"വേദനകളുടെ ആരംഭം"},{"v":3,"t":"അനന്തരം, അവൻ ഒലിവുമലയിൽ ദേവാലയത്തിനഭിമുഖമായി ഇരിക്കുമ്പോൾ, പത്രോസും യാക്കോബും യോഹന്നാനും അന്ത്രയോസും അവനോടു സ്വകാര്യമായി ചോദിച്ചു:","p":1},{"v":4,"t":"ഇത് എന്നു സംഭവിക്കുമെന്നും ഇവയെല്ലാം പൂർത്തിയാകാൻ തുടങ്ങുമ്പോൾ അടയാളം എന്തായിരിക്കുമെന്നും ഞങ്ങളോടു പറയുക."},{"v":5,"t":"യേശു അവരോടു പറയാൻ തുടങ്ങി: ആരും നിങ്ങളെ വഴിതെറ്റിക്കാതിരിക്കാൻ സൂക്ഷിച്ചുകൊള്ളുവിൻ."},{"v":6,"t":"ഞാനാണ് എന്നുപറഞ്ഞ് പലരും എന്റെ നാമത്തിൽ വരും. അവർ അനേകരെ വഴിതെറ്റിക്കും."},{"v":7,"t":"നിങ്ങൾ യുദ്ധങ്ങളെപ്പറ്റി കേൾക്കും; യുദ്ധവാർത്തകളും. അപ്പോൾ നിങ്ങൾ അസ്വസ്ഥരാകരുത്. ഇതെല്ലാം സംഭവിക്കേണ്ടതാണ്. എന്നാൽ, അത് അവസാനമല്ല."},{"v":8,"t":"ജനത ജനതയ്ക്കെതിരായും രാജ്യം രാജ്യത്തിനെതിരായും അണിനിരക്കും. പല സ്ഥലങ്ങളിലും ഭൂകമ്പവും ക്ഷാമവുമുണ്ടാകും. ഇതെല്ലാം ഈറ്റുനോവിന്റെ ആരംഭമാണ്."},{"v":9,"t":"നിങ്ങളാകട്ടെ, ജാഗരൂകരായിരിക്കുവിൻ. അവർ നിങ്ങളെ ന്യായാധിപസംഘങ്ങൾക്ക് ഏല്പിച്ചുകൊടുക്കും. സിനഗോഗുകളിൽവച്ച് നിങ്ങൾ പ്രഹരിക്കപ്പെടും. ദേശാധിപതികളുടെയും രാജാക്കന്മാരുടെയും മുമ്പാകെ എന്നെപ്രതി അവർക്കു സാക്ഷ്യത്തിനായി നിങ്ങൾ നില്ക്കും."},{"v":10,"t":"എന്നാൽ, ആദ്യം എല്ലാ ജനതകളോടും സുവിശേഷം പ്രസംഗിക്കപ്പെടേണ്ടിയിരിക്കുന്നു."},{"v":11,"t":"അവർ നിങ്ങളെ ഏല്പിച്ചുകൊടുക്കാൻ കൊണ്ടുപോകുമ്പോൾ എന്തു പറയണം എന്നു വിചാരിച്ച് ഉത്കണ്ഠാകുലരാകേണ്ടാ. ആ സമയത്തു നിങ്ങൾക്കു നല്കപ്പെടുന്നതെന്തോ അതു സംസാരിക്കുവിൻ. കാരണം, നിങ്ങളല്ല സംസാരിക്കുന്നത്, പരിശുദ്ധാത്മാവാണ്."},{"v":12,"t":"സഹോദരൻ സഹോദരനെ മരണത്തിനേല്പിച്ചു കൊടുക്കും; പിതാവു പുത്രനെയും. മക്കൾ മാതാപിതാക്കന്മാർക്കെതിരേ തിരിയുകയും അവരെ വധിക്കുകയും ചെയ്യും."},{"v":13,"t":"എന്റെ നാമത്തെപ്രതി നിങ്ങൾ എല്ലാവരാലും വെറുക്കപ്പെടും. അവസാനംവരെ സഹിച്ചുനില്ക്കുന്നവൻ രക്ഷിക്കപ്പെടും."},{"h":"ഭീകരദുരിതങ്ങളുടെ കാലം"},{"v":14,"t":"വിനാശത്തിന്റെ മ്ലേച്ഛത നില്ക്കരുതാത്തിടത്തു നില്ക്കുന്നതു നിങ്ങൾ കാണുമ്പോൾ - വായിക്കുന്നവൻ ഗ്രഹിച്ചുകൊള്ളട്ടെ - യൂദയായിലുള്ളവർ പർവതങ്ങളിലേക്കു പലായനംചെയ്യുക.","p":1},{"v":15,"t":"പുരമുകളിലായിരിക്കുന്നവൻ താഴെ ഇറങ്ങുകയോ വീട്ടിൽനിന്ന് എന്തെങ്കിലും എടുക്കാൻ അകത്തു പ്രവേശിക്കുകയോ അരുത്."},{"v":16,"t":"വയലിലായിരിക്കുന്നവൻ തന്റെ മേലങ്കി എടുക്കാൻ പിന്തിരിയരുത്."},{"v":17,"t":"ആ ദിവസങ്ങളിൽ ഗർഭിണികൾക്കും മുലയൂട്ടുന്നവർക്കും ദുരിതം."},{"v":18,"t":"ഇതു ശീതകാലത്തു സംഭവിക്കാതിരിക്കാൻ പ്രാർഥിക്കുവിൻ."},{"v":19,"t":"ദൈവത്തിന്റെ സൃഷ്ടികർമത്തിന്റെ ആരംഭംമുതൽ ഇന്നുവരെ ഉണ്ടായിട്ടില്ലാത്തതും ഇനിയൊരിക്കലും ഉണ്ടാകാനിടയില്ലാത്തതുമായ കഷ്ടതകൾ ആ ദിവസങ്ങളിൽ ഉണ്ടാകും."},{"v":20,"t":"കർത്താവ് ആ ദിവസങ്ങൾ ചുരുക്കിയില്ലായിരുന്നെങ്കിൽ ഒരുവനും രക്ഷിക്കപ്പെടുകയില്ലായിരുന്നു. എന്നാൽ, ദൈവം നിർണയിച്ച തിരഞ്ഞെടുക്കപ്പെട്ടവർക്കുവേണ്ടി അവിടന്ന് ആ ദിവസങ്ങൾ ചുരുക്കി."},{"v":21,"t":"ഇതാ, ക്രിസ്തു ഇവിടെ; അതാ, അവിടെ എന്ന് ആരെങ്കിലും അപ്പോൾ പറഞ്ഞാൽ, നിങ്ങൾ വിശ്വസിക്കരുത്."},{"v":22,"t":"കാരണം, കള്ളക്രിസ്തുമാരും വ്യാജപ്രവാചകന്മാരും ഉയർന്നുവരും. സാധ്യമെങ്കിൽ, തിരഞ്ഞെടുക്കപ്പെട്ടവരെ വഴിതെറ്റിക്കുന്നതിന് അടയാളങ്ങളും അദ്ഭുതങ്ങളും അവർ പ്രവർത്തിക്കും."},{"v":23,"t":"എന്നാൽ, നിങ്ങൾ ജാഗരൂകരായിരിക്കുവിൻ. എല്ലാം ഞാൻ മുൻകൂട്ടി നിങ്ങളോടു പറഞ്ഞിരിക്കുന്നു."},{"h":"മനുഷ്യപുത്രന്റെ ആഗമനം"},{"v":24,"t":"എന്നാൽ, ആ ക്ലേശങ്ങൾക്കുശേഷമുള്ള ദിവസങ്ങളിൽ സൂര്യൻ ഇരുണ്ടുപോകും. ചന്ദ്രൻ അതിന്റെ പ്രകാശം തരുകയില്ല.","p":1},{"v":25,"t":"നക്ഷത്രങ്ങൾ ആകാശത്തുനിന്നു നിപതിക്കും. ആകാശശക്തികൾ ഇളകുകയും ചെയ്യും."},{"v":26,"t":"അപ്പോൾ മനുഷ്യപുത്രൻ വലിയ ശക്തിയോടും മഹത്ത്വത്തോടുംകൂടെ മേഘങ്ങളിൽ വരുന്നത് അവർ കാണും."},{"v":27,"t":"അപ്പോൾ, അവൻ ദൂതന്മാരെ അയയ്ക്കും. അവൻ ഭൂമിയുടെ അതിർത്തികൾ മുതൽ ആകാശത്തിന്റെ അതിർത്തികൾവരെ നാലു ദിക്കുകളിലുംനിന്ന് അവന്റെ തിരഞ്ഞെടുക്കപ്പെട്ടവരെ ഒരുമിച്ചുകൂട്ടും."},{"v":28,"t":"അത്തിമരത്തിൽനിന്ന് ഒരു ഉപമ പഠിക്കുവിൻ. അതിന്റെ കൊമ്പുകൾ ഇളതായി തളിർക്കുമ്പോൾ വേനല്ക്കാലം അടുത്തിരിക്കുന്നെന്നു നിങ്ങൾക്കറിയാം."},{"v":29,"t":"അതുപോലെതന്നെ, ഇക്കാര്യങ്ങൾ സംഭവിക്കുന്നതു കാണുമ്പോൾ അവൻ സമീപത്ത്, വാതില്ക്കലെത്തിയിരിക്കുന്നെന്ന് ഗ്രഹിച്ചുകൊള്ളുക."},{"v":30,"t":"ഞാൻ സത്യമായി നിങ്ങളോടു പറയുന്നു: ഇവയെല്ലാം സംഭവിക്കുന്നതുവരെ ഈ തലമുറ കടന്നുപോകുകയില്ല."},{"v":31,"t":"ആകാശവും ഭൂമിയും കടന്നുപോകും. എന്നാൽ, എന്റെ വചനങ്ങൾ കടന്നുപോകുകയില്ല."},{"h":"സദാ ജാഗരൂകരായിരിക്കുവിൻ"},{"v":32,"t":"എന്നാൽ, ആ ദിവസത്തെയോ ആ മണിക്കൂറിനെയോ കുറിച്ച് പിതാവിനല്ലാതെ മറ്റാർക്കും, സ്വർഗത്തിലുള്ള ദൂതന്മാർക്കോ പുത്രനുപോലുമോ, അറിഞ്ഞുകൂടാ.","p":1},{"v":33,"t":"ശ്രദ്ധിക്കുവിൻ; ഉണർന്നിരിക്കുവിൻ. സമയം എപ്പോഴാണെന്ന് നിങ്ങൾക്കറിവില്ലല്ലോ."},{"v":34,"t":"തന്റെ വീടുവിട്ട് യാത്രപോകുന്ന ഒരുവൻ സേവകർക്ക് അധികാരവും ഓരോ ആൾക്കും അവന്റെ ജോലിയും നല്കുന്നതും വാതിൽ കാവല്ക്കാരനോട് ഉണർന്നിരിക്കാൻ കല്പിക്കുന്നതും പോലെയാണിത്."},{"v":35,"t":"ആകയാൽ, ജാഗരൂകരായിരിക്കുവിൻ. എന്തെന്നാൽ, ഗൃഹനാഥൻ എപ്പോൾ വരുമെന്ന്, സന്ധ്യയ്ക്കോ അർധരാത്രിക്കോ കോഴികൂകുമ്പോഴോ രാവിലെയോ എന്ന്, നിങ്ങൾക്കറിഞ്ഞുകൂടാ."},{"v":36,"t":"പെട്ടെന്നു കയറിവരുമ്പോൾ നിങ്ങളെ നിദ്രാധീനരായി അവൻ കാണാതിരിക്കട്ടെ."},{"v":37,"t":"ഞാൻ നിങ്ങളോടു പറയുന്നത് എല്ലാവരോടുമായി പറയുന്നു: ജാഗരൂകരായിരിക്കുവിൻ."}],"14":[{"h":"യേശുവിനെ വധിക്കാൻ ആലോചന"},{"v":1,"t":"രണ്ടുദിവസങ്ങൾക്കുശേഷം പെസഹായും പുളിപ്പില്ലാത്ത അപ്പത്തിന്റെ തിരുനാളുമായിരുന്നു. യേശുവിനെ ചതിയിൽ പിടികൂടി വധിക്കേണ്ടത് എങ്ങനെയെന്ന് പുരോഹിതപ്രമുഖന്മാരും നിയമജ്ഞരും അന്വേഷിച്ചുകൊണ്ടിരുന്നു.","p":1},{"v":2,"t":"അവർ പറഞ്ഞു: ജനങ്ങൾ ബഹളമുണ്ടാക്കാതിരിക്കാൻ തിരുനാളിൽ വേണ്ട."},{"h":"ബഥാനിയായിലെ തൈലാഭിഷേകം"},{"v":3,"t":"അവൻ ബഥാനിയായിൽ കുഷ്ഠരോഗിയായ ശിമയോന്റെ വീട്ടിൽ ഭക്ഷണത്തിനിരിക്കേ, ഒരു വെൺകൽഭരണിയിൽ വിലയേറിയ ശുദ്ധ നാർദീൻ സുഗന്ധതൈലവുമായി ഒരു സ്ത്രീ അവിടെ വന്നു. അവൾ ഭരണി പൊട്ടിച്ചുതുറന്ന് അവന്റെ ശിരസ്സിൽ ഒഴിച്ചു.","p":1},{"v":4,"t":"അവിടെയുണ്ടായിരുന്ന ചിലർ അമർഷത്തോടെ പരസ്പരം പറഞ്ഞു: ഈ തൈലം പാഴാക്കിക്കളഞ്ഞതെന്തിന്?"},{"v":5,"t":"കാരണം, ഇത് മുന്നൂറിലധികം ദനാറയ്ക്കു വിറ്റ് ദരിദ്രർക്കു കൊടുക്കാമായിരുന്നല്ലോ. അവർ അവളെ കുറ്റപ്പെടുത്തി."},{"v":6,"t":"യേശു പറഞ്ഞു: ഇവളെ വിട്ടേക്കുക. എന്തിന് ഇവളെ വിഷമിപ്പിക്കുന്നു? ഇവൾ എനിക്കുവേണ്ടി ഒരു നല്ല പ്രവൃത്തി ചെയ്തിരിക്കുന്നു."},{"v":7,"t":"ദരിദ്രർ എപ്പോഴും നിങ്ങളോടുകൂടെയുണ്ട്. ആഗ്രഹിക്കുമ്പോഴൊക്കെ അവർക്കു നന്മചെയ്യാൻ നിങ്ങൾക്കു സാധിക്കും. ഞാനാകട്ടെ, എപ്പോഴും നിങ്ങളോടുകൂടെ ഉണ്ടായിരിക്കുകയില്ല."},{"v":8,"t":"ഇവൾക്കു സാധിക്കുന്നത് ഇവൾ ചെയ്തു. എന്റെ സംസ്കാരത്തിനുവേണ്ടി ഇവൾ എന്റെ ശരീരം മുൻകൂട്ടി തൈലം പൂശുകയാണു ചെയ്തത്."},{"v":9,"t":"ഞാൻ സത്യമായി നിങ്ങളോടു പറയുന്നു: ലോകത്തെവിടെയെല്ലാം സുവിശേഷം പ്രസംഗിക്കപ്പെടുമോ, അവിടെയെല്ലാം ഇവൾ ചെയ്തതും ഇവളുടെ സ്മരണയ്ക്കായി പ്രസ്താവിക്കപ്പെടും."},{"h":"യൂദാസിന്റെ വഞ്ചന"},{"v":10,"t":"പന്ത്രണ്ടുപേരിൽ ഒരുവനായ യൂദാസ് സ്കറിയോത്താ അവനെ അവർക്ക് ഒറ്റിക്കൊടുക്കാൻവേണ്ടി പുരോഹിതപ്രമുഖന്മാരുടെ അടുത്തുചെന്നു.","p":1},{"v":11,"t":"അവർ അതുകേട്ടു സന്തോഷിച്ച്, അവനു പണം കൊടുക്കാമെന്നു വാഗ്ദാനം ചെയ്തു. അവനെ എങ്ങനെ ഒറ്റിക്കൊടുക്കാമെന്നുവിചാരിച്ച് അവൻ, പറ്റിയ അവസരം പാർത്തിരുന്നു."},{"h":"പെസഹാ ആചരിക്കുന്നു"},{"v":12,"t":"പെസഹാബലി അർപ്പിക്കുന്ന പുളിപ്പില്ലാത്ത അപ്പത്തിന്റെ ഒന്നാം ദിവസം, അവന്റെ ശിഷ്യന്മാർ അവനോടു ചോദിച്ചു: നിനക്ക് പെസഹാ ഭക്ഷിക്കേണ്ടതിന് എവിടെപ്പോയി ഞങ്ങൾ ഒരുക്കണമെന്നാണ് നീ ആഗ്രഹിക്കുന്നത്?","p":1},{"v":13,"t":"അവൻ തന്റെ രണ്ടുശിഷ്യന്മാരെ അയച്ചുകൊണ്ടു പറഞ്ഞു: നിങ്ങൾ നഗരത്തിലേക്കു ചെല്ലുക. ഒരുകുടം വെള്ളം ചുമന്നുകൊണ്ടുവരുന്ന ഒരു മനുഷ്യൻ നിങ്ങളെ കാണും. അവനെ അനുഗമിക്കുക."},{"v":14,"t":"അവൻ എവിടെ ചെന്നുകയറുന്നുവോ അവിടത്തെ ഗൃഹനാഥനോടു പറയുക: ഗുരു ചോദിക്കുന്നു, ഞാൻ എന്റെ ശിഷ്യന്മാരുമൊത്ത് പെസഹാ ഭക്ഷിക്കുന്നതിന് എന്റെ വിരുന്നുശാല എവിടെയാണ്?"},{"v":15,"t":"സജ്ജീകൃതമായ ഒരു വലിയ മാളികമുറി അവൻ കാണിച്ചുതരും. അവിടെ നമുക്കുവേണ്ടി ഒരുക്കുക."},{"v":16,"t":"ശിഷ്യന്മാർ പുറപ്പെട്ട് നഗരത്തിലെത്തി, അവൻ അവരോടു പറഞ്ഞിരുന്നപോലെ കണ്ടു. അവർ പെസഹാ ഒരുക്കി."},{"v":17,"t":"സന്ധ്യയായപ്പോൾ അവൻ പന്ത്രണ്ടുപേരുമൊരുമിച്ചു വന്നു."},{"v":18,"t":"അവർ പന്തിയിൽ ഭക്ഷിച്ചുകൊണ്ടിരിക്കുമ്പോൾ യേശു പറഞ്ഞു: ഞാൻ സത്യമായി നിങ്ങളോടു പറയുന്നു: എന്നോടൊപ്പം ഭക്ഷണം കഴിക്കുന്ന നിങ്ങളിലൊരുവൻ എന്നെ ഒറ്റിക്കൊടുക്കും."},{"v":19,"t":"അവർ ദുഃഖിതരാകാനും ഓരോരുത്തരും അവനോടു ചോദിക്കാനും തുടങ്ങി: ഞാനല്ലല്ലോ?"},{"v":20,"t":"അവൻ അവരോടു പറഞ്ഞു: പന്ത്രണ്ടിൽ ഒരുവൻ. എന്നോടൊപ്പം പാത്രത്തിൽ കൈമുക്കുന്നവൻ."},{"v":21,"t":"എന്തെന്നാൽ, മനുഷ്യപുത്രൻ തന്നെക്കുറിച്ച് എഴുതപ്പെട്ടിരിക്കുന്നപോലെ കടന്നുപോകുന്നു. എന്നാൽ, ആരാൽ മനുഷ്യപുത്രൻ ഒറ്റിക്കൊടുക്കപ്പെടുന്നുവോ, ആ മനുഷ്യനു ദുരിതം! ആ മനുഷ്യൻ ജനിക്കാതിരുന്നെങ്കിൽ അവനു നന്നായിരുന്നു."},{"h":"പുതിയ ഉടമ്പടി"},{"v":22,"t":"അവർ ഭക്ഷിച്ചുകൊണ്ടിരുന്നപ്പോൾ യേശു അപ്പമെടുത്ത്, ആശീർവദിച്ച്, മുറിച്ച്, അവർക്കു നല്കിക്കൊണ്ട് അരുൾചെയ്തു: സ്വീകരിക്കുവിൻ; ഇത് എന്റെ ശരീരമാണ്.","p":1},{"v":23,"t":"അനന്തരം, പാനപാത്രമെടുത്ത്, കൃതജ്ഞതാസ്തോത്രം ചെയ്ത്, അവർക്കു നല്കി. എല്ലാവരും അതിൽനിന്നു പാനംചെയ്തു."},{"v":24,"t":"അവൻ അവരോട് അരുൾചെയ്തു: ഇത് അനേകർക്കുവേണ്ടി ചിന്തപ്പെടുന്ന, ഉടമ്പടിയുടെ എന്റെ രക്തമാണ്."},{"v":25,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, ദൈവരാജ്യത്തിൽ ഞാൻ ഇതു നവമായി പാനം ചെയ്യുന്ന ആ ദിവസംവരെ മുന്തിരിയുടെ ഫലത്തിൽനിന്ന് ഇനി ഞാൻ കുടിക്കുകയില്ല."},{"v":26,"t":"സ്തോത്രഗീതം ആലപിച്ചശേഷം അവർ ഒലിവുമലയിലേക്കു പോയി."},{"h":"പത്രോസ് ഗുരുവിനെ നിഷേധിക്കും"},{"v":27,"t":"യേശു അവരോടു പറഞ്ഞു: നിങ്ങളെല്ലാവരും ഇടറിപ്പോകും. എന്തെന്നാൽ ഇങ്ങനെ എഴുതപ്പെട്ടിരിക്കുന്നു: ഞാൻ ഇടയനെ അടിക്കും; ആടുകൾ ചിതറിക്കപ്പെടും.","p":1},{"v":28,"t":"എന്നാൽ, ഞാൻ ഉയിർപ്പിക്കപ്പെട്ടശേഷം നിങ്ങൾക്കുമുമ്പേ ഗലീലിയിലേക്കു പോകും."},{"v":29,"t":"അപ്പോൾ, പത്രോസ് പറഞ്ഞു: എല്ലാവരും ഇടറിയാലും ഞാൻ ഇടറുകയില്ല."},{"v":30,"t":"യേശു അവനോടു പറഞ്ഞു: സത്യമായി ഞാൻ നിന്നോടു പറയുന്നു, ഇന്ന്, ഈ രാത്രിയിൽത്തന്നെ, കോഴി രണ്ടു പ്രാവശ്യം കൂകുന്നതിനുമുമ്പ് മൂന്നുപ്രാവശ്യം നീ എന്നെ നിഷേധിച്ചുപറയും."},{"v":31,"t":"അവൻ ആവർത്തിച്ചു പറഞ്ഞു: നിന്നോടുകൂടെ മരിക്കേണ്ടിവന്നാലും ഞാൻ നിന്നെ നിഷേധിക്കുകയില്ല. അങ്ങനെതന്നെ എല്ലാവരും പറഞ്ഞു."},{"h":"ഗത്സെമനിയിൽ പ്രാർഥിക്കുന്നു"},{"v":32,"t":"അവർ ഗത്സെമനി എന്നു പേരുള്ള സ്ഥലത്തെത്തി. അവൻ തന്റെ ശിഷ്യന്മാരോടു പറഞ്ഞു: ഞാൻ പ്രാർഥിക്കുമ്പോൾ നിങ്ങൾ ഇവിടെ ഇരിക്കുവിൻ.","p":1},{"v":33,"t":"അവൻ പത്രോസിനെയും യാക്കോബിനെയും യോഹന്നാനെയും തന്റെ കൂടെക്കൊണ്ടുപോയി, ആകുലനാകാനും അസ്വസ്ഥനാകാനും തുടങ്ങി."},{"v":34,"t":"അവൻ അവരോടു പറഞ്ഞു: എന്റെ ആത്മാവ് മരണത്തോളം അതിദുഃഖിതമായിരിക്കുന്നു. നിങ്ങൾ ഇവിടെ ഉണർന്നിരിക്കുവിൻ."},{"v":35,"t":"അവൻ അല്പദൂരം മുന്നോട്ടു ചെന്ന്, നിലത്തുവീണ്, സാധ്യമെങ്കിൽ ആ മണിക്കൂർ തന്നെ കടന്നുപോകട്ടെ എന്നു പ്രാർഥിച്ചു."},{"v":36,"t":"അവൻ പറഞ്ഞു: അബ്ബാ, പിതാവേ, എല്ലാം അങ്ങേക്കു സാധ്യമാണ്. ഈ പാനപാത്രം എന്നിൽനിന്നു മാറ്റിത്തരണമേ! എന്നാൽ ഞാൻ ആഗ്രഹിക്കുന്നതല്ല, പ്രത്യുത, അങ്ങ് ആഗ്രഹിക്കുന്നത്."},{"v":37,"t":"അനന്തരം അവൻ വന്ന്, അവർ ഉറങ്ങുന്നതു കണ്ട്, പത്രോസിനോടു ചോദിച്ചു: ശിമയോനേ, നീ ഉറങ്ങുന്നുവോ? ഒരു മണിക്കൂർ ഉണർന്നിരിക്കാൻ നിനക്കു ശക്തിയില്ലേ?"},{"v":38,"t":"പ്രലോഭനത്തിൽ അകപ്പെടാതിരിക്കാൻ ഉണർന്നിരുന്നു പ്രാർഥിക്കുവിൻ. ആത്മാവ് സന്നദ്ധമെങ്കിലും ശരീരം ബലഹീനമാണ്."},{"v":39,"t":"അവൻ വീണ്ടും പോയി, അതേ വചനം പറഞ്ഞു പ്രാർഥിച്ചു."},{"v":40,"t":"തിരിച്ചുവന്നപ്പോൾ അവരെ ഉറങ്ങുന്നതായി കണ്ടു. എന്തെന്നാൽ, അവരുടെ കണ്ണുകൾ നിദ്രാഭാരമുള്ളവയായിരുന്നു. അവനോട് എന്തു മറുപടി പറയണമെന്ന് അവർക്ക് അറിഞ്ഞുകൂടായിരുന്നു."},{"v":41,"t":"അവൻ മൂന്നാമതും വന്ന് അവരോടു പറഞ്ഞു: ഇനിയും നിങ്ങൾ ഉറങ്ങി വിശ്രമിക്കുന്നുവോ? മതി. സമയം വന്നെത്തിയിരിക്കുന്നു. ഇതാ, മനുഷ്യപുത്രൻ പാപികളുടെ കൈകളിൽ ഏല്പിക്കപ്പെടുന്നു."},{"v":42,"t":"എഴുന്നേല്ക്കുവിൻ; നമുക്കു പോകാം. ഇതാ, എന്നെ ഒറ്റിക്കൊടുക്കുന്നവൻ അടുത്തെത്തിയിരിക്കുന്നു."},{"h":"യൂദാസ് ഒറ്റിക്കൊടുക്കുന്നു"},{"v":43,"t":"ഉടനെ, അവൻ സംസാരിച്ചുകൊണ്ടിരിക്കുമ്പോൾ, പന്ത്രണ്ടുപേരിൽ ഒരുവനായ യൂദാസ്, പുരോഹിതപ്രമുഖന്മാരുടെയും നിയമജ്ഞരുടെയും ശ്രേഷ്ഠന്മാരുടെയും അടുത്തുനിന്ന് വാളും വടിയുമായി വന്ന ഒരു ജനക്കൂട്ടത്തിന്റെ കൂടെ അവിടെയെത്തി.","p":1},{"v":44,"t":"അവന്റെ ഒറ്റുകാരൻ അവർക്ക് ഒരടയാളം പറഞ്ഞുകൊടുത്തിരുന്നു: ഞാൻ ആരെ ചുംബിക്കുന്നുവോ അവൻതന്നെ. അവനെ പിടിച്ച് കരുതലോടെ കൊണ്ടുപൊയ്ക്കൊള്ളുക."},{"v":45,"t":"അവൻ ഉടനെ, യേശുവിനെ സമീപിച്ച്, ഗുരോ എന്നു വിളിച്ചുകൊണ്ട് അവനെ ചുംബിച്ചു."},{"v":46,"t":"അപ്പോൾ അവർ അവനെ പിടിച്ചുബന്ധിച്ചു."},{"v":47,"t":"സമീപത്തു നിന്നിരുന്ന ഒരുവൻ വാൾ ഊരി പ്രധാന പുരോഹിതന്റെ സേവകനെ വെട്ടി അവന്റെ ചെവി ഛേദിച്ചുകളഞ്ഞു."},{"v":48,"t":"യേശു അവരോടു ചോദിച്ചു: കവർച്ചക്കാരനെതിരേ എന്നപോലെ, വാളും വടിയുമായി എന്നെ ബന്ധിക്കാൻ നിങ്ങൾ വന്നിരിക്കുന്നുവോ?"},{"v":49,"t":"ഞാൻ ദിവസവും ദേവാലയത്തിൽ പഠിപ്പിച്ചുകൊണ്ട് നിങ്ങളോടുകൂടെ ഉണ്ടായിരുന്നു; നിങ്ങൾ എന്നെ പിടിച്ചില്ല. എന്നാൽ, വിശുദ്ധലിഖിതങ്ങൾ പൂർത്തിയാക്കപ്പെടട്ടെ."},{"v":50,"t":"അപ്പോൾ, എല്ലാവരും അവനെ വിട്ട് ഓടിപ്പോയി."},{"v":51,"t":"എന്നാൽ, ഒരു യുവാവ് അവനെ അനുഗമിച്ചു. അവൻ പുതപ്പു മാത്രമേ ശരീരത്തിൽ ചുറ്റിയിരുന്നുള്ളു. അവർ അവനെ പിടിച്ചു."},{"v":52,"t":"അവൻ പുതപ്പുപേക്ഷിച്ച് നഗ്നനായി ഓടിപ്പോയി."},{"h":"ന്യായാധിപസംഘത്തിന്റെ മുമ്പിൽ"},{"v":53,"t":"അവർ യേശുവിനെ പ്രധാനപുരോഹിതന്റെ അടുത്തേക്കു കൊണ്ടുപോയി. എല്ലാ പുരോഹിതപ്രമുഖന്മാരും ശ്രേഷ്ഠന്മാരും നിയമജ്ഞരും ഒരുമിച്ചുകൂടി.","p":1},{"v":54,"t":"പത്രോസ് പ്രധാനപുരോഹിതന്റെ മുറ്റംവരെ അവനെ അല്പം അകലെയായി അനുഗമിച്ചു. പിന്നീട്, അവൻ പരിചാരകരോടൊപ്പം തീകാഞ്ഞുകൊണ്ടിരുന്നു."},{"v":55,"t":"പുരോഹിതപ്രമുഖന്മാരും ന്യായാധിപസംഘം മുഴുവനും യേശുവിനെ വധിക്കുന്നതിന് അവനെതിരേ സാക്ഷ്യം അന്വേഷിച്ചു. പക്ഷേ, അവർ കണ്ടെത്തിയില്ല."},{"v":56,"t":"പലരും അവനെതിരേ കള്ളസാക്ഷ്യം പറഞ്ഞെങ്കിലും സാക്ഷ്യങ്ങൾ തമ്മിൽ പൊരുത്തപ്പെട്ടില്ല."},{"v":57,"t":"ചിലർ എഴുന്നേറ്റ് അവനെതിരേ കള്ളസാക്ഷ്യം പറഞ്ഞു:"},{"v":58,"t":"കൈകൊണ്ടുപണിത ഈ ദേവാലയം ഞാൻ നശിപ്പിക്കുകയും കൈകൊണ്ടുപണിയാത്ത മറ്റൊന്ന് മൂന്നു ദിവസംകൊണ്ടു നിർമിക്കുകയും ചെയ്യും എന്ന് ഇവൻ പറയുന്നതു ഞങ്ങൾ കേട്ടിട്ടുണ്ട്."},{"v":59,"t":"ഇങ്ങനെയും അവരുടെ സാക്ഷ്യം പൊരുത്തപ്പെട്ടില്ല."},{"v":60,"t":"പ്രധാനപുരോഹിതൻ മധ്യത്തിൽ എഴുന്നേറ്റുനിന്ന് യേശുവിനോടു ചോദിച്ചു: ഇവർ നിനക്കെതിരേ സാക്ഷ്യപ്പെടുത്തുന്നതിന് നിനക്കു മറുപടിയൊന്നും പറയാനില്ലേ?"},{"v":61,"t":"അവൻ നിശ്ശബ്ദനായിരുന്നു. മറുപടിയൊന്നും പറഞ്ഞില്ല. പ്രധാനപുരോഹിതൻ വീണ്ടും അവനോടു ചോദിച്ചു: നീയാണോ വാഴ്ത്തപ്പെട്ടവന്റെ പുത്രനായ ക്രിസ്തു?"},{"v":62,"t":"യേശു പറഞ്ഞു: ഞാൻ ആകുന്നു. മനുഷ്യപുത്രൻ ശക്തിയുടെ വലത്തുഭാഗത്ത് ഉപവിഷ്ടനായിരിക്കുന്നതും വാനമേഘങ്ങളിൽ വരുന്നതും നിങ്ങൾ കാണും."},{"v":63,"t":"അപ്പോൾ പ്രധാനപുരോഹിതൻ തന്റെ വസ്ത്രം വലിച്ചുകീറിക്കൊണ്ടു പറഞ്ഞു: ഇനി സാക്ഷികളെക്കൊണ്ട് നമുക്ക് എന്താവശ്യം?"},{"v":64,"t":"ദൈവദൂഷണം നിങ്ങൾ കേട്ടുവല്ലോ? നിങ്ങൾക്ക് എന്തു തോന്നുന്നു? അവൻ മരണാർഹനാണെന്ന് അവരെല്ലാവരും വിധിച്ചു."},{"v":65,"t":"ചിലർ അവനെ തുപ്പാനും അവന്റെ മുഖം മറച്ച് മുഷ്ടികൊണ്ട് ഇടിക്കാനും നീ പ്രവചിക്കുക എന്ന് അവനോടു പറയാനും തുടങ്ങി. ഭൃത്യന്മാർ അവനെ ചെകിട്ടത്തടിച്ച് ഏറ്റുവാങ്ങി."},{"h":"പത്രോസ് തള്ളിപ്പറയുന്നു"},{"v":66,"t":"പത്രോസ് താഴെ മുറ്റത്തിരിക്കുമ്പോൾ, പ്രധാനപുരോഹിതന്റെ പരിചാരികമാരിൽ ഒരുവൾ വന്നു.","p":1},{"v":67,"t":"അവൻ തീകാഞ്ഞുകൊണ്ടിരിക്കുന്നതു കണ്ട് അവനെ നോക്കിപ്പറഞ്ഞു: നീയും നസറായനായ യേശുവിന്റെ കൂടെയായിരുന്നല്ലോ."},{"v":68,"t":"അവനാകട്ടെ, നീ പറയുന്നതെന്തെന്ന് ഞാൻ അറിയുന്നില്ല; എനിക്കു മനസ്സിലാകുന്നുമില്ല എന്നു നിഷേധിച്ചു പറഞ്ഞു. പിന്നെ, അവൻ പുറത്ത് പടിവാതില്ക്കലേക്കു പോയി. അപ്പോൾ കോഴി കൂകി."},{"v":69,"t":"ആ പരിചാരിക അവനെ കണ്ടപ്പോൾ, അടുത്തു നിന്നവരോടു വീണ്ടും പറഞ്ഞു: ഇവൻ അവരിൽ ഒരുവനാണ്."},{"v":70,"t":"അവൻ വീണ്ടും നിഷേധിച്ചു. അല്പം കഴിഞ്ഞപ്പോൾ, അടുത്തുനിന്നവർ വീണ്ടും പത്രോസിനോടു പറഞ്ഞു: സത്യമായും നീ അവരിൽ ഒരുവനാണ്. കാരണം, നീയും ഗലീലിക്കാരനാണല്ലോ."},{"v":71,"t":"നിങ്ങൾ പറയുന്ന ആ മനുഷ്യനെ ഞാൻ അറിയുന്നില്ല എന്നുപറഞ്ഞ് അവൻ ശപിക്കാനും ആണയിടാനും തുടങ്ങി."},{"v":72,"t":"ഉടൻതന്നെ കോഴി രണ്ടാം പ്രാവശ്യം കൂകി. കോഴി രണ്ടുപ്രാവശ്യം കൂകുന്നതിനുമുമ്പ് മൂന്നുപ്രാവശ്യം നീ എന്നെ നിഷേധിക്കുമെന്ന് യേശു അവനോടു പറഞ്ഞവാക്ക് അപ്പോൾ പത്രോസ് ഓർമിച്ചു. അവൻ ഉള്ളുരുകി കരഞ്ഞു."}],"15":[{"h":"വിചാരണയും വിധിയും"},{"v":1,"t":"ഉടനെ, രാവിലെ, പുരോഹിതപ്രമുഖന്മാർ ശ്രേഷ്ഠന്മാരോടും നിയമജ്ഞരോടും ന്യായാധിപസംഘം മുഴുവനോടും ചേർന്ന് ആലോചന നടത്തി. അവർ യേശുവിനെ ബന്ധിച്ചുകൊണ്ടുപോയി പീലാത്തോസിനെ ഏല്പിച്ചു.","p":1},{"v":2,"t":"പീലാത്തോസ് അവനോടു ചോദിച്ചു: നീ യഹൂദരുടെ രാജാവാണോ? അവൻ അവനോടു മറുപടി പറഞ്ഞു: നീതന്നെ പറയുന്നു."},{"v":3,"t":"പുരോഹിതപ്രമുഖന്മാർ അവനിൽ പല കുറ്റങ്ങളും ആരോപിച്ചുകൊണ്ടിരുന്നു."},{"v":4,"t":"പീലാത്തോസ് വീണ്ടും അവനോടു ചോദിച്ചു: നിനക്കു മറുപടിയൊന്നും പറയാനില്ലേ? നോക്കൂ, എത്ര കുറ്റങ്ങളാണ് അവർ നിന്നിൽ ആരോപിക്കുന്നത്!"},{"v":5,"t":"എന്നാൽ, യേശു മറുപടിയൊന്നും പറഞ്ഞില്ല. തന്മൂലം പീലാത്തോസ് വിസ്മയിച്ചു."},{"v":6,"t":"ആവശ്യപ്പെടുന്ന ഒരു തടവുകാരനെ അവൻ അവർക്കായി തിരുനാളിൽ മോചിപ്പിക്കുമായിരുന്നു.","p":1},{"v":7,"t":"വിപ്ലവത്തിനിടയിൽ കൊലപാതകം നടത്തിയ വിപ്ലവകാരികളോടൊപ്പം ബറാബ്ബാസ് എന്നു വിളിക്കപ്പെടുന്ന ഒരുവൻ ബന്ധിതനായി തടങ്കലിൽ ഉണ്ടായിരുന്നു."},{"v":8,"t":"ജനക്കൂട്ടം അടുത്തുചെന്ന് അവർക്കായി അവൻ പതിവായി ചെയ്തിരുന്നത് ആവശ്യപ്പെടാൻ തുടങ്ങി."},{"v":9,"t":"പീലാത്തോസ് അവരോടു പറഞ്ഞു: യഹൂദരുടെ രാജാവിനെ നിങ്ങൾക്ക് ഞാൻ മോചിപ്പിച്ചുതരണമെന്നാണോ നിങ്ങൾ ആഗ്രഹിക്കുന്നത്?"},{"v":10,"t":"എന്തെന്നാൽ, അസൂയ നിമിത്തമാണ് പുരോഹിതപ്രമുഖന്മാർ അവനെ ഏല്പിച്ചുതന്നതെന്ന് അവൻ അറിഞ്ഞിരുന്നു."},{"v":11,"t":"എന്നാൽ, ബറാബ്ബാസിനെയാണു തങ്ങൾക്കു വിട്ടുതരേണ്ടതെന്ന് ആവശ്യപ്പെടാൻ പുരോഹിതപ്രമുഖന്മാർ ജനക്കൂട്ടത്തെ ഇളക്കി."},{"v":12,"t":"അപ്പോൾ പീലാത്തോസ് വീണ്ടും അവരോടു ചോദിച്ചു: യഹൂദരുടെ രാജാവെന്നു നിങ്ങൾ വിളിക്കുന്നവനെ ഞാൻ എന്തു ചെയ്യണമെന്നാണ് നിങ്ങൾ ആഗ്രഹിക്കുന്നത്?"},{"v":13,"t":"അവരാകട്ടെ, വീണ്ടും ആക്രോശിച്ചു: അവനെ ക്രൂശിക്കുക!"},{"v":14,"t":"പീലാത്തോസ് അവരോടു ചോദിച്ചു: അവൻ എന്തു തിന്മ പ്രവർത്തിച്ചു? അവർ ആക്രോശിച്ചു: അവനെ ക്രൂശിക്കുക!"},{"v":15,"t":"അപ്പോൾ, പീലാത്തോസ് ജനക്കൂട്ടത്തിന് ഇഷ്ടമായതു ചെയ്യാൻ ആഗ്രഹിച്ചുകൊണ്ട് ബറാബ്ബാസിനെ അവർക്കു വിട്ടുകൊടുക്കുകയും യേശുവിനെ ചമ്മട്ടികൊണ്ടടിപ്പിച്ചശേഷം ക്രൂശിക്കാൻ ഏല്പിച്ചുകൊടുക്കുകയും ചെയ്തു."},{"h":"പടയാളികളുടെ പരിഹാസം"},{"v":16,"t":"അനന്തരം, പടയാളികൾ അവനെ അകത്തളത്തിൽ, പ്രത്തോറിയത്തിലേക്കു കൊണ്ടുപോയി. അവർ സൈന്യദളത്തെ മുഴുവൻ വിളിച്ചുകൂട്ടി.","p":1},{"v":17,"t":"അവർ അവനെ ധൂമ്രവസ്ത്രം ധരിപ്പിക്കുകയും ഒരു മുൾക്കിരീടം മെടഞ്ഞ് അണിയിക്കുകയും ചെയ്തു."},{"v":18,"t":"യഹൂദരുടെ രാജാവേ, സ്വസ്തി എന്ന് അവർ അവനെ അഭിവാദ്യം ചെയ്യാൻ തുടങ്ങി."},{"v":19,"t":"പിന്നീട് ഞാങ്ങണകൊണ്ട് അവന്റെ ശിരസ്സിൽ അടിക്കുകയും അവനെ തുപ്പുകയും മുട്ടുകുത്തി അവനെ പ്രണമിക്കുകയും ചെയ്തു."},{"v":20,"t":"അവനെ പരിഹസിച്ചശേഷം ധൂമ്രവസ്ത്രം അഴിച്ചുമാറ്റുകയും സ്വന്തം വസ്ത്രം ധരിപ്പിക്കുകയും ചെയ്തു. പിന്നീട് അവർ അവനെ കുരിശിൽ തറയ്ക്കാൻ പുറത്തേക്കു കൊണ്ടുപോയി."},{"h":"കുരിശിൽ തറയ്ക്കുന്നു"},{"v":21,"t":"അലക്സാണ്ടറിന്റെയും റൂഫസിന്റെയും പിതാവായ സൈറീൻകാരൻ ശിമയോൻ നാട്ടിൻപുറത്തുനിന്നു വന്ന്, അതിലേ കടന്നുപോകുകയായിരുന്നു. യേശുവിന്റെ കുരിശുചുമക്കാൻ അവർ അവനെ നിർബന്ധിച്ചു.","p":1},{"v":22,"t":"തലയോടിടം എന്നർഥമുള്ള ഗോൽഗോഥായിൽ അവർ അവനെ കൊണ്ടുവന്നു."},{"v":23,"t":"മീറ കലർത്തിയ വീഞ്ഞ് അവർ അവനു കൊടുത്തു. അവൻ അതു സ്വീകരിച്ചില്ല."},{"v":24,"t":"പിന്നീട്, അവർ അവനെ കുരിശിൽ തറച്ചു. അതിനുശേഷം അവർ അവന്റെ വസ്ത്രങ്ങൾ ഭാഗിച്ച് അവയ്ക്കുമേൽ, ഏത്, ആരെടുക്കണം എന്നതിന് കുറിയിട്ടു."},{"v":25,"t":"അവർ അവനെ കുരിശിൽ തറച്ചപ്പോൾ മൂന്നാം മണിക്കൂറായിരുന്നു."},{"v":26,"t":"യഹൂദരുടെ രാജാവ് എന്ന് അവന്റെ കുറ്റപത്രവും എഴുതിവച്ചിരുന്നു."},{"v":27,"t":"അവനോടുകൂടെ രണ്ടു കവർച്ചക്കാരെയും അവർ കുരിശിൽ തറച്ചു -"},{"v":28,"t":"ഒരുവനെ അവന്റെ വലത്തുവശത്തും അപരനെ ഇടത്തുവശത്തും."},{"v":29,"t":"അതിലേ കടന്നുപോയവർ തങ്ങളുടെ തലകുലുക്കിക്കൊണ്ട് അവനെ ദുഷിച്ചുപറഞ്ഞു: ഹാ! ദേവാലയം നശിപ്പിച്ച്, മൂന്നു ദിവസംകൊണ്ട് വീണ്ടും പണിയുന്നവനേ,"},{"v":30,"t":"കുരിശിൽനിന്ന് ഇറങ്ങിവന്ന്, നിന്നെത്തന്നെ രക്ഷിക്കുക!"},{"v":31,"t":"അതുപോലെ, പുരോഹിതപ്രമുഖന്മാരും നിയമജ്ഞരും പരിഹാസപൂർവം പരസ്പരം പറഞ്ഞു: ഇവൻ മറ്റുള്ളവരെ രക്ഷിച്ചു; തന്നെത്തന്നെ രക്ഷിക്കാൻ ഇവനു സാധിക്കുന്നില്ല."},{"v":32,"t":"ഞങ്ങൾ കണ്ടു വിശ്വസിക്കുന്നതിനുവേണ്ടി ഇസ്രായേലിന്റെ രാജാവായ ക്രിസ്തു ഇപ്പോൾ കുരിശിൽനിന്ന് ഇറങ്ങിവരട്ടെ. അവനോടൊപ്പം ക്രൂശിക്കപ്പെട്ടവരും അവനെ പരിഹസിച്ചു."},{"h":"യേശുവിന്റെ മരണം"},{"v":33,"t":"ആറാംമണിക്കൂർ മുതൽ ഒമ്പതാം മണിക്കൂർ വരെ ഭൂമി മുഴുവൻ അന്ധകാരം വ്യാപിച്ചു.","p":1},{"v":34,"t":"ഒമ്പതാം മണിക്കൂറായപ്പോൾ യേശു വലിയസ്വരത്തിൽ നിലവിളിച്ചു: എലോയ്, എലോയ്, ലമാ സബക്ക്ത്താനി? അതായത്, എന്റെ ദൈവമേ, എന്റെ ദൈവമേ, എന്തുകൊണ്ട് നീ എന്നെ ഉപേക്ഷിച്ചു?"},{"v":35,"t":"അടുത്തു നിന്നിരുന്ന ചിലർ അതുകേട്ടു പറഞ്ഞു: ഇതാ, അവൻ ഏലിയായെ വിളിക്കുന്നു!"},{"v":36,"t":"ഒരുവൻ ഓടിവന്ന്, നീർപ്പഞ്ഞി ചവർപ്പുള്ള വീഞ്ഞിൽ മുക്കി, ഒരു ഞാങ്ങണമേൽവച്ച്, അവനു കുടിക്കാൻ കൊടുത്തുകൊണ്ടു പറഞ്ഞു: ആകട്ടെ, അവനെ താഴെയിറക്കാൻ ഏലിയാ വരുമോ എന്നു നമുക്കു കാണാം."},{"v":37,"t":"യേശു വലിയ സ്വരത്തിൽ നിലവിളിച്ച് ജീവൻ വെടിഞ്ഞു."},{"v":38,"t":"അപ്പോൾ ദേവാലയത്തിലെ തിരശ്ശീല മുകളിൽനിന്ന് താഴെവരെ രണ്ടായി കീറി."},{"v":39,"t":"അവന് അഭിമുഖമായി നിന്നിരുന്ന ശതാധിപൻ, അവൻ ഇപ്രകാരം മരിച്ചതു കണ്ടു പറഞ്ഞു: സത്യമായും ഈ മനുഷ്യൻ ദൈവപുത്രനായിരുന്നു."},{"v":40,"t":"ഇതെല്ലാം കണ്ടുകൊണ്ട് ദൂരെ കുറെ സ്ത്രീകളുമുണ്ടായിരുന്നു. മഗ്ദലേനമറിയവും യോസെയുടെയും ചെറിയ യാക്കോബിന്റെയും അമ്മയായ മറിയവും സലോമിയും അക്കൂട്ടത്തിൽ ഉണ്ടായിരുന്നു."},{"v":41,"t":"ഗലീലിയിലായിരുന്നപ്പോൾ അവനെ അനുഗമിക്കുകയും ശുശ്രൂഷിക്കുകയും ചെയ്തവരാണ് ഇവർ. കൂടാതെ, അവനോടുകൂടെ ജറുസലേമിലേക്കുവന്ന അനവധി സ്ത്രീകളും അവിടെയുണ്ടായിരുന്നു."},{"h":"യേശുവിനെ സംസ്കരിക്കുന്നു"},{"v":42,"t":"അത്, സാബത്തിനു തൊട്ടുമുമ്പുള്ള ഒരുക്കദിവസം വൈകുന്നേരമായിരുന്നു.","p":1},{"v":43,"t":"അതിനാൽ, ആലോചനാസംഘത്തിലെ ഒരു പ്രമുഖാംഗവും ദൈവരാജ്യം പ്രതീക്ഷിച്ചിരുന്നവനുമായ അരിമത്തെയാക്കാരൻ ജോസഫ് ധൈര്യപൂർവം പീലാത്തോസിന്റെ അടുത്തെത്തി യേശുവിന്റെ ശരീരം ചോദിച്ചു."},{"v":44,"t":"അവൻ മരിച്ചുകഴിഞ്ഞോ എന്നു പീലാത്തോസ് വിസ്മയിച്ചു. അവൻ ശതാധിപനെ വിളിച്ച്, അവൻ ഇതിനകം മരിച്ചുകഴിഞ്ഞോ എന്ന് അന്വേഷിച്ചു."},{"v":45,"t":"ശതാധിപനിൽനിന്നു വിവരമറിഞ്ഞശേഷം അവൻ മൃതദേഹം ജോസഫിനു വിട്ടുകൊടുത്തു."},{"v":46,"t":"ജോസഫ് ഒരു കച്ച വാങ്ങി അവനെ താഴെയിറക്കി, അതിൽ പൊതിഞ്ഞ് പാറയിൽ വെട്ടിയൊരുക്കിയ കല്ലറയിൽ അവനെ സംസ്കരിക്കുകയും കല്ലറയുടെ വാതില്ക്കൽ ഒരു കല്ല് ഉരുട്ടിവയ്ക്കുകയും ചെയ്തു."},{"v":47,"t":"അവനെ സംസ്കരിച്ച സ്ഥലം മഗ്ദലേനമറിയവും യോസെയുടെ അമ്മയായ മറിയവും കണ്ടു."}],"16":[{"h":"യേശുവിന്റെ ഉത്ഥാനം"},{"v":1,"t":"സാബത്ത് കഴിഞ്ഞപ്പോൾ മഗ്ദലേനമറിയവും യാക്കോബിന്റെ അമ്മയായ മറിയവും സലോമിയും പോയി അവനെ അഭിഷേകം ചെയ്യുന്നതിനുവേണ്ടി സുഗന്ധദ്രവ്യങ്ങൾ വാങ്ങി.","p":1},{"v":2,"t":"ആഴ്ചയുടെ ആദ്യദിവസം അതിരാവിലേ, സൂര്യനുദിച്ചപ്പോൾതന്നെ, അവർ കല്ലറയിങ്കലേക്കു പോയി."},{"v":3,"t":"അവർ തമ്മിൽ പറഞ്ഞു: ആര് നമുക്കുവേണ്ടി കല്ലറയുടെ വാതില്ക്കൽനിന്ന് കല്ല് ഉരുട്ടിമാറ്റിത്തരും?"},{"v":4,"t":"എന്നാൽ, അവർ സൂക്ഷിച്ചുനോക്കിയപ്പോൾ ആ കല്ല് ഉരുട്ടിമാറ്റപ്പെട്ടിരിക്കുന്നതു കണ്ടു. അതു വളരെ വലുതായിരുന്നുതാനും."},{"v":5,"t":"അവർ ശവകുടീരത്തിനുള്ളിൽ പ്രവേശിച്ചപ്പോൾ വെള്ളവസ്ത്രം ധരിച്ച ഒരു യുവാവ് വലത്തുഭാഗത്തിരിക്കുന്നതുകണ്ടു. അവർ വിസ്മയിച്ചുപോയി."},{"v":6,"t":"അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ അദ്ഭുതപ്പെടേണ്ടാ. കുരിശിൽ തറയ്ക്കപ്പെട്ട നസറായനായ യേശുവിനെ നിങ്ങൾ അന്വേഷിക്കുന്നു. അവൻ ഉയിർപ്പിക്കപ്പെട്ടിരിക്കുന്നു. അവൻ ഇവിടെയില്ല. നോക്കൂ, അവർ അവനെ സംസ്കരിച്ച സ്ഥലം."},{"v":7,"t":"നിങ്ങൾ പോയി, അവന്റെ ശിഷ്യന്മാരോടും പത്രോസിനോടും പറയുക: അവൻ നിങ്ങൾക്കുമുമ്പേ ഗലീലിയിലേക്കു പോകുന്നു. അവൻ നിങ്ങളോടു പറഞ്ഞിരുന്നപോലെ അവിടെ നിങ്ങൾ അവനെ കാണും."},{"v":8,"t":"അവർ കല്ലറയിൽനിന്നു പുറത്തിറങ്ങി ഓടി. എന്തെന്നാൽ, അവർക്ക് വിറയലും ആശ്ചര്യവുമുണ്ടായി. അവർ ആരോടും ഒന്നും പറഞ്ഞില്ല. എന്തെന്നാൽ, അവർ അത്യന്തം ഭയപ്പെട്ടിരുന്നു."},{"h":"ശിഷ്യർക്കു പ്രത്യക്ഷപ്പെടുന്നു"},{"v":9,"t":"ഉയിർത്തെഴുന്നേറ്റശേഷം, ആഴ്ചയുടെ ഒന്നാം ദിവസം രാവിലേ യേശു ആദ്യം മഗ്ദലേനമറിയത്തിനു പ്രത്യക്ഷപ്പെട്ടു. ഇവളിൽനിന്നാണ് അവൻ ഏഴു പിശാചുക്കളെ ബഹിഷ്കരിച്ചത്.","p":1},{"v":10,"t":"അവൾ ചെന്ന് അവനോടുകൂടെ ഉണ്ടായിരുന്നവരെ വിവരമറിയിച്ചു. അവർ ദുഃഖത്തിലാണ്ട് വിലപിച്ചിരിക്കുകയായിരുന്നു."},{"v":11,"t":"അവൻ ജീവിച്ചിരിക്കുന്നു എന്നും അവൾക്കു കാണപ്പെട്ടു എന്നും കേട്ടപ്പോൾ അവർ വിശ്വസിച്ചില്ല."},{"v":12,"t":"ഇതിനുശേഷം അവരിൽ രണ്ടുപേർ ഗ്രാമത്തിലേക്കു നടന്നുപോകുമ്പോൾ അവൻ വേറൊരു രൂപത്തിൽ അവർക്കു പ്രത്യക്ഷപ്പെട്ടു."},{"v":13,"t":"അവർ പോയി ബാക്കിയുള്ളവരെ വിവരം അറിയിച്ചു. അവരെയും അവർ വിശ്വസിച്ചില്ല."},{"h":"ശിഷ്യഗണത്തിനു പ്രേഷിതദൗത്യം"},{"v":14,"t":"പിന്നീട്, അവർ പതിനൊന്നുപേർ ഭക്ഷണത്തിനിരിക്കുമ്പോൾ, അവൻ അവർക്കു പ്രത്യക്ഷപ്പെട്ടു. ഉയിർപ്പിക്കപ്പെട്ടശേഷം അവരുടെ വിശ്വാസരാഹിത്യത്തെയും ഹൃദയകാഠിന്യത്തെയും അവൻ ശാസിച്ചു. കാരണം, ഉയിർപ്പിക്കപ്പെട്ട തന്നെ കണ്ടവരെ അവർ വിശ്വസിച്ചില്ല.","p":1},{"v":15,"t":"അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ ലോകമെങ്ങും പോയി, എല്ലാ സൃഷ്ടികളോടും സുവിശേഷം പ്രഘോഷിക്കുവിൻ."},{"v":16,"t":"വിശ്വസിക്കുകയും സ്നാനം സ്വീകരിക്കുകയും ചെയ്യുന്നവൻ രക്ഷിക്കപ്പെടും; വിശ്വസിക്കാത്തവൻ ശിക്ഷിക്കപ്പെടും."},{"v":17,"t":"വിശ്വസിക്കുന്നവരോടുകൂടെ ഈ അടയാളങ്ങൾ ഉണ്ടായിരിക്കും: അവർ എന്റെ നാമത്തിൽ പിശാചുക്കളെ ബഹിഷ്കരിക്കും. പുതിയ ഭാഷകൾ സംസാരിക്കും."},{"v":18,"t":"അവർ സർപ്പങ്ങളെ കൈയിലെടുക്കും. മാരകമായ എന്തു കുടിച്ചാലും അത് അവർക്ക് ഹാനിവരുത്തുകയില്ല. അവർ രോഗികളുടെമേൽ കൈകൾ വയ്ക്കുകയും അവർ സുഖം പ്രാപിക്കുകയും ചെയ്യും."},{"h":"യേശുവിന്റെ സ്വർഗാരോഹണം"},{"v":19,"t":"കർത്താവായ യേശു അവരോടു സംസാരിച്ചു കഴിഞ്ഞപ്പോൾ, സ്വർഗത്തിലേക്കു സംവഹിക്കപ്പെട്ടു; അവൻ ദൈവത്തിന്റെ വലത്തുഭാഗത്ത് ഉപവിഷ്ടനായി.","p":1},{"v":20,"t":"അവർ എല്ലായിടത്തും പോയി പ്രഘോഷിച്ചു. കർത്താവ് അവരോടുകൂടെ പ്രവർത്തിക്കുകയും തുടർന്നു നടന്ന അടയാളങ്ങൾകൊണ്ട് വചനം സ്ഥിരീകരിക്കുകയും ചെയ്തിരുന്നു."}]}},{"id":"LUK","name":"ലൂക്കാ","chapters":{"1":[{"h":"പ്രാരംഭം"},{"v":1,"t":"നമ്മുടെയിടയിൽ പൂർത്തിയാക്കപ്പെട്ട സംഭവങ്ങളുടെ വിവരണം സമാഹരിച്ചെഴുതാൻ അനേകർ ശ്രമിച്ചിട്ടുണ്ടല്ലോ.","p":1},{"v":2,"t":"അതാകട്ടെ, ആദിമുതൽത്തന്നെ വചനത്തിന്റെ ദൃക്സാക്ഷികളും ശുശ്രൂഷകരുമായിരുന്നവർ നമുക്ക് ഏല്പിച്ചു തന്നിട്ടുള്ളതനുസരിച്ചാണ്."},{"v":3,"t":"അതിശ്രേഷ്ഠനായ തെയോഫിലോസേ, എല്ലാം പ്രാരംഭം മുതൽ സൂക്ഷ്മമായി പരിശോധിച്ച എനിക്കും ക്രമമായി നിനക്കെഴുതുന്നത് ഉചിതമാണെന്നു തോന്നി."},{"v":4,"t":"അത് നിന്നെ പ്രബോധിപ്പിച്ചിട്ടുള്ള വചനങ്ങളുടെ വിശ്വാസ്യത നീ ഗ്രഹിക്കാനാണ്."},{"h":"സ്നാപകയോഹന്നാന്റെ ജനനത്തെക്കുറിച്ച് അറിയിപ്പ്"},{"v":5,"t":"ഹേറോദേസ് യൂദയാരാജാവായിരുന്ന കാലത്ത്, അബിയായുടെ ഗണത്തിൽ സഖറിയാ എന്നു പേരുള്ള ഒരു പുരോഹിതൻ ഉണ്ടായിരുന്നു. അഹറോന്റെ പുത്രിമാരിൽ ഒരാളായിരുന്നു അവന്റെ ഭാര്യ; അവളുടെ പേര് എലിസബത്ത്.","p":1},{"v":6,"t":"ഇരുവരും ദൈവസന്നിധിയിൽ നീതിനിഷ്ഠരും കർത്താവിന്റെ സകല കല്പനകളിലും പ്രമാണങ്ങളിലും കുറ്റമറ്റവിധം ചരിക്കുന്നവരും ആയിരുന്നു."},{"v":7,"t":"അവർക്കു സന്താനമില്ലായിരുന്നു. കാരണം, എലിസബത്ത് വന്ധ്യയായിരുന്നു. ഇരുവരും പ്രായംകവിഞ്ഞവരുമായിരുന്നു."},{"v":8,"t":"തന്റെ ഗണത്തിനു നിശ്ചയിക്കപ്പെട്ടിരുന്ന ക്രമമനുസരിച്ച് സഖറിയാ ദൈവസന്നിധിയിൽ പൗരോഹിത്യശുശ്രൂഷ നിർവഹിച്ചുകൊണ്ടിരിക്കേ,"},{"v":9,"t":"പൗരോഹിത്യാചാരപ്രകാരം കർത്താവിന്റെ വിശുദ്ധസ്ഥലത്തു പ്രവേശിച്ച് ധൂപമർപ്പിക്കാൻ സഖറിയായ്ക്കു കുറിവീണു."},{"v":10,"t":"ധൂപാർപ്പണസമയം ജനം മുഴുവൻ വെളിയിൽ പ്രാർഥിച്ചുകൊണ്ടിരുന്നു."},{"v":11,"t":"കർത്താവിന്റെ ദൂതൻ ധൂപാർപ്പണപീഠത്തിന്റെ വലത്തുവശത്തു നില്ക്കുന്നതായി അവനു കാണപ്പെട്ടു."},{"v":12,"t":"അവനെക്കണ്ട് സഖറിയാ അസ്വസ്ഥനാകുകയും ഭയാധീനനാകുകയും ചെയ്തു."},{"v":13,"t":"ദൂതൻ അവനോടു പറഞ്ഞു: സഖറിയാ, ഭയപ്പെടേണ്ടാ; കാരണം, നിന്റെ പ്രാർഥന കേൾക്കപ്പെട്ടിരിക്കുന്നു. നിന്റെ ഭാര്യ എലിസബത്ത് നിനക്ക് ഒരു പുത്രനെ പ്രസവിക്കും. നീ അവന് യോഹന്നാൻ എന്നു പേരുവിളിക്കണം."},{"v":14,"t":"നിനക്ക് സന്തോഷവും ആനന്ദവും ഉണ്ടാകും. അനേകർ അവന്റെ ജനനത്തിൽ ആഹ്ലാദിക്കും."},{"v":15,"t":"അവൻ കർത്താവിന്റെ മുമ്പിൽ വലിയവനായിരിക്കും. വീഞ്ഞോ ലഹരിപാനീയങ്ങളോ അവൻ കുടിക്കുകയില്ല. അമ്മയുടെ ഉദരത്തിൽവച്ചുതന്നെ അവൻ പരിശുദ്ധാത്മാവാൽ നിറയും."},{"v":16,"t":"ഇസ്രായേൽമക്കളിൽ അനേകരെ തങ്ങളുടെ ദൈവമായ കർത്താവിങ്കലേക്ക് അവൻ തിരികെ കൊണ്ടുവരും."},{"v":17,"t":"പിതാക്കന്മാരുടെ ഹൃദയങ്ങളെ മക്കളിലേക്കും അനുസരണമില്ലാത്തവരെ നീതിനിഷ്ഠരുടെ വിവേകത്തിലേക്കും തിരികെ കൊണ്ടുവരാനും രൂപീകൃതമായ ഒരു ജനത്തെ കർത്താവിനുവേണ്ടി ഒരുക്കാനും ഏലിയായുടെ ചൈതന്യത്തോടും ശക്തിയോടുംകൂടെ അവൻ കർത്താവിന്റെ മുമ്പേ പോകും."},{"v":18,"t":"സഖറിയാ ദൂതനോടു ചോദിച്ചു: ഞാൻ ഇത് എങ്ങനെ അറിയും? ഞാൻ വൃദ്ധനാണ്; എന്റെ ഭാര്യ പ്രായംകവിഞ്ഞവളുമാണ്."},{"v":19,"t":"ദൂതൻ അവനോടു മറുപടി പറഞ്ഞു: ഞാൻ ദൈവസന്നിധിയിൽ നില്ക്കുന്ന ഗബ്രിയേലാണ്. നിന്നോടു സംസാരിക്കാനും ഈ സദ്വാർത്ത നിന്നെ അറിയിക്കാനും ഞാൻ അയയ്ക്കപ്പെട്ടിരിക്കുന്നു."},{"v":20,"t":"ഇതാ, ഇവ സംഭവിക്കുന്ന ദിവസം വരെ നീ നിശ്ശബ്ദനും സംസാരിക്കാൻ കഴിവില്ലാത്തവനുമായിരിക്കും. എന്തെന്നാൽ, യഥാകാലം പൂർത്തിയാകാനിരിക്കുന്ന എന്റെ വാക്കുകൾ നീ വിശ്വസിച്ചില്ല."},{"v":21,"t":"ജനം സഖറിയായെ കാത്തുനില്ക്കുകയും വിശുദ്ധ സ്ഥലത്ത് അവൻ വൈകുന്നതിനെപ്പറ്റി അദ്ഭുതപ്പെടുകയും ചെയ്തു.","p":1},{"v":22,"t":"പുറത്തുവന്നപ്പോൾ അവരോടു സംസാരിക്കാൻ അവനു കഴിഞ്ഞില്ല. വിശുദ്ധ സ്ഥലത്ത് അവന് ഒരു ദർശനമുണ്ടായി എന്ന് അവർക്കു മനസ്സിലായി. അവൻ അവരെ ആംഗ്യം കാണിക്കുകയും ഊമയായി തുടരുകയും ചെയ്തു."},{"v":23,"t":"ദേവാലയശുശ്രൂഷയുടെ ദിവസങ്ങൾ പൂർത്തിയായപ്പോൾ അവൻ വീട്ടിലേക്കു പോയി."},{"v":24,"t":"ആ ദിവസങ്ങൾക്കുശേഷം അവന്റെ ഭാര്യ എലിസബത്ത് ഗർഭിണിയായി. അഞ്ചുമാസം അവൾ ഇങ്ങനെ പറഞ്ഞുകൊണ്ട് രഹസ്യത്തിൽ കഴിഞ്ഞുകൂടി;"},{"v":25,"t":"മനുഷ്യരുടെ ഇടയിലുള്ള എന്റെ അപമാനം നീക്കാൻ എന്നെ കടാക്ഷിച്ച നാളുകളിൽ കർത്താവ് എനിക്ക് ഇപ്രകാരം ചെയ്തുതന്നിരിക്കുന്നു."},{"h":"യേശുവിന്റെ ജനനത്തെക്കുറിച്ച് അറിയിപ്പ്"},{"v":26,"t":"ആറാംമാസം ഗബ്രിയേൽദൂതൻ ഗലീലിയിൽ നസറത്ത് എന്നു പേരുള്ള പട്ടണത്തിൽ","p":1},{"v":27,"t":"ദാവീദിന്റെ കുടുംബത്തിൽപ്പെട്ട ജോസഫ് എന്നുപേരുള്ള പുരുഷനുമായി വിവാഹനിശ്ചയം ചെയ്തിരുന്ന കന്യകയുടെ അടുത്തേക്ക് ദൈവത്താൽ അയയ്ക്കപ്പെട്ടു. ആ കന്യകയുടെ പേര് മറിയം എന്നായിരുന്നു."},{"v":28,"t":"ദൂതൻ അവളുടെ അടുത്തുവന്നു പറഞ്ഞു: കൃപനിറഞ്ഞവളേ, സ്വസ്തി; കർത്താവ് നിന്നോടുകൂടെ!"},{"v":29,"t":"ഈ വചനത്തിൽ അവൾ അതീവം അസ്വസ്ഥയായി; ഏതുതരം അഭിവാദനമായിരിക്കുമിത് എന്ന് അവൾ ചിന്തിച്ചുകൊണ്ടിരുന്നു."},{"v":30,"t":"ദൂതൻ അവളോടു പറഞ്ഞു: മറിയമേ, ഭയപ്പെടേണ്ടാ; എന്തെന്നാൽ, നീ ദൈവസന്നിധിയിൽ കൃപ കണ്ടെത്തിയിരിക്കുന്നു."},{"v":31,"t":"ഇതാ, നീ ഗർഭം ധരിച്ച് ഒരു പുത്രനെ പ്രസവിക്കും. നീ അവനെ യേശു എന്നു പേരുവിളിക്കണം."},{"v":32,"t":"അവൻ വലിയവൻ ആയിരിക്കും; അത്യുന്നതന്റെ പുത്രൻ എന്നു വിളിക്കപ്പെടും. അവന്റെ പിതാവായ ദാവീദിന്റെ സിംഹാസനം ദൈവമായ കർത്താവ് അവനു കൊടുക്കും."},{"v":33,"t":"അവൻ യാക്കോബിന്റെ കുടുംബത്തിന്മേൽ എന്നേക്കും ഭരിക്കും. അവന്റെ രാജ്യത്തിന് അവസാനമുണ്ടായിരിക്കുകയില്ല."},{"v":34,"t":"മറിയമാകട്ടെ, ദൂതനോടു ചോദിച്ചു: ഞാൻ പുരുഷനെ അറിയായ്കയാൽ ഇത് എങ്ങനെ സംഭവിക്കും?"},{"v":35,"t":"ദൂതൻ അവളോടു പ്രതിവചിച്ചു: പരിശുദ്ധാത്മാവ് നിന്റെമേൽ വരും; അത്യുന്നതന്റെ ശക്തി നിന്നെ ആവരണം ചെയ്യും. ആകയാൽ, ജനിക്കാനിരിക്കുന്നവൻ പരിശുദ്ധനായിരിക്കും. അവൻ ദൈവപുത്രൻ എന്നു വിളിക്കപ്പെടും."},{"v":36,"t":"ഇതാ, നിന്റെ ചാർച്ചക്കാരി എലിസബത്തും അവളുടെ വാർദ്ധക്യത്തിൽ ഒരു പുത്രനെ ഗർഭം ധരിച്ചിരിക്കുന്നു. വന്ധ്യയെന്നു വിളിക്കപ്പെട്ടിരുന്ന അവൾക്ക് ഇത് ആറാംമാസമാണ്."},{"v":37,"t":"എന്തെന്നാൽ, ദൈവത്തിന് ഒരു കാര്യവും അസാധ്യമല്ല."},{"v":38,"t":"മറിയം പറഞ്ഞു: ഇതാ, കർത്താവിന്റെ ദാസി! നിന്റെ വാക്കുപോലെ എനിക്കു സംഭവിക്കട്ടെ. അപ്പോൾ ദൂതൻ അവളെ വിട്ടുപോയി."},{"h":"മറിയം എലിസബത്തിനെ സന്ദർശിക്കുന്നു"},{"v":39,"t":"ആ ദിവസങ്ങളിൽത്തന്നെ മറിയം എഴുന്നേറ്റ് യൂദയായിലെ മലമ്പ്രദേശത്തുള്ള ഒരു പട്ടണത്തിലേക്ക് തിടുക്കത്തിൽ പുറപ്പെട്ടു.","p":1},{"v":40,"t":"അവൾ സഖറിയായുടെ വീട്ടിൽ പ്രവേശിച്ച് എലിസബത്തിനെ അഭിവാദനം ചെയ്തു."},{"v":41,"t":"മറിയത്തിന്റെ അഭിവാദനം എലിസബത്ത് കേട്ടപ്പോൾ അവളുടെ ഉദരത്തിൽ ശിശു കുതിച്ചുചാടി. എലിസബത്ത് പരിശുദ്ധാത്മാവാൽ പൂരിതയായി."},{"v":42,"t":"അവൾ ഉദ്ഘോഷിച്ചു: നീ സ്ത്രീകളിൽ അനുഗൃഹീതയാണ്; നിന്റെ ഉദരഫലവും അനുഗൃഹീതം."},{"v":43,"t":"എന്റെ കർത്താവിന്റെ അമ്മ എന്റെ അടുത്തേക്കു വരാൻ ഞാനാര്!"},{"v":44,"t":"എന്തെന്നാൽ, ഇതാ, നിന്റെ അഭിവാദനസ്വരം എന്റെ കാതുകളിൽ പതിച്ചപ്പോൾ ശിശു എന്റെ ഉദരത്തിൽ ആനന്ദത്താൽ കുതിച്ചുചാടി."},{"v":45,"t":"കർത്താവ് തന്നോട് അരുൾചെയ്തവയ്ക്ക് പൂർത്തീകരണമുണ്ടാകുമെന്നു വിശ്വസിച്ചവൾ അനുഗൃഹീത."},{"h":"മറിയത്തിന്റെ സ്തോത്രഗീതം"},{"v":46,"t":"മറിയം പറഞ്ഞു: എന്റെ ആത്മാവ് കർത്താവിനെ മഹത്ത്വപ്പെടുത്തുന്നു.","p":1},{"v":47,"t":"എന്റെ ഉള്ളം എന്റെ രക്ഷകനായ ദൈവത്തിൽ ആനന്ദിക്കുന്നു.","p":1},{"v":48,"t":"എന്തെന്നാൽ, അവിടന്ന് തന്റെ ദാസിയുടെ താഴ്മയെ കടാക്ഷിച്ചു. ഇതാ, ഇപ്പോൾ മുതൽ സകല തലമുറകളും എന്നെ അനുഗൃഹീതയെന്നു പ്രകീർത്തിക്കും.","p":1},{"v":49,"t":"എന്തെന്നാൽ, ശക്തനായവൻ എനിക്കു വലിയ കാര്യങ്ങൾ ചെയ്തിരിക്കുന്നു, അവിടത്തെ നാമം പരിശുദ്ധമാണ്.","p":1},{"v":50,"t":"അവിടത്തെ ഭയപ്പെടുന്നവർക്ക് തലമുറകൾതോറും തന്റെ കരുണയുണ്ടായിരിക്കും.","p":1},{"v":51,"t":"അവിടന്ന് തന്റെ ഭുജംകൊണ്ട് ബലം പ്രയോഗിച്ചു, ഹൃദയവിചാരത്തിൽ അഹങ്കരിക്കുന്നവരെ ചിതറിച്ചു.","p":1},{"v":52,"t":"ശക്തരെ സിംഹാസനങ്ങളിൽ നിന്നു താഴെയിറക്കി. എളിയവരെ ഉയർത്തി.","p":1},{"v":53,"t":"വിശക്കുന്നവരെ വിശിഷ്ടവിഭവങ്ങൾകൊണ്ടു സംതൃപ്തരാക്കി. സമ്പന്നരെ വെറുംകൈയോടെ പറഞ്ഞയച്ചു.","p":1},{"v":54,"t":"തന്റെ കാരുണ്യം അനുസ്മരിച്ചുകൊണ്ട് അവിടന്ന് തന്റെ ദാസനായ ഇസ്രായേലിനെ സഹായിച്ചു.","p":1},{"v":55,"t":"നമ്മുടെ പിതാക്കന്മാരായ അബ്രാഹത്തോടും അവന്റെ സന്തതികളോടും എന്നേക്കുമായി അരുൾചെയ്തപോലെ.","p":1},{"v":56,"t":"മറിയം അവളുടെകൂടെ മൂന്നുമാസത്തോളം താമസിച്ചു. പിന്നെ വീട്ടിലേക്കു മടങ്ങി.","p":1},{"h":"യോഹന്നാന്റെ ജനനവും പരിച്ഛേദനവും"},{"v":57,"t":"എലിസബത്തിനു പ്രസവിക്കാനുള്ള സമയമായി. അവൾ ഒരു പുത്രനെ പ്രസവിച്ചു.","p":1},{"v":58,"t":"കർത്താവ് അവളോടു വലിയ കാരുണ്യം കാണിച്ചിരിക്കുന്നു എന്നു കേട്ട് അയല്ക്കാരും ബന്ധുക്കളും അവളോടൊത്തു സന്തോഷിച്ചു."},{"v":59,"t":"എട്ടാംദിവസം അവർ ശിശുവിന്റെ പരിച്ഛേദനത്തിനു വന്നു. പിതാവിന്റെ പേരനുസരിച്ച് സഖറിയാ എന്നു വിളിക്കാൻ അവർ ഒരുങ്ങി."},{"v":60,"t":"എന്നാൽ അവന്റെ അമ്മ അവരോടു പറഞ്ഞു: അങ്ങനെയല്ല, അവൻ യോഹന്നാൻ എന്നുവിളിക്കപ്പെടണം."},{"v":61,"t":"അവർ അവളോടു പറഞ്ഞു: നിന്റെ ബന്ധുക്കളിലാരും ഈ പേരിൽ വിളിക്കപ്പെടുന്നില്ലല്ലോ."},{"v":62,"t":"അവൻ എങ്ങനെ വിളിക്കപ്പെടാനാണ് ആഗ്രഹിക്കുന്നതെന്ന് അവന്റെ പിതാവിനോട് അവർ ആംഗ്യം കാണിച്ചു ചോദിച്ചു."},{"v":63,"t":"അവൻ ഒരു എഴുത്തുപലക ആവശ്യപ്പെട്ടു. യോഹന്നാൻ എന്നാണ് അവന്റെ പേര് എന്നു പറഞ്ഞുകൊണ്ട് അതിൽ എഴുതി. എല്ലാവരും അദ്ഭുതപ്പെട്ടു."},{"v":64,"t":"തത്ക്ഷണം അവന്റെ വായും നാവും തുറക്കപ്പെട്ടു. അവൻ ദൈവത്തെ വാഴ്ത്തിക്കൊണ്ട് സംസാരിച്ചു."},{"v":65,"t":"അവരുടെ അയല്ക്കാർക്കെല്ലാം ഭയമുണ്ടായി. ഈ കാര്യങ്ങളെല്ലാം യൂദയായിലെ മലനാട്ടിലാകെ സംസാരവിഷയമാകുകയും ചെയ്തു."},{"v":66,"t":"കേട്ടവരെല്ലാം ഈ ശിശു ആരായിത്തീരും എന്നു പറഞ്ഞുകൊണ്ട് ഇവ ഹൃദയത്തിൽ സൂക്ഷിച്ചു. എന്തെന്നാൽ, കർത്താവിന്റെ കരം അവനോടുകൂടെ ഉണ്ടായിരുന്നു."},{"h":"സഖറിയായുടെ പ്രവചനം"},{"v":67,"t":"അവന്റെ പിതാവായ സഖറിയാ പരിശുദ്ധാത്മാവാൽ നിറഞ്ഞു പ്രവചിച്ചു:","p":1},{"v":68,"t":"ഇസ്രായേലിന്റെ ദൈവമായ കർത്താവ് വാഴ്ത്തപ്പെട്ടവൻ. എന്തെന്നാൽ, അവിടന്ന് തന്റെ ജനത്തെ സന്ദർശിച്ച് വീണ്ടെടുപ്പു നടത്തി."},{"v":69,"t":"തന്റെ ദാസനായ ദാവീദിന്റെ കുടുംബത്തിൽ നമുക്കായി രക്ഷയുടെ കൊമ്പുയർത്തി."},{"v":70,"t":"അത് അവിടന്ന് പുരാതനകാലം മുതലേ തന്റെ വിശുദ്ധരായ പ്രവാചകന്മാരുടെ അധരങ്ങളിലൂടെ അരുൾചെയ്തിരുന്നപോലെ,"},{"v":71,"t":"നമ്മുടെ ശത്രുക്കളുടെയും നമ്മെ വെറുക്കുന്ന എല്ലാവരുടെയും കൈയിൽനിന്നു രക്ഷിക്കാനും"},{"v":72,"t":"നമ്മുടെ പിതാക്കന്മാരോടുള്ള കരുണ പ്രവർത്തിക്കാനും തന്റെ പരിശുദ്ധമായ ഉടമ്പടി അനുസ്മരിക്കാനുമാണ്."},{"v":73,"t":"ഇതാകട്ടെ, അവിടന്ന് നമ്മുടെ പിതാവായ അബ്രാഹത്തോടു ചെയ്ത ശപഥമനുസരിച്ച്,"},{"v":74,"t":"നാം ശത്രുക്കളുടെ കൈകളിൽനിന്നു വിമോചിതരായി, നിർഭയം"},{"v":75,"t":"വിശുദ്ധിയിലും നീതിയിലും നമ്മുടെ നാളുകളിലെല്ലാം അവന്റെ മുമ്പിൽ ആരാധിക്കാൻ വേണ്ടിയത്രേ."},{"v":76,"t":"നീയോ, കുഞ്ഞേ, അത്യുന്നതന്റെ പ്രവാചകൻ എന്നു വിളിക്കപ്പെടും. കർത്താവിനു വഴിയൊരുക്കാൻ അവന്റെ മുമ്പേ പോകും."},{"v":77,"t":"അത് അവന്റെ ജനത്തിന് പാപമോചനത്താലുള്ള രക്ഷയെക്കുറിച്ച് അറിവുനല്കാനും"},{"v":78,"t":"നമ്മുടെ ദൈവത്തിന്റെ ആർദ്രമായ കരുണയാൽ ഉന്നതത്തിൽനിന്നുള്ള ഉദയസൂര്യൻ നമ്മെ സന്ദർശിക്കുമ്പോൾ"},{"v":79,"t":"ഇരുളിലും മരണത്തിന്റെ നിഴലിലും ഇരിക്കുന്നവർക്കു പ്രകാശം വീശാനും സമാധാനത്തിന്റെ മാർഗത്തിലേക്ക് നമ്മുടെ പാദങ്ങൾ നേർനയിക്കാനുമത്രേ."},{"v":80,"t":"ശിശു വളരുകയും ആത്മാവിൽ ബലപ്പെടുകയും ചെയ്തുകൊണ്ടിരുന്നു. ഇസ്രായേലിനുള്ള പ്രത്യക്ഷപ്പെടലിന്റെ നാളുകൾവരെ അവൻ മരുഭൂമിയിലായിരുന്നു.","p":1}],"2":[{"h":"യേശുവിന്റെ ജനനം"},{"v":1,"t":"അക്കാലത്ത്, ലോകനിവാസികളെല്ലാം പേരെഴുതിക്കണമെന്ന് അഗസ്റ്റസ് സീസറിൽനിന്ന് കല്പന പുറപ്പെട്ടു.","p":1},{"v":2,"t":"സിറിയായിൽ ക്വിരിനിയോസ് ദേശാധിപതിയായിരിക്കുമ്പോൾ ഈ ഒന്നാമത്തെ പേരെഴുത്തുനടന്നു."},{"v":3,"t":"പേരെഴുതിക്കാൻ ഓരോരുത്തരും താന്താങ്ങളുടെ നഗരങ്ങളിലേക്കു പോയി."},{"v":4,"t":"ദാവീദിന്റെ കുടുംബത്തിലും കുലത്തിലും പെട്ടവനായിരുന്നതിനാൽ, ജോസഫ്, ഗലീലിയിലെ നസറത്ത് എന്ന നഗരത്തിൽനിന്ന് യൂദയായിൽ ദാവീദിന്റെ നഗരമായ ബേത്ലെഹെമിലേക്ക്,"},{"v":5,"t":"തനിക്കു വിവാഹം നിശ്ചയിച്ചിരുന്ന ഗർഭിണിയായ മറിയത്തോടുകൂടെ പേരെഴുതിക്കാൻ പോയി."},{"v":6,"t":"അവിടെയായിരിക്കുമ്പോൾ അവൾക്കു പ്രസവദിവസമായി."},{"v":7,"t":"അവൾ തന്റെ ആദ്യജാതനെ പ്രസവിച്ചു. അവനെ പിള്ളക്കച്ച പൊതിഞ്ഞ് പുല്ത്തൊട്ടിയിൽ കിടത്തി. കാരണം, സത്രത്തിൽ അവർക്കു സ്ഥലമില്ലായിരുന്നു."},{"h":"ആട്ടിടയന്മാർക്കു ലഭിച്ച സന്ദേശം"},{"v":8,"t":"ആ പ്രദേശത്തെ വയലുകളിൽ, തങ്ങളുടെ ആടുകൾക്ക് രാത്രികാവലിരിക്കുന്ന ഇടയന്മാർ ഉണ്ടായിരുന്നു.","p":1},{"v":9,"t":"കർത്താവിന്റെ ദൂതൻ അവരുടെ അടുത്തെത്തി. കർത്താവിന്റെ മഹത്ത്വം അവർക്കു ചുറ്റും പ്രകാശിച്ചു. അവർ അത്യധികം ഭയപ്പെട്ടു."},{"v":10,"t":"ദൂതൻ അവരോടു പറഞ്ഞു: ഭയപ്പെടേണ്ടാ. ഇതാ, സകല ജനത്തിനും ഉണ്ടാകാനുള്ള വലിയ സന്തോഷത്തിന്റെ സദ്വാർത്ത ഞാൻ നിങ്ങളെ അറിയിക്കുന്നു."},{"v":11,"t":"നിങ്ങൾക്കായി ഒരു രക്ഷകൻ, കർത്താവായ ക്രിസ്തു, ഇന്നു ദാവീദിന്റെ നഗരത്തിൽ ജനിച്ചിരിക്കുന്നു."},{"v":12,"t":"നിങ്ങൾക്കുള്ള അടയാളം ഇതാണ്: പിള്ളക്കച്ച പൊതിഞ്ഞ് പുല്ത്തൊട്ടിയിൽ കിടത്തിയിരിക്കുന്ന ഒരു ശിശുവിനെ നിങ്ങൾകണ്ടെത്തും."},{"v":13,"t":"പെട്ടെന്ന് സ്വർഗീയസൈന്യത്തിന്റെ ഒരു വ്യൂഹം ദൂതനോടൊത്ത് ദൈവത്തെ സ്തുതിച്ചുകൊണ്ടു പറഞ്ഞു:"},{"v":14,"t":"അത്യുന്നതങ്ങളിൽ ദൈവത്തിനു മഹത്ത്വം! ഭൂമിയിൽ ദൈവപ്രസാദമുള്ള മനുഷ്യർക്കു സമാധാനം!"},{"v":15,"t":"ദൂതന്മാർ അവരെവിട്ട്, സ്വർഗത്തിലേക്കു പോയപ്പോൾ ആട്ടിടയന്മാർ പരസ്പരം പറഞ്ഞു: നമുക്കു ബേത്ലെഹെംവരെ പോകാം. കർത്താവ് നമ്മെ അറിയിച്ച ഈ സംഭവം നമുക്കു കാണാം.","p":1},{"v":16,"t":"അവർ തിടുക്കപ്പെട്ട് പോയി മറിയത്തെയും ജോസഫിനെയും പുല്ത്തൊട്ടിയിൽ കിടത്തിയിരിക്കുന്ന ശിശുവിനെയും കണ്ടെത്തി."},{"v":17,"t":"കണ്ടുകഴിഞ്ഞപ്പോൾ, ശിശുവിനെപ്പറ്റി തങ്ങളോടു പറഞ്ഞിരുന്ന കാര്യങ്ങൾ അവർ മറ്റുള്ളവരെ അറിയിച്ചു."},{"v":18,"t":"അതു കേട്ടവരെല്ലാം, ഇടയന്മാർ തങ്ങളോടു പറഞ്ഞതിനെപ്പറ്റി അദ്ഭുതപ്പെട്ടു."},{"v":19,"t":"മറിയമാകട്ടെ, കാര്യങ്ങളെല്ലാം ഹൃദയത്തിൽ സംഗ്രഹിച്ച് ധ്യാനിച്ചുകൊണ്ടിരുന്നു."},{"v":20,"t":"തങ്ങളോടു പറയപ്പെട്ടപോലെ കാണുകയും കേൾക്കുകയും ചെയ്ത സകലത്തെയും കുറിച്ച് ദൈവത്തെ മഹത്ത്വപ്പെടുത്തുകയും സ്തുതിക്കുകയും ചെയ്തുകൊണ്ട് ആ ഇടയന്മാർ തിരിച്ചുപോയി."},{"h":"പരിച്ഛേദനം, സമർപ്പണം"},{"v":21,"t":"അവന്റെ പരിച്ഛേദനത്തിനുള്ള എട്ടു ദിവസങ്ങൾ പൂർത്തിയായപ്പോൾ, അവൻ ഗർഭത്തിൽ ഉരുവാകുന്നതിനുമുമ്പ്, ദൂതൻ വിളിച്ച യേശു എന്ന പേര് അവനു നല്കി.","p":1},{"v":22,"t":"മോശയുടെ നിയമമനുസരിച്ച്, അവരുടെ ശുദ്ധീകരണത്തിനുള്ള ദിവസങ്ങൾ പൂർത്തിയായപ്പോൾ, അവർ അവനെ കർത്താവിനു സമർപ്പിക്കാൻ ജറുസലേമിലേക്കു കൊണ്ടുപോയി."},{"v":23,"t":"ഇതാകട്ടെ, ആദ്യം പിറക്കുന്ന ആൺകുട്ടി, കർത്താവിന്റെ പരിശുദ്ധൻ എന്നു വിളിക്കപ്പെടണം എന്ന് കർത്താവിന്റെ നിയമത്തിൽ എഴുതിയിട്ടുള്ളതനുസരിച്ചും"},{"v":24,"t":"ഒരു ജോടി ചെങ്ങാലികളെയോ രണ്ടു പ്രാവിൻകുഞ്ഞുങ്ങളെയോ ബലിയർപ്പിക്കണം എന്ന് കർത്താവിന്റെ നിയമത്തിൽ പറഞ്ഞിട്ടുള്ളതനുസരിച്ചുമാണ്."},{"h":"ശിമയോനും അന്നയും"},{"v":25,"t":"ജറുസലേമിൽ ശിമയോൻ എന്നു പേരുള്ള ഒരുവനുണ്ടായിരുന്നു. അവൻ നീതിമാനും ഭക്തനും ഇസ്രായേലിന്റെ ആശ്വാസം പ്രതീക്ഷിച്ചിരുന്നവനുമായിരുന്നു. പരിശുദ്ധാത്മാവ് അവന്റെമേൽ ഉണ്ടായിരുന്നു.","p":1},{"v":26,"t":"കർത്താവിന്റെ അഭിഷിക്തനെ കാണുന്നതുവരെ മരിക്കുകയില്ല എന്ന് പരിശുദ്ധാത്മാവ് അവനു വെളിപ്പെടുത്തിയിരുന്നു."},{"v":27,"t":"അവൻ പരിശുദ്ധാത്മാവിന്റെ പ്രേരണയാൽ ദേവാലയത്തിലേക്കു വന്നു. നിയമപ്രകാരമുള്ള അനുഷ്ഠാനത്തിന് ശിശുവായ യേശുവിനെ മാതാപിതാക്കന്മാർ കൊണ്ടുവന്നു."},{"v":28,"t":"അപ്പോൾ ശിമയോൻ അവനെ കൈകളിൽ സ്വീകരിച്ച് ദൈവത്തെ വാഴ്ത്തിക്കൊണ്ടു പറഞ്ഞു:"},{"v":29,"t":"കർത്താവേ, ഇപ്പോൾ നിന്റെ ദാസനെ നിന്റെ വാക്കനുസരിച്ച് സമാധാനത്തിൽ വിട്ടയയ്ക്കണമേ."},{"v":30,"t":"എന്തെന്നാൽ, സകല ജനത്തിന്റെയും മുമ്പിൽ നീ ഒരുക്കിയിട്ടുള്ള നിന്റെ രക്ഷ എന്റെ കണ്ണുകൾ കണ്ടുവല്ലോ."},{"v":32,"t":"അത് വിജാതീയർക്ക് വെളിപാടിന്റെ പ്രകാശവും നിന്റെ ജനമായ ഇസ്രായേലിന്റെ മഹത്ത്വവുമാണ്."},{"v":33,"t":"അവനെക്കുറിച്ചു പറഞ്ഞവ കേട്ട് അവന്റെ പിതാവും മാതാവും അദ്ഭുതപ്പെട്ടു."},{"v":34,"t":"ശിമയോൻ അവരെ അനുഗ്രഹിച്ചുകൊണ്ട് അവന്റെ അമ്മയായ മറിയത്തോടു പറഞ്ഞു: ഇവൻ ഇസ്രായേലിൽ അനേകരുടെ വീഴ്ചയ്ക്കും ഉയർച്ചയ്ക്കും എതിർക്കപ്പെടുന്ന അടയാളത്തിനുമായി നിയോഗിക്കപ്പെട്ടിരിക്കുന്നു -"},{"v":35,"t":"നിന്റെതന്നെ ആത്മാവിലൂടെ ഒരു വാൾ തുളച്ചുകയറും - അനേകരുടെ ഹൃദയവിചാരങ്ങൾ വെളിപ്പെടാൻവേണ്ടിയാണിത്."},{"v":36,"t":"ഫനുവേലിന്റെ പുത്രിയും ആഷേർ വംശജയുമായ അന്ന എന്ന പ്രവാചികയും അവിടെയുണ്ടായിരുന്നു. അവൾ വയോവൃദ്ധയായിരുന്നു. കന്യാപ്രായം മുതൽ ഏഴുവർഷം വിവാഹിതയായി ജീവിച്ചു.","p":1},{"v":37,"t":"എൺപത്തിനാലു വയസ്സുള്ള ഈ വിധവ ദേവാലയം വിട്ടുപോകാതെ രാപകൽ ഉപവാസത്തിലും പ്രാർഥനയിലും ആരാധിച്ചു കഴിയുകയായിരുന്നു."},{"v":38,"t":"അവൾ ആ സമയം, മുമ്പോട്ടുവന്ന് ദൈവത്തെ സ്തുതിക്കുകയും ജറുസലേമിൽ വീണ്ടെടുപ്പ് പ്രതീക്ഷിച്ചിരുന്ന എല്ലാവരോടും അവനെക്കുറിച്ചു സംസാരിക്കുകയും ചെയ്തുകൊണ്ടിരുന്നു."},{"v":39,"t":"കർത്താവിന്റെ നിയമപ്രകാരം എല്ലാം നിവർത്തിച്ചശേഷം അവർ സ്വനഗരമായ ഗലീലിയിലെ നസറത്തിലേക്കു മടങ്ങി.","p":1},{"v":40,"t":"ശിശു വളർന്നുകൊണ്ടിരുന്നു, ജ്ഞാനം നിറഞ്ഞ് ശക്തിപ്പെട്ടുകൊണ്ടുമിരുന്നു. ദൈവത്തിന്റെ കൃപ അവന്റെമേൽ ഉണ്ടായിരുന്നു."},{"h":"ബാലനായ യേശു ദേവാലയത്തിൽ"},{"v":41,"t":"അവന്റെ മാതാപിതാക്കന്മാർ ആണ്ടുതോറും പെസഹാത്തിരുനാളിന് ജറുസലേമിലേക്കു പോകുമായിരുന്നു.","p":1},{"v":42,"t":"അവനു പന്ത്രണ്ടു വയസ്സായപ്പോൾ ആചാരമനുസരിച്ച് അവർ തിരുനാളിനു പോയി."},{"v":43,"t":"തിരുനാൾ ദിവസങ്ങൾ കഴിഞ്ഞപ്പോൾ അവർ മടങ്ങിപ്പോന്നു. ബാലനായ യേശുവാകട്ടെ, ജറുസലേമിൽ തങ്ങി. മാതാപിതാക്കന്മാർ അതറിഞ്ഞില്ല."},{"v":44,"t":"അവൻ യാത്രാസംഘത്തിന്റെ കൂടെ കാണും എന്നു വിചാരിച്ച് അവർ ഒരു ദിവസത്തെ വഴി പിന്നിട്ടു. ബന്ധുക്കളുടെയും പരിചയക്കാരുടെയും ഇടയിൽ അവനെ അന്വേഷിച്ചു."},{"v":45,"t":"എന്നാൽ, കാണായ്കയാൽ അവനെത്തിരക്കി അവർ ജറുസലേമിലേക്കു തിരിച്ചുപോയി."},{"v":46,"t":"മൂന്നു ദിവസങ്ങൾക്കുശേഷം അവർ അവനെ ദേവാലയത്തിൽ കണ്ടെത്തി. അവൻ വേദശാസ്ത്രികളുടെ ഇടയിലിരുന്ന് അവരെ കേൾക്കുകയും അവരോടു ചോദ്യങ്ങളുന്നയിക്കുകയും ചെയ്യുകയായിരുന്നു."},{"v":47,"t":"കേട്ടവരെല്ലാം അവന്റെ ഉൾക്കാഴ്ചയിലും മറുപടികളിലും അദ്ഭുതപ്പെട്ടു."},{"v":48,"t":"അവനെ കണ്ടപ്പോൾ മാതാപിതാക്കന്മാർ വിസ്മയിച്ചു. അവന്റെ അമ്മ അവനോടു പറഞ്ഞു: മകനേ, നീ ഞങ്ങളോട് ഇങ്ങനെ ചെയ്തതെന്ത്? നിന്റെ പിതാവും ഞാനും അതീവ വ്യസനിച്ചുകൊണ്ട് നിന്നെ അന്വേഷിക്കുകയായിരുന്നു."},{"v":49,"t":"അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ എന്നെ അന്വേഷിച്ചതെന്തിന്? ഞാൻ എന്റെ പിതാവിന്റെ കാര്യങ്ങളിൽ വ്യാപൃതനായിരിക്കേണ്ടതാണെന്ന് നിങ്ങൾ അറിഞ്ഞിരുന്നില്ലേ?"},{"v":50,"t":"അവൻ തങ്ങളോടു പറഞ്ഞ വാക്ക് അവർ ഗ്രഹിച്ചില്ല."},{"v":51,"t":"അവൻ അവരോടൊപ്പം ഇറങ്ങി നസറത്തിൽ വന്ന് അവർക്കു വിധേയനായി കഴിഞ്ഞു. അവന്റെ അമ്മയാകട്ടെ, ഈ കാര്യങ്ങളെല്ലാം തന്റെ ഹൃദയത്തിൽ സംഗ്രഹിച്ചുകൊണ്ടിരുന്നു."},{"v":52,"t":"യേശു, ജ്ഞാനത്തിലും ആകാരത്തിലും ദൈവത്തിന്റെയും മനുഷ്യരുടെയും കൃപയിലും വളർന്നുവന്നു."}],"3":[{"h":"സ്നാപകന്റെ പ്രഭാഷണം"},{"v":1,"t":"തിബേരിയൂസ് സീസറിന്റെ പതിനഞ്ചാംഭരണവർഷം പൊന്തിയൂസ് പീലാത്തോസ് യൂദയായുടെ ദേശാധിപതിയും ഹേറോദേസ് ഗലീലിയുടെയും അവന്റെ സഹോദരൻ പീലിപ്പോസ് ഇത്തൂറിയ, ത്രാക്കോണിത്തിസ് പ്രദേശങ്ങളുടെയും ലിസാനിയോസ് അബിലേനെയുടെയും ഭരണാധിപന്മാരും","p":1},{"v":2,"t":"അന്നാസും കയ്യാഫാസും പ്രധാന പുരോഹിതന്മാരും ആയിരിക്കേ, സഖറിയായുടെ പുത്രനായ യോഹന്നാന് മരുഭൂമിയിൽ വച്ച് ദൈവത്തിന്റെ അരുളപ്പാടുണ്ടായി."},{"v":3,"t":"അവൻ പാപമോചനത്തിനുള്ള മാനസാന്തരത്തിന്റെ സ്നാനം പ്രസംഗിച്ചുകൊണ്ട് ജോർദാന്റെ സമീപത്തുള്ള എല്ലാ പ്രദേശങ്ങളിലേക്കും വന്നു."},{"v":4,"t":"ഏശയ്യാപ്രവാചകന്റെ വചനങ്ങളുടെ പുസ്തകത്തിൽ എഴുതപ്പെട്ടിരിക്കുന്നപോലെ, മരുഭൂമിയിൽ വിളിച്ചുപറയുന്നവന്റെ ശബ്ദം: കർത്താവിന്റെ വഴി ഒരുക്കുവിൻ; അവന്റെ പാതകൾ നേരേയാക്കുവിൻ."},{"v":5,"t":"ഓരോ താഴ്വരയും നികത്തപ്പെടും, ഓരോ പർവതവും കുന്നും താഴ്ത്തപ്പെടും, വളഞ്ഞവ നേരേയാക്കപ്പെടും. ദുർഘടമായ വഴികൾ സുഗമമാക്കപ്പെടും."},{"v":6,"t":"സകല മനുഷ്യരും ദൈവത്തിന്റെ രക്ഷ കാണും."},{"v":7,"t":"അവനിൽനിന്നു സ്നാനംസ്വീകരിക്കാൻ വന്നിരുന്ന ജനക്കൂട്ടത്തോട് അവൻ ചോദിച്ചു: അണലിസന്തതികളേ, ആസന്നമായ ക്രോധത്തിൽനിന്ന് ഓടിയകലാൻ നിങ്ങൾക്കു മുന്നറിയിപ്പു നല്കിയത് ആരാണ്?","p":1},{"v":8,"t":"മാനസാന്തരത്തിനു യോജിച്ച ഫലങ്ങൾ പുറപ്പെടുവിക്കുവിൻ. ഞങ്ങൾക്കു പിതാവായി അബ്രാഹമുണ്ട് എന്ന് ഉള്ളിൽ പറയാൻ നിങ്ങൾ തുനിയരുത്. കാരണം, ഈ കല്ലുകളിൽനിന്ന് അബ്രാഹത്തിന് മക്കളെ പുറപ്പെടുവിക്കാൻ ദൈവത്തിനു കഴിയുമെന്ന് ഞാൻ നിങ്ങളോടു പറയുന്നു."},{"v":9,"t":"വൃക്ഷങ്ങളുടെ കടയ്ക്കൽ കോടാലി വയ്ക്കപ്പെട്ടുകഴിഞ്ഞു. നല്ല ഫലം നല്കാത്ത വൃക്ഷങ്ങളെല്ലാം വെട്ടി തീയിൽ എറിയപ്പെടും."},{"v":10,"t":"ജനക്കൂട്ടം അവനോടു ചോദിച്ചു: അതുകൊണ്ട് ഞങ്ങൾ എന്താണു ചെയ്യേണ്ടത്?"},{"v":11,"t":"അവൻ പറഞ്ഞു: രണ്ട് ഉടുപ്പുള്ളവൻ ഒന്നുമില്ലാത്തവനുമായി പങ്കുവയ്ക്കട്ടെ. ഭക്ഷണമുള്ളവനും ഇതുപോലെ ചെയ്യട്ടെ."},{"v":12,"t":"ചുങ്കക്കാരും സ്നാനപ്പെടാൻ വന്നു. അവരും അവനോടു ചോദിച്ചു: ഗുരോ, ഞങ്ങൾ എന്തു ചെയ്യണം?"},{"v":13,"t":"അവൻ അവരോടു പറഞ്ഞു: നിങ്ങളോട് ആജ്ഞാപിച്ചിട്ടുള്ളതിൽ കൂടുതൽ ഈടാക്കരുത്."},{"v":14,"t":"പടയാളികളും അവനോടു ചോദിച്ചു: ഞങ്ങൾ എന്തു ചെയ്യണം? അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ ആരെയും ഭീഷണിപ്പെടുത്തരുത്. വ്യാജമായി കുറ്റമാരോപിക്കരുത്. നിങ്ങളുടെ വേതനംകൊണ്ടു തൃപ്തിപ്പെടണം."},{"v":15,"t":"പ്രതീക്ഷയോടെയിരുന്ന ജനമെല്ലാം ഇവൻ തന്നെയോ ക്രിസ്തു എന്നു യോഹന്നാനെപ്പറ്റി ഹൃദയത്തിൽ വിചാരിച്ചുകൊണ്ടിരുന്നു.","p":1},{"v":16,"t":"യോഹന്നാൻ എല്ലാവരോടും മറുപടിയായി പറഞ്ഞു: ഞാൻ നിങ്ങളെ ജലംകൊണ്ടു സ്നാനപ്പെടുത്തുന്നു. എന്നെക്കാൾ ശക്തനായ ഒരുവൻ വരുന്നു. അവന്റെ ചെരുപ്പിന്റെ വാറഴിക്കാൻപോലും ഞാൻ യോഗ്യനല്ല. അവൻ പരിശുദ്ധാത്മാവാലും അഗ്നിയാലും നിങ്ങളെ സ്നാനപ്പെടുത്തും."},{"v":17,"t":"വീശുമുറം അവന്റെ കൈയിലുണ്ട്. അവൻ കളം വെടിപ്പാക്കി, ഗോതമ്പ് അറപ്പുരയിൽ ശേഖരിക്കുകയും പതിര് കെടാത്തതീയിൽ ദഹിപ്പിക്കുകയും ചെയ്യും."},{"v":18,"t":"ഇതുപോലെ, മറ്റു പലതും ഉദ്ബോധിപ്പിച്ചുകൊണ്ട് അവൻ ജനത്തെ സദ്വാർത്തയറിയിച്ചു."},{"h":"യോഹന്നാൻ കാരാഗൃഹത്തിൽ"},{"v":19,"t":"യോഹന്നാൻ ഭരണാധികാരിയായ ഹേറോദേസിനെ അവന്റെ സഹോദരഭാര്യയായ ഹേറോദിയാ നിമിത്തവും അവൻ ചെയ്തിരുന്ന മറ്റെല്ലാ ദുഷ്ടതകളുടെ പേരിലും കുറ്റപ്പെടുത്തിയിരുന്നു.","p":1},{"v":20,"t":"ഹേറോദേസാകട്ടെ, എല്ലാറ്റിനോടുംകൂടെ ഇതുംചേർത്ത് യോഹന്നാനെ കാരാഗൃഹത്തിലടച്ചു."},{"h":"യേശുവിന്റെ അഭിഷേകം"},{"v":21,"t":"ജനമെല്ലാം സ്നാനപ്പെട്ടപ്പോൾ യേശുവും സ്നാനപ്പെട്ടു. അവൻ പ്രാർഥിച്ചുകൊണ്ടിരിക്കുമ്പോൾ സ്വർഗം തുറക്കപ്പെട്ടു.","p":1},{"v":22,"t":"പരിശുദ്ധാത്മാവ് പ്രാവിന്റെ ഗാത്രരൂപത്തിൽ അവന്റെമേൽ ഇറങ്ങിവന്നു. സ്വർഗത്തിൽനിന്ന് ഒരു സ്വരമുണ്ടായി: നീ എന്റെ പ്രിയപുത്രനാകുന്നു; നിന്നിൽ ഞാൻ പ്രസാദിച്ചിരിക്കുന്നു."},{"h":"യേശുവിന്റെ വംശാവലി"},{"v":23,"t":"പരസ്യജീവിതമാരംഭിക്കുമ്പോൾ യേശുവിന് ഏകദേശം മുപ്പതുവയസ്സായിരുന്നു. അവൻ ജോസഫിന്റെ മകനാണെന്നു കരുതപ്പെട്ടിരുന്നു. ജോസഫ് ഹേലിയുടെ പുത്രനായിരുന്നു.","p":1},{"v":24,"t":"ഹേലി മത്താത്തിന്റെയും മത്താത്ത് ലേവിയുടെയും ലേവി മെൽക്കിയുടെയും മെൽക്കി യാന്നിയുടെയും യാന്നി ജോസഫിന്റെയും പുത്രൻ."},{"v":25,"t":"ജോസഫ് മത്താത്തിയായുടെയും മത്താത്തിയാ ആമോസിന്റെയും ആമോസ് നാവൂമിന്റെയും നാവൂം ഹെസ്ലിയുടെയും ഹെസ്ലി നഗ്ഗായിയുടെയും പുത്രൻ."},{"v":26,"t":"നഗ്ഗായി മാത്തിന്റെയും മാത്ത് മത്താത്തിയായുടെയും മത്താത്തിയാ സെമയിന്റെയും സെമയിൻ യോസേക്കിന്റെയും യോസേക്ക് യോദായുടെയും പുത്രൻ."},{"v":27,"t":"യോദാ യോഹന്നാന്റെയും യോഹന്നാൻ റേസായുടെയും റേസാ സെറുബാബേലിന്റെയും സെറുബാബേൽ സലാത്തിയേലിന്റെയും സലാത്തിയേൽ നേരിയുടെയും പുത്രൻ."},{"v":28,"t":"നേരി മെൽക്കിയുടെയും മെൽക്കി അദ്ദിയുടെയും അദ്ദി കോസാമിന്റെയും കോസാം എൽമാദാമിന്റെയും എൽമാദാം ഏറിന്റെയും പുത്രൻ."},{"v":29,"t":"ഏർ ജോഷ്വായുടെയും ജോഷ്വാ എലിയേസറിന്റെയും എലിയേസർ യോറീമിന്റെയും യോറീം മത്താത്തിന്റെയും മത്താത്ത് ലേവിയുടെയും പുത്രൻ."},{"v":30,"t":"ലേവി ശിമയോന്റെയും ശിമയോൻ യൂദായുടെയും യൂദാ ജോസഫിന്റെയും ജോസഫ് യോനാമിന്റെയും യോനാം ഏലിയാക്കിമിന്റെയും പുത്രൻ."},{"v":31,"t":"ഏലിയാക്കീം മെലെയായുടെയും മെലെയാ മെന്നായുടെയും മെന്നാ മത്താത്തായുടെയും മത്താത്താ നാഥാന്റെയും നാഥാൻ ദാവീദിന്റെയും പുത്രൻ."},{"v":32,"t":"ദാവീദ് ജസ്സെയുടെയും ജസ്സെ ഓബദിന്റെയും ഓബദ് ബോവാസിന്റെയും ബോവാസ് സാലായുടെയും സാലാ നഹഷോന്റെയും പുത്രൻ."},{"v":33,"t":"നഹഷോൻ അമിനാദാബിന്റെയും അമിനാദാബ് അദ്മിന്റെയും അദ്മിൻ അർനിയുടെയും അർനി ഹെസ്റോന്റെയും ഹെസ്റോൻ പേരെസിന്റെയും പേരെസ് യൂദായുടെയും പുത്രൻ."},{"v":34,"t":"യൂദാ യാക്കോബിന്റെയും യാക്കോബ് ഇസഹാക്കിന്റെയും ഇസഹാക്ക് അബ്രാഹത്തിന്റെയും അബ്രാഹം തേരായുടെയും തേരാ നാഹോറിന്റെയും പുത്രൻ."},{"v":35,"t":"നാഹോർ സെറൂഹിന്റെയും സെറൂഹ് റവുവിന്റെയും റവു പേലെഗിന്റെയും പേലെഗ് ഏബറിന്റെയും ഏബർ ഷേലായുടെയും പുത്രൻ."},{"v":36,"t":"ഷേലാ കൈനാന്റെയും കൈനാൻ അർഫക്സാദിന്റെയും അർഫക്സാദ് ഷേമിന്റെയും ഷേം നോഹയുടെയും നോഹ ലാമെക്കിന്റെയും പുത്രൻ."},{"v":37,"t":"ലാമെക്ക് മെത്തുസേലഹിന്റെയും മെത്തുസേലഹ് ഹെനോക്കിന്റെയും ഹെനോക്ക് യാരെദിന്റെയും യാരെദ് മഹലലേലിന്റെയും മഹലലേൽ കൈനാന്റെയും പുത്രൻ."},{"v":38,"t":"കൈനാൻ ഏനോസിന്റെയും ഏനോസ് സേത്തിന്റെയും സേത്ത് ആദത്തിന്റെയും ആദം ദൈവത്തിന്റെയും പുത്രൻ."}],"4":[{"h":"മരുഭൂമിയിലെ പരീക്ഷ"},{"v":1,"t":"യേശു പരിശുദ്ധാത്മാവു നിറഞ്ഞവനായി ജോർദാനിൽനിന്നു മടങ്ങി. ആത്മാവാൽ അവൻ മരുഭൂമിയിലേക്കു നയിക്കപ്പെട്ടു.","p":1},{"v":2,"t":"അവൻ നാല്പതുദിവസം പിശാചിനാൽ പരീക്ഷിക്കപ്പെട്ടു. ആ ദിനങ്ങളിൽ അവൻ ഒന്നും ഭക്ഷിച്ചില്ല. ആ ദിവസങ്ങൾ തികഞ്ഞപ്പോൾ അവനു വിശന്നു."},{"v":3,"t":"അപ്പോൾ പിശാച് അവനോടു പറഞ്ഞു: നീ ദൈവപുത്രനാണെങ്കിൽ ഈ കല്ലിനോട് അപ്പമാകാൻ കല്പിക്കുക."},{"v":4,"t":"യേശു അവനോടു പറഞ്ഞു: അപ്പംകൊണ്ടു മാത്രമല്ല, മനുഷ്യൻ ജീവിക്കുന്നതെന്ന് എഴുതപ്പെട്ടിരിക്കുന്നു."},{"v":5,"t":"പിന്നെ പിശാച് അവനെ ആനയിച്ച് ഭൂമിയിലെ സകല രാജ്യങ്ങളും ക്ഷണനേരംകൊണ്ട് അവനു കാണിച്ചുകൊടുത്തു."},{"v":6,"t":"പിശാച് അവനോടു പറഞ്ഞു: ഈ എല്ലാ അധികാരവും അവയുടെ മഹത്ത്വവും നിനക്കു ഞാൻ നല്കാം. കാരണം, ഇതെല്ലാം എനിക്ക് ഏല്പിക്കപ്പെട്ടിരിക്കുന്നു. എനിക്കിഷ്ടമുള്ളവർക്ക് ഞാൻ ഇതു നല്കുന്നു."},{"v":7,"t":"നീ എന്നെ ആരാധിച്ചാൽ ഇവയെല്ലാം നിന്റേതാകും."},{"v":8,"t":"യേശു മറുപടി പറഞ്ഞു: നിന്റെ ദൈവമായ കർത്താവിനെ നീ ആരാധിക്കണം; അവനെ മാത്രമേ നമിക്കാവൂ എന്ന് എഴുതപ്പെട്ടിരിക്കുന്നു."},{"v":9,"t":"അനന്തരം, പിശാച് അവനെ ജറുസലേമിലേക്കു കൊണ്ടുപോയി. ദേവാലയഗോപുരത്തിന്റെ ശൃംഗത്തിൽ നിറുത്തിക്കൊണ്ട് അവനോടു പറഞ്ഞു: നീ ദൈവപുത്രനാണെങ്കിൽ ഇവിടെനിന്നു താഴേക്കു ചാടുക."},{"v":10,"t":"നിന്നെ സംരക്ഷിക്കാൻ അവൻ ദൂതന്മാരോടു കല്പിക്കുമെന്നും"},{"v":11,"t":"നിന്റെ കാൽ കല്ലിൽ തട്ടാതെ അവർ നിന്നെ കൈകളിൽ താങ്ങിക്കൊള്ളുമെന്നും എഴുതപ്പെട്ടിട്ടുണ്ടല്ലോ."},{"v":12,"t":"യേശു മറുപടി പറഞ്ഞു: നിന്റെ ദൈവമായ കർത്താവിനെ പരീക്ഷിക്കരുത് എന്നും പറയപ്പെട്ടിരിക്കുന്നു."},{"v":13,"t":"അപ്പോൾ പിശാച് എല്ലാ പരീക്ഷയും അവസാനിപ്പിച്ച് തക്കസമയംവരെ അവനെ വിട്ടുപോയി."},{"h":"യേശു ദൗത്യമാരംഭിക്കുന്നു"},{"v":14,"t":"യേശു ആത്മാവിന്റെ ശക്തിയോടുകൂടെ ഗലീലിയിലേക്കു മടങ്ങിപ്പോയി. അവന്റെ കീർത്തി സമീപപ്രദേശങ്ങളിലെങ്ങും വ്യാപിച്ചു.","p":1},{"v":15,"t":"അവൻ സിനഗോഗുകളിൽ പഠിപ്പിച്ചുകൊണ്ടിരുന്നു. എല്ലാവരും അവനെ പുകഴ്ത്തി."},{"h":"പ്രവാചകൻ സ്വദേശത്ത് അവഗണിക്കപ്പെടുന്നു"},{"v":16,"t":"യേശു താൻ വളർന്ന സ്ഥലമായ നസറത്തിൽ വന്നു. ഒരു സാബത്തുദിവസം അവൻ പതിവുപോലെ സിനഗോഗിൽ പ്രവേശിച്ച് വായിക്കാൻ എഴുന്നേറ്റുനിന്നു.","p":1},{"v":17,"t":"ഏശയ്യാപ്രവാചകന്റെ ചുരുൾ അവനു നല്കപ്പെട്ടു. ചുരുൾ നിവർത്തിയപ്പോൾ ഇപ്രകാരം എഴുതിയിരിക്കുന്ന ഭാഗം അവൻ കണ്ടു:"},{"v":18,"t":"കർത്താവിന്റെ ആത്മാവ് എന്റെമേലുണ്ട്. എന്തെന്നാൽ, ദരിദ്രരെ സദ്വാർത്ത അറിയിക്കാൻ അവൻ എന്നെ അഭിഷേചിച്ചിരിക്കുന്നു. ബന്ധിതർക്കു മോചനവും അന്ധർക്കു കാഴ്ചയും പ്രഘോഷിക്കാനും അടിച്ചമർത്തപ്പെട്ടവരെ മോചനത്തിലേക്കു നയിക്കാനും"},{"v":19,"t":"കർത്താവിന്റെ പ്രസാദവത്സരം പ്രഘോഷിക്കാനും അവൻ എന്നെ അയച്ചിരിക്കുന്നു."},{"v":20,"t":"ചുരുൾ മടക്കി ശുശ്രൂഷകനെ ഏല്പിച്ചശേഷം അവൻ ഇരുന്നു. സിനഗോഗിൽ ഉണ്ടായിരുന്ന എല്ലാവരുടെയും കണ്ണുകൾ അവനിൽ തറച്ചിരുന്നു."},{"v":21,"t":"അവൻ അവരോടു പറയാൻ തുടങ്ങി: നിങ്ങൾ കേട്ടിരിക്കെത്തന്നെ ഇന്ന് ഈ തിരുവെഴുത്ത് പൂർത്തിയാക്കപ്പെട്ടിരിക്കുന്നു."},{"v":22,"t":"എല്ലാവരും അവനെപ്പറ്റി സാക്ഷ്യപ്പെടുത്തുകയും അവന്റെ നാവിൽനിന്നു പുറപ്പെട്ട കൃപാവചസ്സുകൾകേട്ട് അദ്ഭുതപ്പെടുകയും ചെയ്തു. ഇവൻ ജോസഫിന്റെ മകനല്ലേ എന്ന് അവർ ചോദിച്ചു."},{"v":23,"t":"അവൻ അവരോടു പറഞ്ഞു: വൈദ്യാ, നിന്നെത്തന്നെ സുഖപ്പെടുത്തുക എന്ന ചൊല്ല് ഉദ്ധരിച്ചുകൊണ്ട്, തീർച്ചയായും നിങ്ങൾ എന്നോട് കഫർണാമിൽ സംഭവിച്ചതായി ഞങ്ങൾ കേട്ട കാര്യങ്ങൾ ഇവിടെ നിന്റെ സ്വന്തം സ്ഥലത്തും ചെയ്യുക എന്നുപറയും."},{"v":24,"t":"അവൻ പറഞ്ഞു: എന്നാൽ സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു: ഒരു പ്രവാചകനും സ്വന്തം നാട്ടിൽ സ്വീകാര്യനല്ല."},{"v":25,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു: ഏലിയാപ്രവാചകന്റെ കാലത്ത് ഇസ്രായേലിൽ അനേകം വിധവകൾ ഉണ്ടായിരുന്നു. അന്ന് മൂന്നു വർഷവും ആറുമാസവും ആകാശം അടയ്ക്കപ്പെടുകയും ഭൂമിയിലെങ്ങും രൂക്ഷമായ ക്ഷാമം ഉണ്ടാകുകയും ചെയ്തു."},{"v":26,"t":"എന്നാൽ, സിദോനിൽ സറെപ്തായിലെ ഒരു വിധവയുടെ അടുത്തേക്കല്ലാതെ മറ്റാരുടെയും അടുത്തേക്ക് ഏലിയാ അയയ്ക്കപ്പെട്ടില്ല."},{"v":27,"t":"ഏലീഷപ്രവാചകന്റെ കാലത്ത് ഇസ്രായേലിൽ അനേകം കുഷ്ഠരോഗികൾ ഉണ്ടായിരുന്നു. എന്നാൽ, അവരിൽ സിറിയാക്കാരനായ നാമാൻ അല്ലാതെ മറ്റാരും ശുദ്ധമാക്കപ്പെട്ടില്ല."},{"v":28,"t":"ഇതു കേട്ടപ്പോൾ സിനഗോഗിൽ ഉണ്ടായിരുന്ന എല്ലാവരും രോഷംകൊണ്ടു നിറഞ്ഞു."},{"v":29,"t":"അവർ എഴുന്നേറ്റ് അവനെ പട്ടണത്തിൽനിന്നു പുറത്താക്കുകയും തങ്ങളുടെ പട്ടണം സ്ഥിതിചെയ്യുന്ന മലയുടെ ശൃംഗത്തിൽ നിന്നു താഴേക്കു തള്ളിയിടാൻ കൊണ്ടുപോകുകയും ചെയ്തു."},{"v":30,"t":"എന്നാൽ അവനോ, അവരുടെ ഇടയിലൂടെ കടന്നുപോയി."},{"h":"പിശാചുബാധിതനെ സുഖപ്പെടുത്തുന്നു"},{"v":31,"t":"പിന്നെ അവൻ ഗലീലിയിലെ ഒരു പട്ടണമായ കഫർണാമിലേക്കു പോയി. സാബത്തിൽ അവരെ പഠിപ്പിച്ചുകൊണ്ടിരുന്നു.","p":1},{"v":32,"t":"അവന്റെ പ്രബോധനത്തിൽ അവർ വിസ്മയഭരിതരായി. കാരണം, അധികാരത്തോടെയായിരുന്നു അവന്റെ വചനം."},{"v":33,"t":"അശുദ്ധാത്മാവു ബാധിച്ച ഒരു മനുഷ്യൻ സിനഗോഗിൽ ഉണ്ടായിരുന്നു. അവൻ വലിയ സ്വരത്തിൽ വിളിച്ചു പറഞ്ഞു:"},{"v":34,"t":"ഹാ! നസറായനായ യേശുവേ, ഞങ്ങൾക്കും നിനക്കുമെന്ത്? ഞങ്ങളെ നശിപ്പിക്കാനാണോ നീ വന്നിരിക്കുന്നത്? നീ ആരാണെന്ന് എനിക്കറിയാം; ദൈവത്തിന്റെ പരിശുദ്ധൻ."},{"v":35,"t":"യേശു അവനെ ശാസിച്ചു പറഞ്ഞു: മിണ്ടരുത്, അവനെ വിട്ടുപോകൂ. ആ പിശാച് ഉപദ്രവമൊന്നും വരുത്താതെ നടുവിലേക്കു തള്ളിയിട്ടശേഷം അവനെ വിട്ടുപോയി."},{"v":36,"t":"എല്ലാവരും അദ്ഭുതപ്പെട്ട് പരസ്പരം പറഞ്ഞു: എന്തൊരു വചനമാണിത്! ഇവൻ അധികാരത്തോടും ശക്തിയോടുംകൂടെ അശുദ്ധാത്മാക്കളോടു കല്പിക്കുകയും അവ വിട്ടുപോകുകയും ചെയ്യുന്നല്ലോ."},{"v":37,"t":"അവനെപ്പറ്റിയുള്ള വാർത്ത സമീപപ്രദേശങ്ങളിലെല്ലാം വ്യാപിച്ചു."},{"h":"യേശു പത്രോസിന്റെ ഭവനത്തിൽ"},{"v":38,"t":"അവൻ സിനഗോഗിൽനിന്നെഴുന്നേറ്റ് ശിമയോന്റെ വീട്ടിലേക്കു പോയി. ശിമയോന്റെ അമ്മായിയമ്മ കലശലായ പനിബാധിച്ചു കിടപ്പായിരുന്നു. ആളുകൾ അവൾക്കുവേണ്ടി അവനോട് അപേക്ഷിച്ചു.","p":1},{"v":39,"t":"അവൻ അവളുടെ അടുത്തു ചെന്ന് പനിയെ ശാസിച്ചു. അത് അവളെ വിട്ടുമാറി. ഉടനെ അവൾ എഴുന്നേറ്റ് അവരെ ശുശ്രൂഷിച്ചു."},{"v":40,"t":"സൂര്യാസ്തമയമായപ്പോൾ, വിവിധരോഗങ്ങളാൽ അവശരായവരെയെല്ലാം അവർ അവന്റെ അടുത്തുകൊണ്ടുവന്നു. ഓരോരുത്തരുടെയുംമേൽ കൈവച്ച് അവൻ അവരെ സുഖപ്പെടുത്തി."},{"v":41,"t":"നീ ദൈവപുത്രനാണ് എന്ന് ഉറക്കെ വിളിച്ചു പറഞ്ഞുകൊണ്ട് അനേകരിൽനിന്ന് പിശാചുക്കൾ വിട്ടുപോയി. അവൻ അവയെ ശാസിച്ചു. സംസാരിക്കാൻ അവൻ അവയെ അനുവദിച്ചില്ല. കാരണം, അവൻ ക്രിസ്തുവാണെന്ന് അവയ്ക്ക് അറിയാമായിരുന്നു."},{"h":"യൂദയായിലെ ശുശ്രൂഷ"},{"v":42,"t":"പ്രഭാതമായപ്പോൾ അവൻ പുറപ്പെട്ട് ഒരു വിജനസ്ഥലത്തേക്കു പോയി. ജനക്കൂട്ടം അവനെ അന്വേഷിച്ചു ചെന്നു. തങ്ങളെ വിട്ടുപോകുന്നതിൽനിന്ന് അവർ അവനെ തടഞ്ഞു.","p":1},{"v":43,"t":"എന്നാൽ, അവൻ പറഞ്ഞു: മറ്റു പട്ടണങ്ങളിലും ഞാൻ ദൈവരാജ്യത്തിന്റെ സദ്വാർത്ത അറിയിക്കേണ്ടിയിരിക്കുന്നു. എന്തെന്നാൽ, അതിനുവേണ്ടിയാണ് ഞാൻ അയയ്ക്കപ്പെട്ടിരിക്കുന്നത്."},{"v":44,"t":"അവൻ യൂദയായിലെ സിനഗോഗുകളിൽ പ്രസംഗിച്ചുകൊണ്ടിരുന്നു."}],"5":[{"h":"ശിമയോനെ വിളിക്കുന്നു"},{"v":1,"t":"ദൈവവചനം ശ്രവിക്കാൻ ജനക്കൂട്ടം അവനു ചുറ്റും തിങ്ങിക്കൂടി. അവൻ ഗനേസറത്തുതടാകത്തിന്റെ തീരത്തു നില്ക്കുകയായിരുന്നു.","p":1},{"v":2,"t":"രണ്ടു വള്ളങ്ങൾ കരയോടടുത്തുകിടക്കുന്നത് അവൻ കണ്ടു. മീൻപിടിത്തക്കാർ അവയിൽ നിന്നിറങ്ങി വല കഴുകുകയായിരുന്നു."},{"v":3,"t":"ശിമയോന്റേതായിരുന്നു വള്ളങ്ങളിൽ ഒന്ന്. അവൻ അതിൽ കയറി കരയിൽനിന്ന് അല്പം നീക്കാൻ ആവശ്യപ്പെട്ടു. വഞ്ചിയിലിരുന്ന് അവൻ ജനക്കൂട്ടത്തെ പഠിപ്പിച്ചു."},{"v":4,"t":"സംസാരിച്ചുതീർന്നപ്പോൾ അവൻ ശിമയോനോടു പറഞ്ഞു: മീൻപിടിക്കാൻ ആഴത്തിലേക്കു നീക്കി നിങ്ങളുടെ വലയിറക്കുക."},{"v":5,"t":"ശിമയോൻ മറുപടി പറഞ്ഞു: ഗുരോ, രാത്രി മുഴുവൻ അധ്വാനിച്ചിട്ടും ഞങ്ങൾക്ക് ഒന്നും കിട്ടിയില്ല. എങ്കിലും നിന്റെ വാക്കനുസരിച്ച് ഞാൻ വലയിറക്കാം."},{"v":6,"t":"അങ്ങനെ ചെയ്തപ്പോൾ വളരെ വലിയൊരു മത്സ്യക്കൂട്ടത്തെ അവർ പിടിച്ചു. അവരുടെ വല കീറിത്തുടങ്ങി."},{"v":7,"t":"അവർ മറ്റേ വള്ളത്തിൽ ഉണ്ടായിരുന്ന പങ്കുകാരെ സഹായത്തിനുവരാൻ ആംഗ്യം കാണിച്ചു. അവർ വന്ന് രണ്ടു വള്ളങ്ങളും മുങ്ങാറാകുവോളം നിറച്ചു."},{"v":8,"t":"ഇതു കണ്ടപ്പോൾ ശിമയോൻപത്രോസ് യേശുവിന്റെ കാല്ക്കൽ വീണ്, കർത്താവേ, എന്നിൽനിന്ന് അകന്നുപോകണമേ, ഞാൻ പാപിയാണ് എന്നുപറഞ്ഞു."},{"v":9,"t":"എന്തെന്നാൽ, തങ്ങൾ നടത്തിയ മീൻപിടിത്തത്തെപ്പറ്റി ശിമയോനും കൂടെയുണ്ടായിരുന്ന എല്ലാവരും അദ്ഭുതപ്പെട്ടു."},{"v":10,"t":"അതുപോലെതന്നെ, അവന്റെ കൂട്ടാളികളായ സെബദിപുത്രന്മാർ - യാക്കോബും യോഹന്നാനും - വിസ്മയിച്ചു. ശിമയോനോട് യേശു പറഞ്ഞു: ഭയപ്പെടേണ്ടാ; ഇപ്പോൾ മുതൽ നീ മനുഷ്യരെപ്പിടിക്കുന്നവനാകും."},{"v":11,"t":"വള്ളങ്ങൾ കരയ്ക്കടുപ്പിച്ചശേഷം എല്ലാം ഉപേക്ഷിച്ച് അവർ അവനെ അനുഗമിച്ചു."},{"h":"കുഷ്ഠരോഗിയെ ശുദ്ധനാക്കുന്നു"},{"v":12,"t":"പിന്നീടൊരിക്കൽ യേശു ഒരു പട്ടണത്തിലായിരിക്കുമ്പോൾ ഇതാ, കുഷ്ഠം നിറഞ്ഞ ഒരുവൻ വന്ന് അവനെ കണ്ട് അവന്റെ മുമ്പിൽ കമിഴ്ന്നുവീണു പ്രാർഥിച്ചു: കർത്താവേ, അങ്ങേക്കു മനസ്സുണ്ടെങ്കിൽ എന്നെ ശുദ്ധനാക്കാൻ കഴിയും.","p":1},{"v":13,"t":"യേശു കൈനീട്ടി അവനെ തൊട്ടുകൊണ്ടു പറഞ്ഞു: എനിക്കു മനസ്സുണ്ട്; നിനക്കു ശുദ്ധിയുണ്ടാകട്ടെ! തത്ക്ഷണം കുഷ്ഠം അവനെ വിട്ടുമാറി."},{"v":14,"t":"യേശു അവനോടു കല്പിച്ചു: ഇക്കാര്യം നീ ആരോടും പറയരുത്. പോയി, നിന്നെത്തന്നെ പുരോഹിതനു കാണിച്ചു കൊടുക്കുകയും മോശ കല്പിച്ചിട്ടുള്ളതനുസരിച്ച് അവർക്കു തെളിവിനായി നിന്റെ ശുദ്ധീകരണക്കാഴ്ച സമർപ്പിക്കുകയും ചെയ്യുക."},{"v":15,"t":"എന്നാൽ, യേശുവിനെക്കുറിച്ചുള്ള വാർത്ത പൂർവാധികം വ്യാപിച്ചുകൊണ്ടിരുന്നു. വലിയ ജനക്കൂട്ടം അവനെ കേൾക്കാനും രോഗങ്ങളിൽനിന്നു സുഖപ്പെടാനും വന്നുകൂടിക്കൊണ്ടിരുന്നു."},{"v":16,"t":"അവനാകട്ടെ, മരുഭൂമിയിലേക്കു പിൻവാങ്ങി പ്രാർഥിച്ചുകൊണ്ടിരുന്നു."},{"h":"തളർവാതരോഗിയെ സുഖപ്പെടുത്തുന്നു"},{"v":17,"t":"ഒരു ദിവസം യേശു പഠിപ്പിച്ചുകൊണ്ടിരിക്കുമ്പോൾ, ഗലീലിയിലെ എല്ലാ ഗ്രാമങ്ങളിലുംനിന്നും യൂദയായിൽനിന്നും ജറുസലേമിൽനിന്നും വന്ന ഫരിസേയരും നിയമാധ്യാപകന്മാരും അവിടെ ഇരുന്നിരുന്നു. രോഗികളെ സുഖപ്പെടുത്താൻ കർത്താവിന്റെ ശക്തി അവനിൽ ഉണ്ടായിരുന്നു.","p":1},{"v":18,"t":"അപ്പോൾ, ചിലർ ഒരു തളർവാതരോഗിയെ കിടക്കയിൽ എടുത്തുകൊണ്ടുവന്നു. അവർ അവനെ അകത്തുകൊണ്ടുവന്ന് യേശുവിന്റെ മുമ്പിൽ കിടത്താൻ ശ്രമിച്ചു."},{"v":19,"t":"ജനക്കൂട്ടം നിമിത്തം ഒരു വഴിയും കാണാഞ്ഞ് അവർ പുരമുകളിൽ കയറി മേച്ചിൽ ഇളക്കി കിടക്കയോടെ അവനെ അവരുടെ മധ്യേ യേശുവിന്റെ സമക്ഷം വച്ചു."},{"v":20,"t":"അവരുടെ വിശ്വാസം കണ്ട് അവൻ പറഞ്ഞു: മനുഷ്യാ, നിന്റെ പാപങ്ങൾ നിന്നോടു ക്ഷമിക്കപ്പെട്ടിരിക്കുന്നു."},{"v":21,"t":"നിയമജ്ഞരും ഫരിസേയരും ഉള്ളിൽ ചിന്തിച്ചുകൊണ്ടു പറഞ്ഞു: ദൈവദൂഷണം പറയുന്ന ഇവൻ ആര്? ആർക്കാണ് പാപങ്ങൾ ക്ഷമിക്കാൻ കഴിയുക, ദൈവത്തിനുമാത്രമല്ലാതെ?"},{"v":22,"t":"അവരുടെ വിചാരങ്ങൾ മനസ്സിലാക്കി യേശു അവരോടു മറുപടി പറഞ്ഞു: എന്താണ് നിങ്ങൾ ഹൃദയത്തിൽ സംവദിക്കുന്നത്?"},{"v":23,"t":"ഏതാണ് കൂടുതൽ എളുപ്പം? നിന്റെ പാപങ്ങൾ നിന്നോടു ക്ഷമിക്കപ്പെട്ടിരിക്കുന്നു എന്നു പറയുന്നതോ എഴുന്നേറ്റു നടക്കുക എന്നു പറയുന്നതോ?"},{"v":24,"t":"ഭൂമിയിൽ പാപങ്ങൾ ക്ഷമിക്കാൻ മനുഷ്യപുത്രന് അധികാരമുണ്ടെന്നു നിങ്ങൾ അറിയേണ്ടതിന് അവൻ തളർവാതരോഗിയോടു പറഞ്ഞു: ഞാൻ നിന്നോടു പറയുന്നു, എഴുന്നേറ്റ് നിന്റെ കിടക്കയെടുത്ത് വീട്ടിലേക്കു പോകുക."},{"v":25,"t":"ഉടനെ അവരുടെ മുമ്പാകേ അവൻ എഴുന്നേറ്റ് താൻ കിടന്നിരുന്ന കിടക്കയെടുത്ത് ദൈവത്തെ സ്തുതിച്ചുകൊണ്ട് വീട്ടിലേക്കുപോയി."},{"v":26,"t":"എല്ലാവരും വിസ്മയഭരിതരായി ദൈവത്തെ മഹത്ത്വപ്പെടുത്തി. അവർ ഭയപൂരിതരായി പറഞ്ഞു: ഇന്നു നാം വിചിത്രമായവ കണ്ടിരിക്കുന്നു!"},{"h":"ലേവിയെ വിളിക്കുന്നു"},{"v":27,"t":"ഇതിനുശേഷം യേശു പുറത്തേക്കിറങ്ങിയപ്പോൾ ലേവി എന്നു പേരുള്ള ചുങ്കക്കാരൻ ചുങ്കസ്ഥലത്തിരിക്കുന്നതു ശ്രദ്ധിച്ചു. അവൻ അവനോടു പറഞ്ഞു: എന്നെ അനുഗമിക്കുക.","p":1},{"v":28,"t":"അവൻ എല്ലാം ഉപേക്ഷിച്ച് എഴുന്നേറ്റ് അവനെ അനുഗമിച്ചു."},{"v":29,"t":"ലേവി തന്റെ വീട്ടിൽ അവനുവേണ്ടി ഒരു വലിയ വിരുന്നൊരുക്കി. ചുങ്കക്കാരും മറ്റുള്ളവരുമായി വലിയൊരു ജനക്കൂട്ടം അവരോടൊപ്പം ഭക്ഷണത്തിനിരുന്നു."},{"v":30,"t":"ഫരിസേയരും അവരുടെ നിയമജ്ഞരും ശിഷ്യന്മാർക്കെതിരേ പിറുപിറുത്തു: എന്തുകൊണ്ടാണ് നിങ്ങൾ ചുങ്കക്കാരോടും പാപികളോടുമൊത്ത് തിന്നുകയും കുടിക്കുകയും ചെയ്യുന്നത്?"},{"v":31,"t":"യേശു അവരോടു മറുപടി പറഞ്ഞു: വൈദ്യനെ ആവശ്യം ആരോഗ്യമുള്ളവർക്കല്ല, രോഗികൾക്കാണ്."},{"v":32,"t":"ഞാൻ വന്നിരിക്കുന്നത് നീതിമാന്മാരെ വിളിക്കാനല്ല, പാപികളെ പശ്ചാത്താപത്തിലേക്കു വിളിക്കാനാണ്."},{"h":"ഉപവാസംസംബന്ധിച്ചു തർക്കം"},{"v":33,"t":"അവർ അവനോടു പറഞ്ഞു: യോഹന്നാന്റെ ശിഷ്യന്മാർ മിക്കപ്പോഴും ഉപവസിക്കുകയും പ്രാർഥിക്കുകയും ചെയ്യുന്നു; അങ്ങനെതന്നെ ഫരിസേയരുടെ ശിഷ്യന്മാരും. എന്നാൽ, നിന്റെ കൂടെയുള്ളവർ തിന്നുകയും കുടിക്കുകയും ചെയ്യുന്നു.","p":1},{"v":34,"t":"യേശു അവരോടു മറുപടി പറഞ്ഞു: മണവാളൻ കൂടെയുള്ളപ്പോൾ മണവറത്തോഴരെക്കൊണ്ട് ഉപവസിപ്പിക്കാൻ നിങ്ങൾക്കു കഴിയുമോ?"},{"v":35,"t":"എന്നാൽ, മണവാളൻ അവരിൽനിന്ന് എടുക്കപ്പെടുന്ന ദിവസങ്ങൾ വരും; ആ ദിവസങ്ങളിൽ അവർ ഉപവസിക്കും."},{"v":36,"t":"അവൻ അവരോട് ഒരു ഉപമയും പറഞ്ഞു: ആരും പുതിയ വസ്ത്രത്തിൽനിന്ന് കഷണം കീറിയെടുത്ത് പഴയ വസ്ത്രത്തോടു ചേർക്കാറില്ല. അങ്ങനെ ചെയ്താൽ പുതിയ വസ്ത്രം കീറുന്നു എന്നു മാത്രമല്ല, പുതിയ കഷണം പഴയതിനോട് ചേരാതെവരുകയും ചെയ്യും."},{"v":37,"t":"ആരും പുതിയ വീഞ്ഞ് പഴയ തോല്ക്കുടങ്ങളിൽ ഒഴിച്ചുവയ്ക്കാറില്ല. അങ്ങനെ ചെയ്താൽ, പുതിയ വീഞ്ഞ് പഴയ തോല്ക്കുടങ്ങൾ ഭേദിച്ച് ഒഴുകിപ്പോകുകയും തോല്ക്കുടങ്ങൾ നശിക്കുകയും ചെയ്യും."},{"v":38,"t":"പുതിയ വീഞ്ഞ് പുതിയ തോല്ക്കുടങ്ങളിലാണ് ഒഴിച്ചുവയ്ക്കേണ്ടത്."},{"v":39,"t":"പഴയ വീഞ്ഞു കുടിച്ച ഒരുവനും പുതിയത് ഇഷ്ടപ്പെടുകയില്ല. എന്തെന്നാൽ, പഴയതാണു മെച്ചം എന്നാണല്ലോ പറയുന്നത്."}],"6":[{"h":"സാബത്തിനെപ്പറ്റി തർക്കം"},{"v":1,"t":"ഒരു സാബത്തുദിവസം യേശു ധാന്യവയലിലൂടെ കടന്നുപോകുമ്പോൾ, അവന്റെ ശിഷ്യന്മാർ കതിരുകൾ പറിച്ച് കൈകൊണ്ടു തിരുമ്മിത്തിന്നുകൊണ്ടിരുന്നു.","p":1},{"v":2,"t":"ഫരിസേയരിൽ ചിലർ ചോദിച്ചു: എന്തുകൊണ്ടാണ് സാബത്തിൽ നിഷിദ്ധമായത് നിങ്ങൾ ചെയ്യുന്നത്?"},{"v":3,"t":"യേശു മറുപടി പറഞ്ഞു: വിശന്നപ്പോൾ ദാവീദും കൂടെയുണ്ടായിരുന്നവരും എന്താണു ചെയ്തതെന്ന് നിങ്ങൾ വായിച്ചിട്ടില്ലേ?"},{"v":4,"t":"അവൻ ദൈവത്തിന്റെ ഭവനത്തിൽ പ്രവേശിച്ച്, പുരോഹിതന്മാർക്കല്ലാതെ മറ്റാർക്കും ഭക്ഷിക്കാൻ അനുവാദമില്ലാത്ത കാഴ്ചയപ്പം എടുത്തു ഭക്ഷിക്കുകയും കൂടെയുണ്ടായിരുന്നവർക്കു കൊടുക്കുകയും ചെയ്തതെങ്ങനെ?"},{"v":5,"t":"അവൻ അവരോടു പറഞ്ഞു: മനുഷ്യപുത്രൻ സാബത്തിന്റെ കർത്താവാകുന്നു."},{"v":6,"t":"മറ്റൊരു സാബത്തിൽ അവൻ സിനഗോഗിൽ പ്രവേശിച്ച് പഠിപ്പിക്കുകയായിരുന്നു. അവിടെ വലത്തുകൈ ശോഷിച്ച ഒരുവൻ ഉണ്ടായിരുന്നു."},{"v":7,"t":"നിയമജ്ഞരും ഫരിസേയരും അവനിൽ കുറ്റമാരോപിക്കാൻ പഴുതുനോക്കി, സാബത്തിൽ സുഖപ്പെടുത്തുമോ എന്നു ശ്രദ്ധിച്ചുകൊണ്ടിരുന്നു."},{"v":8,"t":"അവൻ അവരുടെ വിചാരങ്ങൾ മനസ്സിലാക്കിയിട്ട്, കൈശോഷിച്ചവനോടു പറഞ്ഞു: എഴുന്നേറ്റ് നടുക്കുനില്ക്കുക. അവൻ എഴുന്നേറ്റുനിന്നു."},{"v":9,"t":"യേശു അവരോടു പറഞ്ഞു: ഞാൻ നിങ്ങളോടു ചോദിക്കുന്നു, സാബത്തിൽ നന്മ ചെയ്യുന്നതോ തിന്മ ചെയ്യുന്നതോ ജീവൻ രക്ഷിക്കുന്നതോ നശിപ്പിക്കുന്നതോ ഏതാണ് അനുവദനീയം?"},{"v":10,"t":"അവൻ ചുറ്റുമുള്ളവരെയെല്ലാം നോക്കിക്കൊണ്ട് അവനോടു പറഞ്ഞു: നിന്റെ കൈ നീട്ടുക. അവൻ അങ്ങനെ ചെയ്തു. അവന്റെ കൈ സുഖപ്പെട്ടു."},{"v":11,"t":"അവർ രോഷംപൂണ്ട് യേശുവിനെ എന്താണു ചെയ്യേണ്ടതെന്ന് പരസ്പരം ആലോചിച്ചു."},{"h":"അപ്പസ്തോലന്മാരെ തിരഞ്ഞെടുക്കുന്നു"},{"v":12,"t":"ആ ദിവസങ്ങളിൽ അവൻ പ്രാർഥിക്കാൻ ഒരു മലയിലേക്കു പോയി. അവിടെ അവൻ ദൈവത്തോടുള്ള പ്രാർഥനയിൽ രാത്രി മുഴുവൻ ചെലവഴിച്ചു.","p":1},{"v":13,"t":"പ്രഭാതമായപ്പോൾ അവൻ ശിഷ്യന്മാരെ അടുത്തു വിളിച്ച് അവരിൽനിന്നു പന്ത്രണ്ടുപേരെ തിരഞ്ഞെടുത്ത് അവർക്ക് അപ്പസ്തോലന്മാർ എന്നു പേരു നല്കി."},{"v":14,"t":"അവർ, പത്രോസ് എന്ന് അവൻ പേരു നല്കിയ ശിമയോൻ, അവന്റെ സഹോദരനായ അന്ത്രയോസ്, യാക്കോബ്, യോഹന്നാൻ, പീലിപ്പോസ്, ബർത്തലോമിയോ,"},{"v":15,"t":"മത്തായി, തോമസ്, ഹൽപൈയുടെ പുത്രനായ യാക്കോബ്, തീവ്രവാദിയെന്നു വിളിക്കപ്പെട്ടിരുന്ന ശിമയോൻ,"},{"v":16,"t":"യാക്കോബിന്റെ മകനായ യൂദാസ്, ഒറ്റുകാരനായിത്തീർന്ന യൂദാസ് സ്കറിയോത്ത എന്നിവരാണ്."},{"h":"സമതലത്തിലെ ശുശ്രൂഷ"},{"v":17,"t":"അവൻ അവരോടുകൂടെ ഇറങ്ങി സമതലത്തിൽ നിന്നു. ശിഷ്യന്മാരുടെ ഒരു വലിയ കൂട്ടവും യൂദയാ മുഴുവനിലും നിന്നും ജറുസലേമിൽനിന്നും ടയിർ, സിദോൻ എന്നീ തീരപ്രദേശങ്ങളിൽനിന്നുമുള്ള ജനത്തിന്റെ വലിയൊരുസംഘവും ഉണ്ടായിരുന്നു.","p":1},{"v":18,"t":"അവർ അവനെ ശ്രവിക്കുന്നതിനും തങ്ങളുടെ രോഗങ്ങളിൽനിന്നു സുഖപ്പെടുന്നതിനും വന്നു. അശുദ്ധാത്മാക്കളാൽ പീഡിതരായവരും സുഖപ്പെട്ടു."},{"v":19,"t":"ജനക്കൂട്ടമെല്ലാം അവനെ ഒന്നു സ്പർശിക്കാൻ ശ്രമിച്ചിരുന്നു. എന്തെന്നാൽ, അവനിൽനിന്നു ശക്തി പുറപ്പെടുകയും എല്ലാവരെയും സുഖപ്പെടുത്തുകയും ചെയ്തിരുന്നു."},{"h":"സുവിശേഷഭാഗ്യങ്ങൾ"},{"v":20,"t":"അവൻ തന്റെ ശിഷ്യരുടെ നേരേ കണ്ണുകളുയർത്തി അരുൾചെയ്തു: ദരിദ്രരേ, നിങ്ങൾ അനുഗൃഹീതർ, എന്തെന്നാൽ, ദൈവരാജ്യം നിങ്ങളുടേതാകുന്നു.","p":1},{"v":21,"t":"ഇപ്പോൾ വിശക്കുന്നവരേ, നിങ്ങൾ അനുഗൃഹീതർ. എന്തെന്നാൽ നിങ്ങൾ തൃപ്തരാക്കപ്പെടും. ഇപ്പോൾ കരയുന്നവരേ, നിങ്ങൾ അനുഗൃഹീതർ. എന്തെന്നാൽ നിങ്ങൾ ചിരിക്കും."},{"v":22,"t":"മനുഷ്യപുത്രൻ നിമിത്തം മനുഷ്യർ നിങ്ങളെ ദ്വേഷിക്കുകയും ഒറ്റപ്പെടുത്തുകയും അവഹേളിക്കുകയും നിങ്ങളുടെ പേരു ദുഷിച്ചതായി കരുതി പുറന്തള്ളുകയും ചെയ്യുമ്പോൾ നിങ്ങൾ അനുഗൃഹീതർ."},{"v":23,"t":"ആ ദിവസം നിങ്ങൾ സന്തോഷിക്കുകയും കുതിച്ചുചാടുകയും ചെയ്യുവിൻ. എന്തെന്നാൽ സ്വർഗത്തിൽ നിങ്ങളുടെ പ്രതിഫലം വലുതായിരിക്കും അവരുടെ പിതാക്കന്മാർ പ്രവാചകന്മാരോടും ഇപ്രകാരം തന്നെയാണു പ്രവർത്തിച്ചത്."},{"h":"ദുരിതങ്ങൾ"},{"v":24,"t":"എന്നാൽ, സമ്പന്നരേ, നിങ്ങൾക്കു ദുരിതം! എന്തെന്നാൽ, നിങ്ങളുടെ ആശ്വാസം നിങ്ങൾക്കു ലഭിച്ചുകഴിഞ്ഞു.","p":1},{"v":25,"t":"ഇപ്പോൾ സംതൃപ്തരായി കഴിയുന്നവരേ, നിങ്ങൾക്കു ദുരിതം! എന്തെന്നാൽ നിങ്ങൾക്കു വിശക്കും. ഇപ്പോൾ ചിരിക്കുന്നവരേ, നിങ്ങൾക്കു ദുരിതം! എന്തെന്നാൽ നിങ്ങൾ വിലപിക്കുകയും കരയുകയും ചെയ്യും."},{"v":26,"t":"മനുഷ്യരെല്ലാം നിങ്ങളെ പ്രശംസിച്ചു പറയുമ്പോൾ നിങ്ങൾക്കു ദുരിതം! എന്തെന്നാൽ അവരുടെ പിതാക്കന്മാർ വ്യാജപ്രവാചകന്മാരോടും അങ്ങനെതന്നെ ചെയ്തു."},{"h":"ശത്രുക്കളെ സ്നേഹിക്കുവിൻ"},{"v":27,"t":"ശ്രവിച്ചുകൊണ്ടിരിക്കുന്ന നിങ്ങളോടു ഞാൻ പറയുന്നു: നിങ്ങളുടെ ശത്രുക്കളെ സ്നേഹിക്കുവിൻ; നിങ്ങളെ ദ്വേഷിക്കുന്നവർക്കു നന്മ ചെയ്യുവിൻ.","p":1},{"v":28,"t":"നിങ്ങളെ ശപിക്കുന്നവരെ അനുഗ്രഹിക്കുവിൻ. നിങ്ങളെ അധിക്ഷേപിക്കുന്നവർക്കുവേണ്ടി പ്രാർഥിക്കുവിൻ."},{"v":29,"t":"ഒരു ചെകിട്ടത്ത് അടിക്കുന്നവന് മറ്റേ ചെകിടുകൂടി കാണിച്ചു കൊടുക്കുക. നിന്റെ മേലങ്കി എടുക്കുന്നവന് കുപ്പായവും നിഷേധിക്കരുത്."},{"v":30,"t":"നിന്നോടു ചോദിക്കുന്ന ആർക്കും കൊടുക്കുക. നിന്റെ വകകൾ എടുത്തുകൊണ്ടുപോകുന്നവനിൽനിന്ന് തിരികെ ചോദിക്കരുത്."},{"v":31,"t":"മറ്റുള്ളവർ നിങ്ങളോട് എങ്ങനെ പെരുമാറണമെന്നു നിങ്ങൾ ആഗ്രഹിക്കുന്നുവോ, അങ്ങനെതന്നെ നിങ്ങൾ അവരോടും പെരുമാറുവിൻ."},{"v":32,"t":"നിങ്ങളെ സ്നേഹിക്കുന്നവരെ നിങ്ങൾ സ്നേഹിക്കുന്നതിൽ എന്തു മേന്മയാണുള്ളത്? പാപികളും തങ്ങളെ സ്നേഹിക്കുന്നവരെ സ്നേഹിക്കുന്നുണ്ടല്ലോ."},{"v":33,"t":"നിങ്ങൾക്കു നന്മചെയ്യുന്നവർക്ക് നിങ്ങൾ നന്മചെയ്യുന്നതിൽ എന്തു മേന്മയാണുള്ളത്? പാപികളും അതുതന്നെ ചെയ്യുന്നുണ്ടല്ലോ."},{"v":34,"t":"തിരിച്ചു കിട്ടുമെന്നു പ്രതീക്ഷിച്ച് വായ്പകൊടുക്കുന്നതിൽ എന്തു മേന്മയാണുള്ളത്? അത്രത്തോളം തിരിച്ചു കിട്ടുമെന്ന പ്രതീക്ഷയിൽ പാപികളും പാപികൾക്കു വായ്പകൊടുക്കുന്നില്ലേ?"},{"v":35,"t":"എന്നാൽ, നിങ്ങൾ ശത്രുക്കളെ സ്നേഹിക്കുവിൻ. തിരിച്ചുകിട്ടും എന്നു പ്രതീക്ഷിക്കാതെ മറ്റുള്ളവർക്കു നന്മചെയ്യുകയും വായ്പ കൊടുക്കുകയും ചെയ്യുവിൻ. അപ്പോൾ നിങ്ങളുടെ പ്രതിഫലം വലുതായിരിക്കും; നിങ്ങൾ അത്യുന്നതന്റെ പുത്രരായിരിക്കുകയും ചെയ്യും. എന്തെന്നാൽ, അവിടന്ന് നന്ദിഹീനരോടും ദുഷ്ടരോടും കരുണയുള്ളവനാണ്."},{"v":36,"t":"നിങ്ങളുടെ പിതാവ് അനുകമ്പയുള്ളവനായിരിക്കുന്നതുപോലെ നിങ്ങളും അനുകമ്പയുള്ളവരായിരിക്കുവിൻ."},{"h":"അന്യരെ വിധിക്കരുത്"},{"v":37,"t":"വിധിക്കരുത്; നിങ്ങളും വിധിക്കപ്പെടുകയില്ല. കുറ്റാരോപണം നടത്തരുത്; നിങ്ങളുടെമേലും കുറ്റം ആരോപിക്കപ്പെടുകയില്ല. ക്ഷമിക്കുവിൻ; നിങ്ങളോടും ക്ഷമിക്കപ്പെടും.","p":1},{"v":38,"t":"കൊടുക്കുവിൻ; നിങ്ങൾക്കും കിട്ടും. അമർത്തിക്കുലുക്കി നിറഞ്ഞുകവിയുന്ന നല്ല അളവിൽ അവർ നിങ്ങളുടെ മടിയിൽ ഇട്ടുതരും. കാരണം, നിങ്ങൾ അളക്കുന്ന അളവുകൊണ്ടുതന്നെ നിങ്ങൾക്കും തിരിച്ചളന്നുകിട്ടും."},{"v":39,"t":"അവൻ ഒരു ഉപമയും അവരോടു പറഞ്ഞു: കുരുടന് കുരുടനെ നയിക്കാൻ സാധിക്കില്ലല്ലോ. ഇരുവരും കുഴിയിൽ വീഴുകയില്ലേ?"},{"v":40,"t":"ശിഷ്യൻ ഗുരുവിനെക്കാൾ മേലേയല്ല. എന്നാൽ, അഭ്യസനം പൂർത്തിയാകുമ്പോൾ ഓരോരുത്തനും ഗുരുവിനെപ്പോലെ ആകും."},{"v":41,"t":"നിന്റെ സഹോദരന്റെ കണ്ണിലെ കരടു നീ കാണുകയും സ്വന്തം കണ്ണിലെ തടിക്കഷണം ഗൗനിക്കാതിരിക്കുകയും ചെയ്യുന്നതെന്ത്?"},{"v":42,"t":"സ്വന്തം കണ്ണിലെ തടിക്കഷണം കാണാതിരിക്കേ, സഹോദരാ, നിന്റെ കണ്ണിലെ കരട് ഞാൻ എടുത്തുകളയട്ടേ എന്നു നിന്റെ സഹോദരനോടു പറയാൻ നിനക്ക് എങ്ങനെ കഴിയും? കപടനാട്യക്കാരാ, ആദ്യം നിന്റെ കണ്ണിലെ തടിക്കഷണം എടുത്തു മാറ്റുക. അപ്പോൾ നിന്റെ സഹോദരന്റെ കണ്ണിലെ കരട് എടുത്തുകളയാൻ നിന്റെ കാഴ്ച തെളിയും."},{"h":"ഫലത്തിൽനിന്ന് വൃക്ഷത്തെഅറിയുക"},{"v":43,"t":"നല്ല വൃക്ഷം ചീത്ത ഫലങ്ങൾ കായ്ക്കുന്നില്ല. നല്ല ഫലം കായ്ക്കുന്ന ചീത്ത വൃക്ഷങ്ങളുമില്ല.","p":1},{"v":44,"t":"ഓരോ വൃക്ഷവും അതതിന്റെ ഫലംകൊണ്ട് അറിയുന്നു. മുൾച്ചെടിയിൽനിന്ന് അത്തിപ്പഴം ശേഖരിക്കുന്നില്ല; ഞെരിഞ്ഞിലിൽനിന്നു മുന്തിരിക്കുല പറിക്കുന്നുമില്ല."},{"v":45,"t":"നല്ല മനുഷ്യൻ തന്റെ ഹൃദയത്തിലെ നല്ല ശേഖരത്തിൽനിന്ന് നന്മ പുറപ്പെടുവിക്കുന്നു. ദുഷ്ടനാകട്ടെ, തിന്മയിൽനിന്ന് തിന്മ പുറപ്പെടുവിക്കുന്നു. കാരണം, ഹൃദയത്തിന്റെ നിറവിൽ നിന്നാണല്ലോ അധരം സംസാരിക്കുന്നത്."},{"h":"ഉറച്ച അടിസ്ഥാനം"},{"v":46,"t":"നിങ്ങൾ എന്നെ കർത്താവേ, കർത്താവേ എന്നു വിളിക്കുകയും ഞാൻ പറയുന്നവ പ്രവർത്തിക്കാതിരിക്കുകയും ചെയ്യുന്നത് എന്തുകൊണ്ട്?","p":1},{"v":47,"t":"എന്റെ അടുത്തു വരുകയും എന്റെ വചനങ്ങൾ കേൾക്കുകയും അവയനുസരിക്കുകയും ചെയ്യുന്നവൻ ആർക്കു സദൃശനാണെന്ന് ഞാൻ നിങ്ങൾക്കു വ്യക്തമാക്കാം."},{"v":48,"t":"ആഴത്തിൽ കുഴിച്ച് പാറമേൽ അടിസ്ഥാനമിട്ട് ഭവനം പണിത മനുഷ്യനോടു സദൃശനാണ് അവൻ. വെള്ളപ്പൊക്കമുണ്ടാകുകയും ജലപ്രവാഹം ആ ഭവനത്തിന്മേൽ ആഞ്ഞടിക്കുകയും ചെയ്തു. എന്നാൽ അത് ഇളക്കാൻ കഴിഞ്ഞില്ല; എന്തെന്നാൽ, അതു നല്ലവണ്ണം പണിയപ്പെട്ടിരുന്നു."},{"v":49,"t":"എന്നാൽ കേട്ടിട്ടും അതനുസരിക്കാത്ത മനുഷ്യൻ അടിസ്ഥാനമില്ലാത്ത മണ്ണിൽ ഭവനം പണിതവനു തുല്യൻ. ജലപ്രവാഹം അതിന്മേൽ ആഞ്ഞടിച്ചു. ഉടനെ അതു നിലംപൊത്തി. ആ ഭവനത്തിന്റെ തകർച്ച വലുതായിരുന്നു."}],"7":[{"h":"ശതാധിപന്റെ ഭൃത്യനെ സുഖപ്പെടുത്തുന്നു"},{"v":1,"t":"യേശു ജനം കേൾക്കെയുള്ള തന്റെ വാക്കുകളെല്ലാം പൂർത്തിയാക്കിയപ്പോൾ കഫർണാമിലേക്കു പ്രവേശിച്ചു.","p":1},{"v":2,"t":"ഒരു ശതാധിപന്റെ ഭൃത്യൻ രോഗം ബാധിച്ച് ആസന്നമരണനായിക്കിടന്നിരുന്നു. അവൻ യജമാനനു പ്രിയങ്കരനായിരുന്നു."},{"v":3,"t":"ശതാധിപൻ യേശുവിനെപ്പറ്റി കേട്ട്, തന്റെ ഭൃത്യനെ വന്നുസുഖപ്പെടുത്തണമെന്ന് അപേക്ഷിക്കാൻ യഹൂദശ്രേഷ്ഠന്മാരെ അവന്റെ അടുത്തേക്കയച്ചു."},{"v":4,"t":"അവർ യേശുവിന്റെ അടുത്തുവന്ന് താത്പര്യപൂർവം യാചിച്ചു: നീ ഇതു ചെയ്തുകൊടുക്കാൻ അവൻ അർഹനാണ്."},{"v":5,"t":"എന്തെന്നാൽ, അവൻ നമ്മുടെ ജനത്തെ സ്നേഹിക്കുന്നു. നമുക്ക് ഒരു സിനഗോഗു പണിയിച്ചുതരുകയും ചെയ്തിട്ടുണ്ട്."},{"v":6,"t":"യേശു അവരോടൊപ്പം പുറപ്പെട്ടു. ഭവനത്തിൽനിന്ന് അവൻ അധികം അകലെയല്ലാതിരുന്നപ്പോൾ ആ ശതാധിപൻ തന്റെ സ്നേഹിതരെ അയച്ച് അവനോടു പറഞ്ഞു: കർത്താവേ, അങ്ങ് ബുദ്ധിമുട്ടേണ്ടാ. അങ്ങ് എന്റെ വീട്ടിൽ പ്രവേശിക്കാൻ ഞാൻ യോഗ്യനല്ല."},{"v":7,"t":"അതിനാൽ, അങ്ങയുടെ അടുത്ത് നേരിട്ടുവരാൻ എനിക്കു യോഗ്യതയില്ല എന്നു ഞാൻ വിചാരിച്ചു. അങ്ങ് ഒരു വാക്ക് ഉച്ചരിക്കുക, എന്റെ ഭൃത്യൻ സുഖപ്പെടട്ടെ."},{"v":8,"t":"കാരണം, ഞാനും അധികാരത്തിനു കീഴ്പ്പെട്ടവനാണ്; എന്റെ കീഴിലും പടയാളികളുണ്ട്. ഞാൻ ഒരുവനോടു പറയുന്നു, പോകുക; അവൻ പോകുന്നു. വേറൊരുവനോട്, വരുക; അവൻ വരുന്നു. എന്റെ ദാസനോട്, ഇതു ചെയ്യുക; അവൻ ചെയ്യുന്നു."},{"v":9,"t":"യേശു ഇതു കേട്ട് അവനെപ്പറ്റി വിസ്മയിച്ചു. തന്നെ അനുഗമിച്ചിരുന്ന ജനക്കൂട്ടത്തിനുനേരേ തിരിഞ്ഞ് അവൻ പറഞ്ഞു: ഞാൻ നിങ്ങളോടു പറയുന്നു; ഇസ്രായേലിൽപ്പോലും ഇത്ര വലിയ വിശ്വാസം ഞാൻ കണ്ടിട്ടില്ല."},{"v":10,"t":"അയയ്ക്കപ്പെട്ടവർ തിരിച്ചുചെന്നപ്പോൾ ആ ഭൃത്യൻ ആരോഗ്യവാനായിരിക്കുന്നതു കണ്ടു."},{"h":"വിധവയുടെ മകനെ പുനർജീവിപ്പിക്കുന്നു"},{"v":11,"t":"അതിനുശേഷം അവൻ നായിൻ എന്ന പട്ടണത്തിലേക്കു പോയി. ശിഷ്യന്മാരും വലിയ ഒരു ജനക്കൂട്ടവും അവനെ അനുയാത്ര ചെയ്തു.","p":1},{"v":12,"t":"അവൻ നഗരകവാടത്തിന് അടുത്തെത്തിയപ്പോൾ, മരിച്ചുപോയ ഒരുവനെ ചിലർ എടുത്തുകൊണ്ടുവരുന്നതു കണ്ടു. അവൻ അമ്മയുടെ ഏകപുത്രനായിരുന്നു; അവൾ വിധവയും. പട്ടണത്തിൽനിന്ന് വലിയ ഒരു ജനക്കൂട്ടവും അവളോടൊപ്പം ഉണ്ടായിരുന്നു."},{"v":13,"t":"അവളെക്കണ്ട് അനുകമ്പ തോന്നി കർത്താവ് അവളോടു പറഞ്ഞു: കരയേണ്ടാ."},{"v":14,"t":"അവൻ മുന്നോട്ടു വന്ന് ശവമഞ്ചത്തിന്മേൽ തൊട്ടു. അതു വഹിച്ചിരുന്നവർ നിന്നു. അവൻ പറഞ്ഞു: യുവാവേ, ഞാൻ നിന്നോടു പറയുന്നു, എഴുന്നേല്ക്കുക."},{"v":15,"t":"മരിച്ചവൻ ഉടനെ എഴുന്നേറ്റിരിക്കുകയും സംസാരിക്കാൻ തുടങ്ങുകയും ചെയ്തു. യേശു അവനെ അമ്മയ്ക്ക് ഏല്പിച്ചുകൊടുത്തു."},{"v":16,"t":"ഭയം എല്ലാവരെയും ഗ്രസിച്ചു. അവർ ദൈവത്തെ മഹത്ത്വപ്പെടുത്തിക്കൊണ്ടു പറഞ്ഞു: ഒരു വലിയപ്രവാചകൻ നമ്മുടെയിടയിൽ ഉയർന്നിരിക്കുന്നു. ദൈവം തന്റെ ജനത്തെ സന്ദർശിച്ചിരിക്കുന്നു."},{"v":17,"t":"അവനെപ്പറ്റിയുള്ള ഈ വാർത്ത യൂദയാ മുഴുവനിലും സമീപപ്രദേശങ്ങളിലും പരന്നു."},{"h":"സ്നാപകന്റെ ശിഷ്യന്മാർ യേശുവിനെ സമീപിക്കുന്നു"},{"v":18,"t":"ഇവയെപ്പറ്റിയെല്ലാം യോഹന്നാന്റെ ശിഷ്യന്മാർ അവനെ അറിയിച്ചു. യോഹന്നാൻ തന്റെ ശിഷ്യന്മാരിൽ രണ്ടുപേരെ വിളിച്ച്,","p":1},{"v":19,"t":"ഇങ്ങനെ ചോദിക്കാൻ കർത്താവിന്റെ അടുക്കൽ പറഞ്ഞയച്ചു: വരാനിരിക്കുന്നവൻ നീ തന്നെയോ, അതോ ഞങ്ങൾ മറ്റൊരുവനെ പ്രതീക്ഷിക്കണമോ?"},{"v":20,"t":"അവർ അവന്റെ അടുത്തു ചെന്നു പറഞ്ഞു: വരാനിരിക്കുന്നവൻ നീ തന്നെയോ അതോ ഞങ്ങൾ മറ്റൊരുവനെ പ്രതീക്ഷിക്കണമോ എന്നു ചോദിക്കാൻ സ്നാപകയോഹന്നാൻ ഞങ്ങളെ നിന്റെ അടുത്തേക്ക് അയച്ചിരിക്കുന്നു."},{"v":21,"t":"ആ സമയം യേശു അനേകംപേരെ രോഗങ്ങളിൽനിന്നും പീഡകളിൽനിന്നും അശുദ്ധാത്മാക്കളിൽനിന്നും സുഖപ്പെടുത്തുകയും അനേകം കുരുടന്മാർക്ക് കാഴ്ച കൊടുക്കുകയും ചെയ്തു."},{"v":22,"t":"അവൻ അവരോട് മറുപടി പറഞ്ഞു: നിങ്ങൾ കാണുകയും കേൾക്കുകയും ചെയ്തതെല്ലാം ചെന്ന് യോഹന്നാനെ അറിയിക്കുക. കുരുടന്മാർ കാണുന്നു; മുടന്തന്മാർ നടക്കുന്നു; കുഷ്ഠരോഗികൾ സുഖപ്പെടുന്നു; ചെകിടർ കേൾക്കുന്നു; മരിച്ചവർ ഉയിർപ്പിക്കപ്പെടുന്നു; ദരിദ്രരോടു സദ്വാർത്ത അറിയിക്കപ്പെടുന്നു."},{"v":23,"t":"എന്നിൽ ഇടർച്ചയുണ്ടാകാത്തവൻ അനുഗൃഹീതൻ."},{"h":"യോഹന്നാനെക്കുറിച്ച് യേശുവിന്റെ സാക്ഷ്യം"},{"v":24,"t":"യോഹന്നാന്റെ ദൂതന്മാർ പോയപ്പോൾ യേശു അവനെപ്പറ്റി ജനക്കൂട്ടത്തോടു പറയാൻ തുടങ്ങി: എന്തു കാണാനാണ് നിങ്ങൾ മരുഭൂമിയിലേക്കു പോയത്? കാറ്റിൽ ഉലയുന്ന ഞാങ്ങണയോ?","p":1},{"v":25,"t":"അല്ലെങ്കിൽ, എന്തു കാണാനാണ് നിങ്ങൾ പോയത്? മൃദുലവസ്ത്രങ്ങൾ ധരിച്ച മനുഷ്യനെയോ? മോടിയായി വസ്ത്രം ധരിച്ച് ആഡംബരത്തിൽ ജീവിക്കുന്നവർ രാജകൊട്ടാരങ്ങളിലാണല്ലോ."},{"v":26,"t":"അല്ലെങ്കിൽ, എന്തു കാണാനാണു നിങ്ങൾ പോയത്? പ്രവാചകനെയോ? അതേ, ഞാൻ നിങ്ങളോടു പറയുന്നു: പ്രവാചകനെക്കാൾ വലിയവനെ."},{"v":27,"t":"ഇവനെപ്പറ്റിയാണ് ഇങ്ങനെ എഴുതിയിരിക്കുന്നത്: ഇതാ, നിനക്കുമുമ്പേ എന്റെ ദൂതനെ ഞാനയയ്ക്കുന്നു. അവൻ നിന്റെ മുമ്പിൽ നിനക്കു വഴിയൊരുക്കും."},{"v":28,"t":"ഞാൻ നിങ്ങളോടു പറയുന്നു: സ്ത്രീകളിൽനിന്നു ജനിച്ചവരിൽ യോഹന്നാനെക്കാൾ വലിയവൻ ആരുമില്ല. എങ്കിലും ദൈവരാജ്യത്തിലെ ഏറ്റവും ചെറിയവൻ അവനെക്കാൾ വലിയവനാണ്."},{"v":29,"t":"ഇതു കേട്ട്, ജനം മുഴുവനും ചുങ്കക്കാരും യോഹന്നാന്റെ സ്നാനം സ്വീകരിച്ച് ദൈവത്തിന്റെ നീതി അംഗീകരിച്ചു."},{"v":30,"t":"ഫരിസേയരും നിയമജ്ഞരുമാകട്ടെ, യോഹന്നാന്റെ സ്നാനം സ്വീകരിക്കാതെ തങ്ങളെപ്പറ്റിയുള്ള ദൈവത്തിന്റെ പദ്ധതി നിരസിച്ചുകളഞ്ഞു."},{"v":31,"t":"ഈ തലമുറയുടെ മനുഷ്യരെ എന്തിനോടാണ് ഞാൻ ഉപമിക്കേണ്ടത്? അവർ എന്തിനോടു തുല്യരാണ്?"},{"v":32,"t":"അവർ ചന്തസ്ഥലത്തിരുന്ന് പരസ്പരം വിളിച്ചു പറയുന്ന കുട്ടികളെപ്പോലെയാണ്: ഞങ്ങൾ നിങ്ങൾക്കുവേണ്ടി കുഴലൂതി; എങ്കിലും നിങ്ങൾ നൃത്തം ചെയ്തില്ല; ഞങ്ങൾ നിങ്ങൾക്കുവേണ്ടി വിലാപഗാനമാലപിച്ചു; എങ്കിലും നിങ്ങൾ കരഞ്ഞില്ല."},{"v":33,"t":"എന്തെന്നാൽ, സ്നാപകയോഹന്നാൻ അപ്പം ഭക്ഷിക്കാത്തവനും വീഞ്ഞു കുടിക്കാത്തവനുമായി വന്നു. അവൻ പിശാചുബാധിതനാണ് എന്നു നിങ്ങൾ പറയുന്നു."},{"v":34,"t":"മനുഷ്യപുത്രൻ ഭക്ഷിക്കുന്നവനും പാനംചെയ്യുന്നവനുമായി വന്നു. അപ്പോൾ ഇതാ, ഭോജനപ്രിയനും വീഞ്ഞുകുടിയനും ചുങ്കക്കാരുടെയും പാപികളുടെയും സ്നേഹിതനുമായ മനുഷ്യൻ എന്നു നിങ്ങൾ പറയുന്നു."},{"v":35,"t":"ജ്ഞാനം തന്റെ സകല സന്താനങ്ങളാലും നീതിമത്കരിക്കപ്പെടുന്നു."},{"h":"പാപിനിക്കു മോചനം"},{"v":36,"t":"ഫരിസേയരിൽ ഒരുവൻ തന്നോടൊത്തു ഭക്ഷണം കഴിക്കാൻ അവനെ ക്ഷണിച്ചു. യേശു അവന്റെ വീട്ടിൽ പ്രവേശിച്ച് ഭക്ഷണത്തിനിരുന്നു.","p":1},{"v":37,"t":"അപ്പോൾ, ആ പട്ടണത്തിലെ പാപിനിയായ ഒരു സ്ത്രീ ഫരിസേയന്റെ വീട്ടിൽ, അവൻ ഭക്ഷണത്തിനിരിക്കുന്നു എന്നറിഞ്ഞ്, ഒരു വെൺകല്ഭരണി നിറയെ സുഗന്ധതൈലം കൊണ്ടുവന്ന്,"},{"v":38,"t":"അവന്റെ പിന്നിൽ പാദത്തിനരികേ കരഞ്ഞുകൊണ്ടു നിന്നു. കണ്ണീരുകൊണ്ട് അവൾ അവന്റെ പാദങ്ങൾ നനയ്ക്കുകയും തലമുടികൊണ്ടു തുടയ്ക്കുകയും ചുംബിക്കുകയും സുഗന്ധതൈലം പൂശുകയും ചെയ്തു തുടങ്ങി."},{"v":39,"t":"ഇതുകണ്ട്, അവനെ ക്ഷണിച്ച ആ ഫരിസേയൻ ആത്മഗതം ചെയ്തു: ഇവൻ പ്രവാചകനാണെങ്കിൽ തന്നെ സ്പർശിക്കുന്ന സ്ത്രീ ആരെന്നും ഏതു തരക്കാരി എന്നും അറിയുമായിരുന്നു. എന്തെന്നാൽ, ഇവൾ ഒരു പാപിനിയാണല്ലോ."},{"v":40,"t":"യേശു അവനോടു പറഞ്ഞു: ശിമയോനേ, എനിക്കു നിന്നോട് ഒരു കാര്യം പറയാനുണ്ട്. ഗുരോ, അരുൾചെയ്താലും എന്ന് അവൻ പറഞ്ഞു."},{"v":41,"t":"ഒരു ഉത്തമർണന് രണ്ടു കടക്കാർ ഉണ്ടായിരുന്നു. ഒരുവൻ അഞ്ഞൂറു ദനാറ കടപ്പെട്ടിരുന്നു; മറ്റവൻ അമ്പതും."},{"v":42,"t":"വീട്ടാൻ വകയില്ലാത്തതുകൊണ്ട് ഇരുവർക്കും അവൻ ഇളച്ചുകൊടുത്തു. അങ്ങനെയെങ്കിൽ അവരിൽ ആര് അവനെ കൂടുതൽ സ്നേഹിക്കും?"},{"v":43,"t":"ശിമയോൻ മറുപടി പറഞ്ഞു: ആർക്ക് അവൻ കൂടുതൽ ഇളവുചെയ്തോ അവൻ എന്നു ഞാൻ വിചാരിക്കുന്നു. അവൻ പറഞ്ഞു: നീ ശരിയായിത്തന്നെ വിധിച്ചു."},{"v":44,"t":"അനന്തരം യേശു ആ സ്ത്രീയുടെ നേരേ തിരിഞ്ഞ് ശിമയോനോടു പറഞ്ഞു: നീ ഈ സ്ത്രീയെ കാണുന്നല്ലോ. ഞാൻ നിന്റെ വീട്ടിൽ വന്നു; കാലു കഴുകാൻ നീ എനിക്കു വെള്ളം തന്നില്ല. എന്നാൽ ഇവൾ കണ്ണീരുകൊണ്ട് എന്റെ കാൽ നനയ്ക്കുകയും തലമുടികൊണ്ട് തുടയ്ക്കുകയും ചെയ്തു."},{"v":45,"t":"നീ എനിക്കു ചുംബനം തന്നില്ല; എന്നാൽ, ഞാനിവിടെ പ്രവേശിച്ചതുമുതൽ എന്റെ പാദങ്ങൾ ചുംബിക്കുന്നതിൽനിന്ന് ഇവൾ വിരമിച്ചിട്ടില്ല."},{"v":46,"t":"നീ എന്റെ തലയിൽ തൈലം പൂശിയില്ല, ഇവളോ എന്റെ പാദങ്ങളിൽ സുഗന്ധതൈലം പൂശിയിരിക്കുന്നു."},{"v":47,"t":"അതിനാൽ, ഞാൻ നിന്നോടു പറയുന്നു, ഇവളുടെ നിരവധിയായ പാപങ്ങൾ ക്ഷമിക്കപ്പെട്ടിരിക്കുന്നു. എന്തെന്നാൽ, ഇവൾ അധികം സ്നേഹിച്ചു. ആരോട് അല്പം ക്ഷമിക്കപ്പെടുന്നുവോ അയാൾ അല്പം സ്നേഹിക്കുന്നു."},{"v":48,"t":"അവൻ അവളോടു പറഞ്ഞു: നിന്റെ പാപങ്ങൾ ക്ഷമിക്കപ്പെട്ടിരിക്കുന്നു."},{"v":49,"t":"അവനോടുകൂടെ പന്തിയിൽ ഇരുന്നവർ പരസ്പരം പറയാൻ തുടങ്ങി: പാപങ്ങൾ ക്ഷമിക്കുകപോലും ചെയ്യുന്ന ഇവൻ ആരാണ്?"},{"v":50,"t":"അവൻ അവളോടു പറഞ്ഞു: നിന്റെ വിശ്വാസം നിന്നെ രക്ഷിച്ചിരിക്കുന്നു. സമാധാനത്തിൽ പോകുക."}],"8":[{"h":"യേശുവിനെ അനുഗമിച്ച സ്ത്രീകൾ"},{"v":1,"t":"അതിനുശേഷം അവൻ പ്രസംഗിക്കുകയും ദൈവരാജ്യത്തിന്റെ സദ്വാർത്ത അറിയിക്കുകയും ചെയ്തുകൊണ്ട് പട്ടണങ്ങളും ഗ്രാമങ്ങളുംതോറും സഞ്ചരിക്കുകയായിരുന്നു. അവനോടുകൂടെ പന്ത്രണ്ടുപേരും","p":1},{"v":2,"t":"ദുഷ്ടാത്മാക്കളിൽനിന്നും വ്യാധികളിൽനിന്നും സുഖമാക്കപ്പെട്ട ചില സ്ത്രീകളും ഏഴുദുഷ്ടാത്മാക്കൾ വിട്ടുപോയ മഗ്ദലേന എന്നു വിളിക്കപ്പെടുന്ന മറിയവും"},{"v":3,"t":"ഹേറോദേസിന്റെ കാര്യസ്ഥനായ കൂസായുടെ ഭാര്യ യൊവാന്നയും സൂസന്നയും മറ്റു സ്ത്രീകളും ഉണ്ടായിരുന്നു. അവർ തങ്ങളുടെ സ്വത്തുകൊണ്ട് അവരെ ശുശ്രൂഷിച്ചിരുന്നു."},{"h":"വിതക്കാരന്റെ ഉപമ"},{"v":4,"t":"വലിയ ജനക്കൂട്ടവും ഓരോ പട്ടണത്തിൽനിന്നുള്ളവരും തന്റെ അടുത്തു കൂടിയപ്പോൾ അവൻ അവരോട് ഉപമയിലൂടെ അരുൾചെയ്തു:","p":1},{"v":5,"t":"വിതക്കാരൻ തന്റെ വിത്തു വിതയ്ക്കാൻ പുറപ്പെട്ടു. വിതയ്ക്കുമ്പോൾ ചിലതു വഴിയരികിൽ വീണു. അത് ചവിട്ടപ്പെടുകയും ആകാശത്തിലെ പക്ഷികൾ തിന്നുകയും ചെയ്തു."},{"v":6,"t":"ചിലതു പാറമേൽ വീണു. അതു മുളച്ചുപൊങ്ങിയപ്പോൾ, നനവില്ലാതിരുന്നതുകൊണ്ട് ഉണങ്ങിപ്പോയി."},{"v":7,"t":"ചിലതു മുൾച്ചെടികൾക്കിടയിൽ വീണു. മുൾച്ചെടികൾ അതിനോടൊപ്പം വളർന്ന് അതിനെ ഞെരുക്കിക്കളഞ്ഞു."},{"v":8,"t":"ചിലതു നല്ല നിലത്തു വീണു. അതു വളർന്ന് നൂറുമേനി ഫലം പുറപ്പെടുവിച്ചു. ഇതു പറഞ്ഞുകൊണ്ട് അവൻ സ്വരമുയർത്തിപ്പറഞ്ഞു: കേൾക്കാൻ ചെവിയുള്ളവൻ കേൾക്കട്ടെ."},{"h":"ഉപമയുടെ വിശദീകരണം"},{"v":9,"t":"ഈ ഉപമയുടെ അർഥമെന്തെന്ന് അവന്റെ ശിഷ്യന്മാർ അവനോടു ചോദിച്ചു.","p":1},{"v":10,"t":"അവൻ പറഞ്ഞു: ദൈവരാജ്യത്തിന്റെ രഹസ്യങ്ങൾ അറിയാൻ നിങ്ങൾക്കു വരം നല്കപ്പെട്ടിരിക്കുന്നു. മറ്റുള്ളവർക്കാകട്ടെ, ഉപമകളിലൂടെയും. അവർ കണ്ടിട്ടും കാണാതിരിക്കാനും കേട്ടിട്ടും ഗ്രഹിക്കാതിരിക്കാനും വേണ്ടിയാണത്."},{"v":11,"t":"ഉപമ ഇതാണ്: വിത്ത് ദൈവത്തിന്റെ വചനമാണ്."},{"v":12,"t":"ചിലർ വചനം ശ്രവിച്ചെങ്കിലും, അവർ വിശ്വസിക്കുകയോ രക്ഷപ്പെടുകയോ ചെയ്യാതിരിക്കാൻവേണ്ടി, പിശാചു വന്ന് അവരുടെ ഹൃദയങ്ങളിൽനിന്ന് ആ വചനം എടുത്തുകളയുന്നു. ഇവരാണ് വഴിയരികിൽവീണ വിത്ത്."},{"v":13,"t":"പാറയിൽ വീണതാകട്ടെ, കേൾക്കുമ്പോൾ ആ വചനം സന്തോഷത്തോടെ സ്വീകരിക്കുന്നവരാണ്. എങ്കിലും അവർക്കു വേരുകളില്ല. അവർ കുറച്ചു സമയത്തേക്കു വിശ്വസിക്കുന്നു. എന്നാൽ, പ്രലോഭനങ്ങളുടെ സമയത്ത് അവർ വീണുപോകുന്നു."},{"v":14,"t":"മുള്ളുകളുടെ ഇടയിൽ വീണത്, കേട്ടിട്ടും, പോകുംവഴി ഉത്കണ്ഠകൾ, സമ്പത്ത്, ജീവിതത്തിന്റെ സുഖഭോഗങ്ങൾ എന്നിവ വചനത്തെ ഞെരുക്കിക്കളയുന്നതുകൊണ്ട് ഫലം പുറപ്പെടുവിക്കാത്തവരുമാണ്."},{"v":15,"t":"നല്ല നിലത്തു വീണതോ, ഉത്കൃഷ്ടവും നല്ലതുമായ ഹൃദയത്തിൽ വചനംകേട്ട് മുറുകെപ്പിടിക്കുകയും ക്ഷമയോടെ ഫലം പുറപ്പെടുവിക്കുകയും ചെയ്യുന്നവരാകുന്നു."},{"h":"ദീപം മറച്ചുവയ്ക്കരുത്"},{"v":16,"t":"ആരും വിളക്കുകൊളുത്തി പാത്രം കൊണ്ടു മൂടുകയോ കട്ടിലിനടിയിൽ വയ്ക്കുകയോ ചെയ്യുന്നില്ല. മറിച്ച്, അകത്തുപ്രവേശിക്കുന്നവർ വെളിച്ചംകാണാൻ അത് ദീപപീഠത്തിന്മേൽ വയ്ക്കുന്നു.","p":1},{"v":17,"t":"വെളിപ്പെടുത്തപ്പെടാതെ മറഞ്ഞിരിക്കുന്ന ഒന്നുമില്ല. അറിയപ്പെടാതെയും വെളിച്ചത്തുവരാതെയും മറഞ്ഞിരിക്കുന്നതും ഒന്നുമില്ല."},{"v":18,"t":"ആകയാൽ, നിങ്ങൾ എപ്രകാരമാണു കേൾക്കുന്നതെന്നു സൂക്ഷിച്ചുകൊള്ളുവിൻ. എന്തെന്നാൽ, ഉള്ളവന് നല്കപ്പെടും; ഇല്ലാത്തവനിൽനിന്ന് ഉണ്ടെന്ന് അവൻ വിചാരിക്കുന്നതുകൂടിയും എടുക്കപ്പെടും."},{"h":"യേശുവിന്റെ അമ്മയും സഹോദരരും"},{"v":19,"t":"പിന്നീട്, അവന്റെ അമ്മയും സഹോദരരും അവന്റെ അടുത്തുവന്നു. എന്നാൽ, ജനക്കൂട്ടം നിമിത്തം അവനുമായി കണ്ടുമുട്ടാൻ കഴിഞ്ഞില്ല.","p":1},{"v":20,"t":"നിന്റെ അമ്മയും നിന്റെ സഹോദരരും നിന്നെ കാണാൻ ആഗ്രഹിച്ചു പുറത്തുനില്ക്കുന്നു എന്ന് അവർ അറിയിച്ചു."},{"v":21,"t":"അവൻ അവരോടു മറുപടി പറഞ്ഞു: ദൈവത്തിന്റെ വചനം ശ്രവിക്കുകയും നിറവേറ്റുകയും ചെയ്യുന്നവരാണ് എന്റെ അമ്മയും എന്റെ സഹോദരരും."},{"h":"കൊടുങ്കാറ്റു ശാന്തമാക്കുന്നു"},{"v":22,"t":"ഒരു ദിവസം യേശുവും അവന്റെ ശിഷ്യന്മാരും വഞ്ചിയിൽ കയറി. അവൻ അവരോടു പറഞ്ഞു: നമുക്ക് തടാകത്തിന്റെ മറുകരയ്ക്കു പോകാം. അവർ പുറപ്പെട്ടു.","p":1},{"v":23,"t":"അവർ തുഴഞ്ഞുകൊണ്ടിരുന്നപ്പോൾ അവൻ ഉറങ്ങി. അപ്പോൾ തടാകത്തിൽ കൊടുങ്കാറ്റുണ്ടായി; മുങ്ങിത്തുടങ്ങിയ അവർ അപകടത്തിലായി."},{"v":24,"t":"അവർ അടുത്തുവന്ന് ഗുരോ, ഗുരോ, ഞങ്ങൾ നശിക്കുന്നു എന്നുപറഞ്ഞ് അവനെ ഉണർത്തി. അവൻ എഴുന്നേറ്റ് കാറ്റിനെയും തിരകളെയും ശാസിച്ചു. അവ നിലച്ചു, ശാന്തതയുണ്ടായി."},{"v":25,"t":"അവൻ അവരോടു ചോദിച്ചു: നിങ്ങളുടെ വിശ്വാസം എവിടെ? അവർ ഭയന്ന് അദ്ഭുതത്തോടെ അന്യോന്യം പറഞ്ഞു: ഇവൻ ആരാണ്? കാറ്റിനോടും വെള്ളത്തോടും കല്പിക്കുകയും അവ അവനെ അനുസരിക്കുകയും ചെയ്യുന്നല്ലോ."},{"h":"പിശാചുബാധിതനെ സുഖപ്പെടുത്തുന്നു"},{"v":26,"t":"അതിനുശേഷം അവർ വഞ്ചിയിൽ ഗലീലിക്ക് എതിരേയുള്ള ഗരസേനരുടെ നാട്ടിലെത്തി.","p":1},{"v":27,"t":"അവൻ കരയ്ക്കിറങ്ങിയപ്പോൾ ആ പട്ടണത്തിൽനിന്ന് പിശാചുബാധയുള്ള ഒരുവൻ അവനെ സമീപിച്ചു. വളരെക്കാലമായി അവൻ വസ്ത്രം ധരിക്കാറില്ലായിരുന്നു. വീട്ടിലല്ല, കല്ലറകളിലാണ് അവൻ വസിച്ചിരുന്നത്."},{"v":28,"t":"യേശുവിനെ കണ്ടപ്പോൾ അവൻ നിലവിളിച്ചുകൊണ്ട് അവന്റെ മുമ്പിൽ വീഴുകയും വലിയ സ്വരത്തിൽ പറയുകയും ചെയ്തു: യേശുവേ, അത്യുന്നതനായ ദൈവത്തിന്റെ പുത്രാ, എനിക്കും നിനക്കുമെന്ത്? ഞാൻ നിന്നോടപേക്ഷിക്കുന്നു; എന്നെ പീഡിപ്പിക്കരുത്."},{"v":29,"t":"കാരണം, ആ മനുഷ്യനിൽനിന്നു പുറത്തുപോകാൻ അശുദ്ധാത്മാവിനോട് യേശു കല്പിച്ചിരുന്നു. പലപ്പോഴും അത് അവനെ പിടികൂടിയിരുന്നു. ചങ്ങലകളും കാല്വിലങ്ങുകളുംകൊണ്ട് ബന്ധിച്ചു സൂക്ഷിച്ചിരുന്നിട്ടും അവൻ അതെല്ലാം തകർക്കുകയും അശുദ്ധാത്മാവ് വിജനപ്രദേശങ്ങളിലേക്ക് അവനെ കൊണ്ടുപോകുകയും ചെയ്യുമായിരുന്നു."},{"v":30,"t":"യേശു അവനോടു ചോദിച്ചു: നിന്റെ പേരെന്ത്? അവൻ പറഞ്ഞു: ലെഗിയോൻ. എന്തെന്നാൽ, അനേകം പിശാചുക്കൾ അവനെ ആവേശിച്ചിരുന്നു."},{"v":31,"t":"പാതാളത്തിലേക്കു പോകാൻ തങ്ങളോടു കല്പിക്കരുതെന്ന് അവ അവനോടു യാചിച്ചു."},{"v":32,"t":"വലിയ ഒരു പന്നിക്കൂട്ടം കുന്നിൻപുറത്ത് തീറ്റതിന്നുന്നുണ്ടായിരുന്നു. ആ പന്നികളെ ആവേശിക്കാൻ തങ്ങളെ അനുവദിക്കണമെന്ന് പിശാചുക്കൾ അപേക്ഷിച്ചു. അവൻ അവയെ അനുവദിച്ചു."},{"v":33,"t":"അപ്പോൾ അവ ആ മനുഷ്യനെവിട്ട് പന്നികളിൽ പ്രവേശിച്ചു. പന്നിക്കൂട്ടം കീഴ്ക്കാംതൂക്കായ ചരിവിലൂടെ തടാകത്തിലേക്കു പാഞ്ഞു മുങ്ങിച്ചത്തു."},{"v":34,"t":"പന്നികളെ തീറ്റുന്നവർ, സംഭവിച്ചതു കണ്ട് ഓടിച്ചെന്ന് പട്ടണത്തിലും ഗ്രാമപ്രദേശങ്ങളിലും വിവരമറിയിച്ചു."},{"v":35,"t":"സംഭവിച്ചതെന്തെന്നു കാണാൻ ആളുകൾ പുറപ്പെട്ട് യേശുവിന്റെ അടുത്തു വന്നു. പിശാചുബാധയിൽനിന്നു വിമോചിതനായ ആ മനുഷ്യൻ വസ്ത്രംധരിച്ച് സുബോധത്തോടെ യേശുവിന്റെ കാല്ക്കൽ ഇരിക്കുന്നതു കണ്ടു; അവർ ഭയപ്പെട്ടു."},{"v":36,"t":"പിശാചുബാധിതൻ എങ്ങനെ സുഖപ്പെട്ടു എന്ന് അതു കണ്ടവർ അവരെ അറിയിച്ചു."},{"v":37,"t":"തങ്ങളെ വിട്ടുപോകണമെന്ന് ഗരസേനരുടെ സമീപപ്രദേശങ്ങളിലെ ജനങ്ങളെല്ലാം അവനോട് അപേക്ഷിച്ചു. എന്തെന്നാൽ, വലിയ ഭയം അവരെ ഗ്രസിച്ചിരുന്നു."},{"v":38,"t":"പിശാചുബാധയൊഴിഞ്ഞ ആ മനുഷ്യൻ അവന്റെ കൂടെയായിരിക്കാൻ യാചിച്ചു. യേശുവാകട്ടെ, അവനെ പറഞ്ഞയച്ചുകൊണ്ട് ആവശ്യപ്പെട്ടു:"},{"v":39,"t":"നീ വീട്ടിലേക്കു തിരിച്ചു പോകുക; ദൈവം നിനക്കു ചെയ്തതൊക്കെയും വിവരിക്കുക. യേശു തനിക്കുവേണ്ടി ചെയ്തവയെല്ലാം പട്ടണം മുഴുവൻ പ്രഘോഷിച്ച് അവൻ പോയി."},{"h":"ജായ്റോസിന്റെ മകൾ; രക്തസ്രാവക്കാരി"},{"v":40,"t":"യേശു തിരിച്ചുവന്നപ്പോൾ ജനക്കൂട്ടം അവനെ വരവേറ്റു. എല്ലാവരും അവനെ കാത്തിരിക്കുകയായിരുന്നു.","p":1},{"v":41,"t":"അപ്പോൾ, ജായ്റോസ് എന്നുപേരുള്ള ഒരുവൻ വന്നു. അയാൾ സിനഗോഗിലെ അധികാരി ആയിരുന്നു. അയാൾ യേശുവിന്റെ കാല്ക്കൽ വീണ്, തന്റെ വീട്ടിലേക്കു വരണമെന്ന് അപേക്ഷിച്ചു."},{"v":42,"t":"കാരണം, പന്ത്രണ്ടു വയസ്സോളം പ്രായമുള്ള അവന്റെ ഏകപുത്രി ആസന്നമരണയായിരുന്നു. അവൻ പോകുമ്പോൾ ജനക്കൂട്ടം അവനെ തിക്കിക്കൊണ്ടിരുന്നു."},{"v":43,"t":"പന്ത്രണ്ടു വർഷമായി രക്തസ്രാവമുണ്ടായിരുന്നവളും സമ്പാദ്യം മുഴുവൻ വൈദ്യന്മാർക്കു കൊടുത്തിട്ടും ആർക്കും സുഖപ്പെടുത്താൻ കഴിയാതിരുന്നവളുമായ ഒരു സ്ത്രീ","p":1},{"v":44,"t":"പിന്നിലൂടെവന്ന് അവന്റെ വസ്ത്രത്തിന്റെ വിളുമ്പിൽ സ്പർശിച്ചു. തത്ക്ഷണം അവളുടെ രക്തസ്രാവം നിലച്ചു."},{"v":45,"t":"യേശു ചോദിച്ചു: ആരാണ് എന്നെ സ്പർശിച്ചത്? എല്ലാവരും നിഷേധിച്ചപ്പോൾ പത്രോസ് പറഞ്ഞു: ഗുരോ, ജനക്കൂട്ടം ചുറ്റുംകൂടി നിന്നെ തിക്കുകയാണല്ലോ."},{"v":46,"t":"യേശു പറഞ്ഞു: ആരോ എന്നെ സ്പർശിച്ചു. എന്നിൽനിന്നു ശക്തി പുറപ്പെട്ടിരിക്കുന്നു എന്നു ഞാൻ അറിയുന്നു."},{"v":47,"t":"മറഞ്ഞിരിക്കാൻ സാധിക്കില്ലെന്നു കണ്ടപ്പോൾ അവൾ വിറയലോടെ വന്ന്, അവന്റെ കാല്ക്കൽവീണ്, താൻ അവനെ എന്തിനു സ്പർശിച്ചു എന്നും എങ്ങനെ തത്ക്ഷണം സുഖമാക്കപ്പെട്ടു എന്നും ജനം മുഴുവന്റെയും മുമ്പാകെ അറിയിച്ചു."},{"v":48,"t":"അവൻ അവളോടു പറഞ്ഞു: മകളേ, നിന്റെ വിശ്വാസം നിന്നെ രക്ഷിച്ചിരിക്കുന്നു. സമാധാനത്തിൽ പോകുക."},{"v":49,"t":"അവൻ സംസാരിച്ചുകൊണ്ടിരിക്കുമ്പോൾ സിനഗോഗധികാരിയുടെ വീട്ടിൽനിന്ന് ഒരാൾ വന്നുപറഞ്ഞു: നിന്റെ മകൾ മരിച്ചുപോയി; ഗുരുവിനെ ഇനിയും ബുദ്ധിമുട്ടിക്കേണ്ടാ.","p":1},{"v":50,"t":"ഇതുകേട്ട് യേശു പറഞ്ഞു: ഭയപ്പെടേണ്ടാ, വിശ്വസിക്കുകമാത്രം ചെയ്യുക; അവൾ രക്ഷപ്പെടും."},{"v":51,"t":"അവൻ വീട്ടിലെത്തിയപ്പോൾ തന്നോടുകൂടെ അകത്തു പ്രവേശിക്കാൻ പത്രോസിനെയും യോഹന്നാനെയും യാക്കോബിനെയും പെൺകുട്ടിയുടെ പിതാവിനെയും മാതാവിനെയുമല്ലാതെ മറ്റാരെയും അനുവദിച്ചില്ല."},{"v":52,"t":"എല്ലാവരും കരയുകയും അവളെക്കുറിച്ചു വിലപിക്കുകയും ചെയ്തുകൊണ്ടിരുന്നു. അവൻ പറഞ്ഞു: കരയേണ്ടാ, അവൾ മരിച്ചിട്ടില്ല; ഉറങ്ങുകയാണ്."},{"v":53,"t":"എന്നാൽ, അവൾ മരിച്ചു കഴിഞ്ഞു എന്ന് അറിഞ്ഞിരുന്നതുകൊണ്ട് അവർ അവനെ പരിഹസിച്ചു."},{"v":54,"t":"അവൻ അവളുടെ കൈക്കുപിടിച്ച് അവളെ വിളിച്ചുകൊണ്ടു പറഞ്ഞു: ബാലികേ, എഴുന്നേല്ക്കുക."},{"v":55,"t":"അപ്പോൾ അവളുടെ ആത്മാവ് തിരിച്ചുവന്നു. ഉടനെ അവൾ എഴുന്നേറ്റിരുന്നു. അവൾക്കു ഭക്ഷിക്കാൻ എന്തെങ്കിലും നല്കാൻ അവൻ നിർദേശിച്ചു."},{"v":56,"t":"അവളുടെ മാതാപിതാക്കന്മാർ അദ്ഭുതസ്തബ്ധരായി. സംഭവിച്ചതെന്തെന്ന് ആരോടും പറയരുതെന്ന് അവൻ കല്പിച്ചു."}],"9":[{"h":"അപ്പസ്തോലന്മാരെ അയയ്ക്കുന്നു"},{"v":1,"t":"അവൻ പന്ത്രണ്ടുപേരെയും അടുക്കൽ വിളിച്ച് സകല പിശാചുക്കളുടെയുംമേൽ അവർക്ക് ശക്തിയും അധികാരവും കൊടുത്തു; അതോടൊപ്പം രോഗങ്ങൾ സുഖപ്പെടുത്താനും","p":1},{"v":2,"t":"ദൈവരാജ്യം പ്രഘോഷിക്കാനും രോഗികളെ സുഖപ്പെടുത്താനും അവൻ അവരെ അയച്ചു."},{"v":3,"t":"അവൻ പറഞ്ഞു: യാത്രയ്ക്ക് വടിയോ സഞ്ചിയോ അപ്പമോ പണമോ ഒന്നും എടുക്കരുത്. രണ്ട് ഉടുപ്പും ഉണ്ടായിരിക്കരുത്."},{"v":4,"t":"നിങ്ങൾ ഏതു വീട്ടിൽ പ്രവേശിക്കുന്നുവോ അവിടെ താമസിക്കുക. അവിടെനിന്നു പുറപ്പെടുകയും ചെയ്യുക."},{"v":5,"t":"ആരെങ്കിലും നിങ്ങളെ സ്വീകരിക്കാതിരുന്നാൽ ആ പട്ടണത്തിൽനിന്നു പോകുമ്പോൾ അവർക്കെതിരേ സാക്ഷ്യത്തിനായി നിങ്ങളുടെ പാദത്തിലെ പൊടി തട്ടിക്കളയുവിൻ."},{"v":6,"t":"അവർ പുറപ്പെട്ട്, ഗ്രാമങ്ങൾതോറും ചുറ്റിസഞ്ചരിച്ച് എല്ലായിടത്തും സദ്വാർത്ത അറിയിക്കുകയും സുഖപ്പെടുത്തുകയും ചെയ്തു."},{"h":"ഹേറോദേസിന്റെ ഉത്കണ്ഠ"},{"v":7,"t":"സംഭവിച്ചതെല്ലാം കേട്ട് ഭരണാധികാരിയായ ഹേറോദേസ് ചിന്താക്കുഴപ്പത്തിലായി. എന്തെന്നാൽ, യോഹന്നാൻ മരിച്ചവരിൽനിന്ന് ഉയിർപ്പിക്കപ്പെട്ടിരിക്കുന്നു എന്നു ചിലരും","p":1},{"v":8,"t":"ഏലിയാ പ്രത്യക്ഷപ്പെട്ടിരിക്കുന്നു എന്നു മറ്റുചിലരും പൂർവപ്രവാചകന്മാരിൽ ഒരുവൻ ഉയിർത്തുവന്നിരിക്കുന്നു എന്നു വേറെ ചിലരും പറഞ്ഞിരുന്നു."},{"v":9,"t":"ഹേറോദേസ് പറഞ്ഞു: ഞാൻ യോഹന്നാനെ ശിരച്ഛേദം ചെയ്തു. പിന്നെ ആരെക്കുറിച്ചാണ് ഞാൻ ഇക്കാര്യങ്ങൾ കേൾക്കുന്നത്? അവൻ ആരാണ്? അവനെ കാണാൻ ഹേറോദേസ് ശ്രമിച്ചുകൊണ്ടിരുന്നു."},{"h":"അപ്പം വർധിപ്പിക്കുന്നു"},{"v":10,"t":"അപ്പസ്തോലന്മാർ മടങ്ങിവന്ന് തങ്ങൾ ചെയ്തതെല്ലാം യേശുവിനോടു വിവരിച്ചു. അവൻ അവരെ കൂട്ടിക്കൊണ്ട് സ്വകാര്യമായി ബേത്സൈദാ എന്ന പട്ടണത്തിലേക്കു പിൻവാങ്ങി.","p":1},{"v":11,"t":"ഇതറിഞ്ഞ ജനക്കൂട്ടം അവനെ അനുഗമിച്ചു. അവൻ അവരെ സ്വീകരിച്ച് ദൈവരാജ്യത്തെപ്പറ്റി സംസാരിക്കുകയും സൗഖ്യം ആവശ്യമായിരുന്നവരെ സുഖപ്പെടുത്തുകയും ചെയ്തുകൊണ്ടിരുന്നു."},{"v":12,"t":"പകൽ അസ്തമിച്ചുതുടങ്ങിയപ്പോൾ പന്ത്രണ്ടുപേരും അടുത്തുവന്ന് അവനോടു പറഞ്ഞു: നാം വിജനപ്രദേശത്തായതുകൊണ്ട് ചുറ്റുമുള്ള ഗ്രാമങ്ങളിലും നാട്ടിൻപുറങ്ങളിലും പോയി താമസിക്കുന്നതിനും ഭക്ഷണസാധനങ്ങൾ കണ്ടെത്തുന്നതിനും ജനക്കൂട്ടത്തെ പറഞ്ഞയയ്ക്കുക."},{"v":13,"t":"അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ അവർക്കു ഭക്ഷിക്കാൻ കൊടുക്കുവിൻ. എന്നാൽ, അവർ പറഞ്ഞു: ഞങ്ങളുടെ പക്കൽ അഞ്ചപ്പവും രണ്ടു മീനും മാത്രമേയുള്ളു. ഈ ജനത്തിനു മുഴുവൻ ഭക്ഷണം നല്കണമെങ്കിൽ ഞങ്ങൾ പോയി വാങ്ങിക്കൊണ്ടുവരണം."},{"v":14,"t":"അവിടെ ഏകദേശം അയ്യായിരം പുരുഷന്മാർ ഉണ്ടായിരുന്നു. അവൻ ശിഷ്യന്മാരോടു പറഞ്ഞു: ജനത്തെ അമ്പതുവീതം പന്തികളായി ഇരുത്തുവിൻ."},{"v":15,"t":"അവർ അങ്ങനെ ചെയ്തു; എല്ലാവരെയും ഇരുത്തി."},{"v":16,"t":"അപ്പോൾ അവൻ ആ അഞ്ചപ്പവും രണ്ടു മീനും എടുത്ത്, സ്വർഗത്തിലേക്കു നോക്കി, ആശീർവദിച്ചു മുറിച്ച് ജനങ്ങൾക്കു വിളമ്പാനായി ശിഷ്യന്മാരെ ഏല്പിച്ചു."},{"v":17,"t":"എല്ലാവരും ഭക്ഷിച്ചു തൃപ്തരായി. ബാക്കിവന്ന കഷണങ്ങൾ പന്ത്രണ്ടു കുട്ട അവർ ശേഖരിച്ചു."},{"h":"പത്രോസിന്റെ വിശ്വാസപ്രഖ്യാപനം"},{"v":18,"t":"ഒരിക്കൽ അവൻ തനിയേ പ്രാർഥിച്ചുകൊണ്ടിരിക്കുമ്പോൾ ശിഷ്യന്മാരും അവന്റെ കൂടെ ഉണ്ടായിരുന്നു. അപ്പോൾ അവൻ ചോദിച്ചു: ഞാൻ ആരെന്നാണു ജനങ്ങൾ പറയുന്നത്?","p":1},{"v":19,"t":"അവർ മറുപടി നല്കി; ചിലർ സ്നാപകയോഹന്നാനെന്നും മറ്റു ചിലർ ഏലിയാ എന്നും വേറെ ചിലർ പൂർവപ്രവാചകന്മാരിൽ ഒരാൾ ഉയിർത്തെഴുന്നേറ്റു എന്നും പറയുന്നു."},{"v":20,"t":"അവൻ അവരോടു ചോദിച്ചു: എന്നാൽ, ഞാൻ ആരെന്നാണു നിങ്ങൾ പറയുന്നത്? പത്രോസ് മറുപടി പറഞ്ഞു: ദൈവത്തിന്റെ ക്രിസ്തു."},{"h":"പീഡാനുഭവത്തെക്കുറിച്ച് ഒന്നാം പ്രവചനം"},{"v":21,"t":"ഇക്കാര്യം ആരോടും പറയരുതെന്നു കല്പിച്ചശേഷം","p":1},{"v":22,"t":"അവൻ അരുൾചെയ്തു: മനുഷ്യപുത്രൻ വളരെയേറെ സഹിക്കുകയും ജനപ്രമാണികൾ, പുരോഹിതപ്രമുഖന്മാർ, നിയമജ്ഞർ എന്നിവരാൽ തിരസ്കരിക്കപ്പെടുകയും വധിക്കപ്പെടുകയും മൂന്നാംദിവസം ഉയിർപ്പിക്കപ്പെടുകയും വേണം."},{"v":23,"t":"അവൻ എല്ലാവരോടുമായി പറഞ്ഞു: ആരെങ്കിലും എന്റെ പിന്നാലെ വരാൻ ആഗ്രഹിക്കുന്നെങ്കിൽ അയാൾ സ്വയം പരിത്യജിച്ച്, അനുദിനം തന്റെ കുരിശെടുത്ത് എന്നെ അനുഗമിക്കട്ടെ."},{"v":24,"t":"സ്വന്തം ജീവൻ രക്ഷിക്കാൻ ആഗ്രഹിക്കുന്നവൻ അതു നഷ്ടപ്പെടുത്തും; എന്നെപ്രതി സ്വന്തം ജീവൻ നഷ്ടപ്പെടുത്തുന്നവൻ അതിനെ രക്ഷിക്കും."},{"v":25,"t":"ഒരുവൻ ലോകം മുഴുവൻ നേടിയാലും സ്വയം നഷ്ടപ്പെടുത്തുകയോ നശിപ്പിക്കുകയോ ചെയ്താൽ അയാൾക്ക് എന്തു പ്രയോജനം?"},{"v":26,"t":"ആരെങ്കിലും എന്നെക്കുറിച്ചോ എന്റെ വചനങ്ങളെക്കുറിച്ചോ ലജ്ജിച്ചാൽ അയാളെക്കുറിച്ച് തന്റെയും പിതാവിന്റെയും വിശുദ്ധ ദൂതന്മാരുടെയും മഹത്ത്വത്തിൽ വരുമ്പോൾ മനുഷ്യപുത്രനും ലജ്ജിക്കും."},{"v":27,"t":"എന്നാൽ, സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു. ദൈവരാജ്യം കാണുന്നതിനു മുമ്പ് മരണം രുചിക്കയില്ലാത്ത ചിലർ ഈ നില്ക്കുന്നവരുടെ ഇടയിലുണ്ട്."},{"h":"യേശു രൂപാന്തരപ്പെടുന്നു"},{"v":28,"t":"ഈ വചനങ്ങൾക്കുശേഷം ഏകദേശം എട്ടു ദിവസം കഴിഞ്ഞ് അവൻ പത്രോസ്, യോഹന്നാൻ, യാക്കോബ് എന്നിവരെ കൂട്ടിക്കൊണ്ടു പ്രാർഥിക്കാൻ മലയിലേക്കു കയറിപ്പോയി.","p":1},{"v":29,"t":"പ്രാർഥിച്ചുകൊണ്ടിരിക്കുമ്പോൾ അവന്റെ മുഖഭാവം മാറി; വസ്ത്രം തിളങ്ങുന്ന വെണ്മയാർന്നു."},{"v":30,"t":"അപ്പോൾ രണ്ടുപേർ - മോശയും ഏലിയായും - അവനോടു സംസാരിച്ചുകൊണ്ടിരുന്നു."},{"v":31,"t":"അവർ മഹത്ത്വത്തോടെ കാണപ്പെട്ടു. അടുത്തുതന്നെ ജറുസലേമിൽ പൂർത്തിയാകേണ്ട അവന്റെ പുറപ്പാടിനെക്കുറിച്ചാണ് അവർ സംസാരിച്ചുകൊണ്ടിരുന്നത്."},{"v":32,"t":"പത്രോസും കൂടെയുള്ളവരും നിദ്രാവിവശരായിരുന്നു. അവർ ഉണർന്നപ്പോൾ അവന്റെ മഹത്ത്വം ദർശിച്ചു; അവനോടുകൂടെ നില്ക്കുന്ന ഇരുവരെയും കണ്ടു."},{"v":33,"t":"അവർ അവനെ വിട്ടുപോകുമ്പോൾ പത്രോസ് യേശുവിനോടു പറഞ്ഞു: ഗുരോ, നാം ഇവിടെ ആയിരിക്കുന്നതു നല്ലതാണ്. ഞങ്ങൾ മൂന്നു കൂടാരങ്ങൾ ഉണ്ടാക്കട്ടെ. ഒന്നു നിനക്ക്, ഒന്നു മോശയ്ക്ക്, ഒന്ന് ഏലിയായ്ക്ക്. താൻ എന്താണു പറയുന്നതെന്ന് അവനുതന്നെ അറിയില്ലായിരുന്നു."},{"v":34,"t":"അവൻ ഇതു പറയുമ്പോൾ ഒരു മേഘംവന്ന് അവരെ ആവരണം ചെയ്തു. അവർ മേഘത്തിനുള്ളിൽ പ്രവേശിച്ചപ്പോൾ ശിഷ്യന്മാർ ഭയപ്പെട്ടു."},{"v":35,"t":"അപ്പോൾ മേഘത്തിൽനിന്ന് ഒരു സ്വരമുണ്ടായി: ഇവൻ എന്റെ പുത്രൻ, എന്റെ തിരഞ്ഞെടുക്കപ്പെട്ടവൻ; ഇവനെ ശ്രവിക്കുവിൻ."},{"v":36,"t":"സ്വരം നിലച്ചപ്പോൾ യേശു മാത്രം കാണപ്പെട്ടു. ശിഷ്യന്മാർ മൗനം അവലംബിച്ചു; തങ്ങൾ കണ്ടതൊന്നും ആ ദിവസങ്ങളിൽ അവർ ആരോടും പറഞ്ഞില്ല."},{"h":"പിശാചുബാധിച്ച ബാലനെ സുഖപ്പെടുത്തുന്നു"},{"v":37,"t":"പിറ്റേദിവസം അവൻ മലയിൽനിന്ന് ഇറങ്ങിവന്നപ്പോൾ വലിയ ഒരു ജനക്കൂട്ടം അവനെ കണ്ടുമുട്ടി.","p":1},{"v":38,"t":"അപ്പോൾ ജനക്കൂട്ടത്തിൽനിന്ന് ഒരുവൻ വിളിച്ചുപറഞ്ഞു: ഗുരോ, എന്റെ മകനെ കടാക്ഷിക്കണമെന്ന് നിന്നോടു ഞാൻ അപേക്ഷിക്കുന്നു. അവൻ എന്റെ ഏകമകനാണ്."},{"v":39,"t":"അവനെ ഒരു അരൂപി പിടികൂടുന്നു. അപ്പോൾ അവൻ പെട്ടെന്ന് നിലവിളിക്കുന്നു. അത് അവനെ വായിൽ നുര പതയുംവിധം കോച്ചിവലിക്കുകയും വിട്ടുമാറാതെ ഞെരുക്കുകയും ചെയ്യുന്നു"},{"v":40,"t":"അതിനെ പുറത്താക്കാൻ ഞാൻ നിന്റെ ശിഷ്യന്മാരോട് അപേക്ഷിച്ചു. എന്നാൽ, അവർക്കു സാധിച്ചില്ല."},{"v":41,"t":"യേശു മറുപടി പറഞ്ഞു: വിശ്വാസമില്ലാത്ത, വഴിപിഴച്ച തലമുറയേ, ഞാൻ എത്രനാൾ നിങ്ങളോടു കൂടെ ഉണ്ടായിരിക്കും? എത്രനാൾ നിങ്ങളെ സഹിക്കും? നിന്റെ മകനെ ഇവിടെ കൊണ്ടുവരുക."},{"v":42,"t":"യേശുവിന്റെ അടുത്തേക്കു വരുമ്പോൾത്തന്നെ പിശാച് അവനെ തള്ളിയിട്ട്, കോച്ചിവലിച്ചു. യേശു അശുദ്ധാരൂപിയെ ശാസിക്കുകയും കുട്ടിയെ സുഖപ്പെടുത്തി പിതാവിനെ ഏല്പിക്കുകയും ചെയ്തു."},{"v":43,"t":"ദൈവത്തിന്റെ മഹിമാതിരേകത്തിൽ എല്ലാവരും അദ്ഭുതപ്പെട്ടു."},{"h":"പീഡാനുഭവത്തെക്കുറിച്ച് രണ്ടാം പ്രവചനം"},{"v":43,"t":"അവന്റെ പ്രവൃത്തികളെക്കുറിച്ച് എല്ലാവരും വിസ്മയിക്കവേ, അവൻ ശിഷ്യരോടു പറഞ്ഞു:","p":1},{"v":44,"t":"ഈ വചനങ്ങൾ നിങ്ങൾ ശ്രദ്ധയോടെ കേൾക്കുവിൻ. മനുഷ്യപുത്രൻ മനുഷ്യരുടെ കൈകളിൽ ഏല്പിക്കപ്പെടാൻ പോകുന്നു."},{"v":45,"t":"ഇപ്പറഞ്ഞത് അവർക്കു മനസ്സിലായില്ല. അവർ ഗ്രഹിക്കാതിരിക്കാൻ തക്കവിധം അത് അവരിൽനിന്ന് മറയ്ക്കപ്പെട്ടിരുന്നു. അതെപ്പറ്റി അവനോടു ചോദിക്കാൻ അവർ ഭയപ്പെട്ടിരുന്നു."},{"h":"ആരാണു വലിയവൻ?"},{"v":46,"t":"തങ്ങളിൽ ആരാണ് വലിയവൻ എന്ന് അവരുടെയിടയിൽ തർക്കമുണ്ടായി.","p":1},{"v":47,"t":"യേശു അവരുടെ ഹൃദയവിചാരമറിഞ്ഞ് ഒരു ശിശുവിനെ എടുത്ത് തന്റെ അടുത്തുനിറുത്തി,"},{"v":48,"t":"അവരോടു പറഞ്ഞു: എന്റെ നാമത്തിൽ ഈ ശിശുവിനെ സ്വീകരിക്കുന്ന ഏവനും എന്നെ സ്വീകരിക്കുന്നു; എന്നെ സ്വീകരിക്കുന്നവൻ എന്നെ അയച്ചവനെ സ്വീകരിക്കുന്നു. എന്തെന്നാൽ, നിങ്ങളിൽ ഏറ്റവും ചെറിയവനാരോ, അവനാണ് നിങ്ങളിൽ ഏറ്റവും വലിയവൻ."},{"h":"നിങ്ങൾക്ക് എതിരല്ലാത്തയാൾ നിങ്ങളുടെ ഭാഗത്ത്"},{"v":49,"t":"യോഹന്നാൻ പറഞ്ഞു: ഗുരോ, നിന്റെ നാമത്തിൽ പിശാചുക്കളെ പുറത്താക്കുന്ന ഒരുവനെ ഞങ്ങൾ കണ്ടു. അയാൾ ഞങ്ങളോടൊപ്പം നിന്നെ അനുഗമിക്കാത്തതുകൊണ്ട് ഞങ്ങൾ അയാളെ തടഞ്ഞു.","p":1},{"v":50,"t":"യേശു പറഞ്ഞു: അവനെ തടയേണ്ടാ; എന്തെന്നാൽ, നിങ്ങൾക്ക് എതിരല്ലാത്തയാൾ നിങ്ങളുടെ ഭാഗത്താണ്."},{"h":"സമരിയാക്കാരുടെ തിരസ്കാരം"},{"v":51,"t":"തന്റെ ആരോഹണത്തിന്റെ ദിവസങ്ങൾ പൂർത്തിയായിക്കൊണ്ടിരിക്കേ, അവൻ ജറുസലേമിലേക്കു പോകാൻ തീരുമാനിച്ചുറച്ചു.","p":1},{"v":52,"t":"അവൻ തനിക്കു മുമ്പേ ദൂതന്മാരെ അയച്ചു. അവർ പോയി അവനുവേണ്ട ഒരുക്കങ്ങൾ ചെയ്യാൻ സമരിയാക്കാരുടെ ഒരു ഗ്രാമത്തിൽ പ്രവേശിച്ചു."},{"v":53,"t":"അവൻ ജറുസലേമിലേക്കു പോകുകയായിരുന്നതുകൊണ്ട് അവർ അവനെ സ്വീകരിച്ചില്ല."},{"v":54,"t":"ഇതുകണ്ടപ്പോൾ ശിഷ്യന്മാരായ യാക്കോബും യോഹന്നാനും പറഞ്ഞു: കർത്താവേ, സ്വർഗത്തിൽനിന്ന് അഗ്നി ഇറങ്ങി ഇവരെ നശിപ്പിക്കട്ടെ എന്ന് ഞങ്ങൾ പറയാൻ നീ മനസ്സാകുന്നുവോ?"},{"v":55,"t":"അവൻ തിരിഞ്ഞ് അവരെ ശാസിച്ചു."},{"v":56,"t":"അനന്തരം അവർ മറ്റൊരു ഗ്രാമത്തിലേക്കുപോയി."},{"h":"ശിഷ്യത്വം ആവശ്യപ്പെടുന്ന ത്യാഗങ്ങൾ"},{"v":57,"t":"അവർ വഴിയേ പോകുമ്പോൾ ഒരുവൻ അവനോടു പറഞ്ഞു: നീ എവിടെപ്പോയാലും ഞാൻ നിന്നെ അനുഗമിക്കും.","p":1},{"v":58,"t":"യേശു അവനോടു പറഞ്ഞു: കുറുനരികൾക്കു മാളങ്ങളും ആകാശപ്പറവകൾക്കു കൂടുകളുമുണ്ട്; മനുഷ്യപുത്രനു തലചായ്ക്കാൻ ഇടമില്ല."},{"v":59,"t":"അവൻ മറ്റൊരുവനോടു പറഞ്ഞു: എന്നെ അനുഗമിക്കുക. അവൻ പറഞ്ഞു: കർത്താവേ, ഞാൻ ആദ്യം പോയി എന്റെ പിതാവിനെ സംസ്കരിക്കാൻ അനുവദിച്ചാലും."},{"v":60,"t":"യേശു പറഞ്ഞു: മരിച്ചവർ തങ്ങളുടെ മരിച്ചവരെ സംസ്കരിക്കട്ടെ; നീ പോയി ദൈവരാജ്യം പ്രസംഗിക്കുക."},{"v":61,"t":"വേറൊരുവൻ പറഞ്ഞു: കർത്താവേ, ഞാൻ നിന്നെ അനുഗമിക്കാം; പക്ഷേ, ആദ്യം പോയി എന്റെ വീട്ടുകാരോടു യാത്ര പറയാൻ അനുവദിക്കണം."},{"v":62,"t":"യേശു അവനോടു പറഞ്ഞു: കലപ്പയിൽ കൈവച്ചിട്ടു പിന്തിരിഞ്ഞുനോക്കുന്ന ഒരുവനും ദൈവരാജ്യത്തിനു യോഗ്യനല്ല."}],"10":[{"h":"എഴുപത്തിരണ്ടുപേരെ അയയ്ക്കുന്നു"},{"v":1,"t":"അനന്തരം, കർത്താവ് വേറെ എഴുപത്തിരണ്ടുപേരെ നിയമിച്ചു. താൻ പോകാനിരുന്ന ഓരോ പട്ടണത്തിലേക്കും സ്ഥലത്തേക്കും രണ്ടുപേരെ വീതം തനിക്കു മുമ്പേ അയച്ചു.","p":1},{"v":2,"t":"അവൻ അവരോടു പറഞ്ഞു: വിളവ് അധികം; വേലക്കാരോ ചുരുക്കം. അതിനാൽ വിളഭൂമിയിലേക്കു വേലക്കാരെ അയയ്ക്കാൻ വിളവിന്റെ നാഥനോടു നിങ്ങൾ പ്രാർഥിക്കുവിൻ."},{"v":3,"t":"പോകുവിൻ. ഇതാ, ചെന്നായ്ക്കളുടെ ഇടയിൽ കുഞ്ഞാടുകളെ എന്നപോലെ ഞാൻ നിങ്ങളെ അയയ്ക്കുന്നു."},{"v":4,"t":"മടിശ്ശീലയോ സഞ്ചിയോ ചെരിപ്പോ നിങ്ങൾ കൊണ്ടുപോകരുത്. വഴിയിൽവച്ച് ആരെയും അഭിവാദനം ചെയ്യുകയുമരുത്."},{"v":5,"t":"നിങ്ങൾ ഏതു വീട്ടിൽ പ്രവേശിച്ചാലും, ആദ്യമേ ആശംസിക്കണം: ഈ വീടിനു സമാധാനം!"},{"v":6,"t":"സമാധാനത്തിന്റെ പുത്രൻ അവിടെയുണ്ടെങ്കിൽ നിങ്ങളുടെ സമാധാനം അവനിൽ കുടികൊള്ളും. ഇല്ലെങ്കിൽ അതു നിങ്ങളിലേക്കു തിരിച്ചുപോരും."},{"v":7,"t":"അവർ തരുന്നതു ഭക്ഷിക്കുകയും പാനം ചെയ്യുകയും ചെയ്തുകൊണ്ട് ആ വീട്ടിൽത്തന്നെ വസിക്കുവിൻ. എന്തെന്നാൽ, വേലക്കാരൻ കൂലിക്ക് അർഹനാണല്ലോ. നിങ്ങൾ വീടുതോറും നടക്കരുത്."},{"v":8,"t":"ഏതെങ്കിലും നഗരത്തിൽ നിങ്ങൾ പ്രവേശിക്കുകയും അവർ നിങ്ങളെ സ്വീകരിക്കുകയും ചെയ്യുമ്പോൾ നിങ്ങൾക്കു വിളമ്പുന്നതു ഭക്ഷിക്കുവിൻ."},{"v":9,"t":"അവിടെയുള്ള രോഗികളെ സുഖപ്പെടുത്തുവിൻ. ദൈവരാജ്യം നിങ്ങളെ സമീപിച്ചിരിക്കുന്നുവെന്ന് അവരോടു പറയുകയും ചെയ്യുവിൻ."},{"v":10,"t":"ഏതെങ്കിലും നഗരത്തിൽ പ്രവേശിക്കുമ്പോൾ അവർ നിങ്ങളെ സ്വീകരിക്കാതിരുന്നാൽ നിങ്ങൾ പുറത്ത് തെരുവിലേക്കിറങ്ങി പറയണം:"},{"v":11,"t":"നിങ്ങളുടെ നഗരത്തിൽനിന്ന് ഞങ്ങളുടെ പാദങ്ങളിൽ പറ്റിയിട്ടുള്ള പൊടിപോലും നിങ്ങൾക്കെതിരേ ഞങ്ങൾ തട്ടിക്കളയുന്നു. എന്നാൽ, ദൈവരാജ്യം സമീപിച്ചിരിക്കുന്നെന്ന് നിങ്ങൾ അറിഞ്ഞുകൊള്ളുവിൻ."},{"v":12,"t":"ഞാൻ നിങ്ങളോടു പറയുന്നു, ആ ദിവസം സോദോമിന്റെ സ്ഥിതി ആ നഗരത്തിന്റേതിനെക്കാൾ സഹനീയമായിരിക്കും."},{"h":"അനുതപിക്കാത്ത നഗരങ്ങൾ"},{"v":13,"t":"കൊറാസീൻ, നിനക്കു ദുരിതം! ബേത്സൈദാ, നിനക്കു ദുരിതം! നിങ്ങളിൽ നടന്ന അദ്ഭുതങ്ങൾ ടയിറിലും സിദോനിലും നടന്നിരുന്നെങ്കിൽ അവർ ചാക്കിലും ചാരത്തിലുമിരുന്ന് പണ്ടേ മാനസാന്തരപ്പെട്ടുമായിരുന്നു.","p":1},{"v":14,"t":"എന്നാൽ, ന്യായവിധിയിൽ ടയിറിന്റെയും സിദോന്റെയും സ്ഥിതി നിങ്ങളുടേതിനെക്കാൾ സഹനീയമായിരിക്കും."},{"v":15,"t":"കഫർണാമേ, നീ ആകാശത്തോളം ഉയർത്തപ്പെടുമെന്നോ? നീ പാതാളത്തോളം താഴ്ത്തപ്പെടും."},{"v":16,"t":"നിങ്ങളെ കേൾക്കുന്നവൻ എന്നെ കേൾക്കുന്നു; നിങ്ങളെ നിരസിക്കുന്നവൻ എന്നെ നിരസിക്കുന്നു. എന്നെ നിരസിക്കുന്നവനോ, എന്നെ അയച്ചവനെ നിരസിക്കുന്നു."},{"h":"എഴുപത്തിരണ്ടുപേർ മടങ്ങിയെത്തുന്നു"},{"v":17,"t":"എഴുപത്തിരണ്ടുപേരും സന്തോഷത്തോടെ തിരിച്ചുവന്നു പറഞ്ഞു: കർത്താവേ, നിന്റെ നാമത്തിൽ പിശാചുക്കൾപോലും ഞങ്ങൾക്കു കീഴ്പ്പെടുന്നു.","p":1},{"v":18,"t":"അവൻ അവരോടു പറഞ്ഞു: സാത്താൻ സ്വർഗത്തിൽനിന്ന് ഇടിമിന്നൽപോലെ നിപതിക്കുന്നതു ഞാൻ കണ്ടു."},{"v":19,"t":"ഇതാ, പാമ്പുകളുടെയും തേളുകളുടെയും ശത്രുവിന്റെ സകലശക്തികളുടെയുംമേൽ നിങ്ങൾക്കു ഞാൻ അധികാരം തന്നിരിക്കുന്നു. ഒന്നും നിങ്ങളെ ഉപദ്രവിക്കയില്ല."},{"v":20,"t":"എന്നാൽ, അരൂപികൾ നിങ്ങൾക്കു കീഴടങ്ങുന്നു എന്നതിൽ നിങ്ങൾ സന്തോഷിക്കേണ്ടാ; മറിച്ച്, നിങ്ങളുടെ പേരുകൾ സ്വർഗത്തിൽ എഴുതപ്പെട്ടിരിക്കുന്നു എന്നതിൽ സന്തോഷിക്കുവിൻ."},{"h":"യേശു ആത്മാവിൽ ആനന്ദിക്കുന്നു"},{"v":21,"t":"ആ മണിക്കൂറിൽത്തന്നെ പരിശുദ്ധാത്മാവിൽ ആനന്ദിച്ച് അവൻ പറഞ്ഞു: സ്വർഗത്തിന്റെയും ഭൂമിയുടെയും നാഥനായ പിതാവേ, അവിടത്തെ ഞാൻ സ്തുതിക്കുന്നു. എന്തെന്നാൽ, അങ്ങ് ഇവ ബുദ്ധിമതികളിലും വിവേകികളിലുംനിന്ന് മറച്ചുവയ്ക്കുകയും ശിശുക്കൾക്കു വെളിപ്പെടുത്തുകയും ചെയ്തു. അതേ, പിതാവേ, അതായിരുന്നു അവിടത്തെ തിരുവുള്ളം.","p":1},{"v":22,"t":"സർവവും പിതാവ് എന്നെ ഏല്പിച്ചിരിക്കുന്നു. പുത്രനാരെന്ന് പിതാവല്ലാതെ ആരും അറിയുന്നില്ല; പിതാവാരെന്ന് പുത്രനും പുത്രൻ ആർക്കു വെളിപ്പെടുത്താനാഗ്രഹിക്കുന്നുവോ അവനുമല്ലാതെ മറ്റാരും അറിയുന്നില്ല."},{"v":23,"t":"അവൻ ശിഷ്യന്മാരുടെ നേരേ തിരിഞ്ഞ് അവരോടു മാത്രമായി പറഞ്ഞു: നിങ്ങൾ കാണുന്നവ കാണുന്ന കണ്ണുകൾ ഭാഗ്യമുള്ളവ."},{"v":24,"t":"കാരണം, ഞാൻ പറയുന്നു, അനേകം പ്രവാചകന്മാരും രാജാക്കന്മാരും നിങ്ങൾ കാണുന്നവ കാണാൻ ആഗ്രഹിച്ചു; എങ്കിലും കണ്ടില്ല. നിങ്ങൾ കേൾക്കുന്നവ കേൾക്കാൻ ആഗ്രഹിച്ചു; എങ്കിലും കേട്ടില്ല."},{"h":"നല്ല സമരിയാക്കാരന്റെ ഉപമ"},{"v":25,"t":"അപ്പോൾ ഒരു നിയമജ്ഞൻ എഴുന്നേറ്റുനിന്ന് അവനെ പരീക്ഷിക്കാൻ ചോദിച്ചു: ഗുരോ, നിത്യജീവൻ അവകാശമാക്കാൻ ഞാൻ എന്തു ചെയ്യണം?","p":1},{"v":26,"t":"അവൻ ചോദിച്ചു: നിയമത്തിൽ എന്ത് എഴുതിയിരിക്കുന്നു? നീ എങ്ങനെ വായിക്കുന്നു?"},{"v":27,"t":"അവൻ മറുപടി പറഞ്ഞു: നീ നിന്റെ ദൈവമായ കർത്താവിനെ പൂർണഹൃദയത്തോടും പൂർണാത്മാവോടും പൂർണശക്തിയോടും പൂർണമനസ്സോടുംകൂടെ സ്നേഹിക്കണം; നിന്റെ അയല്ക്കാരനെ നിന്നെപ്പോലെയും."},{"v":28,"t":"അവൻ പ്രതിവചിച്ചു: നീ ശരിയായിത്തന്നെ ഉത്തരം പറഞ്ഞു. ഇതനുസരിച്ചു പ്രവർത്തിക്കുക; നീ ജീവിക്കും."},{"v":29,"t":"എന്നാൽ അവൻ തന്നെത്തന്നെ ന്യായീകരിക്കാൻ ആഗ്രഹിച്ച് യേശുവിനോടു ചോദിച്ചു: ആരാണ് എന്റെ അയല്ക്കാരൻ?"},{"v":30,"t":"യേശു പറഞ്ഞു: ഒരുവൻ ജറുസലേമിൽനിന്ന് ജറീക്കോയിലേക്കു ഇറങ്ങിവരികയായിരുന്നു. അവൻ കവർച്ചക്കാരുടെ കൈയിൽപ്പെട്ടു. അവർ അവന്റെ വസ്ത്രങ്ങൾ ഉരിഞ്ഞെടുത്ത്, അവനെ പ്രഹരിച്ച് അർധപ്രാണനാക്കിയിട്ടു പൊയ്ക്കളഞ്ഞു."},{"v":31,"t":"ഒരു പുരോഹിതൻ ആ വഴിയേ ഇറങ്ങിവരാൻ ഇടയായി. അവനെക്കണ്ട് മറുവശത്തുകൂടെ കടന്നുപോയി."},{"v":32,"t":"അതുപോലെ ഒരു ലേവായനും ആ സ്ഥലത്തു വന്നപ്പോൾ, അവനെ കണ്ടെങ്കിലും മറുവശത്തുകൂടെ കടന്നുപോയി."},{"v":33,"t":"എന്നാൽ, ഒരു സമരിയാക്കാരൻ യാത്രാമധ്യേ അവൻ കിടന്ന സ്ഥലത്തു വന്നു. അവനെക്കണ്ട് അനുകമ്പ തോന്നി."},{"v":34,"t":"അടുത്തുചെന്ന് എണ്ണയും വീഞ്ഞുമൊഴിച്ച് അവന്റെ മുറിവുകൾ വച്ചുകെട്ടി, തന്റെ മൃഗത്തിന്റെ പുറത്തു കയറ്റി ഒരു സത്രത്തിൽ കൊണ്ടുചെന്നു പരിചരിച്ചു."},{"v":35,"t":"അടുത്തദിവസം അവൻ സത്രം സൂക്ഷിപ്പുകാരന്റെ കൈയിൽ രണ്ടു ദനാറ കൊടുത്തിട്ടു പറഞ്ഞു: ഇവനെ പരിചരിച്ചു കൊള്ളണം. കൂടുതൽ എന്തെങ്കിലും ചെലവാകുന്നെങ്കിൽ ഞാൻ തിരിച്ചുവരുമ്പോൾ തന്നുകൊള്ളാം."},{"v":36,"t":"കവർച്ചക്കാരുടെ കൈയിൽപ്പെട്ട അവന് ഈ മൂവരിൽ ആരാണ് അയല്ക്കാരനായിത്തീർന്നതെന്നാണ് നീ വിചാരിക്കുന്നത്?"},{"v":37,"t":"അവൻ പറഞ്ഞു: അവനോടു കരുണ കാണിച്ചവൻ. യേശു അവനോടു പറഞ്ഞു: നീയും പോയി അതുപോലെ ചെയ്യുക."},{"h":"മർത്തായും മറിയവും"},{"v":38,"t":"അവർ പോകുന്നവഴി അവൻ ഒരു ഗ്രാമത്തിൽ പ്രവേശിച്ചു. മർത്താ എന്നുപേരുള്ള ഒരുവൾ അവനെ ഭവനത്തിൽ സ്വീകരിച്ചു.","p":1},{"v":39,"t":"അവൾക്ക് മറിയം എന്നു പേരുള്ള ഒരു സഹോദരിയുണ്ടായിരുന്നു. അവൾ കർത്താവിന്റെ പാദത്തിങ്കൽ വചനം കേട്ടുകൊണ്ടിരുന്നു."},{"v":40,"t":"മർത്തായാകട്ടെ, ശുശ്രൂഷയിൽ വളരെയേറെ വ്യഗ്രചിത്തയായിരുന്നു. അവൾ അവന്റെ അടുത്തുചെന്നു പറഞ്ഞു: കർത്താവേ, ശുശ്രൂഷയ്ക്കായി എന്റെ സഹോദരി എന്നെ തനിയേ വിട്ടിരിക്കുന്നതു നീ കാണുന്നില്ലേ? എന്നെ സഹായിക്കാൻ അവളോടു പറയുക."},{"v":41,"t":"കർത്താവ് അവളോടു പറഞ്ഞു: മർത്താ, മർത്താ, നീ അനേക കാര്യങ്ങളെക്കുറിച്ച് ഉത്കണ്ഠാകുലയും അസ്വസ്ഥയുമായിരിക്കുന്നു."},{"v":42,"t":"എന്നാൽ, ഒന്നുമാത്രമേ ആവശ്യമുള്ളൂ. മറിയം നല്ലഭാഗം തിരഞ്ഞെടുത്തിരിക്കുന്നു. അത് അവളിൽനിന്ന് എടുക്കപ്പെടുകയില്ല."}],"11":[{"h":"യേശു പഠിപ്പിച്ച പ്രാർഥന"},{"v":1,"t":"അവൻ ഒരിടത്ത് പ്രാർഥിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അതു കഴിഞ്ഞപ്പോൾ ശിഷ്യന്മാരിലൊരുവൻ അവനോടു പറഞ്ഞു: കർത്താവേ, യോഹന്നാൻ തന്റെ ശിഷ്യരെ പഠിപ്പിച്ചപോലെ, ഞങ്ങളെയും പ്രാർഥിക്കാൻ പഠിപ്പിക്കുക.","p":1},{"v":2,"t":"അവൻ അരുൾചെയ്തു: നിങ്ങൾ പ്രാർഥിക്കുമ്പോൾ ഇങ്ങനെ പറയുവിൻ: പിതാവേ, അങ്ങയുടെ നാമം പരിശുദ്ധമാക്കപ്പെടണമേ. അങ്ങയുടെ രാജ്യം വരണമേ."},{"v":3,"t":"അന്നന്നുവേണ്ട ആഹാരം അനുദിനം ഞങ്ങൾക്കു നല്കണമേ."},{"v":4,"t":"ഞങ്ങളുടെ പാപങ്ങൾ ഞങ്ങളോടു ക്ഷമിക്കണമേ. കാരണം, ഞങ്ങളുടെ എല്ലാ കടക്കാരോടും ഞങ്ങൾ ക്ഷമിക്കുന്നു. ഞങ്ങളെ പ്രലോഭനത്തിൽ ഉൾപ്പെടുത്തരുതേ."},{"h":"പ്രാർഥനയുടെ ശക്തി"},{"v":5,"t":"അവൻ അവരോടു പറഞ്ഞു: നിങ്ങളിലൊരുവന് ഒരു സ്നേഹിതനുണ്ടെന്നിരിക്കട്ടെ. അർധരാത്രി അവന്റെ അടുത്തുചെന്ന് അവൻ പറയുന്നു: സ്നേഹിതാ, എനിക്കു മൂന്ന് അപ്പം വായ്പതരുക.","p":1},{"v":6,"t":"എന്തെന്നാൽ, ഒരു സ്നേഹിതൻ യാത്രാമധ്യേ എന്റെ അടുക്കൽ വന്നിരിക്കുന്നു. അവനു വിളമ്പാൻ എനിക്കൊന്നുമില്ല."},{"v":7,"t":"അപ്പോൾ, അവൻ അകത്തുനിന്നു മറുപടി പറയുന്നു: എന്നെ ശല്യപ്പെടുത്തരുത്. കതകടച്ചുകഴിഞ്ഞു. എന്റെ കുട്ടികളും എന്റെകൂടെ കിടക്കയിലാണ്. എഴുന്നേറ്റ് നിനക്ക് ഒന്നും തരാൻ സാധിക്കുകയില്ല."},{"v":8,"t":"ഞാൻ നിങ്ങളോടു പറയുന്നു: അവൻ സ്നേഹിതനായിട്ടും എഴുന്നേറ്റ് അവനു കൊടുക്കുകയില്ലെങ്കിൽത്തന്നെ, നിർലജ്ജമായ നിർബന്ധത്താൽ എഴുന്നേറ്റ് അവന് ആവശ്യമുള്ളിടത്തോളം കൊടുക്കും."},{"v":9,"t":"വീണ്ടും ഞാൻ നിങ്ങളോടു പറയുന്നു: ചോദിക്കുവിൻ; നിങ്ങൾക്കു നല്കപ്പെടും. അന്വേഷിക്കുവിൻ; നിങ്ങൾ കണ്ടെത്തും. മുട്ടുവിൻ; നിങ്ങൾക്കു തുറക്കപ്പെടും."},{"v":10,"t":"എന്തെന്നാൽ, ചോദിക്കുന്ന ആർക്കും ലഭിക്കുന്നു. അന്വേഷിക്കുന്നവൻ കണ്ടെത്തുന്നു. മുട്ടുന്നവന് തുറക്കപ്പെടുകയും ചെയ്യുന്നു."},{"v":11,"t":"നിങ്ങളിൽ ഏതു പിതാവാണ് മകൻ മീൻ ചോദിച്ചാൽ പകരം പാമ്പിനെ കൊടുക്കുന്നത്?"},{"v":12,"t":"മുട്ട ചോദിച്ചാൽ പകരം തേളിനെ കൊടുക്കുന്നത്?"},{"v":13,"t":"മക്കൾക്കു നല്ല ദാനങ്ങൾ നല്കാൻ ദുഷ്ടരായ നിങ്ങൾക്ക് അറിയാമെങ്കിൽ, സ്വർഗസ്ഥനായ പിതാവ് തന്നോടു ചോദിക്കുന്നവർക്ക് എത്രയധികമായി പരിശുദ്ധാത്മാവിനെ നല്കുകയില്ല!"},{"h":"യേശുവും ബേൽസെബൂലും"},{"v":14,"t":"അവൻ ഊമയായ ഒരു പിശാചിനെ ബഹിഷ്കരിക്കുകയായിരുന്നു. പിശാച് പുറത്തുപോയപ്പോൾ ആ ഊമ സംസാരിച്ചു. ജനക്കൂട്ടം അദ്ഭുതപ്പെട്ടു.","p":1},{"v":15,"t":"അവരിൽ ചിലർ പറഞ്ഞു: അവൻ പിശാചുക്കളുടെ തലവനായ ബേൽസെബൂലിനെക്കൊണ്ടാണ് പിശാചുക്കളെ ബഹിഷ്കരിക്കുന്നത്."},{"v":16,"t":"വേറെ ചിലർ അവനെ പരീക്ഷിക്കാൻ സ്വർഗത്തിൽനിന്ന് ഒരു അടയാളം അവനോട് ആവശ്യപ്പെട്ടു."},{"v":17,"t":"അവരുടെ വിചാരങ്ങൾ അറിഞ്ഞുകൊണ്ട് അവൻ പറഞ്ഞു: അന്തശ്ഛിദ്രമുള്ള ഓരോ രാജ്യവും വിജനമാക്കപ്പെടും; ഭവനം ഭവനത്തിന്മേൽ പതിക്കും."},{"v":18,"t":"സാത്താൻ തനിക്കുതന്നെ എതിരായി ഭിന്നിച്ചാൽ അവന്റെ രാജ്യം എങ്ങനെ നിലനില്ക്കും? ഞാൻ ബേൽസെബൂലിനെക്കൊണ്ടു പിശാചുക്കളെ ബഹിഷ്ക്കരിക്കുന്നു എന്നു നിങ്ങൾ പറയുന്നു."},{"v":19,"t":"ബേൽസെബൂലിനെക്കൊണ്ടാണ് ഞാൻ പിശാചുക്കളെ ബഹിഷ്കരിക്കുന്നതെങ്കിൽ, നിങ്ങളുടെ പുത്രന്മാർ ആരെക്കൊണ്ടാണ് ബഹിഷ്കരിക്കുന്നത്? അതുകൊണ്ട് അവർ നിങ്ങളുടെ വിധികർത്താക്കളായിരിക്കും."},{"v":20,"t":"എന്നാൽ, ദൈവത്തിന്റെ വിരൽകൊണ്ടാണ് ഞാൻ പിശാചുക്കളെ ബഹിഷ്കരിക്കുന്നതെങ്കിൽ, ദൈവരാജ്യം നിങ്ങളിൽ വന്നുകഴിഞ്ഞിരിക്കുന്നു."},{"v":21,"t":"ശക്തൻ ആയുധധാരിയായി തന്റെ കൊട്ടാരത്തിനു കാവൽ നില്ക്കുമ്പോൾ അവനുള്ളവയെല്ലാം സുരക്ഷിതമാണ്."},{"v":22,"t":"എന്നാൽ, കൂടുതൽ ശക്തനായ ഒരുവൻ അവനെ ആക്രമിച്ചു കീഴ്പ്പെടുത്തിയാൽ അവൻ ആശ്രയിച്ചിരുന്ന ആയുധങ്ങൾ മറ്റേയാൾ അപഹരിക്കുകയും കൊള്ളമുതൽ ഭാഗിച്ചെടുക്കുകയും ചെയ്യും."},{"v":23,"t":"എന്നോടുകൂടെയല്ലാത്തവൻ എനിക്ക് എതിരാണ്. എന്നോടുകൂടെ ശേഖരിക്കാത്തവൻ ചിതറിച്ചുകളയുന്നു."},{"h":"അശുദ്ധാരൂപിയുടെ തിരിച്ചുവരവ്"},{"v":24,"t":"അശുദ്ധാരൂപി ഒരു മനുഷ്യനെ വിട്ടുപോയാൽ, വരണ്ട സ്ഥലങ്ങളിലൂടെ ആശ്വാസംതേടി അലഞ്ഞുനടക്കും. കണ്ടെത്താതെ വരുമ്പോൾ അതു പറയുന്നു: ഇറങ്ങിപ്പോന്ന ഭവനത്തിലേക്കുതന്നെ ഞാൻ തിരിച്ചുചെല്ലും.","p":1},{"v":25,"t":"തിരിച്ചുവരുമ്പോൾ ആ വീട് അടിച്ചുവാരിയും സജ്ജീകരിക്കപ്പെട്ടും കാണുന്നു."},{"v":26,"t":"അപ്പോൾ അവൻ പോയി തന്നെക്കാൾ ദുഷ്ടരായ ഏഴ് അശുദ്ധാരൂപികളെക്കൂടി കൊണ്ടുവന്ന് അവിടെ പ്രവേശിച്ച് വാസമുറപ്പിക്കുന്നു. അങ്ങനെ, ആ മനുഷ്യന്റെ അവസാനത്തെ അവസ്ഥ ആദ്യത്തേതിനെക്കാൾ മോശമായിത്തീരുന്നു."},{"h":"കൂടുതൽ അനുഗൃഹീതർ"},{"v":27,"t":"അവൻ ഇത് അരുൾചെയ്തുകൊണ്ടിരിക്കുമ്പോൾ ജനക്കൂട്ടത്തിൽനിന്ന് ഒരു സ്ത്രീ സ്വരമുയർത്തി അവനോടു പറഞ്ഞു: നിന്നെ വഹിച്ച ഉദരവും നിന്നെ പാലൂട്ടിയ മുലകളും അനുഗൃഹീതം.","p":1},{"v":28,"t":"എന്നാൽ അവൻ പറഞ്ഞു: ദൈവവചനംകേട്ട് അതുപാലിക്കുന്നവർ കൂടുതൽ അനുഗൃഹീതർ."},{"h":"യോനായുടെ അടയാളം"},{"v":29,"t":"ജനക്കൂട്ടം വർധിച്ചുവന്നപ്പോൾ അവൻ പറയാൻ തുടങ്ങി: ഈ തലമുറ ദുഷിച്ച തലമുറയാണ്. ഇത് അടയാളം അന്വേഷിക്കുന്നു. എന്നാൽ, യോനായുടെ അടയാളമല്ലാതെ മറ്റൊരടയാളവും അതിന് നല്കപ്പെടുകയില്ല.","p":1},{"v":30,"t":"യോനാ നിനെവേക്കാർക്ക് അടയാളമായിരുന്നപോലെ, മനുഷ്യപുത്രൻ ഈ തലമുറയ്ക്കും അടയാളമായിരിക്കും."},{"v":31,"t":"ദക്ഷിണദേശത്തെ രാജ്ഞി ന്യായവിധിയിൽ ഈ തലമുറയിലെ ആളുകളോടൊപ്പം ഉയിർപ്പിക്കപ്പെടുകയും അവരെ കുറ്റംവിധിക്കുകയും ചെയ്യും. എന്തെന്നാൽ, സോളമന്റെ ജ്ഞാനം ശ്രവിക്കാൻ അവൾ ഭൂമിയുടെ അതിർത്തിയിൽനിന്നു വന്നു. എന്നാൽ ഇതാ, ഇവിടെ സോളമനെക്കാൾ വലിയവൻ!"},{"v":32,"t":"നിനെവേക്കാരായ ആളുകൾ ന്യായവിധിയിൽ ഈ തലമുറയോടുകൂടെ ഉയിർത്തെഴുന്നേല്ക്കുകയും ഇതിനെ കുറ്റംവിധിക്കുകയും ചെയ്യും. എന്തെന്നാൽ, യോനായുടെ പ്രസംഗത്താൽ അവർ മാനസാന്തരപ്പെട്ടു. എന്നാൽ ഇതാ, ഇവിടെ യോനായെക്കാൾ വലിയവൻ!"},{"h":"കണ്ണ് ശരീരത്തിന്റെ വിളക്ക്"},{"v":33,"t":"വിളക്കുകൊളുത്തി ആരും നിലവറയിലോ പറയുടെ കീഴിലോ വയ്ക്കാറില്ല. മറിച്ച്, അകത്തു പ്രവേശിക്കുന്നവർക്കു വെളിച്ചം കാണാൻ പീഠത്തിന്മേലാണു വയ്ക്കുന്നത്.","p":1},{"v":34,"t":"നിന്റെ കണ്ണാണ് ശരീരത്തിന്റെ വിളക്ക്. നിന്റെ കണ്ണ് അന്യൂനമെങ്കിൽ ശരീരം മുഴുവൻ പ്രകാശിക്കും. ദുഷിച്ചതെങ്കിലോ, നിന്റെ ശരീരം ഇരുണ്ടുപോകും."},{"v":35,"t":"അതുകൊണ്ട്, നിന്നിലുള്ള വെളിച്ചം ഇരുളാകാതിരിക്കാൻ ശ്രദ്ധിക്കുക."},{"v":36,"t":"ഇരുളടഞ്ഞ ഒരു ഭാഗവുമില്ലാതെ നിന്റെ ശരീരം മുഴുവൻ പ്രകാശിതമാണെങ്കിൽ, വിളക്ക് അതിന്റെ കിരണങ്ങൾകൊണ്ട് നിനക്കു വെളിച്ചം തരുന്നപോലെ, ശരീരം മുഴുവൻ പ്രകാശമാനമായിരിക്കും."},{"h":"ഫരിസേയരുടെയും നിയമജ്ഞരുടെയും കപടനാട്യം"},{"v":37,"t":"അവൻ സംസാരിച്ചുകൊണ്ടിരിക്കേ, ഒരു ഫരിസേയൻ തന്റെകൂടെ ഭക്ഷണം കഴിക്കാൻ അവനെ ക്ഷണിച്ചു. അവൻ പ്രവേശിച്ച് ഭക്ഷണത്തിനിരുന്നു.","p":1},{"v":38,"t":"ഭക്ഷണത്തിനുമുമ്പ്, ആദ്യം അവൻ ക്ഷാളനം ചെയ്യാതിരുന്നതുകൊണ്ട് ആ ഫരിസേയൻ ആശ്ചര്യപ്പെട്ടു."},{"v":39,"t":"അപ്പോൾ കർത്താവ് അവനോടു പറഞ്ഞു: ഫരിസേയരായ നിങ്ങൾ കോപ്പകളുടെയും പാത്രങ്ങളുടെയും പുറം ശുദ്ധമാക്കുന്നു. നിങ്ങളുടെ അകമോ, ആർത്തിയും ദുഷ്ടതയുംകൊണ്ടു നിറഞ്ഞിരിക്കുന്നു."},{"v":40,"t":"ഭോഷന്മാരേ, പുറം നിർമിച്ചവൻ തന്നെയല്ലേ അകവും നിർമിച്ചത്?"},{"v":41,"t":"ഉള്ളിലുള്ളവ ദാനംചെയ്യുവിൻ. അപ്പോൾ നിങ്ങൾക്ക് എല്ലാം ശുദ്ധമായിരിക്കും."},{"v":42,"t":"ഫരിസേയരേ, നിങ്ങൾക്കു ദുരിതം! എന്തെന്നാൽ, നിങ്ങൾ കർപ്പൂരതുളസിയുടെയും അരൂതയുടെയും മറ്റെല്ലാ ചെടികളുടെയും ദശാംശം കൊടുക്കുന്നു. എന്നാൽ, ദൈവത്തിന്റെ നീതിയും സ്നേഹവും നിങ്ങൾ അവഗണിച്ചുകളയുന്നു. ഇവയാണ് മറ്റുള്ളവ അവഗണിക്കാതെതന്നെ നിങ്ങൾ ചെയ്യേണ്ടിയിരുന്നത്."},{"v":43,"t":"ഫരിസേയരേ, നിങ്ങൾക്കു ദുരിതം! എന്തെന്നാൽ, നിങ്ങൾ സിനഗോഗുകളിൽ ഉന്നതപീഠവും പൊതുസ്ഥലങ്ങളിൽ അഭിവാദനവും അഭിലഷിക്കുന്നു."},{"v":44,"t":"നിങ്ങൾക്കു ദുരിതം! എന്തെന്നാൽ, അടയാളപ്പെടുത്താത്ത കുഴിമാടങ്ങൾപോലെയാണു നിങ്ങൾ. മീതേ നടക്കുന്നവർ അറിയുന്നില്ല."},{"v":45,"t":"നിയമജ്ഞരിൽ ഒരുവൻ അവനോടു പറഞ്ഞു: ഗുരോ, നീ ഇതൊക്കെ പറയുമ്പോൾ ഞങ്ങളെയും അപമാനിക്കുകയാണ്."},{"v":46,"t":"അവൻ പറഞ്ഞു: നിയമജ്ഞരേ, നിങ്ങൾക്കു ദുരിതം! താങ്ങാനാവാത്ത ചുമടുകൾ മനുഷ്യരുടെമേൽ നിങ്ങൾ കെട്ടിയേല്പിക്കുന്നു. നിങ്ങളോ, ആ ചുമടുകൾ വിരൽകൊണ്ടു തൊടുന്നുപോലുമില്ല."},{"v":47,"t":"നിങ്ങൾക്കു ദുരിതം! എന്തെന്നാൽ, നിങ്ങളുടെ പിതാക്കന്മാർ വധിച്ച പ്രവാചകന്മാർക്കു നിങ്ങൾ കല്ലറകൾ പണിയുന്നു."},{"v":48,"t":"അങ്ങനെ നിങ്ങളുടെ പിതാക്കന്മാരുടെ പ്രവൃത്തികൾക്ക് നിങ്ങൾ സാക്ഷികളാകുകയും അവ അംഗീകരിക്കുകയും ചെയ്യുന്നു. അവർ അവരെ കൊന്നു; നിങ്ങളോ അവർക്കു കല്ലറകൾ പണിയുന്നു."},{"v":49,"t":"അതുകൊണ്ട്, ദൈവത്തിന്റെ ജ്ഞാനം ഇങ്ങനെ പറഞ്ഞിരിക്കുന്നു: ഞാൻ അവരുടെ അടുത്തേക്ക് പ്രവാചകന്മാരെയും അപ്പസ്തോലന്മാരെയും അയയ്ക്കും. അവരിൽ ചിലരെ അവർ കൊല്ലുകയും ചിലരെ പീഡിപ്പിക്കുകയും ചെയ്യും."},{"v":50,"t":"ലോകത്തിന്റെ സംസ്ഥാപനം മുതൽ ചൊരിയപ്പെട്ടിട്ടുള്ള സകല പ്രവാചകന്മാരുടെയും രക്തത്തിന് ഈ തലമുറ ഉത്തരംപറയേണ്ടിവരും;"},{"v":51,"t":"ആബേലിന്റെ രക്തം മുതൽ ബലിപീഠത്തിനും വിശുദ്ധസ്ഥലത്തിനും മധ്യേവച്ചു കൊല്ലപ്പെട്ട സഖറിയായുടെ രക്തം വരെ. അതേ, ഞാൻ പറയുന്നു: ഈ തലമുറ ഉത്തരം പറയേണ്ടിവരും."},{"v":52,"t":"നിയമജ്ഞരേ, നിങ്ങൾക്കു ദുരിതം! നിങ്ങൾ അറിവിന്റെ താക്കോൽ കരസ്ഥമാക്കിയിരിക്കുന്നു. നിങ്ങളോ അകത്തു പ്രവേശിച്ചില്ല; പ്രവേശിക്കാൻ വന്നവരെ തടസ്സപ്പെടുത്തുകയും ചെയ്തു."},{"v":53,"t":"അവൻ അവിടെനിന്നു പോകവേ, നിയമജ്ഞരും ഫരിസേയരും പല കാര്യങ്ങളെയുംപറ്റി സംസാരിക്കാൻ അതീവ ദുഷ്ടലാക്കോടെ അവനെ പ്രകോപിപ്പിക്കുകയും"},{"v":54,"t":"അവന്റെ വായിൽനിന്നു വല്ലതും വീണുകിട്ടുമോ എന്ന് തക്കംനോക്കുകയും ചെയ്തു."}],"12":[{"h":"ഭയരഹിതരായി സാക്ഷ്യംനല്കുക"},{"v":1,"t":"പരസ്പരം ചവിട്ടേല്ക്കുംവിധം ആയിരക്കണക്കിനാളുകൾ തിങ്ങിക്കൂടി. അപ്പോൾ അവൻ ശിഷ്യരോടു പറയാൻ തുടങ്ങി: ഫരിസേയരുടെ കാപട്യമാകുന്ന പുളിമാവിനെ സൂക്ഷിച്ചുകൊള്ളുവിൻ.","p":1},{"v":2,"t":"മറഞ്ഞിരിക്കുന്നതൊന്നും വെളിച്ചത്തുവരാതിരിക്കയില്ല; നിഗൂഢമായിരിക്കുന്നതൊന്നും അറിയപ്പെടാതിരിക്കുകയുമില്ല."},{"v":3,"t":"അതുകൊണ്ട്, നിങ്ങൾ ഇരുട്ടത്തു സംസാരിച്ചത് വെളിച്ചത്തു കേൾക്കപ്പെടും. വീട്ടിൽ സ്വകാര്യമുറികളിൽവച്ച് ചെവിയിൽ പറഞ്ഞത് പുരമുകളിൽനിന്നു പ്രഘോഷിക്കപ്പെടും."},{"v":4,"t":"എന്റെ സ്നേഹിതരായ നിങ്ങളോടു ഞാൻ പറയുന്നു, ശരീരത്തെ കൊല്ലുന്നതിൽ കവിഞ്ഞ് ഒന്നും ചെയ്യാൻ കഴിയാത്തവരെ നിങ്ങൾ ഭയപ്പെടേണ്ടാ.","p":1},{"v":5,"t":"എന്നാൽ, നിങ്ങൾ ആരെ ഭയപ്പെടണമെന്ന് ഞാൻ വ്യക്തമാക്കാം. കൊന്നശേഷം നിങ്ങളെ നരകത്തിലേക്കു തള്ളിക്കളയാൻ അധികാരമുള്ളവനെ ഭയപ്പെടുവിൻ. അതേ, ഞാൻ പറയുന്നു, അവനെ ഭയപ്പെടുവിൻ."},{"v":6,"t":"അഞ്ചു കുരുവികൾ രണ്ടു നാണയത്തുട്ടിനു വില്ക്കപ്പെടുന്നില്ലേ? എങ്കിലും അവയിൽ ഒന്നുപോലും ദൈവസന്നിധിയിൽ വിസ്മരിക്കപ്പെടുന്നില്ല."},{"v":7,"t":"നിങ്ങളുടെ തലമുടിയിഴപോലും എണ്ണപ്പെട്ടിരിക്കുന്നു. ഭയപ്പെടേണ്ടാ, നിങ്ങൾ അനേകം കുരുവികളെക്കാൾ വിലയുള്ളവരാണ്."},{"v":8,"t":"ഞാൻ നിങ്ങളോടു പറയുന്നു, മനുഷ്യരുടെ മുമ്പിൽ എന്നെ ഏറ്റുപറയുന്ന ആരെയും ദൈവദൂതന്മാരുടെ മുമ്പിൽ മനുഷ്യപുത്രനും ഏറ്റുപറയും.","p":1},{"v":9,"t":"മനുഷ്യരുടെ മുമ്പിൽ എന്നെ തള്ളിപ്പറയുന്നവൻ ദൈവത്തിന്റെ ദൂതന്മാരുടെ മുമ്പിലും തള്ളിപ്പറയപ്പെടും."},{"v":10,"t":"മനുഷ്യപുത്രനെതിരേ സംസാരിക്കുന്ന ആരോടും ക്ഷമിക്കപ്പെടും. എന്നാൽ, പരിശുദ്ധാത്മാവിനെതിരേ ദൂഷണം പറയുന്നവനോട് ക്ഷമിക്കപ്പെടുകയില്ല."},{"v":11,"t":"സിനഗോഗുകളുടെയും ഭരണാധിപന്മാരുടെയും അധികാരങ്ങളുടെയും മുമ്പിൽ അവർ നിങ്ങളെ കൊണ്ടുപോകുമ്പോൾ, എങ്ങനെ, എന്ത് ഉത്തരം കൊടുക്കുമെന്നും എന്തു പറയുമെന്നും ഉത്കണ്ഠാകുലരാകേണ്ടാ."},{"v":12,"t":"എന്തെന്നാൽ, നിങ്ങൾ പറയേണ്ടത് ആ മണിക്കൂറിൽ പരിശുദ്ധാത്മാവ് നിങ്ങളെ പഠിപ്പിക്കും."},{"h":"ഭോഷനായ ധനികൻ"},{"v":13,"t":"ജനക്കൂട്ടത്തിൽനിന്ന് ഒരുവൻ അവനോടു പറഞ്ഞു: ഗുരോ, പിതൃസ്വത്ത് ഞാനുമായി പങ്കുവയ്ക്കാൻ എന്റെ സഹോദരനോടു പറയണമേ.","p":1},{"v":14,"t":"യേശു അവനോടു ചോദിച്ചു: ഹേ, മനുഷ്യാ, എന്നെ നിങ്ങളുടെ ന്യായാധിപനോ ഭാഗംവയ്ക്കുന്നവനോ ആയി ആരു നിയമിച്ചു?"},{"v":15,"t":"അനന്തരം അവൻ അവരോടു പറഞ്ഞു: ജാഗരൂകരായിരിക്കുവിൻ. എല്ലാ അത്യാഗ്രഹങ്ങളിലുംനിന്ന് അകന്നിരിക്കുകയും ചെയ്യുവിൻ. ജീവിതം സമ്പത്തുകൊണ്ടല്ല ധന്യമാകുന്നത്."},{"v":16,"t":"ഒരു ഉപമയും അവൻ അവരോടു പറഞ്ഞു: ഒരു ധനികന്റെ കൃഷിസ്ഥലം സമൃദ്ധമായ വിളവുനല്കി."},{"v":17,"t":"അവൻ ഇങ്ങനെ ചിന്തിച്ചു: ഞാനെന്തു ചെയ്യും? എന്റെ ധാന്യം ശേഖരിക്കാൻ എനിക്കിടമില്ലല്ലോ."},{"v":18,"t":"അവൻ പറഞ്ഞു: ഞാൻ ഇങ്ങനെ ചെയ്യും. എന്റെ അറപ്പുരകൾ പൊളിച്ച്, കൂടുതൽ വലിയവ പണിയും; അവിടെ എന്റെ മുഴുവൻ ധാന്യവും വിഭവങ്ങളും ശേഖരിക്കും."},{"v":19,"t":"അനന്തരം, ഞാൻ എന്റെ ആത്മാവിനോടു പറയും: ആത്മാവേ, അനേകവർഷത്തേക്കു വേണ്ട വിഭവങ്ങൾ നിനക്കായി സംഭരിക്കപ്പെട്ടിരിക്കുന്നു. വിശ്രമിക്കുക, തിന്നുക, കുടിക്കുക, ആഹ്ലാദിക്കുക."},{"v":20,"t":"എന്നാൽ, ദൈവം അവനോടു പറഞ്ഞു: ഭോഷാ, ഈ രാത്രി നിന്റെ ആത്മാവിനെ നിന്നിൽനിന്ന് ആവശ്യപ്പെടും; അപ്പോൾ നീ ഒരുക്കിവച്ചിരിക്കുന്നവ ആരുടേതാകും?"},{"v":21,"t":"ഇതുപോലെയാണ് ദൈവത്തിലേക്കു സമ്പന്നനാകാതെ തനിക്കുവേണ്ടി നിധി കൂട്ടിവയ്ക്കുന്നവനും."},{"h":"ദൈവപരിപാലനത്തിൽ ആശ്രയം"},{"v":22,"t":"വീണ്ടും അവൻ തന്റെ ശിഷ്യരോട് അരുൾചെയ്തു: അതിനാൽ, ഞാൻ നിങ്ങളോടു പറയുന്നു, എന്തു ഭക്ഷിക്കും എന്നു ജീവനെപ്പറ്റിയോ എന്തു ധരിക്കും എന്നു ശരീരത്തെപ്പറ്റിയോ നിങ്ങൾ ഉത്കണ്ഠാകുലരാകേണ്ടാ.","p":1},{"v":23,"t":"എന്തെന്നാൽ, ജീവൻ ഭക്ഷണത്തിനും ശരീരം വസ്ത്രത്തിനും ഉപരിയാണ്."},{"v":24,"t":"കാക്കകളെ നോക്കുവിൻ; അവ വിതയ്ക്കുന്നില്ല, കൊയ്യുന്നില്ല; കലവറയോ കളപ്പുരയോ അവയ്ക്കില്ല. എങ്കിലും, ദൈവം അവയെ പോറ്റുന്നു. പക്ഷികളെക്കാൾ എത്രയോ വിലപ്പെട്ടവരാണു നിങ്ങൾ!"},{"v":25,"t":"ഉത്കണ്ഠാകുലരാകുന്നതുകൊണ്ട് ആയുസ്സ് ഒരു വിനാഴികകൂടി നീട്ടാൻ നിങ്ങളിൽ ആർക്കു സാധിക്കും?"},{"v":26,"t":"നിസ്സാരമായ ഇതുപോലും ചെയ്യാൻ നിങ്ങൾക്കു കഴിവില്ലെങ്കിൽ മറ്റുള്ളവയെപ്പറ്റി ഉത്കണ്ഠാകുലരാകുന്നതെന്തിന്?"},{"v":27,"t":"ലില്ലികളെ നോക്കുവിൻ. എങ്ങനെ അവ വളരുന്നു? അവ അധ്വാനിക്കുകയോ നൂല്ക്കുകയോ ചെയ്യുന്നില്ലല്ലോ. ഞാൻ നിങ്ങളോടു പറയുന്നു: സോളമൻപോലും അവന്റെ സർവമഹത്ത്വത്തിലും അവയിൽ ഒന്നിനെപ്പോലെ അലംകൃതനായിരുന്നില്ല."},{"v":28,"t":"ഇന്നുള്ളതും നാളെ തീയിൽ എറിയപ്പെടുന്നതുമായ വയലിലെ പുല്ലിനെ ദൈവം ഇങ്ങനെ അണിയിക്കുന്നെങ്കിൽ, അല്പവിശ്വാസികളേ, നിങ്ങളെ എത്രയധികം അണിയിക്കുകയില്ല!"},{"v":29,"t":"എന്തു തിന്നുമെന്നോ എന്തു കുടിക്കുമെന്നോ അന്വേഷിക്കേണ്ടാ; ആകുലചിത്തരാകുകയും വേണ്ടാ."},{"v":30,"t":"ലോകത്തിന്റെ ജനതകളാണ് ഇവയെല്ലാം അന്വേഷിക്കുന്നത്. നിങ്ങൾക്ക് ഇവ ആവശ്യമാണെന്ന് നിങ്ങളുടെ പിതാവിനറിയാം."},{"v":31,"t":"നിങ്ങൾ അവിടത്തെരാജ്യം അന്വേഷിക്കുവിൻ. ഇവയെല്ലാം നിങ്ങളോടു ചേർക്കപ്പെടും."},{"v":32,"t":"ചെറിയ അജഗണമേ, ഭയപ്പെടേണ്ടാ. എന്തെന്നാൽ, നിങ്ങൾക്കു രാജ്യം നല്കാൻ നിങ്ങളുടെ പിതാവ് പ്രസാദിച്ചിരിക്കുന്നു."},{"v":33,"t":"നിങ്ങൾക്കുള്ളവ വിറ്റ് ധർമം കൊടുക്കുവിൻ. കീറിപ്പോകാത്ത പണസഞ്ചികൾ ഉണ്ടാക്കുവിൻ; സ്വർഗത്തിൽ ഒടുങ്ങാത്ത നിക്ഷേപവും. അവിടെ കള്ളൻ അടുക്കുകയോ ചിതലെടുക്കുകയോ ഇല്ല."},{"v":34,"t":"കാരണം, നിങ്ങളുടെ നിക്ഷേപം എവിടെയാണോ അവിടെയായിരിക്കും നിങ്ങളുടെ ഹൃദയവും."},{"h":"സദാ ജാഗരൂകരായ ഭൃത്യന്മാർ"},{"v":35,"t":"നിങ്ങൾ അരമുറുക്കിയും വിളക്കുകൊളുത്തിയും ഇരിക്കുവിൻ.","p":1},{"v":36,"t":"തങ്ങളുടെ യജമാനൻ കല്യാണവിരുന്നിൽനിന്നു മടങ്ങിവന്ന് വാതില്ക്കൽ മുട്ടുന്ന ഉടനെ തുറന്നുകൊടുക്കാൻ കാത്തിരിക്കുന്നവരെപ്പോലെ ആയിരിക്കുവിൻ."},{"v":37,"t":"യജമാനൻ വരുമ്പോൾ ഉണർന്നിരിക്കുന്നവരായി കാണപ്പെടുന്ന ഭൃത്യർ അനുഗൃഹീതർ. സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു: അവൻ അരമുറുക്കി അവരെ ഭക്ഷണത്തിനിരുത്തുകയും അടുത്തുചെന്ന് അവരെ ശുശ്രൂഷിക്കുകയും ചെയ്യും."},{"v":38,"t":"അവൻ രാത്രിയുടെ രണ്ടാംയാമത്തിലോ മൂന്നാംയാമത്തിലോ വന്നാലും അവരെ ഒരുക്കമുള്ളവരായിക്കണ്ടാൽ അവർ അനുഗൃഹീതർ."},{"v":39,"t":"ഇത് അറിഞ്ഞുകൊള്ളുവിൻ: കള്ളൻ ഏതു യാമത്തിൽ വരുമെന്ന് ഗൃഹനായകൻ മനസ്സിലാക്കിയിരുന്നെങ്കിൽ തന്റെ വീടു കുത്തിത്തുറക്കാൻ അനുവദിക്കുകയില്ലായിരുന്നു."},{"v":40,"t":"നിങ്ങളും ഒരുങ്ങിയിരിക്കുവിൻ. എന്തെന്നാൽ, വിചാരിക്കാത്ത മണിക്കൂറിലാണ് മനുഷ്യപുത്രൻ വരുന്നത്."},{"v":41,"t":"പത്രോസ് ചോദിച്ചു: കർത്താവേ, നീ ഈ ഉപമ പറയുന്നത് ഞങ്ങൾക്കുവേണ്ടിയോ എല്ലാവർക്കും വേണ്ടിയോ?","p":1},{"v":42,"t":"അപ്പോൾ കർത്താവ് പറഞ്ഞു: വീട്ടുജോലിക്കാർക്കു നിശ്ചിതസമയം ഭക്ഷണം കൊടുക്കേണ്ടതിന് യജമാനൻ അവരുടെമേൽ നിയമിക്കുന്ന വിശ്വസ്തനും വിവേകിയുമായ കാര്യസ്ഥൻ ആരാണ്?"},{"v":43,"t":"യജമാനൻ വരുമ്പോൾ അപ്രകാരം പ്രവർത്തിക്കുന്നവനായി അവൻ കാണുന്ന ഭൃത്യൻ അനുഗൃഹീതൻ."},{"v":44,"t":"സത്യമായി ഞാൻ നിങ്ങളോടു പറയുന്നു, അവൻ തന്റെ സകലസ്വത്തിന്റെയും മേൽ അവനെ നിയമിക്കും."},{"v":45,"t":"എന്നാൽ, ആ ഭൃത്യൻ തന്റെ യജമാനൻ വരാൻ വൈകുന്നു എന്ന് ഉള്ളിൽ കരുതി, യജമാനന്റെ ദാസന്മാരെയും ദാസിമാരെയും അടിക്കാനും തിന്നുകുടിച്ച് ഉന്മത്തനാകാനും തുടങ്ങിയാൽ,"},{"v":46,"t":"നിനയ്ക്കാത്ത ദിവസത്തിലും അറിയാത്ത മണിക്കൂറിലും ആ ദാസന്റെ യജമാനൻ വരുകയും അവനെ നിഷ്ഠുരം ശിക്ഷിച്ച്, അവന്റെ പങ്ക് അവിശ്വസ്തരോടുകൂടെ ആക്കുകയും ചെയ്യും."},{"v":47,"t":"തന്റെ യജമാനന്റെ ഹിതം അറിഞ്ഞിട്ടും, തയ്യാറെടുക്കുകയോ അവന്റെ ഹിതമനുസരിച്ചു പ്രവർത്തിക്കുകയോ ചെയ്യാത്ത ഭൃത്യൻ ഏറെ പ്രഹരിക്കപ്പെടും."},{"v":48,"t":"എന്നാൽ, അറിയാതെയാണ് ഒരാൾ പ്രഹരാർഹമായതു ചെയ്തതെങ്കിൽ, അയാൾ കുറച്ചേ പ്രഹരിക്കപ്പെടുകയുള്ളൂ. ഏറെ നല്കപ്പെട്ട ഓരോരുത്തരിലുംനിന്ന് ഏറെ ആവശ്യപ്പെടും. ഏറെ ഏല്പിക്കപ്പെട്ടവനോട് വളരെയേറെ ചോദിക്കും."},{"h":"യേശു ഭിന്നതയ്ക്കു കാരണം"},{"v":49,"t":"ഭൂമിയിൽ തീയിടാനാണ് ഞാൻ വന്നത്. അത് ഇതിനകം കത്തിയെരിഞ്ഞെങ്കിൽ!","p":1},{"v":50,"t":"എനിക്ക് ഒരു സ്നാനമേല്ക്കാനുണ്ട്; അതു നിവൃത്തിയാകുവോളം ഞാൻ എത്ര ഞെരുങ്ങുന്നു!"},{"v":51,"t":"ഭൂമിയിൽ സമാധാനം നല്കാനാണ് ഞാൻ വന്നിരിക്കുന്നതെന്നു നിങ്ങൾ വിചാരിക്കുന്നുവോ? അല്ല; ഭിന്നത എന്നു ഞാൻ നിങ്ങളോടു പറയുന്നു."},{"v":52,"t":"എന്തെന്നാൽ, ഭിന്നിച്ചിരിക്കുന്ന അഞ്ചു പേർ ഇനിമേൽ ഒരു വീട്ടിലുണ്ടായിരിക്കും; മൂന്നുപേർ രണ്ടു പേർക്ക് എതിരായും രണ്ടുപേർ മൂന്നുപേർക്ക് എതിരായും."},{"v":53,"t":"പിതാവു പുത്രനും പുത്രൻ പിതാവിനും എതിരായും അമ്മ മകൾക്കും മകൾ അമ്മയ്ക്കും എതിരായും അമ്മായിയമ്മ മരുമകൾക്കും മരുമകൾ അമ്മായിയമ്മയ്ക്കും എതിരായും ഭിന്നിക്കും."},{"h":"കാലത്തിന്റെ അടയാളങ്ങൾ"},{"v":54,"t":"അവൻ ജനക്കൂട്ടത്തോടു പറഞ്ഞു: പടിഞ്ഞാറ് മേഘം ഉയരുന്നതുകണ്ടാൽ മഴവരുന്നു എന്ന് ഉടനേ നിങ്ങൾ പറയുന്നു; അങ്ങനെ സംഭവിക്കുകയും ചെയ്യുന്നു.","p":1},{"v":55,"t":"തെക്കൻകാറ്റ് അടിക്കുമ്പോൾ അത്യുഷ്ണമായിരിക്കും എന്നു നിങ്ങൾ പറയുന്നു; അതു സംഭവിക്കുന്നു."},{"v":56,"t":"കപടനാട്യക്കാരേ, ഭൂമിയുടെയും ആകാശത്തിന്റെയും ഭാവം വ്യാഖ്യാനിക്കാൻ നിങ്ങൾക്കറിയാം. എന്നാൽ, ഈ കാലത്തെ വ്യാഖ്യാനിക്കാൻ നിങ്ങൾക്ക് അറിയാത്തതെങ്ങനെ?"},{"h":"എതിരാളിയുമായി ഒത്തുതീർപ്പ്"},{"v":57,"t":"എന്തുകൊണ്ട് നിങ്ങൾ നീതിപൂർവം വിധിക്കുന്നില്ല?","p":1},{"v":58,"t":"നീ നിന്റെ എതിരാളിയോടുകൂടെ അധികാരിയുടെ അടുത്തേക്കു പോകുമ്പോൾ, വഴിയിൽവച്ചുതന്നെ അയാളുമായി ഒത്തുതീർപ്പിലെത്താൻ ശ്രമംനടത്തുക. അല്ലെങ്കിൽ അയാൾ നിന്നെ ന്യായാധിപന്റെ അടുക്കലേക്കു വലിച്ചിഴയ്ക്കുകയും ന്യായാധിപൻ നിന്നെ പാറാവുകാരനെ ഏല്പിക്കുകയും പാറാവുകാരൻ നിന്നെ തടവിലിടുകയും ചെയ്യും."},{"v":59,"t":"ഞാൻ നിന്നോടു പറയുന്നു: അവസാനത്തെ തുട്ടുവരെ കൊടുത്തു വീട്ടാതെ നീ അവിടെനിന്നു പുറത്തുവരുകയില്ല."}],"13":[{"h":"മാനസാന്തരപ്പെടുന്നില്ലെങ്കിൽ നാശം"},{"v":1,"t":"ഗലീലിയക്കാരുടെ ബലികളിൽ അവരുടെ രക്തംകൂടി പീലാത്തോസ് കലർത്തിയ വിവരം, ആ സമയത്ത് അവിടെയുണ്ടായിരുന്ന ചിലർ യേശുവിനെ അറിയിച്ചു.","p":1},{"v":2,"t":"അവൻ ചോദിച്ചു: ഇവയെല്ലാം സഹിച്ചതുകൊണ്ട് അവർ മറ്റെല്ലാ ഗലീലിയക്കാരെയുംകാൾ പാപികളായിരുന്നു എന്നു നിങ്ങൾ കരുതുന്നുവോ?"},{"v":3,"t":"അല്ല എന്നു ഞാൻ നിങ്ങളോടു പറയുന്നു. മാനസാന്തരപ്പെടുന്നില്ലെങ്കിൽ നിങ്ങളെല്ലാവരും അതുപോലെ നശിക്കും."},{"v":4,"t":"അഥവാ, സിലോഹായിലെ ഗോപുരം ഇടിഞ്ഞുവീണു കൊല്ലപ്പെട്ട ആ പതിനെട്ടു പേർ, എല്ലാ ജറുസലേം നിവാസികളെയുംകാൾ കുറ്റക്കാരായിരുന്നു എന്നു നിങ്ങൾ കരുതുന്നുവോ?"},{"v":5,"t":"അല്ല എന്നു ഞാൻ നിങ്ങളോടു പറയുന്നു. മാനസാന്തരപ്പെടുന്നില്ലെങ്കിൽ നിങ്ങളെല്ലാവരും അതുപോലെ നശിക്കും."},{"h":"ഫലം തരാത്ത അത്തിവൃക്ഷം"},{"v":6,"t":"അവൻ ഈ ഉപമ പറഞ്ഞു: മുന്തിരിത്തോട്ടത്തിൽ ഒരുവൻ നട്ടുപിടിപ്പിച്ച ഒരു അത്തിവൃക്ഷം ഉണ്ടായിരുന്നു. അതിൽ ഫലമുണ്ടോ എന്നുനോക്കാൻ അവൻ വന്നു; എന്നാൽ ഒന്നും കണ്ടില്ല.","p":1},{"v":7,"t":"അപ്പോൾ അവൻ മുന്തിരിത്തോട്ടക്കാരനോടു പറഞ്ഞു: മൂന്നുവർഷമായി ഞാൻ ഈ അത്തിവൃക്ഷത്തിൽനിന്ന് ഫലം അന്വേഷിച്ചുവരുന്നു; ഒന്നും കാണുന്നില്ല. അതു വെട്ടിക്കളയുക. എന്തിന് നിലം പാഴാക്കണം?"},{"v":8,"t":"മുന്തിരിത്തോട്ടക്കാരൻ അവനോടു പറഞ്ഞു: യജമാനനേ, ഈ വർഷംകൂടി അതു നില്ക്കട്ടെ. ഞാൻ അതിനു ചുറ്റും കിളച്ച് വളമിടാം."},{"v":9,"t":"മേലിൽ അതു ഫലം നല്കിയേക്കാം. ഇല്ലെങ്കിൽ നീ അതു വെട്ടിക്കളഞ്ഞുകൊള്ളുക."},{"h":"കൂനുള്ള സ്ത്രീയെ സുഖപ്പെടുത്തുന്നു"},{"v":10,"t":"സാബത്തിൽ അവൻ ഒരു സിനഗോഗിൽ പഠിപ്പിക്കുകയായിരുന്നു.","p":1},{"v":11,"t":"പതിനെട്ടുവർഷമായി രോഗത്തിന്റെ അരൂപി ബാധിച്ച് നിവർന്നുനില്ക്കാൻ സാധിക്കാത്തവിധം കൂനിപ്പോയ ഒരു സ്ത്രീ അവിടെയുണ്ടായിരുന്നു."},{"v":12,"t":"യേശു അവളെ കണ്ടപ്പോൾ അടുത്തുവിളിച്ചു പറഞ്ഞു: സ്ത്രീയേ, നിന്റെ രോഗത്തിൽനിന്ന് നീ മുക്തയാക്കപ്പെട്ടിരിക്കുന്നു."},{"v":13,"t":"അവൻ അവളുടെമേൽ കൈകൾവച്ചു. തത്ക്ഷണം അവൾ നിവർന്നുനില്ക്കുകയും ദൈവത്തെ മഹത്ത്വപ്പെടുത്തുകയും ചെയ്തു."},{"v":14,"t":"യേശു സാബത്തിൽ സുഖപ്പെടുത്തിയതിൽ അമർഷംപൂണ്ട് സിനഗോഗധികാരി ജനക്കൂട്ടത്തോടു പറഞ്ഞു: ജോലി ചെയ്യാവുന്ന ആറു ദിവസങ്ങൾ ഉണ്ട്. ആ ദിവസങ്ങളിൽ വന്ന് സുഖപ്പെട്ടുകൊള്ളുക; സാബത്തുദിവസം പാടില്ല."},{"v":15,"t":"അപ്പോൾ കർത്താവ് മറുപടി പറഞ്ഞു: കപടനാട്യക്കാരേ, നിങ്ങൾ ഓരോരുത്തരും സാബത്തിൽ തങ്ങളുടെ കാളയെയോ കഴുതയെയോ തൊഴുത്തിൽനിന്ന് അഴിച്ച് വെള്ളം കുടിപ്പിക്കാൻ കൊണ്ടുപോകുന്നില്ലേ?"},{"v":16,"t":"പതിനെട്ടുവർഷം സാത്താൻ ബന്ധിച്ചിട്ടിരുന്ന അബ്രാഹത്തിന്റെ മകളെ സാബത്തുദിവസം ഈ ബന്ധനത്തിൽനിന്ന് മോചിപ്പിക്കേണ്ടതില്ലെന്നോ?"},{"v":17,"t":"ഇതുകേട്ട് അവന്റെ പ്രതിയോഗികളെല്ലാം ലജ്ജിതരായി. എന്നാൽ, ജനക്കൂട്ടം മുഴുവൻ അവൻവഴിയായി നടന്നിരുന്ന മഹനീയ കൃത്യങ്ങളെക്കുറിച്ചു സന്തോഷിച്ചു."},{"h":"കടുകുമണിയും പുളിമാവും"},{"v":18,"t":"അവൻ പറഞ്ഞു: ദൈവരാജ്യം എന്തിനോടു സദൃശമാണ്? എന്തിനോടു ഞാൻ അതിനെ ഉപമിക്കും?","p":1},{"v":19,"t":"അത് ഒരുമനുഷ്യൻ തന്റെ തോട്ടത്തിൽ പാകിയ കടുകുമണിക്കു സദൃശമാണ്. അതു വളർന്ന് മരമായി. ആകാശപ്പറവകൾ അതിന്റെ ശാഖകളിൽ കൂടുകൂട്ടി."},{"v":20,"t":"അവൻ വീണ്ടും പറഞ്ഞു: ദൈവരാജ്യത്തെ എന്തിനോടു ഞാൻ ഉപമിക്കും?","p":1},{"v":21,"t":"ഒരു സ്ത്രീ, മൂന്നളവു മാവിൽ, അതു മുഴുവൻ പുളിക്കുവോളം എടുത്ത് ഒളിപ്പിച്ചുവച്ച പുളിമാവുപോലെയാണത്."},{"h":"ഇടുങ്ങിയ വാതിൽ"},{"v":22,"t":"അവൻ ഓരോ പട്ടണത്തിലും ഗ്രാമത്തിലും പോയി പഠിപ്പിച്ചുകൊണ്ട് ജറുസലേമിലേക്കു യാത്രചെയ്യുകയായിരുന്നു.","p":1},{"v":23,"t":"ഒരുവൻ അവനോടുചോദിച്ചു: കർത്താവേ, രക്ഷപ്പെടുന്നവർ ചുരുക്കമാണോ? അവൻ അവരോടു പറഞ്ഞു:"},{"v":24,"t":"ഇടുങ്ങിയ വാതിലിലൂടെ പ്രവേശിക്കാൻ കിണഞ്ഞുപരിശ്രമിക്കുവിൻ. ഞാൻ നിങ്ങളോടു പറയുന്നു, അനേകർ പ്രവേശിക്കാൻ ശ്രമിക്കും. എന്നാൽ അവർക്കു സാധിക്കുകയില്ല."},{"v":25,"t":"വീട്ടുടമസ്ഥൻ എഴുന്നേറ്റ് വാതിൽ അടച്ചുകഴിഞ്ഞാൽപ്പിന്നെ, നിങ്ങൾ പുറത്തുനിന്ന്, കർത്താവേ, ഞങ്ങൾക്കു തുറന്നുതരണമേ എന്നു പറഞ്ഞു വാതില്ക്കൽ മുട്ടാൻ തുടങ്ങും. അപ്പോൾ അവൻ നിങ്ങളോടു പറയും: നിങ്ങൾ എവിടെ നിന്നാണെന്ന് ഞാൻ അറിയുന്നില്ല."},{"v":26,"t":"അപ്പോൾ നിങ്ങൾ പറയാൻ തുടങ്ങും: നിന്റെ സാന്നിധ്യത്തിൽ ഞങ്ങൾ ഭക്ഷിക്കുകയും പാനം ചെയ്യുകയും നീ ഞങ്ങളുടെ തെരുവുകളിൽ പഠിപ്പിക്കുകയും ചെയ്തിട്ടുണ്ട്."},{"v":27,"t":"എന്നാൽ അവൻ അവരോടു പറയും: നിങ്ങൾ എവിടെനിന്നാണെന്ന് ഞാൻ അറിയുന്നില്ല. അനീതി പ്രവർത്തിക്കുന്നവരേ, നിങ്ങൾ എല്ലാവരും എന്നിൽനിന്ന് അകന്നുപോകുവിൻ."},{"v":28,"t":"അബ്രാഹത്തെയും ഇസഹാക്കിനെയും യാക്കോബിനെയും സകല പ്രവാചകന്മാരെയും ദൈവരാജ്യത്തിലും, നിങ്ങളെ ബഹിഷ്കൃതരായി പുറത്തും കാണുമ്പോൾ അവിടെ കരച്ചിലും പല്ലുകടിയുമായിരിക്കും."},{"v":29,"t":"കിഴക്കുനിന്നും പടിഞ്ഞാറുനിന്നും വടക്കുനിന്നും തെക്കുനിന്നും ജനങ്ങൾ വന്ന് ദൈവരാജ്യത്തിൽ വിരുന്നിനിരിക്കും."},{"v":30,"t":"ഇതാ, പിമ്പന്മാർ മുമ്പന്മാരും മുമ്പന്മാർ പിമ്പന്മാരുമാകും."},{"h":"ജറുസലേമിനെക്കുറിച്ചുള്ള വിലാപം"},{"v":31,"t":"ആ മണിക്കൂറിൽത്തന്നെ ചില ഫരിസേയർ വന്ന് അവനോടു പറഞ്ഞു: ഇവിടം വിട്ടുപോകുക; കാരണം, ഹേറോദേസ് നിന്നെ കൊല്ലാൻ ഉദ്ദേശിക്കുന്നു.","p":1},{"v":32,"t":"അവൻ അവരോടു പറഞ്ഞു: നിങ്ങൾ പോയി ആ കുറുക്കനോടു പറയുവിൻ, ഞാൻ ഇന്നും നാളെയും പിശാചുക്കളെ പുറത്താക്കുകയും രോഗശാന്തി നല്കുകയും മൂന്നാംദിവസം പൂർത്തിയാക്കുകയും ചെയ്യും."},{"v":33,"t":"ഏതായാലും, ഇന്നും നാളെയും മറ്റെന്നാളും ഞാൻ എന്റെ യാത്ര ചെയ്യേണ്ടത് ആവശ്യമാണ്. കാരണം, ജറുസലേമിനു പുറത്തുവച്ച് ഒരു പ്രവാചകൻ വധിക്കപ്പെടുക സാധ്യമല്ല."},{"v":34,"t":"ജറുസലേം, ജറുസലേം, പ്രവാചകന്മാരെ കൊല്ലുകയും നിന്റെ അടുക്കലേക്ക് അയയ്ക്കപ്പെടുന്നവരെ കല്ലെറിയുകയും ചെയ്യുന്നവളേ, പിടക്കോഴി കുഞ്ഞുങ്ങളെ ചിറകിൻകീഴിൽ എന്നപോലെ നിന്റെ സന്താനങ്ങളെ ചേർത്തുനിറുത്താൻ ഞാൻ എത്രയോ പ്രാവശ്യം ആഗ്രഹിച്ചു! എന്നാൽ നിനക്കോ മനസ്സുണ്ടായില്ല."},{"v":35,"t":"ഇതാ, നിങ്ങളുടെ ഭവനം നിങ്ങൾക്കു വിട്ടിരിക്കുന്നു. ഞാൻ നിങ്ങളോടു പറയുന്നു, കർത്താവിന്റെ നാമത്തിൽ വരുന്നവൻ വാഴ്ത്തപ്പെട്ടവൻ എന്നു നിങ്ങൾ പറയുന്നതുവരെ നിങ്ങൾ എന്നെ കാണുകയേയില്ല."}],"14":[{"h":"മഹോദരരോഗിയെ സുഖപ്പെടുത്തുന്നു"},{"v":1,"t":"ഒരു സാബത്തിൽ അവൻ ഫരിസേയപ്രമാണികളിൽ ഒരുവന്റെ വീട്ടിൽ ഭക്ഷണംകഴിക്കാൻ പോയി. അവർ അവനെ നിരീക്ഷിച്ചുകൊണ്ടിരുന്നു.","p":1},{"v":2,"t":"അവിടെ അവന്റെ മുമ്പിൽ ഒരു മഹോദരരോഗി ഉണ്ടായിരുന്നു."},{"v":3,"t":"യേശു നിയമജ്ഞരോടും ഫരിസേയരോടുമായി ചോദിച്ചു: സാബത്തിൽ രോഗശാന്തി നല്കുന്നത് അനുവദനീയമോ അല്ലയോ?"},{"v":4,"t":"അവർ നിശ്ശബ്ദരായിരുന്നു. യേശു അവനെ തൊട്ട് സുഖപ്പെടുത്തി അയച്ചു."},{"v":5,"t":"അനന്തരം, അവൻ അവരോടു ചോദിച്ചു: സാബത്തിൽ തന്റെ പുത്രനോ കാളയോ കിണറ്റിൽവീണാൽ തത്ക്ഷണം പിടിച്ചുകയറ്റാത്തവനായി നിങ്ങളിൽ ആരുണ്ട്?"},{"v":6,"t":"ഇവയോടൊന്നും മറുത്തുപറയാൻ അവർക്കു കഴിഞ്ഞില്ല."},{"h":"അതിഥിക്കും ആതിഥേയനും ഉപദേശം"},{"v":7,"t":"ക്ഷണിക്കപ്പെട്ടവർ പ്രമുഖസ്ഥാനങ്ങൾ തിരഞ്ഞെടുക്കുന്നതു കണ്ടപ്പോൾ അവൻ അവരോട് ഒരു ഉപമ പറഞ്ഞു:","p":1},{"v":8,"t":"ആരെങ്കിലും നിന്നെ ഒരു കല്യാണവിരുന്നിനു ക്ഷണിച്ചാൽ, പ്രമുഖസ്ഥാനത്തു കയറി ഇരിക്കരുത്. ഒരുപക്ഷേ, നിന്നെക്കാൾ ബഹുമാന്യനായ ഒരുവനെ അയാൾ ക്ഷണിച്ചിട്ടുണ്ടാകും."},{"v":9,"t":"നിങ്ങളെ രണ്ടുപേരെയും ക്ഷണിച്ചയാൾ വന്ന്, ഇവനു സ്ഥലം കൊടുക്കുക എന്നു നിന്നോടു പറയും. അപ്പോൾ നീ ലജ്ജയോടെ, അവസാനത്തെ സ്ഥാനത്തുപോയി ഇരിക്കേണ്ടിവരും."},{"v":10,"t":"എന്നാൽ, നിന്നെ വിരുന്നിനു ക്ഷണിച്ചാൽ അവസാനത്തെ സ്ഥാനത്തുപോയി ഇരിക്കുക. നിന്നെ ക്ഷണിച്ചയാൾ വന്ന് നിന്നോട്, സ്നേഹിതാ, മുന്നിലേക്കു കയറിയിരിക്കുക എന്നുപറയും. അപ്പോൾ നിന്നോടുകൂടെ ഭക്ഷണത്തിനിരിക്കുന്ന സകലരുടെയും മുമ്പാകെ നിനക്കു മഹത്ത്വമുണ്ടാകും."},{"v":11,"t":"എന്തെന്നാൽ, തന്നെത്തന്നെ ഉയർത്തുന്നവൻ താഴ്ത്തപ്പെടും; തന്നെത്തന്നെ താഴ്ത്തുന്നവൻ ഉയർത്തപ്പെടും."},{"v":12,"t":"തന്നെ ക്ഷണിച്ചവനോടും അവൻ പറഞ്ഞു: നീ ഒരു സദ്യയോ അത്താഴവിരുന്നോ കൊടുക്കുമ്പോൾ നിന്റെ സ്നേഹിതരെയോ സഹോദരരെയോ ബന്ധുക്കളെയോ ധനികരായ അയല്ക്കാരെയോ വിളിക്കരുത്. ഒരുപക്ഷേ, അവർ നിന്നെ പകരം ക്ഷണിക്കുകയും അതു നിനക്കു പ്രതിഫലമാകുകയും ചെയ്യും."},{"v":13,"t":"എന്നാൽ, നീ സദ്യ നടത്തുമ്പോൾ ദരിദ്രർ, വികലാംഗർ, മുടന്തർ, കുരുടർ എന്നിവരെ ക്ഷണിക്കുക."},{"v":14,"t":"അപ്പോൾ നീ അനുഗൃഹീതനായിരിക്കും; കാരണം, നിനക്കു തിരിച്ചുതരാൻ അവർക്ക് ഒന്നുമില്ല. നീതിമാന്മാരുടെ ഉത്ഥാനത്തിൽ നിനക്കു പ്രതിഫലമുണ്ടാകും."},{"h":"വിരുന്നിന്റെ ഉപമ"},{"v":15,"t":"അവനോടുകൂടെ ഭക്ഷിച്ചുകൊണ്ടിരുന്നവരിൽ ഒരുവൻ ഇതു കേട്ടിട്ട് അവനോടു പറഞ്ഞു: ദൈവരാജ്യത്തിൽ അപ്പം ഭക്ഷിക്കുന്നവൻ അനുഗൃഹീതൻ.","p":1},{"v":16,"t":"അപ്പോൾ യേശു അവനോടു പറഞ്ഞു: ഒരിക്കൽ ഒരുവൻ ഒരു വലിയ സദ്യ ഒരുക്കി. വളരെപ്പേരെ ക്ഷണിക്കുകയും ചെയ്തു."},{"v":17,"t":"സദ്യയ്ക്കു നേരമായപ്പോൾ അവൻ ദാസനെ അയച്ച് ക്ഷണിക്കപ്പെട്ടവരെ അറിയിച്ചു: വരുവിൻ, എല്ലാം തയ്യാറായിരിക്കുന്നു."},{"v":18,"t":"എന്നാൽ അവരെല്ലാവരും ഒന്നുപോലെ ഒഴികഴിവു പറയാൻ തുടങ്ങി. ഒന്നാമൻ പറഞ്ഞു: ഞാൻ ഒരു വയൽ വാങ്ങി; അതുപോയി കാണേണ്ടിയിരിക്കുന്നു. എനിക്ക് ഒഴിവു തരണം എന്നു ഞാൻ അപേക്ഷിക്കുന്നു."},{"v":19,"t":"മറ്റൊരുവൻ പറഞ്ഞു: ഞാൻ അഞ്ച് ഏർ കാളകളെ വാങ്ങി; അവയെ പരീക്ഷിച്ചുനോക്കാൻ പോകുന്നു; എനിക്ക് ഒഴിവുതരണമെന്ന് അപേക്ഷിക്കുന്നു."},{"v":20,"t":"വേറൊരുവൻ പറഞ്ഞു: ഞാൻ ഒരു സ്ത്രീയെ വിവാഹം കഴിച്ചിരിക്കുന്നു. അതിനാൽ എനിക്കു വരാൻ നിവൃത്തിയില്ല."},{"v":21,"t":"ആ ദാസൻ തിരിച്ചുവന്ന് യജമാനനെ വിവരമെല്ലാം അറിയിച്ചു. അപ്പോൾ ഗൃഹനാഥൻ ക്രുദ്ധനായി ദാസനോടു പറഞ്ഞു: നീ വേഗം പട്ടണത്തിന്റെ തെരുവുകളിലും ഊടുവഴികളിലും പോകുക; ദരിദ്രരെയും വികലാംഗരെയും കുരുടരെയും മുടന്തരെയും ഇവിടേക്ക് ആനയിക്കുക."},{"v":22,"t":"അനന്തരം, ആ ദാസൻ പറഞ്ഞു: യജമാനനേ, നീ കല്പിച്ചപോലെ ഞാൻ ചെയ്തു. ഇനിയും സ്ഥലമുണ്ട്."},{"v":23,"t":"യജമാനൻ ദാസനോടു പറഞ്ഞു: നീ വഴികളിലേക്കും ഇടവഴികളിലേക്കും പോകുക. എന്റെ വീടു നിറയേണ്ടതിന് അകത്തേക്കു വരാൻ അവരെ നിർബന്ധിക്കുക."},{"v":24,"t":"എന്തെന്നാൽ, ക്ഷണിക്കപ്പെട്ടവരാരും എന്റെ സദ്യ ആസ്വദിക്കയില്ലെന്ന് ഞാൻ നിങ്ങളോടു പറയുന്നു."},{"h":"ശിഷ്യത്വത്തിന്റെ വില"},{"v":25,"t":"വലിയ ജനക്കൂട്ടം അവനോടുകൂടെ പോകുകയായിരുന്നു. അവൻ തിരിഞ്ഞ് അവരോടു പറഞ്ഞു:","p":1},{"v":26,"t":"സ്വന്തം പിതാവിനെയും മാതാവിനെയും ഭാര്യയെയും മക്കളെയും സഹോദരന്മാരെയും സഹോദരിമാരെയും എന്നല്ല, സ്വജീവനെത്തന്നെയും ദ്വേഷിക്കാതെ എന്റെ അടുത്തുവരുന്ന ആർക്കും എന്റെ ശിഷ്യരായിരിക്കാൻ സാധിക്കുകയില്ല."},{"v":27,"t":"സ്വന്തം കുരിശുവഹിക്കാതെ എന്റെ പിന്നാലെ വരുന്നവന് എന്റെ ശിഷ്യനായിരിക്കാൻ കഴിയുകയില്ല."},{"v":28,"t":"ഗോപുരം പണിയാൻ ആഗ്രഹിക്കുമ്പോൾ, അതിന്റെ പൂർത്തീകരണത്തിനുള്ള വക തനിക്കുണ്ടോ എന്ന്, ഇരുന്ന് അതിന്റെ ചെലവ് ആദ്യമേ കണക്കുകൂട്ടിനോക്കാത്തവൻ നിങ്ങളിൽ ആരുണ്ട്?"},{"v":29,"t":"അല്ലെങ്കിൽ, അടിത്തറ ഇട്ടുകഴിഞ്ഞ് പണി മുഴുവനാക്കാൻ കഴിയാതെ വരുമ്പോൾ, കാണുന്നവരെല്ലാം അവനെ ആക്ഷേപിക്കാൻ തുടങ്ങും."},{"v":30,"t":"അവർ പറയും: ഈ മനുഷ്യൻ പണി തുടങ്ങി, പക്ഷേ, മുഴുവനാക്കാൻ കഴിഞ്ഞില്ല."},{"v":31,"t":"അല്ലെങ്കിൽ, രാജാവിനോടു യുദ്ധംചെയ്യാൻ പോകുമ്പോൾ, ഇരുപതിനായിരവുമായി വരുന്നവനെ പതിനായിരത്തെക്കൊണ്ട് നേരിടാനാകുമോ എന്ന് ആദ്യമേ ഇരുന്ന് ആലോചിക്കാത്തത് ഏതു രാജാവാണ്?"},{"v":32,"t":"അതു സാധ്യമല്ലെങ്കിൽ, അവൻ ദൂരത്തായിരിക്കുമ്പോൾത്തന്നെ ദൂതന്മാരെ അയച്ച്, സമാധാനത്തിന് അപേക്ഷിക്കും."},{"v":33,"t":"ഇതുപോലെ, സ്വന്തമായുള്ളതെല്ലാം ഉപേക്ഷിക്കാതെ നിങ്ങളിലാർക്കും എന്റെ ശിഷ്യനാകുക സാധ്യമല്ല."},{"v":34,"t":"ഉപ്പ് നല്ലതു തന്നെ; പക്ഷേ, ഉറകെട്ടുപോയാൽ എങ്ങനെ ഉറകൂട്ടും?"},{"v":35,"t":"അത് നിലത്തിനോ വളത്തിനോ ഉപകരിക്കുകയില്ല. മനുഷ്യൻ അത് പുറത്തെറിഞ്ഞുകളയുന്നു. കേൾക്കാൻ ചെവിയുള്ളവൻ കേൾക്കട്ടെ."}],"15":[{"h":"കാണാതായ ആടിന്റെ ഉപമ"},{"v":1,"t":"ചുങ്കക്കാരും പാപികളുമെല്ലാം അവനെ കേൾക്കാൻ അടുത്തുവന്നുകൊണ്ടിരുന്നു.","p":1},{"v":2,"t":"ഫരിസേയരും നിയമജ്ഞരും പിറുപിറുത്തു: ഇവൻ പാപികളെ സ്വീകരിക്കുകയും അവരോടൊത്തു ഭക്ഷിക്കുകയും ചെയ്യുന്നു."},{"v":3,"t":"അവൻ അവരോട് ഈ ഉപമ പറഞ്ഞു:"},{"v":4,"t":"നൂറ് ആടുകൾ ഉണ്ടായിരിക്കേ, അവയിൽ ഒന്നു നഷ്ടപ്പെട്ടാൽ നിങ്ങളിലാരാണ് തൊണ്ണൂറ്റൊൻപതിനെയും മരുഭൂമിയിൽ വിട്ടിട്ട്, നഷ്ടപ്പെട്ടതിനെ കണ്ടുകിട്ടുവോളം തേടിപ്പോകാത്തത്?"},{"v":5,"t":"കണ്ടുകിട്ടുമ്പോൾ സന്തോഷിച്ച് അതിനെ തോളിലേറ്റുന്നു."},{"v":6,"t":"വീട്ടിലെത്തുമ്പോൾ അവൻ തന്റെ കൂട്ടുകാരെയും അയൽവാസികളെയും വിളിച്ചുകൂട്ടി അവരോടു പറയും: നിങ്ങൾ എന്നോടുകൂടെ സന്തോഷിക്കുവിൻ. നഷ്ടപ്പെട്ട എന്റെ ആടിനെ ഞാൻ കണ്ടെത്തിയിരിക്കുന്നു."},{"v":7,"t":"അതുപോലെ, മാനസാന്തരം ആവശ്യമില്ലാത്ത തൊണ്ണൂറ്റൊൻപതു നീതിമാന്മാരെയും കുറിച്ച് എന്നതിനെക്കാൾ, മാനസാന്തരപ്പെടുന്ന ഒരു പാപിയെക്കുറിച്ച് സ്വർഗത്തിൽ കൂടുതൽ സന്തോഷമുണ്ടാകും എന്ന് ഞാൻ നിങ്ങളോടു പറയുന്നു."},{"h":"കാണാതായ നാണയത്തിന്റെ ഉപമ"},{"v":8,"t":"ഏതു സ്ത്രീയാണ്, പത്തുനാണയം ഉണ്ടായിരിക്കേ, അതിൽ ഒന്നു നഷ്ടപ്പെട്ടാൽ വിളക്കുകൊളുത്തി, വീട് അടിച്ചുവാരി, അതു കണ്ടുകിട്ടുവോളം അവധാനപൂർവം അന്വേഷിക്കാത്തത്?","p":1},{"v":9,"t":"കണ്ടുകിട്ടുമ്പോൾ അവൾ കൂട്ടുകാരെയും അയൽവാസികളെയും വിളിച്ചുകൂട്ടിപറയും: എന്നോടുകൂടെ സന്തോഷിക്കുവിൻ. നഷ്ടപ്പെട്ട എന്റെ നാണയം ഞാൻ കണ്ടെത്തിയിരിക്കുന്നു."},{"v":10,"t":"അതുപോലെതന്നെ, മാനസാന്തരപ്പെടുന്ന ഒരു പാപിയെക്കുറിച്ച് ദൈവദൂതന്മാരുടെ മുമ്പിൽ സന്തോഷമുണ്ടാകുമെന്ന് ഞാൻ നിങ്ങളോടു പറയുന്നു."},{"h":"ധൂർത്തപുത്രന്റെ ഉപമ"},{"v":11,"t":"അവൻ പറഞ്ഞു: ഒരു മനുഷ്യന് രണ്ടു പുത്രന്മാർ ഉണ്ടായിരുന്നു.","p":1},{"v":12,"t":"ഇളയവൻ പിതാവിനോടു പറഞ്ഞു: പിതാവേ, സ്വത്തിൽ എന്റെ ഓഹരി എനിക്കു തരുക. അവൻ സ്വത്ത് അവർക്കായി ഭാഗിച്ചു."},{"v":13,"t":"ഏറെത്താമസിയാതെ, ഇളയമകൻ എല്ലാംശേഖരിച്ചുകൊണ്ട് ദൂരദേശത്തേക്കു പോയി, അവിടെ ധൂർത്തനായി ജീവിച്ച് തനിക്കുള്ളത് ദുർവ്യയം ചെയ്തു."},{"v":14,"t":"അവൻ എല്ലാം ചെലവഴിച്ചുകഴിഞ്ഞപ്പോൾ ആ ദേശമാകെ ഒരു കഠിനക്ഷാമമുണ്ടാകുകയും അവൻ ഞെരുക്കത്തിലാകുകയുംചെയ്തു."},{"v":15,"t":"അവൻ, ആ ദേശത്തെ ഒരു പൗരന്റെ അടുത്ത് ആശ്രയം തേടി. അയാൾ അവനെ പന്നികളെ തീറ്റാൻ വയലിലേക്കയച്ചു."},{"v":16,"t":"പന്നി തിന്നിരുന്ന തവിടുകൊണ്ടു വിശപ്പുമാറ്റാൻ അവൻ ആശിച്ചു. പക്ഷേ, ആരും അവനു കൊടുത്തില്ല."},{"v":17,"t":"അപ്പോൾ തന്നിലേക്കു തിരിഞ്ഞ്, അവൻ പറഞ്ഞു: എന്റെ പിതാവിന്റെ എത്രയോ കൂലിക്കാർക്ക് സുഭിക്ഷമായി ഭക്ഷണമുണ്ട്. ഞാനോ, ഇവിടെ വിശപ്പുകൊണ്ട് നശിക്കുന്നു."},{"v":18,"t":"ഞാൻ എഴുന്നേറ്റ് എന്റെ പിതാവിന്റെ അടുത്തേക്കു പോകും. ഞാൻ അവനോടു പറയും: പിതാവേ, സ്വർഗത്തിനെതിരായും നിന്റെ മുമ്പിലും ഞാൻ പാപം ചെയ്തു."},{"v":19,"t":"നിന്റെ പുത്രൻ എന്നു വിളിക്കപ്പെടാൻ ഞാൻ ഇനി യോഗ്യനല്ല. എന്നെ നിന്റെ കൂലിക്കാരിൽ ഒരുവനാക്കണമേ."},{"v":20,"t":"അവൻ എഴുന്നേറ്റ്, പിതാവിന്റെ അടുത്തേക്കു ചെന്നു. ദൂരെവച്ചുതന്നെ പിതാവ് അവനെ കണ്ടു. മനസ്സലിഞ്ഞ് ഓടിച്ചെന്ന് അവനെ കെട്ടിപ്പിടിച്ച് ചുംബിച്ചു."},{"v":21,"t":"മകൻ പറഞ്ഞു: പിതാവേ, സ്വർഗത്തിനെതിരായും നിന്റെ മുമ്പിലും ഞാൻ പാപംചെയ്തു. നിന്റെ പുത്രൻ എന്നു വിളിക്കപ്പെടാൻ ഞാൻ ഇനി യോഗ്യനല്ല."},{"v":22,"t":"പിതാവാകട്ടെ, തന്റെ ദാസരോടു പറഞ്ഞു: ഉടനെ മേല്ത്തരം മേലങ്കി കൊണ്ടുവന്ന് ഇവനെ ധരിപ്പിക്കുവിൻ. ഇവന്റെ കൈയിൽ മോതിരവും പാദങ്ങളിൽ ചെരിപ്പും അണിയിക്കുവിൻ."},{"v":23,"t":"കൊഴുപ്പിച്ച കാളക്കുട്ടിയെ കൊണ്ടുവന്ന് കൊല്ലുവിൻ. നമുക്കു ഭക്ഷിച്ച് ആഹ്ലാദിക്കാം."},{"v":24,"t":"എന്തെന്നാൽ, എന്റെ ഈ മകൻ മൃതനായിരുന്നു; വീണ്ടും ജീവിക്കുന്നു. അവൻ നഷ്ടപ്പെട്ടവനായിരുന്നു; അവനെ കണ്ടുകിട്ടിയിരിക്കുന്നു. അവർ ആഹ്ലാദിക്കാൻ തുടങ്ങി."}]}}]};
